GENERATOR_JOBS: dict[str, dict[str, Any]] = {}


def _ai_generator_now_iso() -> str:
    return _now_utc().isoformat()


def _ai_generator_result_dict(result: Any) -> dict[str, Any]:
    if isinstance(result, dict):
        return dict(result)
    raw = getattr(result, "__dict__", None)
    if isinstance(raw, dict):
        return dict(raw)
    return {}


def _ai_generator_progress_value(current: Any, total: Any, progress: Any = None) -> int:
    if progress is not None:
        try:
            return max(0, min(100, int(round(float(progress)))))
        except Exception:
            pass
    try:
        current_i = max(0, int(current or 0))
        total_i = max(1, int(total or 0))
        return max(0, min(99, int(round((current_i * 100) / total_i))))
    except Exception:
        return 0


def _ensure_ai_generator_jobs_schema() -> None:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS web_ai_generator_jobs (
                job_id TEXT PRIMARY KEY,
                role TEXT NOT NULL DEFAULT '',
                user_id BIGINT NOT NULL DEFAULT 0,
                kind TEXT NOT NULL,
                subject TEXT NOT NULL,
                level TEXT,
                requested_count INTEGER NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'queued',
                phase TEXT NOT NULL DEFAULT 'queued',
                progress INTEGER NOT NULL DEFAULT 0,
                current_count INTEGER NOT NULL DEFAULT 0,
                total_count INTEGER NOT NULL DEFAULT 0,
                error TEXT,
                result_json TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                completed_at TIMESTAMP
            )
            """
        )
        cur.execute("CREATE INDEX IF NOT EXISTS idx_ai_generator_jobs_user ON web_ai_generator_jobs(user_id, created_at)")
        cur.execute("CREATE INDEX IF NOT EXISTS idx_ai_generator_jobs_status ON web_ai_generator_jobs(status, updated_at)")
        conn.commit()
    finally:
        conn.close()


def _save_ai_generator_job(job: dict[str, Any], *, event: str = "update") -> dict[str, Any]:
    _ensure_ai_generator_jobs_schema()
    data = dict(job or {})
    job_id = str(data.get("job_id") or "").strip()
    if not job_id:
        raise ValueError("AI generator job_id is required")
    count = max(0, int(data.get("count") or data.get("requested_count") or data.get("total") or 0))
    total = max(0, int(data.get("total") or count or 0))
    current = max(0, int(data.get("current") or data.get("current_count") or 0))
    status = str(data.get("status") or "queued").strip().lower() or "queued"
    phase = str(data.get("phase") or status).strip().lower() or status
    progress = _ai_generator_progress_value(current, total or count, data.get("progress"))
    if status in {"completed", "failed"}:
        progress = 100
    result = _ai_generator_result_dict(data.get("result"))
    completed_at = data.get("completed_at") if status in {"completed", "failed"} else None
    created_at = str(data.get("created_at") or _ai_generator_now_iso())
    updated_at = _ai_generator_now_iso()
    saved = {
        **data,
        "job_id": job_id,
        "role": str(data.get("role") or "").strip().lower(),
        "created_by": int(data.get("created_by") or data.get("user_id") or 0),
        "kind": str(data.get("kind") or "vocabulary").strip(),
        "subject": _normalize_subject_label(str(data.get("subject") or "English")) or "English",
        "level": str(data.get("level") or "").strip().upper(),
        "count": count,
        "status": status,
        "phase": phase,
        "progress": progress,
        "current": current,
        "total": total or count,
        "result": result,
        "error": str(data.get("error") or "").strip() or None,
        "created_at": created_at,
        "updated_at": updated_at,
        "completed_at": completed_at,
    }
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_ai_generator_jobs (
                job_id, role, user_id, kind, subject, level, requested_count,
                status, phase, progress, current_count, total_count, error, result_json,
                created_at, updated_at, completed_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(job_id) DO UPDATE SET
                role=excluded.role,
                user_id=excluded.user_id,
                kind=excluded.kind,
                subject=excluded.subject,
                level=excluded.level,
                requested_count=excluded.requested_count,
                status=excluded.status,
                phase=excluded.phase,
                progress=excluded.progress,
                current_count=excluded.current_count,
                total_count=excluded.total_count,
                error=excluded.error,
                result_json=excluded.result_json,
                updated_at=CURRENT_TIMESTAMP,
                completed_at=excluded.completed_at
            """,
            (
                job_id,
                saved["role"],
                saved["created_by"],
                saved["kind"],
                saved["subject"],
                saved["level"],
                saved["count"],
                saved["status"],
                saved["phase"],
                saved["progress"],
                saved["current"],
                saved["total"],
                saved["error"],
                json.dumps(saved["result"] or {}, ensure_ascii=False),
                saved["created_at"],
                saved["updated_at"],
                saved["completed_at"],
            ),
        )
        conn.commit()
    finally:
        conn.close()
    GENERATOR_JOBS[job_id] = dict(saved)
    logger.info(
        "ai_generator.job.%s job_id=%s role=%s user_id=%s kind=%s subject=%s level=%s status=%s phase=%s progress=%s current=%s total=%s error=%s",
        event,
        job_id,
        saved["role"],
        saved["created_by"],
        saved["kind"],
        saved["subject"],
        saved["level"],
        saved["status"],
        saved["phase"],
        saved["progress"],
        saved["current"],
        saved["total"],
        saved["error"] or "",
    )
    return saved


def _get_saved_ai_generator_job(job_id: str) -> dict[str, Any] | None:
    raw = str(job_id or "").strip()
    if not raw:
        return None
    _ensure_ai_generator_jobs_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM web_ai_generator_jobs WHERE job_id=? LIMIT 1", (raw,))
        row = cur.fetchone()
        if not row:
            # Fallback to local memory if not in DB yet
            job = GENERATOR_JOBS.get(raw)
            if job:
                return dict(job)
            return None
        data = dict(row)
        result = _safe_json_object(data.get("result_json"))
        db_job = {
            "job_id": str(data.get("job_id") or raw),
            "role": str(data.get("role") or ""),
            "status": str(data.get("status") or "queued"),
            "phase": str(data.get("phase") or "queued"),
            "progress": int(data.get("progress") or 0),
            "kind": str(data.get("kind") or "vocabulary"),
            "subject": str(data.get("subject") or "English"),
            "level": str(data.get("level") or ""),
            "count": int(data.get("requested_count") or 0),
            "current": int(data.get("current_count") or 0),
            "total": int(data.get("total_count") or data.get("requested_count") or 0),
            "created_at": str(data.get("created_at") or ""),
            "updated_at": str(data.get("updated_at") or ""),
            "completed_at": str(data.get("completed_at") or ""),
            "created_by": int(data.get("user_id") or 0),
            "result": result,
            "error": str(data.get("error") or "") or None,
        }
        GENERATOR_JOBS[raw] = dict(db_job)
        return db_job
    finally:
        conn.close()


def _update_ai_generator_job(job_id: str, updates: dict[str, Any], *, event: str = "update") -> dict[str, Any]:
    current = _get_saved_ai_generator_job(job_id) or GENERATOR_JOBS.get(str(job_id or "")) or {"job_id": str(job_id or "")}
    merged = {**dict(current), **dict(updates or {})}
    return _save_ai_generator_job(merged, event=event)


@app.exception_handler(HTTPException)
async def localized_http_exception_handler(request: Request, exc: HTTPException):
    detail: Any = exc.detail
    if isinstance(detail, str):
        detail = _translate_detail(detail, _request_locale(request))
    return JSONResponse(status_code=exc.status_code, content={"detail": detail}, headers=exc.headers)

