def _acquire_background_scheduler_lock() -> bool:
    """Allow exactly one web worker to run non-request background loops."""
    global background_scheduler_lock_file
    if background_scheduler_lock_file is not None:
        return True
    lock_path = Path(os.getenv("WEB_BACKGROUND_SCHEDULER_LOCK_PATH") or "/tmp/diamond-site-background-scheduler.lock")
    lock_file = lock_path.open("w")
    try:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        lock_file.close()
        return False
    background_scheduler_lock_file = lock_file
    return True

