def _resolve_lang(raw: str | None) -> str:
    low = str(raw or "").strip().lower()
    return low if low in WEB_LANGUAGES else "uz"


def _lang_from_accept_header(raw: str | None) -> str:
    if not raw:
        return "uz"
    sample = raw.split(",", 1)[0].strip().lower()
    if sample.startswith("ru"):
        return "ru"
    if sample.startswith("en"):
        return "en"
    if sample.startswith("uz"):
        return "uz"
    return "uz"


def _lang_from_auth_header(auth_header: str | None) -> str | None:
    if not auth_header or not auth_header.lower().startswith("bearer "):
        return None
    token = auth_header.split(" ", 1)[1].strip()
    if not token:
        return None
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except jwt.ExpiredSignatureError:
        # Expired token: fall back to request-header locale detection below.
        return None
    except Exception:
        return None
    user_id = int(payload.get("sub") or 0)
    if user_id <= 0:
        return None
    row = _safe_call(lambda: get_user_by_id(user_id), None)
    if not row:
        return None
    return _resolve_lang(str(row.get("language") or "uz"))


def _request_locale(request: Request) -> str:
    raw_explicit = request.headers.get("x-language")
    explicit = _resolve_lang(raw_explicit)
    if raw_explicit and raw_explicit.strip():
        return explicit
    from_auth = _lang_from_auth_header(request.headers.get("authorization"))
    if from_auth:
        return from_auth
    return _lang_from_accept_header(request.headers.get("accept-language"))


def _translate_detail(detail: str, locale: str) -> str:
    normalized_locale = _resolve_lang(locale)
    direct = DETAIL_TRANSLATIONS.get(detail)
    if direct:
        return direct.get(normalized_locale) or direct.get("uz") or detail
    for pattern, mapping in DETAIL_TRANSLATION_PATTERNS:
        match = pattern.match(detail)
        if not match:
            continue
        template = mapping.get(normalized_locale) or mapping.get("uz") or detail
        try:
            return template.format(**match.groupdict())
        except Exception:
            return template
    return detail


