def _safe_call(fn, fallback):
    try:
        return fn()
    except Exception:
        return fallback


import redis as _redis_lib
import json as _json_lib
_REDIS_CLIENT = _redis_lib.Redis.from_url("redis://localhost:6379/0", decode_responses=True)

class RedisSyncDict:
    def __init__(self, prefix):
        self.prefix = prefix

    def get(self, key, default=None):
        val = _REDIS_CLIENT.get(self.prefix + str(key))
        if val is None:
            return default
        try:
            return _json_lib.loads(val)
        except Exception:
            return default

    def __getitem__(self, key):
        val = self.get(key)
        if val is None:
            raise KeyError(key)
        return val

    def __setitem__(self, key, value):
        _REDIS_CLIENT.set(
            self.prefix + str(key),
            _json_lib.dumps(
                value,
                default=lambda item: item.isoformat() if isinstance(item, datetime) else str(item),
            ),
            ex=86400,
        )

    def __delitem__(self, key):
        _REDIS_CLIENT.delete(self.prefix + str(key))

    def __contains__(self, key):
        return _REDIS_CLIENT.exists(self.prefix + str(key)) > 0
        
    def pop(self, key, default=None):
        val = self.get(key, default)
        if val is not default:
            self.__delitem__(key)
        return val
        
    def items(self):
        keys = _REDIS_CLIENT.keys(self.prefix + "*")
        return [(k[len(self.prefix):], self.get(k[len(self.prefix):])) for k in keys]
        
    def values(self):
        return [v for k, v in self.items()]
        
    def keys(self):
        return [k for k, v in self.items()]
        
    def clear(self):
        keys = _REDIS_CLIENT.keys(self.prefix + "*")
        if keys:
            _REDIS_CLIENT.delete(*keys)

class RedisSyncSet:
    def __init__(self, prefix):
        self.prefix = prefix
        self.key = self.prefix + "set"
        
    def add(self, item):
        _REDIS_CLIENT.sadd(self.key, str(item))
        _REDIS_CLIENT.expire(self.key, 86400)
        
    def remove(self, item):
        _REDIS_CLIENT.srem(self.key, str(item))
        
    def __contains__(self, item):
        return _REDIS_CLIENT.sismember(self.key, str(item))
        
    def clear(self):
        _REDIS_CLIENT.delete(self.key)

BROADCAST_TASKS: dict[int, asyncio.Task] = {}
