def _ensure_student_quiz_session_schema() -> None:
    global STUDENT_QUIZ_SESSION_SCHEMA_READY
    if STUDENT_QUIZ_SESSION_SCHEMA_READY:
        return
    with STUDENT_QUIZ_SESSION_SCHEMA_LOCK:
        if STUDENT_QUIZ_SESSION_SCHEMA_READY:
            return
        conn = get_conn()
        cur = conn.cursor()
        try:
            try:
                cur.execute("SELECT pg_advisory_xact_lock(hashtext('student_quiz_sessions_schema'))")
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                cur = conn.cursor()
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS student_quiz_sessions (
                    session_id TEXT PRIMARY KEY,
                    user_id BIGINT NOT NULL,
                    quiz_kind TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'active',
                    state_json TEXT NOT NULL,
                    result_json TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    expires_at TIMESTAMP
                )
                """
            )
            cur.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_student_quiz_sessions_user_kind_status
                ON student_quiz_sessions(user_id, quiz_kind, status, updated_at)
                """
            )
            cur.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_student_quiz_sessions_expires
                ON student_quiz_sessions(expires_at)
                """
            )
            conn.commit()
            STUDENT_QUIZ_SESSION_SCHEMA_READY = True
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            logger.exception("student quiz session schema ensure failed")
            raise
        finally:
            conn.close()


def _student_quiz_expiry(status: str) -> datetime:
    hours = 24 if str(status or "").lower() in {"completed", "failed"} else 4
    return _now_utc().replace(tzinfo=None) + timedelta(hours=hours)


def _persist_student_quiz_session(session_id: str, user_id: int, quiz_kind: str, session: dict[str, Any], *, status: str = "active", result: dict[str, Any] | None = None) -> None:
    _ensure_student_quiz_session_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        state_json = json.dumps(session or {}, ensure_ascii=False, default=_json_default)
        result_json = json.dumps(result or {}, ensure_ascii=False, default=_json_default) if result else None
        cur.execute(
            """
            INSERT INTO student_quiz_sessions(session_id, user_id, quiz_kind, status, state_json, result_json, updated_at, expires_at)
            VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?)
            ON CONFLICT(session_id) DO UPDATE SET
                user_id=excluded.user_id,
                quiz_kind=excluded.quiz_kind,
                status=excluded.status,
                state_json=excluded.state_json,
                result_json=excluded.result_json,
                updated_at=CURRENT_TIMESTAMP,
                expires_at=excluded.expires_at
            """,
            (
                str(session_id),
                int(user_id),
                str(quiz_kind),
                str(status or "active"),
                state_json,
                result_json,
                _student_quiz_expiry(status),
            ),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("student quiz session persist failed session_id=%s kind=%s", session_id, quiz_kind)
        raise
    finally:
        conn.close()


def _load_student_quiz_session_locked(session_id: str, user_id: int, quiz_kind: str):
    _ensure_student_quiz_session_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM student_quiz_sessions
            WHERE session_id=? AND user_id=? AND quiz_kind=?
              AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)
            LIMIT 1
            FOR UPDATE
            """,
            (str(session_id), int(user_id), str(quiz_kind)),
        )
        row = cur.fetchone()
        if not row:
            conn.close()
            return None, None, None, None, None
        state = _safe_json_object((row or {}).get("state_json"))
        result = _safe_json_object((row or {}).get("result_json"))
        return conn, cur, dict(row), state, result
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        conn.close()
        raise


def _load_student_quiz_session_snapshot(session_id: str, user_id: int, quiz_kind: str) -> tuple[dict[str, Any] | None, dict[str, Any] | None, dict[str, Any] | None]:
    _ensure_student_quiz_session_schema()
    conn = get_conn()
