def _update_student_quiz_session_tx(cur, session_id: str, session: dict[str, Any], *, status: str = "active", result: dict[str, Any] | None = None) -> None:
    cur.execute(
        """
        UPDATE student_quiz_sessions
        SET state_json=?, result_json=?, status=?, updated_at=CURRENT_TIMESTAMP, expires_at=?
        WHERE session_id=?
        """,
        (
            json.dumps(session or {}, ensure_ascii=False, default=_json_default),
            json.dumps(result or {}, ensure_ascii=False, default=_json_default) if result else None,
            str(status or "active"),
            _student_quiz_expiry(status),
            str(session_id),
        ),
    )


def _ordered_admin_ids() -> list[int]:
    return list(dict.fromkeys([int(x) for x in (ADMIN_CHAT_IDS + LIMITED_ADMIN_CHAT_IDS)]))


def _admin_ref_id(user: dict) -> int:
    lid = str(user.get("login_id") or "").strip().upper()
    match = re.match(r"^DIAMOND-(ADM|LIM)-(\d+)$", lid)
    if match:
        kind = str(match.group(1) or "").upper()
        idx = int(match.group(2))
        ordered = ADMIN_CHAT_IDS if kind == "ADM" else LIMITED_ADMIN_CHAT_IDS
        if 1 <= idx <= len(ordered):
            return int(ordered[idx - 1])

    tg_raw = user.get("telegram_id")
    if tg_raw is not None and str(tg_raw).strip().isdigit():
        return int(str(tg_raw).strip())

    return int(user.get("id") or 0)


def _is_main_admin(admin_ref_id: int) -> bool:
    return int(admin_ref_id) in {int(x) for x in ADMIN_CHAT_IDS}


def _is_limited_admin(admin_ref_id: int) -> bool:
    return int(admin_ref_id) in {int(x) for x in LIMITED_ADMIN_CHAT_IDS}


def _is_general_admin_scope(admin_ref_id: int) -> bool:
    return _is_main_admin(admin_ref_id) or not _is_limited_admin(admin_ref_id)


def _limited_admin_owner_visible(admin_ref_id: int, owner_admin_id: Any) -> bool:
    """Limited admins see their own records plus General Admin/legacy-owned records."""
    if _is_general_admin_scope(int(admin_ref_id)):
        return True
    owner = int(owner_admin_id or 0)
    if owner == int(admin_ref_id):
        return True
    if owner <= 0:
        return True
    return not _is_limited_admin(owner)


def _limited_admin_owner_scope_sql(column_sql: str, admin_ref_id: int) -> tuple[str, list[Any]]:
    """
    SQL equivalent of _limited_admin_owner_visible for owner_admin_id columns.
    Records created by other limited admins are hidden; records created by the
    current limited admin, General Admins, or legacy rows without owner are visible.
    """
    limited_ids = sorted({int(x) for x in LIMITED_ADMIN_CHAT_IDS if int(x) > 0})
    column = str(column_sql)
    if limited_ids:
        placeholders = ", ".join(["?"] * len(limited_ids))
        return (
            f"(COALESCE({column},0)=? OR COALESCE({column},0)=0 OR COALESCE({column},0) NOT IN ({placeholders}))",
            [int(admin_ref_id), *limited_ids],
        )
    return (f"(COALESCE({column},0)=? OR COALESCE({column},0)=0)", [int(admin_ref_id)])


def _scoped_student_user_ids_for_admin(admin_ref_id: int) -> set[int]:
    rows = _scope_users_for_admin(int(admin_ref_id), _safe_call(get_all_users, []) or [], login_type_filter=(1, 2, 6))
    return {int(row.get("id") or 0) for row in rows if int(row.get("id") or 0) > 0}


def _shared_group_ids_for_limited_admin(admin_ref_id: int) -> set[int]:
    if _is_general_admin_scope(int(admin_ref_id)):
        return set()
    shared_student_ids = sorted({int(sid) for sid in get_shared_student_ids_for_admin(int(admin_ref_id)) if int(sid) > 0})
    if not shared_student_ids:
        return set()
    out: set[int] = set()
    conn = get_conn()
    cur = conn.cursor()
    placeholders = ", ".join(["?"] * len(shared_student_ids))
    sql_variants = (
        f"""
        SELECT DISTINCT ug.group_id
        FROM user_groups ug
        JOIN groups g ON g.id = ug.group_id
        WHERE ug.user_id IN ({placeholders})
          AND COALESCE(g.active, 1)=1
          AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT))='')
        """,
        f"""
        SELECT DISTINCT ug.group_id
        FROM user_groups ug
        JOIN groups g ON g.id = ug.group_id
        WHERE ug.user_id IN ({placeholders})
          AND COALESCE(g.active, 1)=1
        """,
    )
    try:
        for sql in sql_variants:
            try:
                cur.execute(sql, tuple(shared_student_ids))
                for row in (cur.fetchall() or []):
                    gid = int((row or {}).get("group_id") or 0)
                    if gid > 0:
                        out.add(gid)
                if out:
                    return out
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                continue
    finally:
        conn.close()
    # Safe fallback in case relation query fails.
    for sid in shared_student_ids:
        groups = _safe_call(lambda user_id=int(sid): get_user_groups(user_id), []) or []
        for group in groups:
            gid = int(group.get("id") or 0)
            if gid > 0:
                out.add(gid)
    return out


def _assert_general_admin_for_payment_globals(admin_ref_id: int, action: str) -> None:
    if _is_general_admin_scope(int(admin_ref_id)):
        return
    logger.warning(
        "payment_permission_denied action=%s scope=limited admin_ref_id=%s",
        str(action),
        int(admin_ref_id),
    )
    raise HTTPException(status_code=403, detail="Only general admin can manage global payment settings")


