def _scope_users_for_admin(admin_ref_id: int, users: list[dict], login_type_filter: tuple[int, ...] | None = None) -> list[dict]:
    if _is_general_admin_scope(admin_ref_id):
        if login_type_filter is None:
            return users
        return [u for u in users if int(u.get("login_type") or 0) in login_type_filter]

    scoped: list[dict] = []
    for row in users:
        lt = int(row.get("login_type") or 0)
        if login_type_filter is not None and lt not in login_type_filter:
            continue
        if lt in (1, 2, 6):
            if _limited_admin_owner_visible(int(admin_ref_id), row.get("owner_admin_id")):
                scoped.append(row)
        else:
            scoped.append(row)
    return scoped


def _scope_staff_for_admin(users: list[dict], login_type_filter: tuple[int, ...] | None = None) -> list[dict]:
    """
    Teachers/support visibility is shared across admins (not owner-scoped).
    """
    if login_type_filter is None:
        return [u for u in users if int(u.get("login_type") or 0) not in (1, 2, 6)]
    return [u for u in users if int(u.get("login_type") or 0) in login_type_filter]


def _scope_groups_for_admin(admin_ref_id: int, groups: list[dict]) -> list[dict]:
    if _is_general_admin_scope(admin_ref_id):
        return groups
    scoped: list[dict] = []
    for row in groups:
        if _limited_admin_owner_visible(int(admin_ref_id), row.get("owner_admin_id")):
            scoped.append(row)
    return scoped


def _can_manage_user(admin_ref_id: int, user_row: dict | None) -> bool:
    if not user_row:
        return False
    if _is_general_admin_scope(admin_ref_id):
        return True
    if int(user_row.get("login_type") or 0) in (1, 2, 6):
        return _limited_admin_owner_visible(int(admin_ref_id), user_row.get("owner_admin_id"))
    return True


def _can_manage_user_globally(admin_ref_id: int, user_row: dict | None) -> bool:
    """Admin user-management screens are shared; group/payment screens stay owner-scoped."""
    return bool(user_row)


def _is_protected_admin_row(user_row: dict | None) -> bool:
    return bool(user_row) and int(user_row.get("login_type") or 0) == 4


def _assert_not_protected_admin_target(user_row: dict | None) -> None:
    if _is_protected_admin_row(user_row):
        raise HTTPException(status_code=409, detail="Protected admin accounts are read-only")


def _can_manage_group(admin_ref_id: int, group_row: dict | None) -> bool:
    if not group_row:
        return False
    if _is_general_admin_scope(admin_ref_id):
        return True
    return _limited_admin_owner_visible(int(admin_ref_id), group_row.get("owner_admin_id"))


def _student_in_manageable_payment_group(admin_ref_id: int, user_id: int) -> bool:
    if _is_general_admin_scope(admin_ref_id):
        return True
    groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
    return any(_can_manage_group(int(admin_ref_id), group) for group in groups)


def _can_create_articles(user: dict) -> bool:
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role == "admin":
        return True
    if role not in {"teacher", "support"}:
        return False

    _ensure_web_tables(force=True)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT can_create FROM web_article_permissions WHERE user_id=? LIMIT 1", (int(user.get("id") or 0),))
    row = cur.fetchone()
    conn.close()
    if not row:
        return True
    return int(row.get("can_create") or 0) == 1


def _tg_token_for_login_type(login_type: int) -> str:
    if login_type == 6:
        return ""
    if login_type in (1, 2):
        return (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    if login_type == 3:
        return (os.getenv("TEACHER_BOT_TOKEN") or "").strip()
    if login_type == 5:
        return (os.getenv("SUPPORT_BOT_TOKEN") or "").strip()
    return (os.getenv("ADMIN_BOT_TOKEN") or "").strip()


async def _send_telegram_text(
    token: str,
    chat_id: str,
    text: str,
    button_text: str | None = None,
    button_url: str | None = None,
    *,
    button_web_app: bool = False,
    parse_mode: str | None = None,
) -> bool:
    if not token:
        return False
    payload: dict[str, Any] = {
        "chat_id": str(chat_id),
        "text": text,
        "disable_web_page_preview": False,
    }
    if parse_mode:
        payload["parse_mode"] = parse_mode
    if button_text and button_url:
        button_payload: dict[str, Any] = {"text": button_text}
        if button_web_app is True:
            is_web_app = True
        elif button_web_app is False:
            is_web_app = False
        else:
            is_web_app = ("diamond-education.com" in button_url or "diamond-education.uz" in button_url or "?startapp=" in button_url)
        
        if is_web_app:
            button_payload["web_app"] = {"url": button_url}
        else:
            button_payload["url"] = button_url
        payload["reply_markup"] = {
            "inline_keyboard": [[button_payload]],
        }
    url = f"https://api.telegram.org/bot{token}/sendMessage"
    timeout = aiohttp.ClientTimeout(total=10)
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(url, json=payload) as response:
                data = await response.json(content_type=None)
                return bool(data.get("ok"))
    except Exception:
        return False


async def _send_telegram_file(
    token: str,
    chat_id: str,
    file_path: str,
    caption: str = "",
) -> bool:
    if not token or not file_path:
        return False
    path = Path(file_path)
    if not path.exists() or not path.is_file():
        return False
        
    ext = path.suffix.lower()
    if ext in (".png", ".jpg", ".jpeg", ".webp", ".gif"):
        method = "sendPhoto"
        field = "photo"
    elif ext in (".ogg", ".mp3", ".wav", ".webm", ".m4a"):
        method = "sendVoice"
        field = "voice"
    elif ext in (".mp4", ".mov", ".avi"):
        method = "sendVideo"
        field = "video"
    else:
        method = "sendDocument"
        field = "document"

    url = f"https://api.telegram.org/bot{token}/{method}"
    timeout = aiohttp.ClientTimeout(total=60)
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            data = aiohttp.FormData()
            data.add_field("chat_id", str(chat_id))
            if caption:
                data.add_field("caption", caption[:1000])
            with open(path, "rb") as f:
                data.add_field(field, f, filename=path.name)
            async with session.post(url, data=data) as response:
                resp_data = await response.json(content_type=None)
                return bool(resp_data.get("ok"))
    except Exception:
        return False
async def _notify_video_comment(video_id: int, comment_text: str, author_name: str) -> None:
    conn = get_conn()
    try:
        cur = conn.cursor()
        cur.execute("SELECT title, teacher_id, support_teacher_ids FROM videos WHERE id = ?", (video_id,))
        video = cur.fetchone()
        if not video:
            return
            
        video_title = str(video.get("title") or "Video")
        teacher_id = int(video.get("teacher_id") or 0)
        support_ids_str = str(video.get("support_teacher_ids") or "")
        
        target_user_ids = set()
        if teacher_id > 0:
            target_user_ids.add(teacher_id)
        if support_ids_str:
            for s_id in support_ids_str.replace(" ", "").split(","):
                if s_id.isdigit() and int(s_id) > 0:
                    target_user_ids.add(int(s_id))
                    
        # Find admins
        cur.execute("SELECT telegram_id FROM users WHERE role = 'admin' AND telegram_id IS NOT NULL")
        admin_rows = cur.fetchall()
        telegram_ids = [str(r.get("telegram_id")).strip() for r in admin_rows if r.get("telegram_id")]
                    
        if target_user_ids:
            placeholders = ",".join("?" * len(target_user_ids))
            cur.execute(f"SELECT telegram_id FROM users WHERE id IN ({placeholders}) AND telegram_id IS NOT NULL", tuple(target_user_ids))
            user_rows = cur.fetchall()
            telegram_ids.extend([str(r.get("telegram_id")).strip() for r in user_rows if r.get("telegram_id")])
            
        telegram_ids = [t for t in set(telegram_ids) if t]
        if not telegram_ids:
            return
            
        bot_token = os.getenv("TELEGRAM_BOT_TOKEN")
        if not bot_token:
            return
            
        msg = f"Yangi sharh:\n\nVideo: {video_title}\nKimdan: {author_name}\nSharh: {comment_text}"
        button_url = f"{WEBAPP_URL}/videos/{video_id}"
        
        for tg_id in set(telegram_ids):
            if tg_id:
                asyncio.create_task(_send_telegram_text(
                    token=bot_token,
                    chat_id=tg_id,
                    text=msg,
                    button_text="Videoni ochish",
                    button_url=button_url,
                    button_web_app=True
                ))
    except Exception as e:
        print(f"Error notifying video comment: {e}")
    finally:
        conn.close()


def _safe_user_lang(row: dict | None, fallback: str = "uz") -> str:
    code = (detect_lang_from_user(row or {"language": fallback}) or fallback).strip().lower()
    if code not in {"uz", "ru", "en"}:
        return "uz"
    return code


