async def _run_broadcast_job(
    broadcast_id: int,
    message_text: str,
    recipients: list[dict],
    button_text: str | None = None,
    button_url: str | None = None,
    button_type: str = "auto",
) -> None:
    sent = 0
    failed = 0
    skipped = 0
    total = len(recipients)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("UPDATE web_broadcasts SET status='sending', started_at=CURRENT_TIMESTAMP WHERE id=?", (int(broadcast_id),))
    conn.commit()
    conn.close()

    # Real OS-level push alongside the existing Telegram fan-out below — a
    # broadcast previously only reached users through their Telegram bot
    # chat; anyone using the Flutter app without Telegram open got nothing.
    recipient_ids = [int(r.get("id") or 0) for r in recipients if int(r.get("id") or 0) > 0]
    if recipient_ids:
        threading.Thread(
            target=push_notifications.send_push_to_users,
            args=(recipient_ids, "Diamond Education", str(message_text or "")),
            kwargs={"data": {"target_screen": "notifications", "button_url": str(button_url or ""), "notification_type": "broadcast"}},
            daemon=True,
        ).start()

    for recipient in recipients:
        tg = str(recipient.get("telegram_id") or "").strip()
        if not tg:
            skipped += 1
            continue
        token = _tg_token_for_login_type(int(recipient.get("login_type") or 0))
        if not token:
            skipped += 1
            continue
        bw_app = True if button_type == "webapp" else (False if button_type == "regular" else None)
        ok = await _send_telegram_text(token, tg, message_text, button_text=button_text, button_url=button_url, button_web_app=bw_app)
        if ok:
            sent += 1
        else:
            failed += 1

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        UPDATE web_broadcasts
        SET status='completed',
            total_recipients=?,
            sent_count=?,
            failed_count=?,
            skipped_count=?,
            finished_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (int(total), int(sent), int(failed), int(skipped), int(broadcast_id)),
    )
    conn.commit()
    conn.close()


def _now_utc() -> datetime:
    return datetime.now(timezone.utc)


def _now_tashkent() -> datetime:
    return datetime.now(TASHKENT_TZ)


def _now_tashkent_date() -> str:
    return _now_tashkent().strftime("%Y-%m-%d")


def _parse_utc_timestamp(value: str | None) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _homework_window_anchor(homework: dict | None, submission: dict | None = None) -> datetime | None:
    # Homework lifetime policy: 7 days from assignment, then 7 days from first submission.
    submission_anchor = _parse_utc_timestamp(str((submission or {}).get("created_at") or ""))
    if submission_anchor is not None:
        return submission_anchor
    return _parse_utc_timestamp(str((homework or {}).get("created_at") or ""))


def _homework_window_open(homework: dict | None, submission: dict | None = None) -> bool:
    anchor = _homework_window_anchor(homework, submission)
    if anchor is None:
        return True
    return _now_utc() <= (anchor + timedelta(days=HOMEWORK_WINDOW_DAYS))


def _filter_homeworks_with_open_window(rows: list[dict]) -> list[dict]:
    kept: list[dict] = []
    for row in rows:
        homework_row = row if isinstance(row, dict) else {}
        submission_row = None
        if str(homework_row.get("submission_created_at") or "").strip():
            submission_row = {"created_at": homework_row.get("submission_created_at")}
        if _homework_window_open(homework_row, submission_row):
            kept.append(homework_row)
    return kept


def _json_text(value: Any) -> str | None:
    if value is None:
        return None
    try:
        return json.dumps(value, ensure_ascii=False)
    except Exception:
        return None


def _json_vector(value: Any) -> list[float] | None:
    if value is None:
        return None
    if isinstance(value, list):
        try:
            return [float(x) for x in value]
        except Exception:
            return None
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = json.loads(raw)
        if isinstance(parsed, list):
            return [float(x) for x in parsed]
    except Exception:
        return None
    return None


def _humanize_proctoring_image_error(error: Exception | str) -> str:
    code = str(error or "").strip()
    normalized = code.upper()
    if normalized in {"IMAGE_URL_REQUIRED", "INVALID_IMAGE_URL", "INVALID_IMAGE_PATH", "IMAGE_NOT_FOUND"}:
        return "Yuborilgan rasm topilmadi, qayta urinib ko'ring."
    if normalized in {"INVALID_IMAGE", "CORRUPTED_IMAGE"}:
        return "Rasmni o'qib bo'lmadi. Kamera kadrini qayta yuboring."
    if normalized in {"NO_FACE"}:
        return "Yuz topilmadi. Kameraga yaqinroq turing."
    if normalized in {"MULTIPLE_FACES"}:
        return "Faqat bitta yuz ko'rinishi kerak."
    if normalized in {"FACE_TOO_SMALL"}:
        return "Yuz juda kichik ko'rinmoqda. Kameraga yaqinroq turing."
    if normalized in {"FACE_NOT_CENTERED"}:
        return "Yuzni kamera ramkasi markaziga to'g'rilang."
    if normalized in {"LOW_QUALITY"}:
        return "Rasm sifati past. Yorug' joyda qayta urinib ko'ring."
    if normalized in {"ENGINE_ERROR", "EMBEDDING_MISSING", "INSIGHTFACE_PROVIDER_REQUIRED"}:
        return "Face analiz xizmati vaqtincha band. Qayta urinmoqda."
    return "Face ID kadrini tekshirib bo'lmadi, qayta urinib ko'ring."


def _is_insightface_embedding_model(model_name: Any) -> bool:
    return str(model_name or "").strip().lower().startswith("insightface")


def _mark_face_reenrollment_required(user_id: int, profile: dict | None = None, reason: str = "incompatible_embedding_model") -> None:
    if int(user_id or 0) <= 0:
        return
    conn = None
    try:
        conn = get_conn()
        cur = conn.cursor()
        profile_id = int((profile or {}).get("id") or 0)
        if profile_id > 0:
            cur.execute(
                """
                UPDATE user_face_profiles
                SET status='expired', updated_at=CURRENT_TIMESTAMP
                WHERE id=? AND user_id=?
                """,
                (profile_id, int(user_id)),
            )
        cur.execute(
            """
            UPDATE users
            SET face_enrollment_required=1,
                face_id_enrolled=0,
                face_id_status='pending',
                face_profile_status='pending',
                face_last_verified_at=NULL
            WHERE id=?
            """,
            (int(user_id),),
        )
        conn.commit()
        append_face_profile_audit(
            int(user_id),
            action_type="profile_reenroll_required",
            result_status="pending",
            details_json=_json_text({
                "reason": reason,
                "profile_id": profile_id or None,
                "embedding_model": (profile or {}).get("embedding_model"),
            }),
        )
        logger.info(
            "proctoring.profile.reenroll_required user_id=%s profile_id=%s reason=%s",
            int(user_id),
            profile_id,
            reason,
        )
        try:
            _clear_auth_caches_for_user(int(user_id))
        except Exception:
            pass
    except Exception:
        logger.exception("proctoring.profile.reenroll_required.failed user_id=%s", int(user_id))
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _ensure_face_profile_compatibility(user: dict) -> dict:
    if not user:
        return user
    user_id = int(user.get("id") or 0)
    if user_id <= 0:
        return user
    profile = get_active_face_profile(user_id)
    if not profile:
        return user
    if not _proctoring_image_url_exists(profile.get("reference_image_url")):
        _mark_face_reenrollment_required(user_id, profile=profile, reason="reference_image_missing")
        refreshed = _safe_call(lambda: get_user_by_id(user_id), None)
        return refreshed or user
    if _is_insightface_embedding_model(profile.get("embedding_model")):
        return user
    _mark_face_reenrollment_required(user_id, profile=profile, reason="embedding_model_mismatch")
    refreshed = _safe_call(lambda: get_user_by_id(user_id), None)
    return refreshed or user


def _user_requires_face_enrollment(user: dict) -> bool:
    # Proctoring/FaceID requirement removed from all test flows.
    # Students are never required to enroll a face or pass FaceID to take tests.
    # (Auth/role/timer/dedup/result/reward checks remain enforced elsewhere.)
    return False


def _require_proctoring_ready(user: dict) -> None:
    # Proctoring/FaceID requirement removed: never block a test on FaceID readiness.
    return None


def _face_enrollment_required_detail() -> dict[str, Any]:
    return {
        "code": "face_enrollment_required",
        "message": "FaceID setup kerak. Profil sahifasidan FaceID setup qiling.",
        "face_enrollment_required": True,
    }


def _require_student_face_setup_complete(user: dict) -> dict:
    """Block student learning/test flows before any attempt/session side effect."""
    user = _ensure_face_profile_compatibility(user)
    if _user_requires_face_enrollment(user):
        raise HTTPException(status_code=409, detail=_face_enrollment_required_detail())
    _require_proctoring_ready(user)
    return user


def _proctoring_runtime_available(user: dict) -> tuple[bool, dict, str | None]:
    # Proctoring/FaceID removed from all test flows: runtime proctoring is never required.
    # Returning "proctoring_disabled" makes _ensure_proctoring_session_access a no-op and
    # _attach_proctoring_payload report proctoring_required=False with no session.
    return False, user, "proctoring_disabled"


def _proctoring_failure_response(row: dict | None) -> None:
    if not row:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    status = str(row.get("status") or "")
    if status not in {"failed", "aborted"}:
        return
    reason = str(row.get("failure_reason") or "proctoring_failed").strip() or "proctoring_failed"
    raise HTTPException(status_code=423, detail=f"Test stopped by proctoring: {reason}")


def _abort_unverified_active_proctoring_sessions_for_user(user_id: int, *, exclude_session_id: int | None = None, reason: str = "new_proctoring_session_started") -> int:
    """Clean up stale camera-start sessions so a fresh FaceID attempt cannot attach to old state."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        if int(exclude_session_id or 0) > 0:
            cur.execute(
                """
                UPDATE test_proctoring_sessions
                SET status='aborted',
                    failure_reason=?,
                    final_verdict='aborted',
                    verdict_reason=?,
                    terminated_by='system'
                WHERE user_id=?
                  AND status='active'
                  AND COALESCE(face_last_seen, 0)=0
                  AND id<>?
                """,
                (reason, reason, int(user_id), int(exclude_session_id or 0)),
            )
        else:
            cur.execute(
                """
                UPDATE test_proctoring_sessions
                SET status='aborted',
                    failure_reason=?,
                    final_verdict='aborted',
                    verdict_reason=?,
                    terminated_by='system'
                WHERE user_id=?
                  AND status='active'
                  AND COALESCE(face_last_seen, 0)=0
                """,
                (reason, reason, int(user_id)),
            )
        affected = int(getattr(cur, "rowcount", 0) or 0)
        conn.commit()
        if affected:
            logger.info("proctoring.session.cleanup_unverified user_id=%s affected=%s reason=%s", int(user_id), affected, reason)
        return affected
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("proctoring.session.cleanup_unverified.error user_id=%s", int(user_id))
        return 0
    finally:
        conn.close()


def _ensure_proctoring_session_access(user: dict, session_id: int | None, *, expected_test_type: str, expected_attempt_ref: str | None = None) -> dict[str, Any] | None:
    available, user, unavailable_reason = _proctoring_runtime_available(user)
    if not available:
        if unavailable_reason == "face_enrollment_required":
            logger.info(
                "proctoring.session_access.skipped user_id=%s test_type=%s attempt_ref=%s reason=%s",
                int(user.get("id") or 0),
                str(expected_test_type or ""),
                str(expected_attempt_ref or ""),
                unavailable_reason,
            )
            raise HTTPException(status_code=409, detail="Face enrollment is required before starting tests")
        return None
    sid = int(session_id or 0)
    if sid <= 0:
        raise HTTPException(status_code=400, detail="proctoring_session_id is required")
    row = get_test_proctoring_session(sid)
    if not row:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    if int(row.get("user_id") or 0) != int(user.get("id") or 0):
        raise HTTPException(status_code=403, detail="Proctoring session does not belong to current user")
    if str(row.get("test_type") or "") != str(expected_test_type or ""):
        raise HTTPException(status_code=409, detail="Proctoring session is linked to different test type")
    if expected_attempt_ref is not None:
        actual_ref = str(row.get("test_attempt_ref") or "")
        if actual_ref != str(expected_attempt_ref or ""):
            # For competition modes (Duel/Arena/Boss), the session may transition from lobby -> running
            # with the same proctoring row. Be lenient on exact ref match to avoid blocking submits.
            is_competition_mode = str(expected_test_type or "").startswith(("duel-", "boss", "daily", "group"))
            if not is_competition_mode:
                raise HTTPException(status_code=409, detail="Proctoring session is linked to different test attempt")
            else:
                logger.info(
                    "proctoring.ref_mismatch_allowed competition mode=%s user=%s expected_ref=%s actual_ref=%s",
                    expected_test_type, int(user.get("id") or 0), expected_attempt_ref, actual_ref
                )
    _proctoring_failure_response(row)
    if str(row.get("status") or "active") != "active":
        raise HTTPException(status_code=423, detail="Proctoring session is not active")
    # Strictly require at least one valid face-detected frame before answers can continue.
    # This blocks "no-face" bypass attempts where test flow could continue without live detection.
    if not bool(int(row.get("face_last_seen") or 0)):
        raise HTTPException(status_code=423, detail="Yuz aniqlanmadi. Iltimos, kameraga qarang.")
    return row


def _attach_proctoring_payload(user: dict, response_payload: dict[str, Any], *, test_type: str, test_attempt_ref: str | None = None, test_route: str | None = None) -> dict[str, Any]:
    available, user, unavailable_reason = _proctoring_runtime_available(user)
    if not available:
        response_payload["proctoring_required"] = unavailable_reason == "face_enrollment_required"
        response_payload["face_enrollment_required"] = _user_requires_face_enrollment(user)
        response_payload["proctoring_status"] = unavailable_reason or "disabled"
        response_payload["proctoring_degraded"] = unavailable_reason == "face_enrollment_required"
        response_payload["proctoring_block_reason"] = "Face enrollment is required before starting tests" if unavailable_reason == "face_enrollment_required" else None
        if unavailable_reason == "face_enrollment_required":
            logger.info(
                "proctoring.attach.skipped user_id=%s test_type=%s attempt_ref=%s reason=%s",
                int(user.get("id") or 0),
                str(test_type or ""),
                str(test_attempt_ref or ""),
                unavailable_reason,
            )
        return response_payload
    active = get_active_test_proctoring_session(int(user.get("id") or 0), test_type, test_attempt_ref)
    if not active:
        active = create_test_proctoring_session(
            int(user.get("id") or 0),
            test_type=test_type,
            test_attempt_ref=test_attempt_ref,
            test_route=test_route,
            selfie_preview_required=True,
        )
    response_payload["proctoring_required"] = True
    response_payload["face_enrollment_required"] = False
    response_payload["proctoring_session_id"] = int(active.get("id") or 0)
    response_payload["proctoring_status"] = str(active.get("status") or "active")
    return response_payload


def _apply_proctoring_event_batch(session_row: dict[str, Any], payload: ProctoringEventsRequest) -> dict[str, Any]:
    row = dict(session_row)
    session_id = int(row.get("id") or 0)
    user_id = int(row.get("user_id") or 0)
    now = _now_utc()
    current_status = str(row.get("status") or "active")
    failure_reason = str(row.get("failure_reason") or "").strip() or None

    for snapshot in payload.snapshots:
        add_test_proctoring_snapshot(
            session_id,
            face_count=int(snapshot.face_count or 0),
            is_live=bool(snapshot.is_live),
            match_score=snapshot.match_score,
            preview_visible=bool(snapshot.preview_visible),
            app_visibility=snapshot.app_visibility,
            snapshot_image_url=snapshot.snapshot_image_url,
            metadata_json=_json_text(snapshot.metadata),
        )

    for item in payload.events:
        event_type = str(item.event_type or "").strip()
        alias_map = {
            "face_returned": "face_restored",
            "app_returned": "app_restored",
            "different_face": "multiple_faces",
            "screenshot_attempt": "screenshot_attempt",
            "SCREENSHOT_SUSPECTED": "screenshot_attempt",
            "TAB_HIDDEN": "tab_hidden",
            "WINDOW_BLUR": "window_blur",
            "NO_FACE": "face_missing",
            "FACE_TOO_SMALL": "face_too_small",
            "LOOKING_AWAY": "looking_away",
            "MULTIPLE_FACES": "multiple_faces",
            "FACE_MISMATCH": "face_mismatch",
            "FULLSCREEN_EXIT": "fullscreen_exit",
            "CAMERA_STREAM_LOST": "camera_stream_lost",
        }
        event_type = alias_map.get(event_type, event_type)
        if not event_type:
            continue
        grace_started_at = None
        grace_expires_at = None
        resolved_at = None

        if event_type == "camera_started":
            row = update_test_proctoring_session_status(session_id, status="active", camera_started=True) or row
        elif event_type == "face_detected":
            resolved_at = now.isoformat()
            row = _resolve_proctoring_warning(row, session_id=session_id, grace_type=None)
            row = update_test_proctoring_session_status(
                session_id,
                status="active",
                face_last_seen=True,
                clear_face_missing_grace=True,
                clear_warning_grace=True,
                last_match_score=item.score,
            ) or row
        elif event_type in {"face_missing", "face_too_small", "looking_away"}:
            increment_test_proctoring_counter(session_id, "face_missing_count", 1)
            row, grace_started_at, grace_expires_at = _begin_or_fail_proctoring_warning(
                row,
                session_id=session_id,
                user_id=user_id,
                event_type=event_type,
                score=item.score,
            )
        elif event_type == "face_restored":
            resolved_at = now.isoformat()
            current_grace = _parse_utc_timestamp(str(row.get("face_missing_grace_until") or ""))
            if current_grace and now > current_grace:
                row = update_test_proctoring_session_status(session_id, status="failed", failure_reason="face_missing_timeout") or row
                log_test_proctoring_event(
                    session_id,
                    user_id,
                    event_type="face_missing_timeout",
                    event_status="failed",
                    reason_code="face_returned_after_5_seconds",
                )
            else:
                row = _resolve_proctoring_warning(row, session_id=session_id, grace_type=None)
                row = update_test_proctoring_session_status(
                    session_id,
                    status="active",
                    face_last_seen=True,
                    clear_face_missing_grace=True,
                    clear_warning_grace=True,
                    last_match_score=item.score,
                ) or row
        elif event_type in {"app_hidden", "tab_hidden", "window_blur", "fullscreen_exit"}:
            increment_test_proctoring_counter(session_id, "app_hidden_count", 1)
            if event_type in {"app_hidden", "tab_hidden", "window_blur"} and str(item.event_status or "").strip().lower() == "failed":
                row = update_test_proctoring_session_status(
                    session_id,
                    status="failed",
                    failure_reason=str(item.reason_code or event_type or "app_closed"),
                    final_verdict="failed",
                    verdict_reason=str(item.reason_code or event_type or "app_closed"),
                    terminated_by="system",
                    clear_warning_grace=True,
                    clear_app_blur_grace=True,
                ) or row
            else:
                row, grace_started_at, grace_expires_at = _begin_or_fail_proctoring_warning(
                    row,
                    session_id=session_id,
                    user_id=user_id,
                    event_type=event_type,
                    score=item.score,
                )
        elif event_type == "app_restored":
            resolved_at = now.isoformat()
            current_grace = _parse_utc_timestamp(str(row.get("app_blur_grace_until") or ""))
            if current_grace and now > current_grace:
                row = update_test_proctoring_session_status(session_id, status="failed", failure_reason="app_hidden_timeout") or row
                log_test_proctoring_event(
                    session_id,
                    user_id,
                    event_type="app_hidden_timeout",
                    event_status="failed",
                    reason_code="app_returned_after_5_seconds",
                )
            else:
                row = _resolve_proctoring_warning(row, session_id=session_id, grace_type=None)
        elif event_type == "internet_lost":
            increment_test_proctoring_counter(session_id, "app_hidden_count", 1)
            row, grace_started_at, grace_expires_at = _begin_or_fail_proctoring_warning(
                row,
                session_id=session_id,
                user_id=user_id,
                event_type="internet_lost",
                score=item.score,
            )
        elif event_type == "internet_restored":
            resolved_at = now.isoformat()
            current_grace = _parse_utc_timestamp(str(row.get("app_blur_grace_until") or ""))
            if current_grace and now > current_grace:
                row = update_test_proctoring_session_status(session_id, status="failed", failure_reason="internet_lost_timeout") or row
                log_test_proctoring_event(
                    session_id,
                    user_id,
                    event_type="internet_lost_timeout",
                    event_status="failed",
                    reason_code="internet_restored_after_10_seconds",
                )
            else:
                row = _resolve_proctoring_warning(row, session_id=session_id, grace_type=None)
        elif event_type == "preview_hidden":
            row = update_test_proctoring_session_status(
                session_id,
                status="active",
                selfie_preview_visible=False,
            ) or row
        elif event_type == "camera_permission_pending":
            grace_started_at = now.isoformat()
            grace_expires_at = (now + timedelta(seconds=60)).isoformat()
            logger.info(
                "proctoring.permission_pending session_id=%s user_id=%s grace_started=1 expires_at=%s reason=%s",
                session_id,
                user_id,
                grace_expires_at,
                str(item.reason_code or "camera_permission_pending"),
            )
            row = update_test_proctoring_session_status(session_id, status="active") or row
        elif event_type == "camera_denied":
            if (
                str(item.event_status or "").lower() == "failed"
                and str(item.reason_code or "").lower() in {"camera_permission_timeout", "permission_timeout"}
            ):
                logger.info(
                    "proctoring.grace_expired session_id=%s user_id=%s fail_applied=1 reason=camera_permission_timeout",
                    session_id,
                    user_id,
                )
                row = update_test_proctoring_session_status(
                    session_id,
                    status="failed",
                    failure_reason="camera_permission_timeout",
                    final_verdict="failed",
                    verdict_reason="camera_permission_timeout",
                    terminated_by="system",
                ) or row
            else:
                grace_started_at = now.isoformat()
                grace_expires_at = (now + timedelta(seconds=60)).isoformat()
                logger.info(
                    "proctoring.permission_pending session_id=%s user_id=%s grace_started=1 expires_at=%s reason=%s",
                    session_id,
                    user_id,
                    grace_expires_at,
                    str(item.reason_code or "camera_denied"),
                )
                row = update_test_proctoring_session_status(session_id, status="active") or row
        elif event_type in {"multiple_faces", "liveness_failed", "face_mismatch", "camera_stopped", "screen_locked", "camera_stream_lost"}:
            if event_type in {"multiple_faces", "face_mismatch"}:
                increment_test_proctoring_counter(session_id, "face_different_person_count", 1)
            row, grace_started_at, grace_expires_at = _begin_or_fail_proctoring_warning(
                row,
                session_id=session_id,
                user_id=user_id,
                event_type=event_type,
                score=item.score,
            )
        elif event_type in {"screenshot_attempt", "screenshot_detected"}:
            row = update_test_proctoring_session_status(
                session_id,
                status="active",
            ) or row
            increment_test_proctoring_counter(session_id, "screenshot_attempt_count", 1)
            log_proctoring_screenshot_attempt(
                session_id,
                user_id,
                detection_method=str((item.details or {}).get("detection_method") or "keyboard_shortcut"),
                key_combination=str((item.details or {}).get("key_combination") or ""),
                blocked=True,
                details_json=_json_text(item.details),
            )

        log_test_proctoring_event(
            session_id,
            user_id,
            event_type=event_type,
            event_status=item.event_status,
            reason_code=item.reason_code,
            score=item.score,
            grace_started_at=grace_started_at,
            grace_expires_at=grace_expires_at,
            resolved_at=resolved_at,
            client_ts=item.client_ts,
            details_json=_json_text(item.details),
        )

        row = _fail_expired_proctoring_warning(row, session_id=session_id, user_id=user_id)
        face_grace = _parse_utc_timestamp(str((row or {}).get("face_missing_grace_until") or ""))
        app_grace = _parse_utc_timestamp(str((row or {}).get("app_blur_grace_until") or ""))
        if str((row or {}).get("status") or "") == "active" and face_grace and now > face_grace:
            row = update_test_proctoring_session_status(session_id, status="failed", failure_reason="face_missing_timeout") or row
            log_test_proctoring_event(
                session_id,
                user_id,
                event_type="face_missing_timeout",
                event_status="failed",
                reason_code=f"face_missing_over_{PROCTORING_NO_FACE_GRACE_SEC}_seconds",
            )
        if str((row or {}).get("status") or "") == "active" and app_grace and now > app_grace:
            row = update_test_proctoring_session_status(session_id, status="failed", failure_reason="app_hidden_timeout") or row
            log_test_proctoring_event(
                session_id,
                user_id,
                event_type="app_hidden_timeout",
                event_status="failed",
                reason_code=f"app_hidden_over_{PROCTORING_FULLSCREEN_EXIT_GRACE_SEC}_seconds",
            )

        current_status = str((row or {}).get("status") or current_status)
        failure_reason = str((row or {}).get("failure_reason") or failure_reason or "").strip() or None
        if current_status == "failed":
            break

    if current_status == "failed" and not bool(int((row or {}).get("penalty_applied") or 0)):
        row = update_test_proctoring_session_status(
            session_id,
            status="failed",
            final_verdict="failed",
            verdict_reason=str(failure_reason or "proctoring_failed"),
            terminated_by="system",
        ) or row
        max_penalty_amount, penalty_details = _proctoring_max_dpoint_penalty(dict(row or {}))
        penalty_details["reason"] = str(failure_reason or "proctoring_failed")
        apply_proctoring_penalty(
            user_id,
            session_id,
            test_type=str((row or {}).get("test_type") or ""),
            penalty_rule=str(failure_reason or "proctoring_failed"),
            penalty_percent=0.0,
            penalty_amount=float(max_penalty_amount),
            details_json=_json_text(penalty_details),
        )
        log_test_proctoring_event(
            session_id,
            user_id,
            event_type="penalty_applied",
            event_status="success",
            reason_code=str(failure_reason or "proctoring_failed"),
        )
        row = get_test_proctoring_session(session_id) or row
    proctoring_failed = str((row or {}).get("status") or current_status) == "failed"
    if proctoring_failed and str((row or {}).get("test_type") or "").strip().lower() == "daily":
        attempt_ref = str((row or {}).get("test_attempt_ref") or "").strip()
        if attempt_ref.isdigit():
            _safe_call(lambda: mark_daily_test_attempt_failed(int(attempt_ref)), False)
    if proctoring_failed:
        _competition_mark_user_left_by_proctoring(
            user_id,
            str((row or {}).get("test_type") or ""),
            str((row or {}).get("test_attempt_ref") or ""),
            str(failure_reason or "proctoring_failed"),
        )

    return dict(row)


def _placement_time_remaining(question_started_at: str | None) -> int:
    started = _parse_utc_timestamp(question_started_at)
    if not started:
        return PLACEMENT_TIME_LIMIT_SEC
    elapsed = int((_now_utc() - started).total_seconds())
    return max(0, PLACEMENT_TIME_LIMIT_SEC - max(0, elapsed))


def _placement_apply_expired_timeouts(user_id: int, session: dict) -> dict:
    if not session.get("active"):
        return session
    ids = session.get("questions") or []
    changed = False
    while int(session.get("question_index") or 0) < len(ids):
        if _placement_time_remaining(session.get("question_started_at")) > 0:
            break
        session["question_index"] = int(session.get("question_index") or 0) + 1
        changed = True
        if int(session.get("question_index") or 0) < len(ids):
            session["question_started_at"] = _now_utc().isoformat()
        else:
            break
    if changed:
        save_placement_session(int(user_id), session)
    return session


PROCTORING_WARNING_LIMIT = 1


def _proctoring_warning_timeout(event_type: str) -> int:
    if event_type in {"internet_lost"}:
        return PROCTORING_OFFLINE_GRACE_SEC
    if event_type in {"face_too_small"}:
        return PROCTORING_FACE_TOO_SMALL_GRACE_SEC
    if event_type in {"looking_away"}:
        return PROCTORING_LOOKING_AWAY_GRACE_SEC
    return PROCTORING_NO_FACE_GRACE_SEC


def _proctoring_max_dpoint_penalty(row: dict[str, Any]) -> tuple[float, dict[str, Any]]:
    test_type = str((row or {}).get("test_type") or "").strip().lower()
    attempt_ref = str((row or {}).get("test_attempt_ref") or "").strip()
    details = {
        "penalty_unit": "dpoint",
        "penalty_policy": "fixed_proctoring_penalty",
        "test_type": test_type,
        "attempt_ref": attempt_ref,
        "fixed_amount": 10.0,
    }
    return 10.0, details


def _begin_or_fail_proctoring_warning(
    row: dict[str, Any],
    *,
    session_id: int,
    user_id: int,
    event_type: str,
    score: float | None = None,
) -> tuple[dict[str, Any], str | None, str | None]:
    now = _now_utc()
    current_warning = _parse_utc_timestamp(str((row or {}).get("warning_grace_until") or ""))
    if current_warning and current_warning > now:
        return row, None, current_warning.isoformat()

    used = int((row or {}).get("warning_count") or 0)
    if used >= PROCTORING_WARNING_LIMIT:
        failed = update_test_proctoring_session_status(
            session_id,
            status="failed",
            failure_reason=f"{event_type}_warning_limit",
            final_verdict="failed",
            verdict_reason=f"{event_type}_warning_limit",
            terminated_by="system",
            clear_warning_grace=True,
        ) or row
        return failed, None, None

    increment_test_proctoring_counter(session_id, "warning_count", 1)
    timeout_sec = _proctoring_warning_timeout(event_type)
    expires_at = (now + timedelta(seconds=timeout_sec)).isoformat()
    kwargs: dict[str, Any] = {
        "status": "active",
        "warning_grace_until": expires_at,
        "last_match_score": score,
    }
    if event_type in {"face_missing", "face_too_small", "looking_away", "multiple_faces", "face_mismatch"}:
        kwargs["face_missing_grace_until"] = expires_at
    else:
        kwargs["app_blur_grace_until"] = expires_at
    updated = update_test_proctoring_session_status(session_id, **kwargs) or row
    create_proctoring_grace_period(session_id, user_id, grace_type=event_type, timeout_sec=timeout_sec)
    return updated, now.isoformat(), expires_at


def _resolve_proctoring_warning(row: dict[str, Any], *, session_id: int, grace_type: str | None = None) -> dict[str, Any]:
    resolve_proctoring_grace_period(proctoring_session_id=session_id, grace_type=grace_type, resolution="recovered")
    return update_test_proctoring_session_status(
        session_id,
        status="active",
        clear_warning_grace=True,
        clear_face_missing_grace=True,
        clear_app_blur_grace=True,
    ) or row


def _fail_expired_proctoring_warning(row: dict[str, Any], *, session_id: int, user_id: int) -> dict[str, Any]:
    now = _now_utc()
    warning_grace = _parse_utc_timestamp(str((row or {}).get("warning_grace_until") or ""))
    if str((row or {}).get("status") or "") == "active" and warning_grace and now > warning_grace:
        reason = "proctoring_warning_timeout"
        row = update_test_proctoring_session_status(
            session_id,
            status="failed",
            failure_reason=reason,
            final_verdict="failed",
            verdict_reason=reason,
            terminated_by="system",
            clear_warning_grace=True,
        ) or row
        log_test_proctoring_event(
            session_id,
            user_id,
            event_type=reason,
            event_status="failed",
            reason_code=f"warning_over_{PROCTORING_NO_FACE_GRACE_SEC}_seconds",
        )
    return row


def _days_since_join(created_at: str | None) -> int | None:
    joined = _parse_utc_timestamp(created_at)
    if not joined:
        return None
    return max(0, int((_now_utc() - joined).total_seconds() // 86400))


def _review_policy_for_user(user: dict) -> dict:
    user_id = int(user.get("id") or 0)
    min_days = 30
    days = _days_since_join(user.get("created_at"))
    wait_required = bool(int(user.get("review_wait_required") or 0))

    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT
            SUM(CASE WHEN LOWER(TRIM(COALESCE(status, '')))='approved' THEN 1 ELSE 0 END) AS approved_count,
            SUM(CASE WHEN LOWER(TRIM(COALESCE(status, '')))='pending' THEN 1 ELSE 0 END) AS pending_count
        FROM web_student_reviews
        WHERE user_id=?
        """,
        (user_id,),
    )
    row = cur.fetchone() or {}
    conn.close()
    approved_count = int(row.get("approved_count") or 0)
    pending_count = int(row.get("pending_count") or 0)
    has_approved_review = approved_count > 0
    has_pending_review = pending_count > 0

    can_submit = True
    reason = ""

    return {
        "can_submit": can_submit,
        "min_days_required": min_days,
        "wait_required": wait_required,
        "days_since_join": days,
        "has_approved_review": has_approved_review,
        "has_pending_review": has_pending_review,
        "approved_reviews_count": approved_count,
        "pending_reviews_count": pending_count,
        "reason": reason,
    }


def _normalize_review_status(status: Any, default: str = "pending") -> str:
    value = str(status or "").strip().lower()
    if value in {"pending", "approved", "rejected"}:
        return value
    return default


def _attempt_counts_from_items(items: list[dict]) -> tuple[int, int, int]:
    correct = wrong = unanswered = 0
    for item in items:
        selected = item.get("selected_option")
        timed_out = bool(int(item.get("timed_out") or 0))
        is_correct = bool(int(item.get("is_correct") or 0))
        if selected is None and timed_out:
            unanswered += 1
        elif selected is None:
            continue
        elif is_correct:
            correct += 1
        else:
            wrong += 1
    return correct, wrong, unanswered


def _daily_attempt_row(attempt_id: int) -> dict | None:
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM daily_test_attempts WHERE id=? LIMIT 1", (int(attempt_id),))
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def _daily_attempt_by_user_for_today(user_id: int, subject: str) -> dict | None:
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT *
        FROM daily_test_attempts
        WHERE user_id=? AND subject=? AND test_date=?
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(user_id), str(subject), _now_tashkent_date()),
    )
    row = cur.fetchone()
    conn.close()
    return dict(row) if row else None


def _daily_locked_message(status: str) -> str:
    normalized = str(status or "").strip().lower()
    if normalized == "failed":
        return "Daily test already failed today. You can try again tomorrow."
    return "Daily test already completed today. You can try again tomorrow."


def _daily_locked_payload(user: dict, attempt: dict, items: list[dict]) -> dict[str, Any]:
    out = _daily_session_payload(user, attempt, items)
    status = str(attempt.get("status") or "").strip().lower()
    out["exists"] = True
    out["blocked"] = True
    out["blocked_reason"] = f"daily_{status or 'locked'}_today"
    out["message"] = _daily_locked_message(status)
    return out


def _daily_unavailable_payload(subject: str, level: str, message: str) -> dict[str, Any]:
    return {
        "exists": False,
        "blocked": True,
        "blocked_reason": "daily_bank_insufficient",
        "message": message,
        "subject": subject,
        "level": level,
        "question_index": 0,
        "total_questions": DAILY_TEST_QUESTION_COUNT,
        "progress_percent": 0,
        "time_limit_sec": DAILY_TEST_WEB_SECONDS,
        "time_remaining_sec": 0,
        "completed": False,
        "stats": {"correct": 0, "wrong": 0, "unanswered": 0},
    }


def _daily_cleanup_used_bank_once_per_day() -> None:
    global _LAST_DAILY_BANK_CLEANUP_DATE
    today = _now_tashkent_date()
    if _LAST_DAILY_BANK_CLEANUP_DATE == today:
        return
    _LAST_DAILY_BANK_CLEANUP_DATE = today
    try:
        removed = cleanup_expired_daily_tests(days=1)
        if removed:
            logger.info("daily_tests_bank cleanup removed=%s", removed)
    except Exception:
        logger.exception("daily_tests_bank cleanup failed")


def _daily_timer_key(attempt_id: int, question_index: int) -> str:
    return f"{int(attempt_id)}:{int(question_index)}"


def _daily_question_time_remaining(attempt_id: int, question_index: int) -> int:
    key = _daily_timer_key(attempt_id, question_index)
    started_at = WEB_DAILY_ATTEMPT_TIMERS.get(key)
    if not started_at:
        WEB_DAILY_ATTEMPT_TIMERS[key] = _now_utc().isoformat()
        return DAILY_TEST_WEB_SECONDS
    started_dt = _parse_utc_timestamp(started_at)
    if not started_dt:
        WEB_DAILY_ATTEMPT_TIMERS[key] = _now_utc().isoformat()
        return DAILY_TEST_WEB_SECONDS
    elapsed = int((_now_utc() - started_dt).total_seconds())
    return max(0, DAILY_TEST_WEB_SECONDS - max(0, elapsed))


def _daily_apply_expired_timeouts(attempt_id: int, items: list[dict]) -> list[dict]:
    changed = False
    while True:
        current = None
        for row in items:
            if row.get("selected_option") is None and not bool(int(row.get("timed_out") or 0)):
                current = row
                break
        if not current:
            break
        question_index = int(current.get("question_index") or 0)
        if _daily_question_time_remaining(attempt_id, question_index) > 0:
            break
        mark_daily_test_question_timed_out(attempt_id, question_index)
        WEB_DAILY_ATTEMPT_TIMERS.pop(_daily_timer_key(attempt_id, question_index), None)
        items = get_daily_test_attempt_items(attempt_id)
        changed = True
    return get_daily_test_attempt_items(attempt_id) if changed else items


def _daily_finalize_if_all_answered(user: dict, attempt: dict, items: list[dict]) -> tuple[dict, list[dict], dict | None]:
    status = str(attempt.get("status") or "").strip().lower()
    if status in {"completed", "failed"}:
        return attempt, items, None
    has_current = any(row.get("selected_option") is None and not bool(int(row.get("timed_out") or 0)) for row in items)
    if has_current:
        return attempt, items, None
    correct, wrong, unanswered = _attempt_counts_from_items(items)
    breakdown = award_quiz_dpoints(
        user_id=int(user.get("id") or 0),
        subject=str(attempt.get("subject") or "English"),
        correct_count=correct,
        wrong_count=wrong,
        skipped_count=unanswered,
        mode="daily_test",
        change_type="daily_test_web_result",
    )
    net = float(breakdown.get("final_dcoins") or 0)
    net_points = float(breakdown.get("total_points") or 0)
    finish_daily_test_attempt(
        attempt_id=int(attempt.get("id") or 0),
        correct=correct,
        wrong=wrong,
        unanswered=unanswered,
        net_dcoins=net,
        net_dpoints=net_points,
    )
    refreshed_attempt = _daily_attempt_row(int(attempt.get("id") or 0)) or attempt
    refreshed_items = get_daily_test_attempt_items(int(attempt.get("id") or 0))
    return refreshed_attempt, refreshed_items, breakdown


def _apply_daily_breakdown_payload(payload: dict[str, Any], breakdown: dict | None) -> dict[str, Any]:
    if not breakdown:
        return payload
    payload["dcoin_breakdown"] = breakdown
    payload["dpoint_breakdown"] = breakdown
    payload["dpoints"] = float(breakdown.get("total_points") or 0.0)
    payload["dcoin"] = float(breakdown.get("final_dcoins") or 0.0)
    return payload


TEST_MCQ_QUESTION_TYPES = {
    "multiple_choice",
    "grammar_rules",
    "grammar_sentence",
    "find_mistake",
    "error_spotting",
    "gap_filling",
    "definition",
    "translation",
    "reading",
    "grammar",
    "sentence_error",
    "true_false",
    "synonym",
    "antonym",
    "gap_fill",
    "vocab_definition",
}


def _row_value(row: Any, key: str, default: Any = None) -> Any:
    if isinstance(row, dict):
        return row.get(key, default)
    try:
        return row[key]
    except Exception:
        getter = getattr(row, "get", None)
        if callable(getter):
            try:
                return getter(key, default)
            except Exception:
                return default
        return default


def _safe_json_object(raw: Any) -> dict[str, Any]:
    if isinstance(raw, dict):
        return raw
    if not raw:
        return {}
    try:
        parsed = json.loads(str(raw))
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _safe_json_array(raw: Any) -> list[Any]:
    if isinstance(raw, list):
        return raw
    if not raw:
        return []
    try:
        parsed = json.loads(str(raw))
    except Exception:
        return []
    return parsed if isinstance(parsed, list) else []


def _normalize_answer_text(value: Any) -> str:
    text = str(value or "").strip().lower()
    text = re.sub(r"[^\w\s'-]+", "", text, flags=re.UNICODE)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _test_subject_is_russian(subject: Any) -> bool:
    normalized = str(subject or "").strip().lower()
    return normalized == "russian" or "рус" in normalized or "ru" == normalized


def _test_tts_language_for_subject(subject: Any) -> str:
    return "ru-RU" if _test_subject_is_russian(subject) else "en-GB"


def _test_instruction_for_type(question_type: Any, subject: Any, fallback: Any = "") -> str:
    qt = str(question_type or "").strip().lower()
    if _test_subject_is_russian(subject):
        mapping = {
            "grammar_rules": "Выберите правильное грамматическое правило.",
            "grammar_sentence": "Выберите правильный вариант для завершения предложения.",
            "find_mistake": "Найдите ошибку и выберите правильный вариант.",
            "error_spotting": "Определите, в какой части предложения есть ошибка.",
            "gap_filling": "Выберите правильный вариант для пропуска.",
            "definition": "Выберите правильное значение.",
            "translation": "Выберите правильный перевод.",
            "reading": "Прочитайте текст и выберите правильный ответ.",
            "multiple_choice": "Выберите правильный ответ.",
        }
    else:
        mapping = {
            "grammar_rules": "Choose the correct grammar rule.",
            "grammar_sentence": "Choose the correct option to complete the sentence.",
            "find_mistake": "Find the mistake and choose the correct version.",
            "error_spotting": "Identify which part of the sentence has the error.",
            "gap_filling": "Choose the best option for the gap.",
            "definition": "Choose the correct meaning.",
            "translation": "Choose the correct translation.",
            "reading": "Read the passage and choose the correct answer.",
            "multiple_choice": "Choose the correct answer.",
        }
    return mapping.get(qt) or str(fallback or "").strip() or mapping.get("multiple_choice", "Choose the correct answer.")


def _strip_test_instruction_prefix(prompt: Any, instruction: str) -> str:
    text = str(prompt or "").strip()
    if not text:
        return ""
    known = {
        _normalize_answer_text(instruction),
        "choose the correct grammar rule",
        "choose the correct option to complete the sentence",
        "find the mistake and choose the correct version",
        "identify which part of the sentence has the error",
        "choose the best option for the gap",
        "choose the correct meaning",
        "choose the correct translation",
        "choose the correct answer",
        "выберите правильное грамматическое правило",
        "выберите правильный вариант для завершения предложения",
        "найдите ошибку и выберите правильный вариант",
        "определите в какой части предложения есть ошибка",
        "выберите правильный вариант для пропуска",
        "выберите правильное значение",
        "выберите правильный перевод",
        "выберите правильный ответ",
    }
    lines = text.splitlines()
    if len(lines) > 1 and _normalize_answer_text(lines[0]) in known:
        return "\n".join(lines[1:]).strip() or text
    normalized_text = _normalize_answer_text(text)
    for item in sorted((x for x in known if x), key=len, reverse=True):
        if normalized_text == item:
            return ""
        if normalized_text.startswith(item + " "):
            original_words = len(item.split())
            parts = text.split()
            return " ".join(parts[original_words:]).strip() or text
    return text


