def _competition_enrich_reading_questions(rows: list[dict[str, Any]], subject: str, mode: str = "") -> list[dict[str, Any]]:
    if not rows:
        return rows
    subject_key = "Russian" if _test_subject_is_russian(subject) else "English"
    enriched = [dict(row) for row in rows]
    for row in enriched:
        payload = _safe_json_object(row.get("payload_json"))
        q = _mcq_question_from_row(row)
        qtype = str(payload.get("question_type") or q.get("question_type") or row.get("question_type") or "").strip().lower()
        passage = str(payload.get("passage") or q.get("passage") or "").strip()
        if qtype != "reading" or not passage:
            continue
        prompt = str(q.get("prompt") or q.get("question") or row.get("question") or "").strip()
        payload.update(
            {
                "question_type": "reading",
                "instruction": _test_instruction_for_type("reading", subject),
                "passage": passage,
                "question": prompt or ("Что лучше всего соответствует тексту?" if subject_key == "Russian" else "What is the best answer according to the passage?"),
                "prompt": prompt or ("Что лучше всего соответствует тексту?" if subject_key == "Russian" else "What is the best answer according to the passage?"),
                "options": q.get("options") or [
                    str(row.get("option_a") or ""),
                    str(row.get("option_b") or ""),
                    str(row.get("option_c") or ""),
                    str(row.get("option_d") or ""),
                ],
                "correct_option_index": int(q.get("correct_option_index") or row.get("correct_option_index") or 1),
                "subject": subject_key,
            }
        )
        row["question_type"] = "reading"
        row["question"] = payload["question"]
        row["payload_json"] = json.dumps(payload, ensure_ascii=False)
    return enriched


def _duel_enrich_reading_questions(rows: list[dict[str, Any]], subject: str) -> list[dict[str, Any]]:
    return _competition_enrich_reading_questions(rows, subject, "duel")


def _mcq_question_from_row(row: dict[str, Any]) -> dict[str, Any]:
    payload = _safe_json_object(_row_value(row, "payload_json"))
    qtype = str(payload.get("question_type") or _row_value(row, "question_type") or _row_value(row, "type") or "multiple_choice").strip().lower()
    if qtype not in TEST_MCQ_QUESTION_TYPES:
        qtype = "multiple_choice"
        payload = {}

    options = _safe_json_array(payload.get("options")) if payload else []
    if not options and isinstance(_row_value(row, "options"), list):
        options = [str(opt) for opt in (_row_value(row, "options") or [])]
    if not options:
        options = _safe_json_array(_row_value(row, "options_json"))
    if not options:
        options = [
            str(_row_value(row, "option_a", "") or ""),
            str(_row_value(row, "option_b", "") or ""),
            str(_row_value(row, "option_c", "") or ""),
            str(_row_value(row, "option_d", "") or ""),
        ]
    options = [str(opt) for opt in options if str(opt or "").strip()][:4]

    try:
        correct_idx = int(payload.get("correct_option_index") if payload else _row_value(row, "correct_option_index", 1))
    except Exception:
        correct_idx = 1
    correct_idx = max(1, min(4, correct_idx))

    prompt = str(payload.get("prompt") or payload.get("question") or _row_value(row, "prompt") or _row_value(row, "question") or "").strip()
    passage = str(payload.get("passage") or payload.get("reading_passage") or "").strip()
    if not passage and "passage:" in prompt.lower():
        parts = re.split(r"(?i)\bquestion\s*:", prompt, maxsplit=1)
        if len(parts) == 2:
            passage = re.sub(r"(?i)^\s*passage\s*:\s*", "", parts[0]).strip()
            prompt = parts[1].strip()
    return {
        "question_type": qtype,
        "subject": str(payload.get("subject") or _row_value(row, "subject") or "").strip(),
        "prompt": prompt,
        "question": prompt,
        "passage": passage,
        "instruction": str(payload.get("instruction") or "").strip(),
        "options": options,
        "correct_option_index": correct_idx,
        "correct": str(payload.get("correct") or _row_value(row, "correct") or "").strip(),
    }


def _public_question_payload(row: dict[str, Any], *, question_index: int | None = None) -> dict[str, Any]:
    q = _mcq_question_from_row(row)
    qtype = str(q.get("question_type") or "multiple_choice").strip().lower()
    subject = str(q.get("subject") or _row_value(row, "subject") or "").strip()
    instruction = _test_instruction_for_type(qtype, subject, q.get("instruction"))
    prompt_text = _strip_test_instruction_prefix(q.get("prompt") or q.get("question") or "", instruction)
    out: dict[str, Any] = {
        "question_type": qtype,
        "prompt": prompt_text,
        "instruction": instruction,
        "subject": subject,
        "options": [str(opt) for opt in (q.get("options") or [])][:4],
        "tts_language": _test_tts_language_for_subject(subject),
    }
    passage = str(q.get("passage") or "").strip()
    if passage:
        out["passage"] = passage
    # Expose per-question time limit (reading questions: 60-120 s; others: None / default)
    payload_raw = _safe_json_object(_row_value(row, "payload_json"))
    tls = payload_raw.get("time_limit_sec") or q.get("time_limit_sec")
    if tls is not None:
        try:
            out["time_limit_sec"] = max(10, int(tls))
        except Exception:
            pass
    if question_index is not None:
        out["question_index"] = int(question_index)
    return out


def _selected_option_is_correct(row_or_question: dict[str, Any], selected_index: int | None) -> bool:
    if selected_index is None:
        return False
    try:
        selected_idx = int(selected_index)
    except Exception:
        return False
    q = _mcq_question_from_row(row_or_question)
    options = [str(opt) for opt in (q.get("options") or [])]
    if selected_idx < 0 or selected_idx >= len(options):
        return False
    correct_idx = int(q.get("correct_option_index") or 1) - 1
    if 0 <= correct_idx < len(options) and selected_idx == correct_idx:
        return True
    correct_text = str(q.get("correct") or "").strip()
    return bool(correct_text) and str(options[selected_idx]).strip() == correct_text


def _get_seen_questions_for_users(user_ids: list[int], limit_sessions: int = 30) -> set[str]:
    if not user_ids:
        return set()
    conn = get_conn()
    cur = conn.cursor()
    try:
        # Get recent session IDs for these participants
        placeholders = ",".join("?" for _ in user_ids)
        cur.execute(
            f"""
            SELECT session_id 
            FROM web_competition_participants
            WHERE user_id IN ({placeholders})
            GROUP BY session_id
            ORDER BY MAX(joined_at) DESC
            LIMIT ?
            """,
            (*user_ids, limit_sessions)
        )
        session_ids = [str(dict(row).get("session_id") or "") for row in (cur.fetchall() or [])]
        session_ids = [sid for sid in session_ids if sid]
        if not session_ids:
            return set()
        
        # Load payloads for these sessions
        sess_placeholders = ",".join("?" for _ in session_ids)
        cur.execute(
            f"""
            SELECT payload_json 
            FROM web_competition_sessions
            WHERE session_id IN ({sess_placeholders})
            """,
            tuple(session_ids)
        )
        seen = set()
        for row in cur.fetchall() or []:
            payload = _safe_json_object(dict(row).get("payload_json"))
            if payload:
                questions = payload.get("questions") or []
                for q in questions:
                    q_text = str(q.get("question") or "").strip().lower()
                    if q_text:
                        seen.add(q_text)
        return seen
    except Exception:
        logger.exception("Failed to fetch seen questions for users: %s", user_ids)
        return set()
    finally:
        conn.close()


async def _runtime_generate_questions(
    *,
    created_by: int,
    subject: str,
    level: str,
    count: int = 10,
    mode: str = "",
    competition_session_id: str | None = None,
    require_fresh: bool = False,
) -> list[dict]:
    """Generate FRESH questions for a competition session via AI.

    Every call produces newly AI-generated questions — we never reuse existing
    bank rows from previous sessions. A timestamp anchor (start_ts) is captured
    before the AI call; only rows created after that moment are used.

    If require_fresh=True, the caller gets [] when AI cannot insert enough fresh
    rows. Otherwise the DB bank remains an explicit legacy fallback.
    """
    import random as _random

    safe_subject = _normalize_subject_label(subject) or "English"
    safe_level = str(level or "PRE-INTERMEDIATE").strip().upper()
    if safe_level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1", "MIXED"}:
        safe_level = "PRE-INTERMEDIATE"

    # Collect participant user IDs for the seen-questions deduplication pass
    user_ids: list[int] = []
    if competition_session_id:
        sess = _competition_load_session_from_db(competition_session_id)
        if sess:
            participants = sess.get("participants") or []
            user_ids = [int(p.get("user_id") or 0) for p in participants if int(p.get("user_id") or 0) > 0]
    if not user_ids and created_by:
        user_ids = [int(created_by)]

    seen_questions = _get_seen_questions_for_users(user_ids)

    target_count = max(1, int(count))

    # ── Step 1: Record timestamp BEFORE generation ──────────────────────────
    # Anything inserted after this moment belongs to THIS session only.
    start_ts = _now_utc()

    rows = []
    attempts = 0
    max_attempts = 3

    while len(rows) < target_count and attempts < max_attempts:
        attempts += 1
        needed = target_count - len(rows)
        # Add a small buffer of 2 to over-request from Gemini and offset duplicates
        req_count = needed + 2

        # Combine seen_questions with questions we just generated in this loop
        current_seen = set(seen_questions)
        for r in rows:
            q_txt = str(r.get("question") or "").strip().lower()
            if q_txt:
                current_seen.add(q_txt)

        await generate_daily_tests_and_insert(
            subject=safe_subject,
            level=safe_level,
            count=req_count,
            created_by=int(created_by),
            assign_today_set=False,
            exclude_questions=list(current_seen),
        )

        # Query what was actually inserted in this window
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT subject, question, option_a, option_b, option_c, option_d,
                       correct_option_index, question_type, payload_json
                FROM daily_tests_bank
                WHERE created_by=? AND subject=? AND level=? AND active=1
                  AND created_at >= ?
                ORDER BY id ASC
                """,
                (int(created_by), safe_subject, safe_level, start_ts.isoformat()),
            )
            rows = [dict(r) for r in (cur.fetchall() or [])]
        finally:
            conn.close()

    if len(rows) >= target_count:
        _random.shuffle(rows)
        rows = rows[:target_count]

        # ── Inject 2-3 reading questions with passages ───────────────────────
        # Only for sessions with 5+ questions (duel/arena/group/boss).
        # Reading questions replace the last N regular MCQs so total stays the same.
        if target_count >= 5 and mode not in ("", "daily"):
            reading_count = 3 if target_count >= 10 else 2
            try:
                from ai_generator import _generate_reading_questions_with_passage
                reading_qs = await _generate_reading_questions_with_passage(
                    subject=safe_subject,
                    level=safe_level,
                    count=reading_count,
                )
                if reading_qs:
                    actual_rc = len(reading_qs)
                    # Replace last `actual_rc` regular questions with reading questions
                    rows = rows[: target_count - actual_rc] + reading_qs
                    _random.shuffle(rows)
                    logger.info(
                        "_runtime_generate_questions: injected %d reading question(s) "
                        "into %d-question set (subject=%s level=%s mode=%s)",
                        actual_rc, target_count, safe_subject, safe_level, mode,
                    )
            except Exception as _reading_err:
                logger.warning(
                    "_runtime_generate_questions: reading injection failed (%s) — "
                    "returning plain MCQ set",
                    _reading_err,
                )
        # ─────────────────────────────────────────────────────────────────────

        return rows

    # If we still don't have enough questions and require_fresh is True:
    # Instead of returning [] (which aborts the duel), let's fill the remaining
    # slots from the existing bank questions (avoiding duplicates) so the duel can start!
    if require_fresh:
        needed = target_count - len(rows)
        logger.warning(
            "_runtime_generate_questions: only got %d/%d fresh questions after %d attempts. Filling remaining %d slots from bank.",
            len(rows), target_count, attempts, needed
        )
        # Fetch from bank
        fallback = _safe_call(lambda: get_tests_by_subject(safe_subject), []) or []
        _random.shuffle(fallback)

        # Exclude seen_questions and already generated questions
        current_seen = set(seen_questions)
        for r in rows:
            q_txt = str(r.get("question") or "").strip().lower()
            if q_txt:
                current_seen.add(q_txt)

        filtered = [q for q in fallback if str(q.get("question") or "").strip().lower() not in current_seen]
        pool = filtered if len(filtered) >= needed else fallback

        for row in pool[:needed]:
            rows.append({
                "question": str(row.get("question") or "").strip(),
                "subject": safe_subject,
                "option_a": str(row.get("option_a") or "").strip(),
                "option_b": str(row.get("option_b") or "").strip(),
                "option_c": str(row.get("option_c") or "").strip(),
                "option_d": str(row.get("option_d") or "").strip(),
                "correct_option_index": int(row.get("correct_option_index") or 1),
            })

        if len(rows) >= target_count:
            return rows[:target_count]
        return []

    # ── Step 3: Absolute last-resort fallback (AI completely failed) ─────────
    # Only reached when generate_daily_tests_and_insert returned 0 inserts.
    logger.warning(
        "_runtime_generate_questions AI returned 0 inserts subject=%s level=%s mode=%s — falling back to bank",
        safe_subject, safe_level, mode,
    )
    fallback = _safe_call(lambda: get_tests_by_subject(safe_subject), []) or []
    _random.shuffle(fallback)
    filtered = [q for q in fallback if str(q.get("question") or "").strip().lower() not in seen_questions]
    pool = filtered if len(filtered) >= target_count else fallback

    mapped = []
    for row in pool[:target_count]:
        mapped.append({
            "question": str(row.get("question") or "").strip(),
            "subject": safe_subject,
            "option_a": str(row.get("option_a") or "").strip(),
            "option_b": str(row.get("option_b") or "").strip(),
            "option_c": str(row.get("option_c") or "").strip(),
            "option_d": str(row.get("option_d") or "").strip(),
            "correct_option_index": int(row.get("correct_option_index") or 1),
        })
    return mapped


def _competition_theme(mode: str) -> str:
    themes = {
        "daily": ["daily-ignite", "daily-glow", "daily-velocity"],
        "group": ["group-alliance", "group-pulse", "group-crest"],
        "boss": ["boss-storm", "boss-crown", "boss-volt"],
        "duel-1v1": ["duel-flare", "duel-sharp", "duel-mirror"],
        "duel-3v3": ["duel-squad", "duel-trio", "duel-impact"],
        "duel-5v5": ["duel-warband", "duel-legion", "duel-forge"],
    }
    pool = themes.get(mode, ["core"])
    day_seed = int(datetime.now(TASHKENT_TZ).strftime("%Y%m%d"))
    return pool[day_seed % len(pool)]


def _normalize_lesson_days(value: str | None) -> str | None:
    raw = str(value or "").strip().upper()
    if not raw:
        return None
    aliases = {
        "MWF": "MWF",
        "MON/WED/FRI": "MWF",
        "MON,WED,FRI": "MWF",
        "TTS": "TTS",
        "TUE/THU/SAT": "TTS",
        "TUE,THU,SAT": "TTS",
    }
    return aliases.get(raw)


def _teacher_subject_choices(teacher_row: dict | None) -> list[str]:
    if not teacher_row:
        return []
    return _normalize_subjects(_user_subjects_from_row(teacher_row), fallback=[])


def _normalize_subject_label(value: str | None) -> str | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    low = raw.lower()
    if low in {"english", "eng", "ingliz", "en"}:
        return "English"
    if low in {"russian", "rus", "ru", "русский", "russian language"}:
        return "Russian"
    if low in {"matematika", "math", "mathematics"}:
        return "Matematika"
    if low in {"ona tili"}:
        return "Ona tili"
    if low in {"tarix", "history"}:
        return "Tarix"
    if low in {"arab tili", "arabic"}:
        return "Arab tili"
    return None


GROUP_SUBJECTS: tuple[dict[str, Any], ...] = (
    {"id": 1, "code": "English", "title": "English"},
    {"id": 2, "code": "Russian", "title": "Russian"},
    {"id": 3, "code": "Matematika", "title": "Matematika"},
    {"id": 4, "code": "Ona tili", "title": "Ona tili"},
    {"id": 5, "code": "Tarix", "title": "Tarix"},
    {"id": 6, "code": "Arab tili", "title": "Arab tili"},
)
GROUP_SUBJECT_ID_TO_CODE = {int(item["id"]): str(item["code"]) for item in GROUP_SUBJECTS}
GROUP_SUBJECT_CODE_TO_ID = {str(item["code"]).lower(): int(item["id"]) for item in GROUP_SUBJECTS}


def _resolve_group_subject_input(subject: str | None, subject_id: int | None) -> str:
    """
    Resolve subject from either explicit label or numeric subject_id.
    This keeps backward compatibility (`subject`) while allowing strict subject_id validation.
    """
    resolved_from_id: str | None = None
    if subject_id is not None:
        resolved_from_id = GROUP_SUBJECT_ID_TO_CODE.get(int(subject_id))
        if not resolved_from_id:
            allowed_ids = ", ".join(str(item["id"]) for item in GROUP_SUBJECTS)
            raise HTTPException(status_code=400, detail=f"Invalid subject_id. Allowed values: {allowed_ids}")
    normalized_subject = _normalize_subject_label(subject)
    if resolved_from_id and normalized_subject and normalized_subject != resolved_from_id:
        raise HTTPException(status_code=400, detail="subject and subject_id mismatch")
    final_subject = normalized_subject or resolved_from_id
    if not final_subject:
        raise HTTPException(status_code=400, detail="subject or subject_id is required")
    if final_subject.lower() not in GROUP_SUBJECT_CODE_TO_ID:
        raise HTTPException(status_code=400, detail="Invalid subject value")
    return final_subject


def _validate_group_teacher_and_subject(teacher_id: int, subject: str | None) -> tuple[dict, str]:
    teacher = _safe_call(lambda: get_user_by_id(int(teacher_id)), None)
    if not teacher or (int(teacher.get("login_type") or 0) != 3 and teacher.get("role") != "teacher"):
        raise HTTPException(status_code=400, detail="teacher_id must reference an existing teacher account")
    teacher_subjects = _teacher_subject_choices(teacher) or ["English"]
    normalized_subject = _normalize_subject_label(subject) or teacher_subjects[0]
    return teacher, normalized_subject


def _normalize_subjects(values: list[str] | None, fallback: list[str] | None = None) -> list[str]:
    clean: list[str] = []
    for raw in values or []:
        val = _normalize_subject_label(raw)
        if val and val not in clean:
            clean.append(val)
    if clean:
        return clean
    if fallback is not None:
        fallback_clean: list[str] = []
        for raw in fallback:
            val = _normalize_subject_label(raw)
            if val and val not in fallback_clean:
                fallback_clean.append(val)
        return fallback_clean
    return ["English"]


def _normalize_attendance_status(value: str | None) -> str:
    raw = str(value or "").strip().lower()
    if raw in {"keldi", "present", "late"}:
        return "Keldi"
    if raw in {"sababli", "excused", "reasoned"}:
        return "Sababli"
    if raw in {"sababsiz", "absent", "unexcused"}:
        return "Sababsiz"
    return "Keldi"


def is_excused_attendance(status: str | None) -> bool:
    raw = str(status or "").strip().lower()
    if not raw:
        return False
    normalized = re.sub(r"[\s_-]+", "", raw)
    return normalized in {
        "sababli",
        "excused",
        "reasoned",
        "sababliabsent",
        "excusedabsent",
        "reasonedabsent",
    }


def _attendance_delta_dpoints(user_id: int, normalized_status: str) -> float:
    settings = _get_runtime_settings()
    if normalized_status == "Keldi":
        return float(settings.get("attendance_keldi_dpoints") or 5.0)
    if normalized_status == "Sababsiz":
        return -10.0
    return 0.0


def _sync_attendance_effect(
    user_id: int,
    group_id: int,
    date: str,
    normalized_status: str,
    subject_hint: str | None = None,
) -> dict[str, Any]:
    before_dpoints = float(get_dpoints(int(user_id)))
    before_dcoins = float(get_dcoins(int(user_id)))
    prev = get_attendance_effect(int(user_id), int(group_id), str(date)) or {}
    prev_status = _normalize_attendance_status(str(prev.get("status") or "")) if prev else None
    prev_delta = float(prev.get("delta_dpoints") or 0)
    if prev and prev_status == normalized_status:
        return {
            "applied": False,
            "noop_reason": "same_status",
            "status": normalized_status,
            "previous_status": prev_status,
            "applied_delta_dpoints": 0.0,
            "status_effect_dpoints": float(prev_delta),
            "previous_effect_dpoints": float(prev_delta),
            "before_dpoints": float(before_dpoints),
            "after_dpoints": float(before_dpoints),
            "before_dcoins": float(before_dcoins),
            "after_dcoins": float(before_dcoins),
        }

    applied_delta = 0.0
    if prev_delta:
        add_dpoints(int(user_id), -prev_delta, subject=subject_hint, change_type="attendance_reverse")
        applied_delta -= float(prev_delta)
    next_delta = _attendance_delta_dpoints(int(user_id), normalized_status)
    if next_delta:
        add_dpoints(int(user_id), next_delta, subject=subject_hint, change_type="attendance_mark")
        applied_delta += float(next_delta)
    set_attendance_effect(int(user_id), int(group_id), str(date), normalized_status, float(next_delta))
    after_dpoints = float(get_dpoints(int(user_id)))
    after_dcoins = float(get_dcoins(int(user_id)))
    return {
        "applied": True,
        "noop_reason": None,
        "status": normalized_status,
        "previous_status": prev_status,
        "applied_delta_dpoints": float(applied_delta),
        "status_effect_dpoints": float(next_delta),
        "previous_effect_dpoints": float(prev_delta),
        "before_dpoints": float(before_dpoints),
        "after_dpoints": float(after_dpoints),
        "before_dcoins": float(before_dcoins),
        "after_dcoins": float(after_dcoins),
    }


def _validate_branch_key(branch: str | None) -> str:
    key = str(branch or "").strip().lower()
    if key not in SUPPORT_BRANCHES:
        raise HTTPException(status_code=400, detail="Invalid branch. Allowed: branch_1, branch_2")
    return key


def _validate_iso_date(date_iso: str | None) -> str:
    raw = str(date_iso or "").strip()
    try:
        datetime.strptime(raw, "%Y-%m-%d")
    except Exception:
        raise HTTPException(status_code=400, detail="date must be in YYYY-MM-DD format")
    return raw


def _weekday_short_name(date_iso: str) -> str:
    try:
        d = datetime.strptime(date_iso, "%Y-%m-%d").date()
        return ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][d.weekday()]
    except Exception:
        return ""


def _support_actor_subjects(user: dict) -> list[str]:
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role == "admin":
        return list(ALLOWED_SUBJECTS)
    if role != "support":
        return []
    subjects = [item for item in _user_subjects_from_row(user) if _normalize_subject_label(item) in ALLOWED_SUBJECTS]
    deduped: list[str] = []
    for subject in subjects:
        normalized = _normalize_subject_label(subject)
        if normalized and normalized not in deduped:
            deduped.append(normalized)
    return deduped


def _require_support_subject_access(user: dict, subject: str | None) -> str:
    normalized = _normalize_subject_label(subject)
    if not normalized or normalized not in ALLOWED_SUBJECTS:
        raise HTTPException(status_code=400, detail="Invalid support subject")
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role == "admin":
        return normalized
    if role != "support":
        raise HTTPException(status_code=403, detail="Permission denied")
    if normalized not in _support_actor_subjects(user):
        raise HTTPException(status_code=403, detail="Sizda bu fan bo'yicha support booking sozlamalarini o'zgartirish huquqi yo'q")
    return normalized


def _active_support_teacher_rows_for_subject(subject: str | None) -> list[dict]:
    normalized = _normalize_subject_label(subject)
    if not normalized:
        return []
    rows: list[dict] = []
    scheduled_teacher_ids = _support_teacher_ids_with_active_schedule(normalized)
    for row in _active_support_teacher_rows_cached():
        teacher_id = int(row.get("id") or 0)
        if normalized in _normalize_subjects(_user_subjects_from_row(row), fallback=[]) or teacher_id in scheduled_teacher_ids:
            rows.append(dict(row))
    rows.sort(key=lambda item: int(item.get("id") or 0))
    return rows


def _support_branch_weekday_sets() -> dict[str, set[int]]:
    return {
        "branch_1": set(get_lesson_branch_weekdays("branch_1")),
        "branch_2": set(get_lesson_branch_weekdays("branch_2")),
    }


def _default_support_branch_for_weekday(weekday: int, branch_weekdays: dict[str, set[int]] | None = None) -> str:
    wd = int(weekday)
    branch_weekdays = branch_weekdays or _support_branch_weekday_sets()
    for branch_key in ("branch_1", "branch_2"):
        if wd in set(branch_weekdays.get(branch_key) or set()):
            return branch_key
    return "branch_1"


def _support_weekday_settings_for_teacher(support_teacher_id: int, subject: str) -> list[dict]:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM support_teacher_weekday_settings
            WHERE support_teacher_id=? AND subject=?
            """,
            (int(support_teacher_id), str(subject)),
        )
        existing = {int(row.get("weekday") or 0): dict(row) for row in (cur.fetchall() or [])}
    except Exception:
        existing = {}
    finally:
        conn.close()
    rows: list[dict] = []
    branch_weekdays = _support_branch_weekday_sets()
    for weekday in range(0, 6):
        fallback_branch = _default_support_branch_for_weekday(weekday, branch_weekdays)
        row = existing.get(weekday) or {}
        rows.append(
            {
                "support_teacher_id": int(support_teacher_id),
                "subject": subject,
                "weekday": weekday,
                "active": bool(int(row.get("active") if row.get("active") is not None else 1)),
                "branch": str(row.get("branch") or fallback_branch),
                "updated_at": row.get("updated_at"),
            }
        )
    return rows


def _support_weekday_settings_map(support_teacher_ids: list[int], subject: str) -> dict[int, list[dict]]:
    ids = sorted({int(item) for item in support_teacher_ids if int(item or 0) > 0})
    if not ids:
        return {}
    existing: dict[tuple[int, int], dict] = {}
    placeholders = ",".join("?" for _ in ids)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT *
            FROM support_teacher_weekday_settings
            WHERE subject=? AND support_teacher_id IN ({placeholders})
            """,
            [subject, *ids],
        )
        for row in (cur.fetchall() or []):
            existing[(int(row.get("support_teacher_id") or 0), int(row.get("weekday") or 0))] = dict(row)
    except Exception:
        existing = {}
    finally:
        conn.close()

    out: dict[int, list[dict]] = {}
    branch_weekdays = _support_branch_weekday_sets()
    for support_teacher_id in ids:
        teacher_rows: list[dict] = []
        for weekday in range(0, 6):
            fallback_branch = _default_support_branch_for_weekday(weekday, branch_weekdays)
            row = existing.get((support_teacher_id, weekday)) or {}
            teacher_rows.append(
                {
                    "support_teacher_id": support_teacher_id,
                    "subject": subject,
                    "weekday": weekday,
                    "active": bool(int(row.get("active") if row.get("active") is not None else 1)),
                    "branch": str(row.get("branch") or fallback_branch),
                    "updated_at": row.get("updated_at"),
                }
            )
        out[support_teacher_id] = teacher_rows
    return out


def _support_weekday_setting_for_teacher(support_teacher_id: int, subject: str, weekday: int) -> dict:
    rows = _support_weekday_settings_for_teacher(int(support_teacher_id), subject)
    return next((row for row in rows if int(row.get("weekday") or -1) == int(weekday)), {})


def _upsert_support_weekday_setting(
    support_teacher_id: int,
    subject: str,
    weekday: int,
    *,
    active: bool,
    branch: str | None = None,
    updated_by: int | None = None,
) -> None:
    branch_key = _validate_branch_key(branch or _default_support_branch_for_weekday(int(weekday)))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO support_teacher_weekday_settings(support_teacher_id, subject, weekday, active, branch, updated_by, updated_at)
            VALUES (?,?,?,?,?,?,CURRENT_TIMESTAMP)
            ON CONFLICT(support_teacher_id, subject, weekday)
            DO UPDATE SET active=excluded.active, branch=excluded.branch, updated_by=excluded.updated_by, updated_at=CURRENT_TIMESTAMP
            """,
            (int(support_teacher_id), subject, int(weekday), 1 if active else 0, branch_key, updated_by),
        )
        conn.commit()
    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        raise HTTPException(status_code=500, detail="Could not save support schedule") from exc
    finally:
        conn.close()


def _support_teacher_date_override(support_teacher_id: int, subject: str, date_iso: str) -> dict | None:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM support_teacher_date_overrides
            WHERE support_teacher_id=? AND subject=? AND date=?
            LIMIT 1
            """,
            (int(support_teacher_id), subject, date_iso),
        )
        row = cur.fetchone()
        return dict(row) if row else None
    except Exception:
        return None
    finally:
        conn.close()


def _support_teacher_date_overrides_map(support_teacher_ids: list[int], subject: str, dates: list[str]) -> dict[tuple[int, str], dict]:
    ids = sorted({int(item) for item in support_teacher_ids if int(item or 0) > 0})
    clean_dates = sorted({str(item) for item in dates if item})
    if not ids or not clean_dates:
        return {}
    teacher_placeholders = ",".join("?" for _ in ids)
    date_placeholders = ",".join("?" for _ in clean_dates)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT *
            FROM support_teacher_date_overrides
            WHERE subject=?
              AND support_teacher_id IN ({teacher_placeholders})
              AND date IN ({date_placeholders})
            """,
            [subject, *ids, *clean_dates],
        )
        return {
            (int(row.get("support_teacher_id") or 0), str(row.get("date") or "")): dict(row)
            for row in (cur.fetchall() or [])
        }
    except Exception:
        return {}
    finally:
        conn.close()


def _support_holiday_dates(dates: list[str]) -> set[str]:
    clean_dates = sorted({str(item) for item in dates if item})
    if not clean_dates:
        return set()
    placeholders = ",".join("?" for _ in clean_dates)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"SELECT date FROM lesson_holidays WHERE date IN ({placeholders})",
            clean_dates,
        )
        return {str(row.get("date") or "") for row in (cur.fetchall() or []) if row.get("date")}
    except Exception:
        return set()
    finally:
        conn.close()


def _support_branch_closed_reasons_map(branch: str, dates: list[str]) -> dict[str, str]:
    clean_dates = sorted({str(item) for item in dates if item})
    if not clean_dates:
        return {}
    placeholders = ",".join("?" for _ in clean_dates)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT date, branch, reason
            FROM lesson_branch_date_closed
            WHERE date IN ({placeholders})
              AND (branch=? OR branch='all')
            ORDER BY date ASC, CASE WHEN branch='all' THEN 1 ELSE 0 END ASC
            """,
            [*clean_dates, str(branch)],
        )
        out: dict[str, str] = {}
        for row in (cur.fetchall() or []):
            date_key = str(row.get("date") or "")
            if date_key and date_key not in out:
                out[date_key] = str(row.get("reason") or "").strip() or "Booking yopiq"
        return out
    except Exception:
        return {}
    finally:
        conn.close()


