def _has_active_web_sessions(user_id: int) -> bool:
    uid = int(user_id or 0)
    if uid <= 0:
        return False
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT 1
            FROM web_user_sessions
            WHERE user_id=?
              AND revoked_at IS NULL
              AND expires_at > ?
            LIMIT 1
            """,
            (uid, _now_utc().isoformat()),
        )
        return cur.fetchone() is not None
    except Exception:
        return False
    finally:
        conn.close()


def _extract_qr_token(raw_value: str | None) -> str:
    raw = str(raw_value or "").strip()
    if not raw:
        return ""
    try:
        parsed_json = json.loads(raw)
        if isinstance(parsed_json, dict):
            candidate = str(parsed_json.get("qr_token") or parsed_json.get("token") or "").strip()
            if candidate:
                return candidate
    except Exception:
        pass

    if "://" in raw:
        parsed_url = urlparse(raw)
        query = parse_qs(parsed_url.query or "")
        for key in ("qr_token", "token"):
            values = query.get(key) or []
            if values and str(values[0] or "").strip():
                return str(values[0]).strip()
    if "qr_token=" in raw.lower():
        parsed_query = parse_qs(raw.split("?", 1)[-1])
        values = parsed_query.get("qr_token") or []
        if values and str(values[0] or "").strip():
            return str(values[0]).strip()
    token_match = re.search(r"(qr_[A-Za-z0-9_-]{16,})", raw)
    if token_match:
        return str(token_match.group(1) or "").strip()
    return raw


def _generate_qr_login_token(user_id: int, ttl_seconds: int = WEB_QR_LOGIN_TTL_SECONDS) -> dict[str, str]:
    uid = int(user_id or 0)
    if uid <= 0:
        raise HTTPException(status_code=404, detail="User not found")
    qr_token = f"qr_{secrets.token_urlsafe(28)}"
    expires_at = (_now_utc() + timedelta(seconds=max(60, int(ttl_seconds or WEB_QR_LOGIN_TTL_SECONDS)))).isoformat()
    qr_payload = f"diamond://login?qr_token={quote(qr_token)}"
    conn = get_conn()
    cur = conn.cursor()
    try:
        # Keep only recent, unused tokens for cleaner lookups.
        cur.execute(
            """
            DELETE FROM web_qr_login_tokens
            WHERE user_id=?
              AND (used_at IS NOT NULL OR expires_at<?)
            """,
            (uid, _now_utc().isoformat()),
        )
        cur.execute(
            """
            INSERT INTO web_qr_login_tokens
            (
                qr_token,
                user_id,
                qr_payload,
                expires_at,
                created_at
            )
            VALUES (?, ?, ?, ?, ?)
            """,
            (qr_token, uid, qr_payload, expires_at, _now_utc().isoformat()),
        )
        conn.commit()
    finally:
        conn.close()
    return {
        "qr_token": qr_token,
        "qr_payload": qr_payload,
        "expires_at": expires_at,
    }


def _consume_qr_login_token(raw_token: str, used_device_id: str | None = None) -> dict:
    token = _extract_qr_token(raw_token)
    if not token:
        raise HTTPException(status_code=400, detail="QR token is required")
    conn = get_conn()
    cur = conn.cursor()
    now = _now_utc()
    now_iso = now.isoformat()
    try:
        cur.execute("SELECT * FROM web_qr_login_tokens WHERE qr_token=? LIMIT 1", (token,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=401, detail="QR token is invalid or expired")
        item = dict(row)
        if str(item.get("used_at") or "").strip():
            raise HTTPException(status_code=409, detail="QR token is already used")
        expires_at = _parse_utc_timestamp(str(item.get("expires_at") or ""))
        if expires_at is None or expires_at <= now:
            raise HTTPException(status_code=401, detail="QR token is invalid or expired")
        cur.execute(
            """
            UPDATE web_qr_login_tokens
            SET used_at=?,
                used_by_device_id=?
            WHERE id=?
              AND used_at IS NULL
            """,
            (now_iso, str(used_device_id or "").strip() or None, int(item.get("id") or 0)),
        )
        if int(cur.rowcount or 0) <= 0:
            raise HTTPException(status_code=409, detail="QR token is already used")
        conn.commit()
    finally:
        conn.close()
    user = _safe_call(lambda: get_user_by_id(int(item.get("user_id") or 0)), None)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user


def _apply_web_login_policy(user: dict, device_id: str | None) -> dict:
    if not user:
        return user
    uid = int(user.get("id") or 0)
    if uid <= 0:
        return user
    device = str(device_id or "").strip()
    if not device:
        return user
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE users
            SET active_device_id=?
            WHERE id=?
            """,
            (device, uid),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        conn.close()
    refreshed = _safe_call(lambda: get_user_by_id(uid), None)
    return refreshed or user


def _create_access_token(
    user: dict,
    telegram_id: int | str | None = None,
    session_id: str | None = None,
    ttl_hours: int = WEB_SESSION_TOKEN_TTL_HOURS,
) -> str:
    payload = _build_user_payload(user)
    session_version = int(user.get("session_version") or 1)
    token_payload = {
        "sub": str(payload.id),
        "role": payload.role,
        "login_type": payload.login_type,
        "login_id": payload.login_id,
        "sv": session_version,
        "exp": _now_utc() + timedelta(hours=int(ttl_hours)),
    }
    sid = str(session_id or "").strip()
    if sid:
        token_payload["sid"] = sid
    if telegram_id is not None:
        token_payload["telegram_id"] = str(telegram_id)
    return jwt.encode(token_payload, SECRET_KEY, algorithm=ALGORITHM)


def _telegram_bot_tokens() -> list[str]:
    candidates = [
        os.getenv("TELEGRAM_BOT_TOKEN"),
        os.getenv("STUDENT_BOT_TOKEN"),
        os.getenv("ADMIN_BOT_TOKEN"),
        os.getenv("TEACHER_BOT_TOKEN"),
        os.getenv("SUPPORT_BOT_TOKEN"),
        os.getenv("DIAMOND_TELEGRAM_BOT_TOKEN"),
        os.getenv("BOT_TOKEN"),
    ]
    tokens: list[str] = []
    seen: set[str] = set()
    for raw in candidates:
        token = str(raw or "").strip()
        if token and token not in seen:
            seen.add(token)
            tokens.append(token)
    return tokens


def _parse_and_validate_telegram_init_data(init_data: str | None, expected_telegram_id: int) -> dict:
    bot_tokens = _telegram_bot_tokens()
    if not bot_tokens:
        return {}
    if not init_data:
        raise HTTPException(status_code=401, detail="Telegram initData is required")

    pairs = dict(parse_qsl(init_data, keep_blank_values=True))
    received_hash = pairs.pop("hash", None)
    if not received_hash:
        raise HTTPException(status_code=401, detail="Telegram initData hash is missing")

    data_check_string = "\n".join(f"{key}={value}" for key, value in sorted(pairs.items()))
    signature_valid = False
    for bot_token in bot_tokens:
        secret_key = hmac.new(b"WebAppData", bot_token.encode("utf-8"), hashlib.sha256).digest()
        calculated_hash = hmac.new(secret_key, data_check_string.encode("utf-8"), hashlib.sha256).hexdigest()
        if hmac.compare_digest(calculated_hash, received_hash):
            signature_valid = True
            break
    if not signature_valid:
        raise HTTPException(status_code=401, detail="Telegram initData signature is invalid")

    auth_date = pairs.get("auth_date")
    max_age = int(os.getenv("TELEGRAM_INIT_DATA_MAX_AGE_SECONDS", "86400"))
    if auth_date and max_age > 0:
        try:
            if _now_utc().timestamp() - int(auth_date) > max_age:
                raise HTTPException(status_code=401, detail="Telegram initData expired")
        except ValueError as exc:
            raise HTTPException(status_code=401, detail="Telegram auth_date is invalid") from exc

    try:
        tg_user = json.loads(pairs.get("user") or "{}")
    except json.JSONDecodeError:
        tg_user = {}
    if int(tg_user.get("id") or 0) != int(expected_telegram_id):
        raise HTTPException(status_code=401, detail="Telegram user mismatch")
    return tg_user


def _env_admin_label_for_telegram_id(telegram_id: int | str) -> str | None:
    try:
        tg = int(telegram_id or 0)
    except Exception:
        return None
    if tg <= 0:
        return None
    main_ids = [int(x) for x in (ADMIN_CHAT_IDS or []) if int(x or 0) > 0]
    limited_ids = [int(x) for x in (LIMITED_ADMIN_CHAT_IDS or []) if int(x or 0) > 0]
    if tg in main_ids:
        index = main_ids.index(tg)
        return f"main_admin_{min(index + 1, 2)}"
    if tg in limited_ids:
        index = limited_ids.index(tg)
        return f"limited_admin_{min(index + 1, 2)}"
    return None


def _telegram_id_is_env_admin(telegram_id: int | str | None) -> bool:
    return _env_admin_label_for_telegram_id(telegram_id or 0) is not None


def _resolve_env_admin_user_for_telegram(telegram_id: int | str) -> dict | None:
    """Env admin Telegram IDs always win over stale DB telegram_id collisions."""
    label = _env_admin_label_for_telegram_id(telegram_id)
    if not label:
        return None
    try:
        rows = set_standard_admin_account_credentials()
    except Exception:
        logger.exception("Could not ensure env admin credentials for telegram_id=%s", telegram_id)
        return None
    selected = next((row for row in rows if str(row.get("label") or "") == label), None) or (rows[0] if rows else None)
    admin_user_id = int((selected or {}).get("id") or 0)
    if admin_user_id <= 0:
        return None
    tg = str(int(telegram_id or 0))
    conn = get_conn()
    cur = conn.cursor()
    try:
        # Clear stale student/teacher collisions first so the UNIQUE telegram_id
        # constraint cannot route an env admin to the wrong account.
        cur.execute("UPDATE users SET telegram_id=NULL WHERE telegram_id=? AND id<>?", (tg, admin_user_id))
        cur.execute(
            """
            UPDATE users
            SET telegram_id=?,
                login_type=4,
                blocked=0,
                access_enabled=1
            WHERE id=?
            """,
            (tg, admin_user_id),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("Could not bind env admin telegram_id=%s to user_id=%s", tg, admin_user_id)
        return None
    finally:
        conn.close()
    _clear_auth_caches_for_user(admin_user_id)
    return _safe_call(lambda: get_user_by_id(admin_user_id), None)


def _decode_bearer_payload(authorization: str | None) -> dict:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="Not authenticated")
    token = authorization.split(" ", 1)[1].strip()
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except Exception as exc:
        raise HTTPException(status_code=401, detail="Invalid token") from exc


def _auth_user_row_cached(user_id: int, ttl_seconds: float = 8.0) -> dict | None:
    uid = int(user_id or 0)
    if uid <= 0:
        return None
    now_ts = time.time()
    cached = _AUTH_USER_BY_ID_CACHE.get(uid)
    if cached and cached[0] > now_ts:
        return dict(cached[1])
    row = _safe_call(lambda: get_user_by_id(uid), None)
    if row:
        _AUTH_USER_BY_ID_CACHE[uid] = (now_ts + max(1.0, float(ttl_seconds)), dict(row))
        if len(_AUTH_USER_BY_ID_CACHE) > 10000:
            for cached_uid, (expires_at, _) in list(_AUTH_USER_BY_ID_CACHE.items()):
                if expires_at <= now_ts:
                    _AUTH_USER_BY_ID_CACHE.pop(cached_uid, None)
    return row


def _validate_web_session_cached(sid: str, user_id: int, ttl_seconds: float = 5.0) -> None:
    session_id = str(sid or "").strip()
    uid = int(user_id or 0)
    if not session_id or uid <= 0:
        raise HTTPException(status_code=401, detail="Session expired. Please login again")
    now_ts = time.time()
    cache_key = (uid, session_id)
    cached = _AUTH_SESSION_VALIDATION_CACHE.get(cache_key)
    if cached and cached[0] > now_ts:
        cached_expires = cached[1]
        if cached_expires is not None and cached_expires > _now_utc():
            return
        _AUTH_SESSION_VALIDATION_CACHE.pop(cache_key, None)

    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT session_id, expires_at, revoked_at
            FROM web_user_sessions
            WHERE session_id=?
              AND user_id=?
            LIMIT 1
            """,
            (session_id, uid),
        )
        session_row = cur.fetchone()
        if not session_row:
            raise HTTPException(status_code=401, detail="Session expired. Please login again")
        session_dict = dict(session_row)
        if str(session_dict.get("revoked_at") or "").strip():
            raise HTTPException(status_code=401, detail="Session expired. Please login again")
        expires_at = _parse_utc_timestamp(str(session_dict.get("expires_at") or ""))
        if expires_at is None or expires_at <= _now_utc():
            raise HTTPException(status_code=401, detail="Session expired. Please login again")
        ttl = min(max(1.0, float(ttl_seconds)), max(0.0, expires_at.timestamp() - now_ts))
        if ttl > 0:
            _AUTH_SESSION_VALIDATION_CACHE[cache_key] = (now_ts + ttl, expires_at)
            if len(_AUTH_SESSION_VALIDATION_CACHE) > 10000:
                for key, (cached_until, _) in list(_AUTH_SESSION_VALIDATION_CACHE.items()):
                    if cached_until <= now_ts:
                        _AUTH_SESSION_VALIDATION_CACHE.pop(key, None)
    finally:
        conn.close()


_AUTH_USER_ROW_CACHE: dict[str, tuple[float, dict]] = {}
_AUTH_USER_BY_ID_CACHE: dict[int, tuple[float, dict]] = {}
_AUTH_SESSION_VALIDATION_CACHE: dict[tuple[int, str], tuple[float, datetime | None]] = {}
_USER_PAYLOAD_CACHE: dict[tuple[Any, ...], tuple[float, User]] = {}
_WEB_SESSION_TOUCH_CACHE: dict[str, float] = {}
_STUDENT_GROUP_ACCESS_CACHE: dict[int, tuple[float, bool]] = {}
_APP_STATE_BOOT_CACHE: dict[tuple[int, str, str, str], tuple[float, dict[str, Any]]] = {}
_APP_STATE_ECONOMY_CACHE: tuple[float, dict[str, Any]] | None = None
_STUDENT_PAYMENT_ME_CACHE: dict[tuple[int, str], tuple[float, dict[str, Any]]] = {}
_STUDENT_OVERVIEW_SUMMARY_CACHE: dict[tuple[int, str], tuple[float, dict[str, Any]]] = {}
_USER_SUBJECTS_CACHE: dict[tuple[int, str, str], tuple[float, list[str]]] = {}
_MEDIA_LIST_CACHE: dict[tuple[Any, ...], tuple[float, dict[str, Any]]] = {}
_DIAMONDVOY_CHAT_LIST_CACHE: dict[tuple[int, int], tuple[float, list[dict[str, Any]]]] = {}
_FINAL_CHAT_CLEANUP_LAST_RUN_MONOTONIC = 0.0
_HOT_CACHE_LOCK_GUARD = threading.Lock()
_HOT_CACHE_KEY_LOCKS: dict[tuple[Any, ...], threading.Lock] = {}
# Security: per-user cooldown for gift chest opens (user_id -> last open monotonic timestamp)
_CHEST_OPEN_LAST_TS: dict[int, float] = {}
_CHEST_OPEN_COOLDOWN_SECONDS: float = 3.0
# Security: per-user daily transfer totals (user_id -> (day_str, total_sent))
_TRANSFER_DAILY_TOTALS: dict[int, tuple[str, float]] = {}
_TRANSFER_DAILY_MAX: float = 5000.0


def _invalidate_student_overview_cache(user_id: int) -> None:
    uid = int(user_id or 0)
    if uid <= 0:
        return
    for key in list(_STUDENT_OVERVIEW_SUMMARY_CACHE.keys()):
        if int(key[0] or 0) == uid:
            _STUDENT_OVERVIEW_SUMMARY_CACHE.pop(key, None)


def _hot_cache_key_lock(namespace: str, key: Any) -> threading.Lock:
    lock_key = (str(namespace), repr(key))
    with _HOT_CACHE_LOCK_GUARD:
        lock = _HOT_CACHE_KEY_LOCKS.get(lock_key)
        if lock is None:
            lock = threading.Lock()
            _HOT_CACHE_KEY_LOCKS[lock_key] = lock
        if len(_HOT_CACHE_KEY_LOCKS) > 4096:
            for stale_key in list(_HOT_CACHE_KEY_LOCKS.keys())[:512]:
                if stale_key != lock_key:
                    _HOT_CACHE_KEY_LOCKS.pop(stale_key, None)
        return lock


def _short_cache_get(cache: dict, key: Any) -> Any | None:
    item = cache.get(key)
    if not item:
        return None
    expires_at, value = item
    if float(expires_at or 0.0) <= time.time():
        cache.pop(key, None)
        return None
    if isinstance(value, dict):
        return dict(value)
    if isinstance(value, list):
        return [dict(row) if isinstance(row, dict) else row for row in value]
    return value


def _short_cache_set(cache: dict, key: Any, value: Any, ttl_seconds: float, max_items: int = 2048) -> Any:
    if len(cache) >= int(max_items):
        now_ts = time.time()
        for stale_key, (expires_at, _) in list(cache.items())[:256]:
            if float(expires_at or 0.0) <= now_ts:
                cache.pop(stale_key, None)
        while len(cache) >= int(max_items):
            try:
                cache.pop(next(iter(cache.keys())))
            except Exception:
                break
    cache[key] = (time.time() + max(0.5, float(ttl_seconds)), value)
    return value


def _clear_user_media_caches(user_id: int) -> None:
    uid = int(user_id or 0)
    if uid <= 0:
        return
    for key in list(_USER_SUBJECTS_CACHE.keys()):
        if int(key[0] or 0) == uid:
            _USER_SUBJECTS_CACHE.pop(key, None)
    for key in list(_MEDIA_LIST_CACHE.keys()):
        try:
            if len(key) > 1 and int(key[1] or 0) == uid:
                _MEDIA_LIST_CACHE.pop(key, None)
        except Exception:
            continue
    _DIAMONDVOY_CHAT_LIST_CACHE.pop((uid, 30), None)
    for key in list(_DIAMONDVOY_CHAT_LIST_CACHE.keys()):
        if int(key[0] or 0) == uid:
            _DIAMONDVOY_CHAT_LIST_CACHE.pop(key, None)


def _clear_video_list_caches() -> None:
    _clear_media_list_caches("videos")


def _clear_book_list_caches() -> None:
    _clear_media_list_caches("books")


def _clear_media_list_caches(media_type: str | None = None) -> None:
    target = str(media_type or "").strip().lower()
    for key in list(_MEDIA_LIST_CACHE.keys()):
        try:
            if not target or (key and str(key[0]) == target):
                _MEDIA_LIST_CACHE.pop(key, None)
        except Exception:
            continue


def _app_state_economy_payload_cached(ttl_seconds: float = 5.0) -> dict[str, Any]:
    global _APP_STATE_ECONOMY_CACHE
    now_ts = time.time()
    cached = _APP_STATE_ECONOMY_CACHE
    if cached and cached[0] > now_ts:
        return dict(cached[1])
    rules_raw = _safe_call(get_economy_rule_settings, {}) or {}
    runtime_rules_raw = _safe_call(_get_runtime_settings, {}) or {}
    payload = {
        "correct": float(rules_raw.get("correct", 2.0)),
        "skipped": float(rules_raw.get("skipped", -1.5)),
        "wrong": float(rules_raw.get("wrong", -3.0)),
        "runtime": runtime_rules_raw,
    }
    _APP_STATE_ECONOMY_CACHE = (now_ts + float(ttl_seconds), dict(payload))
    return payload


def _user_row_from_bearer(authorization: str | None) -> dict:
    token = ""
    if authorization and authorization.lower().startswith("bearer "):
        token = authorization.split(" ", 1)[1].strip()
        cached = _AUTH_USER_ROW_CACHE.get(token)
        if cached and cached[0] > time.time():
            return dict(cached[1])
    payload = _decode_bearer_payload(authorization)
    user_id = payload.get("sub")
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token payload")

    row = _auth_user_row_cached(int(user_id))
    if not row:
        raise HTTPException(status_code=404, detail="User not found")
    token_telegram_id = str(payload.get("telegram_id") or "").strip()
    if token_telegram_id and _telegram_id_is_env_admin(token_telegram_id):
        token_role = _role_from_login_type(int(row.get("login_type") or 0), str(row.get("login_id") or ""))
        if token_role != "admin":
            raise HTTPException(status_code=401, detail="Session expired. Please login again")

    sid = str(payload.get("sid") or "").strip()
    if sid:
        _validate_web_session_cached(sid, int(user_id))
        _touch_web_session(sid)
        if token:
            _AUTH_USER_ROW_CACHE[token] = (time.time() + 8.0, dict(row))
        return row

    # Legacy fallback for old tokens without sid.
    token_sv = int(payload.get("sv") or 1)
    row_sv = int(row.get("session_version") or 1)
    if token_sv != row_sv:
        raise HTTPException(status_code=401, detail="Session expired. Please login again")
    if token:
        _AUTH_USER_ROW_CACHE[token] = (time.time() + 8.0, dict(row))
    return row


ALLOWED_NO_GROUP_PATH_PREFIXES = (
    "/chats",
    "/student/support",
    "/student/diamondvoy",
    "/student/payments",
    "/student/bookings",
    "/student/placement",
    "/student/proctoring",
    "/notifications",
    "/auth",
    "/app/state",
)


def _is_student_no_group_blocked_path(path: str) -> bool:
    normalized = str(path or "").strip()
    if not normalized.startswith("/student/"):
        return False
    for allowed_prefix in ALLOWED_NO_GROUP_PATH_PREFIXES:
        if normalized.startswith(allowed_prefix):
            return False
    return True


def _student_has_group_access_cached(user_id: int, ttl_seconds: float = 8.0) -> bool:
    uid = int(user_id or 0)
    if uid <= 0:
        return False
    now_ts = time.time()
    cached = _STUDENT_GROUP_ACCESS_CACHE.get(uid)
    if cached and cached[0] > now_ts:
        return bool(cached[1])
    groups = _safe_call(lambda: get_user_groups(uid), []) or []
    has_group = bool(groups)
    _STUDENT_GROUP_ACCESS_CACHE[uid] = (now_ts + max(1.0, float(ttl_seconds)), has_group)
    if len(_STUDENT_GROUP_ACCESS_CACHE) > 10000:
        for cached_uid, (expires_at, _) in list(_STUDENT_GROUP_ACCESS_CACHE.items()):
            if expires_at <= now_ts:
                _STUDENT_GROUP_ACCESS_CACHE.pop(cached_uid, None)
    return has_group


@app.middleware("http")
async def student_no_group_access_guard(request: Request, call_next):
    path = str(request.url.path or "").strip()
    if not _is_student_no_group_blocked_path(path):
        return await call_next(request)
    authorization = request.headers.get("Authorization")
    if not authorization:
        return await call_next(request)
    try:
        user = _user_row_from_bearer(authorization)
    except HTTPException:
        return await call_next(request)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role != "student":
        return await call_next(request)
    if _student_has_group_access_cached(int(user.get("id") or 0)):
        return await call_next(request)
    return JSONResponse(status_code=403, content={"detail": "Siz hali guruhga biriktirilmagansiz"})


def _require_role(user: dict, roles: set[str]) -> str:
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role not in roles:
        raise HTTPException(status_code=403, detail="Permission denied")
    return role


def _require_book_upload_access(user: dict) -> str:
    role = _require_role(user, {"admin", "teacher", "support"})
    if role == "admin":
        return role
    user_id = int(user.get("id") or 0)
    if user_id > 0 and _safe_call(lambda: get_book_upload_permission(user_id), False):
        return role
    raise HTTPException(status_code=403, detail="Kitob yuklash uchun ruxsat yo'q")


def _student_has_group_access(user: dict) -> bool:
    user_id = int(user.get("id") or 0)
    if user_id <= 0:
        return False
    groups = _safe_call(lambda uid=user_id: get_user_groups(uid), []) or []
    return len(groups) > 0


def _require_student_learning_access(user: dict) -> None:
    """Copy bot access gating so students cannot engage with tests/arenas/duels etc without active access (enabled + not expired + group)."""
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role != "student":
        return
    if not is_access_active(user):
        raise HTTPException(status_code=403, detail="Sizning kirish huquqingiz yo'q yoki guruhga biriktirilmagansiz")
    if _student_has_group_access(user):
        return
    raise HTTPException(status_code=403, detail="Siz hali guruhga biriktirilmagansiz")


def _require_placement_access(user: dict) -> None:
    """Placement (daraja) testi — kirish testi: guruhga biriktirilish TALAB QILINMAYDI.

    Faqat akkaunt bloklangan bo'lsa rad etiladi; access_enabled/muddat/guruh
    tekshiruvi qo'llanmaydi (yangi o'quvchi placement'ni guruhdan oldin topshiradi).
    """
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role != "student":
        return
    if int(user.get("blocked") or 0) == 1:
        raise HTTPException(status_code=403, detail="Account is blocked")


def _teacher_manageable_groups(teacher_id: int) -> list[dict]:
    own = _safe_call(lambda: get_groups_by_teacher(int(teacher_id)), []) or []
    temp = _safe_call(lambda: get_groups_with_temporary_access_for_teacher(int(teacher_id)), []) or []
    merged: dict[int, dict] = {}
    for row in own:
        gid = int(row.get("id") or 0)
        if gid > 0 and gid not in merged:
            item = dict(row)
            item["temporary_access"] = False
            merged[gid] = item
    for row in temp:
        gid = int(row.get("id") or 0)
        if gid > 0 and gid not in merged:
            item = dict(row)
            item["temporary_access"] = True
            merged[gid] = item
    return list(merged.values())


def _teacher_group_ids(groups: list[dict]) -> list[int]:
    seen: set[int] = set()
    ids: list[int] = []
    for group in groups or []:
        gid = int((group or {}).get("id") or 0)
        if gid > 0 and gid not in seen:
            seen.add(gid)
            ids.append(gid)
    return ids


def _teacher_student_ids_for_groups(group_ids: list[int]) -> set[int]:
    clean_ids = [int(gid) for gid in group_ids if int(gid or 0) > 0]
    if not clean_ids:
        return set()
    placeholders = ",".join(["?"] * len(clean_ids))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT DISTINCT u.id
            FROM user_groups ug
            JOIN users u ON u.id = ug.user_id
            WHERE ug.group_id IN ({placeholders})
              AND u.login_type IN (1, 2, 6)
              AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT)) = '')
            """,
            tuple(clean_ids),
        )
        ids: set[int] = set()
        for row in cur.fetchall() or []:
            try:
                item = dict(row)
            except Exception:
                item = {"id": row[0] if row else 0}
            uid = int(item.get("id") or 0)
            if uid > 0:
                ids.add(uid)
        return ids
    except Exception:
        logger.debug("teacher student bulk lookup failed", exc_info=True)
        return set()
    finally:
        conn.close()


def _attendance_summary_for_groups(group_ids: list[int], date_text: str) -> dict[int, dict[str, int]]:
    clean_ids = [int(gid) for gid in group_ids if int(gid or 0) > 0]
    if not clean_ids:
        return {}
    placeholders = ",".join(["?"] * len(clean_ids))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT group_id, LOWER(COALESCE(status, '')) AS status, COUNT(*) AS cnt
            FROM attendance
            WHERE group_id IN ({placeholders}) AND date=?
            GROUP BY group_id, LOWER(COALESCE(status, ''))
            """,
            tuple([*clean_ids, str(date_text)]),
        )
        summary: dict[int, dict[str, int]] = {}
        for row in cur.fetchall() or []:
            try:
                item = dict(row)
            except Exception:
                item = {
                    "group_id": row[0] if len(row) > 0 else 0,
                    "status": row[1] if len(row) > 1 else "",
                    "cnt": row[2] if len(row) > 2 else 0,
                }
            gid = int(item.get("group_id") or 0)
            status = str(item.get("status") or "").strip().lower()
            count = int(item.get("cnt") or 0)
            bucket = summary.setdefault(gid, {"present": 0, "late": 0, "absent": 0, "total": 0})
            bucket["total"] += count
            if status in {"present", "keldi"}:
                bucket["present"] += count
            elif status in {"late", "sababi", "sababli"}:
                bucket["late"] += count
            elif status in {"absent", "sababsiz"}:
                bucket["absent"] += count
        return summary
    except Exception:
        logger.debug("attendance summary bulk lookup failed", exc_info=True)
        return {}
    finally:
        conn.close()


def _teacher_monthly_test_stats_for_students(student_ids: set[int]) -> dict[int, dict[str, float]]:
    clean_ids = sorted({int(sid) for sid in student_ids if int(sid or 0) > 0})
    if not clean_ids:
        return {}
    placeholders = ",".join(["?"] * len(clean_ids))
    month_start = datetime.utcnow().replace(day=1, hour=0, minute=0, second=0, microsecond=0).strftime("%Y-%m-%d %H:%M:%S")
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT
                user_id,
                COUNT(*) AS tests_taken,
                SUM(CASE WHEN COALESCE(correct_count, 0) > 0 THEN 1 ELSE 0 END) AS tests_completed,
                SUM(COALESCE(correct_count, 0)) AS total_correct,
                SUM(COALESCE(wrong_count, 0)) AS total_wrong,
                SUM(COALESCE(skipped_count, 0)) AS total_skipped
            FROM test_history
            WHERE user_id IN ({placeholders})
              AND created_at >= ?
            GROUP BY user_id
            """,
            tuple([*clean_ids, month_start]),
        )
        out: dict[int, dict[str, float]] = {}
        for row in cur.fetchall() or []:
            try:
                item = dict(row)
            except Exception:
                item = {
                    "user_id": row[0] if len(row) > 0 else 0,
                    "tests_taken": row[1] if len(row) > 1 else 0,
                    "tests_completed": row[2] if len(row) > 2 else 0,
                    "total_correct": row[3] if len(row) > 3 else 0,
                    "total_wrong": row[4] if len(row) > 4 else 0,
                    "total_skipped": row[5] if len(row) > 5 else 0,
                }
            uid = int(item.get("user_id") or 0)
            correct = float(item.get("total_correct") or 0)
            wrong = float(item.get("total_wrong") or 0)
            skipped = float(item.get("total_skipped") or 0)
            answered = correct + wrong + skipped
            out[uid] = {
                "tests_taken": float(item.get("tests_taken") or 0),
                "tests_completed": float(item.get("tests_completed") or 0),
                "_correct": correct,
                "_wrong": wrong,
                "_skipped": skipped,
                "accuracy_percent": round((correct * 100.0 / answered), 1) if answered > 0 else 0.0,
            }
        month_start_date = month_start[:10]
        cur.execute(
            f"""
            SELECT
                user_id,
                COUNT(*) AS tests_completed,
                COALESCE(SUM(correct),0) AS total_correct,
                COALESCE(SUM(wrong),0) AS total_wrong,
                COALESCE(SUM(unanswered),0) AS total_skipped
            FROM daily_test_attempts
            WHERE user_id IN ({placeholders})
              AND status='completed'
              AND test_date >= ?
            GROUP BY user_id
            """,
            tuple([*clean_ids, month_start_date]),
        )
        for row in cur.fetchall() or []:
            item = dict(row)
            uid = int(item.get("user_id") or 0)
            bucket = out.setdefault(uid, {"tests_taken": 0.0, "tests_completed": 0.0, "_correct": 0.0, "_wrong": 0.0, "_skipped": 0.0, "accuracy_percent": 0.0})
            bucket["tests_taken"] = float(bucket.get("tests_taken") or 0) + float(item.get("tests_completed") or 0)
            bucket["tests_completed"] = float(bucket.get("tests_completed") or 0) + float(item.get("tests_completed") or 0)
            bucket["_correct"] = float(bucket.get("_correct") or 0) + float(item.get("total_correct") or 0)
            bucket["_wrong"] = float(bucket.get("_wrong") or 0) + float(item.get("total_wrong") or 0)
            bucket["_skipped"] = float(bucket.get("_skipped") or 0) + float(item.get("total_skipped") or 0)
        for bucket in out.values():
            correct = float(bucket.pop("_correct", 0.0) or 0.0)
            wrong = float(bucket.pop("_wrong", 0.0) or 0.0)
            skipped = float(bucket.pop("_skipped", 0.0) or 0.0)
            answered = correct + wrong + skipped
            bucket["accuracy_percent"] = round((correct * 100.0 / answered), 1) if answered > 0 else 0.0
        return out
    except Exception:
        logger.debug("teacher monthly stats bulk lookup failed", exc_info=True)
        return {}
    finally:
        conn.close()


