def _visible_dcoin_map_for_users(user_ids: set[int]) -> dict[int, float]:
    clean_ids = sorted({int(uid) for uid in user_ids if int(uid or 0) > 0})
    if not clean_ids:
        return {}
    placeholders = ",".join(["?"] * len(clean_ids))
    subject_sets: dict[int, set[str]] = {uid: set() for uid in clean_ids}
    wallet_rows: dict[int, dict[str, float | None]] = {}
    legacy_rows: dict[int, float] = {}
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT id, subject
            FROM users
            WHERE id IN ({placeholders}) AND COALESCE(login_type, 0) <> 6
            """,
            tuple(clean_ids),
        )
        active_user_ids: set[int] = set()
        for row in cur.fetchall() or []:
            item = dict(row)
            uid = int(item.get("id") or 0)
            if uid <= 0:
                continue
            active_user_ids.add(uid)
            for part in str(item.get("subject") or "").split(","):
                token = str(part or "").strip().title()
                if token:
                    subject_sets.setdefault(uid, set()).add(token)
        if not active_user_ids:
            return {uid: 0.0 for uid in clean_ids}

        active_ids = sorted(active_user_ids)
        active_placeholders = ",".join(["?"] * len(active_ids))
        cur.execute(
            f"""
            SELECT ug.user_id, g.subject
            FROM user_groups ug
            JOIN groups g ON g.id = ug.group_id
            WHERE ug.user_id IN ({active_placeholders})
              AND g.subject IS NOT NULL
              AND TRIM(g.subject) <> ''
              AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT)) = '')
            """,
            tuple(active_ids),
        )
        for row in cur.fetchall() or []:
            item = dict(row)
            uid = int(item.get("user_id") or 0)
            token = str(item.get("subject") or "").strip().title()
            if uid > 0 and token:
                subject_sets.setdefault(uid, set()).add(token)

        cur.execute(
            f"""
            SELECT
                user_id,
                COALESCE(dpoints, 0) AS dpoints,
                COALESCE(dcoin_floor, 0) AS dcoin_floor,
                dcoin_anchor_value,
                dcoin_anchor_dpoints
            FROM user_dpoints
            WHERE user_id IN ({active_placeholders})
            """,
            tuple(active_ids),
        )
        for row in cur.fetchall() or []:
            item = dict(row)
            uid = int(item.get("user_id") or 0)
            wallet_rows[uid] = {
                "dpoints": float(item.get("dpoints") or 0.0),
                "dcoin_floor": float(item.get("dcoin_floor") or 0.0),
                "anchor_value": float(item.get("dcoin_anchor_value")) if item.get("dcoin_anchor_value") is not None else None,
                "anchor_dpoints": float(item.get("dcoin_anchor_dpoints")) if item.get("dcoin_anchor_dpoints") is not None else None,
            }

        missing_wallet_ids = [uid for uid in active_ids if uid not in wallet_rows]
        if missing_wallet_ids:
            missing_placeholders = ",".join(["?"] * len(missing_wallet_ids))
            cur.execute(
                f"""
                SELECT user_id, COALESCE(SUM(balance), 0) AS total
                FROM user_subject_dcoins
                WHERE user_id IN ({missing_placeholders})
                GROUP BY user_id
                """,
                tuple(missing_wallet_ids),
            )
            legacy_rows = {int(dict(row).get("user_id") or 0): float(dict(row).get("total") or 0.0) for row in (cur.fetchall() or [])}

        out: dict[int, float] = {}
        for uid in clean_ids:
            if uid not in active_user_ids:
                out[uid] = 0.0
                continue
            state = wallet_rows.get(uid)
            if state:
                dpoints = float(state.get("dpoints") or 0.0)
                floor = float(state.get("dcoin_floor") or 0.0)
                anchor_value = state.get("anchor_value")
                anchor_dpoints = state.get("anchor_dpoints")
            else:
                dpoints = float(legacy_rows.get(uid) or 0.0)
                floor = 0.0
                anchor_value = None
                anchor_dpoints = None
            subject_count = max(1, len(subject_sets.get(uid) or set()))
            if anchor_value is not None and anchor_dpoints is not None:
                visible = float(anchor_value) + (dpoints - float(anchor_dpoints))
            else:
                visible = dpoints
            out[uid] = _round_half_up(max(0.0, floor, visible), 2)
        return out
    except Exception:
        logger.debug("bulk visible dcoin lookup failed", exc_info=True)
        return {}
    finally:
        conn.close()


def _teacher_can_manage_group(user: dict, group: dict | None) -> bool:
    if not user or not group:
        return False
    uid = int(user.get("id") or 0)
    gid = int(group.get("id") or 0)
    owner_tid = int(group.get("teacher_id") or 0)
    if owner_tid == uid:
        return True
    if gid <= 0:
        return False
    return bool(_safe_call(lambda: teacher_has_temporary_group_access(uid, gid), False))


