def _teacher_pending_tasks(
    teacher_id: int,
    groups: list[dict],
    *,
    student_ids: set[int] | None = None,
    attendance_summary: dict[int, dict[str, int]] | None = None,
) -> dict:
    today = _now_tashkent_date()
    pending_attendance = 0
    if attendance_summary is None:
        attendance_summary = _attendance_summary_for_groups(_teacher_group_ids(groups), today)
    for group in groups:
        gid = int(group.get("id") or 0)
        expected = int(group.get("student_count") or 0)
        marked = int((attendance_summary.get(gid) or {}).get("total") or 0)
        if expected > 0 and marked < expected:
            pending_attendance += 1

    bookings, _ = _safe_call(lambda: list_lesson_bookings(status="pending", page=1, per_page=300), ([], 1))
    if student_ids is None:
        student_ids = _teacher_student_ids(int(teacher_id))
    pending_support = len([b for b in (bookings or []) if int(b.get("student_user_id") or 0) in student_ids])
    return {
        "pending_attendance_groups": pending_attendance,
        "pending_support_requests": pending_support,
        "todo_total": int(pending_attendance + pending_support),
    }


def _group_schedule_matches_date(lesson_date: str | None, date_value: Any) -> bool:
    raw = str(lesson_date or "").strip()
    if not raw:
        return False
    upper = raw.upper()
    if re.match(r"^\d{4}-\d{2}-\d{2}$", raw):
        return raw == date_value.isoformat()
    if upper in {"ODD", "MWF", "MON/WED/FRI", "MON,WED,FRI"}:
        return date_value.weekday() in {0, 2, 4}
    if upper in {"EVEN", "TTS", "TUE/THU/SAT", "TUE,THU,SAT"}:
        return date_value.weekday() in {1, 3, 5}
    return False


def _parse_hhmm(value: str | None) -> tuple[int, int] | None:
    text = str(value or "").strip()
    if not re.match(r"^\d{2}:\d{2}$", text):
        return None
    try:
        hh, mm = [int(part) for part in text.split(":", 1)]
        if 0 <= hh <= 23 and 0 <= mm <= 59:
            return hh, mm
    except Exception:
        return None
    return None


def _resolve_temporary_assignment_slots(group: dict, payload: TemporaryAssignmentRequest) -> list[dict[str, str | None]]:
    start = str(payload.lesson_start or group.get("lesson_start") or "").strip() or None
    end = str(payload.lesson_end or group.get("lesson_end") or "").strip() or None
    now_local = datetime.now(TASHKENT_TZ)

    if payload.upcoming_count is not None:
        lesson_pattern = str(group.get("lesson_date") or "").strip()
        if not lesson_pattern:
            raise HTTPException(status_code=422, detail="Group has no lesson schedule configured")
        need = max(1, int(payload.upcoming_count or 1))
        slots: list[dict[str, str | None]] = []
        start_pair = _parse_hhmm(start)
        end_pair = _parse_hhmm(end)
        blocked_holiday_dates = 0
        for offset in range(0, 370):
            day_value = now_local.date() + timedelta(days=offset)
            if not _group_schedule_matches_date(lesson_pattern, day_value):
                continue
            day_iso = day_value.isoformat()
            if is_lesson_otmen_date_cancelled(day_iso):
                blocked_holiday_dates += 1
                continue
            if offset == 0 and start_pair and end_pair:
                start_local = TASHKENT_TZ.localize(
                    datetime.combine(
                        day_value,
                        datetime.min.time().replace(hour=start_pair[0], minute=start_pair[1]),
                    )
                )
                end_local = TASHKENT_TZ.localize(
                    datetime.combine(
                        day_value,
                        datetime.min.time().replace(hour=end_pair[0], minute=end_pair[1]),
                    )
                )
                if end_local < start_local:
                    end_local = end_local + timedelta(days=1)
                if end_local <= now_local:
                    continue
            slots.append(
                {
                    "lesson_date": day_iso,
                    "lesson_start": start,
                    "lesson_end": end,
                }
            )
            if len(slots) >= need:
                break
        if not slots:
            if blocked_holiday_dates > 0:
                raise HTTPException(status_code=409, detail="Selected date is closed due to holiday")
            raise HTTPException(status_code=422, detail="No upcoming lessons found for this group schedule")
        return slots

    lesson_date = str(payload.lesson_date or "").strip()
    if not lesson_date:
        raise HTTPException(status_code=422, detail="lesson_date is required when upcoming_count is not provided")
    try:
        datetime.strptime(lesson_date, "%Y-%m-%d")
    except Exception:
        raise HTTPException(status_code=422, detail="lesson_date must be YYYY-MM-DD")
    if is_lesson_otmen_date_cancelled(lesson_date):
        raise HTTPException(status_code=409, detail="Selected date is closed due to holiday")
    return [{"lesson_date": lesson_date, "lesson_start": start, "lesson_end": end}]


def _create_temporary_assignments_for_slots(
    group_id: int,
    owner_teacher_id: int,
    temp_teacher_id: int,
    slots: list[dict[str, str | None]],
) -> tuple[list[int], int]:
    existing = _safe_call(
        lambda: get_active_temporary_assignments_for_pair(int(owner_teacher_id), int(group_id), int(temp_teacher_id)),
        [],
    ) or []
    existing_keys = {
        (
            str(row.get("lesson_date") or ""),
            str(row.get("lesson_start") or ""),
            str(row.get("lesson_end") or ""),
        )
        for row in existing
    }
    created_ids: list[int] = []
    skipped = 0
    for slot in slots:
        lesson_date = str(slot.get("lesson_date") or "")
        lesson_start = str(slot.get("lesson_start") or "") or None
        lesson_end = str(slot.get("lesson_end") or "") or None
        if is_lesson_otmen_date_cancelled(lesson_date):
            skipped += 1
            continue
        dedupe_key = (lesson_date, str(lesson_start or ""), str(lesson_end or ""))
        if dedupe_key in existing_keys:
            skipped += 1
            continue
        assignment_id = create_temporary_group_assignment(
            int(group_id),
            owner_teacher_id=int(owner_teacher_id),
            temp_teacher_id=int(temp_teacher_id),
            lesson_date=lesson_date,
            lesson_start=lesson_start,
            lesson_end=lesson_end,
        )
        created_ids.append(int(assignment_id))
        existing_keys.add(dedupe_key)
    return created_ids, skipped


def _validate_temporary_assignee_for_group(group: dict, temp_teacher_id: int) -> tuple[dict, str, str]:
    temp_teacher = _safe_call(lambda: get_user_by_id(int(temp_teacher_id)), None)
    temp_role = _role_from_login_type(int((temp_teacher or {}).get("login_type") or 0), str((temp_teacher or {}).get("login_id") or ""))
    if not temp_teacher or temp_role not in {"teacher", "support"}:
        raise HTTPException(status_code=400, detail="Temporary assignee must be a teacher or support teacher")
    group_subject = _normalize_subject_label(str(group.get("subject") or "").strip())
    if group_subject:
        staff_subjects = _normalize_subjects(_user_subjects_from_row(temp_teacher), fallback=[])
        if group_subject not in staff_subjects:
            raise HTTPException(status_code=400, detail="Temporary assignee subject does not match this group")
    return temp_teacher, temp_role, group_subject


def _upsert_support_temp_blocks(
    support_teacher_id: int,
    subject: str,
    group_id: int,
    owner_teacher_id: int,
    slots: list[dict[str, str | None]],
    assignment_ids: list[int] | None = None,
) -> int:
    normalized_subject = _normalize_subject_label(subject)
    if int(support_teacher_id or 0) <= 0 or not normalized_subject:
        return 0
    _ensure_support_teacher_temp_blocks_schema()
    conn = get_conn()
    cur = conn.cursor()
    count = 0
    try:
        for slot in slots:
            date_iso = str(slot.get("lesson_date") or "")
            for tm in _lesson_window_support_times(str(slot.get("lesson_start") or ""), str(slot.get("lesson_end") or "")):
                block_id = _support_temp_block_id(int(support_teacher_id), normalized_subject, date_iso, tm, int(group_id))
                cur.execute(
                    """
                    INSERT INTO support_teacher_temp_blocks(
                        id, support_teacher_id, subject, date, time, group_id, owner_teacher_id,
                        temp_assignment_ids, reason, released_at
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)
                    ON CONFLICT(id) DO UPDATE SET
                        temp_assignment_ids=excluded.temp_assignment_ids,
                        reason=excluded.reason,
                        released_at=NULL
                    """,
                    (
                        block_id,
                        int(support_teacher_id),
                        normalized_subject,
                        date_iso,
                        tm,
                        int(group_id),
                        int(owner_teacher_id),
                        ",".join(str(x) for x in (assignment_ids or [])),
                        "temporary_group_assignment",
                    ),
                )
                count += 1
        conn.commit()
        return count
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("support temp block upsert failed group_id=%s support_teacher_id=%s", group_id, support_teacher_id)
        return 0
    finally:
        conn.close()


def _release_support_temp_blocks(
    support_teacher_id: int,
    subject: str,
    group_id: int,
    slots: list[dict[str, str | None]],
) -> int:
    normalized_subject = _normalize_subject_label(subject)
    if int(support_teacher_id or 0) <= 0 or not normalized_subject:
        return 0
    _ensure_support_teacher_temp_blocks_schema()
    conn = get_conn()
    cur = conn.cursor()
    released = 0
    try:
        for slot in slots:
            date_iso = str(slot.get("lesson_date") or "")
            for tm in _lesson_window_support_times(str(slot.get("lesson_start") or ""), str(slot.get("lesson_end") or "")):
                cur.execute(
                    """
                    UPDATE support_teacher_temp_blocks
                    SET released_at=CURRENT_TIMESTAMP
                    WHERE support_teacher_id=? AND subject=? AND date=? AND time=? AND group_id=? AND released_at IS NULL
                    """,
                    (int(support_teacher_id), normalized_subject, date_iso, tm, int(group_id)),
                )
                released += int(cur.rowcount or 0)
        conn.commit()
        return released
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("support temp block release failed group_id=%s support_teacher_id=%s", group_id, support_teacher_id)
        return 0
    finally:
        conn.close()


def _active_support_bookings_for_temp_slots(
    support_teacher_id: int,
    subject: str,
    slots: list[dict[str, str | None]],
) -> list[dict]:
    normalized_subject = _normalize_subject_label(subject)
    if int(support_teacher_id or 0) <= 0 or not normalized_subject:
        return []
    rows: list[dict] = []
    seen: set[str] = set()
    conn = get_conn()
    cur = conn.cursor()
    try:
        for slot in slots:
            date_iso = str(slot.get("lesson_date") or "")
            for tm in _lesson_window_support_times(str(slot.get("lesson_start") or ""), str(slot.get("lesson_end") or "")):
                cur.execute(
                    """
                    SELECT *
                    FROM lesson_bookings
                    WHERE support_teacher_id=?
                      AND support_subject=?
                      AND date=?
                      AND time=?
                      AND LOWER(COALESCE(status,'')) IN ('pending','approved')
                    """,
                    (int(support_teacher_id), normalized_subject, date_iso, tm),
                )
                for row in cur.fetchall() or []:
                    item = dict(row)
                    bid = str(item.get("id") or "")
                    if bid and bid not in seen:
                        seen.add(bid)
                        rows.append(item)
        return rows
    except Exception:
        logger.exception("support booking temp conflict lookup failed")
        return rows
    finally:
        conn.close()


