def _future_active_support_bookings_for_closed_time(
    support_teacher_id: int,
    subject: str,
    weekday: int,
    time_hhmm: str,
) -> list[dict]:
    teacher_id = int(support_teacher_id or 0)
    normalized_subject = _normalize_subject_label(subject)
    tm = normalize_time_hhmm(time_hhmm)
    if teacher_id <= 0 or not normalized_subject or tm is None or int(weekday) < 0 or int(weekday) > 5:
        return []
    today_iso = datetime.now(TASHKENT_TZ).date().isoformat()
    now_utc = _now_utc()
    conn = get_conn()
    cur = conn.cursor()
    rows: list[dict] = []
    try:
        cur.execute(
            """
            SELECT *
            FROM lesson_bookings
            WHERE support_teacher_id=?
              AND support_subject=?
              AND time=?
              AND date>=?
              AND LOWER(COALESCE(status,'')) IN ('pending','approved')
            ORDER BY date ASC, time ASC
            """,
            (teacher_id, normalized_subject, tm, today_iso),
        )
        for row in cur.fetchall() or []:
            item = dict(row)
            try:
                d = datetime.strptime(str(item.get("date") or ""), "%Y-%m-%d").date()
            except Exception:
                continue
            if d.weekday() != int(weekday):
                continue
            start_ts = str(item.get("start_ts") or "") or (support_make_start_ts(str(item.get("date") or ""), tm) or "")
            start_dt = _parse_utc_timestamp(start_ts)
            if start_dt is not None and start_dt <= now_utc:
                continue
            rows.append(item)
        return rows
    except Exception:
        logger.exception("closed support time booking lookup failed teacher_id=%s subject=%s weekday=%s time=%s", teacher_id, normalized_subject, weekday, tm)
        return []
    finally:
        conn.close()


