async def _apply_support_temp_assignment_side_effects(
    *,
    group: dict,
    support_teacher_id: int,
    subject: str,
    owner_teacher_id: int,
    slots: list[dict[str, str | None]],
    assignment_ids: list[int],
) -> dict[str, int]:
    blocked_count = _upsert_support_temp_blocks(
        int(support_teacher_id),
        subject,
        int(group.get("id") or 0),
        int(owner_teacher_id),
        slots,
        assignment_ids=assignment_ids,
    )
    conflicts = _active_support_bookings_for_temp_slots(int(support_teacher_id), subject, slots)
    cancelled = 0
    for booking in conflicts:
        note = "Support teacher vaqtinchalik guruh darsiga biriktirilgani sababli bekor qilindi"
        ok = set_lesson_booking_status(str(booking.get("id") or ""), "cancelled", admin_id=int(owner_teacher_id or 0), admin_note=note)
        if ok:
            cancelled += 1
            await _notify_support_temp_booking_cancelled(booking, group)
    return {"blocked_slots": int(blocked_count), "cancelled_bookings": int(cancelled)}


def _teacher_can_adjust_dcoin_now(teacher_id: int, student_id: int) -> bool:
    now_local = datetime.now(TASHKENT_TZ)
    dates_to_check = [now_local.date(), (now_local - timedelta(days=1)).date()]
    for group in _teacher_manageable_groups(int(teacher_id)):
        gid = int(group.get("id") or 0)
        if gid <= 0:
            continue
        group_member_ids = {
            int(member.get("id") or 0)
            for member in (_safe_call(lambda group_id=gid: get_group_users(group_id), []) or [])
            if int(member.get("id") or 0) > 0
        }
        if int(student_id) not in group_member_ids:
            continue
        start_pair = _parse_hhmm(group.get("lesson_start"))
        end_pair = _parse_hhmm(group.get("lesson_end"))
        if not start_pair or not end_pair:
            continue
        lesson_date = str(group.get("lesson_date") or "")
        for target_date in dates_to_check:
            if not _group_schedule_matches_date(lesson_date, target_date):
                continue
            try:
                start_local = TASHKENT_TZ.localize(
                    datetime.combine(
                        target_date,
                        datetime.min.time().replace(hour=start_pair[0], minute=start_pair[1]),
                    )
                )
                end_local = TASHKENT_TZ.localize(
                    datetime.combine(
                        target_date,
                        datetime.min.time().replace(hour=end_pair[0], minute=end_pair[1]),
                    )
                )
            except Exception:
                continue
            if end_local < start_local:
                end_local = end_local + timedelta(days=1)
            window_start = start_local - timedelta(minutes=10)
            window_end = end_local + timedelta(hours=24)
            if window_start <= now_local <= window_end:
                return True
    return False


ATTENDANCE_WINDOW_ERROR = (
    "Davomatni faqat dars boshlanishidan 10 daqiqa oldin va dars tugagandan 24 soat ichida belgilash mumkin."
)


def _attendance_window_bounds(group: dict | None, date_text: str | None) -> tuple[datetime, datetime] | None:
    if not group:
        return None
    raw_date = str(date_text or "").strip()
    try:
        target_date = datetime.strptime(raw_date, "%Y-%m-%d").date()
    except Exception:
        return None
    lesson_pattern = str((group or {}).get("lesson_date") or "").strip()
    if lesson_pattern and not _group_schedule_matches_date(lesson_pattern, target_date):
        return None
    start_pair = _parse_hhmm((group or {}).get("lesson_start"))
    end_pair = _parse_hhmm((group or {}).get("lesson_end"))
    if not start_pair or not end_pair:
        return None
    start_local = TASHKENT_TZ.localize(
        datetime.combine(
            target_date,
            datetime.min.time().replace(hour=start_pair[0], minute=start_pair[1]),
        )
    )
    end_local = TASHKENT_TZ.localize(
        datetime.combine(
            target_date,
            datetime.min.time().replace(hour=end_pair[0], minute=end_pair[1]),
        )
    )
    if end_local < start_local:
        end_local = end_local + timedelta(days=1)
    return start_local - timedelta(minutes=10), end_local + timedelta(hours=24)


def _ensure_attendance_window_open(group: dict | None, date_text: str | None) -> None:
    bounds = _attendance_window_bounds(group, date_text)
    if not bounds:
        raise HTTPException(status_code=409, detail=ATTENDANCE_WINDOW_ERROR)
    window_start, window_end = bounds
    now_local = datetime.now(TASHKENT_TZ)
    if not (window_start <= now_local <= window_end):
        raise HTTPException(status_code=409, detail=ATTENDANCE_WINDOW_ERROR)


def _parse_membership_date(raw: Any) -> datetime.date | None:
    text = str(raw or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except Exception:
        try:
            return datetime.strptime(text[:10], "%Y-%m-%d").date()
        except Exception:
            return None


def _group_membership_periods_by_user(group_id: int) -> dict[int, list[tuple[datetime.date | None, datetime.date | None]]]:
    periods: dict[int, list[tuple[datetime.date | None, datetime.date | None]]] = {}
    conn = get_conn()
    cur = conn.cursor()
    try:
        try:
            cur.execute(
                """
                SELECT user_id, joined_at, left_at
                FROM user_group_membership_log
                WHERE group_id=?
                """,
                (int(group_id),),
            )
            for row in cur.fetchall() or []:
                uid = int(row.get("user_id") or 0)
                if not uid:
                    continue
                periods.setdefault(uid, []).append((_parse_membership_date(row.get("joined_at")), _parse_membership_date(row.get("left_at"))))
        except Exception:
            pass
        try:
            cur.execute(
                """
                SELECT user_id, joined_date, left_date, created_at
                FROM user_groups
                WHERE group_id=?
                """,
                (int(group_id),),
            )
            for row in cur.fetchall() or []:
                uid = int(row.get("user_id") or 0)
                if not uid:
                    continue
                joined = _parse_membership_date(row.get("joined_date")) or _parse_membership_date(row.get("created_at"))
                periods.setdefault(uid, []).append((joined, _parse_membership_date(row.get("left_date"))))
        except Exception:
            pass
    finally:
        conn.close()
    return periods


def _membership_period_allows_date(
    periods: list[tuple[datetime.date | None, datetime.date | None]] | None,
    date_text: str | None,
) -> bool:
    try:
        day = datetime.strptime(str(date_text or "").strip(), "%Y-%m-%d").date()
    except Exception:
        return False
    if not periods:
        return True
    for joined, left in periods:
        if joined and day < joined:
            continue
        if left and day > left:
            continue
        return True
    return False


def _ensure_attendance_mark_allowed(group: dict | None, group_id: int, user_id: int, date_text: str | None) -> None:
    raw_date = str(date_text or "").strip()
    try:
        target_date = datetime.strptime(raw_date, "%Y-%m-%d").date()
    except Exception:
        raise HTTPException(status_code=409, detail=ATTENDANCE_WINDOW_ERROR)
    lesson_pattern = str((group or {}).get("lesson_date") or "").strip()
    if not _group_schedule_matches_date(lesson_pattern, target_date):
        raise HTTPException(status_code=409, detail=ATTENDANCE_WINDOW_ERROR)
    periods_by_user = _group_membership_periods_by_user(int(group_id))
    if int(user_id) not in periods_by_user:
        raise HTTPException(status_code=409, detail="O'quvchi bu sanada guruhda emas.")
    if not _membership_period_allows_date(periods_by_user.get(int(user_id)), raw_date):
        raise HTTPException(status_code=409, detail="O'quvchi bu sanada guruhda emas.")
    _ensure_attendance_window_open(group, raw_date)


def _attendance_month_bounds(month_text: str | None) -> tuple[datetime.date, datetime.date, str, str]:
    raw = str(month_text or "").strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}$", raw):
        try:
            center = datetime.strptime(raw, "%Y-%m-%d").date()
        except Exception:
            center = _now_tashkent().date()
        return center - timedelta(days=30), center + timedelta(days=30), center.strftime("%Y-%m"), (center - timedelta(days=3)).isoformat()
    if not re.match(r"^\d{4}-\d{2}$", raw):
        raw = _now_tashkent().strftime("%Y-%m")
    try:
        start = datetime.strptime(f"{raw}-01", "%Y-%m-%d").date()
    except Exception:
        raw = _now_tashkent().strftime("%Y-%m")
        start = datetime.strptime(f"{raw}-01", "%Y-%m-%d").date()
    if start.month == 12:
        next_month = start.replace(year=start.year + 1, month=1, day=1)
    else:
        next_month = start.replace(month=start.month + 1, day=1)
    center = _now_tashkent().date() if raw == _now_tashkent().strftime("%Y-%m") else start
    return center - timedelta(days=30), center + timedelta(days=30), raw, center.isoformat()


def _attendance_lesson_dates_for_month(group: dict | None, month_text: str | None) -> tuple[list[dict[str, Any]], str, str]:
    start, end, ym, visible_start_date = _attendance_month_bounds(month_text)
    lesson_pattern = str((group or {}).get("lesson_date") or "").strip()
    start_hhmm = str((group or {}).get("lesson_start") or "").strip()
    end_hhmm = str((group or {}).get("lesson_end") or "").strip()
    rows: list[dict[str, Any]] = []
    today = start
    while today <= end:
        if _group_schedule_matches_date(lesson_pattern, today):
            day_iso = today.isoformat()
            bounds = _attendance_window_bounds(group, day_iso)
            is_closed = bool(is_lesson_otmen_date_cancelled(day_iso))
            open_now = False
            if bounds and not is_closed:
                window_start, window_end = bounds
                now_local = datetime.now(TASHKENT_TZ)
                open_now = window_start <= now_local <= window_end
            rows.append(
                {
                    "date": day_iso,
                    "label": today.strftime("%d.%m"),
                    "weekday": today.strftime("%a"),
                    "start": start_hhmm,
                    "end": end_hhmm,
                    "open": bool(open_now),
                    "closed": bool(is_closed),
                }
            )
        today = today + timedelta(days=1)
    return rows, ym, visible_start_date


def _attendance_table_payload(group_id: int, group: dict, month: str | None) -> dict[str, Any]:
    dates, ym, visible_start_date = _attendance_lesson_dates_for_month(group, month)
    members = _enrich_user_rows_with_face_profiles(_safe_call(lambda: get_group_users(int(group_id)), []) or [])
    membership_periods = _group_membership_periods_by_user(int(group_id))
    students: list[dict[str, Any]] = []
    for member in members:
        if int(member.get("login_type") or 0) not in (1, 2, 6):
            continue
        uid = int(member.get("id") or 0)
        avatar_url = (
            str(member.get("profile_image_url") or "").strip()
            or str(member.get("effective_profile_image_url") or "").strip()
            or str(member.get("face_reference_image_url") or "").strip()
            or None
        )
        students.append(
            {
                "user_id": uid,
                "id": uid,
                "full_name": _display_name(member),
                "first_name": member.get("first_name"),
                "last_name": member.get("last_name"),
                "login_id": member.get("login_id"),
                "avatar_url": avatar_url,
                "profile_image_url": avatar_url,
            }
        )
    cell_allowed: dict[str, bool] = {}
    for student in students:
        uid = int(student.get("user_id") or 0)
        for day in dates:
            day_iso = str(day.get("date") or "")
            cell_allowed[f"{uid}:{day_iso}"] = bool(day.get("open")) and _membership_period_allows_date(membership_periods.get(uid), day_iso)
    attendance_map: dict[str, str] = {}
    date_values = [str(row.get("date") or "") for row in dates if row.get("date")]
    if date_values:
        placeholders = ",".join("?" for _ in date_values)
        try:
            conn = get_conn()
            cur = conn.cursor()
            cur.execute(
                f"""
                SELECT user_id, date, status
                FROM attendance
                WHERE group_id=? AND date IN ({placeholders})
                """,
                [int(group_id), *date_values],
            )
            for row in cur.fetchall():
                attendance_map[f"{int(row['user_id'])}:{str(row['date'])}"] = str(row["status"] or "")
            conn.close()
        except Exception:
            try:
                conn.close()  # type: ignore[name-defined]
            except Exception:
                pass
            logger.exception("attendance table bulk lookup failed group_id=%s month=%s", group_id, ym)
    return {
        "group_id": int(group_id),
        "month": ym,
        "dates": dates,
        "visible_start_date": visible_start_date,
        "students": students,
        "attendance": attendance_map,
        "cell_allowed": cell_allowed,
        "items": students,
    }


def _safe_probability_weight(value: Any) -> float:
    try:
        parsed = float(value)
    except Exception:
        return 0.0
    if parsed < 0:
        return 0.0
    return parsed


def _weighted_pick_gift(rows: list[dict]) -> dict | None:
    active_rows = [row for row in rows if int(row.get("active") or 0) == 1]
    if not active_rows:
        return None
    weights = [_safe_probability_weight(row.get("probability_weight")) for row in active_rows]
    total = sum(weights)
    if total <= 0:
        return random.choice(active_rows)
    return random.choices(active_rows, weights=weights, k=1)[0]


def _gift_locale(raw: Any) -> str | None:
    lang = str(raw or "").strip().lower()[:2]
    return lang if lang in {"uz", "ru", "en"} else None


def _localized_gift_text(row: dict, field: str, lang: str | None = None) -> str:
    requested = _gift_locale(lang)
    candidates: list[Any] = []
    if requested:
        candidates.append(row.get(f"{field}_{requested}"))
    candidates.extend(
        [
            row.get(field),
            row.get(f"{field}_uz"),
            row.get(f"{field}_ru"),
            row.get(f"{field}_en"),
        ]
    )
    for value in candidates:
        text = str(value or "").strip()
        if text:
            return text
    return ""


def _serialize_gift_row(row: dict, ticket_count: int = 0, lang: str | None = None) -> dict:
    title = _localized_gift_text(row, "title", lang)
    description = _localized_gift_text(row, "description", lang)
    return {
        "id": int(row.get("id") or 0),
        "title": title,
        "title_uz": str(row.get("title_uz") or row.get("title") or "").strip(),
        "title_ru": str(row.get("title_ru") or "").strip(),
        "title_en": str(row.get("title_en") or "").strip(),
        "description": description or None,
        "description_uz": str(row.get("description_uz") or row.get("description") or "").strip(),
        "description_ru": str(row.get("description_ru") or "").strip(),
        "description_en": str(row.get("description_en") or "").strip(),
        "image_url": row.get("image_url"),
        "price_dcoin": float(row.get("price_dcoin") or 0.0),
        "required_tickets": max(1, int(row.get("required_tickets") or 1)),
        "probability_weight": _safe_probability_weight(row.get("probability_weight")),
        "active": bool(int(row.get("active") or 0) == 1),
        "is_payment_discount": bool(int(row.get("is_payment_discount") or 0) == 1),
        "payment_discount_percent": max(0.0, min(100.0, float(row.get("payment_discount_percent") or 0.0))),
        "ticket_count": max(0, int(ticket_count or 0)),
    }


def _serialize_student_purchase_row(row: dict[str, Any], lang: str | None = None) -> dict[str, Any]:
    meta = _safe_json_object(row.get("meta_json"))
    created_at = _as_iso_timestamp(row.get("created_at"))
    item_type = str(row.get("item_type") or "other").strip().lower() or "other"
    localized_gift_title = _localized_gift_text(
        {
            "title": row.get("gift_title") or row.get("item_title"),
            "title_uz": row.get("gift_title_uz"),
            "title_ru": row.get("gift_title_ru"),
            "title_en": row.get("gift_title_en"),
        },
        "title",
        lang,
    )
    localized_gift_description = _localized_gift_text(
        {
            "description": row.get("gift_description"),
            "description_uz": row.get("gift_description_uz"),
            "description_ru": row.get("gift_description_ru"),
            "description_en": row.get("gift_description_en"),
        },
        "description",
        lang,
    )
    item_title = localized_gift_title if item_type in {"gift", "chest"} and localized_gift_title else str(row.get("item_title") or "").strip()
    return {
        "id": int(row.get("id") or 0),
        "item_id": int(row.get("item_id") or 0) or None,
        "item_type": item_type,
        "item_title": item_title or "Xarid",
        "amount_spent": float(row.get("amount_spent") or 0.0),
        "balance_before": float(row.get("balance_before")) if row.get("balance_before") is not None else None,
        "balance_after": float(row.get("balance_after")) if row.get("balance_after") is not None else None,
        "source_page": str(row.get("source_page") or "").strip() or None,
        "created_at": created_at,
        "created_date": created_at[:10] if created_at else None,
        "created_time": created_at[11:19] if created_at and len(created_at) >= 19 else None,
        "meta": meta,
        "gift": {
            "title": localized_gift_title,
            "description": localized_gift_description or None,
            "title_uz": str(row.get("gift_title_uz") or row.get("gift_title") or row.get("item_title") or "").strip(),
            "title_ru": str(row.get("gift_title_ru") or "").strip(),
            "title_en": str(row.get("gift_title_en") or "").strip(),
            "description_uz": str(row.get("gift_description_uz") or row.get("gift_description") or "").strip(),
            "description_ru": str(row.get("gift_description_ru") or "").strip(),
            "description_en": str(row.get("gift_description_en") or "").strip(),
            "image_url": row.get("gift_image_url"),
            "price_dcoin": float(row.get("gift_price_dcoin") or row.get("amount_spent") or 0.0),
            "required_tickets": max(1, int(row.get("gift_required_tickets") or meta.get("required_tickets") or 1)),
            "is_payment_discount": bool(int(row.get("gift_is_payment_discount") or meta.get("is_payment_discount") or 0) == 1),
            "payment_discount_percent": max(0.0, min(100.0, float(row.get("gift_payment_discount_percent") or meta.get("payment_discount_percent") or 0.0))),
        } if item_type in {"gift", "chest"} else None,
    }


def _admin_purchase_web_recipient_ids() -> list[int]:
    admin_chat_ids = [str(int(x)) for x in ((ADMIN_CHAT_IDS or []) + (LIMITED_ADMIN_CHAT_IDS or [])) if int(x or 0) > 0]
    clauses = ["COALESCE(login_type, 0)=4", "LOWER(COALESCE(login_id, '')) LIKE 'admin%'"]
    params: list[Any] = []
    if admin_chat_ids:
        placeholders = ", ".join(["?"] * len(admin_chat_ids))
        clauses.append(f"CAST(COALESCE(telegram_id, '') AS TEXT) IN ({placeholders})")
        params.extend(admin_chat_ids)
        clauses.append(f"CAST(id AS TEXT) IN ({placeholders})")
        params.extend(admin_chat_ids)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"SELECT id FROM users WHERE {' OR '.join(clauses)} LIMIT 200",
            tuple(params),
        )
        return list(dict.fromkeys(int(row.get("id") or 0) for row in (cur.fetchall() or []) if int(row.get("id") or 0) > 0))
    finally:
        conn.close()


def _claim_admin_purchase_telegram_notification(source_key: str, chat_id: int) -> bool:
    source = str(source_key or "").strip()
    cid = int(chat_id or 0)
    if not source or cid <= 0:
        return False
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS admin_purchase_telegram_notifications (
                id BIGSERIAL PRIMARY KEY,
                source_key TEXT NOT NULL,
                chat_id BIGINT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(source_key, chat_id)
            )
            """
        )
        cur.execute(
            """
            INSERT INTO admin_purchase_telegram_notifications(source_key, chat_id, created_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(source_key, chat_id) DO NOTHING
            """,
            (source, cid),
        )
        claimed = (getattr(cur, "rowcount", 0) or 0) > 0
        conn.commit()
        return claimed
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("admin purchase telegram claim failed source=%s chat_id=%s", source, cid)
        return False
    finally:
        conn.close()


async def _notify_admins_purchase_created(
    *,
    buyer: dict,
    item_type: str,
    item_title: str,
    amount_spent: float,
    balance_after: float | None = None,
    purchase_history_id: int | None = None,
    item_id: int | None = None,
    source_page: str | None = None,
) -> None:
    buyer_id = int((buyer or {}).get("id") or 0)
    purchase_id = int(purchase_history_id or 0)
    title = str(item_title or "").strip() or "Xarid"
    source = f"purchase:{purchase_id}" if purchase_id > 0 else f"purchase:{str(item_type or 'other').lower()}:{buyer_id}:{int(item_id or 0)}"
    when_text = datetime.now(pytz.timezone("Asia/Tashkent")).strftime("%Y-%m-%d %H:%M")
    amount = float(amount_spent or 0.0)
    item_label = {
        "chest": "Sandiq",
        "gift": "Sovg'a",
        "book": "Kitob",
    }.get(str(item_type or "").strip().lower(), str(item_type or "Boshqa"))
    balance_line = f"\n💰 Qolgan balans: {float(balance_after):.1f} D'coin" if balance_after is not None else ""
    message = (
        "🛒 Yangi xarid!\n\n"
        f"🎁 Mahsulot: {title}\n"
        f"📦 Turi: {item_label}\n"
        f"👤 Xaridor: {_display_name(buyer)}\n"
        f"🆔 Login ID: {str((buyer or {}).get('login_id') or '-')}\n"
        f"📞 Telefon: {str((buyer or {}).get('phone') or '-')}\n"
        f"💎 Narx: {amount:.1f} D'coin"
        f"{balance_line}\n"
        f"🕒 Vaqt: {when_text}\n\n"
        "📲 Admin paneldagi “Xaridlar” bo'limidan batafsil tekshiring."
    )
    target_url = "/?role=admin&section=purchases"

    web_recipients = _safe_call(_admin_purchase_web_recipient_ids, []) or []
    if web_recipients:
        conn = get_conn()
        cur = conn.cursor()
        try:
            for admin_user_id in web_recipients:
                _payment_upsert_web_notification(
                    cur,
                    user_id=int(admin_user_id),
                    notification_type="purchase_created",
                    title="🛒 Yangi xarid",
                    message=message,
                    button_text="🛒 Xaridlarni ko'rish",
                    button_url=target_url,
                    target_screen="purchases",
                    source_key=source,
                    meta={
                        "buyer_user_id": buyer_id,
                        "item_type": str(item_type or "other"),
                        "item_id": int(item_id or 0),
                        "purchase_history_id": purchase_id,
                        "source_page": source_page,
                    },
                )
                _invalidate_notification_unread_count(int(admin_user_id))
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            logger.exception("admin purchase web notification failed purchase_id=%s", purchase_id)
        finally:
            conn.close()

    token = (os.getenv("ADMIN_BOT_TOKEN") or "").strip()
    admin_chat_ids = list(dict.fromkeys([int(x) for x in ((ADMIN_CHAT_IDS or []) + (LIMITED_ADMIN_CHAT_IDS or [])) if int(x or 0) > 0]))
    sent = 0
    failed = 0
    if token and admin_chat_ids:
        button_url = f"{WEBAPP_URL}{target_url}" if WEBAPP_URL else None
        for chat_id in admin_chat_ids:
            if not _claim_admin_purchase_telegram_notification(source, int(chat_id)):
                continue
            try:
                ok = await _send_telegram_text(
                    token,
                    str(chat_id),
                    message,
                    button_text="🛒 Xaridlarni ko'rish" if button_url else None,
                    button_url=button_url,
                    button_web_app=True,
                )
                sent += 1 if ok else 0
                failed += 0 if ok else 1
            except Exception:
                failed += 1
                logger.exception("admin purchase telegram notification failed chat_id=%s purchase_id=%s", chat_id, purchase_id)
    logger.info(
        "purchase_admin_notification item_type=%s purchase_id=%s web=%s telegram_sent=%s telegram_failed=%s",
        str(item_type or "other"),
        purchase_id,
        len(web_recipients),
        sent,
        failed,
    )


def _ensure_user_web_columns() -> None:
    conn = get_conn()
    cur = conn.cursor()
    def _apply_timeouts() -> None:
        try:
            # Session-level for this connection, so timeouts survive per-statement commits.
            cur.execute("SET lock_timeout = '3000ms'")
            cur.execute("SET statement_timeout = '20000ms'")
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass

    _apply_timeouts()
    columns = (
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS placement_required INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS placement_subject TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS review_wait_required INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS can_upload_daily_tests INTEGER DEFAULT 1",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS can_generate_ai INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS can_upload_books INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS session_version INTEGER DEFAULT 1",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS active_device_id TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS profile_image_url TEXT",
        "ALTER TABLE web_user_sessions ADD COLUMN IF NOT EXISTS device_model TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_enrollment_required INTEGER DEFAULT 1",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_id_required INTEGER DEFAULT 1",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_id_enrolled INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_id_status TEXT DEFAULT 'not_started'",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_profile_status TEXT DEFAULT 'pending'",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_profile_version INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS public_offer_agreed INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS instagram_url TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS telegram_url TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_enrolled_at TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_last_verified_at TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_verification_method TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_match_threshold DOUBLE PRECISION DEFAULT 0.82",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_id_expires_at TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_total_violations INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS face_last_violation_at TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS proctoring_required INTEGER DEFAULT 1",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS proctoring_block_reason TEXT",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS proctoring_hold_until TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS proctoring_blocked_until TIMESTAMP",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS proctoring_risk_score DOUBLE PRECISION DEFAULT 0",
        "ALTER TABLE videos ADD COLUMN IF NOT EXISTS dislike_count INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS family_discount_enabled INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS family_anchor_student_id INTEGER",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS multi_group_discount_opt_in INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS referral_student_id INTEGER",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS free_access INTEGER DEFAULT 0",
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP",
    )
    existing_columns: set[str] = set()
    is_postgres = bool(str(DATABASE_URL or "").strip().lower().startswith(("postgresql://", "postgres://")))
    if is_postgres:
        # Startup safety: if `users` is lock-busy, skip this migration pass and
        # allow API boot. We can retry on next startup/background paths.
        try:
            _apply_timeouts()
            cur.execute("LOCK TABLE users IN ACCESS EXCLUSIVE MODE NOWAIT")
            conn.rollback()
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            logger.warning("_ensure_user_web_columns skipped this startup (users lock busy): %s", str(e))
            conn.close()
            return
        try:
            _apply_timeouts()
            cur.execute(
                """
                SELECT column_name
                FROM information_schema.columns
                WHERE table_name='users'
                """
            )
            existing_columns = {str((row or {}).get("column_name") or "").strip().lower() for row in (cur.fetchall() or [])}
            conn.commit()
            logger.info("_ensure_user_web_columns existing_columns=%s", len(existing_columns))
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            existing_columns = set()

    def _extract_added_column(sql_text: str) -> str | None:
        m = re.search(r"ADD\\s+COLUMN(?:\\s+IF\\s+NOT\\s+EXISTS)?\\s+([a-zA-Z_][a-zA-Z0-9_]*)", str(sql_text), flags=re.IGNORECASE)
        if not m:
            return None
        return str(m.group(1) or "").strip().lower() or None

    for sql in columns:
        col_name = _extract_added_column(sql)
        if col_name and col_name in existing_columns:
            continue
        try:
            _apply_timeouts()
            cur.execute(sql)
            conn.commit()
            if col_name:
                existing_columns.add(col_name)
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            fallback = sql.replace(" IF NOT EXISTS", "")
            try:
                _apply_timeouts()
                cur.execute(fallback)
                conn.commit()
                if col_name:
                    existing_columns.add(col_name)
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
    try:
        _apply_timeouts()
        cur.execute("SELECT 1 FROM users WHERE session_version IS NULL OR session_version < 1 LIMIT 1")
        needs_backfill = cur.fetchone() is not None
        conn.commit()
        if needs_backfill:
            _apply_timeouts()
            cur.execute("UPDATE users SET session_version=1 WHERE session_version IS NULL OR session_version < 1")
            conn.commit()
            logger.info("_ensure_user_web_columns session_version backfill=done")
        else:
            logger.info("_ensure_user_web_columns session_version backfill=skipped")
    except Exception as e:
        logger.warning("_ensure_user_web_columns session_version backfill failed: %s", str(e))
        try:
            conn.rollback()
        except Exception:
            pass
    conn.close()


def _ensure_referral_reward_history_schema() -> None:
    conn = get_conn()
    cur = conn.cursor()
    statements = (
        """
        CREATE TABLE IF NOT EXISTS referral_reward_history (
            id BIGSERIAL PRIMARY KEY,
            referred_user_id BIGINT NOT NULL UNIQUE,
            referral_user_id BIGINT NOT NULL,
            reward_dpoints DOUBLE PRECISION NOT NULL DEFAULT 0,
            created_by_admin_id BIGINT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
        """,
        "CREATE UNIQUE INDEX IF NOT EXISTS ux_referral_reward_referred_user ON referral_reward_history(referred_user_id)",
    )
    for sql in statements:
        try:
            cur.execute(sql)
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
    # Part-4 refund audit columns (safe on fresh DB; idempotent on existing DB).
    for alter_sql in (
        "ALTER TABLE payment_refunds ADD COLUMN refund_type TEXT",
        "ALTER TABLE payment_refunds ADD COLUMN status_before TEXT",
        "ALTER TABLE payment_refunds ADD COLUMN status_after TEXT",
        "ALTER TABLE payment_refunds ADD COLUMN debt_after DOUBLE PRECISION",
        "ALTER TABLE payment_refunds ADD COLUMN overpayment_after DOUBLE PRECISION",
        "ALTER TABLE payment_refunds ADD COLUMN previous_overpayment_amount DOUBLE PRECISION",
    ):
        try:
            cur.execute(alter_sql)
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
    conn.close()


def _drop_legacy_email_artifacts() -> None:
    """Hard cleanup for deprecated email service schema artifacts."""
    conn = get_conn()
    cur = conn.cursor()
    try:
        try:
            cur.execute("SET lock_timeout = '3000ms'")
            cur.execute("SET statement_timeout = '20000ms'")
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
        try:
            cur.execute("DROP TABLE IF EXISTS web_email_audit")
        except Exception:
            pass
        try:
            cur.execute("ALTER TABLE users DROP COLUMN IF EXISTS email")
            conn.commit()
            conn.close()
            return
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass

        conn.commit()
    finally:
        conn.close()


def _execute_ddl_candidates(cur, candidates: list[str]) -> None:
    last_error: Exception | None = None
    items = [str(sql or "").strip() for sql in candidates if str(sql or "").strip()]
    if not items:
        return
    is_postgres = bool(str(DATABASE_URL or "").strip().lower().startswith(("postgresql://", "postgres://")))
    if is_postgres:
        # Paired call sites pass PostgreSQL first and SQLite second. Do not try
        # AUTOINCREMENT fallbacks on production Postgres after a transient DDL
        # race; it hides the useful error and can kill one worker on startup.
        items = items[:1]
    elif len(items) > 1:
        items = items[1:]
    for sql in items:
        try:
            cur.execute(sql)
            return
        except Exception as exc:
            last_error = exc
    if last_error:
        raise last_error


def _ensure_web_tables(force: bool = False) -> None:
    global _web_tables_ensured
    if _web_tables_ensured and not force:
        return
    if not _web_tables_ensure_lock.acquire(blocking=False):
        return
    try:
        if _web_tables_ensured and not force:
            return
        _ensure_web_tables_inner()
        _web_tables_ensured = True
    finally:
        _web_tables_ensure_lock.release()


def _ensure_group_web_columns() -> None:
    conn = get_conn()
    cur = conn.cursor()
    columns = (
        "ALTER TABLE groups ADD COLUMN IF NOT EXISTS telegram_group_url TEXT",
    )
    for col_sql in columns:
        try:
            cur.execute(col_sql)
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
    conn.commit()
    conn.close()


