def _migrate_legacy_feedback_rows(cur, conn) -> None:
    try:
        cur.execute(
            """
            SELECT id, user_id, message_text, is_anonymous, created_at
            FROM web_feedback_messages
            WHERE created_at >= ?
            ORDER BY id ASC
            """,
            (datetime.utcnow() - timedelta(days=190),),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    except Exception:
        return
    for row in rows:
        legacy_id = int(row.get("id") or 0)
        user_id = int(row.get("user_id") or 0)
        if legacy_id <= 0 or user_id <= 0:
            continue
        try:
            cur.execute("SELECT id FROM feedback_messages WHERE legacy_feedback_id=? LIMIT 1", (legacy_id,))
            if cur.fetchone():
                continue
            cur.execute(
                """
                INSERT INTO feedback_threads(user_id, status, created_at, updated_at)
                VALUES (?, 'Yangi', COALESCE(?, CURRENT_TIMESTAMP), COALESCE(?, CURRENT_TIMESTAMP))
                ON CONFLICT(user_id) DO UPDATE SET updated_at=GREATEST(feedback_threads.updated_at, EXCLUDED.updated_at)
                """,
                (user_id, row.get("created_at"), row.get("created_at")),
            )
            cur.execute("SELECT id FROM feedback_threads WHERE user_id=? LIMIT 1", (user_id,))
            thread_id = int((cur.fetchone() or {}).get("id") or 0)
            if thread_id <= 0:
                continue
            cur.execute(
                """
                INSERT INTO feedback_messages(thread_id, sender_user_id, sender_role, message_text, is_anonymous_choice, legacy_feedback_id, created_at)
                VALUES (?, ?, 'student', ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP))
                """,
                (
                    thread_id,
                    user_id,
                    str(row.get("message_text") or "")[:4000],
                    1 if int(row.get("is_anonymous") or 0) == 1 else 0,
                    legacy_id,
                    row.get("created_at"),
                ),
            )
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass


CHAT_IMAGE_MAX_BYTES = 10 * 1024 * 1024
CHAT_IMAGE_MIME_BY_EXT = {
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".png": "image/png",
    ".webp": "image/webp",
}
DIAMONDVOY_RETENTION_DAYS = 7
FEEDBACK_RETENTION_DAYS = 186


def _chat_media_secret() -> bytes:
    raw = (
        os.getenv("CHAT_MEDIA_SECRET")
        or os.getenv("MEDIA_STREAM_TOKEN_SECRET")
        or SECRET_KEY
        or "diamond-chat-media"
    )
    return str(raw).encode("utf-8")


def _chat_media_signature(filename: str) -> str:
    safe = Path(str(filename or "")).name
    return hmac.new(_chat_media_secret(), safe.encode("utf-8"), hashlib.sha256).hexdigest()[:32]


def _chat_media_url(filename: str) -> str:
    safe = Path(str(filename or "")).name
    return f"/chats/media/{quote(safe)}?sig={_chat_media_signature(safe)}"


def _chat_media_filename_from_url(url: str) -> str | None:
    try:
        parsed = urlparse(str(url or ""))
        name = Path(parsed.path).name
        if not name or Path(name).name != name:
            return None
        return name
    except Exception:
        return None


def _chat_media_absolute_url(url: str, request: Request | None = None) -> str:
    raw = str(url or "").strip()
    if not raw:
        return raw
    if raw.startswith("http://") or raw.startswith("https://") or raw.startswith("data:"):
        return raw
    base = WEBAPP_URL
    if request is not None and not base:
        base = str(request.base_url).rstrip("/")
    if not base:
        return raw
    return f"{base}{raw if raw.startswith('/') else '/' + raw}"


def _chat_media_data_url(url: str) -> str:
    filename = _chat_media_filename_from_url(url)
    if not filename:
        raise HTTPException(status_code=400, detail="Rasm yuklanmadi. Qayta urinib ko‘ring.")
    path = CHAT_UPLOAD_DIR / filename
    if not path.exists() or not path.is_file():
        raise HTTPException(status_code=404, detail="Rasm topilmadi")
    ext = path.suffix.lower()
    mime_type = CHAT_IMAGE_MIME_BY_EXT.get(ext)
    if not mime_type:
        raise HTTPException(status_code=422, detail="Rasm turi noto‘g‘ri")
    raw = path.read_bytes()
    if not raw or len(raw) > CHAT_IMAGE_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Rasm hajmi juda katta")
    return f"data:{mime_type};base64,{base64.b64encode(raw).decode('ascii')}"


def _chat_media_metadata(url: str) -> tuple[str | None, str | None, int]:
    filename = _chat_media_filename_from_url(url)
    if not filename:
        return None, None, 0
    path = CHAT_UPLOAD_DIR / filename
    mime_type = mimetypes.guess_type(filename)[0] or ""
    size = int(path.stat().st_size) if path.exists() and path.is_file() else 0
    return filename, mime_type, size


def _validate_chat_image_urls(image_urls: list[str] | None) -> list[str]:
    cleaned: list[str] = []
    for raw in (image_urls or [])[:3]:
        url = str(raw or "").strip()
        if not url:
            continue
        parsed = urlparse(url)
        filename = Path(parsed.path).name
        sig = (parse_qs(parsed.query or "").get("sig") or [""])[0]
        if not filename or sig != _chat_media_signature(filename):
            raise HTTPException(status_code=403, detail="Rasm yuklanmadi. Qayta urinib ko‘ring.")
        ext = Path(filename).suffix.lower()
        if ext not in CHAT_IMAGE_MIME_BY_EXT:
            raise HTTPException(status_code=422, detail="Rasm turi noto‘g‘ri")
        path = CHAT_UPLOAD_DIR / filename
        if not path.exists() or not path.is_file():
            raise HTTPException(status_code=404, detail="Rasm topilmadi")
        if int(path.stat().st_size) > CHAT_IMAGE_MAX_BYTES:
            raise HTTPException(status_code=413, detail="Rasm hajmi juda katta")
        cleaned.append(_chat_media_url(filename))
    if image_urls and len(image_urls) > 3:
        raise HTTPException(status_code=400, detail="Bir xabarda 3 tagacha rasm yuborish mumkin")
    return cleaned


async def _upload_chat_image_file(file: UploadFile, user_id: int) -> str:
    content_type = str(file.content_type or "").split(";")[0].strip().lower()
    raw = await file.read()
    if not raw:
        raise HTTPException(status_code=400, detail="Rasm yuklanmadi. Qayta urinib ko‘ring.")
    if len(raw) > CHAT_IMAGE_MAX_BYTES:
        raise HTTPException(status_code=413, detail="Rasm hajmi juda katta")
    ext = Path(file.filename or "").suffix.lower()
    expected = CHAT_IMAGE_MIME_BY_EXT.get(ext)
    if not expected or content_type not in {expected, "image/jpg" if expected == "image/jpeg" else expected}:
        raise HTTPException(status_code=422, detail="Rasm turi noto‘g‘ri")
    filename = f"chat_{int(user_id)}_{datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(6)}{ext}"
    path = CHAT_UPLOAD_DIR / filename
    with open(path, "wb") as handle:
        handle.write(raw)
    return _chat_media_url(filename)


def _normalize_feedback_status(value: str | None) -> str:
    raw = str(value or "").strip()
    low = raw.lower()
    if low in {"reviewing", "korilmoqda", "ko'rilmoqda", "ko‘rilmoqda"}:
        return "Ko‘rilmoqda"
    if low in {"resolved", "done", "hal qilindi", "hal_qilindi"}:
        return "Hal qilindi"
    return "Yangi"


def _final_chat_cleanup_if_due(*, force: bool = False) -> int:
    global _FINAL_CHAT_CLEANUP_LAST_RUN_MONOTONIC
    now_mono = time.monotonic()
    if not force and (now_mono - float(_FINAL_CHAT_CLEANUP_LAST_RUN_MONOTONIC or 0.0)) < 600.0:
        return 0
    _FINAL_CHAT_CLEANUP_LAST_RUN_MONOTONIC = now_mono
    removed = 0
    _safe_call(lambda: _diamondvoy_cleanup_expired_chats_if_due(force=force), 0)
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cutoff = datetime.utcnow() - timedelta(days=DIAMONDVOY_RETENTION_DAYS)
        cur.execute("SELECT id FROM diamondvoy_chats WHERE (expires_at IS NOT NULL AND expires_at < CURRENT_TIMESTAMP) OR updated_at < ?", (cutoff,))
        chat_ids = [int((dict(r) if not isinstance(r, dict) else r).get("id") or 0) for r in (cur.fetchall() or [])]
        chat_ids = [cid for cid in chat_ids if cid > 0]
        for cid in chat_ids[:500]:
            cur.execute("DELETE FROM diamondvoy_attachments WHERE chat_id=?", (cid,))
            cur.execute("DELETE FROM diamondvoy_chat_messages WHERE chat_id=?", (cid,))
            cur.execute("DELETE FROM diamondvoy_chats WHERE id=?", (cid,))
            removed += int(getattr(cur, "rowcount", 0) or 0)
        feedback_cutoff = datetime.utcnow() - timedelta(days=FEEDBACK_RETENTION_DAYS)
        cur.execute("SELECT id FROM feedback_messages WHERE created_at < ? LIMIT 500", (feedback_cutoff,))
        old_msg_ids = [int((dict(r) if not isinstance(r, dict) else r).get("id") or 0) for r in (cur.fetchall() or [])]
        for mid in [x for x in old_msg_ids if x > 0]:
            cur.execute("DELETE FROM feedback_attachments WHERE message_id=?", (mid,))
            cur.execute("DELETE FROM feedback_messages WHERE id=?", (mid,))
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        conn.close()
    return removed


def _diamondvoy_settings_payload() -> dict[str, Any]:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT free_limit, text_cost, image_cost, voice_room_price, updated_at FROM diamondvoy_settings WHERE id=1 LIMIT 1")
        row = dict(cur.fetchone() or {})
        return {
            "free_limit": int(row.get("free_limit") if row.get("free_limit") is not None else 3),
            "text_cost": float(row.get("text_cost") if row.get("text_cost") is not None else 5.0),
            "image_cost": float(row.get("image_cost") if row.get("image_cost") is not None else 10.0),
            "voice_room_price": float(row.get("voice_room_price") if row.get("voice_room_price") is not None else 50.0),
            "updated_at": row.get("updated_at"),
        }
    finally:
        conn.close()


def _diamondvoy_set_settings(payload: DiamondvoySettingsRequest, admin_id: int) -> dict[str, Any]:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE diamondvoy_settings
            SET free_limit=?, text_cost=?, image_cost=?, voice_room_price=?, updated_by=?, updated_at=CURRENT_TIMESTAMP
            WHERE id=1
            """,
            (int(payload.free_limit), float(payload.text_cost), float(payload.image_cost), float(payload.voice_room_price), int(admin_id)),
        )
        if int(getattr(cur, "rowcount", 0) or 0) <= 0:
            cur.execute(
                """
                INSERT INTO diamondvoy_settings(id, free_limit, text_cost, image_cost, voice_room_price, updated_by, updated_at)
                VALUES (1, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                """,
                (int(payload.free_limit), float(payload.text_cost), float(payload.image_cost), float(payload.voice_room_price), int(admin_id)),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    return _diamondvoy_settings_payload()


def _diamondvoy_insert_message(chat_id: int, role: str, content: str) -> dict | None:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    role_clean = str(role or "").strip().lower()
    if role_clean not in {"user", "assistant", "system"}:
        role_clean = "assistant"
    text = str(content or "")[:32000]
    try:
        cur.execute(
            """
            INSERT INTO diamondvoy_chat_messages(chat_id, role, content)
            VALUES (?, ?, ?)
            """,
            (int(chat_id), role_clean, text),
        )
        message_id = int(getattr(cur, "lastrowid", 0) or 0)
        if not message_id:
            cur.execute("SELECT currval(pg_get_serial_sequence('diamondvoy_chat_messages', 'id')) as id")
            message_id = int((cur.fetchone() or {}).get("id") or 0)
        cur.execute("UPDATE diamondvoy_chats SET updated_at=CURRENT_TIMESTAMP WHERE id=?", (int(chat_id),))
        conn.commit()
        cur.execute("SELECT user_id FROM diamondvoy_chats WHERE id=? LIMIT 1", (int(chat_id),))
        owner_row = cur.fetchone() or {}
        owner_id = int(owner_row.get("user_id") or 0)
        if owner_id > 0:
            _clear_user_media_caches(owner_id)
        cur.execute("SELECT id, chat_id, role, content, created_at FROM diamondvoy_chat_messages WHERE id=? LIMIT 1", (message_id,))
        row = cur.fetchone()
        return dict(row) if row else None
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("diamondvoy message insert failed chat_id=%s", chat_id)
        return None
    finally:
        conn.close()


def _diamondvoy_insert_attachments(chat_id: int, message_id: int, image_urls: list[str]) -> None:
    _ensure_final_chat_schema()
    if not image_urls:
        return
    conn = get_conn()
    cur = conn.cursor()
    try:
        for url in image_urls[:3]:
            clean_url = str(url or "").strip()
            if not clean_url:
                continue
            filename, mime_type, size = _chat_media_metadata(clean_url)
            cur.execute(
                """
                INSERT INTO diamondvoy_attachments(chat_id, message_id, file_url, file_path, mime_type, size_bytes, created_at)
                VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                """,
                (int(chat_id), int(message_id), clean_url, filename, mime_type, int(size or 0)),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("diamondvoy attachment insert failed chat_id=%s message_id=%s", chat_id, message_id)
    finally:
        conn.close()


def _diamondvoy_message_attachments(message_ids: list[int]) -> dict[int, list[dict[str, Any]]]:
    ids = [int(mid) for mid in (message_ids or []) if int(mid) > 0]
    if not ids:
        return {}
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    out: dict[int, list[dict[str, Any]]] = {}
    try:
        for mid in ids:
            cur.execute(
                """
                SELECT id, message_id, file_url, mime_type, size_bytes, created_at
                FROM diamondvoy_attachments
                WHERE message_id=?
                ORDER BY id ASC
                """,
                (mid,),
            )
            out[mid] = [
                {
                    "id": int(row.get("id") or 0),
                    "url": str(row.get("file_url") or ""),
                    "mime_type": row.get("mime_type"),
                    "size_bytes": int(row.get("size_bytes") or 0),
                    "created_at": row.get("created_at"),
                }
                for row in [dict(r) for r in (cur.fetchall() or [])]
            ]
    finally:
        conn.close()
    return out


def _diamondvoy_serialize_message_final(row: dict, attachments_map: dict[int, list[dict[str, Any]]] | None = None) -> dict:
    mid = int(row.get("id") or 0)
    return {
        "id": mid,
        "chat_id": int(row.get("chat_id") or 0),
        "role": str(row.get("role") or "assistant"),
        "content": str(row.get("content") or ""),
        "attachments": (attachments_map or {}).get(mid, []),
        "created_at": row.get("created_at"),
    }


def _diamondvoy_serialize_chat_final(row: dict) -> dict:
    payload = _diamondvoy_serialize_chat_row(row)
    payload["title"] = str(row.get("title") or "").strip() or "Yangi chat"
    payload["chat_type"] = "diamondvoy"
    payload["expires_at"] = row.get("expires_at")
    payload["pinned_at"] = row.get("pinned_at")
    payload["pinned"] = bool(row.get("pinned_at"))
    return payload


def _diamondvoy_create_chat_for_user(user_id: int, title: str | None = None) -> dict:
    _ensure_final_chat_schema()
    created = _safe_call(lambda: create_diamondvoy_chat(int(user_id), (title or "Yangi chat")), None)
    if not created:
        raise HTTPException(status_code=500, detail="Could not create Diamondvoy chat")
    chat_id = int(created.get("id") or 0)
    expires_at = datetime.utcnow() + timedelta(days=DIAMONDVOY_RETENTION_DAYS)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE diamondvoy_chats
            SET title=COALESCE(title, 'Yangi chat'), expires_at=COALESCE(expires_at, ?), deleted_at=NULL
            WHERE id=?
            """,
            (expires_at, chat_id),
        )
        conn.commit()
        cur.execute(
            """
            SELECT c.id, c.user_id, c.title, c.created_at, c.updated_at, c.expires_at,
                   NULL AS last_message_preview
            FROM diamondvoy_chats c
            WHERE c.id=?
            LIMIT 1
            """,
            (chat_id,),
        )
        row = cur.fetchone()
        _clear_user_media_caches(int(user_id))
        return dict(row or created)
    finally:
        conn.close()


def _diamondvoy_get_chat_for_user_final(chat_id: int, user_id: int) -> dict:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, user_id, title, created_at, updated_at, expires_at, deleted_at, pinned_at
            FROM diamondvoy_chats
            WHERE id=?
            LIMIT 1
            """,
            (int(chat_id),),
        )
        row = dict(cur.fetchone() or {})
    finally:
        conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="Diamondvoy chat not found")
    if int(row.get("user_id") or 0) != int(user_id):
        raise HTTPException(status_code=403, detail="Chat does not belong to current user")
    if row.get("deleted_at"):
        raise HTTPException(status_code=410, detail="Bu chat muddati tugagan.")
    expires = _parse_utc_timestamp(str(row.get("expires_at") or "")) if row.get("expires_at") else None
    if expires and _now_utc() > expires:
        _safe_call(lambda: delete_diamondvoy_chat_for_user(int(user_id), int(chat_id)), False)
        raise HTTPException(status_code=410, detail="Bu chat muddati tugagan.")
    return row


def _diamondvoy_list_chats_final(user_id: int, limit: int = 30) -> list[dict]:
    cache_key = (int(user_id), max(1, min(60, int(limit or 30))))
    cached = _short_cache_get(_DIAMONDVOY_CHAT_LIST_CACHE, cache_key)
    if isinstance(cached, list):
        return cached
    _final_chat_cleanup_if_due()
    _ensure_final_chat_schema()
    lim = max(1, min(60, int(limit or 30)))
    cutoff = datetime.utcnow() - timedelta(days=DIAMONDVOY_RETENTION_DAYS)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
                c.id,
                c.user_id,
                COALESCE(NULLIF(c.title, ''), 'Yangi chat') AS title,
                c.created_at,
                c.updated_at,
                c.expires_at,
                c.pinned_at,
                (
                    SELECT m.content
                    FROM diamondvoy_chat_messages m
                    WHERE m.chat_id = c.id
                    ORDER BY m.id DESC
                    LIMIT 1
                ) AS last_message_preview
            FROM diamondvoy_chats c
            WHERE c.user_id=?
              AND (c.deleted_at IS NULL)
              AND (c.expires_at IS NULL OR c.expires_at > CURRENT_TIMESTAMP)
              AND c.updated_at >= ?
            ORDER BY
                CASE WHEN c.pinned_at IS NULL THEN 0 ELSE 1 END DESC,
                c.pinned_at DESC,
                c.updated_at DESC,
                c.id DESC
            LIMIT ?
            """,
            (int(user_id), cutoff, lim),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
        return _short_cache_set(_DIAMONDVOY_CHAT_LIST_CACHE, cache_key, rows, ttl_seconds=6.0, max_items=4096)
    finally:
        conn.close()


def _diamondvoy_list_messages_final(chat_id: int, limit: int = 120) -> list[dict]:
    _ensure_final_chat_schema()
    lim = max(1, min(300, int(limit or 120)))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, chat_id, role, content, created_at
            FROM diamondvoy_chat_messages
            WHERE chat_id=?
            ORDER BY id DESC
            LIMIT ?
            """,
            (int(chat_id), lim),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
        rows.reverse()
        return rows
    finally:
        conn.close()


def _diamondvoy_set_chat_pin_final(chat_id: int, user_id: int, pinned: bool) -> dict:
    _diamondvoy_get_chat_for_user_final(int(chat_id), int(user_id))
    conn = get_conn()
    cur = conn.cursor()
    try:
        if pinned:
            cur.execute(
                "UPDATE diamondvoy_chats SET pinned_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=? AND deleted_at IS NULL",
                (int(chat_id), int(user_id)),
            )
        else:
            cur.execute(
                "UPDATE diamondvoy_chats SET pinned_at=NULL WHERE id=? AND user_id=? AND deleted_at IS NULL",
                (int(chat_id), int(user_id)),
            )
        conn.commit()
        cur.execute(
            """
            SELECT id, user_id, title, created_at, updated_at, expires_at, deleted_at, pinned_at
            FROM diamondvoy_chats
            WHERE id=? AND user_id=?
            LIMIT 1
            """,
            (int(chat_id), int(user_id)),
        )
        row = dict(cur.fetchone() or {})
        if not row:
            raise HTTPException(status_code=404, detail="Diamondvoy chat not found")
        _clear_user_media_caches(int(user_id))
        return row
    except HTTPException:
        raise
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("diamondvoy pin update failed chat_id=%s user_id=%s", chat_id, user_id)
        raise HTTPException(status_code=500, detail="Could not update chat")
    finally:
        conn.close()


def _diamondvoy_soft_delete_chat_final(chat_id: int, user_id: int) -> None:
    _diamondvoy_get_chat_for_user_final(int(chat_id), int(user_id))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "UPDATE diamondvoy_chats SET deleted_at=CURRENT_TIMESTAMP, pinned_at=NULL WHERE id=? AND user_id=? AND deleted_at IS NULL",
            (int(chat_id), int(user_id)),
        )
        conn.commit()
        _clear_user_media_caches(int(user_id))
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("diamondvoy chat delete failed chat_id=%s user_id=%s", chat_id, user_id)
        raise HTTPException(status_code=500, detail="Could not delete chat")
    finally:
        conn.close()


def _diamondvoy_apply_usage(user: dict, role: str, *, has_images: bool, has_text: bool) -> dict[str, Any]:
    if str(role or "").lower() != "student":
        return {"charged": False, "amount": 0.0, "free_used": False}
    user_id = int(user.get("id") or 0)
    settings = _diamondvoy_settings_payload()
    now = _now_utc()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT user_id, window_start, free_count_used, dcoin_spent FROM diamondvoy_usage WHERE user_id=? LIMIT 1", (user_id,))
        row = dict(cur.fetchone() or {})
        window_start = _parse_utc_timestamp(str(row.get("window_start") or "")) if row.get("window_start") else None
        free_used = int(row.get("free_count_used") or 0)
        if not row or window_start is None or now - window_start >= timedelta(hours=24):
            window_start = now
            free_used = 0
            cur.execute(
                """
                INSERT INTO diamondvoy_usage(user_id, window_start, free_count_used, dcoin_spent, updated_at)
                VALUES (?, ?, 0, 0, CURRENT_TIMESTAMP)
                ON CONFLICT(user_id) DO UPDATE SET window_start=excluded.window_start, free_count_used=0, updated_at=CURRENT_TIMESTAMP
                """,
                (user_id, window_start),
            )
            conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        row = {}
        window_start = now
        free_used = 0
    finally:
        conn.close()

    # Limitni qat'iy tekshirish
    current_limit = int(settings.get("free_limit") or 3)
    if free_used >= current_limit:
        raise HTTPException(status_code=403, detail=f"DiamondVoy uchun kunlik {current_limit} ta so'rov limitingiz tugadi.")

    # Har qanday so'rov limitdan bitta olib tashlaydi, d'coin olinmaydi
    charge_amount = 0.0
    should_increment_free = True

    conn = get_conn()
    cur = conn.cursor()
    try:
        if should_increment_free:
            cur.execute(
                """
                UPDATE diamondvoy_usage
                SET free_count_used=COALESCE(free_count_used, 0)+1, updated_at=CURRENT_TIMESTAMP
                WHERE user_id=?
                """,
                (user_id,),
            )
            if int(getattr(cur, "rowcount", 0) or 0) <= 0:
                cur.execute(
                    "INSERT INTO diamondvoy_usage(user_id, window_start, free_count_used, dcoin_spent, updated_at) VALUES (?, ?, 1, 0, CURRENT_TIMESTAMP)",
                    (user_id, window_start),
                )
        elif charge_amount > 0:
            cur.execute(
                """
                UPDATE diamondvoy_usage
                SET dcoin_spent=COALESCE(dcoin_spent, 0)+?, updated_at=CURRENT_TIMESTAMP
                WHERE user_id=?
                """,
                (charge_amount, user_id),
            )
            if int(getattr(cur, "rowcount", 0) or 0) <= 0:
                cur.execute(
                    "INSERT INTO diamondvoy_usage(user_id, window_start, free_count_used, dcoin_spent, updated_at) VALUES (?, ?, 0, ?, CURRENT_TIMESTAMP)",
                    (user_id, window_start, charge_amount),
                )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        conn.close()
    return {"charged": charge_amount > 0, "amount": charge_amount, "free_used": bool(should_increment_free)}


_DIAMONDVOY_MEMORY_STOPWORDS = {
    "the", "and", "for", "you", "are", "with", "this", "that", "what", "how", "why", "please", "about",
    "men", "sen", "siz", "shu", "bu", "ham", "bilan", "uchun", "nima", "qanday", "haqida", "menga", "qilib",
    "как", "что", "для", "это", "или", "меня", "тебя", "почему", "про", "мне", "пожалуйста",
}

_DIAMONDVOY_MEMORY_CANONICAL_PATTERNS: tuple[tuple[re.Pattern[str], str], ...] = tuple(
    (re.compile(pattern, re.I), replacement)
    for pattern, replacement in (
        (r"\b(present\s+simple|present\s+indefinite|hozirgi\s+oddiy\s+zamon\w*|настоящее\s+простое|present_simple)\b", " present_simple "),
        (r"\b(past\s+simple|o['‘]?tgan\s+oddiy\s+zamon\w*|прошедшее\s+простое|past_simple)\b", " past_simple "),
        (r"\b(future\s+simple|kelasi\s+oddiy\s+zamon\w*|будущее\s+простое|future_simple)\b", " future_simple "),
        (r"\b(present\s+continuous|present\s+progressive|hozirgi\s+davomiy\s+zamon\w*|настоящее\s+длительное|present_continuous)\b", " present_continuous "),
        (r"\b(present\s+perfect|hozirgi\s+tugallangan\s+zamon\w*|настоящее\s+совершенное|present_perfect)\b", " present_perfect "),
        (r"\b(conditionals?|if\s+clauses?|shart\s+gap|условн\w+|condition)\b", " conditional "),
        (r"\b(articles?|a\s+an\s+the|artikl\w*|артикл\w*)\b", " article "),
        (r"\b(prepositions?|predlog\w*|предлог\w*)\b", " preposition "),
        (r"\b(vocabulary|vocab|word\s+bank|so['‘]?z\w*|lug['‘]?at|лексик\w*|словар\w*)\b", " vocabulary "),
        (r"\b(grammar|grammatika|грамматик\w*)\b", " grammar "),
        (r"\b(reading|matn|tekst|текст|чтени\w*)\b", " reading "),
        (r"\b(writing|essay|insho|эссе|письмо)\b", " writing "),
        (r"\b(listening|audio|аудио|слушани\w*)\b", " listening "),
        (r"\b(speaking|gapirish|говорени\w*)\b", " speaking "),
        (r"\b(math|matematika|algebra|geometry|геометри\w*|математик\w*)\b", " math "),
        (r"\b(equation|tenglama\w*|уравнени\w*)\b", " equation "),
        (r"\b(homework|uyga\s+vazifa|домашн\w+\s+задани\w*)\b", " homework "),
        (r"\b(test|quiz|exam|imtihon|тест|экзамен)\b", " test "),
        (r"\b(ielts|cefr|sat|duolingo)\b", " exam_prep "),
        (r"\b(d['’]?coin|dcoin|coin|tanga|баланс|balance)\b", " dcoin "),
        (r"\b(d['’]?point|dpoint|reyting|rating|рейтинг)\b", " dpoint "),
        (r"\b(payment|to['‘]?lov|oplata|оплат\w*)\b", " payment "),
        (r"\b(support\s+lesson|support\s+dars|bron|booking|брон\w*)\b", " support_booking "),
        (r"\b(explain|tushuntir\w*|izohla\w*|объясн\w*)\b", " explain "),
        (r"\b(examples?|misol\w*|пример\w*)\b", " example "),
        (r"\b(rules?|formula|qoida\w*|формул\w*|правил\w*)\b", " rule "),
        (r"\b(difference|compare|farq\w*|сравн\w*|разниц\w*)\b", " compare "),
        (r"\b(translate|tarjima\w*|перевод\w*|переведи)\b", " translate "),
        (r"\b(solve|yech\w*|реши\w*|решени\w*)\b", " solve "),
        (r"\b(create|make|generate|tuz\w*|yarat\w*|созда\w*|состав\w*)\b", " create "),
    )
)


def _diamondvoy_memory_norm(text: str) -> str:
    clean = html.unescape(str(text or "")).lower()
    clean = clean.replace("o‘", "o'").replace("g‘", "g'").replace("ʼ", "'").replace("’", "'")
    clean = re.sub(r"https?://\S+", " ", clean)
    for pattern, replacement in _DIAMONDVOY_MEMORY_CANONICAL_PATTERNS:
        clean = pattern.sub(replacement, clean)
    clean = re.sub(r"[^\w\s'\-]+", " ", clean, flags=re.UNICODE)
    clean = re.sub(r"_{2,}", "_", clean)
    clean = re.sub(r"\s+", " ", clean).strip()
    return clean[:700]


def _diamondvoy_memory_stem(token: str) -> str:
    raw = str(token or "").strip().lower()
    if len(raw) <= 4:
        return raw
    if "_" in raw:
        return raw
    for suffix in (
        "larimizdan", "laringizdan", "larimiz", "laringiz", "lardan", "larning", "larni", "larga",
        "imizdan", "ingizdan", "ning", "dan", "lar", "imiz", "ingiz", "lari", "larni", "ni", "ga", "da",
        "ing", "ness", "tion", "sion", "ment", "able", "edly", "edly", "ed", "es", "s",
        "иями", "ами", "ями", "ого", "ему", "ыми", "ими", "ая", "ое", "ые", "ий", "ый", "ой", "ов", "ев",
    ):
        if raw.endswith(suffix) and len(raw) - len(suffix) >= 3:
            return raw[: -len(suffix)]
    return raw


def _diamondvoy_memory_tokens(norm: str) -> set[str]:
    return {
        _diamondvoy_memory_stem(part)
        for part in re.split(r"\s+", str(norm or "").strip())
        if len(part) >= 3 and part not in _DIAMONDVOY_MEMORY_STOPWORDS
    }


def _diamondvoy_memory_ngrams(norm: str, n: int = 4) -> set[str]:
    compact = re.sub(r"\s+", " ", str(norm or "").strip())
    if len(compact) < n:
        return {compact} if compact else set()
    return {compact[i : i + n] for i in range(0, len(compact) - n + 1)}


def _diamondvoy_memory_topic_keys(norm: str) -> set[str]:
    tokens = _diamondvoy_memory_tokens(norm)
    return {token for token in tokens if "_" in token or token in {"grammar", "vocabulary", "reading", "writing", "math", "equation", "payment", "dcoin", "dpoint", "test", "homework"}}


def _diamondvoy_memory_similarity(a: str, b: str) -> float:
    an = _diamondvoy_memory_norm(a)
    bn = _diamondvoy_memory_norm(b)
    if not an or not bn:
        return 0.0
    if an == bn:
        return 1.0
    if len(an) >= 18 and (an in bn or bn in an):
        return 0.92
    at = _diamondvoy_memory_tokens(an)
    bt = _diamondvoy_memory_tokens(bn)
    if not at or not bt:
        return difflib.SequenceMatcher(None, an, bn).ratio() * 0.55
    overlap = len(at & bt)
    union = len(at | bt)
    jaccard = overlap / union if union > 0 else 0.0
    containment = overlap / max(1, min(len(at), len(bt)))
    fuzzy_ratio = difflib.SequenceMatcher(None, an, bn).ratio()
    ag = _diamondvoy_memory_ngrams(an)
    bg = _diamondvoy_memory_ngrams(bn)
    ngram = len(ag & bg) / max(1, len(ag | bg)) if ag and bg else 0.0
    topic_a = _diamondvoy_memory_topic_keys(an)
    topic_b = _diamondvoy_memory_topic_keys(bn)
    topic_score = 0.0
    if topic_a or topic_b:
        topic_score = len(topic_a & topic_b) / max(1, len(topic_a | topic_b))
    score = (jaccard * 0.30) + (containment * 0.26) + (fuzzy_ratio * 0.16) + (ngram * 0.10) + (topic_score * 0.18)
    if topic_a & topic_b and containment >= 0.5:
        score += 0.08
    if topic_a and topic_b and not (topic_a & topic_b) and fuzzy_ratio < 0.88:
        score *= 0.72
    if overlap < 2 and fuzzy_ratio < 0.86 and not (topic_a & topic_b):
        score *= 0.55
    return max(0.0, min(1.0, score))


def _diamondvoy_infer_style(text: str, lang: str) -> dict[str, str]:
    low = str(text or "").lower()
    brevity = "normal"
    if any(marker in low for marker in ("qisqa", "short", "brief", "коротко", "qisqacha")):
        brevity = "short"
    elif any(marker in low for marker in ("batafsil", "detail", "подроб", "tushuntir", "explain")):
        brevity = "detailed"
    tone = "clear"
    if any(marker in low for marker in ("yo ", " aka", "brat", "iltimos", "pls", "😂", "😄")):
        tone = "friendly-casual"
    return {"preferred_language": (lang or "uz")[:2], "brevity": brevity, "tone": tone}


def _diamondvoy_upsert_user_style(user_id: int, text: str, lang: str) -> None:
    if int(user_id or 0) <= 0 or not str(text or "").strip():
        return
    _ensure_final_chat_schema()
    style = _diamondvoy_infer_style(text, lang)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO diamondvoy_user_style(user_id, preferred_language, brevity, tone, updated_at)
            VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(user_id) DO UPDATE SET
                preferred_language=excluded.preferred_language,
                brevity=excluded.brevity,
                tone=excluded.tone,
                updated_at=CURRENT_TIMESTAMP
            """,
            (int(user_id), style["preferred_language"], style["brevity"], style["tone"]),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
            cur.execute("SELECT user_id FROM diamondvoy_user_style WHERE user_id=?", (int(user_id),))
            if cur.fetchone():
                cur.execute(
                    "UPDATE diamondvoy_user_style SET preferred_language=?, brevity=?, tone=?, updated_at=CURRENT_TIMESTAMP WHERE user_id=?",
                    (style["preferred_language"], style["brevity"], style["tone"], int(user_id)),
                )
            else:
                cur.execute(
                    "INSERT INTO diamondvoy_user_style(user_id, preferred_language, brevity, tone, updated_at) VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)",
                    (int(user_id), style["preferred_language"], style["brevity"], style["tone"]),
                )
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
    finally:
        conn.close()


def _diamondvoy_user_style_prompt(user_id: int, lang: str) -> str:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "SELECT preferred_language, brevity, tone FROM diamondvoy_user_style WHERE user_id=? LIMIT 1",
            (int(user_id),),
        )
        row = dict(cur.fetchone() or {})
    finally:
        conn.close()
    preferred = str(row.get("preferred_language") or lang or "uz")[:2]
    brevity = str(row.get("brevity") or "normal")
    tone = str(row.get("tone") or "clear")
    return (
        "User style memory: adapt to this user's preferred style. "
        f"preferred_language={preferred}; brevity={brevity}; tone={tone}. "
        "If the user asks for a specific style in the current message, follow the current message first."
    )


def _diamondvoy_save_memory(
    *,
    user_id: int,
    role: str,
    question: str,
    answer: str,
    subject: str | None,
    chat_id: int,
) -> None:
    norm = _diamondvoy_memory_norm(question)
    clean_answer = sanitize_diamondvoy_reply(str(answer or "").strip())
    if int(user_id or 0) <= 0 or len(norm) < 8 or len(clean_answer) < 8:
        return
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO diamondvoy_memory(user_id, role, subject, question_norm, question_text, answer_text, source_chat_id, hit_count, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            """,
            (int(user_id), str(role or ""), subject, norm, str(question or "")[:2000], clean_answer[:12000], int(chat_id)),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("diamondvoy memory save failed user_id=%s chat_id=%s", user_id, chat_id)
    finally:
        conn.close()


def _diamondvoy_recent_memories(user_id: int, limit: int = 120) -> list[dict[str, Any]]:
    _ensure_final_chat_schema()
    conn = get_conn()
