    try:
        cur.execute(
            """
            SELECT id, role, subject, question_norm, question_text, answer_text, hit_count, updated_at
            FROM diamondvoy_memory
            WHERE user_id=?
            ORDER BY updated_at DESC, id DESC
            LIMIT ?
            """,
            (int(user_id), max(1, min(200, int(limit or 120)))),
        )
        return [dict(r) for r in (cur.fetchall() or [])]
    finally:
        conn.close()


