def _diamondvoy_find_cached_answer(user_id: int, question: str) -> dict[str, Any] | None:
    norm = _diamondvoy_memory_norm(question)
    if len(norm) < 8:
        return None
    best: tuple[float, dict[str, Any] | None] = (0.0, None)
    for row in _diamondvoy_recent_memories(user_id, limit=140):
        score = _diamondvoy_memory_similarity(norm, str(row.get("question_norm") or row.get("question_text") or ""))
        if score > best[0]:
            best = (score, row)
    shared_topic = False
    if best[1]:
        shared_topic = bool(
            _diamondvoy_memory_topic_keys(norm)
            & _diamondvoy_memory_topic_keys(str(best[1].get("question_norm") or best[1].get("question_text") or ""))
        )
    if best[1] and (best[0] >= 0.68 or (shared_topic and best[0] >= 0.50)):
        best[1]["match_score"] = round(best[0], 3)
        logger.info(
            "diamondvoy memory cache hit user_id=%s memory_id=%s score=%.3f",
            user_id,
            int(best[1].get("id") or 0),
            best[0],
        )
        return best[1]
    if best[1]:
        logger.info(
            "diamondvoy memory cache miss user_id=%s best_memory_id=%s score=%.3f",
            user_id,
            int(best[1].get("id") or 0),
            best[0],
        )
    return None


def _diamondvoy_related_memory_prompt(user_id: int, question: str, limit: int = 3) -> str:
    norm = _diamondvoy_memory_norm(question)
    if len(norm) < 8:
        return ""
    scored: list[tuple[float, dict[str, Any]]] = []
    for row in _diamondvoy_recent_memories(user_id, limit=80):
        score = _diamondvoy_memory_similarity(norm, str(row.get("question_norm") or row.get("question_text") or ""))
        if score >= 0.22:
            scored.append((score, row))
    scored.sort(key=lambda item: item[0], reverse=True)
    snippets: list[str] = []
    for score, row in scored[: max(1, min(5, int(limit or 3)))]:
        q = str(row.get("question_text") or "")[:400]
        a = str(row.get("answer_text") or "")[:900]
        if q and a:
            snippets.append(f"- Similar prior Q ({score:.2f}): {q}\n  Prior answer: {a}")
    if not snippets:
        return ""
    return (
        "Relevant user memory from previous Diamondvoy chats. "
        "Use it only if it helps, and adapt naturally instead of copying word-for-word:\n"
        + "\n".join(snippets)
    )


def _diamondvoy_cached_answer_for_style(answer: str, lang: str, style_hint: str) -> str:
    clean = sanitize_diamondvoy_reply(str(answer or "").strip())
    if not clean:
        return clean
    low_style = style_hint.lower()
    if "brevity=short" in low_style and len(clean) > 1600:
        clean = clean[:1550].rsplit(" ", 1)[0].strip() + "..."
    if (lang or "uz").startswith("ru"):
        prefix = "Похоже, мы уже разбирали это. Коротко адаптирую: "
    elif (lang or "uz").startswith("en"):
        prefix = "We covered something similar before. Adapted answer: "
    else:
        prefix = "Buni oldin ham ko'rib chiqqanmiz. Moslab aytsam: "
    if clean.lower().startswith(prefix.lower()[:12]):
        return clean
    return f"{prefix}{clean}"


async def _diamondvoy_allowed_for_role(user: dict, role: str, text: str, has_images: bool) -> bool:
    clean = str(text or "").strip()
    if str(role or "").lower() == "admin":
        return True
    if has_images:
        return True
    # Do not hard-block non-admin text before the model sees it. Diamondvoy's
    # system prompt still keeps non-admin roles on education/work topics, but
    # the UI should never look like it ignored a valid question.
    if clean:
        return True
    broad_subjects = [
        "English",
        "Russian",
        "Math",
        "IELTS",
        "Grammar",
        "Reading",
        "Vocabulary",
        "Writing",
        "School",
        "Homework",
        "Education",
    ]
    if await diamondvoy_is_subject_related(clean, broad_subjects):
        return True
    role_words = {
        "teacher": {"lesson", "dars", "sinf", "class", "student", "o'quvchi", "o‘quvchi", "teaching", "metod"},
        "support": {"support", "bron", "booking", "dars", "student", "o'quvchi", "o‘quvchi", "davomat"},
        "student": {"homework", "test", "grammar", "reading", "math", "essay", "ielts", "dars"},
    }.get(str(role or "").lower(), set())
    low = clean.lower()
    return any(word in low for word in role_words)


def _diamondvoy_refusal_for_role(role: str) -> str:
    if str(role or "").lower() in {"teacher", "support"}:
        return "Diamondvoy faqat ta'lim va ish jarayoniga oid savollarga javob beradi."
    return "Diamondvoy faqat ta'limga oid savollarga javob beradi."


def _feedback_user_payload(user_id: int) -> dict[str, Any]:
    row = _safe_call(lambda: get_user_by_id(int(user_id)), None) or {}
    if not row:
        return {"id": int(user_id), "full_name": f"User #{int(user_id)}"}
    role = _role_from_login_type(int(row.get("login_type") or 1), str(row.get("login_id") or ""))
    group_name = None
    if role == "student":
        groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
        if groups:
            group_name = str((groups[0] or {}).get("name") or (groups[0] or {}).get("title") or "").strip() or None
    return {
        "id": int(user_id),
        "full_name": _display_name(row),
        "role": role,
        "group": group_name,
        "avatar_url": _first_existing_avatar_url(row.get("profile_image_url"), row.get("effective_profile_image_url")),
        "dcoin_balance": float(get_dcoins(int(user_id))) if role == "student" else None,
        "dpoint_balance": float(get_dpoints(int(user_id))) if role == "student" else None,
        "login_id": row.get("login_id"),
    }


def _feedback_get_or_create_thread(user_id: int) -> dict:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM feedback_threads WHERE user_id=? LIMIT 1", (int(user_id),))
        row = cur.fetchone()
        if row:
            return dict(row)
        cur.execute(
            "INSERT INTO feedback_threads(user_id, status, created_at, updated_at) VALUES (?, 'Yangi', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)",
            (int(user_id),),
        )
        thread_id = int(getattr(cur, "lastrowid", 0) or 0)
        if not thread_id:
            cur.execute("SELECT currval(pg_get_serial_sequence('feedback_threads', 'id')) as id")
            thread_id = int((cur.fetchone() or {}).get("id") or 0)
        conn.commit()
        cur.execute("SELECT * FROM feedback_threads WHERE id=? LIMIT 1", (thread_id,))
        return dict(cur.fetchone() or {})
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()


def _feedback_insert_message(thread_id: int, sender_user_id: int, sender_role: str, text: str, is_anonymous: bool) -> dict:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO feedback_messages(thread_id, sender_user_id, sender_role, message_text, is_anonymous_choice, created_at)
            VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            (int(thread_id), int(sender_user_id), str(sender_role or ""), str(text or "")[:4000], 1 if is_anonymous else 0),
        )
        msg_id = int(getattr(cur, "lastrowid", 0) or 0)
        if not msg_id:
            cur.execute("SELECT currval(pg_get_serial_sequence('feedback_messages', 'id')) as id")
            msg_id = int((cur.fetchone() or {}).get("id") or 0)
        cur.execute("UPDATE feedback_threads SET updated_at=CURRENT_TIMESTAMP WHERE id=?", (int(thread_id),))
        conn.commit()
        cur.execute("SELECT * FROM feedback_messages WHERE id=? LIMIT 1", (msg_id,))
        return dict(cur.fetchone() or {})
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()


def _feedback_insert_attachments(message_id: int, image_urls: list[str]) -> None:
    if not image_urls:
        return
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        for url in image_urls[:3]:
            clean_url = str(url or "").strip()
            if not clean_url:
                continue
            filename, mime_type, size = _chat_media_metadata(clean_url)
            cur.execute(
                """
                INSERT INTO feedback_attachments(message_id, file_url, file_path, mime_type, size_bytes, created_at)
                VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                """,
                (int(message_id), clean_url, filename, mime_type, int(size or 0)),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("feedback attachment insert failed message_id=%s", message_id)
    finally:
        conn.close()


def _feedback_attachments_for_messages(message_ids: list[int]) -> dict[int, list[dict[str, Any]]]:
    out: dict[int, list[dict[str, Any]]] = {}
    ids = [int(mid) for mid in (message_ids or []) if int(mid) > 0]
    if not ids:
        return out
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        for mid in ids:
            cur.execute(
                """
                SELECT id, message_id, file_url, mime_type, size_bytes, created_at
                FROM feedback_attachments
                WHERE message_id=?
                ORDER BY id ASC
                """,
                (mid,),
            )
            out[mid] = [
                {
                    "id": int(row.get("id") or 0),
                    "url": str(row.get("file_url") or ""),
                    "mime_type": row.get("mime_type"),
                    "size_bytes": int(row.get("size_bytes") or 0),
                    "created_at": row.get("created_at"),
                }
                for row in [dict(r) for r in (cur.fetchall() or [])]
            ]
    finally:
        conn.close()
    return out


def _feedback_message_payload(row: dict, attachments_map: dict[int, list[dict[str, Any]]] | None = None) -> dict[str, Any]:
    mid = int(row.get("id") or 0)
    sender_id = int(row.get("sender_user_id") or 0)
    return {
        "id": mid,
        "thread_id": int(row.get("thread_id") or 0),
        "sender_user_id": sender_id,
        "sender_role": str(row.get("sender_role") or ""),
        "text": str(row.get("message_text") or ""),
        "is_anonymous_choice": bool(int(row.get("is_anonymous_choice") or 0)),
        "attachments": (attachments_map or {}).get(mid, []),
        "created_at": row.get("created_at"),
    }


def _feedback_thread_detail(thread_id: int) -> dict[str, Any]:
    _ensure_final_chat_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM feedback_threads WHERE id=? LIMIT 1", (int(thread_id),))
        thread = dict(cur.fetchone() or {})
        if not thread:
            raise HTTPException(status_code=404, detail="Feedback thread not found")
        cur.execute(
            "SELECT * FROM feedback_messages WHERE thread_id=? ORDER BY id ASC LIMIT 500",
            (int(thread_id),),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    finally:
        conn.close()
    attachments = _feedback_attachments_for_messages([int(r.get("id") or 0) for r in rows])
    return {
        "thread": {
            "id": int(thread.get("id") or 0),
            "user_id": int(thread.get("user_id") or 0),
            "status": _normalize_feedback_status(str(thread.get("status") or "")),
            "created_at": thread.get("created_at"),
            "updated_at": thread.get("updated_at"),
            "user": _feedback_user_payload(int(thread.get("user_id") or 0)),
        },
        "messages": [_feedback_message_payload(r, attachments) for r in rows],
    }


def _feedback_admin_threads(status: str | None = None, search: str | None = None, limit: int = 80) -> list[dict[str, Any]]:
    _ensure_final_chat_schema()
    lim = max(1, min(200, int(limit or 80)))
    status_norm = _normalize_feedback_status(status) if status else ""
    search_text = str(search or "").strip().lower()
    conn = get_conn()
    cur = conn.cursor()
    try:
        params: list[Any] = []
        where = ["1=1"]
        if status_norm:
            where.append("ft.status=?")
            params.append(status_norm)
        if search_text:
            where.append("(LOWER(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) LIKE ? OR LOWER(COALESCE(u.login_id, '')) LIKE ?)")
            params.extend([f"%{search_text}%", f"%{search_text}%"])
        params.append(lim)
        cur.execute(
            f"""
            SELECT
                ft.id, ft.user_id, ft.status, ft.created_at, ft.updated_at,
                u.first_name, u.last_name, u.login_id, u.login_type,
                (
                    SELECT fm.message_text
                    FROM feedback_messages fm
                    WHERE fm.thread_id=ft.id
                    ORDER BY fm.id DESC
                    LIMIT 1
                ) AS last_message_preview
            FROM feedback_threads ft
            JOIN users u ON u.id=ft.user_id
            WHERE {' AND '.join(where)}
            ORDER BY ft.updated_at DESC, ft.id DESC
            LIMIT ?
            """,
            tuple(params),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    finally:
        conn.close()
    out = []
    for row in rows:
        preview = str(row.get("last_message_preview") or "").replace("\n", " ").strip()
        if len(preview) > 140:
            preview = f"{preview[:137]}..."
        out.append(
            {
                "id": int(row.get("id") or 0),
                "thread_id": int(row.get("id") or 0),
                "user_id": int(row.get("user_id") or 0),
                "user_name": _display_name(row),
                "role": _role_from_login_type(int(row.get("login_type") or 1), str(row.get("login_id") or "")),
                "status": _normalize_feedback_status(row.get("status")),
                "last_message_preview": preview,
                "updated_at": row.get("updated_at"),
                "created_at": row.get("created_at"),
            }
        )
    return out


def _feedback_thread_for_admin_or_error(thread_id: int) -> dict[str, Any]:
    return _feedback_thread_detail(int(thread_id))


async def _feedback_notify_user(user_id: int, title: str, message: str, source_key: str) -> None:
    _safe_call(
        lambda: _feedback_store_student_notification(
            user_id=int(user_id),
            title=title,
            message=message,
            source_key=source_key,
        ),
        None,
    )
    target_user = _safe_call(lambda: get_user_by_id(int(user_id)), None) or {}
    tg = str(target_user.get("telegram_id") or "").strip()
    if not tg:
        return
    try:
        await _send_telegram_text(
            _tg_token_for_login_type(int(target_user.get("login_type") or 0)),
            tg,
            message,
            button_text="Webda ochish",
            button_url=f"{WEBAPP_URL}/dashboard?section=chats" if WEBAPP_URL else None,
        )
    except Exception:
        logger.exception("feedback user telegram notification failed user_id=%s", user_id)


def _user_subjects_from_row(user: dict) -> list[str]:
    user_id = int(user.get("id") or 0)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    cache_key = (user_id, role, str(user.get("subject") or ""))
    cached = _short_cache_get(_USER_SUBJECTS_CACHE, cache_key)
    if isinstance(cached, list):
        return [str(item) for item in cached]
    if role == "student" and user_id > 0:
        group_subjects: list[str] = []
        for group in (_safe_call(lambda uid=user_id: get_user_groups(uid), []) or []):
            subject = _normalize_subject_label(str(group.get("subject") or "").strip())
            if subject and subject not in group_subjects:
                group_subjects.append(subject)
        return _short_cache_set(_USER_SUBJECTS_CACHE, cache_key, group_subjects, ttl_seconds=8.0, max_items=8192)
    subjects = _safe_call(lambda: get_user_subjects(user_id), []) or []
    if not subjects and user.get("subject"):
        subjects = [part.strip() for part in str(user.get("subject") or "").split(",") if part.strip()]
    normalized = _normalize_subjects([str(item) for item in subjects], fallback=["English"])
    out = normalized or ["English"]
    return _short_cache_set(_USER_SUBJECTS_CACHE, cache_key, out, ttl_seconds=8.0, max_items=8192)


def _user_subjects_from_csv(user: dict) -> list[str]:
    raw = str(user.get("subject") or "").strip()
    if not raw:
        return ["English"]
    parts = [part.strip() for part in raw.split(",") if part and str(part).strip()]
    normalized = _normalize_subjects(parts, fallback=["English"])
    return normalized or ["English"]


def _serialize_user_row_light(row: dict) -> dict:
    role = _role_from_login_type(int(row.get("login_type") or 1), str(row.get("login_id") or ""))
    language = str(row.get("language") or "uz").strip().lower()
    if language not in WEB_LANGUAGES:
        language = "uz"
    avatar_url = _first_existing_avatar_url(
        row.get("profile_image_url"),
        row.get("effective_profile_image_url"),
        row.get("face_reference_image_url"),
    )
    return {
        "id": int(row.get("id") or 0),
        "full_name": _display_name(row),
        "role": role,
        "login_id": str(row.get("login_id") or ""),
        "telegram_id": row.get("telegram_id"),
        "login_type": int(row.get("login_type") or 1),
        "phone": row.get("phone"),
        "parent_phone": row.get("parent_phone"),
        "avatar_url": avatar_url,
        "profile_image_url": avatar_url,
        "level": row.get("level"),
        "subjects": _user_subjects_from_row(row) if role == "student" else _user_subjects_from_csv(row),
        "blocked": int(row.get("blocked") or 0) == 1,
        "access_enabled": int(row.get("access_enabled") or 0) == 1,
        "language": language,
        "placement_required": int(row.get("placement_required") or 0) == 1,
        "placement_subject": (_normalize_subject_label(str(row.get("placement_subject") or "").strip()) or None),
        "family_discount_enabled": int(row.get("family_discount_enabled") or 0) == 1,
        "multi_group_discount_opt_in": int(row.get("multi_group_discount_opt_in") or 0) == 1,
        "referral_student_id": int(row.get("referral_student_id") or 0) if row.get("referral_student_id") is not None else None,
        "free_access": int(row.get("free_access") or 0) == 1,
        "group_count": int(row.get("group_count") or 0),
        "created_at": row.get("created_at"),
        "joined_at": row.get("joined_at"),
    }


