def _ensure_runtime_settings_table() -> None:
    conn = get_conn()
    cur = conn.cursor()
    _execute_ddl_candidates(
        cur,
        [
            """
            CREATE TABLE IF NOT EXISTS web_runtime_settings (
                key TEXT PRIMARY KEY,
                value_json TEXT NOT NULL,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """,
        ],
    )
    conn.commit()
    conn.close()


def _get_runtime_settings() -> dict[str, float]:
    _ensure_runtime_settings_table()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT value_json FROM web_runtime_settings WHERE key='dpoint_rules' LIMIT 1")
    row = cur.fetchone()
    conn.close()
    if not row:
        return dict(DPOINT_SETTINGS_DEFAULTS)
    try:
        parsed = json.loads(str((row or {}).get("value_json") or "{}"))
        out = dict(DPOINT_SETTINGS_DEFAULTS)
        for key, value in (parsed or {}).items():
            try:
                out[str(key)] = float(value)
            except Exception:
                continue
        return out
    except Exception:
        return dict(DPOINT_SETTINGS_DEFAULTS)


def _get_web_runtime_string_setting(key: str, default: str = "") -> str:
    """Read a single arbitrary string value from web_runtime_settings by key."""
    _ensure_runtime_settings_table()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT value_json FROM web_runtime_settings WHERE key=? LIMIT 1", (str(key),))
        row = cur.fetchone()
        if not row:
            return str(default)
        raw = str((row or {}).get("value_json") or "")
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, (dict, list)):
                return str(default)
            return str(parsed) if parsed is not None else str(default)
        except Exception:
            return raw or str(default)
    except Exception:
        return str(default)
    finally:
        conn.close()


def _set_web_runtime_string_setting(key: str, value: str) -> None:
    """Write a string value to web_runtime_settings under an arbitrary key."""
    _ensure_runtime_settings_table()
    conn = get_conn()
    cur = conn.cursor()
    payload = json.dumps(str(value), ensure_ascii=False)
    try:
        cur.execute(
            """
            INSERT INTO web_runtime_settings(key, value_json, updated_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json, updated_at=CURRENT_TIMESTAMP
            """,
            (str(key), payload),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("_set_web_runtime_string_setting failed key=%s", key)
    finally:
        conn.close()


def _get_daily_arena_schedule_times() -> dict[str, str]:
    """Return Daily Arena start times per subject, configurable via admin settings.
    Cached for 30 s to avoid repeated DB reads on every join-window check."""
    global _DAILY_ARENA_SCHEDULE_CACHE
    now_ts = time.time()
    cached = _DAILY_ARENA_SCHEDULE_CACHE
    if cached and cached[0] > now_ts:
        return dict(cached[1])
    eng = _get_web_runtime_string_setting("daily_arena_time_english", "19:00") or "19:00"
    rus = _get_web_runtime_string_setting("daily_arena_time_russian", "20:00") or "20:00"
    result: dict[str, str] = {"English": eng, "Russian": rus}
    _DAILY_ARENA_SCHEDULE_CACHE = (now_ts + 30.0, result)
    return result


def _save_runtime_settings(values: dict[str, Any]) -> dict[str, float]:
    percent_keys = {
        "attendance_sababsiz_percent",
        "family_discount_percent",
        "multi_group_discount_percent",
        "payment_family_discount_percent",
        "payment_multi_group_discount_percent",
        "payment_overdue_penalty_dcoin_percent",
        "boss_arena_global_threshold_percent",
    }
    non_negative_keys = {
        "arena_entry_fee_dcoin",
        "duel_entry_fee_dcoin",
        "entry_fee_dcoin",
        "referral_bonus_dpoints",
        "payment_overdue_penalty_dpoints",
        "payment_advance_full_bonus_dpoints",
        "daily_arena_reward_first",
        "daily_arena_reward_second",
        "daily_arena_reward_third",
        "daily_arena_min_players",
        "daily_arena_max_players",
        "group_arena_winner_reward",
        "boss_arena_reward_per_correct",
        "boss_arena_reward_flat",
        "teacher_manual_daily_dpoint_max",
        "homework_deadline_missed_penalty_dpoints",
    }
    magnitude_keys = set(DPOINT_SETTINGS_DEFAULTS.keys()) - percent_keys
    merged = _get_runtime_settings()
    for key, value in (values or {}).items():
        if key not in DPOINT_SETTINGS_DEFAULTS:
            continue
        try:
            numeric = float(value)
        except Exception:
            continue
        if not math.isfinite(numeric):
            continue
        if key in percent_keys:
            if numeric < 0 or numeric > 100:
                continue
        elif key in non_negative_keys:
            if numeric < 0:
                continue
        elif key in magnitude_keys:
            if abs(numeric) > 1_000_000:
                continue
        merged[str(key)] = numeric
    _ensure_runtime_settings_table()
    conn = get_conn()
    cur = conn.cursor()
    payload = json.dumps(merged, ensure_ascii=False)
    try:
        cur.execute(
            """
            INSERT INTO web_runtime_settings(key, value_json, updated_at)
            VALUES ('dpoint_rules', ?, CURRENT_TIMESTAMP)
            ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json, updated_at=CURRENT_TIMESTAMP
            """,
            (payload,),
        )
        conn.commit()
    finally:
        conn.close()
    return merged


def _runtime_settings_updated_at() -> str | None:
    _ensure_runtime_settings_table()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT updated_at FROM web_runtime_settings WHERE key='dpoint_rules' LIMIT 1")
        row = cur.fetchone() or {}
        value = row.get("updated_at")
        return str(value) if value is not None else None
    finally:
        conn.close()


_PAYMENT_FAST_CACHE: dict[str, tuple[float, Any]] = {}
_PAYMENT_FAST_CACHE_MAX = 2048
_PAYMENT_CACHE_NULL = object()


def _payment_cache_get(key: str) -> Any | None:
    item = _PAYMENT_FAST_CACHE.get(str(key))
    if not item:
        return None
    expires_at, value = item
    if expires_at <= time.time():
        _PAYMENT_FAST_CACHE.pop(str(key), None)
        return None
    if value is _PAYMENT_CACHE_NULL:
        return None
    return value


def _payment_cache_has(key: str) -> bool:
    item = _PAYMENT_FAST_CACHE.get(str(key))
    if not item:
        return False
    expires_at, _ = item
    if expires_at <= time.time():
        _PAYMENT_FAST_CACHE.pop(str(key), None)
        return False
    return True


def _payment_cache_set(key: str, value: Any, ttl_seconds: float) -> Any:
    if len(_PAYMENT_FAST_CACHE) >= _PAYMENT_FAST_CACHE_MAX:
        for stale_key, (exp, _) in list(_PAYMENT_FAST_CACHE.items())[:256]:
            if exp <= time.time():
                _PAYMENT_FAST_CACHE.pop(stale_key, None)
        if len(_PAYMENT_FAST_CACHE) >= _PAYMENT_FAST_CACHE_MAX:
            try:
                _PAYMENT_FAST_CACHE.pop(next(iter(_PAYMENT_FAST_CACHE.keys())))
            except Exception:
                pass
    store_value = _PAYMENT_CACHE_NULL if value is None else value
    _PAYMENT_FAST_CACHE[str(key)] = (time.time() + max(0.5, float(ttl_seconds)), store_value)
    return value


@lru_cache(maxsize=128)
def _db_table_columns(table_name: str) -> set[str]:
    tname = str(table_name or "").strip()
    if not tname:
        return set()
    conn = get_conn()
    cur = conn.cursor()
    cols: set[str] = set()
    try:
        # Postgres-first schema detection (runtime is Postgres-only).
        try:
            cur.execute(
                """
                SELECT column_name
                FROM information_schema.columns
                WHERE table_schema = current_schema()
                  AND table_name = %s
                """,
                (tname,),
            )
            pg_rows = cur.fetchall() or []
            for row in pg_rows:
                if isinstance(row, dict):
                    col = str(row.get("column_name") or "").strip().lower()
                else:
                    col = str((row or [None])[0] if row else "").strip().lower()
                if col:
                    cols.add(col)
            if cols:
                return cols
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
        # SQLite compatibility fallback (kept for dev tooling).
        cur.execute(f"PRAGMA table_info({tname})")
        for row in (cur.fetchall() or []):
            col = str((row or {}).get("name") or "").strip().lower()
            if col:
                cols.add(col)
    except Exception:
        cols = set()
    finally:
        conn.close()
    return cols


def _db_has_column(table_name: str, column_name: str) -> bool:
    return str(column_name or "").strip().lower() in _db_table_columns(str(table_name or "").strip())


def _round_half_up(value: float, digits: int = 2) -> float:
    quant = Decimal("1").scaleb(-int(digits))
    return float(Decimal(str(float(value or 0.0))).quantize(quant, rounding=ROUND_HALF_UP))


