def _list_dpoint_deduction_history(limit: int = 100) -> list[dict]:
    return _list_dpoint_history(limit=limit, offset=0, action_type="deduction").get("items", [])


def _parse_dpoint_history_reason(change_type: str) -> tuple[str, str]:
    raw = str(change_type or "").strip()
    if ":" in raw:
        action, reason = raw.split(":", 1)
        return action.strip(), reason.strip()
    return raw, ""


def _list_dpoint_history(
    *,
    limit: int = 50,
    offset: int = 0,
    q: str | None = None,
    action_type: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
) -> dict[str, Any]:
    has_dpoints_change = _db_has_column("diamond_history", "dpoints_change")
    amount_expr = "COALESCE(dh.dpoints_change, dh.dcoin_change, 0)" if has_dpoints_change else "COALESCE(dh.dcoin_change, 0)"
    where = ["ABS(%s) > 0" % amount_expr]
    params: list[Any] = []
    q_text = str(q or "").strip()
    if q_text:
        like = f"%{q_text.lower()}%"
        where.append(
            """
            (
                LOWER(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) LIKE ?
                OR LOWER(COALESCE(u.login_id, '')) LIKE ?
                OR LOWER(COALESCE(dh.change_type, '')) LIKE ?
                OR LOWER(COALESCE(dh.subject, '')) LIKE ?
            )
            """
        )
        params.extend([like, like, like, like])
    action = str(action_type or "").strip().lower()
    if action in {"deduction", "penalty", "negative"}:
        where.append(f"{amount_expr} < 0")
    elif action in {"reward", "bonus", "positive"}:
        where.append(f"{amount_expr} > 0")
    if re.match(r"^\d{4}-\d{2}-\d{2}$", str(date_from or "")):
        where.append("DATE(dh.created_at) >= ?")
        params.append(str(date_from))
    if re.match(r"^\d{4}-\d{2}-\d{2}$", str(date_to or "")):
        where.append("DATE(dh.created_at) <= ?")
        params.append(str(date_to))
    limit_safe = max(1, min(int(limit or 50), 200))
    offset_safe = max(0, int(offset or 0))
    where_sql = " AND ".join(where)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT
                dh.id,
                dh.user_id,
                u.first_name,
                u.last_name,
                u.login_id,
                {amount_expr} AS amount,
                dh.change_type,
                dh.subject,
                dh.created_at
            FROM diamond_history dh
            LEFT JOIN users u ON u.id = dh.user_id
            WHERE {where_sql}
            ORDER BY dh.created_at DESC, dh.id DESC
            LIMIT ?
            OFFSET ?
            """,
            [*params, limit_safe + 1, offset_safe],
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
        has_more = len(rows) > limit_safe
        rows = rows[:limit_safe]
        items = []
        for row in rows:
            action_name, reason = _parse_dpoint_history_reason(str(row.get("change_type") or ""))
            amount = float(row.get("amount") or 0.0)
            items.append(
                {
                    "id": int(row.get("id") or 0),
                    "user_id": int(row.get("user_id") or 0),
                    "full_name": _display_name(row),
                    "login_id": str(row.get("login_id") or ""),
                    "amount": amount,
                    "action_type": "reward" if amount > 0 else "deduction",
                    "action": action_name,
                    "reason": reason,
                    "change_type": str(row.get("change_type") or ""),
                    "subject": str(row.get("subject") or "").strip() or None,
                    "source": action_name or str(row.get("subject") or "").strip() or "dpoint_history",
                    "admin_id": None,
                    "admin_name": None,
                    "admin": None,
                    "created_at": row.get("created_at"),
                }
            )
        total_estimate = offset_safe + len(items) + (1 if has_more else 0)
        return {
            "items": items,
            "total": total_estimate,
            "limit": limit_safe,
            "offset": offset_safe,
            "has_more": has_more,
        }
    except Exception:
        logger.debug("dpoint history lookup failed", exc_info=True)
        return {"items": [], "total": 0, "limit": limit_safe, "offset": offset_safe, "has_more": False}
    finally:
        conn.close()


