    stream_user_id = int(viewer_user_id or 0) or purchase_user_id or None
    protected_pdf_url = _build_media_stream_url(pdf_asset_id, user_id=stream_user_id) if pdf_asset_id > 0 else None
    payload = {
        "id": int(row.get("id") or 0),
        "title": str(row.get("title") or "").strip(),
        "subject": str(row.get("subject") or "").strip() or None,
        "purchase_count": int(row.get("purchase_count") or 0),
        "description": str((row.get("description") or row.get("short_description") or "")).strip(),
        "author": str(row.get("author") or "").strip(),
        "category": str(row.get("category") or "").strip(),
        "level": str(row.get("level") or "").strip(),
        "cover_url": _normalize_image_asset_url(str(row.get("cover_url") or "").strip() or None),
        "pdf_url": protected_pdf_url or pdf_url,
        "pdf_asset_id": pdf_asset_id or None,
        "price": float(row.get("price") or 0),
        "deadline_days": (max(1, int(row.get("deadline_days") or 0)) if int(row.get("deadline_days") or 0) > 0 else None),
        "is_published": int(row.get("is_published") or 0) == 1,
        "created_at": _as_iso_timestamp(row.get("created_at")),
        "updated_at": _as_iso_timestamp(row.get("updated_at")),
        "question_count": _get_book_question_count_cached(int(row.get("id") or 0), row.get("question_count")),
    }
    if include_purchase:
        payload["purchase"] = _serialize_book_purchase_row(purchase_row)
    return payload


