def _startup_validation_report() -> dict:
    checks: list[dict[str, Any]] = []
    url_ok = bool(str(DATABASE_URL or "").strip())
    checks.append({"name": "database_url_present", "ok": url_ok})
    conn_ok = False
    table_ok = False
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("SELECT 1 AS ok")
        _ = cur.fetchone()
        conn_ok = True
        checks.append({"name": "database_connection", "ok": True})
        required_tables = [
            "users",
            "groups",
            "user_subject",
            "web_articles",
            "web_broadcasts",
            "web_student_reviews",
            "web_courses",
            "web_results",
        ]
        found: set[str] = set()
        for table in required_tables:
            try:
                cur.execute("SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name=? LIMIT 1", (table,))
                row = cur.fetchone()
                if row:
                    found.add(table)
            except Exception:
                continue
        table_ok = len(found) == len(required_tables)
        checks.append(
            {
                "name": "required_tables",
                "ok": table_ok,
                "found": sorted(found),
                "required": required_tables,
            }
        )
        conn.close()
    except Exception as exc:
        checks.append({"name": "database_connection", "ok": False, "error": str(exc)})
    face_engine_ok = False
    try:
        engine = get_face_engine()
        diagnostics = engine.diagnostics() if hasattr(engine, "diagnostics") else {"provider": getattr(engine, "provider", "unknown")}
        face_engine_ok = bool(diagnostics.get("insightface_available"))
        checks.append({
            "name": "proctoring_face_engine",
            "ok": face_engine_ok,
            "provider": diagnostics.get("provider"),
            "active_provider": diagnostics.get("active_provider"),
            "insightface_available": diagnostics.get("insightface_available"),
            "error": diagnostics.get("insightface_init_error"),
        })
    except Exception as exc:
        checks.append({"name": "proctoring_face_engine", "ok": False, "error": str(exc)})
    return {
        "ok": bool(url_ok and conn_ok and table_ok and face_engine_ok),
        "checks": checks,
        "database_url": str(DATABASE_URL or ""),
        "timestamp": _now_utc().isoformat(),
    }


def _serialize_user_row(row: dict) -> dict:
    role = _role_from_login_type(int(row.get("login_type") or 1), str(row.get("login_id") or ""))
    language = str(row.get("language") or "uz").strip().lower()
    if language not in WEB_LANGUAGES:
        language = "uz"
    avatar_url = _first_existing_avatar_url(
        row.get("profile_image_url"),
        row.get("effective_profile_image_url"),
        row.get("face_reference_image_url"),
    )
    return {
        "id": int(row.get("id") or 0),
        "full_name": _display_name(row),
        "role": role,
        "login_id": str(row.get("login_id") or ""),
        "telegram_id": row.get("telegram_id"),
        "login_type": int(row.get("login_type") or 1),
        "phone": row.get("phone"),
        "parent_phone": row.get("parent_phone"),
        "avatar_url": avatar_url,
        "profile_image_url": avatar_url,
        "level": row.get("level"),
        "subjects": _user_subjects_from_row(row),
        "blocked": int(row.get("blocked") or 0) == 1,
        "access_enabled": int(row.get("access_enabled") or 0) == 1,
        "language": language,
        "placement_required": int(row.get("placement_required") or 0) == 1,
        "placement_subject": (_normalize_subject_label(str(row.get("placement_subject") or "").strip()) or None),
        "family_discount_enabled": int(row.get("family_discount_enabled") or 0) == 1,
        "multi_group_discount_opt_in": int(row.get("multi_group_discount_opt_in") or 0) == 1,
        "referral_student_id": int(row.get("referral_student_id") or 0) if row.get("referral_student_id") is not None else None,
        "free_access": int(row.get("free_access") or 0) == 1,
    }


def _level_rank_value(level: str | None) -> tuple[int, str]:
    raw = str(level or "").strip()
    upper = raw.upper()
    cefr_order = {"BEGINNER": 0, "ELEMENTARY": 1, "PRE-INTERMEDIATE": 2, "INTERMEDIATE": 3, "UPPER-INTERMEDIATE": 4, "ADVANCED": 5, "MIXED": 6}
    for code, rank in cefr_order.items():
        if code in upper:
            return (rank, raw)
    low = raw.lower().replace("ё", "е")
    if "началь" in low or "а1" in low:
        return (0, raw)
    if "базов" in low or "элементар" in low or "а2" in low:
        return (1, raw)
    if "средн" in low or "б1" in low:
        return (2, raw)
    if "продвинут" in low or "б2" in low:
        return (3, raw)
    return (99, raw)


def _student_subject_levels_from_group_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = {}
    for group in rows or []:
        subject = _normalize_subject_label(str(group.get("subject") or "").strip())
        level = str(group.get("level") or "").strip()
        if not subject or not level:
            continue
        current = grouped.get(subject)
        if current is None or _level_rank_value(level) < _level_rank_value(str(current.get("level") or "")):
            grouped[subject] = {
                "subject": subject,
                "level": level,
                "group_id": int(group.get("id") or 0),
                "group_name": str(group.get("name") or "").strip(),
            }
    return [grouped[key] for key in sorted(grouped)]


def _student_subject_levels_from_groups(user_id: int) -> list[dict[str, Any]]:
    """Return active subject levels derived from the student's current groups."""
    uid = int(user_id or 0)
    if uid <= 0:
        return []
    rows = _safe_call(lambda: get_user_groups(uid), []) or []
    return _student_subject_levels_from_group_rows(rows)


def _student_wallet_summary_fast(user_id: int, subject_count: int) -> dict[str, float]:
    uid = int(user_id or 0)
    if uid <= 0:
        return {"dcoin": 0.0, "dpoints": 0.0}
    count = max(1, int(subject_count or 1))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT login_type FROM users WHERE id=? LIMIT 1", (uid,))
        user_row = cur.fetchone() or {}
        if int(user_row.get("login_type") or 0) == 6:
            return {"dcoin": 0.0, "dpoints": 0.0}
        cur.execute(
            """
            SELECT
                COALESCE(dpoints, 0) AS dpoints,
                COALESCE(dcoin_floor, 0) AS dcoin_floor,
                dcoin_anchor_value,
                dcoin_anchor_dpoints
            FROM user_dpoints
            WHERE user_id=?
            LIMIT 1
            """,
            (uid,),
        )
        row = cur.fetchone() or {}
        dpoints = float(row.get("dpoints") or 0.0)
        floor = float(row.get("dcoin_floor") or 0.0)
        anchor_value_raw = row.get("dcoin_anchor_value")
        anchor_dpoints_raw = row.get("dcoin_anchor_dpoints")
        if anchor_value_raw is not None and anchor_dpoints_raw is not None:
            visible = float(anchor_value_raw) + (dpoints - float(anchor_dpoints_raw))
        else:
            visible = dpoints
        return {"dcoin": _round_half_up(max(floor, max(0.0, visible)), 2), "dpoints": float(dpoints)}
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return {"dcoin": 0.0, "dpoints": 0.0}
    finally:
        conn.close()


def _subject_match_key(value: Any) -> str:
    return re.sub(r"\s+", "", str(value or "").strip().lower())


def _student_can_join_group_subject(student: dict | None, group: dict | None) -> bool:
    group_subject = _subject_match_key((group or {}).get("subject"))
    if not group_subject:
        return True
    if not student:
        return False
    student_id = int(student.get("id") or 0)
    login_type = int(student.get("login_type") or 0)
    if login_type in (1, 2, 6):
        return student_id > 0
    subjects: list[str] = []
    raw_subject = str(student.get("subject") or "")
    subjects.extend([part.strip() for part in raw_subject.split(",") if part.strip()])
    if student_id > 0:
        subjects.extend(_safe_call(lambda: get_user_subjects(student_id), []) or [])
    if not [subject for subject in subjects if str(subject or "").strip()]:
        return True
    return any(_subject_match_key(subject) == group_subject for subject in subjects)


def _require_student_group_subject_match(student: dict | None, group: dict | None) -> None:
    if not _student_can_join_group_subject(student, group):
        raise HTTPException(status_code=400, detail="Student fani guruh faniga mos emas")


def _local_image_url_exists(url: str | None) -> bool:
    raw = str(url or "").strip()
    if not raw:
        return False
    local_prefixes = (
        ("/student/proctoring/images/", PROCTORING_UPLOAD_DIR),
        ("/profile/images/", PROFILE_UPLOAD_DIR),
    )
    for prefix, directory in local_prefixes:
        if raw.startswith(prefix):
            filename = Path(raw.removeprefix(prefix)).name
            return bool(filename) and (directory / filename).is_file()
    if raw.startswith("/"):
        return True
    return True


def _proctoring_image_url_exists(url: str | None) -> bool:
    return _local_image_url_exists(url)


def _first_existing_avatar_url(*urls: Any) -> str | None:
    for value in urls:
        raw = str(value or "").strip()
        if raw and _local_image_url_exists(raw):
            return raw
    return None


def _enrich_user_rows_with_face_profiles(rows: list[dict]) -> list[dict]:
    """Attach active FaceID reference image as avatar fallback for lightweight lists."""
    if not rows:
        return rows
    ids = sorted({
        int(row.get("id") or row.get("user_id") or 0)
        for row in rows
        if int(row.get("id") or row.get("user_id") or 0) > 0
    })
    missing_ids = [
        uid
        for uid in ids
        if any(
            int(row.get("id") or row.get("user_id") or 0) == uid
            and not _first_existing_avatar_url(
                row.get("profile_image_url"),
                row.get("effective_profile_image_url"),
                row.get("face_reference_image_url"),
            )
            for row in rows
        )
    ]
    if not missing_ids:
        return rows
    qmarks = ",".join(["?"] * len(missing_ids))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            f"""
            SELECT user_id, reference_image_url
            FROM user_face_profiles
            WHERE status='active'
              AND user_id IN ({qmarks})
            ORDER BY user_id ASC, id DESC
            """,
            tuple(missing_ids),
        )
        fallback: dict[int, str] = {}
        for item in cur.fetchall() or []:
            uid = int(item.get("user_id") or 0)
            ref = str(item.get("reference_image_url") or "").strip()
            if uid > 0 and ref and uid not in fallback and _proctoring_image_url_exists(ref):
                fallback[uid] = ref
        for row in rows:
            uid = int(row.get("id") or row.get("user_id") or 0)
            avatar = _first_existing_avatar_url(
                row.get("profile_image_url"),
                row.get("effective_profile_image_url"),
                row.get("face_reference_image_url"),
                fallback.get(uid),
            )
            row["profile_image_url"] = avatar
            row["effective_profile_image_url"] = avatar
            row["face_reference_image_url"] = avatar
    except Exception:
        logger.debug("face profile avatar fallback lookup failed", exc_info=True)
    finally:
        conn.close()
    return rows


def _serialize_group_row(row: dict) -> dict:
    ensure_group_extra_subjects_schema()
    group_id = int(row.get("id") or 0)
    students = _safe_call(lambda: get_group_users(group_id), [])
    student_count = len([u for u in students if int(u.get("login_type") or 0) in (1, 2, 6)])
    teacher = _safe_call(lambda: get_user_by_id(int(row.get("teacher_id") or 0)), None)
    primary_subject = _normalize_subject_label(str(row.get("subject") or "").strip()) or "English"
    raw_extra = _safe_call(lambda: get_group_extra_subjects(group_id), []) or []
    extra_subjects: list[str] = []
    for item in raw_extra:
        normalized = _normalize_subject_label(str(item or "").strip())
        if not normalized or normalized == primary_subject or normalized in extra_subjects:
            continue
        extra_subjects.append(normalized)
    all_subjects = [primary_subject, *extra_subjects]
    course_id = int(row.get("course_id") or 0) if row.get("course_id") is not None else None
    linked_course = _safe_call(lambda: _get_course_by_id(int(course_id or 0)), None) if course_id else None
    course_title = str(row.get("course_title") or "").strip() or (str(linked_course.get("title") or "").strip() if linked_course else "")
    pricing_type = str(row.get("pricing_type") or "group").strip()
    monthly_fee_text = str(row.get("monthly_fee_text") or "").strip() or (
        (str(linked_course.get("individual_price_text") or "").strip() if pricing_type == "individual" else str(linked_course.get("price_text") or "").strip()) if linked_course else ""
    )
    return {
        "id": group_id,
        "name": str(row.get("name") or ""),
        "subject": primary_subject,
        "subject_id": GROUP_SUBJECT_CODE_TO_ID.get(primary_subject.lower()),
        "primary_subject": primary_subject,
        "extra_subjects": extra_subjects,
        "subjects": all_subjects,
        "level": str(row.get("level") or "PRE-INTERMEDIATE"),
        "teacher_id": int(row.get("teacher_id") or 0) if row.get("teacher_id") is not None else None,
        "teacher_name": _display_name(teacher) if teacher else "Not assigned",
        "course_id": course_id,
        "course_title": course_title or None,
        "monthly_fee_text": monthly_fee_text or None,
        "lesson_date": row.get("lesson_date"),
        "lesson_start": row.get("lesson_start"),
        "lesson_end": row.get("lesson_end"),
        "student_count": student_count,
        "active": int(row.get("active") or 1) == 1,
        "telegram_group_url": row.get("telegram_group_url") or None,
        "teacher_instagram_url": teacher.get("instagram_url") if teacher else None,
        "teacher_telegram_url": teacher.get("telegram_url") if teacher else None,
        "temporary_access": bool(row.get("temporary_access")),
        "temp_assignment_next_date": row.get("temp_assignment_next_date"),
        "temp_assignment_start": row.get("temp_assignment_start"),
        "temp_assignment_end": row.get("temp_assignment_end"),
    }


def _serialize_group_rows_bulk(rows: list[dict]) -> list[dict]:
    """
    Bulk group serializer for admin list views to avoid N+1 calls.
    Keeps payload shape compatible with _serialize_group_row.
    """
    ensure_group_extra_subjects_schema()
    if not rows:
        return []
    group_ids = [int(r.get("id") or 0) for r in rows if int(r.get("id") or 0) > 0]
    teacher_ids = sorted({int(r.get("teacher_id") or 0) for r in rows if int(r.get("teacher_id") or 0) > 0})
    course_ids = sorted({int(r.get("course_id") or 0) for r in rows if int(r.get("course_id") or 0) > 0})

    teachers_map: dict[int, dict] = {}
    courses_map: dict[int, dict] = {}

    student_count_by_group: dict[int, int] = {}
    extra_subjects_by_group: dict[int, list[str]] = {}
    conn = get_conn()
    cur = conn.cursor()
    try:
        if teacher_ids:
            placeholders = ", ".join(["?"] * len(teacher_ids))
            cur.execute(
                f"""
                SELECT id, first_name, last_name, login_type, login_id, subject
                FROM users
                WHERE id IN ({placeholders})
                """,
                tuple(teacher_ids),
            )
            teachers_map = {int(item.get("id") or 0): dict(item) for item in (cur.fetchall() or []) if int(item.get("id") or 0) > 0}

        if course_ids:
            placeholders = ", ".join(["?"] * len(course_ids))
            course_sql_variants = (
                f"""
                SELECT id, title, price_text, individual_price_text
                FROM web_courses
                WHERE id IN ({placeholders})
                """,
                f"""
                SELECT id, title, price_text, price_text as individual_price_text
                FROM courses
                WHERE id IN ({placeholders})
                """,
            )
            for sql in course_sql_variants:
                try:
                    cur.execute(sql, tuple(course_ids))
                    rows_raw = [dict(item) for item in (cur.fetchall() or [])]
                    if rows_raw:
                        courses_map = {int(item.get("id") or 0): item for item in rows_raw if int(item.get("id") or 0) > 0}
                    break
                except Exception:
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                    continue

        if group_ids:
            placeholders = ", ".join(["?"] * len(group_ids))
            count_sql_variants = (
                f"""
                SELECT ug.group_id, COUNT(DISTINCT ug.user_id) AS cnt
                FROM user_groups ug
                JOIN users u ON u.id = ug.user_id
                WHERE ug.group_id IN ({placeholders})
                  AND u.login_type IN (1,2,6)
                  AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT)) = '')
                GROUP BY ug.group_id
                """,
                f"""
                SELECT ug.group_id, COUNT(DISTINCT ug.user_id) AS cnt
                FROM user_groups ug
                JOIN users u ON u.id = ug.user_id
                WHERE ug.group_id IN ({placeholders})
                  AND u.login_type IN (1,2,6)
                GROUP BY ug.group_id
                """,
            )
            for sql in count_sql_variants:
                try:
                    cur.execute(sql, tuple(group_ids))
                    for item in (cur.fetchall() or []):
                        row = dict(item)
                        gid = int(row.get("group_id") or 0)
                        if gid > 0:
                            student_count_by_group[gid] = int(row.get("cnt") or 0)
                    break
                except Exception:
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                    continue

            try:
                cur.execute(
                    f"""
                    SELECT group_id, subject
                    FROM group_extra_subjects
                    WHERE group_id IN ({placeholders})
                    ORDER BY id ASC
                    """,
                    tuple(group_ids),
                )
                for item in (cur.fetchall() or []):
                    row = dict(item)
                    gid = int(row.get("group_id") or 0)
                    subj = _normalize_subject_label(str(row.get("subject") or "").strip())
                    if gid <= 0 or not subj:
                        continue
                    bucket = extra_subjects_by_group.setdefault(gid, [])
                    if subj not in bucket:
                        bucket.append(subj)
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
    finally:
        conn.close()

    out: list[dict] = []
    for row in rows:
        group_id = int(row.get("id") or 0)
        teacher = teachers_map.get(int(row.get("teacher_id") or 0))
        primary_subject = _normalize_subject_label(str(row.get("subject") or "").strip()) or "English"
        raw_extra = extra_subjects_by_group.get(group_id, [])
        extra_subjects = [s for s in raw_extra if s and s != primary_subject]
        all_subjects = [primary_subject, *extra_subjects]
        course_id = int(row.get("course_id") or 0) if row.get("course_id") is not None else None
        linked_course = courses_map.get(int(course_id or 0)) if course_id else None
        course_title = str(row.get("course_title") or "").strip() or (str((linked_course or {}).get("title") or "").strip())
        pricing_type = str(row.get("pricing_type") or "group").strip()
        monthly_fee_text = str(row.get("monthly_fee_text") or "").strip() or (
            str((linked_course or {}).get("individual_price_text") or "").strip() if pricing_type == "individual" else str((linked_course or {}).get("price_text") or "").strip()
        )
        out.append(
            {
                "id": group_id,
                "name": str(row.get("name") or ""),
                "subject": primary_subject,
                "subject_id": GROUP_SUBJECT_CODE_TO_ID.get(primary_subject.lower()),
                "primary_subject": primary_subject,
                "extra_subjects": extra_subjects,
                "subjects": all_subjects,
                "level": str(row.get("level") or "PRE-INTERMEDIATE"),
                "teacher_id": int(row.get("teacher_id") or 0) if row.get("teacher_id") is not None else None,
                "teacher_name": _display_name(teacher) if teacher else "Not assigned",
                "course_id": course_id,
                "course_title": course_title or None,
                "monthly_fee_text": monthly_fee_text or None,
                "lesson_date": row.get("lesson_date"),
                "lesson_start": row.get("lesson_start"),
                "lesson_end": row.get("lesson_end"),
                "student_count": int(student_count_by_group.get(group_id, 0)),
                "active": int(row.get("active") or 1) == 1,
                "temporary_access": bool(row.get("temporary_access")),
                "temp_assignment_next_date": row.get("temp_assignment_next_date"),
                "temp_assignment_start": row.get("temp_assignment_start"),
                "temp_assignment_end": row.get("temp_assignment_end"),
            }
        )
    return out


def _round_up_to_nearest_1000_uzs(value: float) -> float:
    amount = float(value or 0.0)
    if amount <= 0:
        return 0.0
    return float(math.ceil(amount / 1000.0) * 1000.0)


def _round_payment_nearest(amount: float, unit: int = 1000) -> float:
    value = max(0.0, float(amount or 0.0))
    step = max(1, int(unit or 1000))
    if value <= 0:
        return 0.0
    rounded_units = (Decimal(str(value)) / Decimal(step)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    return float(rounded_units * Decimal(step))


def _round_payment_amount(amount: float, has_discount: bool) -> float:
    return _round_payment_nearest(amount, 1000) if bool(has_discount) else _round_up_to_nearest_1000_uzs(amount)


_SUPPORT_TEACHER_SUBJECT_CACHE: dict[str, Any] = {"expires_at": 0.0, "subjects": set()}
_SUPPORT_TEACHER_ROWS_CACHE: dict[str, Any] = {"expires_at": 0.0, "rows": []}


def _active_support_teacher_rows_cached() -> list[dict]:
    now = time.monotonic()
    cached = _SUPPORT_TEACHER_ROWS_CACHE
    if float(cached.get("expires_at") or 0.0) > now:
        return [dict(row) for row in (cached.get("rows") or [])]
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM users
            WHERE login_type=5
              AND COALESCE(access_enabled, 1)=1
              AND COALESCE(blocked, 0)=0
              AND COALESCE(active, 1)=1
            ORDER BY id ASC
            """
        )
        rows = [dict(row) for row in (cur.fetchall() or [])]
    except Exception:
        rows = []
    finally:
        conn.close()
    _SUPPORT_TEACHER_ROWS_CACHE.update({"expires_at": now + 20.0, "rows": rows})
    return rows


def _support_teacher_ids_with_active_schedule(subject: str | None = None) -> set[int]:
    normalized = _normalize_subject_label(subject)
    conn = get_conn()
    cur = conn.cursor()
    try:
        if normalized:
            cur.execute(
                """
                SELECT DISTINCT support_teacher_id
                FROM support_teacher_weekday_settings
                WHERE subject=? AND COALESCE(active, 1)=1
                """,
                (normalized,),
            )
        else:
            cur.execute(
                """
                SELECT DISTINCT support_teacher_id
                FROM support_teacher_weekday_settings
                WHERE COALESCE(active, 1)=1
                """
            )
        return {int(row.get("support_teacher_id") or 0) for row in (cur.fetchall() or []) if int(row.get("support_teacher_id") or 0) > 0}
    except Exception:
        return set()
    finally:
        conn.close()


def _support_subjects_with_active_schedule(active_teacher_ids: set[int] | None = None) -> set[str]:
    ids = {int(item) for item in (active_teacher_ids or set()) if int(item or 0) > 0}
    conn = get_conn()
    cur = conn.cursor()
    try:
        params: list[Any] = []
        id_filter = ""
        if ids:
            placeholders = ",".join("?" for _ in ids)
            id_filter = f" AND support_teacher_id IN ({placeholders})"
            params.extend(sorted(ids))
        cur.execute(
            f"""
            SELECT DISTINCT subject
            FROM support_teacher_weekday_settings
            WHERE COALESCE(active, 1)=1
            {id_filter}
            """,
            tuple(params),
        )
        return {
            normalized
            for normalized in (_normalize_subject_label(str(row.get("subject") or "")) for row in (cur.fetchall() or []))
            if normalized
        }
    except Exception:
        return set()
    finally:
        conn.close()


def _active_support_teacher_subjects() -> set[str]:
    now = time.monotonic()
    cached = _SUPPORT_TEACHER_SUBJECT_CACHE
    if float(cached.get("expires_at") or 0.0) > now:
        return set(cached.get("subjects") or set())
    subjects: set[str] = set()
    active_rows = _active_support_teacher_rows_cached()
    active_teacher_ids = {int(row.get("id") or 0) for row in active_rows if int(row.get("id") or 0) > 0}
    for row in active_rows:
        subjects.update(_normalize_subjects(_user_subjects_from_row(row), fallback=[]))
    subjects.update(_support_subjects_with_active_schedule(active_teacher_ids))
    _SUPPORT_TEACHER_SUBJECT_CACHE.update({"expires_at": now + 20.0, "subjects": subjects})
    return subjects


def _support_staff_subjects(user: dict) -> set[str]:
    return {
        subject
        for subject in (_normalize_subject_label(item) for item in _user_subjects_from_row(user))
        if subject
    }


def _booking_visible_to_support_user(user: dict, booking: dict | None) -> bool:
    if not booking:
        return False
    staff_subjects = _support_staff_subjects(user)
    if not staff_subjects:
        return False
    assigned_teacher_id = int(booking.get("support_teacher_id") or 0)
    if assigned_teacher_id > 0:
        return assigned_teacher_id == int(user.get("id") or 0)
    booking_subject = _normalize_subject_label(str(booking.get("support_subject") or "").strip())
    return bool(booking_subject and booking_subject in staff_subjects)


def _filter_bookings_for_support_user(user: dict, bookings: list[dict] | tuple[dict, ...] | None) -> list[dict]:
    rows = [dict(row) for row in (bookings or [])]
    staff_subjects = _support_staff_subjects(user)
    if not staff_subjects:
        return []
    user_id = int(user.get("id") or 0)
    return [
        row
        for row in rows
        if (int(row.get("support_teacher_id") or 0) == user_id)
        or (
            int(row.get("support_teacher_id") or 0) <= 0
            and _normalize_subject_label(str(row.get("support_subject") or "").strip()) in staff_subjects
        )
    ]


def _booking_users_by_id(rows: list[dict] | tuple[dict, ...]) -> dict[int, dict]:
    ids = sorted(
        {
            int(value or 0)
            for row in (rows or [])
            for value in (row.get("student_user_id"), row.get("support_teacher_id"))
            if int(value or 0) > 0
        }
    )
    if not ids:
        return {}
    conn = get_conn()
    cur = conn.cursor()
    try:
        placeholders = ",".join("?" for _ in ids)
        cur.execute(f"SELECT * FROM users WHERE id IN ({placeholders})", ids)
        return {int(row.get("id") or 0): dict(row) for row in (cur.fetchall() or [])}
    except Exception:
        logger.exception("support booking user bulk load failed")
        return {}
    finally:
        conn.close()


def _serialize_booking_row(row: dict, student: dict | None = None, teacher: dict | None = None) -> dict:
    if student is None:
        student = _safe_call(lambda: get_user_by_id(int(row.get("student_user_id") or 0)), None)
    if teacher is None and int(row.get("support_teacher_id") or 0) > 0:
        teacher = _safe_call(lambda: get_user_by_id(int(row.get("support_teacher_id") or 0)), None)
    raw_status = str(row.get("status") or "").strip().lower()
    effective_status = raw_status
    end_ts = _parse_utc_timestamp(str(row.get("end_ts") or ""))
    if raw_status in {"pending", "approved"} and end_ts is not None and end_ts <= _now_utc():
        effective_status = "passed"
    return {
        "id": str(row.get("id") or ""),
        "student_user_id": int(row.get("student_user_id") or 0) if row.get("student_user_id") is not None else None,
        "student_name": _display_name(student) if student else "Student",
        "student_login_id": student.get("login_id") if student else None,
        "student_profile_image_url": student.get("profile_image_url") if student else None,
        "student_telegram_id": row.get("student_telegram_id"),
        "support_teacher_id": int(row.get("support_teacher_id") or 0) or None,
        "support_teacher_name": _display_name(teacher) if teacher else None,
        "branch": row.get("branch"),
        "date": row.get("date"),
        "time": row.get("time"),
        "start_ts": row.get("start_ts"),
        "end_ts": row.get("end_ts"),
        "purpose": row.get("purpose"),
        "support_subject": row.get("support_subject"),
        "status": effective_status or row.get("status"),
        "support_attendance_status": row.get("support_attendance_status"),
        "support_bonus_awarded": int(row.get("support_bonus_awarded") or 0) == 1,
        "support_attendance_penalty_applied": int(row.get("support_attendance_penalty_applied") or 0) == 1,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def _serialize_booking_rows(rows: list[dict] | tuple[dict, ...] | None) -> list[dict]:
    booking_rows = [dict(row) for row in (rows or [])]
    users_by_id = _booking_users_by_id(booking_rows)
    serialized: list[dict] = []
    for row in booking_rows:
        student = users_by_id.get(int(row.get("student_user_id") or 0))
        teacher = users_by_id.get(int(row.get("support_teacher_id") or 0))
        item = _serialize_booking_row(row, student, teacher)
        serialized.append(item)
    return serialized


def _serialize_review_row(row: dict, include_private: bool = False) -> dict:
    user = _safe_call(lambda: get_user_by_id(int(row.get("user_id") or 0)), None)
    is_anonymous = False
    cached_name = row.get("author_name")
    if cached_name and str(cached_name).strip():
        author_name = str(cached_name).strip()
    elif user:
        author_name = _display_name(user)
    else:
        author_name = "Diamond User"
    out = {
        "id": int(row.get("id") or 0),
        "user_id": int(row.get("user_id") or 0),
        "rating": max(1, min(5, int(row.get("rating") or 5))),
        "review_text": str(row.get("review_text") or ""),
        "is_anonymous": is_anonymous,
        "author_name": author_name,
        "status": _normalize_review_status(row.get("status")),
        "reward_dcoin": float(row.get("reward_dcoin") or 0),
        "reward_dpoints": float(row.get("reward_dcoin") or 0),
        "reward_granted_at": row.get("reward_granted_at"),
        "created_at": row.get("created_at"),
    }
    if include_private:
        out["reviewed_by"] = row.get("reviewed_by")
        out["reviewed_at"] = row.get("reviewed_at")
    return out


