def _serialize_feedback_row(row: dict, *, include_admin_private: bool = False) -> dict:
    user_id = int(row.get("user_id") or 0)
    user = _safe_call(lambda: get_user_by_id(user_id), None) or {}
    user_role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    user_payload = _build_user_payload(user) if user else None
    dcoin_total = None
    dpoint_total = None
    if user_id > 0 and user_role == "student":
        balances = _safe_call(lambda: get_user_subject_dcoins(user_id), {}) or {}
        dcoin_total = float(sum(float(v) for v in balances.values()))
        dpoint_total = float(_safe_call(lambda: get_dpoints(user_id), 0.0) or 0.0)

    out = {
        "id": int(row.get("id") or 0),
        "user_id": user_id,
        "message_text": str(row.get("message_text") or "").strip(),
        "is_anonymous": int(row.get("is_anonymous") or 0) == 1,
        "created_at": _as_iso_timestamp(row.get("created_at")),
        "dcoin_adjusted_total": float(row.get("dcoin_adjusted_total") or 0.0),
        "dpoint_adjusted_total": float(row.get("dcoin_adjusted_total") or 0.0),
        "sender_role": user_role,
    }
    if include_admin_private:
        out["sender"] = user_payload
        out["student_dcoin_balance"] = dcoin_total
        out["student_dpoint_balance"] = dpoint_total
    return out


def _feedback_push_admin_web_notification(
    *,
    sender_user: dict,
    sender_role: str,
    is_anonymous: bool,
    message_text: str,
    admin_ids: list[int],
) -> None:
    targets = [int(aid) for aid in (admin_ids or []) if int(aid) > 0]
