def _placement_subject_for_user(user: dict) -> str:
    preferred = _normalize_subject_label(str(user.get("placement_subject") or "").strip())
    subjects = _user_subjects_from_row(user)
    if preferred and preferred in subjects:
        return preferred
    return _normalize_subject_label(subjects[0] if subjects else "English") or "English"


def _placement_question_payload(question: dict, question_index: int, total_questions: int) -> dict:
    return {
        "question_id": int(question.get("id") or 0),
        "question_index": int(question_index),
        "total_questions": int(total_questions),
        "question": str(question.get("question") or ""),
        "options": {
            "A": str(question.get("option_a") or ""),
            "B": str(question.get("option_b") or ""),
            "C": str(question.get("option_c") or ""),
            "D": str(question.get("option_d") or ""),
        },
    }


def _serialize_placement_result(row: dict | None) -> dict | None:
    if not row:
        return None
    score = int(row.get("score") or 0)
    max_score = max(1, int(row.get("max_score") or 500))
    correct_count = int(row.get("correct_count") or 0) if row.get("correct_count") is not None else 0
    if correct_count <= 0:
        correct_count = max(0, min(50, score // 10))
    percentage = int(round((correct_count / 50) * 100))
    return {
        "id": int(row.get("id") or 0),
        "subject": _normalize_subject_label(str(row.get("subject") or "").strip()) or "English",
        "score": score,
        "max_score": max_score,
        "correct_count": max(0, min(50, correct_count)),
        "percentage": max(0, min(100, percentage)),
        "level": str(row.get("level") or "").strip(),
        "created_at": row.get("created_at"),
    }


async def _send_web_placement_notifications(user: dict, result_payload: dict) -> None:
    subject = _normalize_subject_label(str(result_payload.get("subject") or "").strip()) or "English"
    level_display = str(result_payload.get("level_display") or "-")
    percentage = int(result_payload.get("percentage") or 0)
    correct_count = int(result_payload.get("correct_count") or 0)

    student_text = (
        "Placement test yakunlandi.\n"
        f"Fan: {subject}\n"
        f"Natija: {correct_count}/50 ({percentage}%)\n"
        f"Level: {level_display}"
    )
    admin_text = (
        "Web placement yakunlandi.\n"
        f"Student: {_display_name(user)}\n"
        f"Login ID: {str(user.get('login_id') or '-')}\n"
        f"Fan: {subject}\n"
        f"Natija: {correct_count}/50 ({percentage}%)\n"
        f"Level: {level_display}"
    )

    student_tg = str(user.get("telegram_id") or "").strip()
    student_token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    if student_tg and student_token:
        await _send_telegram_text(student_token, student_tg, student_text)

    recipients = set(int(x) for x in ADMIN_CHAT_IDS if int(x) > 0)
    owner_admin_id = int(user.get("owner_admin_id") or 0)
    if owner_admin_id and owner_admin_id in set(int(x) for x in LIMITED_ADMIN_CHAT_IDS):
        recipients.add(owner_admin_id)
        for peer_id in _safe_call(lambda: get_peer_admins_for_student_share(int(user.get("id") or 0)), []) or []:
            recipients.add(int(peer_id))
    admin_token = (os.getenv("ADMIN_BOT_TOKEN") or "").strip()
    if admin_token:
        for admin_chat_id in recipients:
            if int(admin_chat_id) <= 0:
                continue
            await _send_telegram_text(admin_token, str(int(admin_chat_id)), admin_text)


async def _complete_web_placement(user: dict, session: dict) -> dict:
    user_id = int(user.get("id") or 0)
    subject = _normalize_subject_label(str(session.get("subject") or "").strip()) or _placement_subject_for_user(user)
    score = int(session.get("score") or 0)
    questions = session.get("questions") or []
    actual_max_score = len(questions) * 10 if questions else 500
    level_code, level_display = _placement_level_from_score(score, subject)
    update_user_level(user_id, level_display)
    save_test_result(user_id, subject, score, level_code, max_score=actual_max_score)
    set_user_login_type(user_id, 2)
    enable_access(user_id)
    set_pending_approval(user_id, True)
    clear_placement_session(user_id)

    _ensure_user_web_columns()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        "UPDATE users SET placement_required=0 WHERE id=?",
        (user_id,),
    )
    conn.commit()
    conn.close()

    refreshed = _safe_call(lambda: get_user_by_id(user_id), None) or user
    payload = {
        "completed": True,
        "subject": subject,
        "score": score,
        "max_score": actual_max_score,
        "correct_count": int(score // 10),
        "percentage": int((score / actual_max_score) * 100) if actual_max_score > 0 else 0,
        "level_code": level_code,
        "level_display": level_display,
        "user": _build_user_payload(refreshed),
    }
    await _send_web_placement_notifications(refreshed, payload)
    return payload


