    topics_completed = int(monthly.get("topics_completed") or 0)
    tests_score = 0 if tests_taken <= 0 else min(40, int(round((tests_completed / max(1, tests_taken)) * 40)))
    words_score = min(30, int(round((words_learned / 120) * 30)))
    topics_score = min(30, int(round((topics_completed / 20) * 30)))
    progress_percent = max(0, min(100, int(tests_score + words_score + topics_score)))

    subject_cards = _student_subject_progress_cards(
        user_id=user_id,
        user=user,
        subjects=subjects,
        attempts=attempts,
        monthly=monthly,
    )

    has_group_access = len(groups) > 0
    payment_overview = _payment_student_overview(user, ym=_payment_ym_now(), months_back=1, include_history=False)
    payment_current = payment_overview.get("current_month") or {}
    payment_debt = float(payment_current.get("total_debt_amount") or 0.0)
    payment_status = str(payment_current.get("status") or PAYMENT_STATUS_UNPAID)
    payment_overdue = payment_status == PAYMENT_STATUS_OVERDUE
    today_day = int(_now_tashkent().day)
    if payment_debt > 1e-9:
        user_lang = str(user.get("language") or "uz")
        
        if user_lang == "ru":
            reminder_suffix = " Сегодня день напоминания." if today_day in {5, 10, 15, 20, 25} else ""
            title_text = "Напоминание об оплате"
