@app.get("/user/sessions")
async def list_user_sessions(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    uid = int(user.get("id") or 0)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT session_id, source, last_seen_at, created_at, expires_at, device_model
            FROM web_user_sessions
            WHERE user_id=?
              AND revoked_at IS NULL
              AND expires_at > ?
            ORDER BY last_seen_at DESC, created_at DESC
            """,
            (uid, _now_utc().isoformat()),
        )
        rows = cur.fetchall()

        token = str(authorization or "").replace("Bearer ", "").strip()
        current_session_id = None
        if token:
            cached = _AUTH_USER_ROW_CACHE.get(token)
            if cached:
                current_session_id = str(cached[0] or "").strip()

        sessions = []
        for r in (rows or []):
            sid = str(r["session_id"])
            sessions.append({
                "session_id": sid,
                "source": r["source"],
                "device_model": r.get("device_model"),
                "last_seen_at": r["last_seen_at"],
                "created_at": r["created_at"],
                "expires_at": r["expires_at"],
                "is_current": sid == current_session_id
            })
        return {"items": sessions}
    finally:
        conn.close()

@app.delete("/user/sessions/{session_id}")
async def delete_user_session(session_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    uid = int(user.get("id") or 0)
    if not session_id:
        raise HTTPException(status_code=400, detail="session_id required")
        
    conn = get_conn()
    cur = conn.cursor()
    try:
        now_iso = _now_utc().isoformat()
        cur.execute(
            """
            UPDATE web_user_sessions
            SET revoked_at=?, revoked_reason=?
            WHERE session_id=? AND user_id=? AND revoked_at IS NULL
            """,
            (now_iso, "user_revoked", session_id, uid)
        )
        conn.commit()
        if cur.rowcount == 0:
            raise HTTPException(status_code=404, detail="Session not found or already revoked")
            
        if not _has_active_web_sessions(uid):
            _sync_bot_logout_state(uid)
            
        tokens_to_remove = []
        for tkn, (sid, row) in _AUTH_USER_ROW_CACHE.items():
            if sid == session_id:
                tokens_to_remove.append(tkn)
        for tkn in tokens_to_remove:
            _AUTH_USER_ROW_CACHE.pop(tkn, None)
            
        return {"success": True}
    finally:
        conn.close()


@app.patch("/user/password", response_model=TokenResponse)
async def update_user_password(payload: UserPasswordUpdateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _role_from_login_type(int(user.get("login_type") or 0), str(user.get("login_id") or ""))
    if role not in {"teacher", "support"}:
        raise HTTPException(status_code=403, detail="Only teacher and support users can change password")
    new_password = (payload.new_password or "").strip().upper()
    if len(new_password) < 6:
        raise HTTPException(status_code=400, detail="new_password must be at least 6 characters")

    user_id = int(user.get("id") or 0)
    if user_id <= 0:
        raise HTTPException(status_code=404, detail="User not found")

    # The password update rotates every other session, but the replacement
    # token belongs to this same physical device. Preserve its identifiers so
    # the device panel does not suddenly show an anonymous "password_change"
    # entry after an otherwise normal password update.
    bearer_payload = _decode_bearer_payload(authorization)
    current_session_id = str(bearer_payload.get("session_id") or "").strip()
    current_device_id: str | None = None
    current_device_model: str | None = None
    if current_session_id:
        metadata_conn = get_conn()
        metadata_cur = metadata_conn.cursor()
        try:
            metadata_cur.execute(
                """
                SELECT device_id, device_model
                FROM web_user_sessions
                WHERE session_id=? AND user_id=?
                """,
                (current_session_id, user_id),
            )
            metadata = metadata_cur.fetchone()
            if metadata:
                current_device_id = str(metadata["device_id"] or "").strip() or None
                current_device_model = str(metadata["device_model"] or "").strip() or None
        finally:
            metadata_conn.close()

    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE users
            SET password=?,
                session_version=COALESCE(session_version, 1) + 1
            WHERE id=?
            """,
            (hash_password(new_password), user_id),
        )
        conn.commit()
    finally:
        conn.close()

    _revoke_web_sessions(user_id, keep_session_id=None, reason="password_changed")
    refreshed = _safe_call(lambda: get_user_by_id(user_id), None)
    if not refreshed:
        raise HTTPException(status_code=404, detail="User not found")
    next_session_id, _ = _issue_web_session(
        refreshed,
        device_id=current_device_id,
        source="password_change",
        device_model=current_device_model,
    )
    token = _create_access_token(
        refreshed,
        telegram_id=bearer_payload.get("telegram_id"),
        session_id=next_session_id,
    )
    return TokenResponse(access_token=token, token_type="bearer", user=_build_user_payload(refreshed))


@app.get("/student/proctoring/status")
async def student_proctoring_status(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user = _ensure_face_profile_compatibility(user)
    status = get_user_proctoring_status(int(user.get("id") or 0)) or {}
    # Proctoring/FaceID removed from all test flows. Always report "not required / not blocked"
    # so the student UI never shows FaceID setup prompts, camera permission cards, or
    # proctoring blocks. Stored enrollment data (if any) is left untouched but unused.
    return {
        "user_id": int(user.get("id") or 0),
        "proctoring_required": False,
        "face_id_required": False,
        "face_id_enrolled": bool(int(status.get("face_id_enrolled") or 0)),
        "face_id_status": str(status.get("face_id_status") or "not_started"),
        "face_enrollment_required": False,
        "face_profile_status": "active",
        "face_profile_version": int(status.get("face_profile_version") or user.get("face_profile_version") or 0),
        "face_enrolled_at": status.get("face_enrolled_at"),
        "face_last_verified_at": status.get("face_last_verified_at"),
        "face_verification_method": status.get("face_verification_method"),
        "face_match_threshold": float(status.get("face_match_threshold") or 0.82),
        "proctoring_block_reason": None,
        "proctoring_hold_until": None,
        "proctoring_blocked_until": None,
        "proctoring_risk_score": 0.0,
    }


@app.post("/student/proctoring/enrollment/start")
async def student_proctoring_enrollment_start(
    payload: ProctoringEnrollmentStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user = _ensure_face_profile_compatibility(user)
    user_id = int(user.get("id") or 0)
    active_profile = get_active_face_profile(user_id)
    if active_profile:
        if not _is_insightface_embedding_model(active_profile.get("embedding_model")):
            _mark_face_reenrollment_required(user_id, profile=active_profile, reason="embedding_model_mismatch")
            active_profile = None
        else:
            expires_at = _parse_utc_timestamp(
                str(active_profile.get("face_id_expires_at") or user.get("face_id_expires_at") or "")
            )
            if expires_at is None or expires_at > _now_utc():
                logger.info(
                    "proctoring.enrollment.start.blocked_already_enrolled user_id=%s profile_id=%s expires_at=%s",
                    user_id,
                    int(active_profile.get("id") or 0),
                    active_profile.get("face_id_expires_at"),
                )
                raise HTTPException(status_code=409, detail="already_enrolled")
    device_session_id = create_or_update_proctoring_device_session(
        user_id,
        device_id=payload.device_id,
        platform=payload.platform,
        browser=payload.browser,
        telegram_init_hash=payload.telegram_init_hash,
    )
    current = get_user_proctoring_status(user_id) or {}
    append_face_profile_audit(
        user_id,
        profile_version=int(current.get("face_profile_version") or 0),
        action_type="enroll_started",
        result_status="started",
        details_json=_json_text(payload.model_dump()),
    )
    now_utc = _now_utc()
    existing_active: dict[str, Any] | None = None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM face_enrollment_sessions
            WHERE user_id=?
              AND status IN ('started', 'photo_captured', 'processing')
            ORDER BY id DESC
            LIMIT 1
            """,
            (user_id,),
        )
        row = cur.fetchone()
        existing_active = dict(row) if row else None
    finally:
        conn.close()
    if existing_active:
        expires_at = _parse_utc_timestamp(str(existing_active.get("expires_at") or ""))
        if expires_at is None or expires_at > now_utc:
            min_samples, max_samples = enrollment_sample_target()
            existing_session_id = int(existing_active.get("id") or 0)
            logger.info(
                "proctoring.enrollment.start.reuse_active user_id=%s session_id=%s",
                user_id,
                existing_session_id,
            )
            return {
                "started": True,
                "reused": True,
                "device_session_id": device_session_id,
                "enrollment_session_id": existing_session_id,
                "face_enrollment_required": _user_requires_face_enrollment(user),
                "enroll_min_samples": int(min_samples),
                "enroll_max_samples": int(max_samples),
                "scan_window_sec": int(PROCTORING_ENROLL_SCAN_WINDOW_SEC),
            }
    enrollment_session = create_face_enrollment_session(
        user_id,
        attempt_number=1,
        device_info=_json_text(payload.model_dump()),
        expires_at=(now_utc + timedelta(minutes=15)).isoformat(),
    )
    enrollment_session_id = int(enrollment_session.get("id") or 0)
    logger.info(
        "proctoring.enrollment.start user_id=%s session_id=%s device_session_id=%s",
        user_id,
        enrollment_session_id,
        int(device_session_id or 0),
    )
    min_samples, max_samples = enrollment_sample_target()
    return {
        "started": True,
        "device_session_id": device_session_id,
        "enrollment_session_id": enrollment_session_id,
        "face_enrollment_required": _user_requires_face_enrollment(user),
        "enroll_min_samples": int(min_samples),
        "enroll_max_samples": int(max_samples),
        "scan_window_sec": int(PROCTORING_ENROLL_SCAN_WINDOW_SEC),
    }


