@app.get("/chats/media/{filename}")
async def chats_serve_media(filename: str, sig: str = Query(default="")):
    """Serve signed chat/feedback images."""
    safe = Path(filename).name
    if safe != filename:
        raise HTTPException(status_code=404, detail="Image not found")
    if str(sig or "") != _chat_media_signature(safe):
        raise HTTPException(status_code=403, detail="Image access denied")
    file_path = CHAT_UPLOAD_DIR / safe
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="Image not found")
    media_type = CHAT_IMAGE_MIME_BY_EXT.get(file_path.suffix.lower()) or mimetypes.guess_type(safe)[0] or "application/octet-stream"
    return FileResponse(str(file_path), media_type=media_type)



@app.post("/student/proctoring/enrollment/capture")
async def student_proctoring_enrollment_capture(
    payload: EnrollmentCaptureRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    enrollment_session_id = int(payload.enrollment_session_id)
    enrollment = get_face_enrollment_session(enrollment_session_id, user_id)
    if not enrollment:
        raise HTTPException(status_code=404, detail="Enrollment session not found")
    if str(enrollment.get("status") or "started") not in {"started", "photo_captured", "processing"}:
        raise HTTPException(status_code=409, detail="Enrollment session is not active")

    pose_label = str(payload.sample_label or payload.pose_hint or "").strip() or "UNKNOWN"
    try:
        sample_path = resolve_proctoring_upload_path(PROCTORING_UPLOAD_DIR, payload.sample_image_url)
        image_bgr = read_image_bgr(sample_path)
        analyzed = evaluate_enrollment_sample(image_bgr)
    except (ValueError, FileNotFoundError) as exc:
        detail = _humanize_proctoring_image_error(exc)
        logger.warning(
            "proctoring.enrollment.capture.rejected user_id=%s session_id=%s pose=%s accepted=0 reason=%s",
            user_id,
            enrollment_session_id,
            pose_label,
            str(exc),
        )
        raise HTTPException(status_code=422, detail=detail) from exc
    except Exception as exc:
        logger.exception(
            "proctoring.enrollment.capture.error user_id=%s session_id=%s pose=%s",
            user_id,
            enrollment_session_id,
            pose_label,
        )
        raise HTTPException(status_code=422, detail=_humanize_proctoring_image_error(exc)) from exc

    quality = analyzed.get("quality") or {}
    accepted = bool(quality.get("accepted"))
    reason = str(quality.get("reason") or "").strip() or None
    raw_reason = str(quality.get("raw_reason") or "").strip() or reason
    relaxed_accept = bool(quality.get("relaxed_accept"))
    center_offset_ratio = float(quality.get("center_offset_ratio") or analyzed.get("center_offset_ratio") or 0.0)
    pose_check = "CENTER_REQUIRED" if str(reason or "").upper() == "FACE_NOT_CENTERED" else "CENTER_ONLY_OK"
    embedding = analyzed.get("embedding")
    sample = None
    if accepted:
        sample = add_face_sample(
            user_id=user_id,
            enrollment_session_id=enrollment_session_id,
            image_path=str(payload.sample_image_url),
            quality_score=float(quality.get("quality_score") or 0.0),
            sample_label=pose_label,
            embedding_vector=json.dumps(embedding) if embedding else None,
            embedding_hash=hashlib.sha256(json.dumps(embedding).encode("utf-8")).hexdigest() if embedding else None,
            metadata_json=_json_text({
                "pose_hint": payload.pose_hint,
                "provider": analyzed.get("provider"),
                "bbox_ratio": analyzed.get("bbox_ratio"),
                "yaw": analyzed.get("yaw"),
                "pitch": analyzed.get("pitch"),
                "face_count": analyzed.get("face_count"),
                "confidence": analyzed.get("confidence"),
                "center_offset_ratio": center_offset_ratio,
                "accepted": accepted,
                "reason": reason,
                "raw_reason": raw_reason,
                "pose_check": pose_check,
                "relaxed_accept": relaxed_accept,
                "analyze_error": analyzed.get("analyze_error"),
            }),
        )
        if not sample:
            raise HTTPException(status_code=500, detail="Failed to save accepted face sample")
    samples = list_face_samples_for_enrollment(enrollment_session_id, user_id)
    min_samples, max_samples = enrollment_sample_target()
    required_next_pose = None
    if len(samples) < min_samples:
        required_next_pose = f"pose_{len(samples) + 1}"
    elif len(samples) < max_samples:
        required_next_pose = "optional"

    logger.info(
        "proctoring.enrollment.capture user_id=%s session_id=%s pose=%s accepted=%s reason=%s quality=%.4f face_count=%s bbox_ratio=%.4f relaxed_accept=%s provider=%s collected=%s",
        user_id,
        enrollment_session_id,
        pose_label,
        int(accepted),
        reason or "ACCEPTED",
        float(quality.get("quality_score") or 0.0),
        int(analyzed.get("face_count") or 0),
        float(analyzed.get("bbox_ratio") or 0.0),
        int(relaxed_accept),
        str(analyzed.get("provider") or "unknown"),
        len(samples),
    )

    return {
        "enrollment_session_id": enrollment_session_id,
        "sample_id": int(sample.get("id") or 0) if sample else 0,
        "accepted": accepted,
        "reason": reason,
        "raw_reason": raw_reason,
        "quality_score": float(quality.get("quality_score") or 0.0),
        "blur_score": float(quality.get("blur_score") or 0.0),
        "face_count": int(analyzed.get("face_count") or 0),
        "face_box_ratio": float(analyzed.get("bbox_ratio") or 0.0),
        "yaw": analyzed.get("yaw"),
        "pitch": analyzed.get("pitch"),
        "provider": analyzed.get("provider"),
        "relaxed_accept": relaxed_accept,
        "center_offset_ratio": center_offset_ratio,
        "pose_check": pose_check,
        "quality_breakdown": {
            "quality_score": float(quality.get("quality_score") or 0.0),
            "blur_score": float(quality.get("blur_score") or 0.0),
            "face_box_ratio": float(analyzed.get("bbox_ratio") or 0.0),
            "center_offset_ratio": center_offset_ratio,
            "capture_quality_min": float(quality.get("capture_quality_min") or 0.0),
            "face_min_box_ratio": float(quality.get("face_min_box_ratio") or 0.0),
        },
        "required_next_pose": required_next_pose,
        "collected_count": len(samples),
    }


@app.get("/student/proctoring/images/{filename}")
async def student_proctoring_image(filename: str):
    safe = Path(filename).name
    if safe != filename:
        raise HTTPException(status_code=404, detail="Image not found")
    file_path = PROCTORING_UPLOAD_DIR / safe
    if not file_path.exists() or not file_path.is_file():
        placeholder = _image_placeholder_response("public, max-age=60")
        if placeholder is not None:
            return placeholder
        raise HTTPException(status_code=404, detail="Image not found")
    return FileResponse(str(file_path))


@app.post("/student/proctoring/enrollment/complete")
async def student_proctoring_enrollment_complete(
    payload: ProctoringEnrollmentCompleteRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    create_or_update_proctoring_device_session(
        user_id,
        device_id=payload.device_id,
        platform=payload.platform,
        browser=payload.browser,
        telegram_init_hash=payload.telegram_init_hash,
    )
    enrollment_session_id = int(payload.enrollment_session_id or 0)
    if enrollment_session_id <= 0:
        raise HTTPException(status_code=400, detail="enrollment_session_id is required")
    enrollment = get_face_enrollment_session(enrollment_session_id, user_id)
    if not enrollment:
        raise HTTPException(status_code=404, detail="Enrollment session not found")
    sample_rows = list_face_samples_for_enrollment(enrollment_session_id, user_id)
    selected_sample_ids = {int(v) for v in (payload.sample_ids or []) if int(v) > 0}
    if selected_sample_ids:
        sample_rows = [row for row in sample_rows if int(row.get("id") or 0) in selected_sample_ids]
    min_samples, _max_samples = enrollment_sample_target()
    if len(sample_rows) < min_samples:
        raise HTTPException(status_code=409, detail=f"At least {min_samples} valid samples are required")
    aggregated_embedding = aggregate_enrollment_embeddings(sample_rows)
    if not aggregated_embedding:
        raise HTTPException(status_code=409, detail="Could not generate a valid face embedding from samples")

    expires_at = enrollment_expiry_iso()
    try:
        completed = complete_face_enrollment(
            user_id,
            reference_image_url=payload.reference_image_url,
            capture_device_info=payload.capture_device_info,
            verification_method=payload.verification_method,
            embedding_model=payload.embedding_model,
            liveness_model=payload.liveness_model,
            primary_embedding=json.dumps(aggregated_embedding),
            face_match_threshold=payload.face_match_threshold or PROCTORING_FACE_MATCH_THRESHOLD,
            face_id_expires_at=expires_at,
        )
        finalize_face_enrollment_session(
            enrollment_session_id,
            user_id,
            status="completed",
            photo_url=payload.reference_image_url,
            liveness_passed=True,
            liveness_score=1.0,
            face_quality_score=float(sum(float(r.get("quality_score") or 0.0) for r in sample_rows) / max(1, len(sample_rows))),
            embedding_saved=True,
            profile_valid_until=expires_at,
        )
        logger.info(
            "proctoring.enrollment.complete user_id=%s session_id=%s sample_count=%s expires_at=%s",
            user_id,
            enrollment_session_id,
            len(sample_rows),
            expires_at,
        )
        return {"completed": True, **(completed or {})}
    except HTTPException:
        raise
    except Exception as exc:
        logger.exception(
            "proctoring.enrollment.complete.error user_id=%s session_id=%s",
            user_id,
            enrollment_session_id,
        )
        finalize_face_enrollment_session(
            enrollment_session_id,
            user_id,
            status="failed",
            error_message=str(exc),
            embedding_saved=False,
        )
        raise HTTPException(
            status_code=422,
            detail="Enrollment yakunlanmadi, iltimos kameraga tik qarab qayta urinib ko'ring.",
        ) from exc


@app.post("/student/proctoring/verify/start-exam")
async def student_proctoring_verify_start_exam(
    payload: VerifyStartExamRequest,
    authorization: str | None = Header(default=None),
):
    total_t0 = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user = _ensure_face_profile_compatibility(user)
    user_id = int(user.get("id") or 0)
    if int(payload.attempt_no) > PROCTORING_START_VERIFY_MAX_RETRIES:
        raise HTTPException(status_code=429, detail="Maximum verify retries exceeded")
    session_row = get_test_proctoring_session(int(payload.proctoring_session_id))
    if not session_row or int(session_row.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    profile = get_active_face_profile(user_id)
    if not profile or not _is_insightface_embedding_model(profile.get("embedding_model")):
        _mark_face_reenrollment_required(user_id, profile=profile, reason="missing_or_incompatible_profile")
        raise HTTPException(status_code=409, detail="Face profile requires re-enrollment")
    try:
        read_t0 = time.perf_counter()
        image_path = resolve_proctoring_upload_path(PROCTORING_UPLOAD_DIR, payload.snapshot_image_url)
        image_bgr = read_image_bgr(image_path)
    except (ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code=422, detail=_humanize_proctoring_image_error(exc)) from exc
    read_ms = (time.perf_counter() - read_t0) * 1000.0
    verify_t0 = time.perf_counter()
    verify = await asyncio.to_thread(
        verify_start_exam_image,
        image_bgr,
        _json_vector(profile.get("primary_embedding")),
        min(
            float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
            float(PROCTORING_START_FACE_MATCH_THRESHOLD),
        ),
    )
    verify_ms = (time.perf_counter() - verify_t0) * 1000.0
    log_test_proctoring_event(
        int(payload.proctoring_session_id),
        user_id,
        event_type="verify_start_exam",
        event_status="ok" if verify.get("verified") else "failed",
        reason_code=str(verify.get("reason") or "").strip() or None,
        score=float(verify.get("match_score") or 0.0),
        details_json=_json_text({
            "threshold": verify.get("threshold"),
            "strict_threshold": float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
            "bbox_ratio": verify.get("bbox_ratio"),
            "face_count": verify.get("face_count"),
            "provider": verify.get("provider"),
            "error": verify.get("error"),
            "engine_diagnostics": verify.get("engine_diagnostics"),
            "attempt_no": payload.attempt_no,
        }),
    )
    logger.info(
        "proctoring.verify.start_exam user_id=%s session_id=%s attempt=%s verified=%s reason=%s score=%.4f provider=%s read_ms=%.2f verify_ms=%.2f total_ms=%.2f",
        user_id,
        int(payload.proctoring_session_id),
        int(payload.attempt_no),
        int(bool(verify.get("verified"))),
        str(verify.get("reason") or ""),
        float(verify.get("match_score") or 0.0),
        str(verify.get("provider") or "unknown"),
        read_ms,
        verify_ms,
        (time.perf_counter() - total_t0) * 1000.0,
    )
    if not verify.get("verified"):
        reason = str(verify.get("reason") or "face_not_verified").strip() or "FACE_NOT_VERIFIED"
        if int(payload.attempt_no) >= PROCTORING_START_VERIFY_MAX_RETRIES:
            update_test_proctoring_session_status(
                int(payload.proctoring_session_id),
                status="failed",
                failure_reason=reason.lower(),
                final_verdict="failed",
                verdict_reason=reason,
                terminated_by="system",
            )
            _competition_mark_user_left_by_proctoring(
                user_id,
                str(session_row.get("test_type") or ""),
                str(session_row.get("test_attempt_ref") or ""),
                reason.lower(),
            )
        else:
            update_test_proctoring_session_status(
                int(payload.proctoring_session_id),
                status="active",
                face_last_seen=False,
            )
        return {
            "verified": False,
            "reason": verify.get("reason"),
            "match_score": verify.get("match_score"),
            "threshold": verify.get("threshold"),
            "provider": verify.get("provider"),
            "error": verify.get("error"),
            "strict_threshold": float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
        }
    update_test_proctoring_session_status(
        int(payload.proctoring_session_id),
        status="active",
        face_last_seen=True,
        clear_face_missing_grace=True,
        last_match_score=float(verify.get("match_score") or 0.0),
    )
    return {
        "verified": True,
        "reason": None,
        "match_score": verify.get("match_score"),
        "threshold": verify.get("threshold"),
        "strict_threshold": float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
    }


@app.post("/student/proctoring/verify/check")
async def student_proctoring_verify_check(
    payload: VerifyCheckRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user = _ensure_face_profile_compatibility(user)
    user_id = int(user.get("id") or 0)
    session_row = get_test_proctoring_session(int(payload.proctoring_session_id))
    if not session_row or int(session_row.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    profile = get_active_face_profile(user_id)
    if not profile or not _is_insightface_embedding_model(profile.get("embedding_model")):
        _mark_face_reenrollment_required(user_id, profile=profile, reason="missing_or_incompatible_profile")
        raise HTTPException(status_code=409, detail="Face profile requires re-enrollment")
    try:
        image_path = resolve_proctoring_upload_path(PROCTORING_UPLOAD_DIR, payload.snapshot_image_url)
        image_bgr = read_image_bgr(image_path)
    except (ValueError, FileNotFoundError) as exc:
        raise HTTPException(status_code=422, detail=_humanize_proctoring_image_error(exc)) from exc
    verify = await asyncio.to_thread(
        verify_recheck_image,
        image_bgr,
        _json_vector(profile.get("primary_embedding")),
        min(
            float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
            float(PROCTORING_RECHECK_FACE_MATCH_THRESHOLD),
        ),
    )
    verified = bool(verify.get("verified"))
    verify_reason = str(verify.get("reason") or "").strip().upper()
    event_type = "face_reverify_ok" if verified else ("multiple_faces" if verify_reason == "MULTIPLE_FACES" else "face_mismatch")
    event_status = "ok" if verified else ("warning" if verify_reason in {"FACE_MISMATCH", "ENGINE_ERROR", "NO_FACE", "FACE_TOO_SMALL", "MULTIPLE_FACES"} else "failed")
    log_test_proctoring_event(
        int(payload.proctoring_session_id),
        user_id,
        event_type=event_type,
        event_status=event_status,
        reason_code=str(verify.get("reason") or "").strip() or None,
        score=float(verify.get("match_score") or 0.0),
        details_json=_json_text({
            "threshold": verify.get("threshold"),
            "strict_threshold": float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
            "context_reason": str(payload.context_reason or "").strip() or None,
            "bbox_ratio": verify.get("bbox_ratio"),
            "face_count": verify.get("face_count"),
            "provider": verify.get("provider"),
            "error": verify.get("error"),
            "engine_diagnostics": verify.get("engine_diagnostics"),
        }),
    )
    logger.info(
        "proctoring.verify.recheck user_id=%s session_id=%s verified=%s reason=%s score=%.4f provider=%s",
        user_id,
        int(payload.proctoring_session_id),
        int(verified),
        str(verify.get("reason") or ""),
        float(verify.get("match_score") or 0.0),
        str(verify.get("provider") or "unknown"),
    )
    session_id = int(payload.proctoring_session_id)
    mismatch_strikes = int((session_row or {}).get("face_different_person_count") or 0)
    confirmed_mismatch = False
    fail_applied = False
    if verified:
        if mismatch_strikes > 0:
            increment_test_proctoring_counter(session_id, "face_different_person_count", -mismatch_strikes)
        update_test_proctoring_session_status(
            session_id,
            status="active",
            face_last_seen=True,
            clear_face_missing_grace=True,
            clear_warning_grace=True,
            last_match_score=float(verify.get("match_score") or 0.0),
        )
        mismatch_strikes = 0
    elif verify_reason == "FACE_MISMATCH":
        increment_test_proctoring_counter(session_id, "face_different_person_count", 1)
        updated_row = get_test_proctoring_session(session_id) or session_row or {}
        mismatch_strikes = int(updated_row.get("face_different_person_count") or 0)
        confirmed_mismatch = mismatch_strikes >= PROCTORING_FACE_MISMATCH_CONFIRMATION_LIMIT
        log_test_proctoring_event(
            session_id,
            user_id,
            event_type="face_mismatch_warning" if not confirmed_mismatch else "confirmed_face_mismatch_fail",
            event_status="warning" if not confirmed_mismatch else "failed",
            reason_code="FACE_MISMATCH",
            score=float(verify.get("match_score") or 0.0),
            details_json=_json_text({
                "mismatch_strikes": mismatch_strikes,
                "required_strikes": PROCTORING_FACE_MISMATCH_CONFIRMATION_LIMIT,
                "threshold": verify.get("threshold"),
                "context_reason": str(payload.context_reason or "").strip() or None,
            }),
        )
        logger.info(
            "proctoring.face_mismatch_warning user_id=%s session_id=%s strikes=%s/%s score=%.4f confirmed=%s",
            user_id,
            session_id,
            mismatch_strikes,
            PROCTORING_FACE_MISMATCH_CONFIRMATION_LIMIT,
            float(verify.get("match_score") or 0.0),
            int(confirmed_mismatch),
        )
        if confirmed_mismatch:
            reason = "confirmed_face_mismatch"
            failed = update_test_proctoring_session_status(
                session_id,
                status="failed",
                failure_reason=reason,
                final_verdict="failed",
                verdict_reason=reason,
                terminated_by="system",
                clear_warning_grace=True,
                clear_face_missing_grace=True,
            ) or updated_row
            _apply_proctoring_event_batch(dict(failed), ProctoringEventsRequest(events=[]))
            fail_applied = True
        else:
            update_test_proctoring_session_status(
                session_id,
                status="active",
                face_last_seen=False,
                last_match_score=float(verify.get("match_score") or 0.0),
            )
    elif verify_reason == "ENGINE_ERROR":
        logger.warning(
            "proctoring.verify.engine_warning user_id=%s session_id=%s error=%s",
            user_id,
            session_id,
            str(verify.get("error") or ""),
        )
        update_test_proctoring_session_status(session_id, status="active", last_match_score=float(verify.get("match_score") or 0.0))
    elif not verified and str(verify.get("reason") or "") in {"EMBEDDING_MISSING", "PROFILE_EMBEDDING_MISSING"}:
        session_row = get_test_proctoring_session(int(payload.proctoring_session_id)) or {}
        reason = str(verify.get("reason") or "FACE_MISMATCH").strip().lower() or "face_mismatch"
        failed = update_test_proctoring_session_status(
            int(payload.proctoring_session_id),
            status="failed",
            failure_reason=reason,
            final_verdict="failed",
            verdict_reason=reason,
            terminated_by="system",
            clear_warning_grace=True,
            clear_face_missing_grace=True,
        ) or session_row
        _apply_proctoring_event_batch(dict(failed), ProctoringEventsRequest(events=[]))
        fail_applied = True
    return {
        "verified": verified,
        "match_score": verify.get("match_score"),
        "threshold": verify.get("threshold"),
        "strict_threshold": float(user.get("face_match_threshold") or PROCTORING_FACE_MATCH_THRESHOLD),
        "reason": verify.get("reason"),
        "provider": verify.get("provider"),
        "error": verify.get("error"),
        "warning": bool((not verified) and verify_reason in {"FACE_MISMATCH", "ENGINE_ERROR"} and not fail_applied),
        "confirmed_mismatch": confirmed_mismatch,
        "fail_applied": fail_applied,
        "mismatch_strikes": mismatch_strikes,
        "mismatch_limit": PROCTORING_FACE_MISMATCH_CONFIRMATION_LIMIT,
    }


@app.post("/student/proctoring/session/start")
async def student_proctoring_session_start(
    payload: ProctoringSessionStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_proctoring_ready(user)
    create_or_update_proctoring_device_session(
        int(user.get("id") or 0),
        device_id=payload.device_id,
        platform=payload.platform,
        browser=payload.browser,
        telegram_init_hash=payload.telegram_init_hash,
    )
    active_row = get_active_test_proctoring_session(
        int(user.get("id") or 0),
        str(payload.test_type or "").strip(),
        str(payload.test_attempt_ref or "").strip() or None,
    )
    if active_row:
        created_at = _parse_utc_timestamp(str(active_row.get("created_at") or active_row.get("started_at") or ""))
        age_sec = (_now_utc() - created_at).total_seconds() if created_at else 0
        unverified = not bool(int(active_row.get("face_last_seen") or 0))
        has_start_warning = int(active_row.get("warning_count") or 0) > 0 or bool(str(active_row.get("failure_reason") or "").strip())
        if unverified:
            logger.info(
                "proctoring.session.start replacing unverified session user_id=%s old_session_id=%s test_type=%s attempt_ref=%s age_sec=%.1f warning_count=%s had_warning=%s",
                int(user.get("id") or 0),
                int(active_row.get("id") or 0),
                str(payload.test_type or "").strip(),
                str(payload.test_attempt_ref or "").strip() or None,
                age_sec,
                int(active_row.get("warning_count") or 0),
                int(has_start_warning),
            )
            update_test_proctoring_session_status(
                int(active_row.get("id") or 0),
                status="aborted",
                failure_reason="unverified_camera_start_replaced",
                final_verdict="aborted",
                verdict_reason="unverified_camera_start_replaced",
                terminated_by="system",
            )
            active_row = None
    _abort_unverified_active_proctoring_sessions_for_user(
        int(user.get("id") or 0),
        exclude_session_id=int((active_row or {}).get("id") or 0) or None,
        reason="fresh_camera_start_requested",
    )
    row = active_row or create_test_proctoring_session(
        int(user.get("id") or 0),
        test_type=str(payload.test_type or "").strip(),
        test_attempt_ref=str(payload.test_attempt_ref or "").strip() or None,
        test_route=payload.test_route,
        selfie_preview_required=bool(payload.selfie_preview_required),
    )
    return {
        "session_id": int(row.get("id") or 0),
        "status": str(row.get("status") or "active"),
        "test_type": str(row.get("test_type") or ""),
        "test_attempt_ref": str(row.get("test_attempt_ref") or "") or None,
        "selfie_preview_required": bool(int(row.get("selfie_preview_required") or 0)),
    }


@app.post("/student/proctoring/session/{session_id}/events")
async def student_proctoring_session_events(
    session_id: int,
    payload: ProctoringEventsRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    session_row = get_test_proctoring_session(int(session_id))
    if not session_row:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    if int(session_row.get("user_id") or 0) != int(user.get("id") or 0):
        raise HTTPException(status_code=403, detail="Proctoring session does not belong to current user")
    updated = _apply_proctoring_event_batch(dict(session_row), payload)
    return {
        "session_id": int(updated.get("id") or 0),
        "status": str(updated.get("status") or "active"),
        "failure_reason": str(updated.get("failure_reason") or "").strip() or None,
        "penalty_applied": bool(int(updated.get("penalty_applied") or 0)),
        "warning_count": int(updated.get("warning_count") or 0),
        "warning_limit": PROCTORING_WARNING_LIMIT,
        "warning_grace_until": updated.get("warning_grace_until"),
        "face_missing_grace_until": updated.get("face_missing_grace_until"),
        "app_blur_grace_until": updated.get("app_blur_grace_until"),
    }


@app.get("/student/proctoring/session/{session_id}/status")
async def student_proctoring_session_status(
    session_id: int,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    row = get_test_proctoring_session(int(session_id))
    if not row or int(row.get("user_id") or 0) != int(user.get("id") or 0):
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    return {
        "session_id": int(row.get("id") or 0),
        "status": str(row.get("status") or "active"),
        "failure_reason": str(row.get("failure_reason") or "").strip() or None,
        "final_verdict": str(row.get("final_verdict") or "pending"),
        "verdict_reason": str(row.get("verdict_reason") or "").strip() or None,
        "terminated_by": str(row.get("terminated_by") or "").strip() or None,
        "face_missing_count": int(row.get("face_missing_count") or 0),
        "face_different_person_count": int(row.get("face_different_person_count") or 0),
        "app_hidden_count": int(row.get("app_hidden_count") or 0),
        "screenshot_attempt_count": int(row.get("screenshot_attempt_count") or 0),
    }


@app.post("/student/proctoring/session/{session_id}/complete")
async def student_proctoring_session_complete(
    session_id: int,
    payload: ProctoringSessionCompleteRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    row = get_test_proctoring_session(int(session_id))
    if not row:
        raise HTTPException(status_code=404, detail="Proctoring session not found")
    if int(row.get("user_id") or 0) != int(user.get("id") or 0):
        raise HTTPException(status_code=403, detail="Proctoring session does not belong to current user")
    if str(row.get("status") or "") == "failed":
        return {
            "session_id": int(row.get("id") or 0),
            "status": "failed",
            "failure_reason": str(row.get("failure_reason") or row.get("verdict_reason") or "proctoring_failed"),
        }
    if payload.final_status != "passed":
        updated = update_test_proctoring_session_status(
            int(session_id),
            status="failed",
            failure_reason="session_closed",
            final_verdict="failed",
            verdict_reason="session_closed",
            terminated_by="system",
            clear_warning_grace=True,
            clear_app_blur_grace=True,
            clear_face_missing_grace=True,
        ) or row
        if not bool(int((updated or {}).get("penalty_applied") or 0)):
            penalty_amount, penalty_details = _proctoring_max_dpoint_penalty(dict(updated or {}))
            penalty_details["reason"] = "session_closed"
            apply_proctoring_penalty(
                int(user.get("id") or 0),
                int(session_id),
                test_type=str((updated or {}).get("test_type") or ""),
                penalty_rule="session_closed",
                penalty_percent=0.0,
                penalty_amount=float(penalty_amount),
                details_json=_json_text(penalty_details),
            )
            updated = get_test_proctoring_session(int(session_id)) or updated
        if str((updated or {}).get("test_type") or "").strip().lower() == "daily":
            attempt_ref = str((updated or {}).get("test_attempt_ref") or "").strip()
            if attempt_ref.isdigit():
                _safe_call(lambda: mark_daily_test_attempt_failed(int(attempt_ref)), False)
        _competition_mark_user_left_by_proctoring(
            int(user.get("id") or 0),
            str((updated or {}).get("test_type") or ""),
            str((updated or {}).get("test_attempt_ref") or ""),
            "session_closed",
        )
        return {"session_id": int((updated or {}).get("id") or session_id), "status": "failed", "failure_reason": "session_closed"}

    updated = update_test_proctoring_session_status(
        int(session_id),
        status="passed",
        final_verdict="passed",
        verdict_reason=None,
        terminated_by="system",
    ) or row
    return {"session_id": int(updated.get("id") or 0), "status": str(updated.get("status") or "aborted")}


@app.get("/app/state")
async def app_state(
    authorization: str | None = Header(default=None),
    role: str | None = Query(default=None, description="Admin preview role"),
    scope: str | None = Query(default="boot", description="boot returns only startup-critical data; full returns dashboard detail"),
    include_heavy: bool = Query(default=False, description="Legacy heavy payload; normal clients should leave this false"),
):
    user = _user_row_from_bearer(authorization)
    actual_role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if actual_role == "accountless":
        raise HTTPException(status_code=403, detail="Accountless student has no web access")
    effective_role = actual_role
    requested = (role or "").strip().lower()
    if actual_role == "admin" and requested in {"student", "teacher", "support", "admin"}:
        effective_role = requested

    scope_value = str(scope or "boot").strip().lower()
    full_state = scope_value in {"full", "dashboard", "all"}
    cache_key = None
    if not full_state or not include_heavy:
        cache_scope = "full_modular" if full_state else "boot"
        cache_key = (int(user.get("id") or 0), str(actual_role), str(effective_role), cache_scope)
        cached_boot = _APP_STATE_BOOT_CACHE.get(cache_key)
        if cached_boot and cached_boot[0] > time.time():
            return dict(cached_boot[1])
        lock = _hot_cache_key_lock("app_state", cache_key)
        with lock:
            cached_boot = _APP_STATE_BOOT_CACHE.get(cache_key)
            if cached_boot and cached_boot[0] > time.time():
                return dict(cached_boot[1])
            economy_rules_payload = _app_state_economy_payload_cached()
            base_payload = {
                "timestamp": _now_utc().isoformat(),
                "user": _build_user_payload(user),
                "actual_role": actual_role,
                "effective_role": effective_role,
                "state_scope": "full_modular" if full_state else "boot",
                "sections": SECTIONS_BY_ROLE,
                "economy_rules": economy_rules_payload,
                effective_role: _build_role_boot_payload(user, effective_role, economy_rules_payload),
            }
            _APP_STATE_BOOT_CACHE[cache_key] = (time.time() + 8.0, dict(base_payload))
            return base_payload

    economy_rules_payload = _app_state_economy_payload_cached()

    base_payload = {
        "timestamp": _now_utc().isoformat(),
        "user": _build_user_payload(user),
        "actual_role": actual_role,
        "effective_role": effective_role,
        "state_scope": "full" if full_state else "boot",
        "sections": SECTIONS_BY_ROLE,
        "economy_rules": economy_rules_payload,
    }

    if effective_role == "student":
        if bool(int(user.get("placement_required") or 0)):
            base_payload["student"] = {
                "placement": {
                    "required": True,
                    "subject": (_normalize_subject_label(str(user.get("placement_subject") or "").strip()) or None),
                },
                "stats": {},
                "subjects": [],
                "groups": [],
                "daily_test_history": [],
                "bookings": [],
                "leaderboard": [],
                "articles": [],
                "dcoin": {"rules": economy_rules_payload, "by_subject": {}, "total": 0, "transactions": []},
            }
        else:
            base_payload["student"] = _build_student_payload(user)
    elif effective_role == "teacher":
        base_payload["teacher"] = _build_teacher_payload(user)
    elif effective_role == "support":
        base_payload["support"] = _build_support_payload(user)
    else:
        base_payload["admin"] = _build_admin_payload(user)

    return base_payload


@app.get("/chats/contacts")
async def chats_contacts(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "admin", "support"})
    user_id = int(user.get("id") or 0)
    ensure_diamondvoy_chat_schema()

    items: list[dict[str, Any]] = []

    # Diamondvoy chat for all roles
    ai_rows = _safe_call(lambda: list_diamondvoy_chats_for_user(int(user_id), limit=1), []) or []
    ai_chat = ai_rows[0] if ai_rows else None
    if not ai_chat:
        ai_chat_id = _ensure_student_diamondvoy_default_chat(int(user_id))
        if ai_chat_id > 0:
            ai_chat = _safe_call(lambda cid=ai_chat_id: get_diamondvoy_chat_for_user(int(user_id), int(cid)), None)
        if not ai_chat:
            # Hard fallback to guarantee Diamondvoy presence in contacts.
            created_chat = _safe_call(lambda: create_diamondvoy_chat(int(user_id), "Diamondvoy"), None) or {}
            created_id = int(created_chat.get("id") or 0)
            if created_id > 0:
                ai_chat = _safe_call(
                    lambda cid=created_id: get_diamondvoy_chat_for_user(int(user_id), int(cid)),
                    None,
                ) or created_chat
    if ai_chat:
        ai_chat_id = int(ai_chat.get("id") or 0)
        if ai_chat_id > 0:
            items.append(
                {
                    "id": f"ai:{ai_chat_id}",
                    "kind": "ai",
                    "thread_id": None,
                    "ai_chat_id": ai_chat_id,
                    "name": "Diamondvoy",
                    "role": "ai",
                    "unread_count": 0,
                    "last_message": str(ai_chat.get("last_message_preview") or "").strip() or None,
                    "last_time": _as_iso_timestamp(ai_chat.get("updated_at") or ai_chat.get("created_at")),
                }
            )

    # Feedback / Suggestions
    items.append({
        "id": "feedback_virtual",
        "kind": "feedback",
        "thread_id": None,
        "name": "Taklif / Fikr bildirish",
        "role": "feedback",
        "unread_count": 0,
        "last_message": "Send feedback or suggestions",
        "last_time": None,
    })

    items.sort(key=lambda entry: str(entry.get("last_time") or ""), reverse=True)
    return {"items": items}


