def _ensure_diamondvoy_gen_jobs_schema() -> None:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS web_diamondvoy_gen_jobs (
                job_id TEXT PRIMARY KEY,
                chat_id BIGINT NOT NULL,
                user_id BIGINT NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'running',
                content TEXT NOT NULL DEFAULT '',
                chat_title TEXT,
                error TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
            """
        )
        cur.execute("CREATE INDEX IF NOT EXISTS idx_diamondvoy_gen_jobs_chat ON web_diamondvoy_gen_jobs(chat_id, created_at)")
        conn.commit()
    finally:
        conn.close()


def _save_diamondvoy_gen_job(job: dict[str, Any]) -> None:
    _ensure_diamondvoy_gen_jobs_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_diamondvoy_gen_jobs (job_id, chat_id, user_id, status, content, chat_title, error, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(job_id) DO UPDATE SET
                status=excluded.status,
                content=excluded.content,
                chat_title=excluded.chat_title,
                error=excluded.error,
                updated_at=CURRENT_TIMESTAMP
            """,
            (
                str(job["job_id"]),
                int(job["chat_id"]),
                int(job.get("user_id") or 0),
                str(job.get("status") or "running"),
                str(job.get("content") or ""),
                job.get("chat_title"),
                job.get("error"),
            ),
        )
        conn.commit()
    finally:
        conn.close()


def _get_diamondvoy_gen_job(job_id: str) -> dict[str, Any] | None:
    _ensure_diamondvoy_gen_jobs_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM web_diamondvoy_gen_jobs WHERE job_id=? LIMIT 1", (str(job_id),))
        row = cur.fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def _get_active_diamondvoy_gen_job_for_chat(chat_id: int) -> dict[str, Any] | None:
    """Used when the app reopens a chat: is there still an in-progress
    generation for this chat that the client can re-attach to (poll)
    instead of starting a brand new message?"""
    _ensure_diamondvoy_gen_jobs_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "SELECT * FROM web_diamondvoy_gen_jobs WHERE chat_id=? AND status='running' ORDER BY created_at DESC LIMIT 1",
            (int(chat_id),),
        )
        row = cur.fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


async def _diamondvoy_run_generation_job(
    *,
    job_id: str,
    chat_id: int,
    user_id: int,
    role: str,
    user: dict,
    user_text: str,
    image_urls: list[str],
    query_lang: str,
    prior_context: list[dict[str, str]],
    subjects: list[str],
    current_chat_title: str,
) -> None:
    """The actual LLM call, fully decoupled from the client's HTTP/SSE
    connection. Runs to completion (saves the assistant message + updates
    the chat title + logs/memory) via `asyncio.create_task` regardless of
    whether the app is still connected/foregrounded — this is what makes
    generation survive the user leaving the Diamondvoy chat mid-answer.
    `event_stream()` below still tails this job's `content` column for
    clients that stay connected, so the live-typing experience is
    unchanged when the app stays open.
    """
    streamed = ""
    try:
        style_hint = _diamondvoy_user_style_prompt(user_id, query_lang)
        role_context_hint = {
            "student": "You are assisting a student. Answer educational and school-related questions only.",
            "teacher": "You are assisting a teacher. Answer educational, teaching, and role-work questions only.",
            "support": "You are assisting a support teacher. Answer educational, support lesson, and role-work questions only.",
            "admin": "You are assisting an admin. You may answer education, platform, management, payment, users, and group questions.",
        }.get(role, "You are assisting an education platform user.")
        if role == "teacher":
            teacher_groups = _safe_call(lambda: get_groups_by_teacher(int(user_id)), []) or []
            if teacher_groups:
                group_names = ", ".join([f"{g.get('name')} (ID: {g.get('id')})" for g in teacher_groups])
                role_context_hint += f"\nSizning guruhlaringiz: {group_names}."
            else:
                role_context_hint += "\nSizda hozircha faol guruhlar yo'q."
        history_lines = []
        for item in prior_context[-8:]:
            history_lines.append(f"{item['role']}: {item['content'][:1200]}")
        image_note = "\nImages are attached. Analyze them only if they are educational." if image_urls else ""
        memory_note = "" if image_urls else _diamondvoy_related_memory_prompt(user_id, user_text, limit=3)
        ai_user_text = (
            f"{role_context_hint}\n"
            f"{style_hint}\n"
            f"Reply in the user's language when possible. Return plain text only.\n"
            f"{image_note}\n\n"
            f"{memory_note}\n\n"
            f"Recent conversation:\n{chr(10).join(history_lines)}\n\n"
            f"User request:\n{user_text or '[image-only educational request]'}"
        )

        if image_urls:
            vision_images = [_chat_media_data_url(url) for url in image_urls]
            async with aiohttp.ClientSession() as session:
                gen = _xai_generate_text_stream_with_images(ai_user_text, vision_images, session=session)
                while True:
                    try:
                        chunk = await asyncio.wait_for(anext(gen), timeout=20.0)
                        if not chunk:
                            continue
                        streamed += chunk
                        _save_diamondvoy_gen_job({"job_id": job_id, "chat_id": chat_id, "user_id": user_id, "status": "running", "content": streamed, "chat_title": current_chat_title})
                    except (asyncio.TimeoutError, TimeoutError):
                        continue
                    except StopAsyncIteration:
                        break
        else:
            gen = diamondvoy_gemini_answer_stream(
                ai_user_text,
                subjects,
                lang=query_lang,
                is_admin_context=role in {"admin", "teacher", "support"},
                conversation=prior_context,
            )
            while True:
                try:
                    chunk = await asyncio.wait_for(anext(gen), timeout=15.0)
                    if not chunk:
                        continue
                    streamed += chunk
                    _save_diamondvoy_gen_job({"job_id": job_id, "chat_id": chat_id, "user_id": user_id, "status": "running", "content": streamed, "chat_title": current_chat_title})
                except (asyncio.TimeoutError, TimeoutError):
                    continue
                except StopAsyncIteration:
                    break

        assistant_text = sanitize_diamondvoy_reply(streamed.strip() or t(query_lang, "diamondvoy_answer_empty"))
        _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
        latest_title, latest_user_msg_count = _diamondvoy_autotitle_from_recent_messages(int(chat_id), max_user_messages=3)
        if latest_user_msg_count >= 2 and latest_title:
            current_chat_title = latest_title
            _safe_call(lambda: update_diamondvoy_chat_title(int(chat_id), current_chat_title), None)
        _safe_call(
            lambda: log_diamondvoy_query(
                user_id,
                user_text or "[image]",
                assistant_text,
                subject=subjects[0] if subjects else None,
                bot_scope="web_final_chat",
            ),
            None,
        )
        if user_text and not image_urls:
            _safe_call(
                lambda: _diamondvoy_save_memory(
                    user_id=user_id,
                    role=role,
                    question=user_text,
                    answer=assistant_text,
                    subject=subjects[0] if subjects else None,
                    chat_id=int(chat_id),
                ),
                None,
            )
        _save_diamondvoy_gen_job({"job_id": job_id, "chat_id": chat_id, "user_id": user_id, "status": "done", "content": assistant_text, "chat_title": current_chat_title})
    except Exception as exc:
        logger.exception("diamondvoy generation job failed job_id=%s chat_id=%s user_id=%s", job_id, chat_id, user_id)
        _save_diamondvoy_gen_job({
            "job_id": job_id,
            "chat_id": chat_id,
            "user_id": user_id,
            "status": "failed",
            "content": streamed,
            "chat_title": current_chat_title,
            "error": t(query_lang, "diamondvoy_generation_error"),
        })


async def _diamondvoy_stream_events(
    *,
    chat_id: int,
    payload: DiamondvoySendMessageRequest,
    user: dict,
    role: str,
    request: Request | None = None,
    regenerate: bool = False,
):
    user_id = int(user.get("id") or 0)
    chat_row = _diamondvoy_get_chat_for_user_final(int(chat_id), user_id)
    user_text = str(payload.message or "").strip()
    image_urls = _validate_chat_image_urls(payload.image_urls)
    if not user_text and not image_urls:
        raise HTTPException(status_code=400, detail="Xabar yoki rasm yuboring")

    if not regenerate:
        _diamondvoy_apply_usage(user, role, has_images=bool(image_urls), has_text=bool(user_text))
        user_message = _diamondvoy_insert_message(int(chat_id), "user", user_text)
        if not user_message:
            raise HTTPException(status_code=500, detail="Could not save user message")
        _diamondvoy_insert_attachments(int(chat_id), int(user_message.get("id") or 0), image_urls)
    else:
        if role not in {"admin", "teacher", "support"}:
            raise HTTPException(status_code=403, detail="Regenerate is not available for students")

    prior_context = _diamondvoy_build_context_messages(int(chat_id), limit=12)
    lang = str(user.get("language") or "uz").lower()
    if lang not in {"uz", "ru", "en"}:
        lang = "uz"
    query_lang = detect_query_language(user_text, fallback=lang)
    if user_text:
        _safe_call(lambda: _diamondvoy_upsert_user_style(user_id, user_text, query_lang), None)

    if not regenerate and role in {"teacher", "support"}:
        norm = user_text.strip().lower()
        if re.search(r"^(homework ber|create homework|vazifa ber|topshiriq ber|make homework|uy vazifasi berish)", norm):
            async def fast_wizard_stream():
                current_chat_title = str(chat_row.get("title") or "Yangi chat").strip() or "Yangi chat"
                assistant_text = json.dumps({"type": "wizard_trigger", "wizard": "homework"})
                _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
                yield _sse_pack("delta", {"delta": "", "content": assistant_text})
                yield _sse_pack("done", {"content": assistant_text, "chat_id": int(chat_id), "chat_title": current_chat_title})
            return StreamingResponse(fast_wizard_stream(), media_type="text/event-stream")

    if not regenerate and role == "admin":
        norm = user_text.strip().lower()
        if re.search(
            r"(yangi.*o.quvchi|add.*student|student.*qo.sh|o.quvchi.*qo.sh|bulk.*student|xlsx.*student|student.*xlsx)",
            norm,
        ):
            async def fast_add_students_stream():
                current_chat_title = str(chat_row.get("title") or "Yangi chat").strip() or "Yangi chat"
                assistant_text = json.dumps({"type": "wizard_trigger", "wizard": "add_students"})
                _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
                yield _sse_pack("delta", {"delta": "", "content": assistant_text})
                yield _sse_pack("done", {"content": assistant_text, "chat_id": int(chat_id), "chat_title": current_chat_title})
            return StreamingResponse(fast_add_students_stream(), media_type="text/event-stream")

    async def event_stream():
        current_chat_title = str(chat_row.get("title") or "Yangi chat").strip() or "Yangi chat"
        assistant_text = ""
        try:
            yield _sse_pack(
                "status",
                {
                    "status": "thinking",
                    "label": "Diamondvoy is Thinking",
                    "message": "Diamondvoy is Thinking",
                },
            )

            allowed = await _diamondvoy_allowed_for_role(user, role, user_text, bool(image_urls))
            if not allowed:
                assistant_text = _diamondvoy_refusal_for_role(role)
                _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
                full = ""
                for i in range(0, len(assistant_text), 8):
                    piece = assistant_text[i : i + 8]
                    full += piece
                    yield _sse_pack("delta", {"delta": piece, "content": full})
                    await asyncio.sleep(0.03)
                yield _sse_pack("done", {"content": assistant_text, "chat_id": int(chat_id), "chat_title": current_chat_title})
                return

            subjects = default_subjects_for_diamondvoy(user)
            
            from teacher_hw import handle_web_diamondvoy_hw_fsm
            hw_fsm_reply = await handle_web_diamondvoy_hw_fsm(user_id, int(chat_id), user_text, image_urls, role)
            if hw_fsm_reply:
                _diamondvoy_insert_message(int(chat_id), "assistant", hw_fsm_reply)
                full = ""
                for i in range(0, len(hw_fsm_reply), 15):
                    piece = hw_fsm_reply[i : i + 15]
                    full += piece
                    yield _sse_pack("delta", {"delta": piece, "content": full})
                    await asyncio.sleep(0.01)
                yield _sse_pack("done", {"content": hw_fsm_reply, "chat_id": int(chat_id), "chat_title": current_chat_title})
                return

            if not image_urls:
                info_text = try_diamondvoy_bot_info(
                    user_text,
                    user=user,
                    telegram_user_id=0,
                    lang=query_lang,
                    scope="admin" if role == "admin" else "student_limited",
                    student_state_map=None,
                )
                if info_text is not None:
                    assistant_text = re.sub(r"<[^>]+>", "", html.unescape(str(info_text or ""))).strip()
                    _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
                    full = ""
                    for i in range(0, len(assistant_text), 8):
                        piece = assistant_text[i : i + 8]
                        full += piece
                        yield _sse_pack("delta", {"delta": piece, "content": full})
                        await asyncio.sleep(0.03)
                    yield _sse_pack("done", {"content": assistant_text, "chat_id": int(chat_id), "chat_title": current_chat_title})
                    return

            style_hint = _diamondvoy_user_style_prompt(user_id, query_lang)
            if user_text and not image_urls:
                cached = _safe_call(lambda: _diamondvoy_find_cached_answer(user_id, user_text), None)
                if cached:
                    _safe_call(lambda: _diamondvoy_touch_memory(int(cached.get("id") or 0)), None)
                    assistant_text = _diamondvoy_cached_answer_for_style(str(cached.get("answer_text") or ""), query_lang, style_hint)
                    _diamondvoy_insert_message(int(chat_id), "assistant", assistant_text)
                    full = ""
                    for i in range(0, len(assistant_text), 12):
                        piece = assistant_text[i : i + 12]
                        full += piece
                        yield _sse_pack("delta", {"delta": piece, "content": full, "cached": True})
                        await asyncio.sleep(0.02)
                    yield _sse_pack(
                        "done",
                        {
                            "content": assistant_text,
                            "chat_id": int(chat_id),
                            "chat_title": current_chat_title,
                            "cached": True,
                            "match_score": cached.get("match_score"),
                        },
                    )
                    return

            role_context_hint = {
                "student": "You are assisting a student. Answer educational and school-related questions only.",
                "teacher": "You are assisting a teacher. Answer educational, teaching, and role-work questions only.",
                "support": "You are assisting a support teacher. Answer educational, support lesson, and role-work questions only.",
                "admin": "You are assisting an admin. You may answer education, platform, management, payment, users, and group questions.",
            }.get(role, "You are assisting an education platform user.")
            
            if role == "teacher":
                teacher_groups = _safe_call(lambda: get_groups_by_teacher(int(user_id)), []) or []
                if teacher_groups:
                    group_names = ", ".join([f"{g.get('name')} (ID: {g.get('id')})" for g in teacher_groups])
                    role_context_hint += f"\nSizning guruhlaringiz: {group_names}."
                else:
                    role_context_hint += "\nSizda hozircha faol guruhlar yo'q."
            history_lines = []
            for item in prior_context[-8:]:
                history_lines.append(f"{item['role']}: {item['content'][:1200]}")
            image_note = "\nImages are attached. Analyze them only if they are educational." if image_urls else ""
            memory_note = "" if image_urls else _diamondvoy_related_memory_prompt(user_id, user_text, limit=3)
            ai_user_text = (
                f"{role_context_hint}\n"
                f"{style_hint}\n"
                f"Reply in the user's language when possible. Return plain text only.\n"
                f"{image_note}\n\n"
                f"{memory_note}\n\n"
                f"Recent conversation:\n{chr(10).join(history_lines)}\n\n"
                f"User request:\n{user_text or '[image-only educational request]'}"
            )

            # The actual LLM call is launched as a standalone background
            # task (survives this HTTP/SSE connection closing — app
            # backgrounded, navigated away, network drop, etc) and
            # persisted incrementally to `web_diamondvoy_gen_jobs`. This
            # generator just tails that job's `content` column and forwards
            # deltas to the client for as long as the client stays
            # connected; if it disconnects, the task keeps running and the
            # final assistant message still gets saved to the chat.
            job_id = uuid4().hex
            _save_diamondvoy_gen_job({"job_id": job_id, "chat_id": int(chat_id), "user_id": user_id, "status": "running", "content": "", "chat_title": current_chat_title})
            asyncio.create_task(
                _diamondvoy_run_generation_job(
                    job_id=job_id,
                    chat_id=int(chat_id),
                    user_id=user_id,
                    role=role,
                    user=user,
                    user_text=user_text,
                    image_urls=image_urls,
                    query_lang=query_lang,
                    prior_context=prior_context,
                    subjects=subjects,
                    current_chat_title=current_chat_title,
                )
            )

            last_sent = ""
            while True:
                job = await asyncio.get_event_loop().run_in_executor(None, _get_diamondvoy_gen_job, job_id)
                job_status = str((job or {}).get("status") or "running")
                job_content = str((job or {}).get("content") or "")
                if job_content != last_sent:
                    delta = job_content[len(last_sent):] if job_content.startswith(last_sent) else job_content
                    last_sent = job_content
                    yield _sse_pack("delta", {"delta": delta, "content": job_content})
                if job_status == "done":
                    final_title = str((job or {}).get("chat_title") or current_chat_title)
                    yield _sse_pack("done", {"content": job_content, "chat_id": int(chat_id), "chat_title": final_title})
                    return
                if job_status == "failed":
                    yield _sse_pack("error", {"message": str((job or {}).get("error") or t(query_lang, "diamondvoy_generation_error"))})
                    return
                yield ": keepalive\n\n"
                await asyncio.sleep(0.35)
        except Exception:
            logger.exception("final diamondvoy stream failed user_id=%s chat_id=%s", user_id, chat_id)
            yield _sse_pack("error", {"message": t(query_lang, "diamondvoy_generation_error")})

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"},
    )


@app.get("/chats/diamondvoy")
async def final_diamondvoy_chats(
    limit: int = Query(default=30, ge=1, le=60),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "admin", "support"})
    rows = _diamondvoy_list_chats_final(int(user.get("id") or 0), limit=int(limit))
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 500:
        logger.info("perf final_chat.diamondvoy.list ms=%.2f rows=%s", elapsed_ms, len(rows))
    return {"items": [_diamondvoy_serialize_chat_final(row) for row in rows]}


