@app.get("/chats/diamondvoy/{chat_id}/active-generation")
async def final_diamondvoy_active_generation(
    chat_id: int,
    authorization: str | None = Header(default=None),
):
    """Lets the client check, right after opening/reopening a chat,
    whether a generation started earlier (possibly before the app was
    closed/backgrounded) is still running server-side. If so the client
    can poll this endpoint instead of assuming the answer was lost — the
    background job in `_diamondvoy_run_generation_job` keeps running and
    saving the assistant message even with no client connected at all.
    """
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "admin", "support"})
    _diamondvoy_get_chat_for_user_final(int(chat_id), int(user.get("id") or 0))
    job = _get_active_diamondvoy_gen_job_for_chat(int(chat_id))
    if not job:
        return {"active": False}
    return {
        "active": True,
        "job_id": job.get("job_id"),
        "content": job.get("content") or "",
        "status": job.get("status"),
    }


@app.post("/chats/diamondvoy/{chat_id}/messages/stream")
async def final_diamondvoy_send_stream(
    chat_id: int,
    payload: DiamondvoySendMessageRequest,
    request: Request,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"student", "teacher", "admin", "support"})
    if role == "student" and (int(user.get("access_enabled") or 1) != 1 or int(user.get("blocked") or 0) == 1):
        raise HTTPException(status_code=403, detail="Student access is blocked")
    return await _diamondvoy_stream_events(chat_id=int(chat_id), payload=payload, user=user, role=role, request=request)


@app.post("/chats/diamondvoy/{chat_id}/regenerate")
async def final_diamondvoy_regenerate(
    chat_id: int,
    request: Request,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"teacher", "admin", "support"})
    _diamondvoy_get_chat_for_user_final(int(chat_id), int(user.get("id") or 0))
    rows = _diamondvoy_list_messages_final(int(chat_id), limit=120)
    last_user = next((row for row in reversed(rows) if str(row.get("role") or "").lower() == "user"), None)
    if not last_user:
        raise HTTPException(status_code=400, detail="Regenerate uchun xabar yo‘q")
    attachments = _diamondvoy_message_attachments([int(last_user.get("id") or 0)]).get(int(last_user.get("id") or 0), [])
    payload = DiamondvoySendMessageRequest(
        message=str(last_user.get("content") or ""),
        image_urls=[str(item.get("url") or "") for item in attachments],
    )
    return await _diamondvoy_stream_events(chat_id=int(chat_id), payload=payload, user=user, role=role, request=request, regenerate=True)


class DiamondVoyWizardActionRequest(BaseModel):
    action: str
    target_group_id: int | None = None
    target_student_id: int | None = None
    target_booking_id: int | None = None
    content_types: list[str] | None = None
    deadline_iso: str | None = None
    title: str | None = None
    description: str | None = None
    manual_test: list[dict] | None = None
    instruction: str | None = None
    topic: str | None = None
    question_count: int | None = None
    raw_test_text: str | None = None

import os
import json

_WIZARD_STATE_DIR = "data/web_hw_wizard_state"
os.makedirs(_WIZARD_STATE_DIR, exist_ok=True)

def _get_homework_wizard_state(chat_id: int, user_id: int) -> dict:
    key = f"{chat_id}_{user_id}"
    path = os.path.join(_WIZARD_STATE_DIR, f"{key}.json")
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except:
            pass
    return {
        "step": "target",
        "target_type": None,
        "target_id": None,
        "booking_id": None,
        "content_types": [],
        "deadline_iso": None,
        "title": None,
        "description": None,
        "manual_test": None,
    }

def _save_homework_wizard_state(chat_id: int, user_id: int, state: dict | None):
    key = f"{chat_id}_{user_id}"
    path = os.path.join(_WIZARD_STATE_DIR, f"{key}.json")
    if state is None:
        if os.path.exists(path):
            os.remove(path)
    else:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(state, f)

@app.post("/chats/diamondvoy/{chat_id}/homework/start")
async def diamondvoy_homework_start(chat_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"teacher", "support"})
    user_id = int(user.get("id") or 0)
    key = f"{chat_id}_{user_id}"
    # Non-destructive: only seed a fresh draft if none exists yet. Every
    # client (app + site) calls this endpoint on every wizard-card mount —
    # including when the teacher just reopens the chat after leaving it —
    # so unconditionally overwriting the saved draft here wiped out
    # whatever step/target/content/details the teacher had already picked.
    # `_get_homework_wizard_state` already returns a blank-template dict
    # when nothing is saved, so this is safe for the true first-open case.
    existing_path = os.path.join(_WIZARD_STATE_DIR, f"{key}.json")
    if os.path.exists(existing_path):
        state = _get_homework_wizard_state(chat_id, user_id)
    else:
        state = {
            "step": "target",
            "target_type": None,
            "target_id": None,
            "booking_id": None,
            "content_types": [],
            "deadline_iso": None,
            "title": None,
            "description": None,
            "manual_test": None,
        }
        _save_homework_wizard_state(chat_id, user_id, state)
    
    targets = []
    if role == "teacher":
        from backend.main import _teacher_manageable_groups
        groups = _teacher_manageable_groups(user_id)
        for g in groups:
            targets.append({"type": "group", "id": g["id"], "name": g["name"], "subject": g["subject"]})
    elif role == "support":
        groups = get_active_temporary_assignments_by_owner(user_id)
        for g in groups:
            targets.append({"type": "group", "id": g["group_id"], "name": g["group_name"], "subject": g["subject"]})
        
        now_ts = _now_utc().timestamp()
        today_date = _now_utc().astimezone(TASHKENT_TZ).strftime("%Y-%m-%d")
        conn = get_conn()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT id, student_id, student_first_name, student_last_name, subject, time, date 
                FROM lesson_bookings
                WHERE support_teacher_id = ? 
                  AND date = ?
                  AND status NOT IN ('cancelled', 'rejected')
                ORDER BY end_ts DESC
            """, (user_id, today_date))
            rows = cur.fetchall()
            for row in rows:
                r = _row_to_dict(row)
                booking_end_ts = support_make_end_ts(r["date"], r["time"])
                if booking_end_ts <= now_ts:
                    targets.append({
                        "type": "student", 
                        "id": r["student_id"], 
                        "booking_id": r["id"],
                        "name": f"{r.get('student_first_name','')} {r.get('student_last_name','')}".strip(),
                        "subject": r["subject"],
                        "label": f"Support Session: {r['time']}"
                    })
                    break
        finally:
            conn.close()
            
    return {"ok": True, "state": _get_homework_wizard_state(chat_id, user_id), "targets": targets}

@app.get("/chats/diamondvoy/{chat_id}/homework/state")
async def diamondvoy_homework_state(chat_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher", "support"})
    user_id = int(user.get("id") or 0)
