@app.post("/chats/diamondvoy/{chat_id}/homework/action")
async def diamondvoy_homework_action(chat_id: int, payload: DiamondVoyWizardActionRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher", "support"})
    user_id = int(user.get("id") or 0)
    state = _get_homework_wizard_state(chat_id, user_id)
    
    if payload.action == "select_target":
        if payload.target_group_id:
            state["target_type"] = "group"
            state["target_id"] = payload.target_group_id
        elif payload.target_student_id:
            state["target_type"] = "student"
            state["target_id"] = payload.target_student_id
            state["booking_id"] = payload.target_booking_id
        state["step"] = "content_types"
    elif payload.action == "set_content_types":
        state["content_types"] = payload.content_types or []
        state["step"] = "details"
    elif payload.action == "set_details":
        state["deadline_iso"] = payload.deadline_iso
        state["title"] = payload.title
        state["description"] = payload.description
        if "test" in state["content_types"] or "ai_test" in state["content_types"]:
            state["step"] = "test"
        else:
            state["step"] = "preview"
            if "voiceroom" in state["content_types"] and state.get("target_type") == "group" and state.get("target_id"):
                import random
                users = _safe_call(lambda: get_group_users(state["target_id"]), []) or []
                students = [u for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
                random.shuffle(students)
                vgs = []
                for i in range(0, len(students), 2):
                    chunk = students[i:i+2]
                    if len(chunk) == 1 and vgs:
                        vgs[-1]["student3_id"] = int(chunk[0]["id"])
                        vgs[-1]["student3_name"] = str(chunk[0].get("first_name") or "")
                        continue
                    vg = {"student1_id": int(chunk[0]["id"]), "student1_name": str(chunk[0].get("first_name") or "")}
                    if len(chunk) > 1:
                        vg["student2_id"] = int(chunk[1]["id"])
                        vg["student2_name"] = str(chunk[1].get("first_name") or "")
                    vgs.append(vg)
                state["voiceroom_groups"] = vgs
    elif payload.action == "set_manual_test":
        state["manual_test"] = payload.manual_test
        state["step"] = "preview"
        if "voiceroom" in state["content_types"] and state.get("target_type") == "group" and state.get("target_id") and not state.get("voiceroom_groups"):
            import random
            users = _safe_call(lambda: get_group_users(state["target_id"]), []) or []
            students = [u for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
            random.shuffle(students)
            vgs = []
            for i in range(0, len(students), 2):
                chunk = students[i:i+2]
                if len(chunk) == 1 and vgs:
                    vgs[-1]["student3_id"] = int(chunk[0]["id"])
                    vgs[-1]["student3_name"] = str(chunk[0].get("first_name") or "")
                    continue
                vg = {"student1_id": int(chunk[0]["id"]), "student1_name": str(chunk[0].get("first_name") or "")}
                if len(chunk) > 1:
                    vg["student2_id"] = int(chunk[1]["id"])
                    vg["student2_name"] = str(chunk[1].get("first_name") or "")
                vgs.append(vg)
            state["voiceroom_groups"] = vgs
    elif payload.action == "accept_ai_test":
        state["manual_test"] = payload.manual_test
        state["step"] = "preview"
        if "voiceroom" in state["content_types"] and state.get("target_type") == "group" and state.get("target_id") and not state.get("voiceroom_groups"):
            import random
            users = _safe_call(lambda: get_group_users(state["target_id"]), []) or []
            students = [u for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
            random.shuffle(students)
            vgs = []
            for i in range(0, len(students), 2):
                chunk = students[i:i+2]
                if len(chunk) == 1 and vgs:
                    vgs[-1]["student3_id"] = int(chunk[0]["id"])
                    vgs[-1]["student3_name"] = str(chunk[0].get("first_name") or "")
                    continue
                vg = {"student1_id": int(chunk[0]["id"]), "student1_name": str(chunk[0].get("first_name") or "")}
                if len(chunk) > 1:
                    vg["student2_id"] = int(chunk[1]["id"])
                    vg["student2_name"] = str(chunk[1].get("first_name") or "")
                vgs.append(vg)
            state["voiceroom_groups"] = vgs
    elif payload.action == "randomise_voiceroom":
        if state.get("target_type") == "group" and state.get("target_id"):
            import random
            users = _safe_call(lambda: get_group_users(state["target_id"]), []) or []
            students = [u for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
            random.shuffle(students)
            vgs = []
            for i in range(0, len(students), 2):
                chunk = students[i:i+2]
                if len(chunk) == 1 and vgs:
                    vgs[-1]["student3_id"] = int(chunk[0]["id"])
                    vgs[-1]["student3_name"] = str(chunk[0].get("first_name") or "")
                    continue
                vg = {"student1_id": int(chunk[0]["id"]), "student1_name": str(chunk[0].get("first_name") or "")}
                if len(chunk) > 1:
                    vg["student2_id"] = int(chunk[1]["id"])
                    vg["student2_name"] = str(chunk[1].get("first_name") or "")
                vgs.append(vg)
            state["voiceroom_groups"] = vgs
    
    _save_homework_wizard_state(chat_id, user_id, state)
    return {"ok": True, "state": state}

@app.post("/chats/diamondvoy/{chat_id}/homework/generate-test")
async def diamondvoy_homework_generate_test(chat_id: int, payload: DiamondVoyWizardActionRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher", "support"})
    user_id = int(user.get("id") or 0)
    state = _get_homework_wizard_state(chat_id, user_id)
    
    prompt = f"Generate {payload.question_count or 5} multiple-choice questions for the topic: {payload.topic}.\nThe language of the questions and options MUST match the language of the topic (e.g. if the topic is in Russian, generate in Russian; if in Uzbek, generate in Uzbek). Provide the response as a JSON array of objects with 'question', 'options' (array of 4 strings), and 'correct_option_index' (0-3)."
    import aiohttp
    async with aiohttp.ClientSession() as session:
        gen = await _xai_generate_text(prompt, session=session, system_content="You are an educational content creator. Output only valid JSON without markdown wrapping.")
    try:
        import re
        raw_json = str(gen or "").strip()
        match = re.search(r"\[.*\]", raw_json, re.DOTALL)
        if match:
            raw_json = match.group(0)
        questions = json.loads(raw_json)
        norm_q = []
        for q in questions:
            norm_q.append({
                "question": q.get("question", ""),
                "options": q.get("options", ["A", "B", "C", "D"])[:4],
                "correct_option_index": max(0, min(3, int(q.get("correct_option_index", 0))))
            })
        state["manual_test"] = norm_q
        _save_homework_wizard_state(chat_id, user_id, state)
        # step qoladi, preview ga o'tmaydi toki user qabul qilmaguncha
    except Exception as e:
        raise HTTPException(status_code=400, detail="Failed to generate test: " + str(e))
    return {"ok": True, "state": state}

