@app.post("/chats/diamondvoy/{chat_id}/homework/send")
async def diamondvoy_homework_send(chat_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"teacher", "support"})
    user_id = int(user.get("id") or 0)
    key = f"{chat_id}_{user_id}"
    state = _get_homework_wizard_state(chat_id, user_id)
    
    if not state.get("target_id") or not state.get("deadline_iso") or not state.get("description"):
        raise HTTPException(status_code=400, detail="Missing required homework fields")
        
    c_types = state.get("content_types") or []
    has_test = "test" in c_types or "ai_test" in c_types
    has_list = "text" in c_types or "image" in c_types or "file" in c_types or "voice" in c_types
    
    if has_test and has_list:
        hk_kind = "both"
    elif has_test:
        hk_kind = "test"
    else:
        hk_kind = "list"
        
    req_file = "image" in c_types or "file" in c_types or "text" in c_types
    req_voice = "voice" in c_types
    is_voiceroom = "voiceroom" in c_types
    
    group_id = state["target_id"] if state["target_type"] == "group" else None
    student_id = state["target_id"] if state["target_type"] == "student" else None
    
    voiceroom_groups = []
    if is_voiceroom and group_id and group_id > 0:
        if state.get("voiceroom_groups"):
            for vg in state["voiceroom_groups"]:
                vg_clean = {"student1_id": vg["student1_id"]}
                if vg.get("student2_id"): vg_clean["student2_id"] = vg["student2_id"]
                if vg.get("student3_id"): vg_clean["student3_id"] = vg["student3_id"]
                voiceroom_groups.append(vg_clean)
        else:
            import random
            users = _safe_call(lambda: get_group_users(group_id), []) or []
            student_ids_list = [u['id'] for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
            random.shuffle(student_ids_list)
            for i in range(0, len(student_ids_list), 2):
                chunk = student_ids_list[i:i+2]
                if len(chunk) == 1 and voiceroom_groups:
                    voiceroom_groups[-1]["student3_id"] = chunk[0]
                    continue
                s1 = chunk[0]
                s2 = chunk[1] if len(chunk) > 1 else None
                vg = {"student1_id": s1}
                if s2: vg["student2_id"] = s2
                voiceroom_groups.append(vg)
    
    hw = create_homework(
        teacher_id=user_id,
        student_id=student_id,
        title=state.get("title") or "DiamondVoy Homework",
        description=state["description"],
        due_at=state["deadline_iso"],
        image_url=None,
        dcoin_effect=0.0,
        group_id=group_id,
        homework_kind=hk_kind,
        requires_voice_message=req_voice,
        requires_file=req_file,
        is_voiceroom=is_voiceroom,
        voiceroom_groups=voiceroom_groups,
    )
    if not hw:
        raise HTTPException(status_code=500, detail="Failed to create homework")
        
    hw_id = hw["id"]
    if has_test and state.get("manual_test"):
        save_content_test("homework", hw_id, json.dumps(state["manual_test"]), user_id, title="Homework Test", created_by_role=role)
        
    msg = f"Homework created successfully! [Homework #{hw_id}]"
    _diamondvoy_insert_message(chat_id, "assistant", msg)
    
    try:
        _attach_homework_runtime_fields(hw)
        await _notify_homework_created(hw, user, _homework_audience_student_ids(hw))
    except Exception as e:
        logger.exception("diamondvoy.homework.send notification failed homework_id=%s", hw_id)
        
    
    _save_homework_wizard_state(chat_id, user_id, None)
        
    return {"ok": True, "homework_id": hw_id}


# ══════════════════════════════════════════════════════════════════════════════
# DIAMONDVOY — ADMIN "ADD STUDENTS FROM XLSX" WIZARD
# ══════════════════════════════════════════════════════════════════════════════

_ADD_STUDENTS_WIZARD_DIR = "data/web_add_students_wizard"
os.makedirs(_ADD_STUDENTS_WIZARD_DIR, exist_ok=True)


def _get_add_students_wizard_state(chat_id: int, user_id: int) -> dict:
    key = f"{chat_id}_{user_id}"
    path = os.path.join(_ADD_STUDENTS_WIZARD_DIR, f"{key}.json")
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return {"step": "select_type", "account_type": None, "students": [], "created": [], "errors": []}


def _save_add_students_wizard_state(chat_id: int, user_id: int, state: dict | None) -> None:
    key = f"{chat_id}_{user_id}"
    path = os.path.join(_ADD_STUDENTS_WIZARD_DIR, f"{key}.json")
    if state is None:
        if os.path.exists(path):
            os.remove(path)
    else:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False)


def _parse_students_xlsx(file_bytes: bytes) -> tuple[list[dict], list[str]]:
    """Parse an xlsx file and extract student rows: first_name, last_name, phone, parent_phone.

    Flexible column detection:
    - Supports separate Ism / Familiya columns
    - Supports a single "Ism Familiya" (full_name) column — auto-splits on first space
    - Supports parent_phone column (optional)
    - Falls back to positional: A=name/first, B=last, C=phone
    Returns (students, errors).
    """
    from openpyxl import load_workbook
    import io

    wb = load_workbook(io.BytesIO(file_bytes), read_only=True)
    sheet = wb.active

    rows = list(sheet.iter_rows(values_only=True))
    if not rows:
        return [], ["Excel fayl bo'sh"]

    errors: list[str] = []
    students: list[dict] = []

    # ── Alias sets ────────────────────────────────────────────────────────────
    FIRST_ALIASES  = {"ism", "first", "first_name", "firstname", "имя", "ad", "ismi", "name"}
    LAST_ALIASES   = {"familiya", "last", "last_name", "lastname", "фамилия", "soyad", "surname", "familiyasi"}
    FULL_ALIASES   = {"ism_familiya", "full_name", "fullname", "ismi_familiyasi", "ism va familiya",
                      "ism familiya", "to'liq ism", "toliq_ism", "f.i.o", "fio", "фио", "полное имя"}
    PHONE_ALIASES  = {"telefon", "phone", "tel", "телефон", "raqam", "number", "mob", "mobile", "phone_number", "telefon_raqami"}
    PARENT_ALIASES = {
        "ota_ona_tel", "ota_ona_telefon", "ota_ona_telefon_raqami", "ota_onani_telefon_raqami",
        "ota_onasi_telefon", "ota_onasi_telefoni", "ota_onasining_telefon_raqami",
        "parent_phone", "parent_tel", "parent_phone_number", "parent_number",
        "ota_ona", "ota-ona tel", "ota ona telefon", "ota ona telefon raqami",
        "родитель тел", "телефон родителя", "otaona", "parent",
    }

    first_col = last_col = phone_col = full_col = parent_col = None
    data_start_row = 0

    def _alias_match(h: str, aliases: set) -> bool:
        h_clean = (
            h.replace("'", "")
            .replace("`", "")
            .replace("’", "")
            .replace(" ", "_")
            .replace("-", "_")
        )
        return h_clean in aliases or any(a.replace(" ", "_") in h_clean for a in aliases)

    def _is_parent_phone_header(h: str) -> bool:
        h_clean = (
            h.replace("'", "")
            .replace("`", "")
            .replace("’", "")
            .replace("-", " ")
            .replace("_", " ")
        )
        has_parent_word = any(token in h_clean for token in ("ota", "ona", "parent", "родител"))
        has_phone_word = any(token in h_clean for token in ("telefon", "tel", "phone", "raqam", "number"))
        return _alias_match(h, PARENT_ALIASES) or (has_parent_word and has_phone_word)

    header_row = [str(c or "").strip().lower() for c in rows[0]]
    has_header = False
    for idx, h in enumerate(header_row):
        if _alias_match(h, FULL_ALIASES):
            full_col = idx; has_header = True
        elif _alias_match(h, FIRST_ALIASES) and first_col is None:
            first_col = idx; has_header = True
        elif _alias_match(h, LAST_ALIASES) and last_col is None:
            last_col = idx; has_header = True
        elif _is_parent_phone_header(h) and parent_col is None:
            parent_col = idx; has_header = True
        elif _alias_match(h, PHONE_ALIASES) and phone_col is None:
            phone_col = idx; has_header = True

    if has_header:
        data_start_row = 1  # skip header row

    # ── Positional fallback ───────────────────────────────────────────────────
    # If only one name col found, treat as full_name
    if full_col is None and first_col is not None and last_col is None:
        full_col = first_col
        first_col = None

    # Pure positional: A=first/full, B=last, C=phone
    if full_col is None and first_col is None:
        first_col = 0
    if last_col is None and full_col is None:
        last_col = 1
    if phone_col is None:
        phone_col = 2 if last_col is not None else (1 if full_col is not None else 2)

    def _norm_phone(p: str) -> str:
        norm = "".join(c for c in p if c.isdigit() or c == "+")
        if norm and not norm.startswith("+"):
            norm = "+" + norm
        return norm

    def _extract_phones(value: Any) -> list[str]:
        import re as _re

        raw = str(value or "").strip()
        if not raw:
            return []

        found: list[str] = []
        # Strong separators usually mean separate phone numbers.
        chunks = _re.split(r"[/\\|,;،\n\r]+", raw)
        for chunk in chunks:
            digits = "".join(c for c in chunk if c.isdigit())
            if len(digits) >= 7:
                phone = _norm_phone(chunk)
                if phone and phone not in found:
                    found.append(phone)

        if found:
            return found

        # Last fallback for a single phone written with spaces/dashes/brackets.
        digits = "".join(c for c in raw if c.isdigit())
        if len(digits) >= 7:
            phone = _norm_phone(raw)
            return [phone] if phone else []
        return []

    def _looks_like_name(value: Any) -> bool:
        raw = str(value or "").strip()
        return bool(raw) and not _extract_phones(raw) and any(ch.isalpha() for ch in raw)

    # ── Row parsing ───────────────────────────────────────────────────────────
    max_col = max((c for c in [first_col, last_col, phone_col, full_col, parent_col] if c is not None), default=-1)
    for row_idx, row in enumerate(rows[data_start_row:], start=data_start_row + 1):
        row = list(row or [])
        while len(row) <= max_col:
            row.append(None)

        def _cell(col: int) -> str:
            v = row[col]
            return str(v).strip() if v is not None else ""

        # Resolve first_name / last_name
        if full_col is not None:
            full = _cell(full_col)
            parts = full.split(None, 1)  # split on first whitespace
            first_name = parts[0] if parts else ""
            last_name  = parts[1] if len(parts) > 1 else ""
        else:
            first_name = _cell(first_col) if first_col is not None else ""
            last_name  = _cell(last_col)  if last_col is not None else ""

        name_cells = [str(v).strip() for v in row if _looks_like_name(v)]
        if not has_header and name_cells:
            if len(name_cells) > 1:
                first_name = name_cells[0]
                last_name = name_cells[1]
            else:
                parts = name_cells[0].split(None, 1)
                first_name = parts[0] if parts else ""
                last_name = parts[1] if len(parts) > 1 else ""
        elif not first_name or not last_name:
            if not first_name and name_cells:
                first_name = name_cells[0]
            if not last_name:
                if len(name_cells) > 1:
                    last_name = name_cells[1]
                elif first_name:
                    parts = first_name.split(None, 1)
                    first_name = parts[0] if parts else first_name
                    last_name = parts[1] if len(parts) > 1 else last_name

        phone       = _cell(phone_col) if phone_col is not None else ""
        parent_phone_val = _cell(parent_col) if parent_col is not None else ""

        # Skip fully empty rows
        if not first_name and not last_name and not phone:
            continue

        row_phones: list[str] = []
        for value in row:
            for extracted in _extract_phones(value):
                if extracted not in row_phones:
                    row_phones.append(extracted)

        if has_header:
            phone_parts = _extract_phones(phone)
            parent_parts = _extract_phones(parent_phone_val)
            phone_norm = phone_parts[0] if phone_parts else (row_phones[0] if row_phones else "")
            parent_norm = parent_parts[0] if parent_parts else ""
            if not parent_norm and len(phone_parts) >= 2:
                parent_norm = phone_parts[1]
            if not parent_norm and len(row_phones) >= 2:
                parent_norm = row_phones[1]
        else:
            phone_norm = row_phones[0] if row_phones else ""
            parent_norm = row_phones[1] if len(row_phones) >= 2 else ""

        row_errors = []
        if not first_name:
            row_errors.append(f"Qator {row_idx}: ism yo'q")
        if not phone_norm or len(phone_norm) < 7:
            row_errors.append(f"Qator {row_idx}: telefon raqam noto'g'ri ({phone!r})")

        if row_errors:
            errors.extend(row_errors)
            continue

        entry: dict = {
            "first_name":   first_name,
            "last_name":    last_name,
            "phone":        phone_norm,
        }
        if parent_norm:
            entry["parent_phone"] = parent_norm

        students.append(entry)

    return students, errors



@app.post("/chats/diamondvoy/{chat_id}/add-students/start")
async def diamondvoy_add_students_start(
    chat_id: int,
    authorization: str | None = Header(default=None),
):
    """Admin starts the 'add students from xlsx' wizard."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    user_id = int(user.get("id") or 0)
    state = {"step": "select_type", "account_type": None, "students": [], "created": [], "errors": []}
    _save_add_students_wizard_state(chat_id, user_id, state)
    return {
        "ok": True,
        "state": state,
        "options": [
            {"value": "student",     "label": "Mavjud student (hisob bilan)"},
            {"value": "accountless", "label": "Hisob raqamsiz student"},
        ],
    }


@app.post("/chats/diamondvoy/{chat_id}/add-students/select-type")
async def diamondvoy_add_students_select_type(
    chat_id: int,
    payload: dict,
    authorization: str | None = Header(default=None),
):
    """Admin selects account type and common fields for all students in the batch."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    user_id = int(user.get("id") or 0)
    account_type = str(payload.get("account_type") or "").strip().lower()
    if account_type not in ("student", "accountless"):
        raise HTTPException(status_code=400, detail="account_type must be 'student' or 'accountless'")

    # Common fields applied to every row in the batch
    parent_phone  = str(payload.get("parent_phone") or "").strip() or None
    free_access   = bool(payload.get("free_access") or False)
    subject       = _normalize_subject_label(str(payload.get("subject") or "").strip()) or "English"
    group_id      = int(payload.get("group_id") or 0)
    joined_at     = str(payload.get("joined_at") or "").strip() or None

    if account_type == "accountless":
        # Validate the group if provided
        if group_id:
            group = _safe_call(lambda: get_group(group_id), None)
            if not group:
                raise HTTPException(status_code=404, detail=f"Guruh topilmadi: {group_id}")
            # Auto-detect subject from group if not explicitly provided
            if not payload.get("subject"):
                subject = _normalize_subject_label(str(group.get("subject") or "")) or "English"

    state = _get_add_students_wizard_state(chat_id, user_id)
    state["account_type"] = account_type
    state["parent_phone"] = parent_phone
    state["free_access"]  = free_access
    state["subject"]      = subject
    state["group_id"]     = group_id
    state["joined_at"]    = joined_at
    state["step"]         = "upload"
    state["students"]     = []
    state["created"]      = []
    state["errors"]       = []
    _save_add_students_wizard_state(chat_id, user_id, state)
    return {"ok": True, "state": state}


@app.post("/chats/diamondvoy/{chat_id}/add-students/upload-xlsx")
async def diamondvoy_add_students_upload_xlsx(
    chat_id: int,
    file: UploadFile = File(...),
    authorization: str | None = Header(default=None),
):
    """Admin uploads an xlsx file. Backend parses it and returns a preview."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    user_id = int(user.get("id") or 0)

    state = _get_add_students_wizard_state(chat_id, user_id)
    if state.get("step") not in ("upload", "preview"):
        raise HTTPException(status_code=400, detail="Avval account turini tanlang")

    fname = str(file.filename or "").lower()
    if not (fname.endswith(".xlsx") or fname.endswith(".docx")):
        raise HTTPException(status_code=400, detail="Faqat .xlsx yoki .docx format qabul qilinadi")

    file_bytes = await file.read()
    if len(file_bytes) > 5 * 1024 * 1024:  # 5 MB limit
        raise HTTPException(status_code=400, detail="Fayl hajmi 5 MB dan oshmasligi kerak")

    if fname.endswith(".docx"):
        from diamondvoy_helpers import diamondvoy_analyze_student_file
        # AI analysis
        students = await diamondvoy_analyze_student_file(file_bytes, fname)
        parse_errors = []
        if not students:
            parse_errors.append("Word fayldan o'quvchi topilmadi.")
    else:
        students, parse_errors = _parse_students_xlsx(file_bytes)

    state["students"] = students
    state["errors"] = parse_errors
    state["step"] = "preview"
    state["created"] = []
    _save_add_students_wizard_state(chat_id, user_id, state)

    return {
        "ok": True,
        "state": state,
        "total": len(students),
        "parse_errors": parse_errors,
        "students": students,  # preview list
    }


@app.post("/chats/diamondvoy/{chat_id}/add-students/confirm")
async def diamondvoy_add_students_confirm(
    chat_id: int,
    authorization: str | None = Header(default=None),
):
    """Admin confirms — bulk-creates accounts using the same logic as the admin users page."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    user_id = int(user.get("id") or 0)
    admin_ref = _admin_ref_id(user)

    state = _get_add_students_wizard_state(chat_id, user_id)
    if state.get("step") != "preview":
        raise HTTPException(status_code=400, detail="Avval xlsx fayl yuklang")
    if not state.get("students"):
        raise HTTPException(status_code=400, detail="Yaroqli student ma'lumotlari topilmadi")

    account_type: str  = str(state.get("account_type") or "student")
    parent_phone: str | None = state.get("parent_phone") or None
    free_access: bool  = bool(state.get("free_access") or False)
    subject: str       = str(state.get("subject") or "English")
    group_id: int      = int(state.get("group_id") or 0)
    joined_at: str | None = state.get("joined_at") or None
    students: list[dict] = list(state.get("students") or [])

    created: list[dict] = []
    failed:  list[dict] = []

    from auth import create_user_sync

    for st in students:
        first = str(st.get("first_name") or "").strip()
        last  = str(st.get("last_name")  or "").strip()
        phone = str(st.get("phone")      or "").strip()
        row_parent_phone = str(st.get("parent_phone") or parent_phone or "").strip() or None
        if not first or not last or not phone:
            failed.append({**st, "error": "To'liq ma'lumot yo'q"})
            continue
        try:
            if account_type == "accountless":
                # ── Same logic as admin_create_accountless_student ──────────
                _ensure_user_web_columns()
                conn = get_conn()
                cur = conn.cursor()
                cur.execute(
                    """
                    INSERT INTO users
                    (login_id, password, password_used,
                     first_name, last_name, phone, parent_phone,
                     subject, login_type, blocked, access_enabled,
                     owner_admin_id, placement_required, placement_subject,
                     free_access)
                    VALUES (NULL, NULL, 1, ?, ?, ?, ?, ?, 6, 1, 0, ?, 0, ?, ?)
                    RETURNING id
                    """,
                    (
                        first, last, phone, row_parent_phone,
                        subject, int(admin_ref), subject,
                        1 if free_access else 0,
                    ),
                )
                row = cur.fetchone() or {}
                new_id = int(row.get("id") or 0)
                conn.commit()
                conn.close()
                if new_id <= 0:
                    failed.append({**st, "error": "Bazaga yozishda xatolik"})
                    continue
                # Ensure login_type stays 6, blocked=1
                conn = get_conn()
                cur = conn.cursor()
                cur.execute(
                    "UPDATE users SET login_id=NULL, password=NULL, password_used=1, blocked=1, access_enabled=0, login_type=6 WHERE id=?",
                    (int(new_id),),
                )
                conn.commit()
                conn.close()
                # Assign to group
                if group_id > 0:
                    add_user_to_group(int(new_id), int(group_id), joined_at=joined_at)
                created.append({
                    "id": new_id,
                    "first_name": first,
                    "last_name": last,
                    "phone": phone,
                    "account_type": "accountless",
                    "login_id": None,
                    "password": None,
                })
            else:
                # ── Same logic as admin_create_user (existing_student) ──────
                created_row = create_user_sync(
                    first, last, phone, subject,
                    2,  # login_type 2 = existing_student
                    owner_admin_id=int(admin_ref),
                    parent_phone=row_parent_phone,
                )
                new_id = int(created_row.get("id") or 0)
                if new_id <= 0:
                    failed.append({**st, "error": "Hisob yaratishda xatolik"})
                    continue
                _ensure_user_web_columns()
                conn = get_conn()
                cur = conn.cursor()
                cur.execute(
                    """
                    UPDATE users
                    SET placement_required=0, placement_subject=?,
                        level='B1', access_enabled=1, blocked=0,
                        free_access=?,
                        face_enrollment_required=1,
                        face_profile_status='pending',
                        face_id_status='not_started',
                        face_id_enrolled=0,
                        proctoring_required=1,
                        review_wait_required=0
                    WHERE id=?
                    """,
                    (subject, 1 if free_access else 0, int(new_id)),
                )
                conn.commit()
                conn.close()
                _generate_qr_login_token(new_id, WEB_QR_LOGIN_TTL_SECONDS)
                created.append({
                    "id": new_id,
                    "first_name": first,
                    "last_name": last,
                    "phone": phone,
                    "account_type": "student",
                    "login_id": str(created_row.get("login_id") or ""),
                    "password": str(created_row.get("password") or ""),
                })
        except Exception as exc:
            logger.warning(
                "diamondvoy.add_students.confirm: failed to create %s %s (%s): %s",
                first, last, phone, exc,
            )
            failed.append({**st, "error": str(exc)[:120]})

    # Finalize state
    state["step"] = "done"
    state["created"] = created
    state["errors"] = [f"{f['first_name']} {f['last_name']}: {f['error']}" for f in failed]
    _save_add_students_wizard_state(chat_id, user_id, state)

    # Insert summary message into chat
    msg = (
        f"✅ {len(created)} ta yangi foydalanuvchi muvaffaqiyatli yaratildi."
        + (f" ❌ {len(failed)} ta xatolik bor." if failed else "")
    )
    _diamondvoy_insert_message(chat_id, "assistant", msg)

    return {
        "ok": True,
        "created": created,
        "failed": failed,
        "total_created": len(created),
        "total_failed": len(failed),
        "state": state,
    }


