@app.post("/feedback/thread/messages")
async def feedback_send_user_message(
    payload: ChatFeedbackCreateRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"student", "teacher", "admin", "support"})
    text = str(payload.message or "").strip()
    image_urls = _validate_chat_image_urls(payload.image_urls)
    if not text and not image_urls:
        raise HTTPException(status_code=400, detail="Xabar yoki rasm yuboring")
    thread = _feedback_get_or_create_thread(int(user.get("id") or 0))
    message = _feedback_insert_message(
        int(thread.get("id") or 0),
        int(user.get("id") or 0),
        role,
        text,
        bool(payload.is_anonymous),
    )
    _feedback_insert_attachments(int(message.get("id") or 0), image_urls)

    users_map = _chat_users_map()
    users_map[int(user.get("id") or 0)] = user
    admin_ids = sorted(_chat_role_ids(users_map, "admin"))
    if admin_ids:
        _safe_call(
            lambda: _feedback_push_admin_web_notification(
                sender_user=user,
                sender_role=role,
                is_anonymous=bool(payload.is_anonymous),
                message_text=text or "[rasm]",
                admin_ids=admin_ids,
            ),
            None,
        )
        await _feedback_push_admin_telegram_notification(
            sender_user=user,
            sender_role=role,
            is_anonymous=bool(payload.is_anonymous),
            message_text=text or "[rasm]",
        )
    return _feedback_thread_detail(int(thread.get("id") or 0))


