@app.post("/feedback/threads/{thread_id}/status")
async def feedback_admin_status(
    thread_id: int,
    payload: FeedbackStatusRequest,
    authorization: str | None = Header(default=None),
):
    admin = _user_row_from_bearer(authorization)
    _require_role(admin, {"admin"})
    detail = _feedback_thread_for_admin_or_error(int(thread_id))
    status = _normalize_feedback_status(payload.status)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("UPDATE feedback_threads SET status=?, updated_at=CURRENT_TIMESTAMP WHERE id=?", (status, int(thread_id)))
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    await _feedback_notify_user(
        int(detail["thread"]["user_id"]),
        "Taklif & Shikoyat holati",
        f"Taklif & Shikoyat holati: {status}",
        f"feedback_status:{int(thread_id)}:{status}:{int(time.time())}",
    )
    return _feedback_thread_detail(int(thread_id))


async def _feedback_admin_dpoint_action(thread_id: int, payload: FeedbackDpointActionRequest, admin: dict, *, sign: int) -> dict[str, Any]:
    detail = _feedback_thread_for_admin_or_error(int(thread_id))
    target_user_id = int(detail["thread"]["user_id"])
    target_user = _safe_call(lambda: get_user_by_id(target_user_id), None) or {}
    target_role = _role_from_login_type(int(target_user.get("login_type") or 1), str(target_user.get("login_id") or ""))
    if target_role != "student":
        raise HTTPException(status_code=400, detail="D'point faqat student uchun o'zgaradi")
    reason = str(payload.reason or "").strip()
    if not reason:
        raise HTTPException(status_code=400, detail="Sabab majburiy")
    amount = abs(float(payload.amount or 0.0)) * (1 if sign > 0 else -1)
    before = float(get_dpoints(target_user_id))
    add_dpoints(target_user_id, amount, change_type=f"feedback_{'reward' if amount > 0 else 'penalty'}:{reason[:80]}")
    after = float(get_dpoints(target_user_id))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO feedback_actions(thread_id, admin_id, action_type, amount, reason, balance_before, balance_after, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            (int(thread_id), int(admin.get("id") or 0), "reward" if amount > 0 else "penalty", float(amount), reason, before, after),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        conn.close()
    kind = "Mukofot" if amount > 0 else "Jarima"
    await _feedback_notify_user(
        target_user_id,
        f"Taklif & Shikoyat: {kind}",
        f"{kind}: {abs(amount):.1f} D'point. Manba: Taklif & Shikoyat. Yangi balans: {after:.1f}",
        f"feedback_dpoint:{int(thread_id)}:{'plus' if amount > 0 else 'minus'}:{int(abs(amount) * 10)}:{int(time.time())}",
    )
    return {"thread": _feedback_thread_detail(int(thread_id))["thread"], "amount": amount, "before": before, "after": after}


