@app.post("/admin/feedback/{feedback_id}/dcoin-adjust")
@app.post("/admin/feedback/{feedback_id}/dpoint-adjust")
async def admin_feedback_dpoint_adjust(
    feedback_id: int,
    payload: AdminFeedbackDcoinAdjustRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    amount = float(payload.amount or 0.0)
    if abs(amount) < 1e-9:
        raise HTTPException(status_code=400, detail="Amount must not be zero")

    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM web_feedback_messages WHERE id=? LIMIT 1", (int(feedback_id),))
    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Feedback not found")
    feedback = dict(row)
    target_user_id = int(feedback.get("user_id") or 0)
    target_user = _safe_call(lambda: get_user_by_id(int(target_user_id)), None) or {}
    target_role = _role_from_login_type(int(target_user.get("login_type") or 1), str(target_user.get("login_id") or ""))
    if target_user_id <= 0 or target_role != "student":
        conn.close()
        raise HTTPException(status_code=400, detail="D'point actions are only available for student feedback")

    before_points = float(get_dpoints(target_user_id))
    before_balance = float(get_dcoins(target_user_id))
    reason_raw = str(payload.reason or "").strip()
    if amount > 0:
        change_type = "admin_feedback_reward"
    else:
        change_type = "admin_feedback_penalty"
    if reason_raw:
        change_type = f"{change_type}:{reason_raw[:80]}"
    add_dpoints(target_user_id, amount, change_type=change_type)
    after_points = float(get_dpoints(target_user_id))
    after_balance = float(get_dcoins(target_user_id))

    cur.execute(
        """
        UPDATE web_feedback_messages
        SET dcoin_adjusted_total = COALESCE(dcoin_adjusted_total, 0) + ?
        WHERE id = ?
        """,
        (float(amount), int(feedback_id)),
    )
    conn.commit()
    cur.execute("SELECT * FROM web_feedback_messages WHERE id=? LIMIT 1", (int(feedback_id),))
    updated_row = dict(cur.fetchone() or feedback)
    conn.close()

    kind = "Mukofot" if amount > 0 else "Jarima"
    _safe_call(
        lambda: _feedback_store_student_notification(
            user_id=int(target_user_id),
            title=f"Taklif & Shikoyat: {kind}",
            message=(
                f"{kind}: {abs(float(amount)):.1f} D'point. "
                f"Yangi balans: {after_points:.1f} D'point."
            ),
            source_key=f"feedback_adjust:{int(feedback_id)}:{'plus' if amount > 0 else 'minus'}:{int(abs(amount) * 10)}",
        ),
        None,
    )
    try:
        tg = str(target_user.get("telegram_id") or "").strip()
        if tg:
            await _send_telegram_text(
                _tg_token_for_login_type(int(target_user.get("login_type") or 0)),
                tg,
                "\n".join(
                    [
                        "Taklif & Shikoyat bo'yicha yangilanish",
                        f"{kind}: {abs(float(amount)):.1f} D'point",
                        f"Yangi D'point: {after_points:.1f}",
                    ]
                ),
                button_text="Webda ochish",
                button_url=f"{WEBAPP_URL}/dashboard?section=chats",
            )
    except Exception:
        logger.exception("feedback reward/penalty telegram notify failed user_id=%s", target_user_id)

    return {
        "message": "D'point updated",
        "feedback": _serialize_feedback_row(updated_row, include_admin_private=True),
        "amount": float(amount),
        "before_dpoints": before_points,
        "after_dpoints": after_points,
        "before_balance": before_balance,
        "after_balance": after_balance,
    }


