@lru_cache(maxsize=64)
def _student_grammar_level_items_cached(subject: str, catalog_version: str) -> tuple[tuple[str, int], ...]:
    if _normalize_subject_label(subject) == "Russian":
        # Russian grammar is deliberately a single ordered list.
        return tuple()
    rows: list[tuple[str, int]] = []
    for code in _GRAMMAR_LEVELS:
        topics = get_topics_by_level(code, subject=subject) or []
        if topics:
            rows.append((code, len(topics)))
    if not rows:
        rows.append(("A1", 0))
    return tuple(rows)


@lru_cache(maxsize=256)
def _student_grammar_topic_items_cached(subject: str, level: str, catalog_version: str) -> tuple[dict[str, Any], ...]:
    selected_level = str(level or "").strip().upper()
    if selected_level == "ALL":
        topics = grammar_get_topics_for_subject(subject)
    else:
        topics = get_topics_by_level(selected_level, subject=subject) or []
    return tuple(
        {
            "topic_id": str(getattr(topic, "topic_id", "") or ""),
            "level": str(getattr(topic, "level", "") or ""),
            "title": str(getattr(topic, "title", "") or ""),
            "question_count": len(list(getattr(topic, "questions", []) or [])),
        }
        for topic in topics
    )


