@app.get("/student/grammar/topics")
async def student_grammar_topics(
    subject: str | None = Query(default=None),
    level: str = Query(default="A1"),
    page: int = Query(default=1, ge=1),
    per_page: int = Query(default=100, ge=1, le=200),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    subjects = _user_subjects_from_row(user)
    selected_subject = _normalize_subject_label(subject) or (subjects[0] if subjects else "English")
    if selected_subject not in subjects:
        selected_subject = subjects[0] if subjects else "English"
    
    # Map legacy levels to CEFR levels
    level_mapping = {
        "BEGINNER": "A1",
        "ELEMENTARY": "A2",
        "PRE-INTERMEDIATE": "B1",
        "INTERMEDIATE": "B2",
        "UPPER-INTERMEDIATE": "C1",
        "ADVANCED": "C1",
    }
    raw_level = str(level or "A1").strip().upper()
    selected_level = level_mapping.get(raw_level, raw_level)
    
    if selected_subject == "Russian":
        # Rus tili grammatikasi: daraja tanlovi YO'Q — barcha mavzular bitta
        # ro'yxatda, katalog tartibida (A1->C1). Sayt va ilova bir xil
        # tartibni ko'radi (level parametri ignore qilinadi).
        selected_level = "ALL"
    elif selected_level not in {"A1", "A2", "B1", "B2", "C1", "ALL"}:
        selected_level = "A1"

    meta = grammar_catalog_meta()
    version = str(meta.get("grammar_catalog_version") or "")
    topics = list(_student_grammar_topic_items_cached(selected_subject, selected_level, version))
    total = len(topics)
    pages = max(1, (total + per_page - 1) // per_page)
    p = min(max(1, int(page)), pages)
    start = (p - 1) * per_page
    chunk = topics[start : start + per_page]
    items = chunk
    payload = {
        "subject": selected_subject,
        "level": selected_level,
        "page": p,
        "pages": pages,
        "total": total,
        "items": items,
    }
    payload.update(meta)
    return payload


def _resolve_grammar_topic_with_fallback(subject: str, preferred_level: str, topic_id: str) -> tuple[Any | None, str]:
    return grammar_resolve_topic_with_fallback(subject, preferred_level, topic_id)


def _resolve_student_grammar_topic(user: dict, subject: str | None, level: str | None, topic_id: str) -> tuple[Any | None, str, str]:
    subjects = _user_subjects_from_row(user)
    requested_subject = _normalize_subject_label(subject) or (subjects[0] if subjects else "English")
    if subjects and requested_subject not in subjects:
        requested_subject = subjects[0]
    
    # Map legacy level to CEFR level
    level_mapping = {
        "BEGINNER": "A1",
        "ELEMENTARY": "A2",
        "PRE-INTERMEDIATE": "B1",
        "INTERMEDIATE": "B2",
        "UPPER-INTERMEDIATE": "C1",
        "ADVANCED": "C1",
    }
    raw_level = str(level or "A1").strip().upper()
    requested_level = level_mapping.get(raw_level, raw_level)
    
    if requested_level not in {"A1", "A2", "B1", "B2", "C1"}:
        requested_level = "A1"

    subject_candidates: list[str] = []
    for item in [requested_subject, *subjects, "English", "Russian"]:
        normalized = _normalize_subject_label(item)
        if normalized and normalized not in subject_candidates and (not subjects or normalized in subjects):
            subject_candidates.append(normalized)
    
    level_candidates = [requested_level, "A1", "A2", "B1", "B2", "C1"]
    seen_levels: list[str] = []
    for item in level_candidates:
        if item not in seen_levels:
            seen_levels.append(item)

    for subj in subject_candidates or [requested_subject]:
        for lvl in seen_levels:
            topic, resolved_level = _resolve_grammar_topic_with_fallback(subj, lvl, topic_id)
            if topic:
                return topic, subj, resolved_level
    return None, requested_subject, requested_level


def _normalize_grammar_question_payload(question: Any) -> dict[str, Any] | None:
    return grammar_normalize_question_payload(question)


def _serialize_grammar_topic_payload(topic: Any, *, preview_limit: int = 5) -> dict[str, Any]:
    return grammar_serialize_topic_payload(topic, preview_limit=preview_limit)


@app.get("/student/grammar/topic")
async def student_grammar_topic(
    subject: str | None = Query(default=None),
    level: str = Query(default="A1"),
    topic_id: str = Query(default=""),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    topic_key = str(topic_id or "").strip()
    if not topic_key:
        raise HTTPException(status_code=400, detail="topic_id is required")

    topic, selected_subject, resolved_level = _resolve_student_grammar_topic(user, subject, level, topic_key)
    if not topic:
        raise HTTPException(status_code=404, detail="Grammar topic not found")
    try:
        topic_payload = _serialize_grammar_topic_payload(topic, preview_limit=5)
        attempts_used = get_grammar_attempts(int(user.get("id") or 0), str(topic_payload["topic_id"] or ""))
    except HTTPException:
        raise
    except Exception:
        logger.exception(
            "student_grammar_topic serialization/attempts failed user_id=%s subject=%s level=%s topic_id=%s",
            int(user.get("id") or 0),
            selected_subject,
            resolved_level,
            topic_key,
        )
        raise HTTPException(
            status_code=503,
            detail="Grammar topic is temporarily unavailable",
        )
    attempts_left = max(0, GRAMMAR_TOPIC_ATTEMPT_LIMIT - int(attempts_used))
    question_count = int(topic_payload.get("question_count") or len(topic_payload.get("questions") or []))
    can_start = attempts_left > 0 and question_count > 0

    payload = {
        "subject": selected_subject,
        "level": resolved_level,
        "topic_id": topic_payload["topic_id"],
        "title": topic_payload["title"],
        "rule": topic_payload["rule"],
        "question_count": question_count,
        "attempts_allowed": GRAMMAR_TOPIC_ATTEMPT_LIMIT,
        "attempts_used": int(attempts_used),
        "attempts_left": attempts_left,
        "can_start_test": can_start,
    }
    payload.update(grammar_catalog_meta())
    return payload


@app.post("/student/grammar/quiz/start")
async def student_grammar_quiz_start(
    payload: GrammarQuizStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)
    user_id = int(user.get("id") or 0)
    topic_id = str(payload.topic_id or "").strip()
    if not topic_id:
        raise HTTPException(status_code=400, detail="topic_id is required")
    topic, selected_subject, resolved_level = _resolve_student_grammar_topic(user, payload.subject, payload.level, topic_id)
    if not topic:
        raise HTTPException(status_code=404, detail="Grammar topic not found")
    try:
        topic_payload = _serialize_grammar_topic_payload(topic, preview_limit=0)
    except Exception:
        logger.exception(
            "student_grammar_quiz_start topic serialization failed user_id=%s subject=%s level=%s topic_id=%s",
            user_id,
            selected_subject,
            resolved_level,
            topic_id,
        )
        raise HTTPException(
            status_code=503,
            detail="Grammar quiz is temporarily unavailable",
        )
    attempts = get_grammar_attempts(user_id, topic_payload["topic_id"])
    if attempts >= GRAMMAR_TOPIC_ATTEMPT_LIMIT:
        raise HTTPException(status_code=409, detail="Grammar topic attempt limit reached")
    questions = list(topic_payload["questions"])
    if not questions:
        raise HTTPException(status_code=400, detail="No grammar questions found for this topic")
    increment_grammar_attempt(user_id, topic_payload["topic_id"])
    session_id = f"gq_{uuid4().hex}"
    GRAMMAR_QUIZ_SESSIONS[session_id] = {
        "user_id": user_id,
        "subject": selected_subject,
        "level": resolved_level,
        "topic_id": topic_payload["topic_id"],
        "topic_title": topic_payload["title"],
        "questions": questions,
        "index": 0,
        "correct": 0,
        "wrong": 0,
        "skipped": 0,
        "started_at": _now_utc().isoformat(),
    }
    _persist_student_quiz_session(session_id, user_id, "grammar", GRAMMAR_QUIZ_SESSIONS[session_id], status="active")
    q0 = questions[0]
    response = _attach_proctoring_payload(user, {
        "session_id": session_id,
        "subject": selected_subject,
        "level": resolved_level,
        "topic_id": topic_payload["topic_id"],
        "topic_title": topic_payload["title"],
        "attempts_allowed": GRAMMAR_TOPIC_ATTEMPT_LIMIT,
        "attempts_used": attempts + 1,
        "attempts_left": max(0, GRAMMAR_TOPIC_ATTEMPT_LIMIT - (attempts + 1)),
        "question_index": 1,
        "total_questions": len(questions),
        "question": {
            "prompt": q0["prompt"],
            "options": q0["options"],
            # Nested question_index lets the client key its per-question
            # timer reset on the actual question — without it every
            # question shares the same key and the timer never restarts.
            "question_index": 1,
        },
    }, test_type="grammar", test_attempt_ref=str(topic_payload["topic_id"]), test_route="/student/grammar")
    response.update(grammar_catalog_meta())
    return response


@app.post("/student/grammar/quiz/answer")
async def student_grammar_quiz_answer(
    payload: GrammarQuizAnswerRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    session_id = str(payload.session_id or "").strip()
    user_id = int(user.get("id") or 0)
    conn = cur = None
    row = state = result = None
    try:
        pre_row, pre_state, pre_result = _load_student_quiz_session_snapshot(session_id, user_id, "grammar")
        if pre_row and str((pre_row or {}).get("status") or "").lower() == "completed":
            if pre_result:
                return pre_result
            raise HTTPException(status_code=400, detail="Grammar quiz already completed")
        pre_session = pre_state if isinstance(pre_state, dict) and pre_state else GRAMMAR_QUIZ_SESSIONS.get(session_id)
        if not pre_session:
            raise HTTPException(status_code=404, detail="Grammar quiz session not found")
        if int(pre_session.get("user_id") or 0) != user_id:
            raise HTTPException(status_code=403, detail="Session does not belong to current user")
        _ensure_proctoring_session_access(
            user,
            payload.proctoring_session_id,
            expected_test_type="grammar",
            expected_attempt_ref=str(pre_session.get("topic_id") or ""),
        )
        conn, cur, row, state, result = _load_student_quiz_session_locked(session_id, user_id, "grammar")
        if row and str((row or {}).get("status") or "").lower() == "completed":
            if result:
                return result
            raise HTTPException(status_code=400, detail="Grammar quiz already completed")
        session = state if isinstance(state, dict) and state else GRAMMAR_QUIZ_SESSIONS.get(session_id)
        if not session:
            raise HTTPException(status_code=404, detail="Grammar quiz session not found")
        if int(session.get("user_id") or 0) != user_id:
            raise HTTPException(status_code=403, detail="Session does not belong to current user")
        questions = session.get("questions") or []
        idx = int(session.get("index") or 0)
        if idx >= len(questions):
            completed_result = result or {}
            if completed_result:
                return completed_result
            raise HTTPException(status_code=400, detail="Grammar quiz already completed")
        session["user_answers"] = session.get("user_answers") or []
        q = questions[idx]
        selected = payload.selected_option_index
        selected_idx = int(selected) if selected is not None else None
        correct_idx = int(q.get("correct_index") or 0)
        if selected is None:
            session["skipped"] = int(session.get("skipped") or 0) + 1
        else:
            if selected_idx < 0 or selected_idx >= len(q.get("options") or []):
                raise HTTPException(status_code=400, detail="Invalid option index")
            if selected_idx == correct_idx:
                session["correct"] = int(session.get("correct") or 0) + 1
            else:
                session["wrong"] = int(session.get("wrong") or 0) + 1
        session["user_answers"].append({
            "question_index": idx + 1,
            "prompt": q.get("prompt") or "",
            "options": q.get("options") or [],
            "selected_index": selected_idx,
            "correct_index": correct_idx,
            "is_correct": selected_idx is not None and selected_idx == correct_idx,
            "is_skipped": selected_idx is None,
        })
        session["index"] = idx + 1

        if session["index"] < len(questions):
            qn = questions[session["index"]]
            next_index = int(session["index"]) + 1
            response = {
                "completed": False,
                "session_id": session_id,
                "question_index": next_index,
                "total_questions": len(questions),
                "question": {
                    "prompt": qn["prompt"],
                    "options": qn["options"],
                    "question_index": next_index,
                },
            }
            response.update(grammar_catalog_meta())
            if cur is not None:
                _update_student_quiz_session_tx(cur, session_id, session, status="active")
                conn.commit()
            else:
                GRAMMAR_QUIZ_SESSIONS[session_id] = session
            return response

        correct = int(session.get("correct") or 0)
        wrong = int(session.get("wrong") or 0)
        skipped = int(session.get("skipped") or 0)
        total = max(1, len(questions))
        percent = round((correct * 100.0) / total, 1)
        dcoin_breakdown = award_quiz_dpoints(
            user_id=user_id,
            subject=str(session.get("subject") or "English"),
            correct_count=correct,
            wrong_count=wrong,
            skipped_count=skipped,
            mode="grammar",
            change_type="grammar_web_quiz",
        )
        final_dcoin = float(dcoin_breakdown.get("final_dcoins") or 0)
        add_test_history(
            user_id,
            "grammar",
            str(session.get("topic_id") or ""),
            correct,
            wrong,
            skipped,
        )
        try:
            attempts_used = get_grammar_attempts(user_id, str(session.get("topic_id") or ""))
        except Exception:
            logger.exception(
                "student_grammar_quiz_answer failed to load attempts user_id=%s topic_id=%s",
                user_id,
                str(session.get("topic_id") or ""),
            )
            attempts_used = 0
        response = {
            "completed": True,
            "topic_id": session.get("topic_id"),
            "topic_title": session.get("topic_title"),
            "subject": session.get("subject"),
            "correct": correct,
            "wrong": wrong,
            "skipped": skipped,
            "total_questions": total,
            "percentage": percent,
            "dpoints": float(dcoin_breakdown.get("total_points") or 0),
            "dcoin": final_dcoin,
            "dcoin_breakdown": dcoin_breakdown,
            "dpoint_breakdown": dcoin_breakdown,
            "attempts_allowed": GRAMMAR_TOPIC_ATTEMPT_LIMIT,
            "attempts_used": attempts_used,
            "attempts_left": max(0, GRAMMAR_TOPIC_ATTEMPT_LIMIT - int(attempts_used)),
            "details": session.get("user_answers") or [],
        }
        response.update(grammar_catalog_meta())
        if cur is not None:
            _update_student_quiz_session_tx(cur, session_id, session, status="completed", result=response)
            conn.commit()
        GRAMMAR_QUIZ_SESSIONS.pop(session_id, None)
        return response
    except HTTPException:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        raise
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logger.exception("student_grammar_quiz_answer failed session_id=%s user_id=%s", session_id, user_id)
        raise
    finally:
        if conn is not None:
            conn.close()


def _daily_session_payload(user: dict, attempt: dict, items: list[dict]) -> dict:
    total = len(items)
    current = None
    for row in items:
        if row.get("selected_option") is None and not bool(int(row.get("timed_out") or 0)):
            current = row
            break
    correct, wrong, unanswered = _attempt_counts_from_items(items)
    completed = current is None
    attempt_id = int(attempt.get("id") or 0)
    question_index = int(current.get("question_index") or 0) if current else total
    time_left = _daily_question_time_remaining(attempt_id, question_index) if current else 0

    payload: dict[str, Any] = {
        "attempt_id": attempt_id,
        "status": str(attempt.get("status") or "in_progress"),
        "subject": str(attempt.get("subject") or ""),
        "level": str(attempt.get("level") or ""),
        "test_date": str(attempt.get("test_date") or ""),
        "question_index": question_index,
        "total_questions": total,
        "progress_percent": int(round(((question_index - 1) * 100 / max(1, total)))) if not completed else 100,
        "time_limit_sec": DAILY_TEST_WEB_SECONDS,
        "time_remaining_sec": time_left,
        "completed": completed,
        "stats": {
            "correct": int(correct),
            "wrong": int(wrong),
            "unanswered": int(unanswered),
        },
    }
    if current:
        current_payload = dict(current)
        current_payload["subject"] = str(attempt.get("subject") or current_payload.get("subject") or "")
        payload["question"] = _public_question_payload(
            current_payload,
            question_index=int(current.get("question_index") or 0),
        )
    # When test is fully completed, attach per-question details for the review popup.
    if completed:
        details = []
        for row in items:
            try:
                q = _mcq_question_from_row(row)
                opts = [str(o) for o in (q.get("options") or [])]
                correct_1idx = int(q.get("correct_option_index") or 1)
                correct_0idx = max(0, correct_1idx - 1)
                # selected_option is stored as the text value; find its index in options
                sel_text = row.get("selected_option")
                timed_out = bool(int(row.get("timed_out") or 0))
                if sel_text is None or timed_out:
                    sel_0idx = None
                    is_skipped = True
                    is_correct = False
                else:
                    sel_text_str = str(sel_text).strip()
                    try:
                        sel_0idx = next((i for i, o in enumerate(opts) if str(o).strip() == sel_text_str), None)
                    except Exception:
                        sel_0idx = None
                    is_skipped = sel_0idx is None
                    is_correct = (not is_skipped) and (sel_0idx == correct_0idx)
                details.append({
                    "question_index": int(row.get("question_index") or 0),
                    "prompt": q.get("prompt") or q.get("question") or "",
                    "options": opts,
                    "selected_index": sel_0idx,
                    "correct_index": correct_0idx,
                    "is_correct": is_correct,
                    "is_skipped": is_skipped,
                })
            except Exception:
                pass
        payload["details"] = details
    return payload


@app.post("/student/daily-tests/start")
async def student_daily_tests_start(
    payload: DailyTestStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)
    _daily_cleanup_used_bank_once_per_day()
    user_id = int(user.get("id") or 0)
    subjects = _user_subjects_from_row(user)
    requested_subject = _normalize_subject_label(payload.subject)
    if requested_subject and subjects and requested_subject not in subjects:
        raise HTTPException(status_code=403, detail="Selected subject is not available for this student")
    subject = requested_subject or (subjects[0] if subjects else "English")
    level = (_safe_call(lambda: get_group_level_for_subject(user_id, subject), None) or str(user.get("level") or "PRE-INTERMEDIATE")).strip().upper()
    if level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}:
        level = "PRE-INTERMEDIATE"
    test_date = _now_tashkent_date()
    existing_attempt = _daily_attempt_by_user_for_today(user_id, subject)
    if existing_attempt and str(existing_attempt.get("status") or "").strip().lower() in {"completed", "failed"}:
        items = get_daily_test_attempt_items(int(existing_attempt.get("id") or 0))
        return _daily_locked_payload(user, existing_attempt, items)
    try:
        attempt_id, _ = ensure_daily_test_attempt_and_items(
            user_id=user_id,
            subject=subject,
            level=level,
            test_date=test_date,
            total_questions=DAILY_TEST_QUESTION_COUNT,
        )
    except Exception as exc:
        logger.exception(
            "student.daily_tests.start unavailable user_id=%s subject=%s level=%s date=%s",
            user_id,
            subject,
            level,
            test_date,
        )
        return _daily_unavailable_payload(subject, level, str(exc))

    attempt = _daily_attempt_row(attempt_id)
    if not attempt:
        raise HTTPException(status_code=500, detail="Daily test attempt was not created")
    if str(attempt.get("status") or "").strip().lower() in {"completed", "failed"}:
        items = get_daily_test_attempt_items(int(attempt.get("id") or 0))
        return _daily_locked_payload(user, attempt, items)
    items = _daily_apply_expired_timeouts(attempt_id, get_daily_test_attempt_items(attempt_id))
    attempt, items, breakdown = _daily_finalize_if_all_answered(user, attempt, items)
    out = _daily_session_payload(user, attempt, items)
    _apply_daily_breakdown_payload(out, breakdown)
    out["started"] = True
    return _attach_proctoring_payload(
        user,
        out,
        test_type="daily",
        test_attempt_ref=str(attempt_id),
        test_route="/student/daily/process",
    )


@app.get("/student/daily-tests/session")
async def student_daily_tests_session(
    attempt_id: int | None = Query(default=None),
    subject: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user_id = int(user.get("id") or 0)
    subjects = _user_subjects_from_row(user)
    requested_subject = _normalize_subject_label(subject)
    if requested_subject and subjects and requested_subject not in subjects:
        raise HTTPException(status_code=403, detail="Selected subject is not available for this student")
    selected_subject = requested_subject or (subjects[0] if subjects else "English")

    attempt = _daily_attempt_row(int(attempt_id)) if attempt_id else _daily_attempt_by_user_for_today(user_id, selected_subject)
    if not attempt:
        return {"exists": False, "message": "No active daily test attempt for today"}
    if int(attempt.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=403, detail="Attempt does not belong to current user")

    items = _daily_apply_expired_timeouts(int(attempt.get("id") or 0), get_daily_test_attempt_items(int(attempt.get("id") or 0)))
    attempt, items, breakdown = _daily_finalize_if_all_answered(user, attempt, items)
    if str(attempt.get("status") or "").strip().lower() in {"completed", "failed"}:
        out = _daily_locked_payload(user, attempt, items)
        _apply_daily_breakdown_payload(out, breakdown)
        return out
    out = _daily_session_payload(user, attempt, items)
    out["exists"] = True
    return _attach_proctoring_payload(
        user,
        out,
        test_type="daily",
        test_attempt_ref=str(int(attempt.get("id") or 0)),
        test_route="/student/daily/process",
    )


@app.post("/student/daily-tests/answer")
async def student_daily_tests_answer(
    payload: DailyTestAnswerRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    attempt = _daily_attempt_row(int(payload.attempt_id))
    if not attempt:
        raise HTTPException(status_code=404, detail="Attempt not found")
    if int(attempt.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=403, detail="Attempt does not belong to current user")
    _ensure_proctoring_session_access(
        user,
        payload.proctoring_session_id,
        expected_test_type="daily",
        expected_attempt_ref=str(int(payload.attempt_id)),
    )
    attempt_status = str(attempt.get("status") or "").strip().lower()
    if attempt_status in {"completed", "failed"}:
        items = get_daily_test_attempt_items(int(payload.attempt_id))
        out = _daily_session_payload(user, attempt, items)
        if attempt_status == "completed":
            out["already_completed"] = True
        else:
            out["blocked"] = True
            out["blocked_reason"] = "daily_failed_today"
            out["message"] = _daily_locked_message("failed")
        return out

    items = _daily_apply_expired_timeouts(int(payload.attempt_id), get_daily_test_attempt_items(int(payload.attempt_id)))
    current = None
    for row in items:
        if row.get("selected_option") is None and not bool(int(row.get("timed_out") or 0)):
            current = row
            break
    if not current:
        items = get_daily_test_attempt_items(int(payload.attempt_id))
        attempt, items, breakdown = _daily_finalize_if_all_answered(user, attempt, items)
        out = _daily_session_payload(user, attempt, items)
        _apply_daily_breakdown_payload(out, breakdown)
        out["completed"] = True
        return out
    expected_index = int(current.get("question_index") or 0)
    if int(payload.question_index) != expected_index:
        raise HTTPException(status_code=409, detail="Question mismatch. Refresh session and try again.")

    if payload.selected_option_index is None:
        mark_daily_test_question_timed_out(int(payload.attempt_id), expected_index)
    else:
        sel = int(payload.selected_option_index)
        if sel < 0 or sel > 3:
            raise HTTPException(status_code=400, detail="selected_option_index must be 0..3")
        options = _mcq_question_from_row(current).get("options") or []
        selected_option = str(options[sel]) if sel < len(options) else ""
        mark_daily_test_question_answered(
            int(payload.attempt_id),
            expected_index,
            selected_option,
            is_correct=_selected_option_is_correct(current, sel),
        )

    WEB_DAILY_ATTEMPT_TIMERS.pop(_daily_timer_key(int(payload.attempt_id), expected_index), None)
    attempt = _daily_attempt_row(int(payload.attempt_id)) or attempt
    items = get_daily_test_attempt_items(int(payload.attempt_id))
    out = _daily_session_payload(user, attempt, items)
    if not out.get("completed"):
        return out

    correct, wrong, unanswered = _attempt_counts_from_items(items)
    breakdown = award_quiz_dpoints(
        user_id=user_id,
        subject=str(attempt.get("subject") or "English"),
        correct_count=correct,
        wrong_count=wrong,
        skipped_count=unanswered,
        mode="daily_test",
        change_type="daily_test_web_result",
    )
    net = float(breakdown.get("final_dcoins") or 0)
    net_points = float(breakdown.get("total_points") or 0)
    finish_daily_test_attempt(
        attempt_id=int(payload.attempt_id),
        correct=correct,
        wrong=wrong,
        unanswered=unanswered,
        net_dcoins=net,
        net_dpoints=net_points,
    )
    _invalidate_student_overview_cache(user_id)
    attempt = _daily_attempt_row(int(payload.attempt_id)) or attempt
    final_out = _daily_session_payload(user, attempt, get_daily_test_attempt_items(int(payload.attempt_id)))
    _apply_daily_breakdown_payload(final_out, breakdown)
    final_out["completed"] = True
    return final_out


# ---------------------------------------------------------------------------
# Gamified tests (Duolingo-style, no audio) — separate from daily tests.
# 20 questions/session, mixed interactive types. Scoring: +2 / -3 / -1.5.
# Answers are stored server-side; the public payload never leaks _answer.
# ---------------------------------------------------------------------------
def _gamified_resolve_subject(user: dict, requested: str | None) -> str:
    """Pick a language subject (English/Russian) for the gamified session."""
    subjects = _user_subjects_from_row(user)
    lang_subjects = [s for s in subjects if s in ("English", "Russian")]
    normalized = _normalize_subject_label(requested)
    if normalized in ("English", "Russian"):
        if lang_subjects and normalized not in lang_subjects:
            raise HTTPException(status_code=403, detail="Selected subject is not available for this student")
        return normalized
    if lang_subjects:
        return lang_subjects[0]
    return "English"


def _gamified_resolve_level(user_id: int, subject: str, user: dict) -> str:
    """Resolve the student's level for the subject so questions match their level."""
    level = (
        _safe_call(lambda: get_group_level_for_subject(user_id, subject), None)
        or str(user.get("level") or "PRE-INTERMEDIATE")
    ).strip().upper()
    valid = {
        "BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE",
        "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1", "C2",
    }
    if level not in valid:
        level = "PRE-INTERMEDIATE"
    return level


def _gamified_scoring_payload() -> dict[str, Any]:
    rules = _get_runtime_settings()
    correct = float(rules.get("correct_answer_reward", 2.0))
    wrong = -abs(float(rules.get("wrong_answer_penalty", 3.0)))
    skipped = -abs(float(rules.get("skipped_answer_penalty", 1.5)))
    return {
        "correct": correct,
        "wrong": wrong,
        "skipped": skipped,
    }


@app.post("/student/gamified-tests/start")
async def student_gamified_tests_start(
    payload: GamifiedStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user_id = int(user.get("id") or 0)
    subject = _gamified_resolve_subject(user, payload.subject)
    level = _gamified_resolve_level(user_id, subject, user)
    session_id = uuid4().hex
    # Generate fresh material via AI so questions/readings don't repeat
    # between attempts. Fully best-effort: on any failure/timeout the
    # builder falls back to the static curated bank, so a test always
    # starts even if the AI is slow or down.
    vocab: list[dict[str, str]] | None = None
    ai_readings: list[dict[str, Any]] | None = None
    try:
        material = await asyncio.wait_for(
            generate_gamified_material(subject=subject, level=level, session_nonce=session_id),
            timeout=8.0,
        )
        vocab = material.get("vocab") or None
        ai_readings = material.get("readings") or None
    except Exception:
        logger.exception("gamified start: AI material generation failed, using static bank")
    questions = gamified_tests.build_questions(
        subject, level=level, count=gamified_tests.QUESTION_COUNT, vocab=vocab, ai_readings=ai_readings
    )
    requested_count = int(gamified_tests.QUESTION_COUNT)
    try:
        ready_count = sum(int(gamified_tests._score_units(q)) for q in questions)
    except Exception:
        ready_count = len(questions)
    ready_count = max(0, min(requested_count, int(ready_count or 0)))
    ready_percent = int(round((ready_count * 100) / max(1, requested_count)))
    GAMIFIED_SESSIONS[session_id] = {
        "user_id": user_id,
        "subject": subject,
        "level": level,
        "questions": questions,
        "created_at": time.time(),
    }
    return {
        "session_id": session_id,
        "subject": subject,
        "level": level,
        "total": ready_count,
        "question_blocks": len(questions),
        "score_units": ready_count,
        "requested_count": requested_count,
        "ready_count": ready_count,
        "ready_percent": ready_percent,
        "generated_by_ai": bool(vocab or ai_readings),
        "scoring": _gamified_scoring_payload(),
        "questions": [gamified_tests.public_question(q) for q in questions],
    }


@app.post("/student/gamified-tests/submit")
async def student_gamified_tests_submit(
    payload: GamifiedSubmitRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    session = GAMIFIED_SESSIONS.get(payload.session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Gamified session not found or expired")
    if int(session.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=403, detail="Session does not belong to current user")

    questions = session.get("questions") or []
    subject = str(session.get("subject") or "English")
    answers_by_index: dict[int, Any] = {}
    for item in (payload.answers or []):
        try:
            answers_by_index[int(item.index)] = item.answer
        except Exception:
            continue

    scoring = _gamified_scoring_payload()
    summary = gamified_tests.score_session(
        questions,
        answers_by_index,
        correct_score=scoring["correct"],
        wrong_score=scoring["wrong"],
        skip_score=scoring["skipped"],
    )
    net = float(summary.get("score") or 0)
    if net != 0:
        add_dpoints(user_id, net, subject=subject, change_type="gamified_test_result")
    _invalidate_student_overview_cache(user_id)
    GAMIFIED_SESSIONS.pop(payload.session_id, None)

    summary["subject"] = subject
    summary["awarded_dpoints"] = round(net, 1)
    summary["scoring"] = scoring
    return summary


@app.post("/student/gamified-tests/check-pair")
async def student_gamified_tests_check_pair(
    payload: GamifiedCheckPairRequest,
    authorization: str | None = Header(default=None),
):
    """Immediate right/wrong feedback for ONE word_match/heading_match pair
    (client taps a pairing, we tell it right away instead of only at final
    submit) — without ever exposing the full answer key. Purely a read of
    the already-generated session's `_answer` map; does not affect
    scoring, which still happens once in `/submit` from the client's final
    answer map (this just lets the UI lock in correct pairs immediately
    per the student's request)."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    session = GAMIFIED_SESSIONS.get(payload.session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Gamified session not found or expired")
    if int(session.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=403, detail="Session does not belong to current user")
    questions = session.get("questions") or []
    question = next((q for q in questions if int(q.get("index", -1)) == int(payload.question_index)), None)
    if not question or question.get("type") not in ("word_match", "heading_match"):
        raise HTTPException(status_code=404, detail="Question not found or not a matching question")
    answer_map = question.get("_answer") or {}
    is_correct = str(answer_map.get(payload.key, "")) == str(payload.value)
    return {"correct": bool(is_correct)}


@app.post("/student/gamified-tests/check-answer")
async def student_gamified_tests_check_answer(
    payload: GamifiedCheckAnswerRequest,
    authorization: str | None = Header(default=None),
):
    """Immediate right/wrong feedback for a single MCQ or fill_gap question.
    Returns {correct: bool} without revealing the correct_index so the client
    can show Duolingo-style green/red feedback before moving to the next question.
    Does NOT affect scoring — scoring still happens in /submit."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    session = GAMIFIED_SESSIONS.get(payload.session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Gamified session not found or expired")
    if int(session.get("user_id") or 0) != user_id:
        raise HTTPException(status_code=403, detail="Session does not belong to current user")
    questions = session.get("questions") or []
    question = next((q for q in questions if int(q.get("index", -1)) == int(payload.question_index)), None)
    if not question or question.get("type") not in ("mcq", "fill_gap", "reading_true_false", "reading_mcq"):
        raise HTTPException(status_code=404, detail="Question not found or not an MCQ/fill_gap/reading question")
    correct_index = int(question.get("_answer") if question.get("_answer") is not None else question.get("correct_index", -1))
    is_correct = int(payload.selected_option_index) == correct_index
    return {"correct": bool(is_correct)}





def _competition_required_players(mode: str) -> int:
    if mode == "duel-1v1":
        return 2
    if mode == "duel-3v3":
        return 6
    if mode == "duel-5v5":
        return 10
    if mode == "daily":
        try:
            settings = _get_runtime_settings()
            return max(1, int(settings.get("daily_arena_min_players") or 10))
        except Exception:
            return 10
    if mode == "boss":
        return 5
    return 1


def _competition_max_players(mode: str) -> int:
    if mode == "daily":
        # Daily arena caps at 15 players (min 10 to start).
        try:
            settings = _get_runtime_settings()
            cap = int(settings.get("daily_arena_max_players") or 15)
        except Exception:
            cap = 15
        return max(_competition_required_players("daily"), cap)
    if mode == "boss":
        return 200  # effectively unlimited
    return _competition_required_players(mode)


def _competition_question_count(mode: str) -> int:
    return 15 if mode == "boss" else 10


def _competition_default_difficulty(mode: str) -> str:
    if mode == "boss":
        return "Hard"
    if mode == "daily":
        return "Medium"
    if str(mode or "").startswith("duel-"):
        return "Medium"
    return "Medium"


def _competition_generation_level(base_level: str, mode: str, stage: int, difficulty: str | None = None) -> str:
    normalized = str(difficulty or _competition_default_difficulty(mode)).strip().lower()
    if mode == "daily":
        return _competition_stage_level(base_level, mode, stage)
    if normalized == "hard":
        return _competition_stage_level(base_level, "boss", 1)
    if normalized == "medium":
        return _competition_stage_level(base_level, "daily", 2)
    return _competition_stage_level(base_level, mode, stage)


def _competition_total_stages(mode: str) -> int:
    return 5 if str(mode or "") == "daily" else 1


def _competition_finalists_target(mode: str) -> int:
    return 4 if str(mode or "") == "daily" else 0


def _competition_queue_key(mode: str, subject: str, level: str) -> str:
    if mode in {"daily", "boss"}:
        return f"{mode}|{subject}"
    if mode.startswith("duel-"):
        return f"{mode}|{subject}"
    return f"{mode}|{subject}|{level}"


@contextmanager
def _competition_session_advisory_lock(session_id: str):
    """Cross-worker database-level lock for a specific Arena/Duel session."""
    lock_key = f"competition_session:{str(session_id or '').strip()}"
    conn = None
    cur = None
    locked = False
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("SELECT pg_advisory_lock(hashtext(?))", (lock_key,))
        locked = True
    except Exception:
        logger.exception("competition session advisory lock unavailable session_id=%s", session_id)
        try:
            if conn:
                conn.close()
        except Exception:
            pass
        conn = None
        cur = None
    try:
        yield
    finally:
        if locked and conn and cur:
            try:
                cur.execute("SELECT pg_advisory_unlock(hashtext(?))", (lock_key,))
                conn.commit()
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                logger.exception("competition session advisory unlock failed session_id=%s", session_id)
        try:
            if conn:
                conn.close()
        except Exception:
            pass


@contextmanager
def _competition_queue_advisory_lock(queue_key: str):
    """Cross-worker lock for one Arena/Duel matching queue."""
    lock_key = f"competition_queue:{str(queue_key or '').strip()}"
    conn = None
    cur = None
    locked = False
    try:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("SELECT pg_advisory_lock(hashtext(?))", (lock_key,))
        locked = True
    except Exception:
        logger.exception("competition queue advisory lock unavailable queue_key=%s", queue_key)
        try:
            if conn:
                conn.close()
        except Exception:
            pass
        conn = None
        cur = None
    try:
        yield
    finally:
        if locked and conn and cur:
            try:
                cur.execute("SELECT pg_advisory_unlock(hashtext(?))", (lock_key,))
                conn.commit()
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                logger.exception("competition queue advisory unlock failed queue_key=%s", queue_key)
        try:
            if conn:
                conn.close()
        except Exception:
            pass


def _group_arena_today_presence(group_id: int) -> tuple[str, list[dict[str, Any]], bool, str]:
    today = _now_tashkent().strftime("%Y-%m-%d")
    members = [
        row
        for row in (_safe_call(lambda: get_group_users(int(group_id)), []) or [])
        if int(row.get("login_type") or 0) in (1, 2, 6)
    ]
    attendance_rows = _safe_call(lambda: get_attendance_by_group(int(group_id), today), []) or []
    attendance_by_user = {int(row.get("user_id") or 0): str(row.get("status") or "").strip().lower() for row in attendance_rows}
    member_ids = {int(row.get("id") or 0) for row in members if int(row.get("id") or 0) > 0}
    if not member_ids:
        return today, [], False, "Group has no account students"
    missing = [uid for uid in member_ids if uid not in attendance_by_user]
    if missing:
        return today, [], False, "Attendance must be completed before Group Arena starts"
    present = _safe_call(lambda: get_present_students_for_group_date(int(group_id), today), []) or []
    present = [dict(row) for row in present if int(row.get("id") or 0) in member_ids]
    if not present:
        return today, [], False, "Only present students can join Group Arena"
    return today, present, True, ""


def _competition_cleanup_stale_pending(now: datetime | None = None) -> None:
    now_dt = now or _now_utc()
    stale_cutoff = now_dt - timedelta(minutes=20)
    
    conn = get_conn()
    cur = conn.cursor()
    db_sessions = []
    try:
        cur.execute(
            """
            SELECT session_id, payload_json FROM web_competition_sessions
            WHERE status IN ('pending', 'generating', 'running')
            """
        )
        for row in cur.fetchall():
            db_sessions.append((str(row.get("session_id", "")), str(row.get("payload_json", ""))))
    except Exception:
        logger.exception("Failed to query non-finished competition sessions from DB")
    finally:
        conn.close()

    for sid, payload_json in db_sessions:
        session = WEB_COMPETITION_SESSIONS.get(sid)
        if not session and payload_json:
            try:
                session = json.loads(payload_json)
                WEB_COMPETITION_SESSIONS[sid] = session
            except Exception:
                continue
        if not session:
            continue

        mode = str(session.get("mode") or "")
        phase = _competition_session_phase(session)
        
        if phase in {"pending", "generating"}:
            if _competition_expire_waiting_session_if_needed(session, now_dt):
                continue
            
            created = _parse_utc_timestamp(str(session.get("created_at") or "")) or now_dt
            if created < stale_cutoff:
                if _duel_is_mode(mode):
                    _duel_refund_pending_session(session, "Queue expired")
                else:
                    _competition_refund_entry_fee(session)
                    session["status"] = "finished"
                    session["finalized"] = True
                    session["result"] = {"winners": [], "by_user": {}, "error": "Queue expired"}
                    notify_rows = _competition_waiting_participants(session) if _duel_is_mode(mode) else _competition_joined_participants(session)
                    for row in notify_rows:
                        WEB_DUEL_PLAYER_SESSION.pop(int(row.get("user_id") or 0), None)
                    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
                    _duel_persist_session(session)
                continue
                
            if session.get("status") == "generating":
                if created + timedelta(minutes=8) < now_dt:
                    if _duel_is_mode(mode):
                        _duel_refund_pending_session(session, "Generation timed out")
                    else:
                        _competition_refund_entry_fee(session)
                        session["status"] = "finished"
                        session["finalized"] = True
                        session["result"] = {"winners": [], "by_user": {}, "error": "Generation timed out"}
                        for row in session.get("participants") or []:
                            WEB_DUEL_PLAYER_SESSION.pop(int(row.get("user_id") or 0), None)
                        WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
                        _duel_persist_session(session)
                    continue

        elif phase == "active" or session.get("status") == "running":
            started_val = session.get("started_at")
            if started_val:
                started_dt = _parse_utc_timestamp(str(started_val))
                if started_dt:
                    max_duration = 45 if mode == "daily" else 20
                    if started_dt + timedelta(minutes=max_duration) < now_dt:
                        logger.info("Expiring stale running session_id=%s mode=%s started_at=%s", sid, mode, started_val)
                        for row in session.get("participants") or []:
                            uid = int(row.get("user_id") or 0)
                            if uid > 0 and str(row.get("status") or "active").strip().lower() == "active":
                                row["status"] = "left"
                                row["left_at"] = now_dt.isoformat()
                                row["left_reason"] = "stale_cleanup"
                                _competition_finish_user_remaining_questions(session, uid, reason="stale_cleanup")
                        if mode == "daily":
                            _competition_finalize_daily_stage(session)
                        else:
                            _competition_finalize_non_daily(session)

    for key, session_id in list(WEB_COMPETITION_PENDING_BY_KEY.items()):
        if session_id not in WEB_COMPETITION_SESSIONS:
            WEB_COMPETITION_PENDING_BY_KEY.pop(key, None)
        else:
            sess = WEB_COMPETITION_SESSIONS[session_id]
            if _competition_session_phase(sess) == "finished":
                WEB_COMPETITION_PENDING_BY_KEY.pop(key, None)


async def _competition_notify_session_timeout(session: dict[str, Any]) -> None:
    mode = str(session.get("mode") or "")
    subject = str(session.get("subject") or "English")
    is_duel = _duel_is_mode(mode)
    title = "Duel boshlanmadi" if is_duel else "Arena boshlanmadi"
    message = f"{title}: {subject}. Kirish haqi qaytarildi."
    web_path = _competition_runtime_path_for_session(session)
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    rows = _competition_joined_participants(session)
    try:
        _ensure_web_tables()
        conn = get_conn()
        cur = conn.cursor()
        try:
            for row in rows:
                uid = int(row.get("user_id") or 0)
                if uid <= 0:
                    continue
                _payment_upsert_web_notification(
                    cur,
                    user_id=uid,
                    notification_type="competition_timeout",
                    title=title,
                    message=message,
                    button_text="Ko'rish",
                    button_url=web_path,
                    target_screen=_competition_section_for_mode(mode),
                    source_key=f"competition_timeout:{session.get('id')}:{uid}",
                    meta={
                        "session_id": str(session.get("id") or ""),
                        "mode": mode,
                        "subject": subject,
                        "refunded": True,
                    },
                )
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            raise
        finally:
            conn.close()
    except Exception:
        logger.exception("competition timeout web notification failed session_id=%s", session.get("id"))

    if not token:
        return
    attempted = sent = failed = skipped = 0
    for row in rows:
        uid = int(row.get("user_id") or 0)
        user_row = _safe_call(lambda target_uid=uid: get_user_by_id(target_uid), None) or {}
        tg = str(user_row.get("telegram_id") or "").strip()
        if not tg:
            skipped += 1
            continue
        attempted += 1
        try:
            if await _send_telegram_text(token, tg, message, button_text="Ko'rish", button_url=_competition_runtime_url_for_session(session), button_web_app=True):
                sent += 1
            else:
                failed += 1
        except Exception:
            failed += 1
            logger.warning("competition timeout telegram failed session_id=%s user_id=%s", session.get("id"), uid)
        if attempted and attempted % 25 == 0:
            await asyncio.sleep(0.25)
    logger.info(
        "competition timeout notifications session_id=%s mode=%s subject=%s attempted=%s sent=%s failed=%s skipped=%s",
        session.get("id"),
        mode,
        subject,
        attempted,
        sent,
        failed,
        skipped,
    )


def _competition_schedule_timeout_notification(session: dict[str, Any]) -> None:
    if session.get("timeout_notifications_sent"):
        return
    session["timeout_notifications_sent"] = True
    try:
        loop = asyncio.get_running_loop()
        loop.create_task(_competition_notify_session_timeout(dict(session)))
    except RuntimeError:
        logger.info("competition timeout notification skipped outside event loop session_id=%s", session.get("id"))


def _competition_pending_uses_wait_timer(session: dict[str, Any]) -> bool:
    mode = str(session.get("mode") or "")
    return mode in {"daily", "boss"} or _duel_is_mode(mode)


def _competition_participant_join_times(session: dict[str, Any]) -> list[datetime]:
    times: list[datetime] = []
    for row in _competition_waiting_participants(session):
        joined = _parse_utc_timestamp(str(row.get("joined_at") or ""))
        if joined:
            times.append(joined)
    return sorted(times)


def _competition_touch_wait_deadline(session: dict[str, Any], now: datetime | None = None) -> None:
    if not _competition_pending_uses_wait_timer(session):
        return
    if session.get("started_at") or _competition_session_phase(session) != "pending":
        return
    now_dt = now or _now_utc()
    joined_times = _competition_participant_join_times(session)
    if not joined_times:
        return
    first = _parse_utc_timestamp(str(session.get("first_joined_at") or "")) or joined_times[0]
    session["first_joined_at"] = first.isoformat()
    session["last_joined_at"] = now_dt.isoformat()
    
    existing_deadline = _parse_utc_timestamp(str(session.get("wait_deadline_at") or ""))
    if existing_deadline:
        deadline = existing_deadline
    else:
        mode = str(session.get("mode") or "")
        if mode == "daily":
            deadline = None
            hhmm = _competition_schedule_start("daily", str(session.get("subject") or "English"))
            if hhmm:
                try:
                    now_t = _now_tashkent()
                    hh, mm = [int(x) for x in hhmm.split(":", 1)]
                    target_dt = now_t.replace(hour=hh, minute=mm, second=0, microsecond=0)
                    deadline_tashkent = target_dt + timedelta(minutes=1)
                    deadline = deadline_tashkent.astimezone(timezone.utc)
                except Exception:
                    pass
            if not deadline:
                deadline = first + timedelta(seconds=300)
        elif mode == "boss":
            deadline = first + timedelta(seconds=180)
        else:
            deadline = first + timedelta(seconds=COMPETITION_PENDING_WAIT_SECONDS)
            
    # Once the minimum number of players has gathered, collapse the wait to a short
    # 1-minute auto-start countdown (never extends an already-sooner deadline).
    required_min = int(session.get("required_players") or _competition_required_players(str(session.get("mode") or "")) or 1)
    waiting_now = len(_competition_waiting_participants(session))
    if waiting_now >= required_min:
        short_deadline = now_dt + timedelta(seconds=60)
        if short_deadline < deadline:
            deadline = short_deadline
    session["wait_deadline_at"] = deadline.isoformat()
    session["required_players"] = required_min
    session["joined_count"] = waiting_now


def _competition_ensure_wait_deadline(session: dict[str, Any], now: datetime | None = None) -> datetime | None:
    if not _competition_pending_uses_wait_timer(session):
        return None
    if session.get("started_at") or _competition_session_phase(session) != "pending":
        return None
    now_dt = now or _now_utc()
    deadline = _parse_utc_timestamp(str(session.get("wait_deadline_at") or ""))
    if deadline:
        return deadline
    joined_times = _competition_participant_join_times(session)
    if not joined_times:
        return None
    first = _parse_utc_timestamp(str(session.get("first_joined_at") or "")) or joined_times[0]
    last = _parse_utc_timestamp(str(session.get("last_joined_at") or "")) or joined_times[-1]
    
    mode = str(session.get("mode") or "")
    if mode == "daily":
        deadline = None
        hhmm = _competition_schedule_start("daily", str(session.get("subject") or "English"))
        if hhmm:
            try:
                now_t = _now_tashkent()
                hh, mm = [int(x) for x in hhmm.split(":", 1)]
                target_dt = now_t.replace(hour=hh, minute=mm, second=0, microsecond=0)
                deadline_tashkent = target_dt + timedelta(minutes=1)
                deadline = deadline_tashkent.astimezone(timezone.utc)
            except Exception:
                pass
        if not deadline:
            deadline = first + timedelta(seconds=300)
    elif mode == "boss":
        deadline = first + timedelta(seconds=180)
    else:
        deadline = first + timedelta(seconds=COMPETITION_PENDING_WAIT_SECONDS)
        
    session["first_joined_at"] = first.isoformat()
    session["last_joined_at"] = last.isoformat()
    session["wait_deadline_at"] = deadline.isoformat()
    session["required_players"] = int(session.get("required_players") or _competition_required_players(str(session.get("mode") or "")) or 1)
    session["joined_count"] = len(_competition_waiting_participants(session))
    if deadline > now_dt:
        _duel_persist_session(session)
    return deadline


def _competition_expire_waiting_session_if_needed(session: dict[str, Any] | None, now: datetime | None = None) -> bool:
    if not session or not _competition_pending_uses_wait_timer(session):
        return False
    # Only block on phase, NOT on started_at — generating phase can still be cancelled/refunded
    if _competition_session_phase(session) not in {"pending", "generating"}:
        return False
    now_dt = now or _now_utc()

    waiting = _competition_waiting_participants(session)
    required = int(session.get("required_players") or _competition_required_players(str(session.get("mode") or "")) or 1)
    deadline = _competition_ensure_wait_deadline(session, now_dt)
    
    if not deadline or deadline > now_dt:
        return False
        
    if len(waiting) >= required:
        if _competition_session_phase(session) == "pending":
            token = _competition_prepare_generation(session, target_stage=1)
            if token:
                asyncio.create_task(_competition_start_generation(str(session.get("id") or ""), stage=1, generation_token=token))
        return False

    reason = "session_timeout"
    for uid in [int(x) for x in (session.get("charged_user_ids") or []) if int(x) > 0]:
        _competition_refund_user_entry_fee(session, uid, reason, force=True)
    by_user: dict[int, dict[str, Any]] = {}
    refunded = {int(x) for x in (session.get("refunded_user_ids") or []) if int(x) > 0}
    for row in session.get("participants") or []:
        uid = int(row.get("user_id") or 0)
        if uid <= 0:
            continue
        row["status"] = "cancelled"
        by_user[uid] = {
            "rank": None,
            "correct": 0,
            "wrong": 0,
            "unanswered": 0,
            "total_questions": 0,
            "accuracy": 0.0,
            "winner": False,
            "tie": False,
            "dpoints_delta": 0.0,
            "dcoin": 0.0,
            "refunded": uid in refunded,
            "result_status": "cancelled",
            "error": reason,
        }
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
    session["status"] = "expired"
    session["finalized"] = True
    session["cancelled_at"] = now_dt.isoformat()
    session["finished_at"] = now_dt.isoformat()
    session["cancel_reason"] = reason
    session["result"] = {
        "winners": [],
        "by_user": by_user,
        "tie": False,
        "error": reason,
        "refunded": True,
        "reason": "Arena/Duel session timeout",
    }
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    _competition_save_history(session)
    _duel_persist_session(session)
    _competition_schedule_timeout_notification(session)
    logger.info(
        "competition pending session expired session_id=%s mode=%s subject=%s joined=%s required=%s refunded=%s",
        session.get("id"),
        session.get("mode"),
        session.get("subject"),
        len(waiting),
        required,
        len(refunded),
    )
    return True


def _competition_runtime_path_for_session(session: dict[str, Any], *, include_session_id: bool = True) -> str:
    section = _competition_section_for_mode(str(session.get("mode") or "daily"))
    path_map = {
        "arena-daily": "/student/arena/daily/run",
        "arena-group": "/student/arena/group/run",
        "arena-boss": "/student/arena/boss/run",
        "duel-1v1": "/student/duel/1v1/run",
        "duel-3v3": "/student/duel/3v3/run",
        "duel-5v5": "/student/duel/5v5/run",
    }
    path = path_map.get(section, "/?role=student&section=arena")
    subject = quote(str(session.get("subject") or "English"))
    query = f"arena_mode={quote(section)}&auto_join=1&subject={subject}"
    if include_session_id:
        query = f"{query}&session_id={quote(str(session.get('id') or ''))}"
    return f"{path}?{query}"


def _competition_runtime_url_for_session(session: dict[str, Any], *, include_session_id: bool = True) -> str:
    relative = _competition_runtime_path_for_session(session, include_session_id=include_session_id)
    return f"{WEBAPP_URL}{relative}" if WEBAPP_URL else relative


async def _competition_notify_started(session: dict[str, Any]) -> None:
    if session.get("start_notifications_sent"):
        return
    session["start_notifications_sent"] = True
    mode_title = _competition_section_for_mode(str(session.get("mode") or "daily")).replace("-", " ").title()
    subject = str(session.get("subject") or "English")
    # Invite links are intentionally generic by mode+subject. If the lobby
    # referenced by this notification becomes full, the normal start endpoint
    # creates/joins the next matching lobby instead of failing on an old id.
    web_path = _competition_runtime_path_for_session(session, include_session_id=False)
    telegram_url = _competition_runtime_url_for_session(session, include_session_id=False)
    title = "Arena boshlandi" if not str(session.get("mode") or "").startswith("duel-") else "Duel boshlandi"
    message = f"{mode_title} ({subject}) boshlandi. To'g'ridan-to'g'ri kirish uchun tugmani bosing."
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    try:
        _ensure_web_tables()
        conn = get_conn()
        cur = conn.cursor()
        for row in _competition_joined_participants(session):
            uid = int(row.get("user_id") or 0)
            if uid <= 0:
                continue
            try:
                _payment_upsert_web_notification(
                    cur,
                    user_id=uid,
                    notification_type="competition_started",
                    title=title,
                    message=message,
                    button_text="Kirish",
                    button_url=web_path,
                    target_screen=_competition_section_for_mode(str(session.get("mode") or "")),
                    source_key=f"competition_started:{session.get('id')}:{uid}",
                    meta={
                        "session_id": str(session.get("id") or ""),
                        "mode": str(session.get("mode") or ""),
                        "subject": subject,
                    },
                )
            except Exception:
                logger.exception("competition web notification failed session_id=%s user_id=%s", session.get("id"), uid)
        conn.commit()
    except Exception:
        logger.exception("competition notification storage failed session_id=%s", session.get("id"))
    finally:
        try:
            conn.close()  # type: ignore[name-defined]
        except Exception:
            pass

    if not token:
        return
    notify_rows = _competition_waiting_participants(session) if _duel_is_mode(session.get("mode")) else _competition_joined_participants(session)
    for row in notify_rows:
        uid = int(row.get("user_id") or 0)
        user_row = _safe_call(lambda target_uid=uid: get_user_by_id(target_uid), None) or {}
        tg = str(user_row.get("telegram_id") or "").strip()
        if not tg:
            continue
        await _send_telegram_text(token, tg, message, button_text="Kirish", button_url=telegram_url if telegram_url.startswith("http") else None, button_web_app=True)

def _get_students_for_daily_arena(subject: str) -> list[dict[str, Any]]:
    """Return active students in groups with the given subject.
    Avoids full get_all_students() + per-student group look-ups."""
    norm = _normalize_subject_label(subject) or str(subject or "")
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT DISTINCT u.*
            FROM users u
            JOIN user_groups ug ON u.id = ug.user_id
            JOIN groups g ON g.id = ug.group_id
            WHERE u.login_type IN (1, 2, 6)
              AND COALESCE(u.active, 1)=1
              AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT)) = '')
              AND LOWER(TRIM(g.subject)) = LOWER(TRIM(?))
            ORDER BY u.id
            """,
            (norm,),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    except Exception:
        logger.exception("_get_students_for_daily_arena failed subject=%s", subject)
        rows = []
    finally:
        conn.close()
    eligible: list[dict[str, Any]] = []
    for row in rows:
        uid = int(row.get("id") or 0)
        if uid <= 0:
            continue
        try:
            _require_student_learning_access(row)
        except HTTPException:
            continue
        eligible.append(row)
    return eligible


async def _competition_notify_daily_prestart(session: dict[str, Any]) -> None:
    if str(session.get("mode") or "") != "daily":
        return
    subject = _normalize_subject_label(str(session.get("subject") or "English")) or "English"
    marker = f"{subject}:{_now_tashkent_date()}:{session.get('id') or ''}"
    # Fast in-memory dedup
    if marker in WEB_COMPETITION_PRESTART_SENT:
        return
    # Persistent dedup: survives process restarts
    db_sent_key = f"daily_arena_prestart_sent:{marker}"
    if _get_web_runtime_string_setting(db_sent_key, "") == "1":
        WEB_COMPETITION_PRESTART_SENT.add(marker)
        return
    WEB_COMPETITION_PRESTART_SENT.add(marker)
    # Persist immediately so concurrent or restarted processes won't re-send
    _set_web_runtime_string_setting(db_sent_key, "1")

    # Invite links are generic. Students who tap after this lobby fills will
    # be placed into the next open lobby for the same mode+subject.
    web_path = _competition_runtime_path_for_session(session, include_session_id=False)
    telegram_url = _competition_runtime_url_for_session(session, include_session_id=False)
    title = "Daily Arena boshlanishiga oz qoldi"
    message = f"Daily Arena ({subject}) boshlanishiga oz qoldi. Kirish tugmasi orqali arenaga o'ting."
    source_prefix = f"daily_arena_prestart:{marker}"
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()

    try:
        # Targeted query: only students enrolled in groups for this subject
        eligible: list[dict[str, Any]] = _get_students_for_daily_arena(subject)
        if not eligible:
            return

        _ensure_web_tables()
        conn = get_conn()
        cur = conn.cursor()
        try:
            for row in eligible:
                uid = int(row.get("id") or 0)
                _payment_upsert_web_notification(
                    cur,
                    user_id=uid,
                    notification_type="daily_arena_prestart",
                    title=title,
                    message=message,
                    button_text="Daily Arena'ga kirish",
                    button_url=web_path,
                    target_screen="arena-daily",
                    source_key=f"{source_prefix}:{uid}",
                    meta={
                        "session_id": str(session.get("id") or ""),
                        "mode": "daily",
                        "subject": subject,
                        "date": _now_tashkent_date(),
                        "browser_notification_scope": "in_app_session",
                    },
                )
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            raise
        finally:
            conn.close()

        if token:
            for row in eligible:
                tg = str(row.get("telegram_id") or "").strip()
                if tg:
                    await _send_telegram_text(
                        token,
                        tg,
                        message,
                        button_text="Daily Arena'ga kirish",
                        button_url=telegram_url if telegram_url.startswith("http") else None,
                        button_web_app=True,
                    )
    except Exception:
        WEB_COMPETITION_PRESTART_SENT.discard(marker)
        # Revert persistent marker so the next scheduler cycle will retry
        try:
            _set_web_runtime_string_setting(db_sent_key, "")
        except Exception:
            pass
        logger.exception("daily arena pre-start notification failed subject=%s session_id=%s", subject, session.get("id"))



async def _competition_notify_session_available(session: dict[str, Any], creator_user_id: int | None = None) -> None:
    if session.get("available_notifications_sent"):
        return
    mode = str(session.get("mode") or "")
    if mode == "group" or not mode:
        return
    session["available_notifications_sent"] = True
    subject = _normalize_subject_label(str(session.get("subject") or "English")) or "English"
    mode_title = _competition_section_for_mode(mode).replace("-", " ").title()
    # Generic invite link: joining is resolved by mode+subject at click time.
    # If the old lobby is full, /competition/runtime/start opens the next one.
    web_path = _competition_runtime_path_for_session(session, include_session_id=False)
    telegram_url = _competition_runtime_url_for_session(session, include_session_id=False)
    is_duel = _duel_is_mode(mode)
    title = "Yangi Duel boshlandi" if is_duel else "Yangi sessiya mavjud"
    message = (
        f"Yangi {mode_title} boshlandi: {subject}. Kirish tugmasi orqali Duel lobbysiga o'ting."
        if is_duel
        else f"Yangi {mode_title} sessiyasi mavjud: {subject}. Qo'shilish uchun Kirish tugmasini bosing."
    )
    source_prefix = f"{'duel_available' if is_duel else 'competition_available'}:{session.get('id')}"
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    sent_rows: list[dict[str, Any]] = []
    try:
        rows = _get_students_for_daily_arena(subject)
        if not rows:
            rows = _safe_call(get_all_students, []) or []
        eligible: list[dict[str, Any]] = []
        for row in rows:
            uid = int(row.get("id") or 0)
            if uid <= 0 or (creator_user_id and uid == int(creator_user_id)):
                continue
            try:
                _require_student_learning_access(row)
            except HTTPException:
                continue
            if subject not in _normalize_subjects(_user_subjects_from_row(row), fallback=[]):
                continue
            eligible.append(row)
        if not eligible:
            session["available_notifications_sent"] = False
            logger.info(
                "competition available notification skipped no eligible students mode=%s subject=%s session_id=%s",
                mode,
                subject,
                session.get("id"),
            )
            return
        _ensure_web_tables()
        conn = get_conn()
        cur = conn.cursor()
        try:
            for row in eligible:
                uid = int(row.get("id") or 0)
                _payment_upsert_web_notification(
                    cur,
                    user_id=uid,
                    notification_type="duel_available" if is_duel else "competition_available",
                    title=title,
                    message=message,
                    button_text="Kirish",
                    button_url=web_path,
                    target_screen=_competition_section_for_mode(mode),
                    source_key=f"{source_prefix}:{uid}",
                    meta={
                        "session_id": str(session.get("id") or ""),
                        "mode": mode,
                        "subject": subject,
                        "browser_notification_scope": "in_app_session",
                    },
                )
                sent_rows.append(row)
            conn.commit()
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            raise
        finally:
            conn.close()
    except Exception:
        session["available_notifications_sent"] = False
        logger.exception("competition available notification failed mode=%s subject=%s session_id=%s", mode, subject, session.get("id"))
        return

    if not token:
        return
    attempts = 0
    ok_count = 0
    failed_count = 0
    skipped_count = 0
    for row in sent_rows:
        tg = str(row.get("telegram_id") or "").strip()
        if not tg:
            skipped_count += 1
            continue
        attempts += 1
        try:
            if await _send_telegram_text(token, tg, message, button_text="Kirish", button_url=telegram_url if telegram_url.startswith("http") else None, button_web_app=True):
                ok_count += 1
            else:
                failed_count += 1
        except Exception:
            failed_count += 1
            logger.warning("competition available telegram failed session_id=%s user_id=%s", session.get("id"), row.get("id"))
        if attempts and attempts % 25 == 0:
            await asyncio.sleep(0.25)
    logger.info(
        "%s notifications session_id=%s mode=%s subject=%s attempted=%s sent=%s failed=%s skipped=%s web=%s",
        "duel same-subject" if is_duel else "competition available",
        session.get("id"),
        mode,
        subject,
        attempts,
        ok_count,
        failed_count,
        skipped_count,
        len(sent_rows),
    )


def _competition_session_phase(session: dict[str, Any]) -> str:
    status = str(session.get("status") or "pending")
    result = session.get("result") or {}
    if bool(session.get("finalized")) or result.get("by_user") or result.get("error") or result.get("refunded"):
        return "finished"
    if status in {"running", "active"}:
        return "active"
    if status in {"finished", "done", "cancelled", "expired"}:
        return "finished"
    if status == "generating":
        return "generating"
    return "pending"


def _competition_session_is_stale_for_switch(session: dict[str, Any], now: datetime | None = None) -> bool:
    """Return True for abandoned runtime rows that should not block a new selected mode/subject."""
    if not session:
        return True
    phase = _competition_session_phase(session)
    if phase == "generating" and _competition_reset_generation_to_pending_if_not_ready(session, int(session.get("stage") or 1) or 1):
        phase = "pending"
    if phase == "finished":
        return True
    now_dt = now or _now_utc()
    expires_at = _parse_utc_timestamp(str(session.get("expires_at") or ""))
    if expires_at and expires_at <= now_dt:
        return True
    created = _parse_utc_timestamp(str(session.get("created_at") or ""))
    started = _parse_utc_timestamp(str(session.get("started_at") or ""))
    ref = started or created
    if not ref:
        return False
    if phase in {"pending", "generating"}:
        return (now_dt - ref) > timedelta(minutes=25)
    if phase == "active":
        return (now_dt - ref) > timedelta(hours=2)
    return False


def _competition_detach_user_from_session(session: dict[str, Any], user_id: int, reason: str) -> None:
    """Detach only this user from a stale/mismatched session without touching payment calculations."""
    uid = int(user_id)
    phase = _competition_session_phase(session)
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) == uid:
            row["status"] = "left"
            row["left_at"] = _now_utc().isoformat()
            row["left_reason"] = str(reason or "session_switched")
            break
    WEB_DUEL_PLAYER_SESSION.pop(uid, None)
    if phase == "active":
        _competition_finish_user_remaining_questions(session, uid, reason=str(reason or "left_runtime"))
        _competition_finalize_if_all_progress_finished(session)
    if phase in {"pending", "generating"}:
        if _duel_is_mode(session.get("mode")):
            _duel_refund_user_fee(session, uid, reason)
        else:
            _competition_refund_user_entry_fee(session, uid, reason)
        if not _competition_waiting_participants(session):
            session["status"] = "finished"
            session["finalized"] = True
            session["finished_at"] = _now_utc().isoformat()
            session["cancel_reason"] = reason
            session["result"] = {"winners": [], "by_user": {}, "error": reason, "refunded": True}
            WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    _duel_persist_session(session)


def _competition_user_status_in_session(session: dict[str, Any], user_id: int) -> str:
    uid = int(user_id or 0)
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) == uid:
            return str(row.get("status") or "active").strip().lower() or "active"
    return ""


def _competition_user_left_or_blocked(session: dict[str, Any], user_id: int) -> bool:
    return _competition_user_status_in_session(session, user_id) in {
        "left",
        "cancelled",
        "finished",
        "eliminated",
        "blocked",
        "failed",
    }


def _competition_mark_user_left_by_proctoring(user_id: int, test_type: str | None, attempt_ref: str | None, reason: str | None = None) -> None:
    mode = str(test_type or "").strip()
    session_id = str(attempt_ref or "").strip()
    if mode not in {"daily", "group", "boss", "duel-1v1", "duel-3v3", "duel-5v5"} or not session_id:
        return
    with _competition_session_advisory_lock(session_id):
        session = _competition_load_session_from_db(session_id)
        if not session or _competition_session_phase(session) == "finished":
            return
        uid = int(user_id or 0)
        changed = False
        for row in session.get("participants") or []:
            if int(row.get("user_id") or 0) != uid:
                continue
            status = str(row.get("status") or "active").strip().lower()
            if status not in {"left", "cancelled", "finished", "eliminated", "blocked", "failed"}:
                row["status"] = "left"
                row["left_at"] = _now_utc().isoformat()
                row["left_reason"] = str(reason or "proctoring_failed")
                changed = True
            break
        if not changed:
            return
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        session["active_participants"] = [
            int(row)
            for row in (session.get("active_participants") or [])
            if int(row or 0) != uid
        ]
        session.setdefault("eliminated_participants", [])
        if uid not in [int(row or 0) for row in session.get("eliminated_participants") or []]:
            session["eliminated_participants"].append(uid)
        _competition_finish_user_remaining_questions(session, uid, reason=str(reason or "proctoring_failed"))
        _competition_finalize_if_all_progress_finished(session)
        _duel_persist_session(session)
    logger.info(
        "competition.proctoring_detach user_id=%s session_id=%s mode=%s reason=%s",
        uid,
        session_id,
        mode,
        str(reason or "proctoring_failed"),
    )


def _competition_joined_participants(session: dict[str, Any]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for row in session.get("participants") or []:
        uid = int(row.get("user_id") or 0)
        if uid <= 0:
            continue
        out.append(
            {
                "user_id": uid,
                "name": str(row.get("name") or f"Player {uid}"),
                "status": str(row.get("status") or "active"),
            }
        )
    return out


def _competition_waiting_participants(session: dict[str, Any]) -> list[dict[str, Any]]:
    inactive = {"left", "cancelled", "finished", "eliminated", "blocked", "failed"}
    return [
        row
        for row in _competition_joined_participants(session)
        if str(row.get("status") or "active").lower() not in inactive
    ]


def _competition_generation_ready(session: dict[str, Any], target_stage: int | None = None) -> bool:
    if not session:
        return False
    stage = int(target_stage or session.get("stage") or 1)
    if stage > 1 or session.get("started_at"):
        return True
    mode = str(session.get("mode") or "daily")
    required = max(1, int(session.get("required_players") or _competition_required_players(mode) or 1))
    joined = _competition_waiting_participants(session)
    return len(joined) >= required


def _competition_reset_generation_to_pending_if_not_ready(session: dict[str, Any], target_stage: int | None = None) -> bool:
    if not session or _competition_session_phase(session) != "generating":
        return False
    if _competition_generation_ready(session, target_stage):
        return False
    session["status"] = "pending"
    session["generation_started"] = False
    session["generation_percent"] = 0
    session["stage_generation_percent"] = 0
    session.pop("generation_token", None)
    session.pop("generation_task_stage", None)
    session.pop("generation_recovery_started_at", None)
    WEB_COMPETITION_PENDING_BY_KEY[str(session.get("queue_key") or "")] = str(session.get("id") or "")
    _duel_persist_session(session)
    return True


def _competition_prepare_generation(session: dict[str, Any], target_stage: int | None = None) -> str | None:
    """Move a lobby into generating only after the required active players are still present.

    Returns a one-shot generation token when this call should launch a worker.
    Returning None means either the lobby is not ready or another generation
    worker already owns the current stage.
    """
    if not session:
        return None
    mode = str(session.get("mode") or "")
    total_stages = _competition_total_stages(mode)
    stage = int(target_stage or (int(session.get("stage") or 0) + 1))
    if stage < 1:
        stage = 1
    if stage > total_stages:
        stage = total_stages
    phase = _competition_session_phase(session)
    if phase in {"active", "finished"}:
        return None
    if stage == 1 and not _competition_generation_ready(session, stage):
        if phase == "generating":
            _competition_reset_generation_to_pending_if_not_ready(session, stage)
        return None
    existing_token = str(session.get("generation_token") or "")
    existing_stage = int(session.get("generation_task_stage") or 0)
    if phase == "generating" and existing_token and existing_stage == stage:
        return None
    token = uuid4().hex
    session["status"] = "generating"
    session["generation_started"] = True
    session["generation_percent"] = max(5, int(session.get("generation_percent") or 0))
    session["stage_generation_percent"] = max(5, int(session.get("stage_generation_percent") or session.get("generation_percent") or 0))
    session["generation_token"] = token
    session["generation_task_stage"] = stage
    session["generation_recovery_started_at"] = _now_utc().isoformat()
    session["joined_count"] = len(_competition_waiting_participants(session))
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    _duel_persist_session(session)
    return token


def _competition_session_has_join_slot(session: dict[str, Any]) -> bool:
    if not session:
        return False
    _competition_reset_generation_to_pending_if_not_ready(session, int(session.get("stage") or 1) or 1)
    if _competition_session_phase(session) != "pending":
        return False
    if _competition_expire_waiting_session_if_needed(session):
        return False
    max_players = int(session.get("max_players") or session.get("required_players") or 1)
    return len(_competition_waiting_participants(session)) < max(1, max_players)


def _competition_user_is_participant(session: dict[str, Any], user_id: int) -> bool:
    for row in _competition_joined_participants(session):
        if int(row.get("user_id") or 0) == int(user_id):
            status = str(row.get("status") or "active").lower()
            if status not in {"left", "cancelled", "blocked", "failed"}:
                return True
    return False



_COMPETITION_TERMINAL_PARTICIPANT_STATUSES = {
    "cancelled",
    "finished",
    "eliminated",
    "blocked",
    "failed",
}
_COMPETITION_EXPLICIT_LEFT_REASONS = {
    "left_queue",
    "left_runtime",
    "switched_competition",
    "session_switched",
    "stale_session_switched",
    "proctoring_failed",
    "face_verification_failed",
    "manual_leave",
}
_COMPETITION_RESTORABLE_LEFT_REASONS = {
    "",
    "offline",
    "offline_timeout",
    "heartbeat_timeout",
    "connection_lost",
    "status_offline",
}


def _competition_participant_row(session: dict[str, Any], user_id: int) -> dict[str, Any] | None:
    uid = int(user_id or 0)
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) == uid:
            return row
    return None


def _competition_user_progress(session: dict[str, Any], user_id: int) -> dict[str, Any] | None:
    progress = session.get("progress") or {}
    uid = int(user_id)
    return progress.get(uid) or progress.get(str(uid))


def _competition_user_result(session: dict[str, Any], user_id: int) -> dict[str, Any] | None:
    uid = int(user_id)
    by_user = ((session.get("result") or {}).get("by_user") or {})
    return by_user.get(uid) or by_user.get(str(uid))


def _competition_restore_runtime_participant_if_needed(session: dict[str, Any], user_id: int, *, source: str = "") -> bool:
    """Recover users incorrectly marked left by old heartbeat/offline sweeping during active runtime."""
    if not session or _competition_session_phase(session) != "active":
        return False
    uid = int(user_id or 0)
    if uid <= 0 or _competition_user_result(session, uid):
        return False
    progress = _competition_user_progress(session, uid)
    if progress is None:
        return False
    row = _competition_participant_row(session, uid)
    if not row:
        return False
    status = str(row.get("status") or "active").strip().lower()
    if status not in {"left"}:
        return status not in _COMPETITION_TERMINAL_PARTICIPANT_STATUSES
    reason = str(row.get("left_reason") or row.get("reason") or "").strip().lower()
    if reason in _COMPETITION_EXPLICIT_LEFT_REASONS:
        return False
    if reason not in _COMPETITION_RESTORABLE_LEFT_REASONS:
        return False
    total = len(_competition_questions_for_user(session, uid))
    q_index = int(progress.get("index") or 1)
    if total <= 0 or q_index > total or progress.get("finished_at"):
        return False
    row["status"] = "active"
    row["recovered_at"] = _now_utc().isoformat()
    row["recovered_from_status"] = status
    row["recovered_from_reason"] = reason or "unknown"
    row.pop("left_at", None)
    row.pop("left_reason", None)
    if str(session.get("mode") or "") == "daily":
        active = {int(x) for x in (session.get("active_participants") or []) if int(x) > 0}
        active.add(uid)
        session["active_participants"] = sorted(active)
    WEB_DUEL_PLAYER_SESSION[uid] = str(session.get("id") or "")
    _duel_persist_session(session)
    logger.info(
        "competition.runtime participant restored user_id=%s session_id=%s source=%s reason=%s",
        uid,
        session.get("id"),
        source or "runtime",
        reason or "unknown",
    )
    return True


def _competition_runtime_user_has_access(session: dict[str, Any], user_id: int, *, source: str = "") -> bool:
    if _competition_user_is_participant(session, user_id):
        return True
    restored = _competition_restore_runtime_participant_if_needed(session, user_id, source=source)
    if restored:
        return True

    uid = int(user_id or 0)
    row = _competition_participant_row(session, uid)
    phase = _competition_session_phase(session)
    if not row:
        logger.warning(
            "competition.access_denied: user_id=%d is not in participants list of session_id=%s. Phase: %s. Source: %s. Participants: %s",
            uid, session.get("id"), phase, source, [p.get("user_id") for p in (session.get("participants") or [])]
        )
    else:
        logger.warning(
            "competition.access_denied: user_id=%d has terminal/left status in session_id=%s. Phase: %s. Status: %s. Reason: %s. Source: %s",
            uid, session.get("id"), phase, row.get("status"), row.get("left_reason") or row.get("reason"), source
        )
    return False


def _competition_finish_user_remaining_questions(session: dict[str, Any], user_id: int, *, reason: str = "left_runtime") -> bool:
    if not session or _competition_session_phase(session) != "active":
        return False
    uid = int(user_id or 0)
    progress = _competition_user_progress(session, uid)
    if not progress or progress.get("finished_at"):
        return False
    questions = _competition_questions_for_user(session, uid)
    total = len(questions)
    changed = False
    guard = 0
    while int(progress.get("index") or 1) <= total and guard < max(1, total + 2):
        guard += 1
        q_index = int(progress.get("index") or 1)
        q = questions[q_index - 1]
        timer_state = _competition_timer_state(session, uid, q_index, q, create=True)
        timer_state["time_remaining_sec"] = 0
        timer_state["skip_reason"] = reason
        if _competition_apply_question_outcome(session, uid, q_index, None, timer_state):
            changed = True
    if changed:
        progress["finished_at"] = progress.get("finished_at") or _now_utc().isoformat()
        _duel_persist_session(session)
    return changed


def _competition_finish_abandoned_session(session: dict[str, Any], reason: str) -> None:
    if not session or _competition_session_phase(session) == "finished":
        return
    now_iso = _now_utc().isoformat()
    phase = _competition_session_phase(session)
    if phase in {"pending", "generating"}:
        if _duel_is_mode(session.get("mode")):
            _duel_refund_pending_session(session, reason)
            return
        for uid in [int(x) for x in (session.get("charged_user_ids") or []) if int(x) > 0]:
            _competition_refund_user_entry_fee(session, uid, reason, force=True)
        for row in session.get("participants") or []:
            if str(row.get("status") or "active").lower() not in {"left", "cancelled", "finished", "eliminated", "blocked", "failed"}:
                row["status"] = "cancelled"
    session["status"] = "finished"
    session["finalized"] = True
    session["cancelled_at"] = now_iso
    session["finished_at"] = now_iso
    session["cancel_reason"] = reason
    session["result"] = {"winners": [], "by_user": {}, "tie": False, "error": reason, "refunded": phase in {"pending", "generating"}}
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    for row in _competition_joined_participants(session):
        WEB_DUEL_PLAYER_SESSION.pop(int(row.get("user_id") or 0), None)
    _duel_persist_session(session)


def _competition_session_unusable_for_matching(session: dict[str, Any] | None, now: datetime | None = None) -> bool:
    if not session:
        return True
    phase = _competition_session_phase(session)
    if phase == "finished":
        return True
    now_dt = now or _now_utc()
    if phase in {"pending", "generating"}:
        if _competition_expire_waiting_session_if_needed(session, now_dt):
            return True
        expires = _parse_utc_timestamp(str(session.get("expires_at") or ""))
        if expires and expires <= now_dt and not session.get("started_at"):
            _competition_finish_abandoned_session(session, "Queue expired")
            return True
        if not _competition_waiting_participants(session):
            _competition_finish_abandoned_session(session, "Queue empty")
            return True
        return False
    if phase in {"active", "running"}:
        started_at = _parse_utc_timestamp(str(session.get("started_at") or ""))
        if started_at and now_dt > started_at + timedelta(hours=2):
            _competition_finish_abandoned_session(session, "Match timeout")
            return True
        if not _competition_active_participant_ids(session):
            if started_at and now_dt <= started_at + timedelta(hours=2) and (session.get("progress") or {}):
                return False
            _competition_finish_abandoned_session(session, "No active participants")
            return True
    return False


def _competition_session_unusable_for_user(session: dict[str, Any] | None, user_id: int, now: datetime | None = None) -> bool:
    if _competition_session_unusable_for_matching(session, now):
        return True
    if not session:
        return True
    if _competition_restore_runtime_participant_if_needed(session, user_id, source="session_unusable_check"):
        return False
    if _competition_user_left_or_blocked(session, user_id):
        return True
    if _competition_user_result(session, user_id):
        return True
    return False


def _competition_result_participants(session: dict[str, Any]) -> list[dict[str, Any]]:
    result = session.get("result") or {}
    by_user = result.get("by_user") or {}
    winners = {int(uid) for uid in (result.get("winners") or []) if str(uid).strip().lstrip("-").isdigit()}
    rows: list[dict[str, Any]] = []
    for participant in _competition_joined_participants(session):
        uid = int(participant.get("user_id") or 0)
        if uid <= 0:
            continue
        own = by_user.get(uid) or by_user.get(str(uid)) or {}
        raw_status = str(participant.get("status") or "").strip().lower()
        result_status = str(own.get("result_status") or "").strip().lower()
        left = raw_status in {"left", "cancelled", "eliminated", "blocked", "failed"}
        winner = bool(own.get("winner")) or uid in winners
        rows.append(
            {
                "user_id": uid,
                "name": participant.get("name") or f"Player {uid}",
                "status": result_status or ("left" if left else "finished"),
                "winner": winner,
                "tie": bool(own.get("tie")),
                "left": left,
                "rank": own.get("rank"),
                "correct": int(own.get("correct") or 0),
                "wrong": int(own.get("wrong") or 0),
                "unanswered": int(own.get("unanswered") or own.get("skipped") or 0),
                "total_questions": int(own.get("total_questions") or len(_competition_questions_for_user(session, uid)) or 0),
                "dpoints_delta": float(own.get("dpoints_delta") or 0.0),
            }
        )
    rows.sort(
        key=lambda row: (
            0 if row.get("winner") else 1,
            1 if row.get("left") else 0,
            int(row.get("rank") or 9999),
            -int(row.get("correct") or 0),
            str(row.get("name") or ""),
        )
    )
    return rows


def _competition_questions_for_user(session: dict[str, Any], user_id: int | None = None) -> list[dict[str, Any]]:
    questions = list(session.get("questions") or [])
    if str(session.get("mode") or "") != "boss" or user_id is None:
        return questions
    assigned = session.get("participant_questions") or {}
    rows = assigned.get(str(int(user_id))) or assigned.get(int(user_id))
    return list(rows or questions[:5])


def _competition_active_participant_ids(session: dict[str, Any]) -> list[int]:
    mode = str(session.get("mode") or "")
    if mode != "daily":
        return [int(r.get("user_id") or 0) for r in _competition_waiting_participants(session) if int(r.get("user_id") or 0) > 0]
    ids = [int(uid) for uid in (session.get("active_participants") or []) if int(uid) > 0]
    if ids:
        return ids
    return [int(r.get("user_id") or 0) for r in _competition_joined_participants(session) if int(r.get("user_id") or 0) > 0]


def _competition_daily_stage_target(n0: int, stage: int) -> int:
    # Linearly cut the field from n0 down to the finalists target across the
    # non-final stages, so the final stage runs with exactly `finalists` players.
    if n0 <= 0:
        return 0
    finalists = _competition_finalists_target("daily") or 4
    if n0 <= finalists:
        return n0
    total_stages = _competition_total_stages("daily")
    denom = max(1, total_stages - 1)  # cuts happen over (total-1) stages -> reaches finalists at stage total-1
    raw = math.ceil(float(n0) - (float(stage) * float(n0 - finalists) / float(denom)))
    return max(finalists, int(raw))


def _competition_team_map(mode: str, player_ids: list[int]) -> dict[int, int]:
    teams: dict[int, int] = {}
    for idx, uid in enumerate(player_ids):
        if mode == "duel-1v1":
            teams[int(uid)] = 1 if idx == 0 else 2
        elif mode == "duel-3v3":
            teams[int(uid)] = 1 if idx < 3 else 2
        elif mode == "duel-5v5":
            teams[int(uid)] = 1 if idx < 5 else 2
        else:
            teams[int(uid)] = 1
    return teams


def _competition_stage_level(base_level: str, mode: str, stage: int) -> str:
    levels = ["BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED"]
    base = str(base_level or "PRE-INTERMEDIATE").strip().upper()
    if base not in levels:
        base = "PRE-INTERMEDIATE"
    if mode == "boss":
        return "UPPER-INTERMEDIATE" if base in {"INTERMEDIATE", "UPPER-INTERMEDIATE"} else "INTERMEDIATE"
    if mode != "daily":
        return base
    start_idx = levels.index(base)
    bump = max(0, int(stage or 1) - 1)
    return levels[min(len(levels) - 1, start_idx + bump)]


def _competition_rule_settings() -> dict[str, float]:
    settings = _get_runtime_settings()
    fallback_entry = float(settings.get("entry_fee_dcoin") or 3.0)
    return {
        "entry_fee_dcoin": max(0.0, fallback_entry),
        "arena_entry_fee_dcoin": max(0.0, float(settings.get("arena_entry_fee_dcoin") or fallback_entry)),
        "duel_entry_fee_dcoin": max(0.0, float(settings.get("duel_entry_fee_dcoin") or fallback_entry)),
        "duel_reward": float(settings.get("duel_reward") or settings.get("arena_reward") or 5.0),
        "duel_penalty": -abs(float(settings.get("duel_penalty") or 0.0)),
        "daily_arena_reward_first": max(0.0, float(settings.get("daily_arena_reward_first") or 25.0)),
        "daily_arena_reward_second": max(0.0, float(settings.get("daily_arena_reward_second") or 20.0)),
        "daily_arena_reward_third": max(0.0, float(settings.get("daily_arena_reward_third") or 15.0)),
        "group_arena_winner_reward": max(0.0, float(settings.get("group_arena_winner_reward") or 10.0)),
        "boss_arena_reward_per_correct": max(0.0, float(settings.get("boss_arena_reward_per_correct") or 3.0)),
        "boss_arena_global_threshold_percent": max(0.0, min(100.0, float(settings.get("boss_arena_global_threshold_percent") or 86.0))),
    }


def _competition_snapshot(session: dict[str, Any], user_id: int | None = None) -> dict[str, Any]:
    phase = _competition_session_phase(session)
    participants = _competition_waiting_participants(session) if phase in {"pending", "generating"} else _competition_joined_participants(session)
    required_players = int(session.get("required_players") or 1)
    max_players = max(required_players, int(session.get("max_players") or required_players))
    participants_count = len(participants)
    remaining_players = max(0, required_players - participants_count) if phase == "pending" else 0
    mode = str(session.get("mode") or "")
    now_dt = _now_utc()
    deadline = _competition_ensure_wait_deadline(session, now_dt) if phase == "pending" else None
    wait_remaining = max(0, int(math.ceil((deadline - now_dt).total_seconds()))) if deadline else None
    user_status = None
    if user_id is not None:
        for row in participants:
            if int(row.get("user_id") or 0) == int(user_id):
                user_status = str(row.get("status") or "active")
                break

    # Proctoring/FaceID removed: Arena/Duel flow is now lobby -> generating -> runtime.
    # There is no proctoring_check phase and no per-participant face verification gate.
    match_start_at = session.get("match_start_at")
    verified_count = participants_count
    proctoring_phase = None
    current_user_proctoring_status = "verified"
    proctoring_check_deadline = None
    generation_started_out = bool(session.get("generation_started")) and phase in {"generating", "active"}
    generation_percent_out = int(session.get("generation_percent") or 0) if generation_started_out else 0
    stage_generation_percent_out = int(session.get("stage_generation_percent") or session.get("generation_percent") or 0) if generation_started_out else 0

    payload: dict[str, Any] = {
        "session_id": str(session.get("id") or ""),
        "mode": session.get("mode"),
        "arena_type": session.get("mode"),
        "subject": session.get("subject"),
        "level": session.get("level"),
        "theme": session.get("theme"),
        "status": session.get("status"),
        "phase": phase,
        "required_players": required_players,
        "max_players": max_players,
        "participants_count": participants_count,
        "joined_count": participants_count,
        "remaining_players": remaining_players,
        "remaining_count": remaining_players,
        "participants": participants,
        "entry_fee": float(session.get("entry_fee") if session.get("entry_fee") is not None else _competition_entry_fee(mode)),
        "minimum_participants": required_players if mode in {"daily", "boss"} else None,
        "group_id": int(session.get("group_id") or 0) or None,
        "group_name": session.get("group_name"),
        "teacher_name": session.get("teacher_name"),
        "reward_settings": _competition_rule_settings(),
        "generation_started": generation_started_out,
        "generation_percent": generation_percent_out,
        "stage_generation_percent": stage_generation_percent_out,
        "stage": int(session.get("stage") or 0),
        "total_stages": int(session.get("total_stages") or _competition_total_stages(str(session.get("mode") or ""))),
        "finalists_target": int(session.get("finalists_target") or _competition_finalists_target(str(session.get("mode") or ""))),
        "initial_participants": int(session.get("initial_participants") or participants_count),
        "active_participants_count": len(_competition_active_participant_ids(session)),
        "eliminated_participants_count": len([int(uid) for uid in (session.get("eliminated_participants") or []) if int(uid) > 0]),
        "started_at": session.get("started_at") or session.get("created_at"),
        "first_joined_at": session.get("first_joined_at"),
        "last_joined_at": session.get("last_joined_at"),
        "wait_deadline_at": session.get("wait_deadline_at"),
        "lobby_deadline": session.get("wait_deadline_at"),
        "allowed_wait_seconds": COMPETITION_PENDING_WAIT_SECONDS if _competition_pending_uses_wait_timer(session) else None,
        "wait_seconds": COMPETITION_PENDING_WAIT_SECONDS if _competition_pending_uses_wait_timer(session) else None,
        "waiting_remaining_sec": wait_remaining,
        "seconds_left": wait_remaining,
        "server_now": now_dt.isoformat(),
        "can_start": bool(phase == "pending" and participants_count >= required_players),
        "user_joined": bool(user_status),
        "user_status": user_status,
        "refunded": bool((session.get("result") or {}).get("refunded")),
        "cancel_reason": session.get("cancel_reason") or (session.get("result") or {}).get("error"),
        "schedule_start": _competition_schedule_start(mode, str(session.get("subject") or "English")) if mode == "daily" else None,
        # New proctoring concurrency / fair start fields
        "proctoring_phase": proctoring_phase,
        "verified_count": verified_count,
        "required_verified": required_players,
        "proctoring_check_deadline": proctoring_check_deadline,
        "match_start_at": match_start_at,
        "current_user_proctoring_status": current_user_proctoring_status,
        "can_enter_runtime": bool(phase == "active"),
    }
    if mode == "daily":
        scores = []
        daily_scores = session.get("daily_scores") or {}
        scores_map = {}
        for k, v in daily_scores.items():
            try:
                scores_map[int(k)] = v
            except (ValueError, TypeError):
                pass
        for p in (session.get("participants") or []):
            p_uid = int(p.get("user_id") or 0)
            if p_uid <= 0:
                continue
            rec = scores_map.get(p_uid) or {}
            scores.append({
                "user_id": p_uid,
                "name": p.get("name") or "User",
                "status": p.get("status") or "active",
                "total_correct": int(rec.get("total_correct") or 0),
                "total_wrong": int(rec.get("total_wrong") or 0),
            })
        scores.sort(key=lambda x: (-x["total_correct"], x["total_wrong"], x["name"]))
        payload["daily_scoreboard"] = scores
    if user_id is not None:
        progress = _competition_user_progress(session, int(user_id)) or {}
        total = len(_competition_questions_for_user(session, int(user_id)))
        q_index = int(progress.get("index") or 1)
        payload["progress_percent"] = 100 if phase == "finished" else int(round(((q_index - 1) * 100 / max(1, total)))) if total else 0
        payload["question_index"] = min(max(1, q_index), max(1, total)) if total else 1
        payload["total_questions"] = total
        if phase == "finished":
            payload["result"] = _competition_user_result(session, int(user_id))
    return payload


def _duel_is_mode(mode: Any) -> bool:
    return str(mode or "").startswith("duel-")


def _json_default(value: Any) -> str:
    if isinstance(value, datetime):
        return value.isoformat()
    return str(value)


def _json_safe_runtime_value(value: Any) -> Any:
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, list):
        return [_json_safe_runtime_value(item) for item in value]
    if isinstance(value, tuple):
        return [_json_safe_runtime_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _json_safe_runtime_value(item) for key, item in value.items()}
    return value


def _duel_int_key_dict(value: Any) -> dict[int, Any]:
    if not isinstance(value, dict):
        return {}
    out: dict[int, Any] = {}
    for key, item in value.items():
        try:
            out[int(key)] = item
        except Exception:
            continue
    return out


def _duel_normalize_session(session: dict[str, Any]) -> dict[str, Any]:
    session["progress"] = {
        int(uid): (dict(row) if isinstance(row, dict) else {})
        for uid, row in _duel_int_key_dict(session.get("progress")).items()
    }
    session["teams"] = {
        int(uid): int(team or 1)
        for uid, team in _duel_int_key_dict(session.get("teams")).items()
    }
    result = dict(session.get("result") or {})
    result["by_user"] = {
        int(uid): (dict(row) if isinstance(row, dict) else {})
        for uid, row in _duel_int_key_dict(result.get("by_user")).items()
    }
    result["winners"] = [int(uid) for uid in (result.get("winners") or []) if str(uid).strip().lstrip("-").isdigit()]
    session["result"] = result
    for key in ("charged_user_ids", "refunded_user_ids", "active_participants", "eliminated_participants"):
        session[key] = [int(uid) for uid in (session.get(key) or []) if str(uid).strip().lstrip("-").isdigit()]
    participants: list[dict[str, Any]] = []
    for row in session.get("participants") or []:
        if not isinstance(row, dict):
            continue
        uid = int(row.get("user_id") or 0)
        if uid <= 0:
            continue
        item = dict(row)
        item["user_id"] = uid
        participants.append(item)
    session["participants"] = participants
    return _json_safe_runtime_value(session)


def _ensure_web_competition_runtime_schema() -> None:
    global WEB_COMPETITION_RUNTIME_SCHEMA_READY
    if WEB_COMPETITION_RUNTIME_SCHEMA_READY:
        return
    with WEB_COMPETITION_RUNTIME_SCHEMA_LOCK:
        if WEB_COMPETITION_RUNTIME_SCHEMA_READY:
            return
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_competition_sessions (
                    session_id TEXT PRIMARY KEY,
                    mode TEXT NOT NULL,
                    subject TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'pending',
                    group_id BIGINT,
                    required_players INTEGER DEFAULT 1,
                    max_players INTEGER DEFAULT 1,
                    entry_fee DOUBLE PRECISION DEFAULT 0,
                    queue_key TEXT,
                    payload_json TEXT NOT NULL DEFAULT '{}',
                    result_json TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    first_joined_at TIMESTAMP,
                    last_joined_at TIMESTAMP,
                    wait_deadline_at TIMESTAMP,
                    started_at TIMESTAMP,
                    finished_at TIMESTAMP,
                    expires_at TIMESTAMP,
                    cancelled_at TIMESTAMP,
                    cancel_reason TEXT
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_competition_participants (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    name TEXT,
                    team_no INTEGER DEFAULT 1,
                    status TEXT DEFAULT 'joined',
                    fee_charged DOUBLE PRECISION DEFAULT 0,
                    fee_refunded INTEGER DEFAULT 0,
                    joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    result_json TEXT,
                    UNIQUE(session_id, user_id)
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_competition_answers (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    question_index INTEGER NOT NULL,
                    selected_option_index INTEGER,
                    is_correct INTEGER DEFAULT 0,
                    is_unanswered INTEGER DEFAULT 0,
                    is_late INTEGER DEFAULT 0,
                    allowed_seconds INTEGER,
                    deadline_at TIMESTAMP,
                    answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(session_id, user_id, question_index)
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_competition_history (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    mode TEXT NOT NULL,
                    subject TEXT NOT NULL,
                    group_id BIGINT,
                    result_status TEXT NOT NULL,
                    rank INTEGER,
                    correct_count INTEGER DEFAULT 0,
                    wrong_count INTEGER DEFAULT 0,
                    skipped_count INTEGER DEFAULT 0,
                    total_questions INTEGER DEFAULT 0,
                    accuracy DOUBLE PRECISION DEFAULT 0,
                    entry_fee DOUBLE PRECISION DEFAULT 0,
                    fee_refunded INTEGER DEFAULT 0,
                    dpoints_delta DOUBLE PRECISION DEFAULT 0,
                    dcoin_delta DOUBLE PRECISION DEFAULT 0,
                    participants_json TEXT,
                    result_json TEXT,
                    started_at TIMESTAMP,
                    finished_at TIMESTAMP,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(session_id, user_id)
                )
                """
            )
            for sql in (
                "ALTER TABLE web_competition_sessions ADD COLUMN IF NOT EXISTS first_joined_at TIMESTAMP",
                "ALTER TABLE web_competition_sessions ADD COLUMN IF NOT EXISTS last_joined_at TIMESTAMP",
                "ALTER TABLE web_competition_sessions ADD COLUMN IF NOT EXISTS wait_deadline_at TIMESTAMP",
            ):
                cur.execute(sql)
            for sql in (
                "CREATE INDEX IF NOT EXISTS idx_web_comp_sessions_queue ON web_competition_sessions(queue_key, status, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_sessions_mode_status ON web_competition_sessions(mode, status, subject, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_sessions_wait_deadline ON web_competition_sessions(status, wait_deadline_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_participants_user ON web_competition_participants(user_id, status, joined_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_answers_session_user ON web_competition_answers(session_id, user_id)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_history_user_created ON web_competition_history(user_id, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_comp_history_mode_created ON web_competition_history(mode, created_at)",
            ):
                cur.execute(sql)
            conn.commit()
            WEB_COMPETITION_RUNTIME_SCHEMA_READY = True
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            logger.exception("web competition runtime schema ensure failed")
            raise
        finally:
            conn.close()


def _competition_persist_session_db(session: dict[str, Any] | None) -> None:
    if not session:
        return
    _ensure_web_competition_runtime_schema()
    session = _duel_normalize_session(session)
    sid = str(session.get("id") or "")
    if not sid:
        return
    result = session.get("result") if bool(session.get("finalized")) else None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_competition_sessions
            (session_id, mode, subject, status, group_id, required_players, max_players, entry_fee, queue_key, payload_json,
             result_json, created_at, first_joined_at, last_joined_at, wait_deadline_at, started_at, finished_at, expires_at, cancelled_at, cancel_reason)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id) DO UPDATE SET
                mode=excluded.mode,
                subject=excluded.subject,
                status=excluded.status,
                group_id=excluded.group_id,
                required_players=excluded.required_players,
                max_players=excluded.max_players,
                entry_fee=excluded.entry_fee,
                queue_key=excluded.queue_key,
                payload_json=excluded.payload_json,
                result_json=excluded.result_json,
                first_joined_at=excluded.first_joined_at,
                last_joined_at=excluded.last_joined_at,
                wait_deadline_at=excluded.wait_deadline_at,
                started_at=excluded.started_at,
                finished_at=excluded.finished_at,
                expires_at=excluded.expires_at,
                cancelled_at=excluded.cancelled_at,
                cancel_reason=excluded.cancel_reason
            """,
            (
                sid,
                str(session.get("mode") or ""),
                str(session.get("subject") or "English"),
                str(session.get("status") or "pending"),
                int(session.get("group_id") or 0) or None,
                int(session.get("required_players") or 1),
                int(session.get("max_players") or session.get("required_players") or 1),
                float(session.get("entry_fee") or 0.0),
                str(session.get("queue_key") or ""),
                json.dumps(session, ensure_ascii=False, default=_json_default),
                json.dumps(result or {}, ensure_ascii=False, default=_json_default) if result else None,
                session.get("created_at"),
                session.get("first_joined_at"),
                session.get("last_joined_at"),
                session.get("wait_deadline_at"),
                session.get("started_at"),
                session.get("finished_at"),
                session.get("expires_at"),
                session.get("cancelled_at"),
                session.get("cancel_reason"),
            ),
        )
        charged = {int(uid) for uid in (session.get("charged_user_ids") or []) if int(uid) > 0}
        refunded = {int(uid) for uid in (session.get("refunded_user_ids") or []) if int(uid) > 0}
        teams = session.get("teams") or {}
        by_user = (session.get("result") or {}).get("by_user") or {}
        for row in session.get("participants") or []:
            uid = int(row.get("user_id") or 0)
            if uid <= 0:
                continue
            cur.execute(
                """
                INSERT INTO web_competition_participants
                (session_id, user_id, name, team_no, status, fee_charged, fee_refunded, joined_at, result_json)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(session_id, user_id) DO UPDATE SET
                    name=excluded.name,
                    team_no=excluded.team_no,
                    status=excluded.status,
                    fee_charged=excluded.fee_charged,
                    fee_refunded=excluded.fee_refunded,
                    result_json=excluded.result_json
                """,
                (
                    sid,
                    uid,
                    str(row.get("name") or f"Player {uid}"),
                    int(teams.get(uid) or row.get("team_no") or 1),
                    str(row.get("status") or "active"),
                    float(session.get("entry_fee") or 0.0) if uid in charged else 0.0,
                    1 if uid in refunded else 0,
                    str(row.get("joined_at") or session.get("created_at") or _now_utc().isoformat()),
                    json.dumps(by_user.get(uid) or by_user.get(str(uid)) or {}, ensure_ascii=False, default=_json_default),
                ),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("competition session persist failed session_id=%s", sid)
    finally:
        conn.close()


def _competition_load_session_from_db(session_id: str) -> dict[str, Any] | None:
    _ensure_web_competition_runtime_schema()
    sid = str(session_id or "").strip()
    if not sid:
        return None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM web_competition_sessions WHERE session_id=? LIMIT 1", (sid,))
        row = cur.fetchone()
        if not row:
            return None
        data = _safe_json_object((row or {}).get("payload_json")) or {"id": sid}
        data["id"] = sid
        for key in ("mode", "subject", "status", "queue_key", "created_at", "first_joined_at", "last_joined_at", "wait_deadline_at", "started_at", "finished_at", "expires_at", "cancelled_at", "cancel_reason"):
            if (row or {}).get(key) is not None:
                data[key] = (row or {}).get(key)
        data["required_players"] = int((row or {}).get("required_players") or data.get("required_players") or 1)
        data["max_players"] = int((row or {}).get("max_players") or data.get("max_players") or data["required_players"])
        data["entry_fee"] = float((row or {}).get("entry_fee") or data.get("entry_fee") or 0.0)
        if (row or {}).get("group_id") is not None:
            data["group_id"] = int((row or {}).get("group_id") or 0)
        result_json = _safe_json_object((row or {}).get("result_json"))
        if result_json:
            data["result"] = result_json
            data["finalized"] = True
        cur.execute("SELECT * FROM web_competition_participants WHERE session_id=? ORDER BY joined_at ASC, id ASC", (sid,))
        part_rows = [dict(r) for r in (cur.fetchall() or [])]
        if part_rows:
            payload_participants = {
                int(p.get("user_id") or 0): dict(p)
                for p in (data.get("participants") or [])
                if isinstance(p, dict) and int(p.get("user_id") or 0) > 0
            }
            participants: list[dict[str, Any]] = []
            for r in part_rows:
                uid = int(r.get("user_id") or 0)
                if uid <= 0:
                    continue
                item = dict(payload_participants.get(uid) or {})
                item.update(
                    {
                        "user_id": uid,
                        "name": str(r.get("name") or item.get("name") or f"Player {uid}"),
                        "status": str(r.get("status") or item.get("status") or "active"),
                        "team_no": int(r.get("team_no") or item.get("team_no") or 1),
                        "joined_at": r.get("joined_at") or item.get("joined_at"),
                    }
                )
                participants.append(item)
            data["participants"] = participants
            data["charged_user_ids"] = [int(r.get("user_id") or 0) for r in part_rows if float(r.get("fee_charged") or 0) > 0]
            data["refunded_user_ids"] = [int(r.get("user_id") or 0) for r in part_rows if int(r.get("fee_refunded") or 0) == 1]
            data.setdefault("teams", {})
            for r in part_rows:
                uid = int(r.get("user_id") or 0)
                if uid > 0:
                    data["teams"][uid] = int(r.get("team_no") or data.get("teams", {}).get(uid) or 1)
                    
        # Reconstruct progress from web_competition_answers to prevent stale cache overwrites
        if data.get("progress"):
            cur.execute("SELECT user_id, question_index, is_correct, is_unanswered FROM web_competition_answers WHERE session_id=? ORDER BY question_index ASC", (sid,))
            answers = [dict(a) for a in cur.fetchall() or []]
            if answers:
                for pid in data["progress"]:
                    try:
                        uid = int(pid)
                    except Exception:
                        continue
                    user_answers = [a for a in answers if int(a.get("user_id") or 0) == uid]
                    if not user_answers:
                        continue
                    correct = sum(1 for a in user_answers if int(a.get("is_correct") or 0))
                    unanswered = sum(1 for a in user_answers if int(a.get("is_unanswered") or 0))
                    wrong = len(user_answers) - correct - unanswered
                    max_idx = max(int(a.get("question_index") or 0) for a in user_answers)
                    if isinstance(data["progress"][pid], dict):
                        data["progress"][pid]["correct"] = correct
                        data["progress"][pid]["wrong"] = wrong
                        data["progress"][pid]["unanswered"] = unanswered
                        data["progress"][pid]["index"] = max_idx + 1
                        
        return _duel_cache_session(data)
    except Exception:
        logger.exception("competition session load failed session_id=%s", sid)
        return None
    finally:
        conn.close()


def _competition_load_active_session_for_user(user_id: int) -> dict[str, Any] | None:
    _ensure_web_competition_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT s.session_id
            FROM web_competition_sessions s
            JOIN web_competition_participants p ON p.session_id=s.session_id
            WHERE p.user_id=?
              AND s.status IN ('pending', 'generating', 'running', 'active')
              AND (
                COALESCE(p.status, 'joined') NOT IN ('left', 'cancelled', 'finished', 'eliminated', 'blocked', 'failed')
                OR (s.status IN ('running', 'active') AND COALESCE(p.status, '')='left')
              )
            ORDER BY p.joined_at DESC
            LIMIT 10
            """,
            (int(user_id),),
        )
        for row in cur.fetchall() or []:
            session = _competition_load_session_from_db(str(row.get("session_id") or ""))
            if not session:
                continue
            if _competition_session_unusable_for_user(session, user_id):
                continue
            return session
        return None
    finally:
        conn.close()


def _competition_find_pending_session(queue_key: str) -> dict[str, Any] | None:
    _ensure_web_competition_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT session_id
            FROM web_competition_sessions
            WHERE queue_key=? AND status='pending'
            ORDER BY created_at ASC
            LIMIT 10
            """,
            (str(queue_key),),
        )
        for row in cur.fetchall() or []:
            session = _competition_load_session_from_db(str(row.get("session_id") or ""))
            if _competition_session_unusable_for_matching(session):
                continue
            if _competition_session_has_join_slot(session):
                return session
        return None
    finally:
        conn.close()


def _competition_load_group_runtime_session(group_id: int, legacy_session_id: int | None = None) -> dict[str, Any] | None:
    _ensure_web_competition_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT session_id
            FROM web_competition_sessions
            WHERE mode='group'
              AND group_id=?
              AND status IN ('pending', 'generating', 'running', 'active')
            ORDER BY created_at DESC
            LIMIT 10
            """,
            (int(group_id),),
        )
        rows = cur.fetchall() or []
    finally:
        conn.close()
    for row in rows:
        session = _competition_load_session_from_db(str(row.get("session_id") or ""))
        if not session:
            continue
        if not legacy_session_id or int(session.get("external_group_arena_session_id") or 0) == int(legacy_session_id):
            return session
    return None


def _auto_close_stale_arena_group_session(sess: dict[str, Any] | None, *, hours: int = 3) -> dict[str, Any] | None:
    """
    A `ready`/`sent`/`running` `arena_group_sessions` row that outlives a
    single lesson (default 3h) AND has no live runtime counterpart is
    almost certainly abandoned — the teacher closed the app, the backend
    restarted mid-session and lost the in-memory/DB runtime row, or a
    student's device dropped the connection before
    `distribute_arena_group_rewards_if_ready` ever saw everyone finish.
    Previously this was only swept reactively, once, inside `/start` with
    a 48h grace window — meaning `/status` (and therefore the
    Flutter/teacher-app polling loop) kept reporting a dead session as
    "active" indefinitely, and a teacher who never tried to start ANOTHER
    session for that same group would see the stuck session forever. This
    closes it proactively wherever a session is read (`/status`, `/start`)
    with a much tighter, lesson-length window — but only when there's also
    no live `web_competition_sessions` row backing it, so a genuinely long
    (but still active) session is never force-closed under a teacher.
    """
    if not sess:
        return sess
    created_at_dt = _parse_utc_timestamp(str(sess.get("created_at") or ""))
    if not created_at_dt:
        return sess
    now = _now_utc()
    gid = int(sess.get("group_id") or 0)

    # Preferred cutoff: exactly 1 hour after the group's scheduled lesson
    # end on the session's creation date — a group arena the teacher forgot
    # to end must not outlive the lesson by more than an hour. Falls back to
    # "hours after creation" when the group's lesson_end isn't known.
    cutoff = created_at_dt + timedelta(hours=hours)
    if gid > 0:
        group = _safe_call(lambda: get_group(gid), None)
        end_hhmm = _parse_hhmm((group or {}).get("lesson_end"))
        if end_hhmm:
            created_local = created_at_dt.astimezone(TASHKENT_TZ)
            lesson_end_local = created_local.replace(
                hour=end_hhmm[0], minute=end_hhmm[1], second=0, microsecond=0
            )
            # Guard against a session created after that day's lesson_end
            # (late start) yielding a cutoff already in the past at creation.
            if lesson_end_local < created_local:
                lesson_end_local = created_local
            cutoff = (lesson_end_local + timedelta(hours=1)).astimezone(timezone.utc)

    if now <= cutoff:
        return sess
    sid = int(sess.get("id") or 0)
    # Never force-close a session that still has a live runtime backing it —
    # a genuinely long (but active) game under a teacher is left alone.
    live = _safe_call(lambda: _competition_load_group_runtime_session(gid, sid), None) if gid > 0 else None
    if live:
        return sess
    _safe_call(lambda: _mark_legacy_group_arena_completed(sid), None)
    return None


def _mark_legacy_group_arena_completed(session_id: int) -> None:
    if int(session_id or 0) <= 0:
        return
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE arena_group_sessions
            SET status='completed',
                rewards_distributed=1,
                completed_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (int(session_id),),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("Failed to mark legacy group arena completed session_id=%s", session_id)
    finally:
        conn.close()


def _latest_legacy_group_arena_session(group_id: int) -> dict[str, Any] | None:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, group_id, subject, level, question_count, bank_ids_json, created_by_teacher_id,
                   expected_players, rewards_distributed, status, created_at, completed_at
            FROM arena_group_sessions
            WHERE group_id=?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (int(group_id),),
        )
        row = cur.fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def _competition_persist_answer_db(
    session: dict[str, Any],
    user_id: int,
    question_index: int,
    selected: int | None,
    *,
    is_correct: bool,
    is_unanswered: bool,
    is_late: bool,
    timer_state: dict[str, Any],
) -> None:
    _ensure_web_competition_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_competition_answers
            (session_id, user_id, question_index, selected_option_index, is_correct, is_unanswered, is_late,
             allowed_seconds, deadline_at, answered_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id, user_id, question_index) DO UPDATE SET
                selected_option_index=excluded.selected_option_index,
                is_correct=excluded.is_correct,
                is_unanswered=excluded.is_unanswered,
                is_late=excluded.is_late,
                allowed_seconds=excluded.allowed_seconds,
                deadline_at=excluded.deadline_at,
                answered_at=excluded.answered_at
            """,
            (
                str(session.get("id") or ""),
                int(user_id),
                int(question_index),
                None if selected is None else int(selected),
                1 if is_correct else 0,
                1 if is_unanswered else 0,
                1 if is_late else 0,
                int(timer_state.get("allowed_seconds") or COMPETITION_WEB_SECONDS),
                timer_state.get("deadline_at"),
                _now_utc().isoformat(),
            ),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("competition answer persist failed session_id=%s user_id=%s", session.get("id"), user_id)
    finally:
        conn.close()

def _boss_arena_has_received_reward(session_id: str, user_id: int) -> bool:
    if not session_id or not user_id:
        return False
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "SELECT 1 FROM web_competition_history WHERE session_id=? AND user_id=? LIMIT 1",
            (session_id, int(user_id)),
        )
        return bool(cur.fetchone())
    except Exception:
        return False
    finally:
        conn.close()


def _competition_save_history(session: dict[str, Any]) -> None:
    if not bool(session.get("finalized")):
        return
    _ensure_web_competition_runtime_schema()
    result = session.get("result") or {}
    by_user = result.get("by_user") or {}
    participants = _competition_joined_participants(session)
    total = max(0, len(session.get("questions") or []))
    if str(session.get("mode") or "") == "boss":
        assigned = session.get("participant_questions") or {}
        total = max(0, max((len(v or []) for v in assigned.values()), default=total))
    ranking = result.get("ranking") or []
    rank_by_user = {int(row.get("user_id") or 0): int(row.get("rank") or 0) for row in ranking if int(row.get("user_id") or 0) > 0}
    participants_json = json.dumps(participants, ensure_ascii=False, default=_json_default)
    conn = get_conn()
    cur = conn.cursor()
    try:
        charged_user_ids = {int(x) for x in (session.get("charged_user_ids") or []) if str(x).strip().lstrip("-").isdigit()}
        refunded_user_ids = {int(x) for x in (session.get("refunded_user_ids") or []) if str(x).strip().lstrip("-").isdigit()}
        for row in participants:
            uid = int(row.get("user_id") or 0)
            if uid <= 0:
                continue
            own = by_user.get(uid) or by_user.get(str(uid)) or {}
            correct = int(own.get("correct") or 0)
            wrong = int(own.get("wrong") or 0)
            skipped = int(own.get("unanswered") or own.get("skipped") or 0)
            total_q = int(own.get("total_questions") or total or max(1, correct + wrong + skipped))
            rank = int(own.get("rank") or rank_by_user.get(uid) or 0) or None
            status = str(own.get("result_status") or ("tie" if own.get("tie") else "win" if own.get("winner") else "lose"))
            accuracy = round((correct * 100.0) / max(1, total_q), 2)
            cur.execute(
                """
                INSERT INTO web_competition_history
                (session_id, user_id, mode, subject, group_id, result_status, rank, correct_count, wrong_count, skipped_count,
                 total_questions, accuracy, entry_fee, fee_refunded, dpoints_delta, dcoin_delta, participants_json, result_json,
                 started_at, finished_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(session_id, user_id) DO UPDATE SET
                    result_status=excluded.result_status,
                    rank=excluded.rank,
                    correct_count=excluded.correct_count,
                    wrong_count=excluded.wrong_count,
                    skipped_count=excluded.skipped_count,
                    total_questions=excluded.total_questions,
                    accuracy=excluded.accuracy,
                    entry_fee=excluded.entry_fee,
                    fee_refunded=excluded.fee_refunded,
                    dpoints_delta=excluded.dpoints_delta,
                    dcoin_delta=excluded.dcoin_delta,
                    participants_json=excluded.participants_json,
                    result_json=excluded.result_json,
                    started_at=excluded.started_at,
                    finished_at=excluded.finished_at
                """,
                (
                    str(session.get("id") or ""),
                    uid,
                    str(session.get("mode") or ""),
                    str(session.get("subject") or "English"),
                    int(session.get("group_id") or 0) or None,
                    status,
                    rank,
                    correct,
                    wrong,
                    skipped,
                    total_q,
                    accuracy,
                    float(session.get("entry_fee") or 0.0) if uid in charged_user_ids else 0.0,
                    1 if uid in refunded_user_ids else 0,
                    float(own.get("dpoints_delta") or 0.0),
                    float(own.get("dcoin") or 0.0),
                    participants_json,
                    json.dumps(own, ensure_ascii=False, default=_json_default),
                    session.get("started_at"),
                    session.get("finished_at") or _now_utc().isoformat(),
                ),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("competition history save failed session_id=%s", session.get("id"))
        raise
    finally:
        conn.close()


def _competition_history_for_user(user_id: int, mode: str | None = None, limit: int = 20) -> list[dict[str, Any]]:
    _ensure_web_competition_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        args: list[Any] = [int(user_id)]
        where = "WHERE user_id=?"
        if mode:
            where += " AND mode=?"
            args.append(str(mode))
        args.append(max(1, min(50, int(limit or 20))))
        cur.execute(
            f"""
            SELECT *
            FROM web_competition_history
            {where}
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            tuple(args),
        )
        rows = []
        for row in cur.fetchall() or []:
            item = dict(row)
            item["participants"] = _safe_json_array(item.pop("participants_json", None))
            item["result"] = _safe_json_object(item.pop("result_json", None))
            item["type"] = item.get("mode")
            item["correct"] = item.get("correct_count")
            item["wrong"] = item.get("wrong_count")
            item["skipped"] = item.get("skipped_count")
            item["reward_dpoints"] = item.get("dpoints_delta")
            item["dcoin_fee"] = item.get("entry_fee")
            item["tie"] = str(item.get("result_status") or "").lower() == "tie" or bool((item.get("result") or {}).get("tie"))
            rows.append(item)
        return rows
    finally:
        conn.close()


def _duel_cache_session(session: dict[str, Any]) -> dict[str, Any]:
    session = _duel_normalize_session(session)
    sid = str(session.get("id") or "")
    if not sid:
        return session
    WEB_COMPETITION_SESSIONS[sid] = session
    phase = _competition_session_phase(session)
    queue_key = str(session.get("queue_key") or "")
    if queue_key and phase == "pending":
        WEB_COMPETITION_PENDING_BY_KEY[queue_key] = sid
    for row in _competition_waiting_participants(session):
        uid = int(row.get("user_id") or 0)
        if uid > 0 and phase in {"pending", "generating", "active"}:
            WEB_DUEL_PLAYER_SESSION[uid] = sid
    return session


def _ensure_web_duel_runtime_schema() -> None:
    global WEB_DUEL_RUNTIME_SCHEMA_READY
    if WEB_DUEL_RUNTIME_SCHEMA_READY:
        return
    with WEB_DUEL_RUNTIME_SCHEMA_LOCK:
        if WEB_DUEL_RUNTIME_SCHEMA_READY:
            return
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_duel_sessions (
                    session_id TEXT PRIMARY KEY,
                    mode TEXT NOT NULL,
                    subject TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'pending',
                    required_players INTEGER DEFAULT 2,
                    max_players INTEGER DEFAULT 2,
                    entry_fee DOUBLE PRECISION DEFAULT 0,
                    queue_key TEXT,
                    payload_json TEXT NOT NULL DEFAULT '{}',
                    result_json TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    first_joined_at TIMESTAMP,
                    last_joined_at TIMESTAMP,
                    wait_deadline_at TIMESTAMP,
                    started_at TIMESTAMP,
                    finished_at TIMESTAMP,
                    expires_at TIMESTAMP,
                    cancelled_at TIMESTAMP,
                    cancel_reason TEXT
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_duel_participants (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    name TEXT,
                    team_no INTEGER DEFAULT 1,
                    status TEXT DEFAULT 'joined',
                    fee_charged DOUBLE PRECISION DEFAULT 0,
                    fee_refunded INTEGER DEFAULT 0,
                    joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    result_json TEXT,
                    UNIQUE(session_id, user_id)
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_duel_answers (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    question_index INTEGER NOT NULL,
                    selected_option_index INTEGER,
                    is_correct INTEGER DEFAULT 0,
                    is_unanswered INTEGER DEFAULT 0,
                    is_late INTEGER DEFAULT 0,
                    allowed_seconds INTEGER,
                    deadline_at TIMESTAMP,
                    answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(session_id, user_id, question_index)
                )
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS web_duel_history (
                    id BIGSERIAL PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    user_id BIGINT NOT NULL,
                    mode TEXT NOT NULL,
                    subject TEXT NOT NULL,
                    team_no INTEGER,
                    result_status TEXT NOT NULL,
                    correct_count INTEGER DEFAULT 0,
                    wrong_count INTEGER DEFAULT 0,
                    skipped_count INTEGER DEFAULT 0,
                    total_questions INTEGER DEFAULT 0,
                    winner_user_id BIGINT,
                    winner_team INTEGER,
                    tie INTEGER DEFAULT 0,
                    entry_fee DOUBLE PRECISION DEFAULT 0,
                    fee_refunded INTEGER DEFAULT 0,
                    dpoints_delta DOUBLE PRECISION DEFAULT 0,
                    dcoin_delta DOUBLE PRECISION DEFAULT 0,
                    participants_json TEXT,
                    result_json TEXT,
                    started_at TIMESTAMP,
                    finished_at TIMESTAMP,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(session_id, user_id)
                )
                """
            )
            for sql in (
                "ALTER TABLE web_duel_sessions ADD COLUMN IF NOT EXISTS first_joined_at TIMESTAMP",
                "ALTER TABLE web_duel_sessions ADD COLUMN IF NOT EXISTS last_joined_at TIMESTAMP",
                "ALTER TABLE web_duel_sessions ADD COLUMN IF NOT EXISTS wait_deadline_at TIMESTAMP",
            ):
                cur.execute(sql)
            for sql in (
                "CREATE INDEX IF NOT EXISTS idx_web_duel_sessions_queue ON web_duel_sessions(queue_key, status, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_duel_sessions_status ON web_duel_sessions(status, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_duel_sessions_wait_deadline ON web_duel_sessions(status, wait_deadline_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_duel_participants_user ON web_duel_participants(user_id, status, joined_at)",
                "CREATE INDEX IF NOT EXISTS idx_web_duel_answers_session_user ON web_duel_answers(session_id, user_id)",
                "CREATE INDEX IF NOT EXISTS idx_web_duel_history_user_created ON web_duel_history(user_id, created_at)",
            ):
                cur.execute(sql)
            conn.commit()
            WEB_DUEL_RUNTIME_SCHEMA_READY = True
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            logger.exception("web duel runtime schema ensure failed")
            raise
        finally:
            conn.close()


def _duel_persist_session(session: dict[str, Any] | None) -> None:
    if not session:
        return
    _competition_persist_session_db(session)
    if not _duel_is_mode(session.get("mode")):
        return
    _ensure_web_duel_runtime_schema()
    session = _duel_normalize_session(session)
    sid = str(session.get("id") or "")
    if not sid:
        return
    now_iso = _now_utc().isoformat()
    result = session.get("result") if bool(session.get("finalized")) else None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_duel_sessions
            (session_id, mode, subject, status, required_players, max_players, entry_fee, queue_key, payload_json,
             result_json, created_at, first_joined_at, last_joined_at, wait_deadline_at, started_at, finished_at, expires_at, cancelled_at, cancel_reason)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id) DO UPDATE SET
                mode=excluded.mode,
                subject=excluded.subject,
                status=excluded.status,
                required_players=excluded.required_players,
                max_players=excluded.max_players,
                entry_fee=excluded.entry_fee,
                queue_key=excluded.queue_key,
                payload_json=excluded.payload_json,
                result_json=excluded.result_json,
                first_joined_at=excluded.first_joined_at,
                last_joined_at=excluded.last_joined_at,
                wait_deadline_at=excluded.wait_deadline_at,
                started_at=excluded.started_at,
                finished_at=excluded.finished_at,
                expires_at=excluded.expires_at,
                cancelled_at=excluded.cancelled_at,
                cancel_reason=excluded.cancel_reason
            """,
            (
                sid,
                str(session.get("mode") or ""),
                str(session.get("subject") or "English"),
                str(session.get("status") or "pending"),
                int(session.get("required_players") or 2),
                int(session.get("max_players") or session.get("required_players") or 2),
                float(session.get("entry_fee") or 0.0),
                str(session.get("queue_key") or ""),
                json.dumps(session, ensure_ascii=False, default=_json_default),
                json.dumps(result or {}, ensure_ascii=False, default=_json_default) if result else None,
                str(session.get("created_at") or now_iso),
                session.get("first_joined_at"),
                session.get("last_joined_at"),
                session.get("wait_deadline_at"),
                session.get("started_at"),
                session.get("finished_at"),
                session.get("expires_at"),
                session.get("cancelled_at"),
                session.get("cancel_reason"),
            ),
        )
        charged = {int(uid) for uid in (session.get("charged_user_ids") or []) if int(uid) > 0}
        refunded = {int(uid) for uid in (session.get("refunded_user_ids") or []) if int(uid) > 0}
        teams = session.get("teams") or {}
        by_user = (session.get("result") or {}).get("by_user") or {}
        for row in session.get("participants") or []:
            uid = int(row.get("user_id") or 0)
            if uid <= 0:
                continue
            team_no = int(teams.get(uid) or row.get("team_no") or 1)
            cur.execute(
                """
                INSERT INTO web_duel_participants
                (session_id, user_id, name, team_no, status, fee_charged, fee_refunded, joined_at, result_json)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(session_id, user_id) DO UPDATE SET
                    name=excluded.name,
                    team_no=excluded.team_no,
                    status=excluded.status,
                    fee_charged=excluded.fee_charged,
                    fee_refunded=excluded.fee_refunded,
                    result_json=excluded.result_json
                """,
                (
                    sid,
                    uid,
                    str(row.get("name") or f"Player {uid}"),
                    team_no,
                    str(row.get("status") or "active"),
                    float(session.get("entry_fee") or 0.0) if uid in charged else 0.0,
                    1 if uid in refunded else 0,
                    str(row.get("joined_at") or session.get("created_at") or now_iso),
                    json.dumps(by_user.get(uid) or by_user.get(str(uid)) or {}, ensure_ascii=False, default=_json_default),
                ),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("duel session persist failed session_id=%s", sid)
    finally:
        conn.close()


def _duel_load_session_from_db(session_id: str) -> dict[str, Any] | None:
    _ensure_web_duel_runtime_schema()
    sid = str(session_id or "").strip()
    if not sid:
        return None
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM web_duel_sessions WHERE session_id=? LIMIT 1", (sid,))
        row = cur.fetchone()
        if not row:
            return None
        data = _safe_json_object((row or {}).get("payload_json"))
        if not data:
            data = {"id": sid}
        data["id"] = sid
        data["mode"] = str((row or {}).get("mode") or data.get("mode") or "")
        data["subject"] = str((row or {}).get("subject") or data.get("subject") or "English")
        data["status"] = str((row or {}).get("status") or data.get("status") or "pending")
        data["required_players"] = int((row or {}).get("required_players") or data.get("required_players") or 2)
        data["max_players"] = int((row or {}).get("max_players") or data.get("max_players") or data["required_players"])
        data["entry_fee"] = float((row or {}).get("entry_fee") or data.get("entry_fee") or 0.0)
        data["queue_key"] = str((row or {}).get("queue_key") or data.get("queue_key") or "")
        for key in ("created_at", "first_joined_at", "last_joined_at", "wait_deadline_at", "started_at", "finished_at", "expires_at", "cancelled_at", "cancel_reason"):
            if (row or {}).get(key) is not None:
                data[key] = (row or {}).get(key)
        result_json = _safe_json_object((row or {}).get("result_json"))
        if result_json:
            data["result"] = result_json
            data["finalized"] = True
        cur.execute("SELECT * FROM web_duel_participants WHERE session_id=? ORDER BY joined_at ASC, id ASC", (sid,))
        part_rows = [dict(r) for r in (cur.fetchall() or [])]
        if part_rows:
            payload_participants = {
                int(p.get("user_id") or 0): dict(p)
                for p in (data.get("participants") or [])
                if isinstance(p, dict) and int(p.get("user_id") or 0) > 0
            }
            participants: list[dict[str, Any]] = []
            for r in part_rows:
                uid = int(r.get("user_id") or 0)
                if uid <= 0:
                    continue
                item = dict(payload_participants.get(uid) or {})
                item.update(
                    {
                        "user_id": uid,
                        "name": str(r.get("name") or item.get("name") or f"Player {uid}"),
                        "status": str(r.get("status") or item.get("status") or "active"),
                        "team_no": int(r.get("team_no") or item.get("team_no") or 1),
                        "joined_at": r.get("joined_at") or item.get("joined_at"),
                    }
                )
                participants.append(item)
            data["participants"] = participants
            data["charged_user_ids"] = [int(r.get("user_id") or 0) for r in part_rows if float(r.get("fee_charged") or 0) > 0]
            data["refunded_user_ids"] = [int(r.get("user_id") or 0) for r in part_rows if int(r.get("fee_refunded") or 0) == 1]
            data.setdefault("teams", {})
            for r in part_rows:
                uid = int(r.get("user_id") or 0)
                if uid > 0:
                    data["teams"][uid] = int(r.get("team_no") or data.get("teams", {}).get(uid) or 1)
        return _duel_cache_session(data)
    except Exception:
        logger.exception("duel session load failed session_id=%s", sid)
        return None
    finally:
        conn.close()


def _duel_load_active_session_for_user(user_id: int) -> dict[str, Any] | None:
    _ensure_web_duel_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT s.session_id
            FROM web_duel_sessions s
            JOIN web_duel_participants p ON p.session_id=s.session_id
            WHERE p.user_id=?
              AND s.status IN ('pending', 'generating', 'running', 'active')
              AND COALESCE(p.status, 'joined') NOT IN ('left', 'cancelled', 'finished', 'eliminated', 'blocked', 'failed')
            ORDER BY p.joined_at DESC
            LIMIT 10
            """,
            (int(user_id),),
        )
        for row in cur.fetchall() or []:
            session = _duel_load_session_from_db(str(row.get("session_id") or ""))
            if not session:
                continue
            if _competition_session_unusable_for_user(session, user_id):
                continue
            return session
        return None
    finally:
        conn.close()


def _duel_find_pending_session(queue_key: str) -> dict[str, Any] | None:
    _ensure_web_duel_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT session_id, expires_at
            FROM web_duel_sessions
            WHERE queue_key=? AND status='pending'
            ORDER BY created_at ASC
            LIMIT 10
            """,
            (str(queue_key),),
        )
        now_dt = _now_utc()
        for row in cur.fetchall() or []:
            session = _duel_load_session_from_db(str((row or {}).get("session_id") or ""))
            if _competition_session_unusable_for_matching(session, now_dt):
                continue
            if session and _competition_session_has_join_slot(session):
                return session
        return None
    finally:
        conn.close()


def _duel_decrement_daily_usage(user_id: int, mode: str, usage_date: str) -> None:
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            UPDATE duel_daily_usage
            SET plays=CASE WHEN plays > 0 THEN plays - 1 ELSE 0 END
            WHERE user_id=? AND usage_date=? AND mode=?
            """,
            (int(user_id), str(usage_date), str(mode)),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("duel daily usage decrement failed user_id=%s mode=%s", user_id, mode)
    finally:
        conn.close()


def _duel_usage_date_for_user(session: dict[str, Any], user_id: int) -> str:
    usage_dates = session.setdefault("usage_dates", {})
    raw = usage_dates.get(str(int(user_id))) or usage_dates.get(int(user_id))
    if raw:
        return str(raw)
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) != int(user_id):
            continue
        row_usage = str(row.get("usage_date") or "").strip()
        if row_usage:
            usage_dates[str(int(user_id))] = row_usage
            return row_usage
        joined_at = _parse_utc_timestamp(str(row.get("joined_at") or ""))
        if joined_at:
            usage_date = joined_at.astimezone(TASHKENT_TZ).strftime("%Y-%m-%d")
            row["usage_date"] = usage_date
            usage_dates[str(int(user_id))] = usage_date
            return usage_date
    return _now_tashkent_date()


def _duel_refund_user_fee(session: dict[str, Any], user_id: int, reason: str, *, force: bool = False) -> bool:
    if not _duel_is_mode(session.get("mode")):
        return False
    # Block refund if session already started, UNLESS forced (e.g. timeout/expiry path)
    if not force and session.get("started_at"):
        return False
    fee = float(session.get("entry_fee") or 0.0)
    uid = int(user_id)
    refunded = {int(x) for x in (session.get("refunded_user_ids") or []) if int(x) > 0}
    charged = {int(x) for x in (session.get("charged_user_ids") or []) if int(x) > 0}
    if uid in refunded or uid not in charged or fee <= 0:
        return uid in refunded
    subject = str(session.get("subject") or "English")
    bot_mode = _competition_bot_mode(str(session.get("mode") or "duel-1v1"))
    if add_dcoins_only(uid, fee, subject, change_type=f"{bot_mode}_refund:{session.get('id')}:{reason}"):
        refunded.add(uid)
        session["refunded_user_ids"] = sorted(refunded)
        _duel_decrement_daily_usage(uid, bot_mode, _duel_usage_date_for_user(session, uid))
        return True
    return False


def _duel_refund_pending_session(session: dict[str, Any], reason: str) -> None:
    if not _duel_is_mode(session.get("mode")):
        _competition_refund_entry_fee(session)
        return
    # Allow refund in both pending and generating phase regardless of started_at
    phase = _competition_session_phase(session)
    if phase not in {"pending", "generating", "finished"}:
        return
    for uid in [int(x) for x in (session.get("charged_user_ids") or []) if int(x) > 0]:
        _duel_refund_user_fee(session, uid, reason, force=True)
    session["status"] = "finished"
    session["finalized"] = True
    session["cancelled_at"] = _now_utc().isoformat()
    session["finished_at"] = session["cancelled_at"]
    session["cancel_reason"] = reason
    session["result"] = {"winners": [], "by_user": {}, "tie": False, "error": reason, "refunded": True}
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    for row in _competition_joined_participants(session):
        WEB_DUEL_PLAYER_SESSION.pop(int(row.get("user_id") or 0), None)
    _duel_persist_session(session)


def _duel_leave_pending_session(session: dict[str, Any], user_id: int) -> dict[str, Any]:
    if not _duel_is_mode(session.get("mode")):
        raise HTTPException(status_code=400, detail="This is not a duel session")
    phase = _competition_session_phase(session)
    # Allow leaving (with refund) in pending or generating phase.
    # started_at may be set during generating — we still allow refund before session goes active.
    if phase not in {"pending", "generating"}:
        raise HTTPException(status_code=409, detail="Duel already started")
    uid = int(user_id)
    if not _competition_user_is_participant(session, uid):
        raise HTTPException(status_code=403, detail="Session is not assigned to current user")
    refunded = _duel_refund_user_fee(session, uid, "left_queue")
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) == uid:
            row["status"] = "left"
            row["left_at"] = _now_utc().isoformat()
            break
    WEB_DUEL_PLAYER_SESSION.pop(uid, None)
    joined_count = len(_competition_waiting_participants(session))
    if joined_count <= 0:
        session["status"] = "finished"
        session["finalized"] = True
        session["cancelled_at"] = _now_utc().isoformat()
        session["finished_at"] = session["cancelled_at"]
        session["cancel_reason"] = "left_queue"
        session["result"] = {"winners": [], "by_user": {}, "tie": False, "error": "Queue cancelled", "refunded": refunded}
        WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    else:
        session["status"] = "pending"
        session["generation_started"] = False
        session["generation_percent"] = 0
        session["stage_generation_percent"] = 0
        session.pop("generation_token", None)
        session.pop("generation_task_stage", None)
        session.pop("generation_recovery_started_at", None)
        WEB_COMPETITION_PENDING_BY_KEY[str(session.get("queue_key") or "")] = str(session.get("id") or "")
    _duel_persist_session(session)
    return {"cancelled": True, "refunded": bool(refunded), "phase": _competition_session_phase(session), "status": session.get("status")}


def _competition_refund_user_entry_fee(session: dict[str, Any], user_id: int, reason: str, *, force: bool = False) -> bool:
    if _duel_is_mode(session.get("mode")):
        return _duel_refund_user_fee(session, int(user_id), reason, force=force)
    # Block refund if already started, UNLESS force=True (used by timeout/expire paths)
    if not force and session.get("started_at"):
        return False
    fee = float(session.get("entry_fee") or 0.0)
    uid = int(user_id)
    charged = {int(x) for x in (session.get("charged_user_ids") or []) if int(x) > 0}
    refunded = {int(x) for x in (session.get("refunded_user_ids") or []) if int(x) > 0}
    if uid in refunded or uid not in charged or fee <= 0:
        return uid in refunded
    subject = str(session.get("subject") or "English")
    bot_mode = _competition_bot_mode(str(session.get("mode") or "daily"))
    # Use add_dcoins_only (not add_dcoins) so the refund is symmetric with
    # try_consume_dcoins which only touched visible dcoin / dcoin_floor,
    # not the authoritative D'point balance.
    ok = bool(_safe_call(lambda: add_dcoins_only(uid, fee, subject, change_type=f"{bot_mode}_refund:{session.get('id')}:{reason}"), False))
    if ok:
        refunded.add(uid)
        session["refunded_user_ids"] = sorted(refunded)
        if str(session.get("mode") or "") in {"boss", "daily"}:
            _duel_decrement_daily_usage(uid, bot_mode, _duel_usage_date_for_user(session, uid))
        logger.info(
            "competition refund OK uid=%s fee=%s mode=%s session=%s reason=%s",
            uid, fee, session.get("mode"), session.get("id"), reason,
        )
    else:
        logger.warning(
            "competition refund FAILED uid=%s fee=%s mode=%s session=%s reason=%s",
            uid, fee, session.get("mode"), session.get("id"), reason,
        )
    return ok


def _competition_leave_pending_session(session: dict[str, Any], user_id: int, reason: str = "left_queue") -> dict[str, Any]:
    if _duel_is_mode(session.get("mode")):
        return _duel_leave_pending_session(session, int(user_id))
    phase = _competition_session_phase(session)
    # Allow leaving (with refund) in pending or generating phase.
    # started_at may be set during generating — we still allow refund.
    if phase not in {"pending", "generating"}:
        return {"cancelled": False, "refunded": False, "phase": phase, "status": session.get("status")}
    uid = int(user_id)
    if not _competition_user_is_participant(session, uid):
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"cancelled": False, "refunded": False, "phase": _competition_session_phase(session), "status": session.get("status")}
    refunded = _competition_refund_user_entry_fee(session, uid, reason, force=True)
    # Persist immediately after refund so that refunded_user_ids reaches the DB
    # even if the final persist below fails for any reason.
    if refunded:
        _duel_persist_session(session)
    for row in session.get("participants") or []:
        if int(row.get("user_id") or 0) == uid:
            row["status"] = "left"
            row["left_at"] = _now_utc().isoformat()
            break
    WEB_DUEL_PLAYER_SESSION.pop(uid, None)
    joined_count = len(_competition_waiting_participants(session))
    if joined_count <= 0:
        session["status"] = "finished"
        session["finalized"] = True
        session["cancelled_at"] = _now_utc().isoformat()
        session["finished_at"] = session["cancelled_at"]
        session["cancel_reason"] = reason
        session["result"] = {"winners": [], "by_user": {}, "tie": False, "error": reason, "refunded": refunded}
        WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    else:
        session["status"] = "pending"
        session["generation_started"] = False
        session["generation_percent"] = 0
        session["stage_generation_percent"] = 0
        session.pop("generation_token", None)
        session.pop("generation_task_stage", None)
        session.pop("generation_recovery_started_at", None)
        WEB_COMPETITION_PENDING_BY_KEY[str(session.get("queue_key") or "")] = str(session.get("id") or "")
    _duel_persist_session(session)
    return {"cancelled": True, "refunded": bool(refunded), "phase": _competition_session_phase(session), "status": session.get("status")}


def _duel_expire_stale_pending() -> None:
    _ensure_web_duel_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT session_id, expires_at FROM web_duel_sessions WHERE status IN ('pending', 'generating')")
        rows = [dict(r) for r in (cur.fetchall() or [])]
    finally:
        conn.close()
    now_dt = _now_utc()
    for row in rows:
        expires = _parse_utc_timestamp(str(row.get("expires_at") or ""))
        if expires and expires <= now_dt:
            session = _duel_load_session_from_db(str(row.get("session_id") or ""))
            if session and not session.get("started_at"):
                _duel_refund_pending_session(session, "Queue expired")


def _duel_expire_session_if_needed(session: dict[str, Any]) -> bool:
    if not _duel_is_mode(session.get("mode")) or session.get("started_at"):
        return False
    if _competition_session_phase(session) not in {"pending", "generating"}:
        return False
    if _competition_expire_waiting_session_if_needed(session):
        return True
    expires = _parse_utc_timestamp(str(session.get("expires_at") or ""))
    if expires and expires <= _now_utc():
        _duel_refund_pending_session(session, "Queue expired")
        return True
    return False


def _duel_persist_answer(
    session: dict[str, Any],
    user_id: int,
    question_index: int,
    selected: int | None,
    *,
    is_correct: bool,
    is_unanswered: bool,
    is_late: bool,
    timer_state: dict[str, Any],
) -> None:
    _competition_persist_answer_db(
        session,
        user_id,
        question_index,
        selected,
        is_correct=is_correct,
        is_unanswered=is_unanswered,
        is_late=is_late,
        timer_state=timer_state,
    )
    if not _duel_is_mode(session.get("mode")):
        return
    _ensure_web_duel_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            INSERT INTO web_duel_answers
            (session_id, user_id, question_index, selected_option_index, is_correct, is_unanswered, is_late,
             allowed_seconds, deadline_at, answered_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(session_id, user_id, question_index) DO UPDATE SET
                selected_option_index=excluded.selected_option_index,
                is_correct=excluded.is_correct,
                is_unanswered=excluded.is_unanswered,
                is_late=excluded.is_late,
                allowed_seconds=excluded.allowed_seconds,
                deadline_at=excluded.deadline_at,
                answered_at=excluded.answered_at
            """,
            (
                str(session.get("id") or ""),
                int(user_id),
                int(question_index),
                None if selected is None else int(selected),
                1 if is_correct else 0,
                1 if is_unanswered else 0,
                1 if is_late else 0,
                int(timer_state.get("allowed_seconds") or COMPETITION_WEB_SECONDS),
                timer_state.get("deadline_at"),
                _now_utc().isoformat(),
            ),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("duel answer persist failed session_id=%s user_id=%s", session.get("id"), user_id)
    finally:
        conn.close()


def _duel_save_history(session: dict[str, Any]) -> None:
    if not _duel_is_mode(session.get("mode")) or not bool(session.get("finalized")):
        return
    _ensure_web_duel_runtime_schema()
    result = session.get("result") or {}
    by_user = result.get("by_user") or {}
    participants = _competition_joined_participants(session)
    teams = session.get("teams") or {}
    total = max(0, len(session.get("questions") or []))
    tie = bool(result.get("tie"))
    winner_user_id = None if tie else (int((result.get("winners") or [0])[0] or 0) or None)
    winner_team = None if tie else result.get("winner_team")
    conn = get_conn()
    cur = conn.cursor()
    try:
        participants_json = json.dumps(participants, ensure_ascii=False, default=_json_default)
        for row in participants:
            uid = int(row.get("user_id") or 0)
            if uid <= 0:
                continue
            own = by_user.get(uid) or by_user.get(str(uid)) or {}
            status = "tie" if tie else ("win" if bool(own.get("winner")) else "lose")
            fee_charged = float(session.get("entry_fee") or 0.0) if uid in [int(x) for x in (session.get("charged_user_ids") or [])] else 0.0
            fee_refunded = 1 if uid in [int(x) for x in (session.get("refunded_user_ids") or [])] else 0
            cur.execute(
                """
                INSERT INTO web_duel_history
                (session_id, user_id, mode, subject, team_no, result_status, correct_count, wrong_count, skipped_count,
                 total_questions, winner_user_id, winner_team, tie, entry_fee, fee_refunded, dpoints_delta, dcoin_delta,
                 participants_json, result_json, started_at, finished_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(session_id, user_id) DO UPDATE SET
                    result_status=excluded.result_status,
                    correct_count=excluded.correct_count,
                    wrong_count=excluded.wrong_count,
                    skipped_count=excluded.skipped_count,
                    winner_user_id=excluded.winner_user_id,
                    winner_team=excluded.winner_team,
                    tie=excluded.tie,
                    entry_fee=excluded.entry_fee,
                    fee_refunded=excluded.fee_refunded,
                    dpoints_delta=excluded.dpoints_delta,
                    dcoin_delta=excluded.dcoin_delta,
                    participants_json=excluded.participants_json,
                    result_json=excluded.result_json,
                    started_at=excluded.started_at,
                    finished_at=excluded.finished_at
                """,
                (
                    str(session.get("id") or ""),
                    uid,
                    str(session.get("mode") or ""),
                    str(session.get("subject") or "English"),
                    int(teams.get(uid) or 1),
                    status,
                    int(own.get("correct") or 0),
                    int(own.get("wrong") or 0),
                    int(own.get("unanswered") or 0),
                    total,
                    winner_user_id,
                    winner_team,
                    1 if tie else 0,
                    fee_charged,
                    fee_refunded,
                    float(own.get("dpoints_delta") or 0.0),
                    float(own.get("dcoin") or 0.0),
                    participants_json,
                    json.dumps(own, ensure_ascii=False, default=_json_default),
                    session.get("started_at"),
                    session.get("finished_at") or _now_utc().isoformat(),
                ),
            )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("duel history save failed session_id=%s", session.get("id"))
    finally:
        conn.close()


def _duel_history_for_user(user_id: int, mode: str | None = None, limit: int = 20) -> list[dict[str, Any]]:
    _ensure_web_duel_runtime_schema()
    conn = get_conn()
    cur = conn.cursor()
    try:
        args: list[Any] = [int(user_id)]
        where = "WHERE user_id=?"
        if mode and _duel_is_mode(mode):
            where += " AND mode=?"
            args.append(str(mode))
        args.append(max(1, min(50, int(limit or 20))))
        cur.execute(
            f"""
            SELECT *
            FROM web_duel_history
            {where}
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            tuple(args),
        )
        rows = []
        for row in cur.fetchall() or []:
            item = dict(row)
            item["participants"] = _safe_json_array(item.pop("participants_json", None))
            item["result"] = _safe_json_object(item.pop("result_json", None))
            rows.append(item)
        return rows
    finally:
        conn.close()


def _competition_refund_entry_fee(session: dict[str, Any]) -> None:
    fee = float(session.get("entry_fee") or 0)
    if fee <= 0:
        return
    if _duel_is_mode(session.get("mode")):
        _duel_refund_pending_session(session, "Queue expired")
        return
    charged_ids = [int(uid) for uid in (session.get("charged_user_ids") or []) if int(uid) > 0]
    for uid in charged_ids:
        _competition_refund_user_entry_fee(session, uid, "Queue expired")


def _competition_mark_user_finished(session: dict[str, Any], user_id: int) -> None:
    for item in session.get("participants") or []:
        if int(item.get("user_id") or 0) == int(user_id):
            item["status"] = "finished"
            break


def _competition_record_solo_result(session: dict[str, Any], user_id: int) -> dict[str, Any]:
    return ((_competition_finalize_non_daily(session).get("by_user") or {}).get(int(user_id)) or {})


def _competition_dpoints_to_dcoin(user_id: int, dpoints_delta: float) -> float:
    return float(dpoints_delta)


def _competition_finalize_non_daily(session: dict[str, Any]) -> dict[str, Any]:
    if bool(session.get("finalized")) and (session.get("result") or {}).get("by_user"):
        return session.get("result") or {"winners": [], "by_user": {}}
    mode = str(session.get("mode") or "")
    subject = str(session.get("subject") or "English")
    progress_map = session.get("progress") or {}
    total = max(1, len(session.get("questions") or []))
    winners: list[int] = []
    reward_by_user: dict[int, float] = {}
    tie_result = False
    winner_team: int | None = None
    settings = _get_runtime_settings()
    arena_reward_base = float(settings.get("arena_reward") or 5.0)
    duel_reward = float(settings.get("duel_reward") or arena_reward_base)
    arena_penalty = -abs(float(settings.get("arena_penalty") or 0.0))
    duel_penalty = -abs(float(settings.get("duel_penalty") or 0.0))
    group_winner_reward = max(0.0, float(settings.get("group_arena_winner_reward") or 10.0))
    boss_reward_per_correct = max(0.0, float(settings.get("boss_arena_reward_per_correct") or 3.0))
    boss_reward_flat = max(0.0, float(settings.get("boss_arena_reward_flat") or 20.0))
    boss_threshold = max(0.0, min(100.0, float(settings.get("boss_arena_global_threshold_percent") or 86.0)))

    if mode.startswith("duel-"):
        if mode == "duel-1v1":
            rows = [(int(pid), int(r.get("correct") or 0), int(r.get("wrong") or 0)) for pid, r in progress_map.items()]
            best_correct = max([row[1] for row in rows], default=0)
            best_rows = [row for row in rows if int(row[1]) == int(best_correct)]
            tie_result = len(best_rows) > 1
            if not tie_result and best_rows:
                winners = [int(best_rows[0][0])]
        else:
            team_score: dict[int, dict[str, int]] = {}
            for pid, row in progress_map.items():
                team = int((session.get("teams") or {}).get(int(pid), 1))
                cur = team_score.setdefault(team, {"correct": 0, "wrong": 0})
                cur["correct"] += int(row.get("correct") or 0)
                cur["wrong"] += int(row.get("wrong") or 0)
            best_correct = max([int(row.get("correct") or 0) for row in team_score.values()], default=0)
            best_teams = [int(team) for team, row in team_score.items() if int(row.get("correct") or 0) == int(best_correct)]
            tie_result = len(best_teams) > 1
            if not tie_result and best_teams:
                winner_team = int(best_teams[0])
                winners = [int(pid) for pid in progress_map.keys() if int((session.get("teams") or {}).get(int(pid), 1)) == winner_team]
        if not tie_result:
            for uid in winners:
                reward_by_user[int(uid)] = duel_reward
            if duel_penalty != 0:
                for uid in [int(pid) for pid in progress_map.keys()]:
                    if uid in winners:
                        continue
                    reward_by_user[uid] = duel_penalty
    elif mode == "group":
        ranked = sorted(
            [(int(pid), int(r.get("correct") or 0), int(r.get("wrong") or 0)) for pid, r in progress_map.items()],
            key=lambda item: (-item[1], item[2]),
        )
        best_correct = int(ranked[0][1]) if ranked else 0
        winners = [int(item[0]) for item in ranked if int(item[1]) == best_correct]
        for uid in winners:
            reward_by_user[int(uid)] = group_winner_reward
        if arena_penalty != 0:
            for uid in [int(item[0]) for item in ranked]:
                if uid in winners:
                    continue
                reward_by_user[uid] = arena_penalty
    elif mode == "boss":
        rows = [(int(pid), int((row or {}).get("correct") or 0)) for pid, row in progress_map.items()]
        possible = sum(max(1, len(_competition_questions_for_user(session, int(uid)))) for uid, _ in rows)
        global_accuracy = (sum(correct for _, correct in rows) * 100.0) / float(max(1, possible))
        gate_ok = global_accuracy >= boss_threshold
        # Spec: if the group's aggregate accuracy clears the threshold, EVERY participant
        # earns a flat reward (admin-configurable, default 20 D'Points).
        for uid, correct in rows:
            reward_by_user[uid] = boss_reward_flat if gate_ok else 0.0
            if gate_ok:
                winners.append(uid)
        session["boss_global_accuracy"] = round(global_accuracy, 2)
        session["boss_reward_flat"] = boss_reward_flat
        session["boss_threshold_percent"] = boss_threshold

    result_map: dict[int, dict[str, Any]] = {}
    for pid, row in progress_map.items():
        uid = int(pid)
        correct = int(row.get("correct") or 0)
        wrong = int(row.get("wrong") or 0)
        unanswered = int(row.get("unanswered") or 0)
        user_total = max(1, len(_competition_questions_for_user(session, uid)))
        dpoints_delta = float(reward_by_user.get(uid, 0.0))
        if dpoints_delta != 0:
            if mode == "group":
                change_type = f"group_arena_reward:{session.get('external_group_arena_session_id') or session.get('id')}"
            elif mode == "boss":
                change_type = f"boss_arena_reward:{session.get('id')}:correct_{correct}"
            else:
                change_type = f"web_{mode}_reward"
            
            if mode == "boss":
                already_rewarded = _boss_arena_has_received_reward(str(session.get("id") or ""), uid) or \
                                  bool(session.get("rewards_distributed_by_user", {}).get(str(uid)))
                if not already_rewarded:
                    add_dpoints(uid, dpoints_delta, subject, change_type=change_type)
                    session.setdefault("rewards_distributed_by_user", {})[str(uid)] = True
            else:
                add_dpoints(uid, dpoints_delta, subject, change_type=change_type)
        result_map[uid] = {
            "correct": correct,
            "wrong": wrong,
            "unanswered": unanswered,
            "total_questions": user_total,
            "accuracy": round((correct * 100.0) / float(user_total), 2),
            "winner": uid in winners,
            "tie": tie_result,
            "result_status": "tie" if tie_result else ("win" if uid in winners else "lose"),
            "team": int((session.get("teams") or {}).get(uid, 1)),
            "dpoints_delta": dpoints_delta,
            "dcoin": _competition_dpoints_to_dcoin(uid, dpoints_delta),
        }
        if mode == "group" and int(session.get("external_group_arena_session_id") or 0) > 0:
            _safe_call(
                lambda uid_ref=uid, row_ref=row, delta_ref=dpoints_delta: finish_arena_group_session_attempt(
                    session_id=int(session.get("external_group_arena_session_id") or 0),
                    user_id=uid_ref,
                    correct=correct,
                    wrong=wrong,
                    unanswered=unanswered,
                    net_dcoins=0.0,
                    net_dpoints=delta_ref,
                ),
                None,
            )
        _competition_mark_user_finished(session, uid)
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)

    out = {"winners": winners, "by_user": result_map, "tie": tie_result}
    if winner_team is not None:
        out["winner_team"] = winner_team
    session["status"] = "finished"
    session["finalized"] = True
    session["finished_at"] = _now_utc().isoformat()
    session["result"] = out
    if mode == "group" and int(session.get("external_group_arena_session_id") or 0) > 0:
        _mark_legacy_group_arena_completed(int(session.get("external_group_arena_session_id") or 0))
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    _competition_save_history(session)
    _duel_save_history(session)
    _duel_persist_session(session)
    return out


def _competition_finalize_daily_stage(session: dict[str, Any]) -> dict[str, Any]:
    mode = str(session.get("mode") or "")
    if mode != "daily":
        return _competition_finalize_non_daily(session)
    progress_map = session.get("progress") or {}
    stage = max(1, int(session.get("stage") or 1))
    total_stages = max(1, int(session.get("total_stages") or 5))
    joined_ids = [int(r.get("user_id") or 0) for r in _competition_joined_participants(session) if int(r.get("user_id") or 0) > 0]
    if not joined_ids:
        session["status"] = "finished"
        session["finalized"] = True
        session["result"] = {"winners": [], "by_user": {}, "podium": []}
        return session["result"]
    active_ids = _competition_active_participant_ids(session)
    if not active_ids:
        active_ids = list(joined_ids)

    daily_scores = session.setdefault("daily_scores", {})
    now_iso = _now_utc().isoformat()
    for uid in active_ids:
        daily_scores.setdefault(int(uid), {"total_correct": 0, "total_wrong": 0, "total_unanswered": 0, "stages": {}})
    for pid, row in progress_map.items():
        uid = int(pid)
        if uid not in active_ids:
            continue
        correct = int(row.get("correct") or 0)
        wrong = int(row.get("wrong") or 0)
        unanswered = int(row.get("unanswered") or 0)
        finished_at = str(row.get("finished_at") or now_iso)
        rec = daily_scores.setdefault(uid, {"total_correct": 0, "total_wrong": 0, "total_unanswered": 0, "stages": {}})
        rec["total_correct"] = int(rec.get("total_correct") or 0) + correct
        rec["total_wrong"] = int(rec.get("total_wrong") or 0) + wrong
        rec["total_unanswered"] = int(rec.get("total_unanswered") or 0) + unanswered
        rec.setdefault("stages", {})[stage] = {
            "correct": correct,
            "wrong": wrong,
            "unanswered": unanswered,
            "finished_at": finished_at,
        }

    n0 = int(session.get("initial_participants") or len(joined_ids))
    session["initial_participants"] = n0
    finalists_target = max(1, int(session.get("finalists_target") or 4))
    if n0 < finalists_target:
        finalists_target = n0
    session["finalists_target"] = finalists_target

    if stage < total_stages:
        ranked = sorted(
            active_ids,
            key=lambda uid: (
                -int((daily_scores.get(uid) or {}).get("total_correct") or 0),
                int((daily_scores.get(uid) or {}).get("total_wrong") or 0),
                str((((daily_scores.get(uid) or {}).get("stages") or {}).get(stage) or {}).get("finished_at") or ""),
                int(uid),
            ),
        )
        target = _competition_daily_stage_target(n0, stage)
        keep_count = max(1, min(len(ranked), target))
        keepers = ranked[:keep_count]
        eliminated = [uid for uid in ranked[keep_count:] if uid not in keepers]
        session["active_participants"] = keepers
        session["eliminated_participants"] = sorted(
            {
                int(uid)
                for uid in ((session.get("eliminated_participants") or []) + eliminated)
                if int(uid) > 0
            }
        )
        for row in session.get("participants") or []:
            uid = int(row.get("user_id") or 0)
            if uid in keepers:
                row["status"] = "active"
            elif uid in session.get("eliminated_participants") or []:
                row["status"] = "eliminated"
        token = uuid4().hex
        session["status"] = "generating"
        session["generation_started"] = True
        session["generation_percent"] = 5
        session["stage_generation_percent"] = 5
        session["generation_token"] = token
        session["generation_task_stage"] = int(stage + 1)
        session["generation_recovery_started_at"] = _now_utc().isoformat()
        WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
        _duel_persist_session(session)
        return {"winners": [], "by_user": {}, "stage_transition": True}

    finalists = [int(uid) for uid in (session.get("active_participants") or joined_ids) if int(uid) > 0]
    if not finalists:
        finalists = joined_ids
    stage_key = total_stages
    ranked_final = sorted(
        finalists,
        key=lambda uid: (
            -int((((daily_scores.get(uid) or {}).get("stages") or {}).get(stage_key) or {}).get("correct") or 0),
            int((((daily_scores.get(uid) or {}).get("stages") or {}).get(stage_key) or {}).get("wrong") or 0),
            -int((daily_scores.get(uid) or {}).get("total_correct") or 0),
            str(((((daily_scores.get(uid) or {}).get("stages") or {}).get(stage_key) or {}).get("finished_at") or "")),
            int(uid),
        ),
    )
    settings = _get_runtime_settings()
    podium_rewards = {
        1: max(0.0, float(settings.get("daily_arena_reward_first") or 25.0)),
        2: max(0.0, float(settings.get("daily_arena_reward_second") or 20.0)),
        3: max(0.0, float(settings.get("daily_arena_reward_third") or 15.0)),
    }
    podium: list[dict[str, Any]] = []
    result_map: dict[int, dict[str, Any]] = {}
    subject = str(session.get("subject") or "English")
    # Idempotency guard: prevent double reward if finalize is called twice (restart / concurrent)
    already_rewarded = bool(session.get("rewards_distributed"))

    for rank, uid in enumerate(ranked_final, start=1):
        reward = float(podium_rewards.get(rank, 0.0))
        if reward != 0 and not already_rewarded:
            add_dpoints(uid, reward, subject, change_type="web_daily_arena_stage5_reward")
        if rank <= 3:
            podium.append({"user_id": uid, "rank": rank, "dpoints_delta": reward})
        s5 = (((daily_scores.get(uid) or {}).get("stages") or {}).get(stage_key) or {})
        result_map[uid] = {
            "rank": rank,
            "correct": int(s5.get("correct") or 0),
            "wrong": int(s5.get("wrong") or 0),
            "unanswered": int(s5.get("unanswered") or 0),
            "total_questions": max(1, len(session.get("questions") or [])),
            "accuracy": round((int(s5.get("correct") or 0) * 100.0) / float(max(1, len(session.get("questions") or []))), 2),
            "total_correct": int((daily_scores.get(uid) or {}).get("total_correct") or 0),
            "winner": rank == 1,
            "dpoints_delta": reward,
            "dcoin": _competition_dpoints_to_dcoin(uid, reward),
        }

    # Mark rewards distributed so a second finalize call never re-awards
    session["rewards_distributed"] = True

    for uid in joined_ids:
        if uid in result_map:
            _competition_mark_user_finished(session, uid)
            WEB_DUEL_PLAYER_SESSION.pop(uid, None)
            continue
        rec = daily_scores.get(uid) or {}
        result_map[uid] = {
            "rank": None,
            "correct": int(rec.get("total_correct") or 0),
            "wrong": int(rec.get("total_wrong") or 0),
            "unanswered": int(rec.get("total_unanswered") or 0),
            "total_questions": max(1, len(session.get("questions") or [])),
            "accuracy": 0.0,
            "total_correct": int(rec.get("total_correct") or 0),
            "winner": False,
            "dpoints_delta": 0.0,
            "dcoin": 0.0,
            "eliminated": True,
        }
        _competition_mark_user_finished(session, uid)
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)

    winners = [int(ranked_final[0])] if ranked_final else []
    out = {"winners": winners, "podium": podium, "by_user": result_map}
    session["status"] = "finished"
    session["finalized"] = True
    session["finished_at"] = _now_utc().isoformat()
    session["result"] = out
    WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
    _competition_save_history(session)
    _duel_persist_session(session)
    return out


async def _competition_start_generation(session_id: str, stage: int | None = None, generation_token: str | None = None) -> None:
    session: dict[str, Any] | None = None
    with _competition_session_advisory_lock(session_id):
        session = _competition_load_session_from_db(session_id) or WEB_COMPETITION_SESSIONS.get(session_id)
        if not session or _competition_session_phase(session) in {"active", "finished"}:
            return

        mode = str(session.get("mode") or "daily")
        total_stages = _competition_total_stages(mode)
        target_stage = int(stage or (int(session.get("stage") or 0) + 1))
        if target_stage < 1:
            target_stage = 1
        if target_stage > total_stages:
            target_stage = total_stages

        if not generation_token:
            generation_token = str(session.get("generation_token") or "")
            if not generation_token:
                generation_token = _competition_prepare_generation(session, target_stage=target_stage)
        if not generation_token:
            return
        if str(session.get("generation_token") or "") != str(generation_token):
            return
        if int(session.get("generation_task_stage") or target_stage) != int(target_stage):
            return
        if target_stage == 1 and not _competition_generation_ready(session, target_stage):
            _competition_reset_generation_to_pending_if_not_ready(session, target_stage)
            return

        session["generation_percent"] = max(18, int(session.get("generation_percent") or 0))
        session["stage_generation_percent"] = max(18, int(session.get("stage_generation_percent") or session.get("generation_percent") or 0))
        _duel_persist_session(session)

    if not session:
        return
    mode = str(session.get("mode") or "daily")
    total_stages = _competition_total_stages(mode)
    target_stage = int(stage or (int(session.get("stage") or 0) + 1))
    if target_stage < 1:
        target_stage = 1
    if target_stage > total_stages:
        target_stage = total_stages
    owner_candidates = [int(row.get("user_id") or 0) for row in (session.get("participants") or []) if int(row.get("user_id") or 0) > 0]
    created_by = owner_candidates[0] if owner_candidates else int(session.get("created_by") or 0) or 1
    question_count = max(1, int(session.get("question_count") or _competition_question_count(mode)))
    difficulty = str(session.get("difficulty") or _competition_default_difficulty(mode))

    async def _update_progress():
        try:
            for i in range(19, 81):
                if session.get("status") != "generating" or str(session.get("generation_token") or "") != str(generation_token):
                    break
                session["generation_percent"] = i
                session["stage_generation_percent"] = i
                if i % 10 == 0:
                    _duel_persist_session(session)
                await asyncio.sleep(12.0 / (80 - 18 + 1))
        except asyncio.CancelledError:
            pass

    questions: list[dict[str, Any]] = []
    progress_task = asyncio.create_task(_update_progress())
    
    try:
        if mode == "daily" and target_stage > 1:
            all_qs = session.get("all_daily_questions") or []
            if len(all_qs) >= target_stage:
                questions = all_qs[target_stage - 1]
            else:
                questions = []
        elif mode == "daily" and target_stage == 1:
            async def gen_stage_q(stg):
                unique_created_by = -stg - (int(created_by) * 10)
                return await _runtime_generate_questions(
                    created_by=unique_created_by,
                    subject=str(session.get("subject") or "English"),
                    level=_competition_generation_level(str(session.get("level") or "PRE-INTERMEDIATE"), mode, stg, difficulty),
                    count=question_count,
                    mode=mode,
                    competition_session_id=str(session.get("id") or None),
                    require_fresh=True,
                )
            results = await asyncio.gather(
                gen_stage_q(1),
                gen_stage_q(2),
                gen_stage_q(3),
                gen_stage_q(4),
                gen_stage_q(5)
            )
            all_ok = all(r and len(r) >= question_count for r in results)
            if not all_ok:
                questions = []
            else:
                session["all_daily_questions"] = [list(r) for r in results]
                questions = session["all_daily_questions"][0]
        else:
            questions = await _runtime_generate_questions(
                created_by=created_by,
                subject=str(session.get("subject") or "English"),
                level=_competition_generation_level(str(session.get("level") or "PRE-INTERMEDIATE"), mode, target_stage, difficulty),
                count=question_count,
                mode=mode,
                competition_session_id=str(session.get("id") or None),
                require_fresh=True,
            )
    except Exception:
        logger.exception("competition question generation failed session_id=%s stage=%s", session_id, target_stage)
        questions = []
    finally:
        progress_task.cancel()
        with suppress(asyncio.CancelledError, Exception):
            await progress_task
        
    with _competition_session_advisory_lock(session_id):
        current = _competition_load_session_from_db(session_id)
        if not current:
            return
        if _competition_session_phase(current) in {"active", "finished"}:
            return
        if str(current.get("generation_token") or "") != str(generation_token):
            return
        if int(current.get("generation_task_stage") or target_stage) != int(target_stage):
            return
        if target_stage == 1 and not _competition_generation_ready(current, target_stage):
            _competition_reset_generation_to_pending_if_not_ready(current, target_stage)
            return
        if mode == "daily" and target_stage == 1 and session.get("all_daily_questions"):
            current["all_daily_questions"] = session.get("all_daily_questions")
        session = current

        session["generation_percent"] = 82
        session["stage_generation_percent"] = 82
        _duel_persist_session(session)

        if not questions or len(questions) < question_count:
            _competition_refund_entry_fee(session)
            session["status"] = "finished"
            session["finalized"] = True
            session["result"] = {"winners": [], "by_user": {}, "error": "Could not generate competition questions"}
            session.pop("generation_token", None)
            session.pop("generation_task_stage", None)
            session.pop("generation_recovery_started_at", None)
            for row in _competition_joined_participants(session):
                WEB_DUEL_PLAYER_SESSION.pop(int(row.get("user_id") or 0), None)
            WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
            _duel_persist_session(session)
            return

        joined = _competition_waiting_participants(session) if target_stage == 1 or _duel_is_mode(mode) else _competition_joined_participants(session)
        joined_ids = [int(row.get("user_id") or 0) for row in joined if int(row.get("user_id") or 0) > 0]
        if mode == "daily":
            if target_stage == 1:
                session["initial_participants"] = int(session.get("initial_participants") or len(joined_ids))
                player_ids = joined_ids
                session["active_participants"] = list(player_ids)
                session["eliminated_participants"] = []
            else:
                player_ids = [int(uid) for uid in (session.get("active_participants") or []) if int(uid) > 0]
        else:
            player_ids = joined_ids
        if not player_ids:
            session["status"] = "finished"
            session["finalized"] = True
            session["result"] = {"winners": [], "by_user": {}, "error": "No active participants"}
            session.pop("generation_token", None)
            session.pop("generation_task_stage", None)
            session.pop("generation_recovery_started_at", None)
            WEB_COMPETITION_PENDING_BY_KEY.pop(str(session.get("queue_key") or ""), None)
            _duel_persist_session(session)
            return
        session["questions"] = questions
        if mode == "boss":
            import random as _random
            session["participant_questions"] = {}
            for uid in player_ids:
                pool = list(questions)
                _random.shuffle(pool)
                session["participant_questions"][str(int(uid))] = pool[:5]
        session["progress"] = {int(uid): {"index": 1, "correct": 0, "wrong": 0, "unanswered": 0} for uid in player_ids}
        session["teams"] = _competition_team_map(mode, player_ids)
        session["stage"] = int(target_stage)
        session["total_stages"] = int(total_stages)
        session["finalists_target"] = int(session.get("finalists_target") or _competition_finalists_target(mode))
        session["status"] = "running"
        started_at_dt = _now_utc()
        session["started_at"] = started_at_dt.isoformat()
        session["expires_at"] = None
        session["timers"] = {}
        _competition_seed_initial_question_timers(session, player_ids, started_at=started_at_dt)
        session["generation_percent"] = 100
        session["stage_generation_percent"] = 100
        session.pop("generation_token", None)
        session.pop("generation_task_stage", None)
        session.pop("generation_recovery_started_at", None)
        for row in session.get("participants") or []:
            uid = int(row.get("user_id") or 0)
            if uid in player_ids:
                row["status"] = "active"
            elif mode == "daily":
                row["status"] = "eliminated"
        _duel_persist_session(session)
    await _competition_notify_started(session)
    _duel_persist_session(session)


@app.post("/competition/runtime/start")
async def competition_runtime_start(payload: CompetitionStartRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    mode = payload.mode
    is_duel = _duel_is_mode(mode)
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)

    user_subjects = _normalize_subjects(_user_subjects_from_row(user), fallback=["English"])
    requested_subject = _normalize_subject_label(payload.subject)
    if len(user_subjects) == 1:
        subject = user_subjects[0]
    elif requested_subject and requested_subject in user_subjects:
        subject = requested_subject
    elif requested_subject:
        raise HTTPException(status_code=403, detail="Selected subject is not assigned to current student")
    else:
        raise HTTPException(status_code=400, detail="subject is required")
    level = (_safe_call(lambda: get_group_level_for_subject(user_id, subject), None) or str(user.get("level") or "PRE-INTERMEDIATE")).strip().upper()
    if level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}:
        level = "PRE-INTERMEDIATE"

    existing_session_id = WEB_DUEL_PLAYER_SESSION.get(user_id)
    if not existing_session_id:
        db_existing = _competition_load_active_session_for_user(user_id)
        if db_existing:
            existing_session_id = str(db_existing.get("id") or "")
    existing = None
    if existing_session_id:
        existing = WEB_COMPETITION_SESSIONS.get(existing_session_id)
        if not existing:
            existing = _competition_load_session_from_db(existing_session_id)
            if existing:
                WEB_COMPETITION_SESSIONS[existing_session_id] = existing
    if existing:
        if _competition_session_unusable_for_user(existing, user_id):
            WEB_DUEL_PLAYER_SESSION.pop(user_id, None)
            existing_session_id = ""
        elif existing_session_id and _competition_session_phase(existing) != "finished":
            if not _competition_session_matches_request(existing, mode, subject, payload.group_id):
                existing_phase = _competition_session_phase(existing)
                if _competition_session_is_stale_for_switch(existing):
                    logger.info(
                        "competition.start detached stale mismatch user_id=%s old_session_id=%s old_mode=%s old_subject=%s requested_mode=%s requested_subject=%s phase=%s",
                        user_id,
                        str(existing.get("id") or ""),
                        str(existing.get("mode") or ""),
                        str(existing.get("subject") or ""),
                        mode,
                        subject,
                        existing_phase,
                    )
                    _competition_detach_user_from_session(existing, user_id, "stale_session_switched")
                    existing_session_id = ""
                elif existing_phase in {"pending", "generating"} and not existing.get("started_at"):
                    if _duel_is_mode(existing.get("mode")):
                        _duel_leave_pending_session(existing, user_id)
                    else:
                        _competition_leave_pending_session(existing, user_id, reason="switched_competition")
                    WEB_DUEL_PLAYER_SESSION.pop(user_id, None)
                else:
                    logger.info(
                        "competition.start active mismatch user_id=%s old_session_id=%s old_mode=%s old_subject=%s requested_mode=%s requested_subject=%s phase=%s",
                        user_id,
                        str(existing.get("id") or ""),
                        str(existing.get("mode") or ""),
                        str(existing.get("subject") or ""),
                        mode,
                        subject,
                        existing_phase,
                    )
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "active_session_mismatch",
                            "message": "Active competition session does not match selected mode or subject",
                            "existing": {
                                "session_id": str(existing.get("id") or ""),
                                "mode": existing.get("mode"),
                                "subject": existing.get("subject"),
                                "group_id": existing.get("group_id"),
                                "phase": existing_phase,
                            },
                        },
                    )
            if existing_session_id and _competition_session_matches_request(existing, mode, subject, payload.group_id) and _competition_session_phase(existing) != "finished":
                if _competition_user_left_or_blocked(existing, user_id):
                    WEB_DUEL_PLAYER_SESSION.pop(user_id, None)
                    raise HTTPException(status_code=423, detail="This arena or duel was already left or blocked")
                snapshot = _competition_snapshot(existing, user_id=user_id)
                return _attach_proctoring_payload(
                    user,
                    snapshot,
                    test_type=str(existing.get("mode") or payload.mode),
                    test_attempt_ref=str(existing.get("id") or ""),
                    test_route=f"/?role=student&section={_competition_section_for_mode(str(existing.get('mode') or payload.mode))}",
                )
        elif existing_session_id:
            WEB_DUEL_PLAYER_SESSION.pop(user_id, None)

    if mode == "group":
        group_id = int(payload.group_id or 0)
        if group_id <= 0:
            student_groups = _safe_call(lambda: get_user_groups(user_id), []) or []
            active_candidates: list[dict[str, Any]] = []
            for student_group in student_groups:
                gid = int(student_group.get("id") or 0)
                if gid <= 0:
                    continue
                sess = _safe_call(lambda group_ref=gid: get_active_arena_group_session_by_group_id(group_ref), None)
                if sess:
                    active_candidates.append({"group_id": gid, "session": sess})
            if not active_candidates:
                raise HTTPException(status_code=409, detail="Group Arena has not been started by the teacher")
            active_candidates.sort(key=lambda item: str((item.get("session") or {}).get("created_at") or ""), reverse=True)
            group_id = int(active_candidates[0]["group_id"])
        group = _safe_call(lambda: get_group(group_id), None)
        if not group:
            raise HTTPException(status_code=404, detail="Group not found")
        member_ids = {
            int(row.get("id") or 0)
            for row in (_safe_call(lambda: get_group_users(group_id), []) or [])
            if int(row.get("login_type") or 0) in (1, 2, 6)
        }
        if user_id not in member_ids:
            raise HTTPException(status_code=403, detail="You are not a member of this group")
        active_group_session = _safe_call(lambda: get_active_arena_group_session_by_group_id(group_id), None)
        if not active_group_session:
            raise HTTPException(status_code=409, detail="Group Arena has not been started by the teacher")
        today, present_students, attendance_ready, attendance_reason = _group_arena_today_presence(group_id)
        if not attendance_ready:
            raise HTTPException(status_code=409, detail=attendance_reason)
        present_ids = {int(row.get("id") or 0) for row in present_students}
        if user_id not in present_ids:
            raise HTTPException(status_code=403, detail="Only present students can join Group Arena")
        group_question_rows = _safe_call(lambda: get_arena_group_session_questions(int(active_group_session.get("id") or 0)), []) or []
        if not group_question_rows:
            raise HTTPException(status_code=409, detail="Group Arena questions are not ready")
        subject = _normalize_subject_label(str(active_group_session.get("subject") or group.get("subject") or subject)) or subject
        level = str(active_group_session.get("level") or group.get("level") or level).strip().upper()
        if level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}:
            level = "PRE-INTERMEDIATE"
        legacy_group_session_id = int(active_group_session.get("id") or 0)
        group_queue_key = f"group|{int(group_id)}|{legacy_group_session_id}"
        group_questions = _competition_enrich_reading_questions(group_question_rows, subject, "group")

        async with WEB_COMPETITION_LOCK:
            session = _competition_load_group_runtime_session(group_id, legacy_group_session_id)
            if not session:
                session_id = f"cmp_{uuid4().hex}"
                participants = [
                    {
                        "user_id": int(row.get("id") or 0),
                        "name": _display_name(row),
                        "status": "active",
                        "joined_at": _now_utc().isoformat(),
                    }
                    for row in present_students
                    if int(row.get("id") or 0) > 0
                ]
                player_ids = [int(row.get("user_id") or 0) for row in participants if int(row.get("user_id") or 0) > 0]
                started_at_dt = _now_utc()
                session = {
                    "id": session_id,
                    "mode": mode,
                    "subject": subject,
                    "level": level,
                    "group_id": int(group_id),
                    "group_name": str(group.get("name") or f"Group #{group_id}"),
                    "teacher_name": str(group.get("teacher_name") or group.get("teacher") or ""),
                    "external_group_arena_session_id": legacy_group_session_id,
                    "created_at": _now_utc().isoformat(),
                    "created_by": int(active_group_session.get("created_by_teacher_id") or 0),
                    "status": "running",
                    "theme": _competition_theme(mode),
                    "questions": group_questions,
                    "participants": participants,
                    "teams": _competition_team_map(mode, player_ids),
                    "required_players": len(player_ids),
                    "max_players": len(player_ids),
                    "queue_key": group_queue_key,
                    "progress": {int(uid): {"index": 1, "correct": 0, "wrong": 0, "unanswered": 0} for uid in player_ids},
                    "finalized": False,
                    "generation_started": True,
                    "generation_percent": 100,
                    "stage_generation_percent": 100,
                    "stage": 1,
                    "total_stages": 1,
                    "initial_participants": len(player_ids),
                    "active_participants": player_ids,
                    "eliminated_participants": [],
                    "finalists_target": 0,
                    "daily_scores": {},
                    "entry_fee": 0.0,
                    "charged_user_ids": [],
                    "refunded_user_ids": [],
                    "usage_dates": {},
                    "started_at": started_at_dt.isoformat(),
                    "timers": {},
                    "result": {"winners": [], "by_user": {}},
                }
                _competition_seed_initial_question_timers(session, player_ids, started_at=started_at_dt)
                WEB_COMPETITION_SESSIONS[session_id] = session
                WEB_COMPETITION_PENDING_BY_KEY[group_queue_key] = session_id
            else:
                session_id = str(session.get("id") or "")
            if _competition_user_left_or_blocked(session, user_id):
                WEB_DUEL_PLAYER_SESSION.pop(user_id, None)
                raise HTTPException(status_code=423, detail="This group arena was already left or blocked")
            mark_arena_group_session_attempt(session_id=legacy_group_session_id, user_id=user_id)
            WEB_DUEL_PLAYER_SESSION[user_id] = str(session.get("id") or session_id)
            _duel_persist_session(session)

        snapshot = _competition_snapshot(session, user_id=user_id)
        return _attach_proctoring_payload(
            user,
            snapshot,
            test_type=mode,
            test_attempt_ref=str(session.get("id") or session_id),
            test_route=f"/?role=student&section={_competition_section_for_mode(mode)}",
        )

    if mode == "daily":
        ok_window, hhmm = _competition_is_within_join_window(mode, subject)
        if not ok_window:
            raise HTTPException(
                status_code=409,
                detail=f"{mode.title()} arena join window is closed. Scheduled start for {subject}: {hhmm} (Asia/Tashkent).",
            )
    # Boss Arena is always open (anytime queue) - no fixed schedule window ever
    if mode == "boss":
        pass  # intentionally always joinable, per user request to remove any fixed time

    bot_mode = _competition_bot_mode(mode)
    required_players = _competition_required_players(mode)
    max_players = max(required_players, _competition_max_players(mode))
    charged_fee = _competition_entry_fee(mode)
    requested_question_count = int(payload.question_count or _competition_question_count(mode))
    requested_difficulty = str(payload.difficulty or _competition_default_difficulty(mode)).strip().title()
    queue_key = _competition_queue_key(mode, subject, level)
    should_start_generation = False
    generation_token = ""
    created_new_session = False
    session_id = ""
    session: dict[str, Any] | None = None

    with _competition_queue_advisory_lock(queue_key):
        async with WEB_COMPETITION_LOCK:
            if is_duel:
                _duel_expire_stale_pending()
            _competition_cleanup_stale_pending()
            pending_session_id = WEB_COMPETITION_PENDING_BY_KEY.get(queue_key)
            if pending_session_id:
                pending_session = WEB_COMPETITION_SESSIONS.get(pending_session_id)
                if not pending_session:
                    pending_session = _competition_load_session_from_db(pending_session_id)
                    if pending_session:
                        WEB_COMPETITION_SESSIONS[pending_session_id] = pending_session
                if pending_session and not _competition_session_unusable_for_matching(pending_session) and _competition_session_has_join_slot(pending_session):
                    session = pending_session
                    session_id = str(pending_session.get("id") or "")
                else:
                    WEB_COMPETITION_PENDING_BY_KEY.pop(queue_key, None)
            if not session:
                session = _competition_find_pending_session(queue_key)
                if session:
                    session_id = str(session.get("id") or "")

            if not session:
                session_id = f"cmp_{uuid4().hex}"
                session = {
                    "id": session_id,
                    "mode": mode,
                    "subject": subject,
                    "level": level,
                    "created_at": _now_utc().isoformat(),
                    "created_by": user_id,
                    "status": "pending",
                    "theme": _competition_theme(mode),
                    "questions": [],
                    "question_count": requested_question_count,
                    "difficulty": requested_difficulty,
                    "participants": [],
                    "teams": {},
                    "required_players": required_players,
                    "max_players": max_players,
                    "queue_key": queue_key,
                    "progress": {},
                    "finalized": False,
                    "generation_started": False,
                    "generation_percent": 0,
                    "stage_generation_percent": 0,
                    "stage": 0,
                    "total_stages": _competition_total_stages(mode),
                    "initial_participants": 0,
                    "active_participants": [],
                    "eliminated_participants": [],
                    "finalists_target": _competition_finalists_target(mode),
                    "daily_scores": {},
                    "entry_fee": charged_fee,
                    "charged_user_ids": [],
                    "refunded_user_ids": [],
                    "usage_dates": {},
                    "expires_at": (_now_utc() + timedelta(minutes=20)).isoformat() if is_duel else None,
                    "result": {"winners": [], "by_user": {}},
                }
                WEB_COMPETITION_SESSIONS[session_id] = session
                WEB_COMPETITION_PENDING_BY_KEY[queue_key] = session_id
                created_new_session = True
                _duel_persist_session(session)

            participants = session.setdefault("participants", [])
            existing_participant = next((row for row in participants if int(row.get("user_id") or 0) == user_id), None)
            existing_status = str((existing_participant or {}).get("status") or "active").lower()
            inactive_rejoin = bool(existing_participant and existing_status in {"left", "cancelled", "finished", "eliminated", "blocked", "failed"})
            phase = _competition_session_phase(session)
            reactivated_participant = False
            if inactive_rejoin:
                if phase == "pending":
                    existing_participant["status"] = "active"
                    existing_participant["joined_at"] = _now_utc().isoformat()
                    existing_participant.pop("left_at", None)
                    existing_participant.pop("left_reason", None)
                    inactive_rejoin = False
                    reactivated_participant = True
                else:
                    WEB_DUEL_PLAYER_SESSION.pop(user_id, None)
                    raise HTTPException(status_code=423, detail="This lobby or session was already left or blocked")
            if not existing_participant:
                current_joined = len(_competition_waiting_participants(session))
                if phase != "pending":
                    raise HTTPException(status_code=409, detail="This arena has already started")
                if current_joined >= max_players:
                    raise HTTPException(status_code=409, detail="Arena queue is full")
                if (mode.startswith("duel-") or mode == "boss") and not can_start_duel_today(user_id, bot_mode, _now_tashkent_date(), limit_per_day=COMPETITION_DAILY_JOIN_LIMIT):
                    limit_label = f"{bot_mode} duel" if mode.startswith("duel-") else "Boss Arena"
                    raise HTTPException(status_code=429, detail=f"Daily limit reached for {limit_label}")
                fee_change_type = f"arena_fee:{bot_mode}:{session.get('id') or session_id}" if is_duel else None
                already_charged = user_id in [int(uid) for uid in session.setdefault("charged_user_ids", [])]
                if is_duel and not already_charged and fee_change_type:
                    conn_check = get_conn()
                    try:
                        cur_check = conn_check.cursor()
                        cur_check.execute("SELECT 1 FROM diamond_history WHERE user_id=? AND change_type=? LIMIT 1", (user_id, fee_change_type))
                        already_charged = bool(cur_check.fetchone())
                    finally:
                        conn_check.close()

                if charged_fee > 0 and not already_charged:
                    if not try_consume_dcoins(user_id, charged_fee, subject, arena_type=bot_mode, change_type=fee_change_type):
                        raise HTTPException(status_code=409, detail="Insufficient D'Coin balance")
                usage_date = _now_tashkent_date()
                if mode.startswith("duel-") or mode == "boss":
                    increment_duel_daily_usage(user_id, bot_mode, usage_date)
                    session.setdefault("usage_dates", {})[str(user_id)] = usage_date
                participants.append({"user_id": user_id, "name": _display_name(user), "status": "active", "joined_at": _now_utc().isoformat(), "usage_date": usage_date})
                if charged_fee > 0 and user_id not in [int(uid) for uid in session.setdefault("charged_user_ids", [])]:
                    session.setdefault("charged_user_ids", []).append(user_id)
                if charged_fee > 0:
                    session["refunded_user_ids"] = [int(uid) for uid in (session.get("refunded_user_ids") or []) if int(uid) != int(user_id)]
                _competition_touch_wait_deadline(session)
                _duel_persist_session(session)
            elif reactivated_participant:
                _competition_touch_wait_deadline(session)
                _duel_persist_session(session)

            WEB_DUEL_PLAYER_SESSION[user_id] = str(session.get("id") or session_id)

            joined_count = len(_competition_waiting_participants(session))
            start_threshold = required_players
            if phase == "pending" and joined_count >= start_threshold:
                token = _competition_prepare_generation(session, target_stage=1)
                if token:
                    should_start_generation = True
                    generation_token = token

    if mode == "daily" and session:
        asyncio.create_task(_competition_notify_daily_prestart(session))
    if session and _competition_session_phase(session) == "pending" and not session.get("available_notifications_sent"):
        asyncio.create_task(_competition_notify_session_available(session, creator_user_id=user_id))
    if should_start_generation:
        asyncio.create_task(_competition_start_generation(str(session.get("id") or session_id), stage=1, generation_token=generation_token))

    snapshot = _competition_snapshot(session, user_id=user_id)
    return _attach_proctoring_payload(
        user,
        snapshot,
        test_type=mode,
        test_attempt_ref=str(session.get("id") or session_id),
        test_route=f"/?role=student&section={_competition_section_for_mode(mode)}",
    )


@app.get("/competition/runtime/my-active")
async def competition_runtime_my_active(
    mode: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    group_id: int | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    sid = WEB_DUEL_PLAYER_SESSION.get(uid)
    if not sid:
        sess = _competition_load_active_session_for_user(uid)
        if not sess:
            return {"active": False}
        sid = str(sess.get("id") or "")
    else:
        sess = _competition_load_session_from_db(sid)
    if sess:
        _competition_restore_runtime_participant_if_needed(sess, uid, source="my_active")
        if _competition_session_unusable_for_matching(sess):
            WEB_DUEL_PLAYER_SESSION.pop(uid, None)
            return {"active": False, "expired": True, "refunded": True}
        if _competition_session_phase(sess) == "active":
            with _competition_session_advisory_lock(sid):
                sess = _competition_load_session_from_db(sid)
                if sess and _competition_session_phase(sess) == "active":
                    _competition_auto_skip_due_questions(sess)
    if not sess:
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"active": False}
    if _competition_user_left_or_blocked(sess, uid):
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"active": False, "blocked": True, "reason": "left_or_proctoring_blocked"}
    if _competition_session_phase(sess) == "finished":
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"active": False}
    if _competition_user_result(sess, uid):
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"active": False}
    requested_mode = str(mode or "").strip()
    requested_subject = _normalize_subject_label(subject)
    if requested_mode:
        session_subject = _normalize_subject_label(str(sess.get("subject") or ""))
        mismatch = str(sess.get("mode") or "") != requested_mode
        if requested_subject:
            mismatch = mismatch or session_subject != requested_subject
        if requested_mode == "group" and group_id is not None:
            mismatch = mismatch or int(sess.get("group_id") or 0) != int(group_id or 0)
        if mismatch:
            return {
                "active": False,
                "mismatch": True,
                "existing": {
                    "session_id": str(sess.get("id") or ""),
                    "mode": sess.get("mode"),
                    "subject": sess.get("subject"),
                    "group_id": sess.get("group_id"),
                    "phase": _competition_session_phase(sess),
                },
            }
    snap = _competition_snapshot(sess, user_id=uid)
    return {"active": True, **snap}


@app.get("/competition/runtime/duel/history")
async def competition_runtime_duel_history(
    mode: str | None = Query(default=None),
    limit: int = Query(default=20, ge=1, le=50),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    mode_value = str(mode or "").strip()
    if mode_value and not _duel_is_mode(mode_value):
        raise HTTPException(status_code=400, detail="Invalid duel mode")
    shared_items = _competition_history_for_user(uid, mode_value or None, int(limit))
    if shared_items:
        return {"items": shared_items}
    return {"items": _duel_history_for_user(uid, mode_value or None, int(limit))}


@app.get("/competition/runtime/history")
async def competition_runtime_history(
    mode: str | None = Query(default=None),
    limit: int = Query(default=20, ge=1, le=50),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    mode_value = str(mode or "").strip()
    valid_modes = {"daily", "group", "boss", "duel-1v1", "duel-3v3", "duel-5v5"}
    if mode_value and mode_value not in valid_modes:
        raise HTTPException(status_code=400, detail="Invalid competition mode")
    items = _competition_history_for_user(uid, mode_value or None, int(limit))
    if (not mode_value or _duel_is_mode(mode_value)) and len(items) < int(limit):
        seen = {str(row.get("session_id") or "") for row in items}
        for row in _duel_history_for_user(uid, mode_value or None, int(limit)):
            sid = str(row.get("session_id") or "")
            if sid in seen:
                continue
            item = dict(row)
            item["type"] = item.get("mode")
            item["rank"] = item.get("team_no")
            item["correct"] = item.get("correct_count")
            item["wrong"] = item.get("wrong_count")
            item["skipped"] = item.get("skipped_count")
            item["reward_dpoints"] = item.get("dpoints_delta")
            item["dcoin_fee"] = item.get("entry_fee")
            items.append(item)
            seen.add(sid)
            if len(items) >= int(limit):
                break
    return {"items": items[: int(limit)]}


async def _competition_ensure_session_for_user(session_id: str, user: dict) -> dict[str, Any]:
    uid = int(user.get("id") or 0)
    # 1. Direct session lookup by requested session_id
    sess = _competition_load_session_from_db(session_id)
    if sess:
        direct_phase = _competition_session_phase(sess)
        if direct_phase == "finished":
            if _competition_participant_row(sess, uid) or _competition_user_result(sess, uid) or (sess.get("result") or {}).get("error"):
                return sess
        elif not _competition_session_unusable_for_user(sess, uid):
            return sess

    # 2. Check active session stored in memory for user
    active_sid = WEB_DUEL_PLAYER_SESSION.get(uid)
    if active_sid:
        active_sess = _competition_load_session_from_db(active_sid)
        if active_sess and not _competition_session_unusable_for_user(active_sess, uid):
            return active_sess

    # 3. Active session lookup in DB
    active_sess = _competition_load_active_session_for_user(uid)
    if active_sess and not _competition_session_unusable_for_user(active_sess, uid):
        WEB_DUEL_PLAYER_SESSION[uid] = str(active_sess.get("id") or "")
        return active_sess

    WEB_DUEL_PLAYER_SESSION.pop(uid, None)
    raise HTTPException(status_code=404, detail="Competition session not found or expired")


@app.post("/competition/runtime/{session_id}/leave")
async def competition_runtime_leave(session_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    with _competition_session_advisory_lock(session_id):
        sess = _competition_load_session_from_db(session_id) or _competition_load_active_session_for_user(uid)
        if not sess:
            WEB_DUEL_PLAYER_SESSION.pop(uid, None)
            return {"cancelled": True, "refunded": False, "phase": "finished", "status": "finished"}
        phase = _competition_session_phase(sess)
        if phase in {"pending", "generating"} and not sess.get("started_at"):
            return _competition_leave_pending_session(sess, uid)
        if not _competition_user_is_participant(sess, uid):
            WEB_DUEL_PLAYER_SESSION.pop(uid, None)
            return {"cancelled": False, "refunded": False, "phase": phase, "status": sess.get("status")}
        _competition_detach_user_from_session(sess, uid, "left_runtime")
        WEB_DUEL_PLAYER_SESSION.pop(uid, None)
        return {"cancelled": True, "refunded": False, "phase": _competition_session_phase(sess), "status": sess.get("status")}


@app.get("/competition/runtime/{session_id}/status")
async def competition_runtime_status(session_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    sess = await _competition_ensure_session_for_user(session_id, user)
    actual_sid = str(sess.get("id") or session_id)
    with _competition_session_advisory_lock(actual_sid):
        current_phase = _competition_session_phase(sess)
        for row in (sess.get("participants") or []):
            if int(row.get("user_id") or 0) == uid:
                row["last_ping_at"] = _now_utc().isoformat()
                _duel_persist_session(sess)
                break

        expired_now = _duel_expire_session_if_needed(sess) if _duel_is_mode(sess.get("mode")) else _competition_expire_waiting_session_if_needed(sess)
        if expired_now:
            out = _competition_snapshot(sess, user_id=uid)
            out["live"] = _competition_live_lists(sess)
            out["result"] = _competition_user_result(sess, uid)
            return out
        if _competition_session_phase(sess) == "active":
            _competition_auto_skip_due_questions(sess)
            current_phase = _competition_session_phase(sess)
        if _competition_session_phase(sess) == "generating" and not (sess.get("questions") or []):
            now_dt = _now_utc()
            target_stage = int(sess.get("stage") or 1) or 1
            if _competition_reset_generation_to_pending_if_not_ready(sess, target_stage):
                current_phase = "pending"
            else:
                recovery_dt = _parse_utc_timestamp(str(sess.get("generation_recovery_started_at") or ""))
                if not recovery_dt or now_dt - recovery_dt > timedelta(seconds=45):
                    sess.pop("generation_token", None)
                    sess.pop("generation_task_stage", None)
                    token = _competition_prepare_generation(sess, target_stage=target_stage)
                    if token:
                        asyncio.create_task(_competition_start_generation(str(sess.get("id") or actual_sid), stage=target_stage, generation_token=token))
        elif _competition_session_phase(sess) == "pending":
            sess["generation_started"] = False
            sess["generation_percent"] = 0
            sess["stage_generation_percent"] = 0
            if sess.get("generation_recovery_started_at"):
                sess.pop("generation_recovery_started_at", None)
                _duel_persist_session(sess)
        live = _competition_live_lists(sess)
        out = _competition_snapshot(sess, user_id=uid)
        out["live"] = live
        out["opponent_progress"] = _competition_opponent_progress(sess, uid)
        out["result"] = _competition_user_result(sess, uid) if _competition_session_phase(sess) == "finished" else None
        return out



@app.get("/competition/runtime/{session_id}/question")
async def competition_runtime_question(
    session_id: str,
    proctoring_session_id: int | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    sess = await _competition_ensure_session_for_user(session_id, user)
    actual_sid = str(sess.get("id") or session_id)
    with _competition_session_advisory_lock(actual_sid):
        if _duel_is_mode(sess.get("mode")):
            _require_student_learning_access(user)
        expired_now = _duel_expire_session_if_needed(sess) if _duel_is_mode(sess.get("mode")) else _competition_expire_waiting_session_if_needed(sess)
        if expired_now:
            return {"completed": True, "phase": _competition_session_phase(sess), "status": sess.get("status"), "result": _competition_user_result(sess, uid)}
        if _competition_session_phase(sess) == "active":
            _competition_auto_skip_due_questions(sess)
        elif _competition_session_phase(sess) == "generating" and not (sess.get("questions") or []):
            _competition_reset_generation_to_pending_if_not_ready(sess, int(sess.get("stage") or 1) or 1)
        phase = _competition_session_phase(sess)
        progress = _competition_user_progress(sess, uid)
        if not progress:
            if str(sess.get("mode") or "") == "daily" and int(uid) in [int(x) for x in (sess.get("eliminated_participants") or [])]:
                return {
                    "completed": False,
                    "phase": phase,
                    "eliminated": True,
                    "stage": int(sess.get("stage") or 0),
                    "total_stages": int(sess.get("total_stages") or 5),
                    "generation_started": bool(sess.get("generation_started")) and phase in {"generating", "active"},
                    "generation_percent": int(sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                    "stage_generation_percent": int(sess.get("stage_generation_percent") or sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                    "live": _competition_live_lists(sess),
                }
            progress = sess.setdefault("progress", {})[uid] = {"index": 1, "correct": 0, "wrong": 0, "unanswered": 0}
            _duel_persist_session(sess)

        user_questions = _competition_questions_for_user(sess, uid)
        total = len(user_questions)
        if phase in {"pending", "generating"}:
            return {
                "completed": False,
                "phase": phase,
                "status": sess.get("status"),
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
                "initial_participants": int(sess.get("initial_participants") or len(_competition_joined_participants(sess))),
                "active_participants_count": len(_competition_active_participant_ids(sess)),
                "eliminated_participants_count": len([int(uid) for uid in (sess.get("eliminated_participants") or []) if int(uid) > 0]),
                "finalists_target": int(sess.get("finalists_target") or _competition_finalists_target(str(sess.get("mode") or ""))),
                "question_index": 0,
                "total_questions": max(0, total),
                "progress_percent": 0,
                "generation_started": bool(sess.get("generation_started")) and phase in {"generating", "active"},
                "generation_percent": int(sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                "stage_generation_percent": int(sess.get("stage_generation_percent") or sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                "live": _competition_live_lists(sess),
            }
        q_index = int(progress.get("index") or 1)
        if phase == "finished":
            return {"completed": True, "phase": phase, "result": _competition_user_result(sess, uid)}
        if q_index > total:
            mode = str(sess.get("mode") or "")
            is_daily_mode = mode == "daily"
            return {
                "completed": False,
                "phase": phase,
                "waiting_stage_completion": is_daily_mode,
                "waiting_completion": not is_daily_mode,
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(mode)),
                "generation_started": bool(sess.get("generation_started")) and phase in {"generating", "active"},
                "generation_percent": int(sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                "stage_generation_percent": int(sess.get("stage_generation_percent") or sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                "live": _competition_live_lists(sess),
            }
        question = user_questions[min(max(0, q_index - 1), max(0, total - 1))] if total > 0 else {}
        global_timer = _competition_global_match_timer_state(sess, uid, user_questions)
        questions_payload = [_public_question_payload(q) for q in user_questions]
        opponents = _competition_opponent_progress(sess, uid)
        return {
            "completed": False,
            "phase": phase,
            "stage": int(sess.get("stage") or 0),
            "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
            "initial_participants": int(sess.get("initial_participants") or len(_competition_joined_participants(sess))),
            "active_participants_count": len(_competition_active_participant_ids(sess)),
            "eliminated_participants_count": len([int(uid) for uid in (sess.get("eliminated_participants") or []) if int(uid) > 0]),
            "finalists_target": int(sess.get("finalists_target") or _competition_finalists_target(str(sess.get("mode") or ""))),
            "question_index": q_index,
            "total_questions": total,
            "progress_percent": int(round(((q_index - 1) * 100 / max(1, total)))),
            "time_limit_sec": global_timer["total_match_seconds"],
            "time_remaining_sec": global_timer["global_time_remaining_sec"],
            "deadline_at": global_timer["deadline_at"],
            "question_started_at": global_timer["started_at"],
            "question": _public_question_payload(question) if question else None,
            "questions": questions_payload,
            "opponent_progress": opponents,
            "live": _competition_live_lists(sess),
        }



@app.post("/competition/runtime/{session_id}/answer")
async def competition_runtime_answer(session_id: str, payload: CompetitionAnswerRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    sess = await _competition_ensure_session_for_user(session_id, user)
    actual_sid = str(sess.get("id") or session_id)
    with _competition_session_advisory_lock(actual_sid):
        if _duel_is_mode(sess.get("mode")):
            _require_student_learning_access(user)
        expired_now = _duel_expire_session_if_needed(sess) if _duel_is_mode(sess.get("mode")) else _competition_expire_waiting_session_if_needed(sess)
        if expired_now:
            return {"completed": True, "phase": _competition_session_phase(sess), "status": sess.get("status"), "result": _competition_user_result(sess, uid)}
        phase = _competition_session_phase(sess)
        if phase == "generating" and not (sess.get("questions") or []):
            _competition_reset_generation_to_pending_if_not_ready(sess, int(sess.get("stage") or 1) or 1)
            phase = _competition_session_phase(sess)
        if phase in {"pending", "generating"}:
            return {
                "completed": False,
                "status": sess.get("status"),
                "phase": phase,
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
                "generation_started": bool(sess.get("generation_started")) and phase in {"generating", "active"},
                "generation_percent": int(sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
                "stage_generation_percent": int(sess.get("stage_generation_percent") or sess.get("generation_percent") or 0) if phase in {"generating", "active"} else 0,
            }
        if phase == "finished":
            return {
                "completed": True,
                "status": sess.get("status"),
                "phase": phase,
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
                "result": _competition_user_result(sess, uid),
            }
        
        if _competition_session_phase(sess) == "active":
            _competition_auto_skip_due_questions(sess)
        phase = _competition_session_phase(sess)
        if phase == "finished":
            return {
                "completed": True,
                "status": sess.get("status"),
                "phase": phase,
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
                "result": _competition_user_result(sess, uid),
            }
        progress = _competition_user_progress(sess, uid)
        if not progress:
            if str(sess.get("mode") or "") == "daily" and int(uid) in [int(x) for x in (sess.get("eliminated_participants") or [])]:
                return {
                    "completed": False,
                    "status": sess.get("status"),
                    "phase": _competition_session_phase(sess),
                    "stage": int(sess.get("stage") or 0),
                    "total_stages": int(sess.get("total_stages") or 5),
                    "eliminated": True,
                    "result": _competition_user_result(sess, uid),
                }
            progress = sess.setdefault("progress", {})[uid] = {"index": 1, "correct": 0, "wrong": 0, "unanswered": 0}
            _duel_persist_session(sess)

        questions = _competition_questions_for_user(sess, uid)
        total = len(questions)
        q_index = int(progress.get("index") or 1)
        mode = str(sess.get("mode") or "")
        if payload.question_index is not None:
            if payload.question_index < q_index:
                # Stale/duplicate submit from client - silently ignore, return current state
                return {
                    "completed": q_index > total,
                    "status": sess.get("status"),
                    "phase": _competition_session_phase(sess),
                    "stage": int(sess.get("stage") or 0),
                    "total_stages": int(sess.get("total_stages") or _competition_total_stages(mode)),
                    "result": _competition_user_result(sess, uid) if _competition_session_phase(sess) == "finished" else None,
                    "question_index": q_index,
                }
            elif payload.question_index > q_index:
                # Client is ahead of server - likely a timing issue, treat as current question
                # Don't raise an error, just process with server's q_index
                pass

        if q_index > total:
            ready = _competition_session_phase(sess) == "finished" and _competition_user_result(sess, uid) is not None
            return {
                "completed": bool(ready),
                "result": _competition_user_result(sess, uid) if ready else None,
                "status": sess.get("status"),
                "phase": _competition_session_phase(sess),
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
            }

        q = questions[max(0, min(q_index - 1, total - 1))] if total > 0 else {}
        sel = payload.selected_option_index
        mode = str(sess.get("mode") or "")
        timer_state = _competition_timer_state(sess, uid, q_index, q, create=True)
        _competition_apply_question_outcome(sess, uid, q_index, None if sel is None else int(sel), timer_state)
        _duel_persist_session(sess)

        finalized_or_transitioned = _competition_finalize_if_all_progress_finished(sess)
        if not finalized_or_transitioned:
            return {
                "completed": False,
                "status": sess.get("status"),
                "phase": _competition_session_phase(sess),
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or _competition_total_stages(mode)),
                "result": None,
            }

        if mode == "daily":
            return {
                "completed": bool(_competition_session_phase(sess) == "finished" and _competition_user_result(sess, uid) is not None),
                "status": sess.get("status"),
                "phase": _competition_session_phase(sess),
                "stage": int(sess.get("stage") or 0),
                "total_stages": int(sess.get("total_stages") or 5),
                "result": _competition_user_result(sess, uid),
            }

        return {
            "completed": bool(_competition_user_result(sess, uid) is not None),
            "status": sess.get("status"),
            "phase": _competition_session_phase(sess),
            "stage": int(sess.get("stage") or 1),
            "total_stages": int(sess.get("total_stages") or 1),
            "result": _competition_user_result(sess, uid),
        }


@app.get("/competition/runtime/{session_id}/result")
async def competition_runtime_result(session_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    uid = int(user.get("id") or 0)
    sess = await _competition_ensure_session_for_user(session_id, user)
    actual_sid = str(sess.get("id") or session_id)
    if _competition_session_phase(sess) == "active":
        with _competition_session_advisory_lock(actual_sid):
            sess = await _competition_ensure_session_for_user(actual_sid, user)
            if sess and _competition_session_phase(sess) == "active":
                _competition_auto_skip_due_questions(sess)
    own = _competition_user_result(sess, uid)
    if not own:
        session_result = sess.get("result") or {}
        if session_result.get("error") or session_result.get("refunded"):
            return {
                "ready": True,
                "mode": sess.get("mode"),
                "theme": sess.get("theme"),
                "phase": _competition_session_phase(sess),
                "winners": [],
                "tie": False,
                "result": {
                    "correct": 0,
                    "wrong": 0,
                    "unanswered": 0,
                    "winner": False,
                    "tie": False,
                    "dpoints_delta": 0,
                    "dcoin": 0,
                    "refunded": bool(session_result.get("refunded")),
                    "error": session_result.get("error") or "Queue expired",
                },
                "live": _competition_live_lists(sess),
                "participants_result": _competition_result_participants(sess),
            }
        return {"ready": False, "phase": _competition_session_phase(sess), "status": sess.get("status")}
    return {
        "ready": True,
        "mode": sess.get("mode"),
        "theme": sess.get("theme"),
        "phase": _competition_session_phase(sess),
        "stage": int(sess.get("stage") or 0),
        "total_stages": int(sess.get("total_stages") or _competition_total_stages(str(sess.get("mode") or ""))),
        "winners": (sess.get("result") or {}).get("winners") or [],
        "tie": bool((sess.get("result") or {}).get("tie")),
        "winner_team": (sess.get("result") or {}).get("winner_team"),
        "podium": (sess.get("result") or {}).get("podium") or [],
        "boss_summary": _competition_boss_summary(sess),
        "result": own,
        "live": _competition_live_lists(sess),
        "participants_result": _competition_result_participants(sess),
    }


def _competition_opponent_progress(session: dict[str, Any], current_user_id: int) -> list[dict[str, Any]]:
    out = []
    questions = session.get("questions") or []
    total = len(questions) or 5
    progress_map = session.get("progress") or {}
    for p in session.get("participants") or []:
        uid = int(p.get("user_id") or 0)
        if uid <= 0 or uid == int(current_user_id):
            continue
        p_prog = progress_map.get(uid) or progress_map.get(str(uid)) or {}
        correct = int(p_prog.get("correct") or 0)
        wrong = int(p_prog.get("wrong") or 0)
        unanswered = int(p_prog.get("unanswered") or 0)
        completed = correct + wrong + unanswered
        status_str = str(p.get("status") or "active").lower()
        is_finished = status_str in {"finished", "left", "eliminated", "cancelled"} or completed >= total
        out.append({
            "user_id": uid,
            "name": str(p.get("name") or f"Player {uid}"),
            "completed_count": min(total, completed),
            "total_questions": total,
            "is_finished": is_finished,
            "status": status_str,
        })
    return out


def _competition_global_match_timer_state(session: dict[str, Any], user_id: int, user_questions: list[dict[str, Any]]) -> dict[str, Any]:
    mode = str(session.get("mode") or "")
    total_sec = sum(_competition_question_allowed_seconds(q, mode) for q in user_questions) if user_questions else COMPETITION_WEB_SECONDS * 5
    started_raw = str(session.get("started_at") or "")
    started_at = _parse_utc_timestamp(started_raw)
    if not started_at:
        started_at = _now_utc()
        session["started_at"] = started_at.isoformat()
        _duel_persist_session(session)
    deadline = started_at + timedelta(seconds=total_sec)
    now_dt = _now_utc()
    remaining = max(0, int(math.ceil((deadline - now_dt).total_seconds())))
    return {
        "total_match_seconds": total_sec,
        "started_at": started_at.isoformat(),
        "deadline_at": deadline.isoformat(),
        "global_time_remaining_sec": remaining,
        "is_expired": remaining <= 0,
    }


def _competition_question_allowed_seconds(question: dict[str, Any], mode: str = "") -> int:

    q = _mcq_question_from_row(question or {})
    passage = str(q.get("passage") or "").strip()
    prompt = str(q.get("prompt") or q.get("question") or "").strip()
    options_text = " ".join(str(opt) for opt in (q.get("options") or []))
    text = " ".join([passage, prompt, options_text]).strip()
    qtype = str(q.get("question_type") or "").strip().lower()

    # Reading questions always get extended time (60–120 s)
    if qtype == "reading" or passage:
        words = len(text.split())
        seconds = 30 + int(words * 0.85)
        return max(60, min(120, seconds))

    if len(text.split()) >= 55 and (_duel_is_mode(mode) or mode in {"daily", "group", "boss"}):
        words = len(text.split())
        seconds = 30 + int(words * 0.85)
        return max(30, min(120, seconds))
    return COMPETITION_WEB_SECONDS


def _competition_timer_state(
    session: dict,
    user_id: int,
    question_index: int,
    question: dict[str, Any] | None = None,
    *,
    create: bool = True,
) -> dict[str, Any]:
    q = question or ((session.get("questions") or [])[max(0, int(question_index) - 1)] if (session.get("questions") or []) else {})
    allowed = int(_competition_question_allowed_seconds(q or {}, str(session.get("mode") or "")))
    timers = session.setdefault("timers", {})
    key = f"{int(user_id)}:{int(question_index)}"
    rec = timers.get(key)
    if isinstance(rec, dict):
        started_raw = str(rec.get("started_at") or "")
        allowed = int(rec.get("allowed_seconds") or allowed)
    else:
        started_raw = str(rec or "")
    started_at = _parse_utc_timestamp(started_raw)
    if not started_at:
        if not create:
            now_dt = _now_utc()
            deadline = now_dt - timedelta(seconds=1)
            return {
                "allowed_seconds": allowed,
                "started_at": None,
                "deadline_at": deadline.isoformat(),
                "time_remaining_sec": 0,
                "is_late": True,
            }
        started_at = _now_utc()
        timers[key] = {"started_at": started_at.isoformat(), "allowed_seconds": allowed}
        _duel_persist_session(session)
    deadline = started_at + timedelta(seconds=allowed)
    now_dt = _now_utc()
    remaining = max(0, int(math.ceil((deadline - now_dt).total_seconds())))
    return {
        "allowed_seconds": allowed,
        "started_at": started_at.isoformat(),
        "deadline_at": deadline.isoformat(),
        "time_remaining_sec": remaining,
        "is_late": now_dt > deadline + timedelta(seconds=2),
    }


def _competition_seed_question_timer(
    session: dict[str, Any],
    user_id: int,
    question_index: int,
    question: dict[str, Any] | None = None,
    *,
    started_at: datetime | None = None,
) -> None:
    timers = session.setdefault("timers", {})
    key = f"{int(user_id)}:{int(question_index)}"
    rec = timers.get(key)
    if isinstance(rec, dict) and _parse_utc_timestamp(str(rec.get("started_at") or "")):
        return
    if not isinstance(rec, dict) and _parse_utc_timestamp(str(rec or "")):
        return
    questions = _competition_questions_for_user(session, int(user_id))
    q = question or (questions[int(question_index) - 1] if 0 < int(question_index) <= len(questions) else {})
    timers[key] = {
        "started_at": (started_at or _now_utc()).isoformat(),
        "allowed_seconds": int(_competition_question_allowed_seconds(q or {}, str(session.get("mode") or ""))),
    }


def _competition_seed_initial_question_timers(session: dict[str, Any], player_ids: list[int], *, started_at: datetime | None = None) -> None:
    start_dt = started_at or _now_utc()
    for uid in [int(x) for x in player_ids if int(x) > 0]:
        questions = _competition_questions_for_user(session, uid)
        if questions:
            _competition_seed_question_timer(session, uid, 1, questions[0], started_at=start_dt)


def _competition_apply_question_outcome(
    session: dict[str, Any],
    user_id: int,
    question_index: int,
    selected: int | None,
    timer_state: dict[str, Any],
) -> bool:
    uid = int(user_id)
    progress = _competition_user_progress(session, uid)
    if not progress:
        return False
    questions = _competition_questions_for_user(session, uid)
    total = len(questions)
    q_index = int(question_index or progress.get("index") or 1)
    if q_index <= 0 or q_index > total:
        return False
    current_index = int(progress.get("index") or 1)
    if current_index != q_index:
        return False

    q = questions[q_index - 1]
    is_late = bool(timer_state.get("is_late"))
    is_correct = False
    is_unanswered = selected is None or is_late
    if is_unanswered:
        progress["unanswered"] = int(progress.get("unanswered") or 0) + 1
    else:
        selected_idx = int(selected)
        if selected_idx < 0 or selected_idx > 3:
            raise HTTPException(status_code=400, detail="selected_option_index must be between 0 and 3")
        if _selected_option_is_correct(q, selected_idx):
            progress["correct"] = int(progress.get("correct") or 0) + 1
            is_correct = True
        else:
            progress["wrong"] = int(progress.get("wrong") or 0) + 1

    _duel_persist_answer(
        session,
        uid,
        q_index,
        None if selected is None else int(selected),
        is_correct=is_correct,
        is_unanswered=is_unanswered,
        is_late=is_late,
        timer_state=timer_state,
    )
    if str(session.get("mode") or "") == "group" and int(session.get("external_group_arena_session_id") or 0) > 0:
        _safe_call(
            lambda: update_arena_group_session_attempt_progress(
                session_id=int(session.get("external_group_arena_session_id") or 0),
                user_id=int(uid),
                correct=int(progress.get("correct") or 0),
                wrong=int(progress.get("wrong") or 0),
                unanswered=int(progress.get("unanswered") or 0),
            ),
            None,
        )

    progress["index"] = q_index + 1
    if int(progress.get("index") or 1) > total and not progress.get("finished_at"):
        progress["finished_at"] = _now_utc().isoformat()
    session.setdefault("timers", {}).pop(f"{uid}:{q_index}", None)
    next_index = q_index + 1
    if next_index <= total:
        _competition_seed_question_timer(session, uid, next_index, questions[next_index - 1])
    return True


def _competition_all_progress_finished(session: dict[str, Any]) -> bool:
    progress_map = session.get("progress") or {}
    if not progress_map:
        return False
    for pid, row in progress_map.items():
        try:
            uid = int(pid)
        except Exception:
            continue
        total = len(_competition_questions_for_user(session, uid))
        if total > 0 and int((row or {}).get("index") or 1) <= total:
            return False
    return True


def _competition_finalize_if_all_progress_finished(session: dict[str, Any]) -> bool:
    if _competition_session_phase(session) != "active":
        return False
    if not _competition_all_progress_finished(session):
        return False
    mode = str(session.get("mode") or "")
    if mode == "daily":
        _competition_finalize_daily_stage(session)
        if _competition_session_phase(session) == "generating":
            next_stage = int(session.get("stage") or 1) + 1
            asyncio.create_task(
                _competition_start_generation(
                    str(session.get("id") or ""),
                    stage=next_stage,
                    generation_token=str(session.get("generation_token") or ""),
                )
            )
        return True
    _competition_finalize_non_daily(session)
    return True


def _competition_auto_skip_due_questions(session: dict[str, Any], now: datetime | None = None) -> bool:
    if not session or _competition_session_phase(session) != "active":
        return False
    changed = False
    for row in list(session.get("participants") or []):
        uid = int(row.get("user_id") or 0)
        if uid <= 0:
            continue
        status = str(row.get("status") or "active").strip().lower()
        reason = str(row.get("left_reason") or row.get("reason") or "").strip().lower()
        is_explicit_left = status == "left" and reason in _COMPETITION_EXPLICIT_LEFT_REASONS
        is_terminal_failure = status in {"cancelled", "blocked", "failed"}
        if is_explicit_left or is_terminal_failure:
            if _competition_finish_user_remaining_questions(session, uid, reason=str(row.get("left_reason") or status)):
                changed = True
    if _competition_finalize_if_all_progress_finished(session):
        return True
    iterations = 0
    while _competition_session_phase(session) == "active" and iterations < 200:
        iterations += 1
        now_dt = now or _now_utc()
        due: list[tuple[int, int, dict[str, Any]]] = []
        for pid, progress in list((session.get("progress") or {}).items()):
            try:
                uid = int(pid)
            except Exception:
                continue
            if not isinstance(progress, dict):
                continue
            questions = _competition_questions_for_user(session, uid)
            total = len(questions)
            q_index = int(progress.get("index") or 1)
            if q_index <= 0 or q_index > total:
                continue
            timer_state = _competition_timer_state(session, uid, q_index, questions[q_index - 1], create=True)
            deadline = _parse_utc_timestamp(str(timer_state.get("deadline_at") or ""))
            if deadline and now_dt > deadline + timedelta(seconds=2):
                due.append((uid, q_index, {**timer_state, "is_late": True, "time_remaining_sec": 0}))
        if not due:
            break
        for uid, q_index, timer_state in due:
            if _competition_apply_question_outcome(session, uid, q_index, None, timer_state):
                changed = True
        _duel_persist_session(session)
        if _competition_finalize_if_all_progress_finished(session):
            changed = True
            break
    if iterations >= 200:
        logger.warning("competition auto-skip iteration cap reached session_id=%s", session.get("id"))
    if changed and _competition_session_phase(session) != "finished":
        _duel_persist_session(session)
    return changed


def _competition_timer_remaining(session: dict, user_id: int, question_index: int) -> int:
    return int(_competition_timer_state(session, user_id, question_index).get("time_remaining_sec") or 0)


def _competition_live_lists(session: dict) -> dict:
    remained = []
    left = []
    for row in session.get("participants") or []:
        status = str(row.get("status") or "active")
        name = str(row.get("name") or "Player")
        if status in {"left", "eliminated", "finished", "cancelled", "blocked", "failed"}:
            left.append(name)
        else:
            remained.append(name)
    return {"remained": remained, "left": left}


def _competition_boss_summary(session: dict[str, Any]) -> dict[str, Any] | None:
    if str(session.get("mode") or "") != "boss":
        return None
    result = session.get("result") or {}
    by_user = result.get("by_user") or {}
    rows: list[dict[str, Any]] = []
    total_correct = 0
    total_possible = 0
    for participant in _competition_joined_participants(session):
        uid = int(participant.get("user_id") or 0)
        own = by_user.get(uid) or by_user.get(str(uid)) or {}
        correct = int(own.get("correct") or 0)
        total_q = int(own.get("total_questions") or len(_competition_questions_for_user(session, uid)) or 0)
        reward = float(own.get("dpoints_delta") or 0.0)
        total_correct += correct
        total_possible += max(0, total_q)
        rows.append(
            {
                "user_id": uid,
                "name": participant.get("name") or f"Player {uid}",
                "correct": correct,
                "total_questions": total_q,
                "dpoints_delta": reward,
            }
        )
    global_accuracy = round((total_correct * 100.0) / float(max(1, total_possible)), 2)
    if session.get("boss_global_accuracy") is not None:
        global_accuracy = round(float(session.get("boss_global_accuracy") or 0.0), 2)
    rules = _competition_rule_settings()
    threshold = float(session.get("boss_threshold_percent") or rules.get("boss_arena_global_threshold_percent") or 86.0)
    per_correct = float(session.get("boss_reward_per_correct") or rules.get("boss_arena_reward_per_correct") or 3.0)
    return {
        "participant_count": len(rows),
        "total_correct": total_correct,
        "total_possible": total_possible,
        "global_accuracy": global_accuracy,
        "passed": global_accuracy >= threshold,
        "reward_per_correct": per_correct,
        "threshold_percent": threshold,
        "participants": rows,
    }


def _competition_bot_mode(mode: str) -> str:
    if mode == "duel-1v1":
        return "1v1"
    if mode == "duel-3v3":
        return "3v3"
    if mode == "duel-5v5":
        return "5v5"
    return mode


def _competition_session_matches_request(session: dict[str, Any], mode: str, subject: str, group_id: int | None = None) -> bool:
    if not session:
        return False
    if str(session.get("mode") or "") != str(mode or ""):
        return False
    if _normalize_subject_label(str(session.get("subject") or "")) != _normalize_subject_label(subject):
        return False
    if str(mode or "") == "group":
        return int(session.get("group_id") or 0) == int(group_id or 0)
    return True


def _competition_section_for_mode(mode: str) -> str:
    mapping = {
        "daily": "arena-daily",
        "group": "arena-group",
        "boss": "arena-boss",
        "duel-1v1": "duel-1v1",
        "duel-3v3": "duel-3v3",
        "duel-5v5": "duel-5v5",
    }
    return mapping.get(mode, "arena")


def _competition_entry_fee(mode: str) -> float:
    normalized = str(mode or "").strip().lower()
    if normalized == "group":
        return 0.0
    settings = _get_runtime_settings()
    fallback = float(settings.get("entry_fee_dcoin") or 3.0)
    if normalized.startswith("duel-"):
        return max(0.0, float(settings.get("duel_entry_fee_dcoin") or fallback))
    if normalized in {"daily", "boss"}:
        return max(0.0, float(settings.get("arena_entry_fee_dcoin") or fallback))
    return max(0.0, fallback)


def _competition_schedule_start(mode: str, subject: str) -> str | None:
    subj = _normalize_subject_label(subject) or "English"
    if mode == "daily":
        return _get_daily_arena_schedule_times().get(subj)
    # Boss Arena and Duels are intentionally always-open queue modes.
    return None


def _competition_is_within_join_window(mode: str, subject: str) -> tuple[bool, str]:
    hhmm = _competition_schedule_start(mode, subject)
    if not hhmm:
        return True, ""
    now = _now_tashkent()
    try:
        hh, mm = [int(x) for x in hhmm.split(":", 1)]
        start_dt = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
    except Exception:
        return True, ""
    open_dt = start_dt - timedelta(minutes=5)
    close_dt = start_dt + timedelta(minutes=1)
    if open_dt <= now <= close_dt:
        return True, hhmm
    return False, hhmm


@app.get("/student/support/branches")
async def student_support_branches(
    subject: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    student_subjects = _support_enabled_subjects_for_user(user)
    teacher_subjects = _active_support_teacher_subjects()
    available_subjects = [item for item in student_subjects if item in teacher_subjects]
    requested_subject = _normalize_subject_label(subject)
    support_subjects = available_subjects or student_subjects
    selected_subject = requested_subject or (support_subjects[0] if support_subjects else None)
    if selected_subject and selected_subject not in support_subjects:
        selected_subject = support_subjects[0] if support_subjects else None
    has_support_teacher = _has_active_support_teacher_for_subject(selected_subject)
    support_enabled = bool(support_subjects) and bool(selected_subject) and has_support_teacher
    items = []
    for key, label in SUPPORT_BRANCHES.items():
        items.append(
            {
                "key": key,
                "label": label,
                "weekdays": get_lesson_branch_weekdays(key),
            }
        )
    # Build teachers list for the selected subject
    teachers_list: list[dict] = []
    if selected_subject:
        for teacher_row in _active_support_teacher_rows_for_subject(selected_subject):
            tid = int(teacher_row.get("id") or 0)
            if tid <= 0:
                continue
            weekday_settings = _support_weekday_settings_for_teacher(tid, selected_subject)
            active_branches: list[str] = []
            for ws in weekday_settings:
                if int(ws.get("active") or 0) == 1 and ws.get("branch"):
                    b = str(ws["branch"])
                    if b not in active_branches:
                        active_branches.append(b)
            teachers_list.append({
                "id": tid,
                "name": _display_name(teacher_row),
                "subject": selected_subject,
                "active_branches": active_branches,
                "weekday_settings": [
                    {
                        "weekday": int(ws.get("weekday") or 0),
                        "active": bool(int(ws.get("active") or 0) == 1),
                        "branch": ws.get("branch"),
                    }
                    for ws in weekday_settings
                ],
            })
    return {
        "enabled": support_enabled,
        "support_subjects": support_subjects,
        "selected_subject": selected_subject,
        "has_support_teacher": has_support_teacher,
        "no_support_teacher": bool(selected_subject) and not has_support_teacher,
        "items": items,
        "teachers": teachers_list,
        "booking_guard": _student_support_booking_guard_payload(user_id, selected_subject),
    }


@app.get("/student/support/available-dates")
async def student_support_available_dates(
    branch: str,
    subject: str | None = Query(default=None),
    teacher_id: int | None = Query(default=None),
    days_ahead: int = Query(default=14, ge=1, le=30),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    support_subjects = _support_enabled_subjects_for_user(user)
    selected_subject = _normalize_subject_label(subject) or (support_subjects[0] if support_subjects else None)
    if not selected_subject or selected_subject not in support_subjects:
        raise HTTPException(status_code=403, detail="Support lessons are available only for English subject")
    # If a specific teacher is requested, validate they exist for this subject
    selected_teacher_id: int | None = None
    if teacher_id and int(teacher_id) > 0:
        teacher_rows = _active_support_teacher_rows_for_subject(selected_subject)
        valid_ids = {int(r.get("id") or 0) for r in teacher_rows}
        if int(teacher_id) in valid_ids:
            selected_teacher_id = int(teacher_id)
    if selected_teacher_id is None and not _has_active_support_teacher_for_subject(selected_subject):
        raise HTTPException(status_code=409, detail="No support teacher available for selected subject")
    branch_key = _validate_branch_key(branch)
    return {
        "branch": branch_key,
        "subject": selected_subject,
        "teacher_id": selected_teacher_id,
        "items": _support_allowed_dates_payload(branch_key, days_ahead=days_ahead, subject=selected_subject),
    }


@app.get("/student/support/available-times")
async def student_support_available_times(
    branch: str,
    date: str,
    subject: str | None = Query(default=None),
    teacher_id: int | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    support_subjects = _support_enabled_subjects_for_user(user)
    selected_subject = _normalize_subject_label(subject) or (support_subjects[0] if support_subjects else None)
    if not selected_subject or selected_subject not in support_subjects:
        raise HTTPException(status_code=403, detail="Support lessons are available only for English subject")
    # If a specific teacher is requested, validate they exist for this subject
    selected_teacher_id: int | None = None
    if teacher_id and int(teacher_id) > 0:
        teacher_rows = _active_support_teacher_rows_for_subject(selected_subject)
        valid_ids = {int(r.get("id") or 0) for r in teacher_rows}
        if int(teacher_id) in valid_ids:
            selected_teacher_id = int(teacher_id)
    if selected_teacher_id is None and not _has_active_support_teacher_for_subject(selected_subject):
        raise HTTPException(status_code=409, detail="No support teacher available for selected subject")
    branch_key = _validate_branch_key(branch)
    date_iso = _validate_iso_date(date)
    raw_items = _support_available_times_payload(branch_key, date_iso, subject=selected_subject)
    # Annotate each free slot with available teachers for auto-selection
    enriched_items: list[dict] = []
    for slot in raw_items:
        slot_copy = dict(slot)
        if slot.get("status") == "free" and selected_subject:
            candidates = _support_teacher_candidates_for_slot(selected_subject, branch_key, date_iso, str(slot["time"]))
            slot_copy["available_teachers"] = [
                {"id": int(c.get("id") or 0), "name": _display_name(c)}
                for c in candidates
                if int(c.get("id") or 0) > 0
            ]
        else:
            slot_copy["available_teachers"] = []
        enriched_items.append(slot_copy)
    return {
        "branch": branch_key,
        "date": date_iso,
        "subject": selected_subject,
        "teacher_id": selected_teacher_id,
        "items": enriched_items,
    }


@app.get("/student/support/available-teachers")
async def student_support_available_teachers(
    branch: str,
    date: str,
    time: str,
    subject: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    """Return teachers available for a specific branch+date+time+subject combination."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    support_subjects = _support_enabled_subjects_for_user(user)
    selected_subject = _normalize_subject_label(subject) or (support_subjects[0] if support_subjects else None)
    if not selected_subject or selected_subject not in support_subjects:
        raise HTTPException(status_code=403, detail="Subject not available")
    branch_key = _validate_branch_key(branch)
    date_iso = _validate_iso_date(date)
    time_normalized = normalize_time_hhmm(str(time or "").strip())
    if not time_normalized:
        raise HTTPException(status_code=400, detail="Invalid time format")
    candidates = _support_teacher_candidates_for_slot(selected_subject, branch_key, date_iso, time_normalized)
    teachers = [
        {"id": int(c.get("id") or 0), "name": _display_name(c)}
        for c in candidates
        if int(c.get("id") or 0) > 0
    ]
    return {
        "branch": branch_key,
        "date": date_iso,
        "time": time_normalized,
        "subject": selected_subject,
        "teachers": teachers,
        "auto_selected": teachers[0] if len(teachers) == 1 else None,
    }


