@app.post("/student/gifts/chest/open")
async def student_open_gift_chest(payload: ChestOpenRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    lang = _gift_locale(user.get("language")) or "uz"
    cost = float(payload.cost_dcoin or 1000.0)
    if abs(cost - 1000.0) > 0.0001:
        raise HTTPException(status_code=400, detail="Chest cost must be exactly 1000 D'coin")

    # Security: per-user cooldown — prevent rapid chest spam
    now_mono = time.monotonic()
    last_ts = _CHEST_OPEN_LAST_TS.get(user_id, 0.0)
    if now_mono - last_ts < _CHEST_OPEN_COOLDOWN_SECONDS:
        wait = round(_CHEST_OPEN_COOLDOWN_SECONDS - (now_mono - last_ts), 1)
        raise HTTPException(status_code=429, detail=f"Please wait {wait}s before opening another chest")
    _CHEST_OPEN_LAST_TS[user_id] = now_mono

    active_gifts = _safe_call(lambda: list_gifts(active_only=True), []) or []
    winner = _weighted_pick_gift(active_gifts)
    if not winner:
        raise HTTPException(status_code=409, detail="No active gifts available")

    winner_id = int(winner.get("id") or 0)
    awarded_tickets = 1
    roulette_payload = _json_text(
        {
            "weights": [
                {
                    "gift_id": int(item.get("id") or 0),
                    "title": item.get("title"),
                    "weight": _safe_probability_weight(item.get("probability_weight")),
                }
                for item in active_gifts
            ],
            "winner_id": winner_id,
        }
    )
    purchase = open_gift_chest_atomic(
        user_id=user_id,
        winner_gift_id=winner_id,
        winner_title=str(winner.get("title") or "").strip() or "Gift Chest",
        cost_dcoin=cost,
        awarded_tickets=awarded_tickets,
        roulette_payload_json=roulette_payload,
    )
    if not purchase.get("ok"):
        reason = str(purchase.get("reason") or "transaction_failed")
        if reason == "insufficient_balance":
            raise HTTPException(status_code=409, detail="Insufficient D'coin balance")
        raise HTTPException(status_code=500, detail="Could not open gift chest")

    ticket_row = purchase.get("ticket") if isinstance(purchase.get("ticket"), dict) else None
    # Chest ochilishi xarid sifatida hisoblanmaydi — admin ga bildirish yo'q
    return {
        "message": "Chest opened",
        "spin_id": int(purchase.get("spin_id") or 0),
        "winner": _serialize_gift_row(winner, ticket_count=int(ticket_row.get("ticket_count") or 0) if ticket_row else 0, lang=lang),
        "awarded_tickets": awarded_tickets,
        "wallet_dcoin": float(purchase.get("balance_after") or 0.0),
        "roulette_items": [_serialize_gift_row(item, lang=lang) for item in active_gifts],
    }


@app.post("/student/gifts/{gift_id}/purchase")
async def student_purchase_gift(gift_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    lang = _gift_locale(user.get("language")) or "uz"
    result = purchase_gift_with_tickets_atomic(user_id=user_id, gift_id=int(gift_id))
    if not result.get("ok"):
        reason = str(result.get("reason") or "transaction_failed")
        if reason == "gift_not_found":
            raise HTTPException(status_code=404, detail="Gift not found")
        if reason == "insufficient_tickets":
            raise HTTPException(
                status_code=409,
                detail={
                    "message": "Sovga uchun ticketlar yetarli emas",
                    "ticket_count": int(result.get("ticket_count") or 0),
                    "required_tickets": int(result.get("required_tickets") or 0),
                },
            )
        if reason == "insufficient_balance":
            raise HTTPException(status_code=409, detail="D'coin balans yetarli emas")
        if reason == "accountless_user":
            raise HTTPException(status_code=403, detail="Accountless users cannot purchase gifts")
        raise HTTPException(status_code=500, detail="Could not purchase gift")
    gift = result.get("gift") if isinstance(result.get("gift"), dict) else {}
    ticket = result.get("ticket") if isinstance(result.get("ticket"), dict) else {}
    ticket_count = int(ticket.get("ticket_count") or 0) if ticket else 0
    payment_discount = _safe_call(
        lambda: _apply_gift_payment_discount_purchase(user, gift, int(result.get("purchase_id") or 0)),
        None,
    )
    await _notify_admins_purchase_created(
        buyer=user,
        item_type="gift",
        item_title=str(gift.get("title") or "").strip() or "Gift",
        amount_spent=float(gift.get("price_dcoin") or 0.0),
        balance_after=float(result.get("balance_after") or 0.0),
        purchase_history_id=int(result.get("purchase_id") or 0),
        item_id=int(gift.get("id") or gift_id),
        source_page="student_gifts",
    )
    return {
        "message": "Gift purchased",
        "item": _serialize_gift_row(gift, ticket_count=ticket_count, lang=lang),
        "wallet_dcoin": float(result.get("balance_after") or 0.0),
        "ticket_count": ticket_count,
        "payment_discount": payment_discount,
    }


