@app.post("/admin/gifts")
async def admin_create_gift(payload: GiftCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    if not str(payload.title or "").strip():
        raise HTTPException(status_code=400, detail="Gift title is required")
    if float(payload.probability_weight) not in GIFT_PROBABILITY_OPTIONS:
        raise HTTPException(status_code=400, detail="Probability must be from fixed options list")
    if bool(payload.is_payment_discount) and float(payload.payment_discount_percent or 0.0) <= 0:
        raise HTTPException(status_code=400, detail="Payment discount percent is required")
    try:
        created = create_gift(
            title=payload.title,
            description=payload.description,
            title_uz=payload.title_uz,
            title_ru=payload.title_ru,
            title_en=payload.title_en,
            description_uz=payload.description_uz,
            description_ru=payload.description_ru,
            description_en=payload.description_en,
            image_url=payload.image_url,
            price_dcoin=float(payload.price_dcoin or 0),
            required_tickets=int(payload.required_tickets or 1),
            probability_weight=float(payload.probability_weight or 1),
            active=bool(payload.active),
            created_by=int(user.get("id") or 0),
            is_payment_discount=bool(payload.is_payment_discount),
            payment_discount_percent=float(payload.payment_discount_percent or 0.0),
        )
    except Exception as exc:
        logger.exception("admin.gifts.create failed admin_id=%s title=%s", int(user.get("id") or 0), payload.title)
        raise HTTPException(status_code=500, detail=f"Could not create gift: {str(exc)[:220]}") from exc
    if not created:
        raise HTTPException(status_code=422, detail="Could not create gift")
    return {"message": "Gift created", "item": _serialize_gift_row(created)}


