def _normalize_homework_kind(value: Any) -> str:
    raw = str(value or "both").strip().lower()
    return raw if raw in {"list", "test", "both"} else "both"


def _derive_homework_kind_from_request(payload: HomeworkCreateRequest) -> str:
    if payload.requires_upload is not None or payload.requires_test is not None:
        requires_upload = bool(payload.requires_upload) or bool(payload.requires_file) or bool(payload.requires_voice_message) or bool(payload.is_voiceroom)
        requires_test = bool(payload.requires_test)
        if requires_upload and requires_test:
            return "both"
        if requires_test:
            return "test"
        if requires_upload:
            return "list"
        raise HTTPException(status_code=400, detail="Homework uchun list yoki testdan kamida bittasini tanlang")
    return _normalize_homework_kind(payload.homework_kind)


def _parse_homework_due_at(raw: Any) -> datetime | None:
    value = str(raw or "").strip()
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except Exception:
        try:
            parsed = datetime.strptime(value[:19].replace("T", " "), "%Y-%m-%d %H:%M:%S")
        except Exception:
            return None
    if parsed.tzinfo is None:
        return TASHKENT_TZ.localize(parsed)
    return parsed.astimezone(TASHKENT_TZ)


def _homework_deadline_has_passed(row: dict[str, Any]) -> bool:
    due_at = _parse_homework_due_at(row.get("due_at"))
    return bool(due_at and due_at <= _now_tashkent())


def _apply_homework_deadline_penalties(rows: list[dict[str, Any]]) -> bool:
    settings = _get_runtime_settings() or {}
    penalty_abs = abs(float(settings.get("homework_deadline_missed_penalty_dpoints") or 0.0))
    if penalty_abs <= 0:
        return False
    applied_any = False
    for row in rows:
        homework_id = int(row.get("id") or 0)
        student_id = int(row.get("_viewer_student_id") or row.get("submission_student_id") or row.get("student_id") or row.get("homework_student_id") or 0)
        if homework_id <= 0 or student_id <= 0:
            continue
        if row.get("submission_status") or row.get("submission_student_id") or row.get("reviewed_at"):
            continue
        if not _homework_deadline_has_passed(row):
            continue
        penalty = -penalty_abs
        try:
            marker = record_homework_deadline_penalty(homework_id, student_id, penalty)
            if not marker:
                continue
            student = _safe_call(lambda sid=student_id: get_user_by_id(sid), {}) or {}
            add_dpoints(
                student_id,
                penalty,
                subject=(_user_subjects_from_row(student) or ["GLOBAL"])[0],
                change_type=f"homework_deadline_missed:{homework_id}",
            )
            applied_any = True
        except Exception:
            logger.exception("homework deadline penalty failed homework_id=%s student_id=%s", homework_id, student_id)
    return applied_any


def _homework_proof_images_from_row(row: dict | None) -> list[str]:
    if not row:
        return []
    images: list[str] = []
    raw_json = row.get("proof_images_json")
    if raw_json:
        try:
            parsed = json.loads(str(raw_json))
            if isinstance(parsed, list):
                images.extend(str(item or "").strip() for item in parsed)
        except Exception:
            pass
    single = str(row.get("proof_image_url") or "").strip()
    if single:
        images.insert(0, single)
    out: list[str] = []
    seen: set[str] = set()
    for image in images:
        if image and image not in seen:
            out.append(image)
            seen.add(image)
    return out[:12]


def _homework_proof_images_from_payload(payload: HomeworkSubmitRequest) -> list[str]:
    raw_items = list(payload.proof_images or [])
    if payload.proof_image_url:
        raw_items.insert(0, payload.proof_image_url)
    out: list[str] = []
    seen: set[str] = set()
    for item in raw_items:
        clean = str(item or "").strip()
        if clean and clean not in seen:
            out.append(clean)
            seen.add(clean)
    return out[:12]


def _attach_homework_runtime_fields(row: dict) -> dict:
    kind = _normalize_homework_kind(row.get("homework_kind"))
    row["homework_kind"] = kind
    row["requires_upload"] = kind in {"list", "both"}
    row["requires_test"] = kind in {"test", "both"}
    row["proof_images"] = _homework_proof_images_from_row(row)
    row["dpoints_delta"] = float(row.get("dpoints_delta") if row.get("dpoints_delta") is not None else row.get("dcoin_delta") or 0.0)
    # Deadline o'tib, hech narsa topshirilmagan — avtomatik "qilinmadi".
    # (test_topshirilgan bo'lsa keyingi qadamda tozalanadi)
    row["deadline_missed"] = bool(
        not (row.get("submission_status") or row.get("submission_student_id") or row.get("reviewed_at"))
        and _homework_deadline_has_passed(row)
    )
    return row


def _strip_notification_html(text: str) -> str:
    """Telegram uchun yozilgan HTML teglarni (<b>, <i>, <a>...) web/push
    bildirishnomadan olib tashlaydi va asosiy entity'larni oddiy belgiga aylantiradi."""
    raw = str(text or "")
    if "<" in raw:
        raw = re.sub(r"<[^>]+>", "", raw)
    return (
        raw.replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", '"')
        .replace("&#39;", "'")
    ).strip()


def _store_browser_notification_for_user(
    user_id: int,
    *,
    notification_type: str,
    title: str,
    message: str,
    button_text: str,
    button_url: str,
    target_screen: str,
    source_key: str,
    meta: dict[str, Any] | None = None,
) -> None:
    uid = int(user_id or 0)
    if uid <= 0:
        return
    # Web/push bildirishnomalar HTML render qilmaydi — Telegram uchun yozilgan
    # <b>...</b> kabi teglarni olib tashlaymiz (aks holda ular ko'rinib qoladi).
    title = _strip_notification_html(title)
    message = _strip_notification_html(message)
    conn = get_conn()
    cur = conn.cursor()
    try:
        _payment_upsert_web_notification(
            cur,
            user_id=uid,
            notification_type=notification_type,
            title=title,
            message=message,
            button_text=button_text,
            button_url=button_url,
            target_screen=target_screen,
            source_key=source_key,
            meta=meta or {},
        )
        conn.commit()
        _invalidate_notification_unread_count(uid)
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("homework browser notification failed user_id=%s type=%s", uid, notification_type)
    finally:
        conn.close()


def _homework_audience_student_ids(homework: dict | None) -> list[int]:
    if not homework:
        return []
    group_id = int(homework.get("group_id") or 0)
    if group_id > 0:
        members = _safe_call(lambda: get_group_users(group_id), []) or []
        return sorted({
            int(member.get("id") or 0)
            for member in members
            if int(member.get("id") or 0) > 0 and int(member.get("login_type") or 0) in (1, 2, 6)
        })
    sid = int(homework.get("student_id") or 0)
    return [sid] if sid > 0 else []


async def _notify_homework_created(homework: dict, teacher: dict, student_ids: Iterable[int]) -> None:
    title = str(homework.get("title") or "Homework").strip()
    teacher_name = _display_name(teacher) if teacher else "Teacher"
    web_path = "/?role=student&section=homework"
    tg_url = f"{WEBAPP_URL}{web_path}" if WEBAPP_URL else None
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    kind = str(homework.get("homework_kind") or "both")
    for student_id in sorted({int(sid) for sid in student_ids if int(sid or 0) > 0}):
        student = _safe_call(lambda sid=student_id: get_user_by_id(sid), None) or {}
        lang = str(student.get("language") or "uz")
        
        is_voiceroom = int(homework.get("is_voiceroom") or 0) == 1
        if is_voiceroom:
            type_str = t(lang, "homework.type.voiceroom") or "VoiceRoom suhbati"
        elif kind == "test":
            type_str = t(lang, "homework.type.test") or "Test"
        elif kind == "list":
            type_str = t(lang, "homework.type.list") or "Fayl/izoh yuklash"
        else:
            type_str = t(lang, "homework.type.both") or "Test va fayl/izoh"
            
        message = t(lang, "notification_new_homework", title=title, teacher_name=teacher_name)
        message += f"\n\n{t(lang, 'homework.type.label') or 'Vazifa turi'}: {type_str}"
        
        if is_voiceroom:
            def _get_voiceroom_partner_names(hw_id: int, sid: int) -> str | None:
                from db import get_conn
                conn = get_conn()
                cur = conn.cursor()
                try:
                    cur.execute("""
                        SELECT v.student1_id, v.student2_id, v.student3_id,
                               u1.first_name AS student1_name,
                               u2.first_name AS student2_name,
                               u3.first_name AS student3_name
                        FROM web_homework_voiceroom_groups v
                        LEFT JOIN users u1 ON u1.id=v.student1_id
                        LEFT JOIN users u2 ON u2.id=v.student2_id
                        LEFT JOIN users u3 ON u3.id=v.student3_id
                        WHERE v.homework_id=%s AND (v.student1_id=%s OR v.student2_id=%s OR v.student3_id=%s)
                    """, (hw_id, sid, sid, sid))
                    row = cur.fetchone()
                    if not row: return None
                    partners = []
                    if int(row["student1_id"] or 0) > 0 and int(row["student1_id"]) != sid: partners.append(row["student1_name"])
                    if int(row.get("student2_id") or 0) > 0 and int(row["student2_id"]) != sid: partners.append(row["student2_name"])
                    if int(row.get("student3_id") or 0) > 0 and int(row["student3_id"]) != sid: partners.append(row["student3_name"])
                    return ", ".join(p for p in partners if p)
                except Exception: return None
                finally: conn.close()
            partners_str = _get_voiceroom_partner_names(int(homework.get("id") or 0), student_id)
            if partners_str:
                partner_label = t(lang, "homework.voiceroom.partner") or "🤝 Sizning sherigingiz:"
                message += f"\n{partner_label} {partners_str}"
                
        button_text = t(lang, "homework_btn_open") or "Homeworkni ochish"
        _store_browser_notification_for_user(
            student_id,
            notification_type="homework_created",
            title=t(lang, "student.homework.new") or "Yangi uy vazifasi",
            message=message,
            button_text=button_text,
            button_url=web_path,
            target_screen="homework",
            source_key=f"homework_created:{int(homework.get('id') or 0)}:{student_id}",
            meta={"homework_id": int(homework.get("id") or 0), "teacher_id": int(homework.get("teacher_id") or 0)},
        )
        tg = str(student.get("telegram_id") or "").strip()
        if token and tg:
            await _send_telegram_text(token, tg, message, button_text=button_text, button_url=tg_url, button_web_app=True, parse_mode="HTML")


async def _notify_homework_submitted(homework: dict, student: dict, submission: dict | None) -> None:
    teacher = _safe_call(lambda: get_user_by_id(int(homework.get("teacher_id") or 0)), None) or {}
    teacher_id = int(teacher.get("id") or homework.get("teacher_id") or 0)
    if teacher_id <= 0:
        return
    student_name = _display_name(student) if student else f"Student #{int((submission or {}).get('student_id') or 0)}"
    title = str(homework.get("title") or "Homework").strip()
    message = f"{student_name} homework topshirdi: {title}"
    web_path = f"/?role=teacher&section=homework&homework_id={int(homework.get('id') or 0)}"
    tg_url = f"{WEBAPP_URL}{web_path}" if WEBAPP_URL else None
    _store_browser_notification_for_user(
        teacher_id,
        notification_type="homework_submitted",
        title="Homework topshirildi",
        message=message,
        button_text="Tekshirish",
        button_url=web_path,
        target_screen="homework",
        source_key=f"homework_submitted:{int(homework.get('id') or 0)}:{int(student.get('id') or 0)}",
        meta={"homework_id": int(homework.get("id") or 0), "student_id": int(student.get("id") or 0)},
    )
    token = (os.getenv("TEACHER_BOT_TOKEN") or _tg_token_for_login_type(int(teacher.get("login_type") or 3))).strip()
    tg = str(teacher.get("telegram_id") or "").strip()
    if token and tg:
        await _send_telegram_text(token, tg, message, button_text="Tekshirish", button_url=tg_url)
        if submission:
            proofs = []
            if submission.get("proof_images_json"):
                try:
                    import json
                    proofs.extend(json.loads(submission["proof_images_json"]))
                except Exception:
                    pass
            elif submission.get("proof_image_url"):
                proofs.append(submission["proof_image_url"])
            for p in proofs:
                p_name = Path(p).name
                if p_name:
                    local_path = HOMEWORK_UPLOAD_DIR / p_name
                    if local_path.exists():
                        await _send_telegram_file(token, tg, str(local_path), caption=f"{student_name} fayli")
            voice = submission.get("voice_message_url")
            if voice:
                v_name = Path(voice).name
                if v_name:
                    local_path = HOMEWORK_UPLOAD_DIR / v_name
                    if local_path.exists():
                        await _send_telegram_file(token, tg, str(local_path), caption=f"{student_name} audio xabari")


async def _notify_homework_reviewed(homework: dict, student_id: int, reviewed: dict | None, teacher: dict) -> None:
    student = _safe_call(lambda: get_user_by_id(int(student_id)), None) or {}
    lang = str(student.get("language") or "uz")
    title = str(homework.get("title") or "Homework").strip()
    delta = float((reviewed or {}).get("dpoints_delta") if (reviewed or {}).get("dpoints_delta") is not None else (reviewed or {}).get("dcoin_delta") or 0.0)
    
    is_done = str((reviewed or {}).get("status") or "").lower() != "not_done"
    status_text = t(lang, "homework_status_done") if is_done else t(lang, "homework_status_not_done")
    
    message = t(lang, "notification_homework_reviewed", title=title, status=status_text, delta=f"{delta:g}")
    button_text = t(lang, "homework_btn_open") or "Homeworkni ochish"
    
    web_path = "/?role=student&section=homework"
    tg_url = f"{WEBAPP_URL}{web_path}" if WEBAPP_URL else None
    _store_browser_notification_for_user(
        int(student_id),
        notification_type="homework_reviewed",
        title="Homework tekshirildi",
        message=message,
        button_text=button_text,
        button_url=web_path,
        target_screen="homework",
        source_key=f"homework_reviewed:{int(homework.get('id') or 0)}:{int(student_id)}",
        meta={"homework_id": int(homework.get("id") or 0), "teacher_id": int(teacher.get("id") or 0), "dpoints_delta": delta},
    )
    token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
    tg = str(student.get("telegram_id") or "").strip()
    if token and tg:
        await _send_telegram_text(token, tg, message, button_text=button_text, button_url=tg_url, button_web_app=True)


@app.post("/teacher/homework")
async def teacher_create_homework(payload: HomeworkCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    student_id = int(payload.student_id or 0)
    group_id = int(payload.group_id or 0)
    title = str(payload.title or "").strip()
    description = str(payload.description or "").strip()
    due_at = str(payload.due_at or "").strip()
    homework_kind = _derive_homework_kind_from_request(payload)
    requires_upload = homework_kind in {"list", "both"}
    if not title:
        raise HTTPException(status_code=400, detail="Homework title is required")
    if (requires_upload or payload.requires_file or payload.requires_voice_message) and not description:
        raise HTTPException(status_code=400, detail="Homework description is required")
    if not due_at:
        raise HTTPException(status_code=400, detail="Homework deadline is required")
    audience_count = 0
    if group_id > 0:
        group = _safe_call(lambda: get_group(group_id), None)
        if not group:
            raise HTTPException(status_code=404, detail="Group not found")
        if not _teacher_can_manage_group(user, group):
            raise HTTPException(status_code=403, detail="Teacher can assign homework only to own or temporary groups")
        group_members = _safe_call(lambda gid=group_id: get_group_users(gid), []) or []
        group_student_count = len([row for row in group_members if int(row.get("login_type") or 0) in (1, 2, 6)])
        if group_student_count <= 0:
            raise HTTPException(status_code=400, detail="Selected group has no students")
        audience_count = int(group_student_count)
        student_id = 0
    elif student_id > 0:
        if student_id not in _teacher_student_ids(teacher_id):
            raise HTTPException(status_code=403, detail="Teacher can assign homework only to own students")
        audience_count = 1
    else:
        raise HTTPException(status_code=400, detail="Select a group or student for homework")
        
    voiceroom_groups = []
    if payload.is_voiceroom and group_id > 0:
        if payload.voiceroom_groups:
            voiceroom_groups = payload.voiceroom_groups
        else:
            import random
            users = _safe_call(lambda: get_group_users(group_id), []) or []
            student_ids_list = [u['id'] for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
            random.shuffle(student_ids_list)
            for i in range(0, len(student_ids_list), 2):
                chunk = student_ids_list[i:i+2]
                if len(chunk) == 1 and voiceroom_groups:
                    voiceroom_groups[-1]["student3_id"] = chunk[0]
                    continue
                s1 = chunk[0]
                s2 = chunk[1] if len(chunk) > 1 else None
                vg = {"student1_id": s1}
                if s2: vg["student2_id"] = s2
                voiceroom_groups.append(vg)
            
    try:
        created = create_homework(
            teacher_id=teacher_id,
            student_id=student_id or None,
            title=title,
            description=description or ("Test homework" if homework_kind == "test" else ""),
            due_at=due_at,
            image_url=payload.image_url,
            dcoin_effect=0.0,
            group_id=group_id or None,
            homework_kind=homework_kind,
            requires_voice_message=payload.requires_voice_message or False,
            requires_file=payload.requires_file or False,
            is_voiceroom=payload.is_voiceroom or False,
            voiceroom_groups=voiceroom_groups,
        )
    except Exception as exc:
        logger.exception("teacher.homework.create failed teacher_id=%s student_id=%s group_id=%s", teacher_id, student_id, group_id)
        raise HTTPException(status_code=500, detail=f"Could not create homework: {str(exc)[:220]}") from exc
    if not created:
        raise HTTPException(status_code=422, detail="Could not create homework")
    try:
        _attach_homework_runtime_fields(created)
        await _notify_homework_created(created, user, _homework_audience_student_ids(created))
    except Exception:
        logger.exception("teacher.homework.create notification failed homework_id=%s", int(created.get("id") or 0))
    return {
        "message": "Homework created",
        "item": created,
        "target_type": "group" if group_id > 0 else "student",
        "audience_count": int(audience_count),
        "group_id": group_id if group_id > 0 else None,
        "student_id": student_id if student_id > 0 else None,
    }


@app.patch("/teacher/homework/{homework_id}")
async def teacher_update_homework(homework_id: int, payload: HomeworkCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    group_id = int(homework.get("group_id") or 0)
    is_owner = int(homework.get("teacher_id") or 0) == teacher_id
    teacher_can_manage_group = bool(group_id > 0 and _teacher_can_manage_group(user, _safe_call(lambda: get_group(group_id), None)))
    
    if not is_owner and not teacher_can_manage_group:
        student_id = int(homework.get("student_id") or 0)
        if student_id <= 0 or student_id not in _teacher_student_ids(teacher_id):
            raise HTTPException(status_code=403, detail="Only homework owner or active temporary teacher can edit")

    title = str(payload.title or "").strip()
    description = str(payload.description or "").strip()
    due_at = str(payload.due_at or "").strip()
    homework_kind = _derive_homework_kind_from_request(payload)
    requires_upload = homework_kind in {"list", "both"}
    if not title:
        raise HTTPException(status_code=400, detail="Homework title is required")
    if (requires_upload or payload.requires_file or payload.requires_voice_message) and not description:
        raise HTTPException(status_code=400, detail="Homework description is required")
    if not due_at:
        raise HTTPException(status_code=400, detail="Homework deadline is required")
    try:
        updated = update_homework(
            int(homework_id),
            title=title,
            description=description or ("Test homework" if homework_kind == "test" else ""),
            due_at=due_at,
            image_url=payload.image_url,
            dcoin_effect=0.0,
            homework_kind=homework_kind,
            requires_voice_message=payload.requires_voice_message or False,
            requires_file=payload.requires_file or False,
        )
    except Exception as exc:
        logger.exception("teacher.homework.update failed teacher_id=%s homework_id=%s", teacher_id, homework_id)
        raise HTTPException(status_code=500, detail=f"Could not update homework: {str(exc)[:220]}") from exc
    if not updated:
        raise HTTPException(status_code=422, detail="Could not update homework")
    _attach_homework_runtime_fields(updated)
    return {"message": "Homework updated", "item": updated}


@app.delete("/teacher/homework/{homework_id}")
async def teacher_delete_homework(homework_id: int, authorization: str | None = Header(default=None)):
    """Teacher O'ZI bergan homeworkni o'chiradi (soft delete — status='deleted',
    student va teacher ro'yxatlaridan yo'qoladi). Admin har qanday homeworkni."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    role = _role_from_login_type(int(user.get("login_type") or 0), str(user.get("login_id") or ""))
    is_owner = int(homework.get("teacher_id") or 0) == teacher_id
    if not is_owner and role != "admin":
        raise HTTPException(status_code=403, detail="Faqat o'zingiz bergan homeworkni o'chira olasiz")
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "UPDATE web_homeworks SET status='deleted', updated_at=CURRENT_TIMESTAMP WHERE id=?",
            (int(homework_id),),
        )
        conn.commit()
    finally:
        conn.close()
    _safe_call(lambda: deactivate_content_test("homework", int(homework_id)), None)
    return {"message": "Homework o'chirildi"}


@app.get("/teacher/homework")
async def teacher_homework_list(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    rows = _safe_call(lambda: list_homeworks_for_teacher(int(user.get("id") or 0)), []) or []
    if _apply_homework_deadline_penalties(rows):
        rows = _safe_call(lambda: list_homeworks_for_teacher(int(user.get("id") or 0)), []) or []
    tests: dict[int, bool] = {}
    for row in rows:
        _attach_homework_runtime_fields(row)
        hid = int(row.get("id") or 0)
        if hid > 0 and hid not in tests:
            tests[hid] = bool(_safe_call(lambda homework_id=hid: get_content_test("homework", homework_id, include_inactive=False, include_answers=False), None))
        sid = int(row.get("submission_student_id") or row.get("student_id") or 0)
        result = _safe_call(lambda student_id=sid, homework_id=hid: get_content_test_result(student_id, "homework", homework_id), None) if sid > 0 and hid > 0 else None
        row["test_available"] = bool(tests.get(hid))
        row["test_completed"] = bool(result)
        if row["test_completed"]:
            row["deadline_missed"] = False  # test topshirilgan — bajarilgan hisoblanadi
        row["test_result"] = result
        row["test_correct_count"] = int((result or {}).get("correct_count") or 0)
        row["test_wrong_count"] = int((result or {}).get("wrong_count") or 0)
        row["test_skipped_count"] = int((result or {}).get("skipped_count") or 0)
        row["test_total_questions"] = int((result or {}).get("total_questions") or 0)
        row["test_dpoints_delta"] = float((result or {}).get("dpoints_delta") or 0.0)
    return {"items": rows}


@app.get("/teacher/homework/groups")
async def teacher_homework_groups(
    subject: str | None = Query(default=None),
    query: str | None = Query(default=None),
    limit: int = Query(default=80, ge=1, le=200),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    normalized_subject = _normalize_subject_label(subject)
    needle = str(query or "").strip().lower()
    rows = _teacher_manageable_groups(int(user.get("id") or 0))
    if normalized_subject:
        rows = [g for g in rows if _normalize_subject_label(str(g.get("subject") or "")) == normalized_subject]
    if needle:
        rows = [
            g for g in rows
            if needle in f"{g.get('name') or ''} {g.get('subject') or ''} {g.get('level') or ''}".lower()
        ]
    items = []
    for row in rows[: int(limit)]:
        items.append(
            {
                "id": int(row.get("id") or 0),
                "name": str(row.get("name") or ""),
                "subject": str(row.get("subject") or ""),
                "level": str(row.get("level") or ""),
                "lesson_date": row.get("lesson_date"),
                "lesson_start": row.get("lesson_start"),
                "lesson_end": row.get("lesson_end"),
                "student_count": int(row.get("student_count") or 0),
                "teacher_id": int(row.get("teacher_id") or 0),
            }
        )
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 500:
        logger.info("perf teacher.homework.groups total_ms=%.2f rows=%s", elapsed_ms, len(items))
    return {"items": items, "total": len(rows), "limit": int(limit)}


@app.get("/teacher/homework/groups/{group_id}/voiceroom-preview")
async def teacher_homework_voiceroom_preview(group_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    import random
    users = _safe_call(lambda: get_group_users(group_id), []) or []
    students = [u for u in users if u.get('role') == 'student' or int(u.get('login_type') or 0) in (1, 2, 6)]
    random.shuffle(students)
    
    voiceroom_groups = []
    for i in range(0, len(students), 2):
        chunk = students[i:i+2]
        if len(chunk) == 1 and voiceroom_groups:
            # Add to the last group
            s3 = chunk[0]
            voiceroom_groups[-1]["student3_id"] = int(s3["id"])
            voiceroom_groups[-1]["student3_first_name"] = str(s3.get("first_name") or "")
            voiceroom_groups[-1]["student3_last_name"] = str(s3.get("last_name") or "")
            voiceroom_groups[-1]["student3_profile_image_url"] = str(s3.get("profile_image_url") or "")
            continue
            
        s1 = chunk[0]
        s2 = chunk[1] if len(chunk) > 1 else None
        
        vg = {
            "student1_id": int(s1["id"]),
            "student1_first_name": str(s1.get("first_name") or ""),
            "student1_last_name": str(s1.get("last_name") or ""),
            "student1_profile_image_url": str(s1.get("profile_image_url") or ""),
        }
        if s2:
            vg["student2_id"] = int(s2["id"])
            vg["student2_first_name"] = str(s2.get("first_name") or "")
            vg["student2_last_name"] = str(s2.get("last_name") or "")
            vg["student2_profile_image_url"] = str(s2.get("profile_image_url") or "")
        voiceroom_groups.append(vg)
        
    return {"items": voiceroom_groups}


@app.get("/student/homework")
async def student_homework_list(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    rows = _safe_call(lambda: list_homeworks_for_student(user_id), []) or []
    for row in rows:
        row["_viewer_student_id"] = user_id
    if _apply_homework_deadline_penalties(rows):
        rows = _safe_call(lambda: list_homeworks_for_student(user_id), []) or []
        for row in rows:
            row["_viewer_student_id"] = user_id
    for row in rows:
        _attach_homework_runtime_fields(row)
        hid = int(row.get("id") or 0)
        test = _safe_call(lambda homework_id=hid: get_content_test("homework", homework_id, include_inactive=False, include_answers=False), None) if hid > 0 else None
        result = _safe_call(lambda homework_id=hid: get_content_test_result(user_id, "homework", homework_id), None) if hid > 0 else None
        row["test_available"] = bool(test)
        row["test_completed"] = bool(result)
        if row["test_completed"]:
            row["deadline_missed"] = False  # test topshirilgan — bajarilgan hisoblanadi
        row["test_result"] = result
        row["test_correct_count"] = int((result or {}).get("correct_count") or 0)
        row["test_wrong_count"] = int((result or {}).get("wrong_count") or 0)
        row["test_skipped_count"] = int((result or {}).get("skipped_count") or 0)
        row["test_total_questions"] = int((result or {}).get("total_questions") or 0)
        row["test_dpoints_delta"] = float((result or {}).get("dpoints_delta") or 0.0)
    return {"items": rows}


class VoiceRoomSubmitRequest(BaseModel):
    recorded_audio_url: str

@app.post("/student/homework/{homework_id}/submit-voiceroom")
async def student_submit_voiceroom_homework(
    homework_id: int,
    payload: VoiceRoomSubmitRequest,
    authorization: str | None = Header(default=None)
):
    from db import _user_row_from_bearer, get_conn, upsert_homework_submission
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    student_id = int(user.get("id") or 0)
    
    conn = get_conn()
    cur = conn.cursor()
    try:
        # Get the voiceroom group for this homework
        cur.execute(
            "SELECT student1_id, student2_id, student3_id FROM web_homework_voiceroom_groups WHERE homework_id=%s AND (student1_id=%s OR student2_id=%s OR student3_id=%s)",
            (homework_id, student_id, student_id, student_id)
        )
        vg = cur.fetchone()
        if not vg:
            raise HTTPException(status_code=404, detail="Siz ushbu guruhga kiritilmagansiz.")
            
        cur.execute(
            "UPDATE web_homework_voiceroom_groups SET recorded_audio_url=%s, status='completed' WHERE homework_id=%s AND (student1_id=%s OR student2_id=%s OR student3_id=%s)",
            (payload.recorded_audio_url, homework_id, student_id, student_id, student_id)
        )
        
        vg_values = vg.values() if isinstance(vg, dict) else vg
        students = [int(sid) for sid in vg_values if sid and int(sid) > 0]
        
        for sid in students:
            upsert_homework_submission(
                homework_id=homework_id,
                student_id=sid,
                status="completed",
                note="Voice Room orqali yozib olingan.",
                voice_message_url=payload.recorded_audio_url,
            )
            
        conn.commit()
        return {"success": True}
    except Exception as e:
        conn.rollback()
        raise e
    finally:
        conn.close()

@app.post("/student/homework/{homework_id}/submit")
async def student_submit_homework(
    homework_id: int,
    payload: HomeworkSubmitRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if homework:
        _attach_homework_runtime_fields(homework)
    group_id = int((homework or {}).get("group_id") or 0)
    student_owns_homework = bool(homework and int(homework.get("student_id") or 0) == user_id)
    student_group_ids = {int(row.get("id") or 0) for row in (_safe_call(lambda: get_user_groups(user_id), []) or [])}
    if not homework or not (student_owns_homework or (group_id > 0 and group_id in student_group_ids)):
        raise HTTPException(status_code=404, detail="Homework not found")
    existing_submission = _safe_call(lambda: get_homework_submission(int(homework_id), user_id), None)
    if existing_submission:
        raise HTTPException(status_code=409, detail="Homework already submitted")
    proof_images = _homework_proof_images_from_payload(payload)
    try:
        submission = upsert_homework_submission(
            homework_id=int(homework_id),
            student_id=user_id,
            status="pending_review",
            note=(payload.note or "").strip() or None,
            proof_image_url=(proof_images[0] if proof_images else None),
            proof_images_json=json.dumps(proof_images, ensure_ascii=False) if proof_images else None,
            voice_message_url=payload.voice_message_url,
        )
    except Exception as exc:
        logger.exception("student.homework.submit failed user_id=%s homework_id=%s", user_id, homework_id)
        raise HTTPException(status_code=500, detail=f"Could not submit homework: {str(exc)[:220]}") from exc
    if not submission:
        raise HTTPException(status_code=422, detail="Could not submit homework")
    _attach_homework_runtime_fields(submission)
    try:
        await _notify_homework_submitted(homework, user, submission)
    except Exception:
        logger.exception("student.homework.submit notification failed user_id=%s homework_id=%s", user_id, homework_id)
    return {"message": "Homework submitted", "submission": submission}


@app.post("/teacher/homework/{homework_id}/review")
async def teacher_review_homework(
    homework_id: int,
    payload: HomeworkReviewRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    group_id = int(homework.get("group_id") or 0)
    is_owner = int(homework.get("teacher_id") or 0) == teacher_id
    teacher_can_manage_group = bool(group_id > 0 and _teacher_can_manage_group(user, _safe_call(lambda: get_group(group_id), None)))
    
    student_id = int(homework.get("student_id") or 0)
    if group_id > 0:
        student_id = int(payload.student_id or 0)
        group_member_ids = {
            int(member.get("id") or 0)
            for member in (_safe_call(lambda: get_group_users(group_id), []) or [])
            if int(member.get("id") or 0) > 0
        }
        if student_id <= 0 or student_id not in group_member_ids:
            raise HTTPException(status_code=400, detail="Select a valid student submission for group homework")
            
    if not is_owner and not teacher_can_manage_group:
        if student_id <= 0 or student_id not in _teacher_student_ids(teacher_id):
            raise HTTPException(status_code=403, detail="Only homework owner or active temporary teacher can review")
    submission = _safe_call(lambda: get_homework_submission(int(homework_id), student_id), None)
    if not submission:
        submission = _safe_call(lambda: upsert_homework_submission(int(homework_id), student_id, "missed", "O'qituvchi tomonidan belgilandi"), None)
        if not submission:
            raise HTTPException(status_code=404, detail="Submission not found")
    if submission.get("reviewed_at"):
        raise HTTPException(status_code=409, detail="Homework already reviewed")
    requested_delta = float(payload.dpoint_delta if payload.dpoint_delta is not None else payload.dcoin_delta or 0.0)
    group = _safe_call(lambda: get_group(group_id), None) if group_id > 0 else None
    subj = group.get("subject") if group else None
    if subj in ("Matematika", "Ona tili", "Tarix", "Arab tili"):
        dpoint_delta = 0.0
    else:
        dpoint_delta = max(-500.0, min(500.0, requested_delta))
    if dpoint_delta != 0:
        try:
            add_dpoints(
                student_id,
                dpoint_delta,
                subject=(_user_subjects_from_row(_safe_call(lambda: get_user_by_id(student_id), {}) or {}) or ["English"])[0],
                change_type="teacher_homework_review",
            )
        except Exception as exc:
            logger.exception("teacher.homework.review dpoint failed teacher_id=%s homework_id=%s student_id=%s", teacher_id, homework_id, student_id)
            raise HTTPException(status_code=500, detail="Could not apply homework D'point reward") from exc
    try:
        reviewed = review_homework_submission(
            homework_id=int(homework_id),
            student_id=student_id,
            reviewed_by=teacher_id,
            status=str(payload.status or "done"),
            dcoin_delta=dpoint_delta,
            review_note=(payload.review_note or "").strip() or None,
        )
    except Exception as exc:
        logger.exception("teacher.homework.review failed teacher_id=%s homework_id=%s student_id=%s", teacher_id, homework_id, student_id)
        raise HTTPException(status_code=500, detail=f"Could not save homework review: {str(exc)[:220]}") from exc
    if not reviewed:
        raise HTTPException(status_code=422, detail="Could not save homework review")
    _attach_homework_runtime_fields(reviewed)
    try:
        await _notify_homework_reviewed(homework, student_id, reviewed, user)
    except Exception:
        logger.exception("teacher.homework.review notification failed homework_id=%s student_id=%s", homework_id, student_id)
    return {"message": "Homework reviewed", "submission": reviewed}


@app.get("/teacher/dcoin/students")
@app.get("/teacher/economy/students")
async def teacher_economy_students(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    items: list[dict[str, Any]] = []
    student_ids = sorted(_teacher_student_ids(teacher_id))
    student_id_set = set(student_ids)
    monthly_stats = _teacher_monthly_test_stats_for_students(student_id_set)
    student_rows = _user_rows_by_ids_light(student_id_set, limit=max(80, len(student_id_set)))
    _enrich_user_rows_with_face_profiles(student_rows)
    students_by_id: dict[int, dict] = {int(student.get("id") or 0): student for student in student_rows}
    visible_dcoins = _visible_dcoin_map_for_users(student_id_set)
    dpoints_map = _dpoints_map_for_users(student_id_set)
    subject_levels_map = _student_subject_levels_map_for_users(student_id_set)
    daily_limit = max(0.0, float((_get_runtime_settings() or {}).get("teacher_manual_daily_dpoint_max") or 500.0))
    daily_used_map = _teacher_manual_dpoint_usage_24h_map(student_id_set)
    for student_id in student_ids:
        student = students_by_id.get(int(student_id))
        if not student:
            continue
        subject_levels = subject_levels_map.get(int(student_id)) or []
        subjects = [str(row.get("subject") or "").strip() for row in subject_levels if str(row.get("subject") or "").strip()]
        if not subjects:
            subjects = _user_subjects_from_csv(student)
        visible_dcoin = float(visible_dcoins.get(int(student_id), 0.0) or 0.0)
        stats = monthly_stats.get(int(student_id), {})
        daily_used = max(0.0, float(daily_used_map.get(int(student_id), 0.0) or 0.0))
        daily_remaining = max(0.0, daily_limit - daily_used)
        items.append(
            {
                "student": _serialize_user_row_light(student),
                "subjects": subjects,
                "subject_levels": subject_levels,
                "balances": {"GLOBAL": visible_dcoin},
                "balance_total": visible_dcoin,
                "dpoints_total": float(dpoints_map.get(int(student_id), 0.0) or 0.0),
                "tests_taken": float(stats.get("tests_taken") or 0),
                "tests_completed": float(stats.get("tests_completed") or 0),
                "accuracy_percent": float(stats.get("accuracy_percent") or 0),
                "adjustment_allowed": True,
                "lesson_window_active": True,
                "rules": {
                    "give_max": min(500.0, daily_remaining),
                    "take_min": 1,
                    "take_max": 500,
                    "daily_max": daily_limit,
                    "daily_used": daily_used,
                    "daily_remaining": daily_remaining,
                },
            }
        )
    return {"items": items}


