@app.get("/teacher/payments/status")
async def teacher_payments_status(
    ym: str | None = Query(default=None),
    group_id: int | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"teacher"})
    if role != "teacher":
        raise HTTPException(status_code=403, detail="Support teacher cannot access payment status")
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    groups_started_at = time.perf_counter()
    groups = _teacher_manageable_groups(int(user.get("id") or 0))
    selected_group_id = int(group_id or 0)
    if selected_group_id > 0:
        groups = [row for row in groups if int(row.get("id") or 0) == selected_group_id]
        if not groups:
            raise HTTPException(status_code=404, detail="Group not found for current teacher")
    groups_elapsed_ms = (time.perf_counter() - groups_started_at) * 1000.0
    payload_items: list[dict[str, Any]] = []
    obligations_fetch_ms = 0.0
    fallback_upsert_ms = 0.0
    conn = get_conn()
    cur = conn.cursor()
    try:
        for group in groups:
            gid = int(group.get("id") or 0)
            if gid <= 0:
                continue
            members = _payment_get_group_users_with_history(gid, month_key)
            student_members = [m for m in members if int(m.get("login_type") or 0) in (1, 2, 6)]
            member_ids = [int(m.get("id") or 0) for m in student_members if int(m.get("id") or 0) > 0]
            obligations_by_user: dict[int, dict[str, Any]] = {}
            if member_ids:
                fetch_started_at = time.perf_counter()
                placeholders = ", ".join(["?"] * len(member_ids))
                cur.execute(
                    f"""
                    SELECT user_id, status, debt_amount
                    FROM payment_monthly_obligations
                    WHERE group_id=?
                      AND ym=?
                      AND user_id IN ({placeholders})
                    """,
                    (int(gid), str(month_key), *member_ids),
                )
                for row in (cur.fetchall() or []):
                    item = dict(row)
                    uid = int(item.get("user_id") or 0)
                    if uid > 0:
                        obligations_by_user[uid] = item
                obligations_fetch_ms += (time.perf_counter() - fetch_started_at) * 1000.0
            for member in student_members:
                if int(member.get("login_type") or 0) not in (1, 2, 6):
                    continue
                uid = int(member.get("id") or 0)
                obligation = obligations_by_user.get(uid)
                if not obligation:
                    upsert_started_at = time.perf_counter()
                    obligation = _payment_upsert_obligation(member, group, month_key)
                    fallback_upsert_ms += (time.perf_counter() - upsert_started_at) * 1000.0
                    if not obligation:
                        continue
                payload_items.append(
                    {
                        "user_id": uid,
                        "student_name": _display_name(member),
                        "group_id": gid,
                        "group_name": str(group.get("name") or "").strip() or f"Group #{gid}",
                        "ym": month_key,
                        "status": str(obligation.get("status") or PAYMENT_STATUS_UNPAID),
                        "has_remaining_debt": bool(float(obligation.get("debt_amount") or 0.0) > 1e-9),
                        "is_accountless": bool(int(member.get("login_type") or 0) == 6),
                    }
                )
    finally:
        conn.close()
    total_elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    logger.info(
        "teacher_payment_status_timing teacher_id=%s month=%s group_id=%s groups_ms=%.2f obligations_fetch_ms=%.2f fallback_upsert_ms=%.2f total_ms=%.2f rows=%s",
        int(user.get("id") or 0),
        month_key,
        int(selected_group_id or 0),
        float(groups_elapsed_ms),
        float(obligations_fetch_ms),
        float(fallback_upsert_ms),
        float(total_elapsed_ms),
        len(payload_items),
    )
    return {"ym": month_key, "group_id": selected_group_id if selected_group_id > 0 else None, "items": payload_items}


def _group_membership_change_payload(group_id: int, student_id: int, message: str, **extra: Any) -> dict[str, Any]:
    student = _safe_call(lambda: get_user_by_id(int(student_id)), None) or {}
    groups = _safe_call(lambda: get_user_groups(int(student_id)), []) or []
    member = _serialize_user_row_light(student) if student else {"id": int(student_id)}
    member["group_count"] = len(groups)
    
    group_count = 0
    try:
        from db import get_conn
        conn = get_conn()
        cur = conn.cursor()
        cur.execute("SELECT COUNT(*) FROM user_groups WHERE group_id=?", (int(group_id),))
        row = cur.fetchone()
        if row:
            group_count = row[0]
    except Exception:
        pass

    payload = {
        "message": message,
        "group_id": int(group_id),
        "student_id": int(student_id),
        "member": member,
        "group_count": group_count,
    }
    payload.update(extra)
    return payload


