@app.post("/teacher/tests/upload")
async def teacher_tests_upload(
    subject: str = Form(default=""),
    level: str = Form(default="PRE-INTERMEDIATE"),
    file: UploadFile = File(...),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher"})
    uid = int(user.get("id") or 0)
    if not _safe_call(lambda: get_daily_test_upload_permission(uid), False):
        raise HTTPException(status_code=403, detail="Daily test upload permission denied")

    allowed_subjects = _normalize_subjects(_user_subjects_from_row(user), fallback=["English"])
    selected_subject = _normalize_subject_label(subject) or (allowed_subjects[0] if allowed_subjects else "English")
    if selected_subject not in allowed_subjects:
        raise HTTPException(status_code=403, detail="Selected subject is not available for this teacher")

    selected_level = str(level or "PRE-INTERMEDIATE").strip().upper()
    allowed_levels = {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE"} if selected_subject == "Russian" else {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}
    if selected_level not in allowed_levels:
        raise HTTPException(status_code=400, detail="Invalid daily test level")

    file_name = str(file.filename or "daily-tests.xlsx").strip()
    if not file_name.lower().endswith(".xlsx"):
        raise HTTPException(status_code=400, detail="Only .xlsx files are allowed")
    data = await file.read()
    if not data:
        raise HTTPException(status_code=400, detail="Uploaded file is empty")
    if len(data) > 12 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="File is too large")

    try:
        from daily_tests import import_daily_tests_from_xlsx

        report = import_daily_tests_from_xlsx(
            data,
            file_name,
            uid,
            selected_subject,
            selected_level,
        )
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Daily tests upload failed: {exc}") from exc
    return {
        "message": "Daily tests uploaded",
        "subject": selected_subject,
        "level": selected_level,
        "report": report,
        "stock": _generator_stock_payload(selected_subject, teacher_id=uid),
    }


