def _generator_stock_payload(subject: str, teacher_id: int | None = None) -> dict[str, Any]:
    subj = _normalize_subject_label(subject) or "English"
    subjects = [str(item.get("code") or "") for item in GROUP_SUBJECTS if str(item.get("code") or "").strip()]
    level_order = ["BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "MIXED", "UNSET", "ALL"]

    def _ordered_counts(source: dict[str, int]) -> dict[str, int]:
        out: dict[str, int] = {}
        old_to_new = {
            "A1": "BEGINNER",
            "A2": "ELEMENTARY",
            "B1": "PRE-INTERMEDIATE",
            "B2": "INTERMEDIATE",
            "C1": "UPPER-INTERMEDIATE",
            "C2": "ADVANCED"
        }
        for level in level_order:
            out[level] = int(source.get(level) or 0)
        for old, new in old_to_new.items():
            if old in source and new in out:
                out[new] += int(source[old] or 0)
        for level, count in sorted(source.items()):
            if level not in out and level not in old_to_new:
                out[level] = int(count or 0)
        return out

    daily_global_rows = _safe_call(lambda: get_daily_tests_unused_stock_by_subject_level(), []) or []
    daily_by_subject: dict[str, dict[str, int]] = {}
    for row in daily_global_rows:
        row_subject = _normalize_subject_label(row.get("subject")) or str(row.get("subject") or "").strip().title()
        level = str(row.get("level") or "ALL").strip().upper() or "ALL"
        count = int(row.get("count") or row.get("c") or 0)
        daily_by_subject.setdefault(row_subject, {})[level] = count
    teacher_daily = _safe_call(lambda: get_daily_tests_stock_by_teacher(int(teacher_id or 0), subj), {}) if teacher_id else {}
    vocabulary_by_subject: dict[str, dict[str, int]] = {}
    vocabulary_totals: dict[str, int] = {}
    for item_subject in subjects:
        vocab_rows = _safe_call(lambda s=item_subject: get_vocabulary_stock_by_subject_level(s), []) or []
        levels = {
            str(row.get("level") or "ALL").strip().upper() or "ALL": int(row.get("count") or row.get("c") or 0)
            for row in vocab_rows
        }
        ordered = _ordered_counts(levels)
        vocabulary_by_subject[item_subject] = ordered
        vocabulary_totals[item_subject] = int(sum(ordered.values()))
    daily_ordered = {item_subject: _ordered_counts(daily_by_subject.get(item_subject, {})) for item_subject in subjects}
    daily_totals = {item_subject: int(sum(levels.values())) for item_subject, levels in daily_ordered.items()}
    return {
        "subject": subj,
        "subjects": subjects,
        "levels": level_order,
        "daily": {
            "teacher": teacher_daily,
            "global_by_subject": daily_ordered,
            "by_subject": daily_ordered,
            "total_by_subject": daily_totals,
            "selected_subject_levels": daily_ordered.get(subj, {}),
        },
        "vocabulary": {
            "levels": vocabulary_by_subject.get(subj, {}),
            "by_subject": vocabulary_by_subject,
            "total_by_subject": vocabulary_totals,
            "total": int(sum(vocabulary_totals.values())),
        },
        "arena": {
            "source": "daily_tests_bank",
            "selected_subject_levels": daily_ordered.get(subj, {}),
        },
    }


async def _push_ai_generator_admin_bot_result(
    *,
    job_id: str,
    actor: dict,
    role: str,
    kind: str,
    subject: str,
    level: str,
    count: int,
    status: str,
    result: dict[str, Any] | None = None,
    error: str = "",
    elapsed_ms: int = 0,
) -> None:
    try:
        token = (os.getenv("ADMIN_BOT_TOKEN") or "").strip()
        if not token:
            return
        admin_chat_ids: list[int] = []
        for raw_chat_id in ((ADMIN_CHAT_IDS or []) + (LIMITED_ADMIN_CHAT_IDS or [])):
            try:
                chat_id = int(raw_chat_id)
            except Exception:
                continue
            if chat_id > 0 and chat_id not in admin_chat_ids:
                admin_chat_ids.append(chat_id)
        if not admin_chat_ids:
            return
        res = result or {}
        kind_label = {
            "vocabulary": "Vocabulary",
            "daily-tests": "Daily Test",
            "arena": "Arena",
        }.get(str(kind or ""), str(kind or "generator"))
        status_label = "tugadi" if status == "completed" else "xatolik"
        actor_name = _display_name(actor)
        lines = [
            f"AI generator {status_label}",
            f"Job: {job_id}",
            f"User: {actor_name} ({role}, ID {int(actor.get('id') or 0)})",
            f"Turi: {kind_label}",
            f"Fan/level: {subject} {level}",
            f"So'ralgan: {int(count or 0)}",
        ]
        if status == "completed":
            for key, label in (
                ("requested", "Requested"),
                ("generated", "Generated"),
                ("inserted", "Inserted"),
                ("skipped", "Skipped"),
                ("inserted_from_seed", "Seed insert"),
                ("inserted_from_ai", "AI insert"),
                ("attempts", "Attempts"),
            ):
                if key in res:
                    lines.append(f"{label}: {res.get(key)}")
        else:
            preview = str(error or res.get("error") or "Jarayon to'xtadi").strip()
            if len(preview) > 900:
                preview = f"{preview[:897]}..."
            lines.append(f"Error: {preview}")
        if elapsed_ms:
            lines.append(f"Vaqt: {max(0, int(elapsed_ms / 1000))}s")
        button_url = f"{WEBAPP_URL}/?role=admin&section=generator" if WEBAPP_URL else None
        for admin_chat_id in admin_chat_ids:
            try:
                await _send_telegram_text(
                    token,
                    str(admin_chat_id),
                    "\n".join(lines),
                    button_text="Admin AI Generator",
                    button_url=button_url,
                )
            except Exception:
                logger.exception("ai_generator admin bot notify failed job_id=%s chat_id=%s", job_id, admin_chat_id)
    except Exception:
        logger.exception("ai_generator admin bot notify setup failed job_id=%s", job_id)


async def _run_generator_job(job_id: str, actor: dict, payload: GeneratorJobRequest, role: str) -> None:
    started_monotonic = time.monotonic()
    _update_ai_generator_job(job_id, {"status": "running", "phase": "starting", "progress": 5}, event="started")
    uid = int(actor.get("id") or 0)
    subject = _normalize_subject_label(payload.subject) or "English"
    level = str(payload.level or "PRE-INTERMEDIATE").strip().upper()
    count = max(1, min(5000, int(payload.count or 1)))
    kind = str(payload.kind or "vocabulary")
    try:
        logger.info(
            "ai_generator.job.run job_id=%s role=%s user_id=%s kind=%s subject=%s level=%s count=%s",
            job_id,
            role,
            uid,
            kind,
            subject,
            level,
            count,
        )
        _update_ai_generator_job(job_id, {"phase": "generating", "progress": 20, "total": count}, event="generating")
        if role == "teacher":
            _ensure_teacher_ai_permission(actor)
        if kind == "vocabulary":
            async def _job_progress(pct: int, current: int, total: int):
                # Check if job was externally cancelled
                current_job = _get_generator_job(job_id)
                if str(current_job.get("status") or "") == "failed":
                    return
                # Keep 20-99 reserved for active work.
                mapped = max(20, min(99, int(20 + (max(0, min(100, int(pct))) * 79 / 100))))
                _update_ai_generator_job(
                    job_id,
                    {
                        "phase": "generating",
                        "progress": mapped,
                        "current": int(current),
                        "total": int(total),
                    },
                    event="progress",
                )
            result = await generate_vocabulary_and_insert_exact(
                subject=subject,
                level=level,
                target_count=count,
                added_by=uid,
                progress_cb=_job_progress,
                check_cancel=lambda: str(_get_generator_job(job_id).get("status") or "") == "failed",
                allow_partial=True,
            )
        elif kind == "daily-tests":
            remaining = count
            batch_size = 20
            requested = generated = inserted = skipped = 0
            attempts = 0
            max_attempts = max(10, int((count * 2) / batch_size) + 5)
            no_progress = 0
            while remaining > 0 and attempts < max_attempts and no_progress < 10:
                current_job = _get_generator_job(job_id)
                if str(current_job.get("status") or "") == "failed":
                    logger.info("ai_generator.job.cancelled_mid_run daily-tests job_id=%s", job_id)
                    break
                attempts += 1
                cur = min(batch_size, remaining + 5) # ask for slightly more to compensate duplicates
                partial = await generate_daily_tests_and_insert(
                    subject=subject,
                    level=level,
                    count=cur,
                    created_by=uid,
                    assign_today_set=False,
                )
                p_req = int(getattr(partial, "requested", 0) or 0)
                p_ins = int(getattr(partial, "inserted", 0) or 0)
                requested += p_req
                generated += int(getattr(partial, "generated", 0) or 0)
                inserted += p_ins
                skipped += int(getattr(partial, "skipped", 0) or 0)
                
                if p_ins > 0:
                    remaining -= p_ins
                    no_progress = 0
                else:
                    no_progress += 1
                    
                done = count - max(0, remaining)
                base_prog = done / max(1, count)
                attempt_bonus = (attempts / max(1, max_attempts)) * (1.0 - base_prog) * 0.8
                overall_prog = base_prog + attempt_bonus
                
                _update_ai_generator_job(
                    job_id,
                    {
                        "phase": "generating",
                        "progress": max(20, min(99, int(20 + (overall_prog * 79)))),
                        "current": done,
                        "total": count,
                    },
                    event="progress",
                )
            result = GenerationResult(requested=requested, generated=generated, inserted=inserted, skipped=skipped)
        elif kind == "arena":
            remaining = count
            batch_size = 20
            requested = generated = inserted = skipped = 0
            attempts = 0
            max_attempts = max(10, int((count * 2) / batch_size) + 5)
            no_progress = 0
            while remaining > 0 and attempts < max_attempts and no_progress < 10:
                current_job = _get_generator_job(job_id)
                if str(current_job.get("status") or "") == "failed":
                    logger.info("ai_generator.job.cancelled_mid_run arena job_id=%s", job_id)
                    break
                attempts += 1
                cur = min(batch_size, remaining + 5)
                partial = await generate_arena_questions_and_insert(
                    subject=subject,
                    level=level,
                    count=cur,
                    created_by=uid,
                )
                p_req = int(getattr(partial, "requested", 0) or 0)
                p_ins = int(getattr(partial, "inserted", 0) or 0)
                requested += p_req
                generated += int(getattr(partial, "generated", 0) or 0)
                inserted += p_ins
                skipped += int(getattr(partial, "skipped", 0) or 0)
                
                if p_ins > 0:
                    remaining -= p_ins
                    no_progress = 0
                else:
                    no_progress += 1
                    
                done = count - max(0, remaining)
                base_prog = done / max(1, count)
                attempt_bonus = (attempts / max(1, max_attempts)) * (1.0 - base_prog) * 0.8
                overall_prog = base_prog + attempt_bonus
                
                _update_ai_generator_job(
                    job_id,
                    {
                        "phase": "generating",
                        "progress": max(20, min(99, int(20 + (overall_prog * 79)))),
                        "current": done,
                        "total": count,
                    },
                    event="progress",
                )
            result = GenerationResult(requested=requested, generated=generated, inserted=inserted, skipped=skipped)
        else:
            raise ValueError("Unsupported generator kind")
        result_dict = _ai_generator_result_dict(result)
        
        current_job = _get_saved_ai_generator_job(job_id)
        if current_job and current_job.get("status") == "failed":
            logger.info("ai_generator.job.cancelled_mid_run job_id=%s", job_id)
            _update_ai_generator_job(
                job_id,
                {"phase": "failed", "progress": 100, "result": result_dict},
                event="cancelled_partial_result"
            )
            return

        elapsed_ms = int((time.monotonic() - started_monotonic) * 1000)
        logger.info(
            "ai_generator.job.completed job_id=%s role=%s kind=%s requested=%s generated=%s inserted=%s skipped=%s elapsed_ms=%s",
            job_id,
            role,
            kind,
            result_dict.get("requested"),
            result_dict.get("generated"),
            result_dict.get("inserted"),
            result_dict.get("skipped"),
            elapsed_ms,
        )
        _update_ai_generator_job(
            job_id,
            {
                "status": "completed",
                "phase": "completed",
                "progress": 100,
                "current": int(result_dict.get("inserted") or result_dict.get("generated") or count),
                "total": count,
                "result": result_dict,
                "completed_at": _ai_generator_now_iso(),
            },
            event="completed",
        )
        await _push_ai_generator_admin_bot_result(
            job_id=job_id,
            actor=actor,
            role=role,
            kind=kind,
            subject=subject,
            level=level,
            count=count,
            status="completed",
            result=result_dict,
            elapsed_ms=elapsed_ms,
        )
    except Exception as exc:
        elapsed_ms = int((time.monotonic() - started_monotonic) * 1000)
        logger.exception("ai_generator.job.failed job_id=%s role=%s kind=%s elapsed_ms=%s", job_id, role, kind, elapsed_ms)
        _update_ai_generator_job(
            job_id,
            {
                "status": "failed",
                "phase": "failed",
                "progress": 100,
                "error": str(exc),
                "completed_at": _ai_generator_now_iso(),
            },
            event="failed",
        )
        await _push_ai_generator_admin_bot_result(
            job_id=job_id,
            actor=actor,
            role=role,
            kind=kind,
            subject=subject,
            level=level,
            count=count,
            status="failed",
            error=str(exc),
            elapsed_ms=elapsed_ms,
        )


def _create_generator_job(actor: dict, payload: GeneratorJobRequest, role: str) -> dict[str, Any]:
    if not str(os.getenv("XAI_API_KEY") or "").strip():
        logger.error(
            "ai_generator.job.rejected missing_xai_api_key role=%s user_id=%s kind=%s subject=%s level=%s count=%s",
            role,
            int(actor.get("id") or 0),
            str(payload.kind or "vocabulary"),
            _normalize_subject_label(payload.subject) or "English",
            str(payload.level or "PRE-INTERMEDIATE").strip().upper(),
            max(1, min(5000, int(payload.count or 1))),
        )
        raise HTTPException(status_code=503, detail="XAI_API_KEY is not configured")
    job_id = uuid4().hex
    job = {
        "job_id": job_id,
        "role": role,
        "status": "queued",
        "phase": "queued",
        "progress": 0,
        "kind": str(payload.kind or "vocabulary"),
        "subject": _normalize_subject_label(payload.subject) or "English",
        "level": str(payload.level or "PRE-INTERMEDIATE").strip().upper(),
        "count": max(1, min(5000, int(payload.count or 1))),
        "current": 0,
        "total": max(1, min(5000, int(payload.count or 1))),
        "created_at": _ai_generator_now_iso(),
        "created_by": int(actor.get("id") or 0),
    }
    saved = _save_ai_generator_job(job, event="queued")
    asyncio.create_task(_run_generator_job(job_id, dict(actor), payload, role))
    return saved


def _get_generator_job(job_id: str) -> dict[str, Any]:
    ai_job = _get_saved_ai_generator_job(str(job_id or ""))
    if ai_job:
        return ai_job
    db_job = _get_group_arena_generation_job(str(job_id or ""))
    if db_job:
        return db_job
    raise HTTPException(status_code=404, detail="Generator job not found")


