async def _run_bulk_ai_generation(actor: dict, payload: BulkAiGenerationRequest) -> dict:
    uid = int(actor.get("id") or 0)
    subject = _normalize_subject_label(payload.subject) or "English"
    levels = payload.levels or []
    if not levels:
        raise HTTPException(status_code=400, detail="At least one level config is required")

    rows: list[dict] = []
    total_daily = 0
    total_arena = 0

    for item in levels:
        level = str(item.level or "").strip().upper()
        if level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1", "MIXED"}:
            raise HTTPException(status_code=400, detail=f"Unsupported level: {level}")

        daily_count = max(0, int(item.daily_tests_count or 0))
        arena_count = max(0, int(item.arena_level_tests_count or 0))
        one: dict[str, Any] = {
            "level": level,
            "daily_tests_count": daily_count,
            "arena_level_tests_count": arena_count,
            "daily_result": None,
            "arena_result": None,
            "error": None,
        }
        try:
            if daily_count > 0:
                daily_res = await generate_daily_tests_and_insert(
                    subject=subject,
                    level=level,
                    count=daily_count,
                    created_by=uid,
                    assign_today_set=False,
                )
                one["daily_result"] = dict(daily_res.__dict__)
                total_daily += int(one["daily_result"].get("inserted") or 0)
            if arena_count > 0:
                arena_res = await generate_arena_questions_and_insert(
                    subject=subject,
                    level=level,
                    count=arena_count,
                    created_by=uid,
                )
                one["arena_result"] = dict(arena_res.__dict__)
                total_arena += int(one["arena_result"].get("inserted") or 0)
        except Exception as exc:
            one["error"] = str(exc)
        rows.append(one)

    return {
        "subject": subject,
        "items": rows,
        "totals": {
            "inserted_daily_tests": int(total_daily),
            "inserted_arena_level_tests": int(total_arena),
        },
    }


