class PushTokenRegisterRequest(BaseModel):
    token: str
    platform: Literal["android", "ios", "web"] = "android"
    app: str = "teacher"


@app.post("/notifications/push-token")
async def register_push_token(payload: PushTokenRegisterRequest, authorization: str | None = Header(default=None)):
    """
    Registers this device's FCM token against the logged-in user so the
    backend can send real OS-level push notifications (see
    `push_notifications.py`) — called by the Flutter app right after login
    and whenever `FirebaseMessaging.onTokenRefresh` fires.
    """
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "admin", "support"})
    token = str(payload.token or "").strip()
    if not token:
        raise HTTPException(status_code=400, detail="token is required")
    _ensure_web_tables()
    _safe_call(
        lambda: push_notifications.register_device_token(
            int(user.get("id") or 0), token, platform=payload.platform, app=payload.app
        ),
        None,
    )
    return {"message": "Push token registered"}


@app.post("/notifications/push-token/unregister")
async def unregister_push_token(payload: PushTokenRegisterRequest, authorization: str | None = Header(default=None)):
    """Called on logout so this device stops receiving pushes for the
    account that just signed out immediately."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "admin", "support"})
    token = str(payload.token or "").strip()
    if token:
        _safe_call(lambda: push_notifications.unregister_device_token(token), None)
    return {"message": "Push token unregistered"}


