@app.get("/student/placement/session")
async def student_placement_session(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_placement_access(user)
    user_id = int(user.get("id") or 0)
    required = bool(int(user.get("placement_required") or 0))
    subject = _placement_subject_for_user(user)
    session = _safe_call(lambda: get_placement_session(user_id), None) or {}
    session = _placement_apply_expired_timeouts(user_id, session)
    question_ids = session.get("questions") or []
    current_index = int(session.get("question_index") or 0)
    total = int(len(question_ids))
    started = bool(session.get("active"))
    current_question = None
    if started and current_index < total:
        current_question = _safe_call(lambda: get_test_by_id(int(question_ids[current_index])), None)
    question_started_at = session.get("question_started_at")
    time_remaining_sec = _placement_time_remaining(question_started_at) if started and current_question else PLACEMENT_TIME_LIMIT_SEC

    payload: dict[str, Any] = {
        "required": required,
        "subject": subject,
        "active": started,
        "question_index": current_index,
        "total_questions": total,
        "score": int(session.get("score") or 0),
        "time_limit_sec": PLACEMENT_TIME_LIMIT_SEC,
        "question_started_at": question_started_at,
        "time_remaining_sec": time_remaining_sec,
    }
    if current_question:
        payload["current_question"] = _placement_question_payload(current_question, current_index + 1, total)
    return _attach_proctoring_payload(user, payload, test_type="placement", test_attempt_ref="placement", test_route="/")


@app.post("/student/placement/start")
async def student_placement_start(
    payload: PlacementStartRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_placement_access(user)
    user = _require_student_face_setup_complete(user)
    user_id = int(user.get("id") or 0)
    if not bool(int(user.get("placement_required") or 0)):
        raise HTTPException(status_code=400, detail="Placement test is not required for this account")

    existing = _safe_call(lambda: get_placement_session(user_id), None) or {}
    existing = _placement_apply_expired_timeouts(user_id, existing)
    if existing.get("active") and not payload.force_restart:
        ids = existing.get("questions") or []
        idx = int(existing.get("question_index") or 0)
        if idx < len(ids):
            q = _safe_call(lambda: get_test_by_id(int(ids[idx])), None)
            if q:
                if not existing.get("question_started_at"):
                    existing["question_started_at"] = _now_utc().isoformat()
                    save_placement_session(user_id, existing)
                return _attach_proctoring_payload(user, {
                    "started": True,
                    "resumed": True,
                    "subject": _normalize_subject_label(existing.get("subject")) or _placement_subject_for_user(user),
                    "question": _placement_question_payload(q, idx + 1, len(ids)),
                    "score": int(existing.get("score") or 0),
                    "time_limit_sec": PLACEMENT_TIME_LIMIT_SEC,
                    "question_started_at": existing.get("question_started_at"),
                    "time_remaining_sec": _placement_time_remaining(existing.get("question_started_at")),
                }, test_type="placement", test_attempt_ref="placement", test_route="/")

    subject = _placement_subject_for_user(user)
    questions = _safe_call(lambda: get_tests_by_subject(subject), []) or []
    if len(questions) < 1:
        raise HTTPException(status_code=400, detail=f"Placement bank for {subject} must have at least 1 question")
    sample_size = min(50, len(questions))
    selected = random.sample(questions, sample_size)
    question_ids = [int(row.get("id") or 0) for row in selected if int(row.get("id") or 0) > 0]
    session = {
        "active": True,
        "subject": subject,
        "question_index": 0,
        "score": 0,
        "questions": question_ids,
        "question_started_at": _now_utc().isoformat(),
    }
    save_placement_session(user_id, session)
    first_question = _safe_call(lambda: get_test_by_id(int(question_ids[0])), None)
    if not first_question:
        raise HTTPException(status_code=500, detail="Could not load first placement question")
    return _attach_proctoring_payload(user, {
        "started": True,
        "subject": subject,
        "question": _placement_question_payload(first_question, 1, len(question_ids)),
        "score": 0,
        "time_limit_sec": PLACEMENT_TIME_LIMIT_SEC,
        "question_started_at": session.get("question_started_at"),
        "time_remaining_sec": _placement_time_remaining(session.get("question_started_at")),
    }, test_type="placement", test_attempt_ref="placement", test_route="/")


@app.post("/student/placement/answer")
async def student_placement_answer(payload: PlacementAnswerRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_placement_access(user)
    user_id = int(user.get("id") or 0)
    _ensure_proctoring_session_access(
        user,
        payload.proctoring_session_id,
        expected_test_type="placement",
        expected_attempt_ref="placement",
    )
    if not bool(int(user.get("placement_required") or 0)):
        raise HTTPException(status_code=400, detail="Placement test is not required for this account")

    session = _safe_call(lambda: get_placement_session(user_id), None) or {}
    session = _placement_apply_expired_timeouts(user_id, session)
    if not session.get("active"):
        raise HTTPException(status_code=400, detail="Placement session is not active. Start the test first.")
    ids = session.get("questions") or []
    index = int(session.get("question_index") or 0)
    if index >= len(ids):
        return await _complete_web_placement(user, session)

    expected_question_id = int(ids[index])
    if int(payload.question_id) != expected_question_id:
        raise HTTPException(status_code=409, detail="Question mismatch. Please refresh placement session.")

    question = _safe_call(lambda: get_test_by_id(expected_question_id), None)
    if not question:
        raise HTTPException(status_code=404, detail="Question not found")

    question_started_at = session.get("question_started_at")
    time_remaining_sec = _placement_time_remaining(question_started_at)
    timed_out = time_remaining_sec <= 0

    selected = str(payload.selected_option or "").strip().upper()
    if not selected and not timed_out:
        raise HTTPException(status_code=400, detail="selected_option is required before timeout")
    correct = str(question.get("correct_option") or "").strip().upper()
    is_correct = (not timed_out) and selected in {"A", "B", "C", "D"} and selected == correct
    if is_correct:
        session["score"] = int(session.get("score") or 0) + 10

    session["question_index"] = index + 1
    if int(session["question_index"]) >= len(ids):
        return {
            "completed": True,
            "is_correct": is_correct,
            "timed_out": timed_out,
            "time_limit_sec": PLACEMENT_TIME_LIMIT_SEC,
            "time_remaining_sec": 0,
            **(await _complete_web_placement(user, session)),
        }

    session["question_started_at"] = _now_utc().isoformat()
    save_placement_session(user_id, session)
    next_question = _safe_call(lambda: get_test_by_id(int(ids[int(session["question_index"])])), None)
    if not next_question:
        raise HTTPException(status_code=500, detail="Could not load next placement question")

    return {
        "completed": False,
        "is_correct": is_correct,
        "timed_out": timed_out,
        "score": int(session.get("score") or 0),
        "time_limit_sec": PLACEMENT_TIME_LIMIT_SEC,
        "question_started_at": session.get("question_started_at"),
        "time_remaining_sec": _placement_time_remaining(session.get("question_started_at")),
        "question": _placement_question_payload(
            next_question,
            int(session["question_index"]) + 1,
            len(ids),
        ),
    }


async def _upload_web_image(file: UploadFile, upload_dir: Path, prefix: str) -> str:
    content_type = str(file.content_type or "").split(";")[0].strip().lower()
    allowed_exts = {".jpg", ".jpeg", ".png", ".webp", ".gif"}
    original_name = Path(file.filename or "").name
    ext = Path(original_name).suffix.lower()
    is_image_type = content_type.startswith("image/")
    is_image_ext = ext in allowed_exts
    if not is_image_type and not is_image_ext:
        raise HTTPException(status_code=422, detail="Fayl turi noto'g'ri. Faqat rasm yuklash mumkin.")
    raw = await file.read()
    if not raw:
        raise HTTPException(status_code=400, detail="Fayl bo'sh.")
    if len(raw) > 7 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="Fayl hajmi juda katta. Maksimal hajm: 7MB.")
    if ext not in allowed_exts:
        guessed = (mimetypes.guess_extension(content_type) or "").lower()
        ext = guessed if guessed in allowed_exts else ".jpg"
    filename = f"{prefix}_{datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(5)}{ext}"
    upload_dir.mkdir(parents=True, exist_ok=True)
    path = upload_dir / filename
    with open(path, "wb") as handle:
        handle.write(raw)
    return filename


async def _upload_web_file(file: UploadFile, upload_dir: Path, prefix: str, max_size_mb: int = 20) -> tuple[str, str]:
    raw = await file.read()
    max_bytes = int(max_size_mb) * 1024 * 1024
    if not raw:
        raise HTTPException(status_code=400, detail="Fayl bo'sh.")
    if len(raw) > max_bytes:
        raise HTTPException(status_code=413, detail=f"Fayl hajmi juda katta. Maksimal hajm: {int(max_size_mb)}MB.")
    original_name = Path(file.filename or "upload.bin").name
    ext = Path(original_name).suffix.lower()
    if not ext or len(ext) > 10 or not re.match(r"^\.[a-z0-9]{1,9}$", ext):
        guessed = mimetypes.guess_extension(str(file.content_type or "").split(";")[0].strip().lower() or "") or ""
        ext = guessed.lower() if guessed and len(guessed) <= 10 else ".bin"
    filename = f"{prefix}_{datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(5)}{ext}"
    path = upload_dir / filename
    with open(path, "wb") as handle:
        handle.write(raw)
    content_type = str(file.content_type or "").strip().lower()
    if not content_type:
        content_type = mimetypes.guess_type(filename)[0] or "application/octet-stream"
    return filename, content_type


