@app.get("/public/videos")
async def list_public_videos(response: Response, limit: int = Query(default=120, ge=1, le=300), subject: str | None = Query(default=None)):
    response.headers["Cache-Control"] = "public, max-age=60, stale-while-revalidate=300"
    conn = get_conn()
    try:
        cur = conn.cursor()
        columns = """
            id, title, description, author, category, level, subject, teacher_id, support_teacher_ids,
            thumbnail_url, video_url, video_asset_id, duration, is_published, created_at, updated_at,
            COALESCE(view_count, 0) AS view_count,
            COALESCE(like_count, 0) AS like_count
        """
        where = "is_published = 1"
        params = []
        if subject:
            where += " AND subject = ?"
            params.append(subject)
        
        cur.execute(
            f"""
            SELECT {columns}
            FROM videos
            WHERE {where}
            ORDER BY COALESCE(view_count, 0) DESC, created_at DESC, id DESC
            LIMIT ?
            """,
            tuple([*params, int(limit)])
        )
        items = [dict(r) for r in cur.fetchall() or []]
        return {"items": items}
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.get("/public/videos/{video_id}")
async def get_public_video(video_id: int):
    conn = get_conn()
    try:
        cur = conn.cursor()
        columns = """
            id, title, description, author, category, level, subject, teacher_id, support_teacher_ids,
            thumbnail_url, video_url, video_asset_id, duration, is_published, created_at, updated_at,
            COALESCE(view_count, 0) AS view_count,
            COALESCE(like_count, 0) AS like_count
        """
        cur.execute(
            f"SELECT {columns} FROM videos WHERE id=? AND is_published=1 LIMIT 1",
            (int(video_id),)
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Video not found")
        
        # Optionally fetch some related videos
        subject = row.get("subject")
        related = []
        if subject:
            cur.execute(
                f"SELECT {columns} FROM videos WHERE is_published=1 AND subject=? AND id!=? ORDER BY created_at DESC LIMIT 5",
                (subject, int(video_id))
            )
            related = [_serialize_video_list_row(dict(r), None) for r in cur.fetchall() or []]
            
        return {"video": _serialize_video_row(dict(row), None, viewer_user_id=0), "related": related}
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.post("/public/videos/{video_id}/view")
async def record_public_video_view(video_id: int):
    conn = get_conn()
    try:
        cur = conn.cursor()
        cur.execute(
            "UPDATE videos SET view_count = COALESCE(view_count, 0) + 1 WHERE id = ?",
            (int(video_id),)
        )
        conn.commit()
        
        cur.execute("SELECT COALESCE(view_count, 0) AS view_count FROM videos WHERE id=? LIMIT 1", (int(video_id),))
        row = cur.fetchone()
        count = int(row.get("view_count") or 0) if row else 0
        return {"success": True, "view_count": count}
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.post("/public/videos/{video_id}/like")
async def record_public_video_like(video_id: int, action: str = Query("like")):
    conn = get_conn()
    try:
        cur = conn.cursor()
        increment = 1 if action == "like" else -1
        cur.execute(
            "UPDATE videos SET like_count = MAX(0, COALESCE(like_count, 0) + ?) WHERE id = ?",
            (increment, int(video_id))
        )
        conn.commit()
        
        cur.execute("SELECT COALESCE(like_count, 0) AS like_count FROM videos WHERE id=? LIMIT 1", (int(video_id),))
        row = cur.fetchone()
        count = int(row.get("like_count") or 0) if row else 0
        return {"success": True, "like_count": count}
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        try:
            conn.close()
        except Exception:
            pass



