@app.post("/public/videos/{video_id}/comments")
async def post_public_video_comment(
    video_id: int, 
    req: PublicVideoCommentRequest,
    authorization: str | None = Header(default=None)
):
    conn = get_conn()
    try:
        cur = conn.cursor()
        
        name = "Anonim"
        if authorization:
            user = _user_row_from_bearer(authorization)
            if user:
                first = str(user.get("first_name") or "").strip()
                last = str(user.get("last_name") or "").strip()
                if first or last:
                    name = f"{first} {last}".strip()
                else:
                    name = str(user.get("role") or "").capitalize()
        
        if req.author_name and req.author_name.strip():
            # Only use req.author_name if explicitly provided (e.g. legacy clients)
            name = req.author_name.strip()
            
        text = req.comment_text.strip()
        if not text:
            raise HTTPException(status_code=400, detail="Comment text is required")
            
        cur.execute(
            "INSERT INTO web_video_comments (video_id, author_name, comment_text, parent_id) VALUES (?, ?, ?, ?)",
            (int(video_id), name, text, req.parent_id)
        )
        conn.commit()
        asyncio.create_task(_notify_video_comment(int(video_id), text, name))
        return {"success": True}
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        try:
            conn.close()
        except Exception:
            pass

@app.post("/public/videos/comments/{comment_id}/vote")
async def vote_public_video_comment(comment_id: int, action: str):
    conn = get_conn()
    try:
        cur = conn.cursor()
        if action == "like":
            cur.execute("UPDATE web_video_comments SET like_count = COALESCE(like_count, 0) + 1 WHERE id = ?", (int(comment_id),))
        elif action == "dislike":
            cur.execute("UPDATE web_video_comments SET dislike_count = COALESCE(dislike_count, 0) + 1 WHERE id = ?", (int(comment_id),))
        else:
            raise HTTPException(status_code=400, detail="Invalid action")
            
        cur.execute("SELECT like_count, dislike_count FROM web_video_comments WHERE id = ?", (int(comment_id),))
        row = cur.fetchone()
        conn.commit()
        if not row:
            raise HTTPException(status_code=404, detail="Comment not found")
            
        return {"success": True, "like_count": row["like_count"] or 0, "dislike_count": row["dislike_count"] or 0}
    except HTTPException:
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        try:
            conn.close()
        except Exception:
            pass

@app.get("/public/call/{phone}")
async def redirect_to_call(phone: str):
    safe_phone = "".join([c for c in str(phone or "").replace(" ", "+") if c.isdigit() or c == "+"])
    if safe_phone and not safe_phone.startswith("+") and safe_phone.startswith("998"):
        safe_phone = f"+{safe_phone}"
    from fastapi.responses import RedirectResponse
    return RedirectResponse(url=f"tel:{safe_phone}")


@app.post("/public/callbacks")
async def public_callback(payload: CallbackCreateRequest):
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    
    cur.execute(
        "INSERT INTO web_callbacks (name, phone, subject, status) VALUES (?, ?, ?, 'pending')",
        (payload.name, payload.phone, payload.subject)
    )
    
    cur.execute("SELECT id, telegram_id, login_type FROM users WHERE login_type IN (4, 5) AND blocked=0")
    admins = [dict(r) for r in (cur.fetchall() or [])]
    callback_source = f"callback:{int(time.time() * 1000)}"

    # Notify via web
    for admin in admins:
        uid = int(admin.get("id") or 0)
        if uid > 0:
            _payment_upsert_web_notification(
                cur,
                user_id=uid,
                notification_type="callback_request",
                title="Yangi ariza",
                message=f"Yangi qo'ng'iroq arizasi keldi. Tafsilotlarni admin paneldan ko'ring.",
                button_text="Arizalarni ko'rish",
                button_url="/admin?section=admin-callbacks",
                target_screen="admin-callbacks",
                source_key=callback_source,
                meta={}
            )
    conn.commit()
    conn.close()

    async def _send_tg():
        when_text = datetime.now(pytz.timezone("Asia/Tashkent")).strftime("%Y-%m-%d %H:%M")
        message = (
            f"🚨 Yangi ariza keldi! ({when_text})\n\n"
            "Tafsilotlarni ko'rish uchun tugmani bosing 👇"
        )
        mini_app_url = f"{WEBAPP_URL}/admin?section=admin-callbacks" if WEBAPP_URL else None
        token = (os.getenv("ADMIN_BOT_TOKEN") or "").strip()
        config_chat_ids = [int(x) for x in ((ADMIN_CHAT_IDS or []) + (LIMITED_ADMIN_CHAT_IDS or [])) if int(x or 0) > 0]
        db_chat_ids = [
            int(str(admin.get("telegram_id") or "0"))
            for admin in admins
            if str(admin.get("telegram_id") or "").strip().isdigit()
        ]
        admin_chat_ids = list(dict.fromkeys(config_chat_ids + db_chat_ids))
        if token and admin_chat_ids:
            for chat_id in admin_chat_ids:
                try:
                    ok = await _send_telegram_text(
                        token,
                        str(chat_id),
                        message,
                        button_text="📋 Arizalarni ko'rish",
                        button_url=mini_app_url,
                        button_web_app=True,
                    )
                    if not ok:
                        logger.warning("callback admin telegram notification failed chat_id=%s source=%s", chat_id, callback_source)
                except Exception:
                    logger.exception("callback admin telegram notification exception chat_id=%s source=%s", chat_id, callback_source)

    await _send_tg()

    return {"message": "ok"}


