@app.post("/reviews")
async def create_student_review(payload: ReviewCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "accountless"})
    policy = _review_policy_for_user(user)
    if not bool(policy.get("can_submit")):
        raise HTTPException(status_code=409, detail=str(policy.get("reason") or "Review policy does not allow submission right now."))
    text = str(payload.review_text or "").strip()
    if len(text) < 5:
        raise HTTPException(status_code=400, detail="Review text is too short")
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    author_name = _display_name(user)
    cur.execute(
        """
        INSERT INTO web_student_reviews (user_id, rating, review_text, is_anonymous, status, author_name)
        VALUES (?, ?, ?, ?, 'pending', ?)
        RETURNING *
        """,
        (
            int(user.get("id") or 0),
            max(1, min(5, int(payload.rating))),
            text[:1800],
            0,
            author_name,
        ),
    )
    row = dict(cur.fetchone() or {})
    conn.commit()
    conn.close()
    return {
        "message": "Review submitted and pending moderation",
        "review_id": int(row.get("id") or 0) if row else None,
        "review": _serialize_review_row(row, include_private=True) if row else None,
        "review_policy": _review_policy_for_user(user),
    }


