@app.post("/admin/reviews/{review_id}/status")
async def admin_review_status(review_id: int, payload: ReviewStatusRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    next_status = _normalize_review_status(payload.status, default="approved")
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM web_student_reviews WHERE id=? LIMIT 1", (int(review_id),))
    before = dict(cur.fetchone() or {})
    if not before:
        conn.close()
        raise HTTPException(status_code=404, detail="Review not found")
    cur.execute(
        """
        UPDATE web_student_reviews
        SET status=?, reviewed_by=?, reviewed_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (next_status, int(user.get("id") or 0), int(review_id)),
    )
    conn.commit()
    affected = int(cur.rowcount or 0)
    conn.close()
    if affected <= 0:
        raise HTTPException(status_code=404, detail="Review not found")
    reward_granted = False
    reward_amount = 0.0
    if next_status == "approved" and not before.get("reward_granted_at"):
        student_id = int(before.get("user_id") or 0)
        student = _safe_call(lambda: get_user_by_id(student_id), None)
        if student:
            reward_amount = 100.0
            conn = get_conn()
            cur = conn.cursor()
            cur.execute(
                """
                UPDATE web_student_reviews
                SET reward_dcoin=?, reward_granted_at=CURRENT_TIMESTAMP
                WHERE id=? AND reward_granted_at IS NULL
                """,
                (reward_amount, int(review_id)),
            )
            conn.commit()
            reward_granted = bool(cur.rowcount and cur.rowcount > 0)
            conn.close()
            if reward_granted:
                subject = (_user_subjects_from_row(student) or ["English"])[0]
                add_dpoints(student_id, reward_amount, subject=subject, change_type="approved_review_reward")
                token = (os.getenv("STUDENT_BOT_TOKEN") or "").strip()
                tg = str(student.get("telegram_id") or "").strip()
                if token and tg:
                    await _send_telegram_text(
                        token,
                        tg,
                        "Reviewingiz admin tomonidan tasdiqlandi. Hisobingizga +100 D'point qo'shildi.",
                    )
    updated_review = _get_review_row(int(review_id)) or {**before, "status": next_status}
    return {
        "message": "Review status updated",
        "review_id": int(review_id),
        "status": next_status,
        "review": _serialize_review_row(updated_review, include_private=True),
        "reward_granted": reward_granted,
        "reward_dcoin": reward_amount if reward_granted else 0,
        "reward_dpoints": reward_amount if reward_granted else 0,
    }


