@app.post("/admin/upload/media")
@app.post("/teacher/upload/media")
@app.post("/support/upload/media")
async def admin_upload_media(
    file: UploadFile = File(...),
    asset_type: str = Form(default="file"),
    target: str | None = Form(default=None),
    entity_id: int | None = Form(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"admin", "teacher", "support"})
    ensure_media_assets_schema()

    normalized_type = str(asset_type or "").strip().lower()
    if normalized_type in {"image", "thumbnail", "cover"}:
        normalized_type = "file"
    if normalized_type not in {"video", "book", "pdf", "file"}:
        normalized_type = "file"
    if role in {"teacher", "support"}:
        actor_id = int(user.get("id") or 0)
        can_video = _safe_call(lambda: get_video_upload_permission(actor_id), False)
        can_book = _safe_call(lambda: get_book_upload_permission(actor_id), False)
        if normalized_type == "video" and not can_video:
            raise HTTPException(status_code=403, detail="Video yuklash uchun ruxsat yo'q")
        if normalized_type in {"book", "pdf"} and not can_book:
            raise HTTPException(status_code=403, detail="Kitob yuklash uchun ruxsat yo'q")
        if normalized_type == "file" and not (can_video or can_book):
            raise HTTPException(status_code=403, detail="Media yuklash uchun ruxsat yo'q")
    file_name = Path(str(file.filename or "")).name
    lowered_name = file_name.lower()
    detected_content_type = str(getattr(file, "content_type", "") or "").strip().lower()
    if normalized_type == "video":
        if not (
            detected_content_type.startswith("video/")
            or lowered_name.endswith((".mp4", ".mov", ".mkv", ".webm", ".m4v"))
        ):
            raise HTTPException(status_code=422, detail="Fayl turi noto'g'ri. Video fayl yuklang.")
    elif normalized_type in {"book", "pdf"}:
        if not (detected_content_type == "application/pdf" or lowered_name.endswith(".pdf")):
            raise HTTPException(status_code=422, detail="Fayl turi noto'g'ri. Faqat PDF fayl yuklash mumkin.")
    elif normalized_type == "file":
        # Generic upload bucket is mostly used for images/covers in admin forms.
        if not (
            detected_content_type.startswith("image/")
            or lowered_name.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg"))
        ):
            raise HTTPException(status_code=422, detail="Fayl turi noto'g'ri. Faqat rasm yuklash mumkin.")
    max_size_mb = 2000 if normalized_type == "video" else (80 if normalized_type in {"book", "pdf"} else 12)
    filename, content_type = await _upload_web_file(file, MEDIA_UPLOAD_DIR, f"media_{normalized_type}", max_size_mb=max_size_mb)
    file_path = MEDIA_UPLOAD_DIR / filename
    size_bytes = int(file_path.stat().st_size) if file_path.exists() else 0

    asset = create_media_asset(
        asset_type=normalized_type,
        storage_path=filename,
        original_name=Path(str(file.filename or filename)).name,
        content_type=content_type,
        size_bytes=size_bytes,
        uploaded_by=int(user.get("id") or 0),
    )
    if not asset:
        raise HTTPException(status_code=500, detail="Media faylni saqlab bo'lmadi. Qayta urinib ko'ring.")

    asset_id = int(asset.get("id") or 0)
    target_normalized = str(target or "").strip().lower()
    if asset_id > 0 and target_normalized in {"video", "book"} and int(entity_id or 0) > 0:
        conn = get_conn()
        cur = conn.cursor()
        if target_normalized == "video":
            cur.execute(
                """
                UPDATE videos
                SET video_asset_id=?, updated_at=CURRENT_TIMESTAMP
                WHERE id=?
                """,
                (asset_id, int(entity_id)),
            )
        else:
            cur.execute(
                """
                UPDATE books
                SET pdf_asset_id=?, updated_at=CURRENT_TIMESTAMP
                WHERE id=?
                """,
                (asset_id, int(entity_id)),
            )
        conn.commit()
        conn.close()
        if target_normalized == "video":
            _clear_video_list_caches()
        else:
            _clear_book_list_caches()

    stream_url = _build_media_stream_url(asset_id, user_id=int(user.get("id") or 0)) if asset_id > 0 else None
    public_url = _build_media_public_url(asset_id) if asset_id > 0 and normalized_type == "file" else None
    return {
        "message": "Media uploaded",
        "asset": {
            "id": asset_id or None,
            "asset_type": asset.get("asset_type"),
            "content_type": asset.get("content_type"),
            "size_bytes": int(asset.get("size_bytes") or 0),
            "original_name": asset.get("original_name"),
            "stream_url": stream_url,
            "public_url": public_url,
            "target": target_normalized or None,
            "entity_id": int(entity_id or 0) or None,
        },
    }


@app.get("/media/public/{asset_id}")
async def media_public_asset(asset_id: int):
    asset = get_media_asset(int(asset_id))
    if not asset or int(asset.get("is_active") or 0) != 1:
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    stored_name = Path(str(asset.get("storage_path") or "")).name
    if not stored_name:
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    content_type = str(asset.get("content_type") or "").strip().lower()
    if not content_type.startswith("image/"):
        raise HTTPException(status_code=403, detail="Public access allowed only for image assets")
    file_path = MEDIA_UPLOAD_DIR / stored_name
    if not file_path.exists() or not file_path.is_file():
        placeholder = _image_placeholder_response()
        if placeholder is not None:
            return placeholder
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    return FileResponse(
        str(file_path),
        media_type=content_type or mimetypes.guess_type(stored_name)[0] or "application/octet-stream",
        headers={
            "Cache-Control": "public, max-age=300, stale-while-revalidate=60",
            "X-Content-Type-Options": "nosniff",
        },
    )


@app.get("/media/stream/{asset_id}")
async def media_stream_asset(
    asset_id: int,
    request: Request,
    token: str = Query(default=""),
    authorization: str | None = Header(default=None),
):
    token_ok = _verify_media_stream_token(int(asset_id), token)
    if not token_ok:
        viewer = _user_row_from_bearer(authorization)
        if not viewer:
            raise HTTPException(status_code=401, detail="Invalid or expired media token")
        _require_role(viewer, {"student", "teacher", "admin", "support"})

    asset = get_media_asset(int(asset_id))
    if not asset or int(asset.get("is_active") or 0) != 1:
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))

    stored_name = Path(str(asset.get("storage_path") or "")).name
    if not stored_name:
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    file_path = MEDIA_UPLOAD_DIR / stored_name
    if not file_path.exists() or not file_path.is_file():
        logger.error(f"Media file not found physically: {file_path}")
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))

    media_type = str(asset.get("content_type") or "").strip().lower() or mimetypes.guess_type(stored_name)[0] or "application/octet-stream"
    asset_type = str(asset.get("asset_type") or "").strip().lower()

    # Videos require HTTP Range support for browser seeking/scrubbing.
    if asset_type == "video" or media_type.startswith("video/"):
        file_size = file_path.stat().st_size
        range_header = request.headers.get("range", "").strip()
        if range_header:
            _rm = re.match(r"bytes=(\d+)-(\d*)", range_header)
            if _rm:
                _start = int(_rm.group(1))
                _end = int(_rm.group(2)) if _rm.group(2) else file_size - 1
                _end = min(_end, file_size - 1)
                if _start > _end or _start >= file_size:
                    raise HTTPException(status_code=416, detail="Range Not Satisfiable")
                _chunk = _end - _start + 1

                def _iter_chunk(path: Path, s: int, length: int):
                    # 1MB li chunklar: 64KB da har chunk uchun threadpool iteratsiyasi
                    # kerak edi — video to'xtab-to'xtab o'ynashining asosiy sababi.
                    with open(path, "rb") as _f:
                        _f.seek(s)
                        _rem = length
                        while _rem > 0:
                            _buf = _f.read(min(1024 * 1024, _rem))
                            if not _buf:
                                break
                            _rem -= len(_buf)
                            yield _buf

                return StreamingResponse(
                    _iter_chunk(file_path, _start, _chunk),
                    status_code=206,
                    media_type=media_type,
                    headers={
                        "Content-Range": f"bytes {_start}-{_end}/{file_size}",
                        "Accept-Ranges": "bytes",
                        "Content-Length": str(_chunk),
                        "Cache-Control": "private, max-age=3600",
                        "Content-Disposition": "inline",
                    },
                )
        # Full video response — advertise Range support
        return FileResponse(
            str(file_path),
            media_type=media_type,
            content_disposition_type="inline",
            headers={
                "Accept-Ranges": "bytes",
                "Content-Length": str(file_size),
                "Cache-Control": "private, max-age=3600",
            },
        )

    # PDFs and other files — inline, no range needed
    return FileResponse(
        str(file_path),
        media_type=media_type,
        filename=Path(str(asset.get("original_name") or stored_name)).name,
        content_disposition_type="inline",
        headers={"Cache-Control": "private, max-age=30"},
    )


@app.get("/media/book-open-once/{open_token}")
async def media_book_open_once(open_token: str):
    _ensure_book_external_open_schema()
    token = str(open_token or "").strip()
    if not token.startswith("book_"):
        raise HTTPException(status_code=404, detail="Link topilmadi")
    now_iso = _now_utc().isoformat()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM book_external_open_tokens WHERE token=? LIMIT 1", (token,))
        row = dict(cur.fetchone() or {})
        if not row:
            raise HTTPException(status_code=404, detail="Link topilmadi")
        if row.get("used_at"):
            raise HTTPException(status_code=410, detail="Bu havola allaqachon ishlatilgan")
        expires = _parse_utc_timestamp(str(row.get("expires_at") or ""))
        if expires is None or expires < _now_utc():
            raise HTTPException(status_code=410, detail="Havola muddati tugagan")
        cur.execute(
            "UPDATE book_external_open_tokens SET used_at=? WHERE token=? AND used_at IS NULL",
            (now_iso, token),
        )
        if int(getattr(cur, "rowcount", 0) or 0) <= 0:
            raise HTTPException(status_code=410, detail="Bu havola allaqachon ishlatilgan")
        conn.commit()
        asset_id = int(row.get("asset_id") or 0)
    except HTTPException:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("book open once consume failed")
        raise HTTPException(status_code=500, detail="Kitob ochilmadi")
    finally:
        conn.close()

    asset = get_media_asset(asset_id)
    if not asset or int(asset.get("is_active") or 0) != 1:
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    stored_name = Path(str(asset.get("storage_path") or "")).name
    file_path = MEDIA_UPLOAD_DIR / stored_name
    if not stored_name or not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail=_clean_media_missing_detail(asset))
    media_type = str(asset.get("content_type") or "").strip().lower() or "application/pdf"
    if media_type != "application/pdf":
        raise HTTPException(status_code=403, detail="Faqat PDF ochish mumkin")
    return FileResponse(
        str(file_path),
        media_type="application/pdf",
        content_disposition_type="inline",
        headers={
            "Cache-Control": "no-store, no-cache, max-age=0, must-revalidate",
            "Pragma": "no-cache",
            "Expires": "0",
            "X-Content-Type-Options": "nosniff",
            "Content-Disposition": "inline",
        },
    )


