    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Article not found")
    current = dict(row)
    vis_student = int(current.get("visible_students") or 0)
    vis_teacher = int(current.get("visible_teachers") or 0)
    vis_support = int(current.get("visible_support") or 0)
    vis_admin = int(current.get("visible_admins") or 0)
    tags_json = current.get("tags_json")
    if payload.visibility is not None:
        vis_student, vis_teacher, vis_support, vis_admin = _visibility_to_columns(payload.visibility)
    if payload.tags is not None:
        tags_json = json.dumps([str(tag).strip() for tag in (payload.tags or []) if str(tag).strip()][:20])

    cur.execute(
        """
        UPDATE web_articles
        SET title=?,
            content=?,
            category=?,
            status=?,
            read_minutes=?,
            featured_image_url=?,
            publisher_first_name=?,
            publisher_last_name=?,
            tags_json=?,
            visible_students=?,
            visible_teachers=?,
            visible_support=?,
            visible_admins=?,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (
            payload.title.strip() if payload.title is not None else current.get("title"),
            payload.content.strip() if payload.content is not None else current.get("content"),
            payload.category.strip() if payload.category is not None else current.get("category"),
            payload.status if payload.status is not None else current.get("status"),
            int(payload.read_minutes) if payload.read_minutes is not None else int(current.get("read_minutes") or 6),
            (payload.featured_image_url or "").strip() if payload.featured_image_url is not None else current.get("featured_image_url"),
            (payload.publisher_first_name or "").strip() if payload.publisher_first_name is not None else current.get("publisher_first_name"),
            (payload.publisher_last_name or "").strip() if payload.publisher_last_name is not None else current.get("publisher_last_name"),
            tags_json,
            vis_student,
            vis_teacher,
            vis_support,
            vis_admin,
            int(article_id),
        ),
    )
    conn.commit()
    conn.close()
    return {"message": "Article updated", "article_id": int(article_id)}


