async def get_admin_competitions_history(
    mode: str = Query("arena-group"),
    page: int = Query(1, ge=1),
    limit: int = Query(50, ge=1, le=100),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    
    conn = get_conn()
    cur = conn.cursor()
    offset = (page - 1) * limit
    try:
        if mode == "arena-group":
            cur.execute("SELECT COUNT(*) as c FROM arena_group_sessions")
            total = int(cur.fetchone().get("c", 0) or 0)
            cur.execute('''
                SELECT s.id, s.group_id, s.subject, s.level, s.status, s.created_at,
                       (SELECT COUNT(*) FROM arena_group_session_attempts WHERE session_id = s.id) as participants_count
                FROM arena_group_sessions s
                ORDER BY s.id DESC
                LIMIT %s OFFSET %s
            ''', [limit, offset])
            items = cur.fetchall()
            
        elif mode == "arena-daily":
            cur.execute("SELECT COUNT(*) as c FROM arena_daily_sessions")
            total = int(cur.fetchone().get("c", 0) or 0)
            cur.execute('''
                SELECT s.id, s.subject, s.level, s.status, s.created_at,
                       (SELECT COUNT(*) FROM arena_daily_session_attempts WHERE session_id = s.id) as participants_count
                FROM arena_daily_sessions s
                ORDER BY s.id DESC
                LIMIT %s OFFSET %s
            ''', [limit, offset])
            items = cur.fetchall()
            
        elif mode == "arena-boss":
            cur.execute("SELECT COUNT(*) as c FROM arena_boss_sessions")
            total = int(cur.fetchone().get("c", 0) or 0)
            cur.execute('''
                SELECT s.id, s.subject, s.level, s.status, s.created_at,
                       (SELECT COUNT(*) FROM arena_boss_session_attempts WHERE session_id = s.id) as participants_count
                FROM arena_boss_sessions s
                ORDER BY s.id DESC
                LIMIT %s OFFSET %s
            ''', [limit, offset])
            items = cur.fetchall()
            
        elif mode == "duel":
            cur.execute("SELECT COUNT(DISTINCT session_id) as c FROM arena_duel_match_participants")
            total = int(cur.fetchone().get("c", 0) or 0)
            cur.execute('''
                SELECT session_id as id,
                       MAX(mode) as subject,
                       MAX(created_at) as created_at,
                       COUNT(user_id) as participants_count
                FROM arena_duel_match_participants
                GROUP BY session_id
                ORDER BY MAX(id) DESC
                LIMIT %s OFFSET %s
            ''', [limit, offset])
            items = cur.fetchall()
        else:
            total = 0
            items = []
            
        return {"items": items, "total": total, "page": page, "limit": limit}
    finally:
        conn.close()

