@app.post("/admin/results")
async def admin_create_result(payload: ResultCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    student_name = str(payload.student_name or "").strip()
    if len(student_name) < 2:
        raise HTTPException(status_code=400, detail="Student name is too short")
    media = [str(item).strip() for item in (payload.media or []) if str(item).strip()][:32]
    result_type = str(payload.result_type or "IELTS").strip() or "IELTS"
    subject = (payload.subject or "").strip() if result_type == "Milliy Sertifikat" else None
    university_name = (payload.university_name or "").strip() if result_type == "Universitet" else None
    university_scope = (payload.university_scope or "").strip() if result_type == "Universitet" else None
    university_country = (payload.university_country or "").strip() if result_type == "Universitet" else None
    university_city = (payload.university_city or "").strip() if result_type == "Universitet" else None
    grant_percent = payload.grant_percent if result_type == "Universitet" and payload.grant_percent is not None else None
    if grant_percent is not None:
        grant_percent = max(0.0, min(100.0, float(grant_percent)))
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO web_results
        (
            student_name, result_type, subject, university_name, university_scope,
            university_country, university_city, grant_percent, score_text, level_text, exam_date, description,
            image_url, media_json, status, created_by, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'published', ?, CURRENT_TIMESTAMP)
        RETURNING id
        """,
        (
            student_name,
            result_type,
            subject,
            university_name,
            university_scope,
            university_country,
            university_city,
            grant_percent,
            (payload.score_text or "").strip() or None,
            (payload.level_text or "").strip() or None,
            (payload.exam_date or "").strip() or None,
            (payload.description or "").strip() or None,
            (payload.image_url or "").strip() or None,
            json.dumps(media),
            int(user.get("id") or 0),
        ),
    )
    row = cur.fetchone()
    conn.commit()
    conn.close()
    return {"message": "Result created", "result_id": int(row.get("id") or 0) if row else 0}


@app.patch("/admin/results/{result_id}")
async def admin_patch_result(result_id: int, payload: ResultUpdateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM web_results WHERE id=? LIMIT 1", (int(result_id),))
    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Result not found")
    current = dict(row)
    media_json = current.get("media_json")
    if payload.media is not None:
        media_json = json.dumps([str(item).strip() for item in (payload.media or []) if str(item).strip()][:32])
    next_result_type = str(payload.result_type or current.get("result_type") or "IELTS").strip() or "IELTS"
    next_subject = (
        (payload.subject or "").strip() if payload.subject is not None else str(current.get("subject") or "").strip()
    )
    if next_result_type != "Milliy Sertifikat":
        next_subject = ""
    next_university_name = (
        (payload.university_name or "").strip() if payload.university_name is not None else str(current.get("university_name") or "").strip()
    )
    next_university_scope = (
        (payload.university_scope or "").strip() if payload.university_scope is not None else str(current.get("university_scope") or "").strip()
    )
    next_university_country = (
        (payload.university_country or "").strip() if payload.university_country is not None else str(current.get("university_country") or "").strip()
    )
    next_university_city = (
        (payload.university_city or "").strip() if payload.university_city is not None else str(current.get("university_city") or "").strip()
    )
    if payload.grant_percent is not None:
        next_grant_percent = max(0.0, min(100.0, float(payload.grant_percent)))
    else:
        next_grant_percent = current.get("grant_percent")
    if next_result_type != "Universitet":
        next_university_name = ""
        next_university_scope = ""
        next_university_country = ""
        next_university_city = ""
        next_grant_percent = None
    cur.execute(
        """
        UPDATE web_results
        SET student_name=?,
            result_type=?,
            subject=?,
            university_name=?,
            university_scope=?,
            university_country=?,
            university_city=?,
            grant_percent=?,
            score_text=?,
            level_text=?,
            exam_date=?,
            description=?,
            image_url=?,
            media_json=?,
            status=?,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (
            (payload.student_name or "").strip() if payload.student_name is not None else current.get("student_name"),
            next_result_type,
            next_subject or None,
            next_university_name or None,
            next_university_scope or None,
            next_university_country or None,
            next_university_city or None,
            next_grant_percent,
            (payload.score_text or "").strip() if payload.score_text is not None else current.get("score_text"),
            (payload.level_text or "").strip() if payload.level_text is not None else current.get("level_text"),
            (payload.exam_date or "").strip() if payload.exam_date is not None else current.get("exam_date"),
            (payload.description or "").strip() if payload.description is not None else current.get("description"),
            (payload.image_url or "").strip() if payload.image_url is not None else current.get("image_url"),
            media_json,
            "published",
            int(result_id),
        ),
    )
    conn.commit()
    conn.close()
    return {"message": "Result updated", "result_id": int(result_id)}


def _delete_result_file_by_url(url: str | None):
    if not url: return
    url = url.strip()
    if not url: return
    if url.startswith("http"): return
    if url.startswith("/results/media/") or url.startswith("/results/images/"):
        filename = url.split("/")[-1]
        safe = Path(filename).name
        if safe == filename:
            file_path = RESULT_UPLOAD_DIR / safe
            if file_path.exists() and file_path.is_file():
                try:
                    file_path.unlink()
                except Exception:
                    pass

@app.delete("/admin/results/media/{filename}")
async def admin_delete_result_media(filename: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _delete_result_file_by_url(f"/results/media/{filename}")
    return {"message": "File deleted"}

@app.delete("/admin/results/{result_id}")
async def admin_delete_result(result_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT image_url, media_json FROM web_results WHERE id=? LIMIT 1", (int(result_id),))
    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Result not found")
        
    image_url = row.get("image_url")
    media_json = row.get("media_json")
    
    cur.execute("DELETE FROM web_results WHERE id=?", (int(result_id),))
    conn.commit()
    affected = int(cur.rowcount or 0)
    conn.close()
    
    if affected > 0:
        _delete_result_file_by_url(image_url)
        if media_json:
            try:
                media_list = json.loads(media_json)
                for m in media_list:
                    _delete_result_file_by_url(m)
            except Exception:
                pass

    return {"message": "Result deleted", "result_id": int(result_id)}


