@app.get("/admin/homework/{homework_id}/report")
async def admin_homework_report(homework_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, "admin")
    from db import get_homework, get_group_users, get_content_test, get_content_test_result, list_homeworks_for_teacher
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
        
    group_id = int(homework.get("group_id") or 0)
    teacher_id = int(homework.get("teacher_id") or 0)
    
    rows = [row for row in (_safe_call(lambda: list_homeworks_for_teacher(teacher_id), []) or []) if int(row.get("id") or 0) == int(homework_id)]
    
    if not rows:
        members = _safe_call(lambda: get_group_users(group_id), []) or []
        rows = [
            {
                **homework,
                "student_id": int(m.get("id") or 0),
                "student_first_name": m.get("first_name"),
                "student_last_name": m.get("last_name"),
                "student_profile_image_url": m.get("profile_image_url"),
            }
            for m in members
            if int(m.get("login_type") or 0) in (1, 2, 6)
        ]
        
    test = _safe_call(lambda: get_content_test("homework", int(homework_id), include_inactive=False, include_answers=False), None)
    items: list[dict[str, Any]] = []
    for row in rows:
        _attach_homework_runtime_fields(row)
        sid = int(row.get("submission_student_id") or row.get("student_id") or 0)
        result = _safe_call(lambda student_id=sid: get_content_test_result(student_id, "homework", int(homework_id)), None) if sid > 0 else None
        items.append(
            {
                **row,
                "student_id": sid,
                "uploaded": bool(row.get("proof_images") or row.get("proof_image_url")),
                "uploaded_at": row.get("submission_created_at") or row.get("submission_updated_at"),
                "test_available": bool(test),
                "test_completed": bool(result),
                "test_result": result,
                "test_correct_count": int((result or {}).get("correct_count") or (result or {}).get("correct") or 0),
                "test_wrong_count": int((result or {}).get("wrong_count") or (result or {}).get("wrong") or 0),
                "test_skipped_count": int((result or {}).get("skipped_count") or (result or {}).get("skipped") or 0),
                "test_total_questions": int((result or {}).get("total_questions") or (result or {}).get("total") or 0),
                "test_dpoints_delta": float((result or {}).get("dpoints_delta") or 0.0),
                "test_submitted_at": (result or {}).get("submitted_at"),
            }
        )
    return {"homework": homework, "test": _sanitize_content_test_for_student(test), "items": items, "total": len(items)}


@app.get("/admin/users")
async def admin_users(
    q: str | None = Query(default=None),
    role: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    limit: int = Query(default=120, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_admin_perf_indexes()
    _safe_call(_ensure_proctoring_schema_runtime_fast, None)
    role_filter = str(role or "").strip().lower()
    normalized_subject = _normalize_subject_label(subject)
    query = str(q or "").strip().lower()
    where_clauses: list[str] = ["1=1"]
    params: list[Any] = []

    if query:
        where_clauses.append(
            "LOWER(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'') || ' ' || COALESCE(u.phone,'') || ' ' || COALESCE(u.login_id,'')) LIKE ?"
        )
        params.append(f"%{query}%")

    if role_filter and role_filter != "all":
        if role_filter == "student":
            where_clauses.append("u.login_type IN (1,2,6)")
        elif role_filter == "teacher":
            where_clauses.append("u.login_type=3")
        elif role_filter == "support":
            where_clauses.append("u.login_type=5")
        elif role_filter == "admin":
            where_clauses.append("u.login_type=4")

    if normalized_subject:
        where_clauses.append("LOWER(COALESCE(u.subject,'')) LIKE ?")
        params.append(f"%{normalized_subject.lower()}%")

    where_sql = " AND ".join(where_clauses)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT COUNT(*) AS c
        FROM users u
        WHERE {where_sql}
        """,
        tuple(params),
    )
    total = int((cur.fetchone() or {}).get("c") or 0)

    rows: list[dict[str, Any]] = []
    try:
        cur.execute(
            f"""
            WITH paged_users AS (
                SELECT u.*
                FROM users u
                WHERE {where_sql}
                ORDER BY COALESCE(u.created_at, CURRENT_TIMESTAMP) DESC, u.id DESC
                LIMIT ? OFFSET ?
            ),
            fp_idx AS (
                SELECT user_id, MAX(id) AS profile_id
                FROM user_face_profiles
                WHERE status='active'
                  AND user_id IN (SELECT id FROM paged_users)
                GROUP BY user_id
            ),
            group_counts AS (
                SELECT ug.user_id, COUNT(DISTINCT ug.group_id) AS group_count
                FROM user_groups ug
                LEFT JOIN groups g ON g.id = ug.group_id
                WHERE ug.user_id IN (SELECT id FROM paged_users)
                  AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT)) = '')
                  AND (g.id IS NULL OR COALESCE(g.active, 1)=1)
                GROUP BY ug.user_id
            )
            SELECT
                pu.*,
                COALESCE(NULLIF(pu.profile_image_url, ''), fp.reference_image_url) AS effective_profile_image_url,
                fp.reference_image_url AS face_reference_image_url,
                COALESCE(gc.group_count, 0) AS group_count
            FROM paged_users pu
            LEFT JOIN fp_idx ON fp_idx.user_id = pu.id
            LEFT JOIN user_face_profiles fp ON fp.id = fp_idx.profile_id
            LEFT JOIN group_counts gc ON gc.user_id = pu.id
            ORDER BY COALESCE(pu.created_at, CURRENT_TIMESTAMP) DESC, pu.id DESC
            """,
            tuple([*params, int(limit), int(offset)]),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        cur.execute(
            f"""
            WITH paged_users AS (
                SELECT u.*
                FROM users u
                WHERE {where_sql}
                ORDER BY COALESCE(u.created_at, CURRENT_TIMESTAMP) DESC, u.id DESC
                LIMIT ? OFFSET ?
            ),
            fp_idx AS (
                SELECT user_id, MAX(id) AS profile_id
                FROM user_face_profiles
                WHERE status='active'
                  AND user_id IN (SELECT id FROM paged_users)
                GROUP BY user_id
            ),
            group_counts AS (
                SELECT ug.user_id, COUNT(DISTINCT ug.group_id) AS group_count
                FROM user_groups ug
                WHERE ug.user_id IN (SELECT id FROM paged_users)
                GROUP BY ug.user_id
            )
            SELECT
                pu.*,
                COALESCE(NULLIF(pu.profile_image_url, ''), fp.reference_image_url) AS effective_profile_image_url,
                fp.reference_image_url AS face_reference_image_url,
                COALESCE(gc.group_count, 0) AS group_count
            FROM paged_users pu
            LEFT JOIN fp_idx ON fp_idx.user_id = pu.id
            LEFT JOIN user_face_profiles fp ON fp.id = fp_idx.profile_id
            LEFT JOIN group_counts gc ON gc.user_id = pu.id
            ORDER BY COALESCE(pu.created_at, CURRENT_TIMESTAMP) DESC, pu.id DESC
            """,
            tuple([*params, int(limit), int(offset)]),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    conn.close()
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 750:
        logger.info(
            "perf admin.users.list total_ms=%.2f total=%s rows=%s role=%s q=%s",
            elapsed_ms,
            total,
            len(rows),
            role_filter or "all",
            bool(query),
        )

    return {
        "items": [_serialize_user_row_light(u) for u in rows],
        "total": int(total),
        "limit": int(limit),
        "offset": int(offset),
    }


