@app.post("/admin/users", response_model=AdminUserCreateResponse)
async def admin_create_user(payload: AdminUserCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    from auth import create_user_sync
    admin_ref = _admin_ref_id(user)

    normalized_type = (payload.user_type or "").strip().lower()
    is_new_student_with_test = normalized_type in {"new_student_with_test", "new_student", "student_test"}
    is_existing_student = normalized_type in {"existing_student", "student", "existing"}
    is_teacher = normalized_type in {"teacher", "new_teacher"}
    is_support_teacher = normalized_type in {"support", "support_teacher"}

    if is_new_student_with_test:
        login_type = 1
        role = "student"
    elif is_existing_student:
        login_type = 2
        role = "student"
    elif is_teacher:
        login_type = 3
        role = "teacher"
    elif is_support_teacher:
        login_type = 5
        role = "support"
    else:
        raise HTTPException(
            status_code=400,
            detail="user_type must be one of: new_student_with_test, existing_student, teacher, support_teacher",
        )

    referral_source_user = None
    if payload.referral_student_id is not None and int(payload.referral_student_id) > 0:
        referral_source_user = _safe_call(lambda: get_user_by_id(int(payload.referral_student_id or 0)), None)
        if not referral_source_user:
            raise HTTPException(status_code=404, detail="Referral source student not found")
        if int(referral_source_user.get("login_type") or 0) not in (1, 2, 6):
            raise HTTPException(status_code=400, detail="Referral source must be a student or accountless student")

    provided_subjects = _normalize_subjects(payload.subjects, fallback=[])
    if is_teacher or is_support_teacher:
        if (payload.level or "").strip():
            raise HTTPException(status_code=400, detail="teacher/support_teacher must not include level")
        if (payload.placement_subject or "").strip():
            raise HTTPException(status_code=400, detail="teacher/support_teacher must not include placement_subject")
        if not provided_subjects:
            raise HTTPException(status_code=400, detail="Teacher/support_teacher must have at least one subject")
        subjects = provided_subjects
        placement_required = False
        level_to_store = None
        placement_subject = subjects[0]
    elif is_existing_student:
        if (payload.placement_subject or "").strip():
            raise HTTPException(status_code=400, detail="existing_student must not include placement_subject")
        subjects = []
        placement_required = False
        level_to_store = (payload.level or "").strip().upper() or "PRE-INTERMEDIATE"
        placement_subject = "English"
    else:
        if (payload.level or "").strip():
            raise HTTPException(status_code=400, detail="new_student_with_test must not include level")
        selected_placement_subject = _normalize_subject_label(payload.placement_subject) or (provided_subjects[0] if provided_subjects else "English")
        subjects = []
        placement_required = True
        level_to_store = None
        placement_subject = selected_placement_subject

    subject_csv = ",".join(subjects) or placement_subject or "English"
    created = create_user_sync(
        payload.first_name.strip(),
        payload.last_name.strip(),
        payload.phone.strip(),
        subject_csv,
        login_type,
        owner_admin_id=int(admin_ref),
        parent_phone=payload.parent_phone,
    )

    _ensure_user_web_columns()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        UPDATE users
        SET placement_required=?,
            placement_subject=?,
            level=?,
            face_enrollment_required=1,
            face_profile_status='pending',
            face_id_status='not_started',
            face_id_enrolled=0,
            proctoring_required=1,
            review_wait_required=?,
            proctoring_block_reason=NULL,
            proctoring_hold_until=NULL,
            proctoring_blocked_until=NULL,
            family_discount_enabled=?,
            multi_group_discount_opt_in=?,
            referral_student_id=?,
            access_enabled=?,
            instagram_url=?,
            telegram_url=?,
            free_access=?,
            blocked=0
        WHERE id=?
        """,
        (
            1 if placement_required else 0,
            placement_subject,
            level_to_store,
            1 if placement_required else 0,
            1 if payload.family_discount_enabled else 0,
            1 if payload.multi_group_discount_opt_in else 0,
            int(payload.referral_student_id) if payload.referral_student_id is not None else None,
            0 if placement_required else 1,
            payload.instagram_url,
            payload.telegram_url,
            1 if getattr(payload, "free_access", False) else 0,
            int(created["id"]),
        ),
    )
    conn.commit()
    conn.close()
    update_user_subjects(int(created["id"]), subjects)
    referral_reward_applied = False
    referral_reward_dpoints: float | None = None
    referral_reward_message: str | None = None
    if payload.referral_student_id is not None and int(payload.referral_student_id) > 0:
        referral_bonus = float(_get_runtime_settings().get("referral_bonus_dpoints") or 100.0)
        _ensure_payment_automation_schema()
        inserted = False
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                INSERT INTO payment_referral_bonus_log(referred_user_id, referral_user_id, bonus_amount, status, created_by_admin_id, created_at, updated_at)
                VALUES (?, ?, ?, 'pending_first_payment', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                ON CONFLICT(referred_user_id) DO UPDATE SET
                    referral_user_id=excluded.referral_user_id,
                    bonus_amount=excluded.bonus_amount,
                    status='pending_first_payment',
                    updated_at=CURRENT_TIMESTAMP
                """,
                (
                    int(created["id"]),
                    int(payload.referral_student_id),
                    float(referral_bonus),
                    int(admin_ref),
                ),
            )
            conn.commit()
            inserted = True
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            cur.execute(
                "SELECT 1 FROM payment_referral_bonus_log WHERE referred_user_id=? LIMIT 1",
                (int(created["id"]),),
            )
            inserted = cur.fetchone() is not None
        conn.close()
        if inserted:
            referral_reward_applied = False
            referral_reward_dpoints = float(referral_bonus)
            referral_reward_message = "Referral bonus queued: first paymentdan keyin beriladi"
        else:
            referral_reward_applied = False
            referral_reward_dpoints = 0.0
            referral_reward_message = "Referral queue update failed"
    qr_generated = _generate_qr_login_token(int(created["id"]), WEB_QR_LOGIN_TTL_SECONDS)

    return AdminUserCreateResponse(
        id=int(created["id"]),
        full_name=f"{payload.first_name.strip()} {payload.last_name.strip()}",
        role=role,
        login_id=str(created["login_id"]),
        password=str(created["password"]),
        subjects=subjects,
        placement_test_required=placement_required,
        qr_token=str(qr_generated.get("qr_token") or ""),
        qr_payload=str(qr_generated.get("qr_payload") or ""),
        qr_expires_at=str(qr_generated.get("expires_at") or ""),
        referral_reward_applied=bool(referral_reward_applied),
        referral_reward_dpoints=referral_reward_dpoints,
        referral_reward_message=referral_reward_message,
    )


@app.get("/admin/groups")
async def admin_groups(
    subject: str | None = Query(default=None),
    teacher_name: str | None = Query(default=None),
    lesson_day: str | None = Query(default=None),
    group_query: str | None = Query(default=None),
    limit: int = Query(default=500, ge=1, le=2000),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_admin_perf_indexes()
    where_sql: list[str] = ["1=1"]
    params: list[Any] = []

    if _is_limited_admin(admin_ref) and not _is_main_admin(admin_ref):
        owner_scope, owner_params = _limited_admin_owner_scope_sql("g.owner_admin_id", int(admin_ref))
        where_sql.append(owner_scope)
        params.extend(owner_params)

    normalized_subject = _normalize_subject_label(subject)
    if normalized_subject:
        where_sql.append("LOWER(COALESCE(g.subject,''))=?")
        params.append(str(normalized_subject).lower())

    lesson_day_filter = str(lesson_day or "").strip().upper()
    if lesson_day_filter:
        where_sql.append("UPPER(COALESCE(g.lesson_date,''))=?")
        params.append(lesson_day_filter)

    group_query_filter = str(group_query or "").strip().lower()
    if group_query_filter:
        where_sql.append("LOWER(COALESCE(g.name,'')) LIKE ?")
        params.append(f"%{group_query_filter}%")

    teacher_filter = str(teacher_name or "").strip().lower()
    if teacher_filter:
        where_sql.append("LOWER(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) LIKE ?")
        params.append(f"%{teacher_filter}%")

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT COUNT(*) AS c
        FROM groups g
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(where_sql)}
        """,
        tuple(params),
    )
    total = int((cur.fetchone() or {}).get("c") or 0)
    cur.execute(
        f"""
        SELECT g.*
        FROM groups g
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(where_sql)}
        ORDER BY COALESCE(g.name,'') ASC, g.id DESC
        LIMIT ? OFFSET ?
        """,
        tuple([*params, int(limit), int(offset)]),
    )
    rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()
    return {"items": _serialize_group_rows_bulk(rows), "total": int(total), "limit": int(limit), "offset": int(offset)}


