@app.get("/admin/users/search")
async def admin_search_users(q: str = Query(default=""), authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_admin_perf_indexes()
    query = (q or "").strip().lower()
    where_sql: list[str] = ["u.login_type IN (1,2,6)"]
    params: list[Any] = []
    if query:
        where_sql.append(
            "LOWER(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'') || ' ' || COALESCE(u.phone,'') || ' ' || COALESCE(u.login_id,'')) LIKE ?"
        )
        params.append(f"%{query}%")
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT
            u.*,
            COALESCE(gc.group_count, 0) AS group_count
        FROM users u
        LEFT JOIN (
            SELECT ug.user_id, COUNT(DISTINCT ug.group_id) AS group_count
            FROM user_groups ug
            LEFT JOIN groups g ON g.id = ug.group_id
            WHERE (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT))='')
              AND (g.id IS NULL OR COALESCE(g.active,1)=1)
            GROUP BY ug.user_id
        ) gc ON gc.user_id = u.id
        WHERE {" AND ".join(where_sql)}
        ORDER BY COALESCE(u.created_at, CURRENT_TIMESTAMP) DESC, u.id DESC
        LIMIT 200
        """,
        tuple(params),
    )
    rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()
    return {"items": [_serialize_user_row_light(r) for r in rows]}


