@app.get("/admin/recipients/search")
async def admin_search_recipients(q: str = Query(default=""), authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    query = (q or "").strip().lower()
    users = _safe_call(get_all_users, []) or []
    groups = _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])

    def _match_user(row: dict) -> bool:
        if not query:
            return True
        return (
            query in _display_name(row).lower()
            or query in str(row.get("login_id") or "").lower()
            or query in str(row.get("telegram_id") or "").lower()
        )

    def _match_group(row: dict) -> bool:
        if not query:
            return True
        return query in str(row.get("name") or "").lower()

    return {
        "users": [_serialize_user_row(r) for r in users if _match_user(r)][:300],
        "groups": [_serialize_group_row(g) for g in groups if _match_group(g)][:120],
    }


@app.get("/admin/users/{user_id}")
async def admin_user_detail(user_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not str(target.get("profile_image_url") or "").strip():
        face_profile = _safe_call(lambda: get_active_face_profile(int(user_id)), None) or {}
        face_ref = str(face_profile.get("reference_image_url") or "").strip()
        if face_ref:
            target["effective_profile_image_url"] = face_ref
            target["face_reference_image_url"] = face_ref
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="You cannot manage this user")

    subject_balances = _safe_call(lambda: get_user_subject_dcoins(int(user_id)), {}) or {}
    teachers = _safe_call(lambda: get_student_teachers(int(user_id)), []) if int(target.get("login_type") or 0) in (1, 2) else []
    groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
    test_history = _safe_call(lambda: get_daily_test_attempt_history(int(user_id), limit=40), []) or []
    placement_results = [_serialize_placement_result(r) for r in (_safe_call(lambda: get_placement_results_for_user(int(user_id), limit=20), []) or [])]
    peer_admins = _safe_call(lambda: get_peer_admins_for_student_share(int(user_id)), []) or []
    teacher_permissions = {
        "can_upload_daily_tests": bool(_safe_call(lambda: get_daily_test_upload_permission(int(user_id)), False)),
        "can_generate_ai": bool(_safe_call(lambda: get_teacher_ai_generation_permission(int(user_id)), False)),
        "can_upload_books": bool(_safe_call(lambda: get_book_upload_permission(int(user_id)), False)),
        "can_upload_videos": bool(_safe_call(lambda: get_video_upload_permission(int(user_id)), False)),
        "can_manage_video_tests": bool(_safe_call(lambda: get_content_test_manage_permission(int(user_id), "video"), False)),
        "can_manage_book_tests": bool(_safe_call(lambda: get_content_test_manage_permission(int(user_id), "book"), False)),
        "can_create_articles": True,
    }
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT can_create FROM web_article_permissions WHERE user_id=? LIMIT 1", (int(user_id),))
    perm_row = cur.fetchone()
    conn.close()
    if perm_row is not None:
        teacher_permissions["can_create_articles"] = bool(int(perm_row.get("can_create") or 0))

    admin_options = [
        {
            "admin_id": int(aid),
            "is_main": _is_main_admin(int(aid)),
            "is_limited": _is_limited_admin(int(aid)),
            "label": f"Admin {int(aid)}",
        }
        for aid in _ordered_admin_ids()
    ]
    recommended_peer_admin_id: int | None = None
    if _is_limited_admin(admin_ref):
        peers = [int(a) for a in LIMITED_ADMIN_CHAT_IDS if int(a) != int(admin_ref)]
        if peers:
            recommended_peer_admin_id = peers[0]
    return {
        "user": _serialize_user_row(target),
        "groups": [_serialize_group_row(g) for g in groups],
        "subject_levels": _student_subject_levels_from_groups(int(user_id)),
        "teachers": [_serialize_user_row(t) for t in teachers],
        "daily_test_history": test_history,
        "placement_results": [r for r in placement_results if r],
        "dcoin_by_subject": subject_balances,
        "dcoin_total": float(sum(float(v) for v in subject_balances.values())),
        "subject_count": max(1, len(_safe_call(lambda: get_user_subjects(int(user_id)), []) or [])),
        "peer_admins": [int(x) for x in peer_admins],
        "admin_options": admin_options,
        "recommended_peer_admin_id": recommended_peer_admin_id,
        "teacher_permissions": teacher_permissions,
    }


def _parse_price_text_value(raw_value: str | None) -> float:
    raw = str(raw_value or "").strip()
    if not raw:
        return 0.0
    cleaned = re.sub(r"[^0-9.,]", "", raw)
    if not cleaned:
        return 0.0
    if "," in cleaned and "." not in cleaned:
        comma_parts = cleaned.split(",")
        # 500,000 or 1,250,000 -> thousand separators
        if len(comma_parts) >= 2 and all(part.isdigit() for part in comma_parts) and all(len(part) == 3 for part in comma_parts[1:]):
            cleaned = "".join(comma_parts)
        else:
            # decimal comma fallback
            cleaned = cleaned.replace(",", ".")
    elif "." in cleaned and "," not in cleaned:
        dot_parts = cleaned.split(".")
        # 500.000 or 1.250.000 -> thousand separators
        if len(dot_parts) >= 2 and all(part.isdigit() for part in dot_parts) and all(len(part) == 3 for part in dot_parts[1:]):
            cleaned = "".join(dot_parts)
    elif "," in cleaned and "." in cleaned:
        # 1,250.50 => remove commas as thousand separators
        cleaned = cleaned.replace(",", "")
    try:
        return max(0.0, float(cleaned))
    except Exception:
        return 0.0


def _month_start_end(ym: str) -> tuple[datetime, datetime]:
    start = datetime.strptime(f"{ym}-01", "%Y-%m-%d")
    if start.month == 12:
        next_month = datetime(start.year + 1, 1, 1)
    else:
        next_month = datetime(start.year, start.month + 1, 1)
    end = next_month - timedelta(days=1)
    return start, end


def _group_month_lesson_count(group_row: dict, ym: str) -> int:
    month_start, month_end = _month_start_end(ym)
    lesson_date = str(group_row.get("lesson_date") or "").strip().upper()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", lesson_date):
        try:
            one_day = datetime.strptime(lesson_date, "%Y-%m-%d")
            return 1 if month_start.date() <= one_day.date() <= month_end.date() else 0
        except Exception:
            return 0
    weekdays = [0, 2, 4] if lesson_date == "MWF" else [1, 3, 5] if lesson_date == "TTS" else []
    if not weekdays:
        return 0
    current = month_start
    count = 0
    while current <= month_end:
        if int(current.weekday()) in weekdays:
            count += 1
        current += timedelta(days=1)
    return max(0, count)


def _attendance_excused_lesson_dates(user_id: int, group_id: int, lesson_dates: list[str]) -> set[str]:
    days = [str(day or "").strip() for day in (lesson_dates or []) if re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(day or "").strip())]
    if not days:
        return set()
    conn = get_conn()
    cur = conn.cursor()
    try:
        placeholders = ", ".join(["?"] * len(days))
        cur.execute(
            f"""
            SELECT date, status
            FROM attendance
            WHERE user_id=?
              AND group_id=?
              AND date IN ({placeholders})
            """,
            (int(user_id), int(group_id), *days),
        )
        return {
            str(row.get("date") or "").strip()
            for row in (cur.fetchall() or [])
            if is_excused_attendance(str(row.get("status") or ""))
        }
    finally:
        conn.close()


def _attendance_sababli_count(user_id: int, group_id: int, ym: str) -> int:
    group = _safe_call(lambda: get_group(int(group_id)), None) or {}
    lesson_dates = _payment_lesson_dates_for_group_month(group, ym) if group else []
    active_dates = _payment_active_lesson_dates(int(user_id), int(group_id), ym, lesson_dates)
    return len(_attendance_excused_lesson_dates(int(user_id), int(group_id), active_dates))


def _membership_active_ratio(user_id: int, group_id: int, ym: str) -> float:
    month_start, month_end = _month_start_end(ym)
    periods = list_user_group_membership_periods(int(user_id), int(group_id)) or []
    if not periods:
        return 1.0
    active_days = 0
    total_days = (month_end.date() - month_start.date()).days + 1
    for period in periods:
        joined_raw = str(period.get("joined_date") or period.get("joined_at") or "").strip()
        left_raw = str(period.get("left_date") or period.get("left_at") or "").strip()
        try:
            joined_at = datetime.fromisoformat(joined_raw.replace("Z", "+00:00")) if joined_raw else month_start
        except Exception:
            joined_at = month_start
        if left_raw:
            try:
                left_at = datetime.fromisoformat(left_raw.replace("Z", "+00:00"))
            except Exception:
                left_at = month_end
        else:
            left_at = month_end
        start_day = max(month_start.date(), joined_at.date())
        end_day = min(month_end.date(), left_at.date())
        if end_day < start_day:
            continue
        active_days += (end_day - start_day).days + 1
    if active_days <= 0:
        return 0.0
    return min(1.0, max(0.0, float(active_days) / float(max(1, total_days))))


def _student_has_multi_subject_single_group(user_id: int) -> bool:
    groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
    for group in groups:
        gid = int(group.get("id") or 0)
        if gid <= 0:
            continue
        primary_subject = _normalize_subject_label(str(group.get("subject") or "").strip()) or ""
        extra_subjects = _safe_call(lambda group_id=gid: get_group_extra_subjects(group_id), []) or []
        normalized_extras: list[str] = []
        for raw_subject in extra_subjects:
            normalized = _normalize_subject_label(str(raw_subject or "").strip()) or ""
            if not normalized or normalized == primary_subject or normalized in normalized_extras:
                continue
            normalized_extras.append(normalized)
        subject_count = (1 if primary_subject else 0) + len(normalized_extras)
        if subject_count > 1:
            return True
    return False


def _resolve_family_anchor_for_student(student_row: dict) -> int:
    student_id = int(student_row.get("id") or 0)
    if student_id <= 0:
        return 0
    direct_anchor = int(student_row.get("family_anchor_student_id") or 0)
    conn = get_conn()
    cur = conn.cursor()
    try:
        if direct_anchor > 0:
            cur.execute(
                "SELECT 1 FROM users WHERE id=? AND login_type IN (1,2) LIMIT 1",
                (direct_anchor,),
            )
            if cur.fetchone():
                return int(direct_anchor)
            return 0
        cur.execute(
            """
            SELECT 1
            FROM users
            WHERE family_anchor_student_id=?
              AND login_type IN (1,2)
            LIMIT 1
            """,
            (student_id,),
        )
        if cur.fetchone():
            return int(student_id)
        return 0
    except Exception:
        return 0
    finally:
        conn.close()


def _resolve_student_discount_info(student_row: dict) -> dict:
    resolved = _payment_discount_info_for_student(student_row)
    return {
        "discount_type": str(resolved.get("discount_type") or "none"),
        "discount_percent": float(resolved.get("discount_percent") or 0.0),
        "discount_percentage": float(resolved.get("discount_percentage") or resolved.get("discount_percent") or 0.0),
        "discount_reason": str(resolved.get("discount_reason") or "no_eligible_discount"),
        "family_group_id": (int(resolved.get("family_group_id")) if resolved.get("family_group_id") is not None else None),
        "student_active_group_count": int(resolved.get("student_active_group_count") or 0),
        "family_valid": bool(resolved.get("family_valid")),
        "multi_group_valid": bool(resolved.get("multi_group_valid")),
        "multi_group_blocked_by_single_group_multi_subject": False,
    }


def _calculate_monthly_payment_for_student_group(
    user_id: int,
    group_id: int,
    ym: str,
    *,
    student_row: dict | None = None,
    group_row: dict | None = None,
    lesson_dates: list[date] | None = None,
    teacher_row: dict | None = None,
    discount_info: dict[str, Any] | None = None,
    skip_sababli: bool = False,
) -> dict:
    student = student_row or (_safe_call(lambda: get_user_by_id(int(user_id)), None) or {})
    group = group_row or (_safe_call(lambda: get_group(int(group_id)), None) or {})
    if not student or not group:
        return {
            "user_id": int(user_id),
            "group_id": int(group_id),
            "ym": ym,
            "course_price": 0.0,
            "active_ratio": 0.0,
            "planned_lessons": 0,
            "membership_lessons": 0,
            "chargeable_lessons": 0,
            "sababli_lessons": 0,
            "excused_lessons": 0,
            "course_title": None,
            "course_price_source": "none",
            "original_price": 0.0,
            "discount_type": "none",
            "discount_percent": 0.0,
            "discount_amount": 0.0,
            "final_payable_amount": 0.0,
            "calculated_amount": 0.0,
            "calculated_group_amount": 0.0,
        }
    linked_course = None
    course_id = int(group.get("course_id") or 0)
    if course_id > 0:
        linked_course = _safe_call(lambda: _get_course_by_id(course_id), None)
    linked_course_price = str((linked_course or {}).get("price_text") or "").strip()
    linked_course_individual_price = str((linked_course or {}).get("individual_price_text") or "").strip()
    
    pricing_type = str(group.get("pricing_type") or "group").strip().lower()
    if pricing_type == "individual" and linked_course_individual_price:
        course_price_value = linked_course_individual_price
    else:
        course_price_value = linked_course_price

    legacy_group_price = str(group.get("monthly_fee_text") or "").strip()
    raw_price = course_price_value or legacy_group_price
    course_price_source = "course" if course_price_value else ("legacy_group_fee" if legacy_group_price else "none")
    course_price = _parse_price_text_value(raw_price)
    effective_lesson_dates = lesson_dates if lesson_dates is not None else _payment_lesson_dates_for_group_month(group, ym)
    planned_lessons = len(effective_lesson_dates)
    active_lesson_dates = _payment_active_lesson_dates(int(user_id), int(group_id), ym, effective_lesson_dates)
    membership_lessons = len(active_lesson_dates)
    excused_dates = set() if bool(skip_sababli) else _attendance_excused_lesson_dates(int(user_id), int(group_id), active_lesson_dates)
    sababli_lessons = min(membership_lessons, len(excused_dates))
    chargeable_lessons = max(0, membership_lessons - sababli_lessons)
    active_ratio = float(chargeable_lessons) / float(max(1, planned_lessons)) if planned_lessons > 0 else 0.0
    standard_divisor = 12.0
    lesson_value = course_price / standard_divisor
    effective_chargeable = min(chargeable_lessons, int(standard_divisor))
    base_active_amount = lesson_value * float(effective_chargeable)
    # Part-2 model: group amount is lesson-count based only (no extra deductions here).
    discounted_before = max(0.0, base_active_amount)
    resolved_discount_info = discount_info or _payment_discount_info_for_student(student, ym=ym)
    discount_percent = float(resolved_discount_info.get("discount_percent") or 0.0)
    discount_amount = max(0.0, discounted_before * (discount_percent / 100.0))
    before_round_amount = max(0.0, discounted_before - discount_amount)
    final_amount = _round_payment_amount(before_round_amount, discount_percent > 0)
    rounding_delta = final_amount - before_round_amount
    teacher = teacher_row if teacher_row is not None else (_safe_call(lambda: get_user_by_id(int(group.get("teacher_id") or 0)), None) or {})
    subject_name = _normalize_subject_label(str(group.get("subject") or "").strip()) or str(group.get("subject") or "").strip() or None
    return {
        "user_id": int(user_id),
        "group_id": int(group_id),
        "group_name": str(group.get("name") or "").strip() or f"Group #{int(group_id)}",
        "ym": ym,
        "month": int(str(ym).split("-")[1]) if re.fullmatch(r"\d{4}-\d{2}", str(ym)) else None,
        "year": int(str(ym).split("-")[0]) if re.fullmatch(r"\d{4}-\d{2}", str(ym)) else None,
        "course_id": int(course_id) if course_id > 0 else None,
        "course_title": str((linked_course or {}).get("title") or group.get("course_title") or "").strip() or None,
        "course_name": str((linked_course or {}).get("title") or group.get("course_title") or "").strip() or None,
        "course_price_source": course_price_source,
        "original_price": round(course_price, 2),
        "course_price": round(course_price, 2),
        "course_monthly_price": round(course_price, 2),
        "subject_name": subject_name,
        "teacher_name": _display_name(teacher) if teacher else None,
        "active_ratio": round(active_ratio, 6),
        "planned_lessons": int(planned_lessons),
        "total_lesson_count_in_month": int(planned_lessons),
        "active_lessons": int(chargeable_lessons),
        "student_active_lesson_count": int(chargeable_lessons),
        "membership_lessons": int(membership_lessons),
        "chargeable_lessons": int(chargeable_lessons),
        "sababli_lessons": int(sababli_lessons),
        "excused_lessons": int(sababli_lessons),
        "price_per_lesson": round(float(lesson_value), 6),
        "discount_type": str(resolved_discount_info.get("discount_type") or "none"),
        "discount_percent": float(discount_percent),
        "discount_percentage": float(discount_percent),
        "discount_amount": round(discount_amount, 2),
        "discount_reason": str(resolved_discount_info.get("discount_reason") or "no_eligible_discount"),
        "applied_discount_source": str(resolved_discount_info.get("discount_type") or "none"),
        "applied_discount_label": str(resolved_discount_info.get("discount_type") or "none").replace("_", " ").title(),
        "gift_payment_discount_id": int(resolved_discount_info.get("gift_payment_discount_id") or 0),
        "gift_purchase_history_id": int(resolved_discount_info.get("gift_purchase_history_id") or 0) if resolved_discount_info.get("gift_purchase_history_id") is not None else None,
        "family_group_id": (int(resolved_discount_info.get("family_group_id")) if resolved_discount_info.get("family_group_id") is not None else None),
        "student_active_group_count": int(resolved_discount_info.get("student_active_group_count") or 0),
        "final_payable_amount": round(final_amount, 2),
        "base_amount_before_discount": round(discounted_before, 2),
        "final_amount_after_discount": round(final_amount, 2),
        "rounding_delta": round(rounding_delta, 2),
        "family_discount_valid": bool(resolved_discount_info.get("family_valid")),
        "multi_group_discount_valid": bool(resolved_discount_info.get("multi_group_valid")),
        "multi_group_discount_blocked_by_single_group_multi_subject": False,
        "calculated_amount": round(final_amount, 2),
        "calculated_group_amount": round(discounted_before, 2),
    }


def _calculate_monthly_payment_summary_for_student(user_id: int, ym: str, admin_ref: int, selected_group_id: int | None = None) -> dict:
    groups = _payment_get_user_groups_with_history(int(user_id), ym)
    allowed_groups = [g for g in groups if _can_manage_group(int(admin_ref), g)]
    if selected_group_id is not None and int(selected_group_id) > 0:
        selected_gid = int(selected_group_id)
        if selected_gid not in {int(g.get("id") or 0) for g in allowed_groups}:
            raise HTTPException(status_code=403, detail="Permission denied")
    items = [
        _calculate_monthly_payment_for_student_group(int(user_id), int(g.get("id") or 0), ym)
        for g in allowed_groups
        if int(g.get("id") or 0) > 0
    ]
    original_total = round(sum(float(item.get("calculated_group_amount") or 0.0) for item in items), 2)
    student_row = _safe_call(lambda: get_user_by_id(int(user_id)), None) or {}
    discount_info = _payment_discount_info_for_student(student_row, ym=ym)
    discount_type = str(discount_info.get("discount_type") or "none")
    discount_percent = float(discount_info.get("discount_percent") or 0.0)
    discount_amount_total = round(max(0.0, float(original_total) * (discount_percent / 100.0)), 2)
    before_round_total = round(max(0.0, float(original_total) - float(discount_amount_total)), 2)
    final_total = _round_payment_amount(before_round_total, discount_percent > 0)
    # Keep per-group discount fields aligned with current consumers while discount is student-level.
    if original_total > 0:
        for item in items:
            group_amount = float(item.get("calculated_group_amount") or 0.0)
            share = group_amount / original_total if original_total > 0 else 0.0
            group_discount = round(discount_amount_total * share, 2)
            item["discount_type"] = discount_type
            item["discount_percent"] = discount_percent
            item["discount_amount"] = group_discount
            item_before_round = max(0.0, group_amount - group_discount)
            item["final_payable_amount"] = round(_round_payment_amount(item_before_round, discount_percent > 0), 2)
            item["base_amount_before_discount"] = round(group_amount, 2)
            item["final_amount_after_discount"] = item["final_payable_amount"]
            item["rounding_delta"] = round(float(item["final_payable_amount"]) - item_before_round, 2)
            item["calculated_amount"] = item["final_payable_amount"]
        final_total = round(sum(float(item.get("final_payable_amount") or 0.0) for item in items), 2)
    if discount_type == "none":
        for item in items:
            group_amount = float(item.get("calculated_group_amount") or 0.0)
            item["discount_type"] = "none"
            item["discount_percent"] = 0.0
            item["discount_amount"] = 0.0
            item["final_payable_amount"] = round(_round_up_to_nearest_1000_uzs(group_amount), 2)
            item["base_amount_before_discount"] = round(group_amount, 2)
            item["final_amount_after_discount"] = item["final_payable_amount"]
            item["rounding_delta"] = round(float(item["final_payable_amount"]) - group_amount, 2)
            item["calculated_amount"] = item["final_payable_amount"]
        final_total = round(sum(float(item.get("final_payable_amount") or 0.0) for item in items), 2)
        discount_amount_total = 0.0
    selected_item = None
    if selected_group_id is not None and int(selected_group_id) > 0:
        selected_item = next((item for item in items if int(item.get("group_id") or 0) == int(selected_group_id)), None)
    return {
        "user_id": int(user_id),
        "student": _serialize_user_row(student_row) if student_row else {"id": int(user_id)},
        "ym": ym,
        "month": int(str(ym).split("-")[1]) if re.fullmatch(r"\d{4}-\d{2}", str(ym)) else None,
        "year": int(str(ym).split("-")[0]) if re.fullmatch(r"\d{4}-\d{2}", str(ym)) else None,
        "selected_group_id": int(selected_group_id) if selected_group_id is not None and int(selected_group_id) > 0 else None,
        "items": items,
        "original_total_amount": round(original_total, 2),
        "discount_type": discount_type,
        "discount_percent": float(discount_percent),
        "discount_percentage": float(discount_percent),
        "discount_amount": round(discount_amount_total, 2),
        "discount_reason": str(discount_info.get("discount_reason") or "no_eligible_discount"),
        "family_group_id": (int(discount_info.get("family_group_id")) if discount_info.get("family_group_id") is not None else None),
        "student_active_group_count": int(discount_info.get("student_active_group_count") or 0),
        "final_payable_amount": round(final_total, 2),
        "total_payable_amount": round(final_total, 2),
        "group_count": len(items),
        # Backward-compatible top-level fields for older consumers.
        "course_price": float((selected_item or items[0]).get("course_price") or 0.0) if items else 0.0,
        "active_ratio": float((selected_item or items[0]).get("active_ratio") or 0.0) if items else 0.0,
        "planned_lessons": int((selected_item or items[0]).get("planned_lessons") or 0) if items else 0,
        "sababli_lessons": int((selected_item or items[0]).get("sababli_lessons") or 0) if items else 0,
        "calculated_amount": float((selected_item or items[0]).get("calculated_amount") or 0.0) if items else 0.0,
    }


