        "ALTER TABLE family_groups ADD COLUMN IF NOT EXISTS created_by_admin_id BIGINT",
        "ALTER TABLE family_groups ADD COLUMN IF NOT EXISTS updated_by_admin_id BIGINT",
        "ALTER TABLE family_groups ADD COLUMN IF NOT EXISTS created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP",
