def _payment_store_confirmation_notification(
    cur,
    *,
    user_id: int,
    payment_transaction_id: int,
    ym: str,
    amount: float,
    status: str,
    remaining: float,
    overpayment: float,
    payment_method: str,
    note: str | None,
    group_name: str | None,
    course_title: str | None,
    bonus_events: list[dict[str, Any]] | None = None,
) -> int:
    method = str(payment_method or "").strip().lower() or "cash"
    method_label = "Naqd" if method == "cash" else "Plastik karta" if method == "card" else method
    message = (
        f"To'lov qabul qilindi ({str(ym)}). "
        f"Holat: {str(status)}. "
        f"Usul: {method_label}."
    )
    message = f"{message} Sana: {_now_tashkent_date()}."
    if group_name:
        message = f"{message} Guruh: {str(group_name).strip()}."
    if course_title:
        message = f"{message} Kurs: {str(course_title).strip()}."
    if note:
        message = f"{message} Izoh: {str(note).strip()}."
    applied_bonus = [
        event
        for event in (bonus_events or [])
        if bool(event.get("applied")) and float(event.get("amount") or 0.0) > 0
    ]
    if applied_bonus:
        bonus_text = ", ".join([f"{float(event.get('amount') or 0.0):.1f} ({str(event.get('bonus_type') or '-')})" for event in applied_bonus[:4]])
        message = f"{message} D'point bonus: {bonus_text}."
    return _payment_upsert_web_notification(
        cur,
        user_id=int(user_id),
        payment_transaction_id=int(payment_transaction_id),
        notification_type="payment_confirmation",
        title="To'lov qabul qilindi",
        message=message,
        source_key=f"payment_confirmation:{int(payment_transaction_id)}",
        meta={
            "ym": str(ym),
            "status": str(status),
            "remaining": float(remaining),
            "overpayment": float(overpayment),
            "bonus_events": bonus_events or [],
        },
    )


def _payment_store_refund_notification(
    cur,
    *,
    user_id: int,
    payment_refund_id: int,
    transaction_id: int,
    ym: str,
    amount: float,
    status: str,
    debt: float,
    overpayment: float,
    note: str,
    reversed_full_bonus: float = 0.0,
    reversed_advance_bonus: float = 0.0,
) -> int:
    message = (
        f"Refund bajarildi: {float(amount):.2f} ({str(ym)}). "
        f"Yangi holat: {str(status)}. "
        f"Qoldiq: {float(debt):.2f}. "
        f"Ortiqcha: {float(overpayment):.2f}."
    )
    message = f"{message} Sana: {_now_tashkent_date()}."
    if reversed_full_bonus > 1e-9:
        message = f"{message} Qaytarilgan full payment bonusi: {float(reversed_full_bonus):.1f} D'point."
    if reversed_advance_bonus > 1e-9:
        message = f"{message} Qaytarilgan advance bonusi: {float(reversed_advance_bonus):.1f} D'point."
    if note:
        message = f"{message} Izoh: {str(note).strip()}."
    return _payment_upsert_web_notification(
        cur,
        user_id=int(user_id),
        payment_refund_id=int(payment_refund_id),
        notification_type="payment_refund",
        title="To'lov refund qilindi",
        message=message,
        source_key=f"payment_refund:{int(payment_refund_id)}",
        meta={
            "ym": str(ym),
            "status": str(status),
            "debt": float(debt),
            "overpayment": float(overpayment),
            "transaction_id": int(transaction_id),
            "reversed_full_bonus": float(reversed_full_bonus),
            "reversed_advance_bonus": float(reversed_advance_bonus),
        },
    )


