def _payment_reminder_job_already_done(trigger_source: str, day_iso: str) -> bool:
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT 1
        FROM payment_job_runs
        WHERE job_name='payment_reminders_schedule'
          AND trigger_source=?
          AND ym=?
          AND status='success'
        LIMIT 1
        """,
        (str(trigger_source), str(day_iso)),
    )
    row = cur.fetchone()
    conn.close()
    return row is not None


def _payment_log_reminder_dispatch(
    *,
    user_id: int,
    ym: str,
    trigger_source: str,
    channel: str,
    status: str,
    dispatch_day: str,
    reminder_type: str = "payment_reminder",
    reason: str | None = None,
    message_text: str | None = None,
    telegram_chat_id: str | None = None,
    notification_id: int | None = None,
) -> bool:
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, status
        FROM payment_reminder_dispatch_log
        WHERE user_id=?
          AND dispatch_day=?
          AND channel=?
          AND trigger_source=?
          AND reminder_type=?
        LIMIT 1
        """,
        (
            int(user_id),
            str(dispatch_day),
            str(channel),
            str(trigger_source),
            str(reminder_type or "payment_reminder"),
        ),
    )
    existing = dict(cur.fetchone() or {})
    existing_status = str(existing.get("status") or "").strip().lower()
    if existing and existing_status == "sent":
        conn.close()
        return False
    cur.execute(
        """
        INSERT INTO payment_reminder_dispatch_log
        (
            user_id, ym, trigger_source, reminder_type, channel, status, reason,
            message_text, dispatch_day, telegram_chat_id, notification_id, created_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(user_id, dispatch_day, channel, trigger_source, reminder_type)
        DO UPDATE SET
            status=excluded.status,
            reason=excluded.reason,
            message_text=excluded.message_text,
            telegram_chat_id=COALESCE(excluded.telegram_chat_id, payment_reminder_dispatch_log.telegram_chat_id),
            notification_id=COALESCE(excluded.notification_id, payment_reminder_dispatch_log.notification_id)
        """,
        (
            int(user_id),
            str(ym),
            str(trigger_source),
            str(reminder_type or "payment_reminder"),
            str(channel),
            str(status),
            (str(reason or "")[:500] or None),
            (str(message_text or "")[:2000] or None),
            str(dispatch_day),
            (str(telegram_chat_id or "").strip() or None),
            (int(notification_id) if notification_id and int(notification_id) > 0 else None),
        ),
    )
    conn.commit()
    conn.close()
    return True


def _payment_reminder_dispatch_sent(
    *,
    user_id: int,
    trigger_source: str,
    channel: str,
    dispatch_day: str,
    reminder_type: str = "payment_reminder",
) -> bool:
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT 1
        FROM payment_reminder_dispatch_log
        WHERE user_id=?
          AND dispatch_day=?
          AND channel=?
          AND trigger_source=?
          AND reminder_type=?
          AND status='sent'
        LIMIT 1
        """,
        (
            int(user_id),
            str(dispatch_day),
            str(channel),
            str(trigger_source),
            str(reminder_type or "payment_reminder"),
        ),
    )
    exists = cur.fetchone() is not None
    conn.close()
    return bool(exists)


def _payment_reminder_triggers_for_today() -> list[str]:
    today = _now_tashkent()
    day = int(today.day)
    triggers: list[str] = []
    if day in {5, 10, 15, 20, 25}:
        triggers.append(f"monthly_day_{day}")
    triggers.append("overdue_daily")
    return triggers


def _payment_skip_reason_for_reminder(
    *,
    trigger_source: str,
    status: str,
    debt_amount: float,
    overpayment_amount: float,
    overdue_items: list[dict[str, Any]] | None = None,
) -> str | None:
    if str(trigger_source) == "overdue_daily":
        if not (overdue_items or []):
            return "no_overdue_items"
        return None
    debt_value = max(0.0, float(debt_amount or 0.0))
    if debt_value > 1e-9:
        return None
    normalized_status = str(status or "").strip()
    overpayment_value = max(0.0, float(overpayment_amount or 0.0))
    if normalized_status == PAYMENT_STATUS_OVERPAY:
        return "overpaid"
    if overpayment_value > 1e-9:
        return "covered_by_overpayment"
    if normalized_status == PAYMENT_STATUS_PAID:
        return "fully_paid"
    return "no_debt"


async def _payment_send_reminders_for_trigger(trigger_source: str) -> dict[str, Any]:
    _ensure_payment_automation_schema()
    current_ym = _payment_ym_now()
    dispatch_day = _now_tashkent_date()
    conn = get_conn()
    cur = conn.cursor()
    if str(trigger_source) == "overdue_daily":
        cur.execute(
            """
            SELECT DISTINCT user_id
            FROM payment_monthly_obligations
            WHERE COALESCE(debt_amount, 0) > 0
              AND COALESCE(overdue, 0)=1
              AND COALESCE(is_accountless, 0)=0
            """
        )
    else:
        cur.execute(
            """
            SELECT DISTINCT user_id
            FROM payment_monthly_obligations
            WHERE ym=?
              AND COALESCE(is_accountless, 0)=0
            """,
            (current_ym,),
        )
    target_ids = [int((row or {}).get("user_id") or 0) for row in (cur.fetchall() or [])]
    conn.close()
    if not target_ids:
        return {"sent": 0, "failed": 0, "skipped": 0}
    cards = _payment_cards_public_payload()
    default_card = next((card for card in cards if bool(card.get("is_default"))), cards[0] if cards else None)
    card_line = ""
    if default_card:
        owner = f"{str(default_card.get('owner_first_name') or '').strip()} {str(default_card.get('owner_last_name') or '').strip()}".strip()
        number = str(default_card.get("card_number_masked") or "").strip()
        if owner and number:
            card_line = f"Karta: {owner} — {number}"
        elif number:
            card_line = f"Karta: {number}"
    sent = 0
    failed = 0
    skipped = 0
    for uid in target_ids:
        if uid <= 0:
            continue
        user = _safe_call(lambda user_id=uid: get_user_by_id(user_id), None)
        if not user:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=current_ym,
                trigger_source=str(trigger_source),
                channel="website",
                status="skipped",
                reason="user_not_found",
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        if int(user.get("login_type") or 0) not in (1, 2):
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=current_ym,
                trigger_source=str(trigger_source),
                channel="website",
                status="skipped",
                reason="not_student_account",
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        active_groups = _safe_call(lambda user_id=uid: get_user_groups(int(user_id)), []) or []
        if not active_groups:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=current_ym,
                trigger_source=str(trigger_source),
                channel="website",
                status="skipped",
                reason="no_active_group",
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        tg = str(user.get("telegram_id") or "").strip()
        overview = _payment_student_overview(user, ym=current_ym, months_back=4)
        current = overview.get("current_month") or {}
        current_status = str(current.get("status") or PAYMENT_STATUS_UNPAID)
        current_debt = float(current.get("total_debt_amount") or 0.0)
        current_overpayment = float(current.get("total_overpayment_amount") or 0.0)
        overdue_items = [
            month
            for month in (overview.get("months") or [])
            if str(month.get("status") or "") == PAYMENT_STATUS_OVERDUE and float(month.get("total_debt_amount") or 0.0) > 0
        ]
        skip_reason = _payment_skip_reason_for_reminder(
            trigger_source=str(trigger_source),
            status=current_status,
            debt_amount=float(current_debt),
            overpayment_amount=float(current_overpayment),
            overdue_items=overdue_items,
        )
        if skip_reason:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=current_ym,
                trigger_source=str(trigger_source),
                channel="website",
                status="skipped",
                reason=str(skip_reason),
                dispatch_day=dispatch_day,
            )
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=current_ym,
                trigger_source=str(trigger_source),
                channel="telegram",
                status="skipped",
                reason=str(skip_reason),
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        group_names = ", ".join(
            sorted(
                {
                    str(item.get("group_name") or "").strip()
                    for item in (current.get("items") or [])
                    if str(item.get("group_name") or "").strip()
                }
            )
        )
        course_names = ", ".join(
            sorted(
                {
                    str(item.get("course_title") or "").strip()
                    for item in (current.get("items") or [])
                    if str(item.get("course_title") or "").strip()
                }
            )
        )
        first_group = group_names or "-"
        first_course = course_names or "-"
        user_lang = str(user.get("language") or "uz")
        text = _format_payment_reminder_text(
            lang=user_lang,
            student_name=_display_name(user),
            ym=current_ym,
            status=current_status,
            debt_amount=float(current_debt),
            groups_text=first_group,
            courses_text=first_course,
            card_line=card_line,
            overdue_items=overdue_items,
        )
        reminder_ym = current_ym
        if str(trigger_source) == "overdue_daily" and overdue_items:
            reminder_ym = str(overdue_items[0].get("ym") or current_ym)
        student_payments_url = f"{WEBAPP_URL}/?role=student&section=payments" if WEBAPP_URL else None

        web_notification_id = 0
        website_already_sent = _payment_reminder_dispatch_sent(
            user_id=int(uid),
            trigger_source=str(trigger_source),
            channel="website",
            dispatch_day=dispatch_day,
        )
        if not website_already_sent:
            conn_w = get_conn()
            cur_w = conn_w.cursor()
            try:
                web_notification_id = int(
                    _payment_upsert_web_notification(
                        cur_w,
                        user_id=int(uid),
                        notification_type="payment_reminder",
                        title=_payment_reminder_web_title(user_lang),
                        message=text,
                        button_text=_payment_reminder_web_button(user_lang),
                        button_url="/?role=student&section=payments",
                        target_screen="payments",
                        source_key=f"payment_reminder:{dispatch_day}:{trigger_source}:{int(uid)}",
                        meta={
                            "ym": reminder_ym,
                            "status": current_status,
                            "debt_amount": float(current_debt),
                            "trigger_source": str(trigger_source),
                        },
                    )
                    or 0
                )
                conn_w.commit()
                _payment_log_reminder_dispatch(
                    user_id=int(uid),
                    ym=reminder_ym,
                    trigger_source=str(trigger_source),
                    channel="website",
                    status="sent",
                    reason="ok",
                    message_text=text,
                    dispatch_day=dispatch_day,
                    notification_id=(web_notification_id if web_notification_id > 0 else None),
                )
                sent += 1
            except Exception as exc:
                try:
                    conn_w.rollback()
                except Exception:
                    pass
                failed += 1
                _payment_log_reminder_dispatch(
                    user_id=int(uid),
                    ym=reminder_ym,
                    trigger_source=str(trigger_source),
                    channel="website",
                    status="failed",
                    reason=str(exc)[:240],
                    message_text=text,
                    dispatch_day=dispatch_day,
                    notification_id=(web_notification_id if web_notification_id > 0 else None),
                )
            finally:
                conn_w.close()
        else:
            skipped += 1

        if not tg:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=reminder_ym,
                trigger_source=str(trigger_source),
                channel="telegram",
                status="skipped",
                reason="telegram_id_missing",
                message_text=text,
                dispatch_day=dispatch_day,
            )
            continue
        telegram_already_sent = _payment_reminder_dispatch_sent(
            user_id=int(uid),
            trigger_source=str(trigger_source),
            channel="telegram",
            dispatch_day=dispatch_day,
        )
        if telegram_already_sent:
            skipped += 1
            continue
        token = _tg_token_for_login_type(int(user.get("login_type") or 0))
        ok = await _send_telegram_text(
            token,
            tg,
            text,
        )
        if ok:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=reminder_ym,
                trigger_source=str(trigger_source),
                channel="telegram",
                status="sent",
                reason="ok",
                message_text=text,
                dispatch_day=dispatch_day,
                telegram_chat_id=tg,
                notification_id=(web_notification_id if web_notification_id > 0 else None),
            )
            sent += 1
        else:
            failed += 1
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=reminder_ym,
                trigger_source=str(trigger_source),
                channel="telegram",
                status="failed",
                reason="telegram_send_failed",
                message_text=text,
                dispatch_day=dispatch_day,
                telegram_chat_id=tg,
                notification_id=(web_notification_id if web_notification_id > 0 else None),
            )
    return {"sent": sent, "failed": failed, "skipped": skipped}


async def _payment_run_scheduled_reminders() -> None:
    today_iso = _now_tashkent_date()
    for trigger_source in _payment_reminder_triggers_for_today():
        if _payment_reminder_job_already_done(trigger_source, today_iso):
            continue
        run_id = _payment_log_job("payment_reminders_schedule", trigger_source, today_iso, "running", message="started")
        try:
            result = await _payment_send_reminders_for_trigger(trigger_source)
            _payment_log_job(
                "payment_reminders_schedule",
                trigger_source,
                today_iso,
                "success",
                message=(
                    f"sent={int(result.get('sent') or 0)} "
                    f"failed={int(result.get('failed') or 0)} "
                    f"skipped={int(result.get('skipped') or 0)}"
                ),
                run_id=run_id,
            )
        except Exception as exc:
            _payment_log_job(
                "payment_reminders_schedule",
                trigger_source,
                today_iso,
                "failed",
                message=str(exc)[:900],
                run_id=run_id,
            )
@app.get("/admin/payments/transactions")
async def admin_payments_transactions(
    limit: int = Query(default=40, ge=1, le=150),
    ym: str | None = Query(default=None),
    group_id: int | None = Query(default=None),
    lesson_day: str | None = Query(default=None),
    day: str | None = Query(default=None),
    teacher_name: str | None = Query(default=None),
    group_query: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    payment_status: str | None = Query(default=None),
    payment_method: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_payment_automation_schema()
    ym_filter = _payment_validate_ym(ym) if str(ym or "").strip() else ""
    selected_gid = int(group_id or 0)
    lesson_day_filter = str(lesson_day or "").strip().upper()
    day_filter = str(day or "").strip()
    teacher_filter = str(teacher_name or "").strip().lower()
    group_filter = str(group_query or "").strip().lower()
    subject_filter = str(subject or "").strip().lower()
    status_filter = str(payment_status or "").strip().lower()
    method_filter = str(payment_method or "").strip().lower()
    if selected_gid > 0:
        selected_group = _safe_call(lambda: get_group(selected_gid), None)
        if not _can_manage_group(admin_ref, selected_group):
            raise HTTPException(status_code=403, detail="Permission denied")
        scoped_group_ids = {int(selected_gid)}
    else:
        scoped_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}

    def _append_int_in_filter(where: list[str], params: list[Any], column: str, values: set[int]) -> None:
        clean_values = sorted({int(value) for value in values if int(value or 0) > 0})
        if not clean_values:
            where.append("1=0")
            return
        where.append(f"{column} IN ({', '.join(['?'] * len(clean_values))})")
        params.extend(clean_values)

    scan_limit = max(300, min(2500, int(limit) * 8))
    tx_where: list[str] = ["1=1"]
    tx_params: list[Any] = []
    refund_where: list[str] = ["1=1"]
    refund_params: list[Any] = []
    if selected_gid > 0:
        tx_where.append("tx.group_id=?")
        tx_params.append(int(selected_gid))
        refund_where.append("r.group_id=?")
        refund_params.append(int(selected_gid))
    else:
        _append_int_in_filter(tx_where, tx_params, "tx.group_id", scoped_group_ids)
        _append_int_in_filter(refund_where, refund_params, "r.group_id", scoped_group_ids)
    if ym_filter:
        tx_where.append("tx.ym=?")
        tx_params.append(str(ym_filter))
        refund_where.append("r.ym=?")
        refund_params.append(str(ym_filter))
    if day_filter:
        tx_where.append("DATE(tx.created_at)=DATE(?)")
        tx_params.append(str(day_filter))
        refund_where.append("DATE(r.created_at)=DATE(?)")
        refund_params.append(str(day_filter))
    if method_filter and method_filter not in {"all", "refund"}:
        tx_where.append("LOWER(COALESCE(tx.payment_method,''))=?")
        tx_params.append(str(method_filter))

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT
            tx.id,
            tx.user_id,
            tx.group_id,
            tx.ym,
            tx.created_at AS paid_at,
            tx.amount AS payment_dcoin_amount,
            tx.payment_method,
            tx.card_id,
            COALESCE(tx.refunded_amount, 0) AS refunded_amount,
            tx.is_advance,
            tx.note,
            tx.confirmed_by_admin_id AS paid_by_admin_id,
            tx.confirmed_by_admin_name AS paid_by_admin_name,
            tx.status_after AS payment_status,
            tx.remaining_after,
            tx.overpayment_after,
            TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')) AS student_name,
            g.name AS group_name,
            g.lesson_date,
            g.course_title,
            g.subject AS group_subject,
            g.teacher_id,
            TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name,
            pc.card_number AS card_number,
            pc.owner_first_name AS card_owner_first_name,
            pc.owner_last_name AS card_owner_last_name,
            o.original_amount,
            o.discount_type,
            o.discount_percent,
            o.discount_amount,
            o.final_amount,
            o.debt_amount,
            o.overpayment_amount
        FROM payment_transactions tx
        LEFT JOIN payment_monthly_obligations o ON o.id = tx.obligation_id
        LEFT JOIN users u ON u.id = tx.user_id
        LEFT JOIN groups g ON g.id = tx.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        LEFT JOIN payment_cards pc ON pc.id = tx.card_id
        WHERE {" AND ".join(tx_where)}
        ORDER BY tx.created_at DESC, tx.id DESC
        LIMIT ?
        """,
        tuple([*tx_params, int(scan_limit)]),
    )
    rows = [dict(r) for r in (cur.fetchall() or [])]
    tx_ids = [int(row.get("id") or 0) for row in rows if int(row.get("id") or 0) > 0]
    bonus_map: dict[int, dict[str, Any]] = {}
    if tx_ids:
        placeholders = ", ".join(["?"] * len(tx_ids))
        cur.execute(
            f"""
            SELECT source_transaction_id, bonus_type, amount, COALESCE(reversed,0) AS reversed
            FROM payment_bonus_log
            WHERE source_transaction_id IN ({placeholders})
            """,
            tuple(tx_ids),
        )
        for bonus_row in (cur.fetchall() or []):
            b = dict(bonus_row)
            tx_id = int(b.get("source_transaction_id") or 0)
            if tx_id <= 0:
                continue
            item = bonus_map.get(tx_id) or {"bonus_dpoints": 0.0, "bonus_types": []}
            amount = float(b.get("amount") or 0.0)
            if int(b.get("reversed") or 0) == 1:
                amount = 0.0
            item["bonus_dpoints"] = float(item.get("bonus_dpoints") or 0.0) + float(amount)
            bonus_type = str(b.get("bonus_type") or "").strip()
            if bonus_type and bonus_type not in item["bonus_types"]:
                item["bonus_types"].append(bonus_type)
            bonus_map[tx_id] = item
    conn.close()
    filtered: list[dict] = []
    for row in rows:
        gid = int(row.get("group_id") or 0)
        uid = int(row.get("user_id") or 0)
        if gid and gid not in scoped_group_ids:
            continue
        if selected_gid > 0 and gid != selected_gid:
            continue
        if ym_filter and str(row.get("ym") or "") != ym_filter:
            continue
        if lesson_day_filter and str(row.get("lesson_date") or "").strip().upper() != lesson_day_filter:
            continue
        paid_at = str(row.get("paid_at") or "").strip()
        if day_filter and (not paid_at or not paid_at.startswith(day_filter)):
            continue
        if teacher_filter and teacher_filter not in str(row.get("teacher_name") or "").lower():
            continue
        if group_filter and group_filter not in str(row.get("group_name") or "").lower():
            continue
        if subject_filter and subject_filter != "all":
            if subject_filter not in str(row.get("group_subject") or "").strip().lower():
                continue
        method = str(row.get("payment_method") or "").strip().lower() or "cash"
        if method_filter and method_filter != "all" and method_filter != method:
            continue
        row["payment_type"] = f"advance_{method}" if bool(int(row.get("is_advance") or 0) == 1) else method
        if not str(row.get("payment_status") or "").strip():
            row["payment_status"] = PAYMENT_STATUS_PAID
        row["status"] = str(row.get("payment_status") or PAYMENT_STATUS_PAID)
        if status_filter and status_filter != "all":
            if status_filter not in str(row.get("status") or "").strip().lower():
                continue
        row["paid_amount"] = float(row.get("payment_dcoin_amount") or 0.0)
        row["debt_amount"] = float(row.get("debt_amount") or float(row.get("remaining_after") or 0.0))
        row["overpayment_amount"] = float(row.get("overpayment_amount") or float(row.get("overpayment_after") or 0.0))
        row["final_amount"] = float(row.get("final_amount") or 0.0)
        row["discount_type"] = str(row.get("discount_type") or "none")
        row["discount_percent"] = float(row.get("discount_percent") or 0.0)
        row["discount_amount"] = float(row.get("discount_amount") or 0.0)
        card_number = str(row.get("card_number") or "").strip()
        digits = re.sub(r"\D", "", card_number)
        card_masked = f"{digits[:4]} **** **** {digits[-4:]}" if len(digits) >= 8 else card_number
        row["card_number_masked"] = card_masked if card_masked else None
        row["card_owner_name"] = (
            f"{str(row.get('card_owner_first_name') or '').strip()} {str(row.get('card_owner_last_name') or '').strip()}".strip() or None
        )
        tx_id = int(row.get("id") or 0)
        bonus_meta = bonus_map.get(tx_id) or {}
        row["bonus_dpoints"] = float(bonus_meta.get("bonus_dpoints") or 0.0)
        row["bonus_types"] = bonus_meta.get("bonus_types") or []
        filtered.append(row)
        if len(filtered) >= int(limit):
            break
    referral_cache = _payment_referral_statuses_for_users(
        int(row.get("user_id") or 0)
        for row in filtered
        if int(row.get("user_id") or 0) > 0
    )
    for row in filtered:
        uid = int(row.get("user_id") or 0)
        if uid > 0:
            row["referral_status"] = referral_cache.get(uid)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT
            r.id,
            r.transaction_id,
            r.user_id,
            r.group_id,
            r.ym,
            r.amount,
            r.refund_type,
            r.note,
            r.status_before,
            r.status_after,
            r.debt_after,
            r.overpayment_after,
            r.refunded_by_admin_id,
            r.refunded_by_admin_name,
            r.created_at AS paid_at,
            TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')) AS student_name,
            g.name AS group_name,
            g.lesson_date,
            g.course_title,
            g.subject AS group_subject,
            g.teacher_id,
            TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_refunds r
        LEFT JOIN users u ON u.id = r.user_id
        LEFT JOIN groups g ON g.id = r.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(refund_where)}
        ORDER BY r.created_at DESC, r.id DESC
        LIMIT ?
        """,
        tuple([*refund_params, int(scan_limit)]),
    )
    refund_rows = [dict(r) for r in (cur.fetchall() or [])]
    refund_ids = [int(row.get("id") or 0) for row in refund_rows if int(row.get("id") or 0) > 0]
    refund_bonus_map: dict[int, float] = {}
    if refund_ids:
        placeholders = ", ".join(["?"] * len(refund_ids))
        cur.execute(
            f"""
            SELECT source_refund_id, SUM(COALESCE(amount,0)) AS total_amount
            FROM payment_bonus_log
            WHERE source_refund_id IN ({placeholders})
            GROUP BY source_refund_id
            """,
            tuple(refund_ids),
        )
        for row in (cur.fetchall() or []):
            item = dict(row)
            rid = int(item.get("source_refund_id") or 0)
            if rid <= 0:
                continue
            refund_bonus_map[rid] = float(item.get("total_amount") or 0.0)
    conn.close()
    for row in refund_rows:
        gid = int(row.get("group_id") or 0)
        uid = int(row.get("user_id") or 0)
        if gid and gid not in scoped_group_ids:
            continue
        if selected_gid > 0 and gid != selected_gid:
            continue
        if ym_filter and str(row.get("ym") or "") != ym_filter:
            continue
        if lesson_day_filter and str(row.get("lesson_date") or "").strip().upper() != lesson_day_filter:
            continue
        paid_at = str(row.get("paid_at") or "").strip()
        if day_filter and (not paid_at or not paid_at.startswith(day_filter)):
            continue
        if teacher_filter and teacher_filter not in str(row.get("teacher_name") or "").lower():
            continue
        if group_filter and group_filter not in str(row.get("group_name") or "").lower():
            continue
        if subject_filter and subject_filter != "all":
            if subject_filter not in str(row.get("group_subject") or "").strip().lower():
                continue
        if method_filter and method_filter != "all" and method_filter != "refund":
            continue
        tx_row = {
            "id": f"refund-{int(row.get('id') or 0)}",
            "record_type": "refund",
            "refund_id": int(row.get("id") or 0),
            "source_transaction_id": int(row.get("transaction_id") or 0),
            "user_id": int(row.get("user_id") or 0),
            "group_id": gid,
            "ym": str(row.get("ym") or ""),
            "paid_at": row.get("paid_at"),
            "payment_dcoin_amount": -abs(float(row.get("amount") or 0.0)),
            "paid_amount": -abs(float(row.get("amount") or 0.0)),
            "payment_method": "refund",
            "payment_type": "refund",
            "payment_status": str(row.get("status_after") or PAYMENT_STATUS_UNPAID),
            "status": str(row.get("status_after") or PAYMENT_STATUS_UNPAID),
            "remaining_after": float(row.get("debt_after") or 0.0),
            "overpayment_after": float(row.get("overpayment_after") or 0.0),
            "debt_amount": float(row.get("debt_after") or 0.0),
            "overpayment_amount": float(row.get("overpayment_after") or 0.0),
            "student_name": str(row.get("student_name") or "").strip(),
            "group_name": row.get("group_name"),
            "lesson_date": row.get("lesson_date"),
            "course_title": row.get("course_title"),
            "group_subject": row.get("group_subject"),
            "teacher_id": row.get("teacher_id"),
            "teacher_name": row.get("teacher_name"),
            "paid_by_admin_id": row.get("refunded_by_admin_id"),
            "paid_by_admin_name": row.get("refunded_by_admin_name"),
            "note": row.get("note"),
            "refund_type": row.get("refund_type"),
            "bonus_dpoints": -abs(float(refund_bonus_map.get(int(row.get("id") or 0), 0.0))),
        }
        filtered.append(tx_row)
    filtered.sort(key=lambda r: (str(r.get("paid_at") or ""), str(r.get("id") or "")), reverse=True)
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 250:
        logger.info(
            "perf payments.transactions group_id=%s ym=%s total_ms=%.2f tx_rows=%s refund_rows=%s returned=%s",
            int(selected_gid or 0),
            str(ym_filter or ""),
            elapsed_ms,
            len(rows),
            len(refund_rows),
            min(len(filtered), int(limit)),
        )
    return {
        "items": filtered[: int(limit)],
        "permission_scope": "general" if _is_general_admin_scope(admin_ref) else "limited",
    }


def _payment_export_scope_filters(
    *,
    payload: PaymentExportRequest | None,
    months: int | None = None,
    group_id: int | None = None,
    teacher_name: str | None = None,
    subject: str | None = None,
    payment_status: str | None = None,
    payment_method: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
) -> dict[str, Any]:
    body = payload or PaymentExportRequest()
    return {
        "months": int(months or body.months or 6),
        "group_id": int(group_id or body.group_id or 0) if int(group_id or body.group_id or 0) > 0 else None,
        "teacher_name": (str(teacher_name or body.teacher_name or "").strip() or None),
        "subject": (str(subject or body.subject or "").strip() or None),
        "payment_status": (str(payment_status or body.payment_status or "").strip() or None),
        "payment_method": (str(payment_method or body.payment_method or "").strip() or None),
        "date_from": (str(date_from or body.date_from or "").strip() or None),
        "date_to": (str(date_to or body.date_to or "").strip() or None),
    }


@app.get("/admin/payments/export")
async def admin_payments_export(
    months: int = Query(default=6, ge=1, le=36),
    group_id: int | None = Query(default=None),
    teacher_name: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    payment_status: str | None = Query(default=None),
    payment_method: str | None = Query(default=None),
    date_from: str | None = Query(default=None),
    date_to: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    _require_payment_extra_feature("payments export")
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    from_day = _payment_validate_optional_iso_date(date_from, field_name="date_from")
    to_day = _payment_validate_optional_iso_date(date_to, field_name="date_to")
    if from_day and to_day and from_day > to_day:
        raise HTTPException(status_code=400, detail="date_from must be before date_to")
    if int(group_id or 0) > 0:
        target_group = _safe_call(lambda gid=int(group_id): get_group(gid), None)
        if not _can_manage_group(admin_ref, target_group):
            raise HTTPException(status_code=403, detail="Permission denied")
    scoped_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}
    filters = _payment_export_scope_filters(
        payload=None,
        months=months,
        group_id=group_id,
        teacher_name=teacher_name,
        subject=subject,
        payment_status=payment_status,
        payment_method=payment_method,
        date_from=date_from,
        date_to=date_to,
    )
    bio, filename = export_payment_history_to_xlsx(
        owner_admin_id=(None if _is_general_admin_scope(admin_ref) else int(admin_ref)),
        filters=filters,
        scoped_group_ids=scoped_group_ids,
    )
    logger.info(
        "payment_export_downloaded admin_ref_id=%s scope=%s months=%s group_id=%s",
        int(admin_ref),
        "general" if _is_general_admin_scope(admin_ref) else "limited",
        int(filters.get("months") or 0),
        int(filters.get("group_id") or 0) if filters.get("group_id") else 0,
    )
    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return StreamingResponse(bio, media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers=headers)


@app.get("/admin/payments/stats")
async def admin_payments_stats(
    ym: str | None = Query(default=None),
    group_id: int | None = Query(default=None),
    teacher_name: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    payment_status: str | None = Query(default=None),
    payment_method: str | None = Query(default=None),
    date_from: str | None = Query(default=None),
    date_to: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    selected_group_id = int(group_id or 0)
    teacher_filter = str(teacher_name or "").strip().lower()
    subject_filter = str(subject or "").strip().lower()
    status_filter = str(payment_status or "").strip().lower()
    method_filter = str(payment_method or "").strip().lower()
    raw_date_from = str(date_from or "").strip()
    raw_date_to = str(date_to or "").strip()

    from_day = _payment_validate_optional_iso_date(raw_date_from, field_name="date_from")
    to_day = _payment_validate_optional_iso_date(raw_date_to, field_name="date_to")
    if from_day and to_day and from_day > to_day:
        raise HTTPException(status_code=400, detail="date_from must be before date_to")
    from_ym = (from_day.strftime("%Y-%m") if from_day else month_key)
    to_ym = (to_day.strftime("%Y-%m") if to_day else month_key)
    if from_ym > to_ym:
        from_ym, to_ym = to_ym, from_ym

    # Keep stats open fast for wide custom ranges: only trigger freshness recalc
    # for the currently selected single month view.
    if (not from_day and not to_day) or (from_ym == to_ym == month_key):
        _payment_recalc_for_view_if_stale({month_key}, trigger_source="stats_open", freshness_seconds=900)
    _ensure_payment_automation_schema()
    group = _safe_call(lambda: get_group(selected_group_id), None) if selected_group_id > 0 else None
    if selected_group_id > 0 and not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    scoped_groups = [group] if selected_group_id > 0 and group else _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])
    scoped_group_ids = {int(g.get("id") or 0) for g in scoped_groups if g}
    obligation_where = ["o.ym>=? AND o.ym<=?"]
    obligation_params: list[Any] = [from_ym, to_ym]
    tx_where = ["tx.ym>=? AND tx.ym<=?"]
    tx_params: list[Any] = [from_ym, to_ym]
    refund_where = ["r.ym>=? AND r.ym<=?"]
    refund_params: list[Any] = [from_ym, to_ym]
    bonus_where = ["b.ym>=? AND b.ym<=?"]
    bonus_params: list[Any] = [from_ym, to_ym]
    penalty_where = ["p.ym>=? AND p.ym<=?"]
    penalty_params: list[Any] = [from_ym, to_ym]

    def _append_int_in_filter(where: list[str], params: list[Any], column: str, values: set[int]) -> None:
        clean_values = sorted({int(value) for value in values if int(value or 0) > 0})
        if not clean_values:
            where.append("1=0")
            return
        where.append(f"{column} IN ({', '.join(['?'] * len(clean_values))})")
        params.extend(clean_values)

    if selected_group_id > 0:
        obligation_where.append("o.group_id=?")
        obligation_params.append(int(selected_group_id))
        tx_where.append("tx.group_id=?")
        tx_params.append(int(selected_group_id))
        refund_where.append("r.group_id=?")
        refund_params.append(int(selected_group_id))
        bonus_where.append("b.group_id=?")
        bonus_params.append(int(selected_group_id))
        penalty_where.append("p.group_id=?")
        penalty_params.append(int(selected_group_id))
    else:
        _append_int_in_filter(obligation_where, obligation_params, "o.group_id", scoped_group_ids)
        _append_int_in_filter(tx_where, tx_params, "tx.group_id", scoped_group_ids)
        _append_int_in_filter(refund_where, refund_params, "r.group_id", scoped_group_ids)
        _append_int_in_filter(bonus_where, bonus_params, "b.group_id", scoped_group_ids)
        _append_int_in_filter(penalty_where, penalty_params, "p.group_id", scoped_group_ids)

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        f"""
        SELECT
            o.*,
            g.name AS group_name,
            g.subject AS group_subject,
            g.course_title AS group_course_title,
            g.teacher_id,
            TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name,
            TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')) AS student_name,
            u.phone AS student_phone
        FROM payment_monthly_obligations o
        LEFT JOIN groups g ON g.id = o.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        LEFT JOIN users u ON u.id = o.user_id
        WHERE {" AND ".join(obligation_where)}
        ORDER BY o.ym DESC, o.updated_at DESC, o.id DESC
        """,
        tuple(obligation_params),
    )
    obligation_rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        f"""
        SELECT
            tx.id,
            tx.user_id,
            tx.group_id,
            tx.ym,
            tx.amount,
            tx.payment_method,
            tx.status_after,
            tx.created_at,
            g.subject AS group_subject,
            g.teacher_id,
            TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_transactions tx
        LEFT JOIN groups g ON g.id = tx.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(tx_where)}
        ORDER BY tx.created_at DESC, tx.id DESC
        """,
        tuple(tx_params),
    )
    transaction_rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        f"""
        SELECT
            r.id,
            r.user_id,
            r.group_id,
            r.ym,
            r.amount,
            r.status_after,
            r.created_at,
            g.subject AS group_subject,
            g.teacher_id,
            TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_refunds r
        LEFT JOIN groups g ON g.id = r.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(refund_where)}
        ORDER BY r.created_at DESC, r.id DESC
        """,
        tuple(refund_params),
    )
    refund_rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        f"""
        SELECT b.amount, b.reversed, b.group_id, b.ym, g.subject AS group_subject,
               g.teacher_id, TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_bonus_log b
        LEFT JOIN groups g ON g.id = b.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(bonus_where)}
        """,
        tuple(bonus_params),
    )
    bonus_rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        f"""
        SELECT p.amount, p.group_id, p.ym, g.subject AS group_subject,
               g.teacher_id, TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_penalty_log p
        LEFT JOIN groups g ON g.id = p.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE {" AND ".join(penalty_where)}
        """,
        tuple(penalty_params),
    )
    penalty_rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()

    def _date_ok(raw_value: Any) -> bool:
        if not from_day and not to_day:
            return True
        raw = str(raw_value or "")[:10]
        if not raw:
            return False
        try:
            day_val = datetime.strptime(raw, "%Y-%m-%d").date()
        except Exception:
            return False
        if from_day and day_val < from_day:
            return False
        if to_day and day_val > to_day:
            return False
        return True

    def _common_ok(row: dict[str, Any], *, status_key: str | None = None) -> bool:
        gid = int(row.get("group_id") or 0)
        if gid > 0 and gid not in scoped_group_ids:
            return False
        if selected_group_id > 0 and gid != selected_group_id:
            return False
        if teacher_filter and teacher_filter not in str(row.get("teacher_name") or "").lower():
            return False
        if subject_filter and subject_filter != "all":
            if subject_filter not in str(row.get("group_subject") or "").lower():
                return False
        if status_filter and status_filter != "all" and status_key:
            if status_filter not in str(row.get(status_key) or "").lower():
                return False
        if str(row.get("discount_type") or "") == "free_access":
            return False
        return True

    filtered: list[dict] = []
    for row in obligation_rows:
        if not _common_ok(row, status_key="status"):
            continue
        filtered.append(row)

    filtered_transactions: list[dict] = []
    for row in transaction_rows:
        method_value = str(row.get("payment_method") or "").strip().lower() or "cash"
        row["payment_method"] = method_value
        if method_filter and method_filter != "all" and method_filter != method_value:
            continue
        if not _date_ok(row.get("created_at")):
            continue
        if not _common_ok(row, status_key="status_after"):
            continue
        filtered_transactions.append(row)

    filtered_refunds: list[dict] = []
    for row in refund_rows:
        if method_filter and method_filter != "all" and method_filter != "refund":
            continue
        if not _date_ok(row.get("created_at")):
            continue
        if not _common_ok(row, status_key="status_after"):
            continue
        filtered_refunds.append(row)

    filtered_bonuses: list[dict] = []
    for row in bonus_rows:
        if not _common_ok(row):
            continue
        filtered_bonuses.append(row)

    filtered_penalties: list[dict] = []
    for row in penalty_rows:
        if not _common_ok(row):
            continue
        filtered_penalties.append(row)

    by_user: dict[int, dict[str, Any]] = {}
    for row in filtered:
        uid = int(row.get("user_id") or 0)
        if uid <= 0:
            continue
        item = by_user.get(uid)
        if not item:
            item = {
                "id": uid,
                "full_name": str(row.get("student_name") or "").strip() or f"User #{uid}",
                "phone": str(row.get("student_phone") or "").strip(),
                "status": str(row.get("status") or PAYMENT_STATUS_UNPAID),
                "group_names": set(),
                "course_names": set(),
                "final_payable_amount": 0.0,
                "paid_amount": 0.0,
                "debt_amount": 0.0,
                "overpayment_amount": 0.0,
            }
            by_user[uid] = item
        if str(row.get("group_name") or "").strip():
            item["group_names"].add(str(row.get("group_name") or "").strip())
        course_name = str(row.get("course_title") or row.get("group_course_title") or "").strip()
        if course_name:
            item["course_names"].add(course_name)
        item["final_payable_amount"] = float(item.get("final_payable_amount") or 0.0) + float(row.get("final_amount") or 0.0)
        item["paid_amount"] = float(item.get("paid_amount") or 0.0) + float(row.get("paid_amount") or 0.0)
        item["debt_amount"] = float(item.get("debt_amount") or 0.0) + float(row.get("debt_amount") or 0.0)
        item["overpayment_amount"] = float(item.get("overpayment_amount") or 0.0) + float(row.get("overpayment_amount") or 0.0)
        status_value = str(row.get("status") or PAYMENT_STATUS_UNPAID)
        if status_value == PAYMENT_STATUS_OVERDUE:
            item["status"] = PAYMENT_STATUS_OVERDUE
        elif status_value == PAYMENT_STATUS_PARTIAL and item["status"] != PAYMENT_STATUS_OVERDUE:
            item["status"] = PAYMENT_STATUS_PARTIAL
        elif status_value == PAYMENT_STATUS_UNPAID and item["status"] not in {PAYMENT_STATUS_OVERDUE, PAYMENT_STATUS_PARTIAL}:
            item["status"] = PAYMENT_STATUS_UNPAID
        elif status_value == PAYMENT_STATUS_OVERPAY and item["status"] not in {PAYMENT_STATUS_OVERDUE, PAYMENT_STATUS_PARTIAL, PAYMENT_STATUS_UNPAID}:
            item["status"] = PAYMENT_STATUS_OVERPAY

    student_rows: list[dict[str, Any]] = []
    for row in by_user.values():
        student_rows.append(
            {
                "id": int(row.get("id") or 0),
                "full_name": str(row.get("full_name") or "").strip(),
                "phone": str(row.get("phone") or "").strip(),
                "group_names": sorted(list(row.get("group_names") or [])),
                "course_names": sorted(list(row.get("course_names") or [])),
                "final_payable_amount": round(float(row.get("final_payable_amount") or 0.0), 2),
                "paid_amount": round(float(row.get("paid_amount") or 0.0), 2),
                "debt_amount": round(float(row.get("debt_amount") or 0.0), 2),
                "overpayment_amount": round(float(row.get("overpayment_amount") or 0.0), 2),
                "status": str(row.get("status") or PAYMENT_STATUS_UNPAID),
            }
        )

    paid_students = [row for row in student_rows if str(row.get("status") or "") in {PAYMENT_STATUS_PAID, PAYMENT_STATUS_OVERPAY}]
    unpaid_students = [row for row in student_rows if str(row.get("status") or "") == PAYMENT_STATUS_UNPAID]
    partial_students = [row for row in student_rows if str(row.get("status") or "") == PAYMENT_STATUS_PARTIAL]
    late_students = [row for row in student_rows if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE]
    overpay_students = [row for row in student_rows if str(row.get("status") or "") == PAYMENT_STATUS_OVERPAY]

    group_map: dict[int, dict[str, Any]] = {}
    teacher_map: dict[int, dict[str, Any]] = {}
    for row in filtered:
        gid = int(row.get("group_id") or 0)
        if gid <= 0:
            continue
        teacher_id = int(row.get("teacher_id") or 0)
        group_item = group_map.get(gid)
        if not group_item:
            group_item = {
                "group_id": gid,
                "group_name": str(row.get("group_name") or "").strip() or f"Group #{gid}",
                "teacher_name": str(row.get("teacher_name") or "").strip() or "-",
                "student_ids": set(),
                "expected_amount": 0.0,
                "final_amount": 0.0,
                "paid_amount": 0.0,
                "debt_amount": 0.0,
                "discount_amount": 0.0,
                "refund_amount": 0.0,
                "overdue_user_ids": set(),
            }
            group_map[gid] = group_item
        group_item["student_ids"].add(int(row.get("user_id") or 0))
        group_item["expected_amount"] += (0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0))
        group_item["final_amount"] += float(row.get("final_amount") or 0.0)
        group_item["paid_amount"] += float(row.get("paid_amount") or 0.0)
        group_item["debt_amount"] += float(row.get("debt_amount") or 0.0)
        group_item["discount_amount"] += float(row.get("discount_amount") or 0.0)
        if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE:
            group_item["overdue_user_ids"].add(int(row.get("user_id") or 0))

        teacher_item = teacher_map.get(teacher_id)
        if not teacher_item:
            teacher_item = {
                "teacher_id": teacher_id,
                "teacher_name": str(row.get("teacher_name") or "").strip() or ("No teacher" if teacher_id <= 0 else f"Teacher #{teacher_id}"),
                "group_ids": set(),
                "student_ids": set(),
                "expected_amount": 0.0,
                "final_amount": 0.0,
                "paid_amount": 0.0,
                "debt_amount": 0.0,
                "discount_amount": 0.0,
                "refund_amount": 0.0,
                "overdue_user_ids": set(),
            }
            teacher_map[teacher_id] = teacher_item
        teacher_item["group_ids"].add(gid)
        teacher_item["student_ids"].add(int(row.get("user_id") or 0))
        teacher_item["expected_amount"] += (0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0))
        teacher_item["final_amount"] += float(row.get("final_amount") or 0.0)
        teacher_item["paid_amount"] += float(row.get("paid_amount") or 0.0)
        teacher_item["debt_amount"] += float(row.get("debt_amount") or 0.0)
        teacher_item["discount_amount"] += float(row.get("discount_amount") or 0.0)
        if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE:
            teacher_item["overdue_user_ids"].add(int(row.get("user_id") or 0))

    for row in filtered_refunds:
        gid = int(row.get("group_id") or 0)
        teacher_id = int(row.get("teacher_id") or 0)
        if gid in group_map:
            group_map[gid]["refund_amount"] += abs(float(row.get("amount") or 0.0))
        if teacher_id in teacher_map:
            teacher_map[teacher_id]["refund_amount"] += abs(float(row.get("amount") or 0.0))

    group_comparison: list[dict[str, Any]] = []
    for item in group_map.values():
        final_amount = float(item.get("final_amount") or 0.0)
        paid_amount = float(item.get("paid_amount") or 0.0)
        group_comparison.append(
            {
                "group_id": int(item.get("group_id") or 0),
                "group_name": item.get("group_name"),
                "teacher_name": item.get("teacher_name"),
                "student_count": len(item.get("student_ids") or set()),
                "expected_amount": round(float(item.get("expected_amount") or 0.0), 2),
                "paid_amount": round(paid_amount, 2),
                "debt_amount": round(float(item.get("debt_amount") or 0.0), 2),
                "discount_amount": round(float(item.get("discount_amount") or 0.0), 2),
                "refund_amount": round(float(item.get("refund_amount") or 0.0), 2),
                "overdue_count": len(item.get("overdue_user_ids") or set()),
                "completion_percent": round((paid_amount / final_amount) * 100.0, 2) if final_amount > 1e-9 else 0.0,
            }
        )
    group_comparison.sort(key=lambda r: (float(r.get("debt_amount") or 0.0), -float(r.get("paid_amount") or 0.0)), reverse=True)

    teacher_comparison: list[dict[str, Any]] = []
    for item in teacher_map.values():
        final_amount = float(item.get("final_amount") or 0.0)
        paid_amount = float(item.get("paid_amount") or 0.0)
        teacher_comparison.append(
            {
                "teacher_id": int(item.get("teacher_id") or 0),
                "teacher_name": item.get("teacher_name"),
                "group_count": len(item.get("group_ids") or set()),
                "student_count": len(item.get("student_ids") or set()),
                "expected_amount": round(float(item.get("expected_amount") or 0.0), 2),
                "paid_amount": round(paid_amount, 2),
                "debt_amount": round(float(item.get("debt_amount") or 0.0), 2),
                "discount_amount": round(float(item.get("discount_amount") or 0.0), 2),
                "refund_amount": round(float(item.get("refund_amount") or 0.0), 2),
                "overdue_count": len(item.get("overdue_user_ids") or set()),
                "completion_percent": round((paid_amount / final_amount) * 100.0, 2) if final_amount > 1e-9 else 0.0,
            }
        )
    teacher_comparison.sort(key=lambda r: (float(r.get("debt_amount") or 0.0), -float(r.get("paid_amount") or 0.0)), reverse=True)

    chart_map: dict[str, dict[str, float]] = {}
    cursor = from_ym
    while cursor <= to_ym:
        chart_map[cursor] = {"paid_amount": 0.0, "debt_amount": 0.0, "expected_amount": 0.0, "final_amount": 0.0}
        cursor = _payment_next_ym(cursor)
    for row in filtered:
        ym_key = str(row.get("ym") or "")
        if ym_key in chart_map:
            chart_map[ym_key]["debt_amount"] += float(row.get("debt_amount") or 0.0)
            chart_map[ym_key]["expected_amount"] += float(row.get("original_amount") or 0.0)
            chart_map[ym_key]["final_amount"] += float(row.get("final_amount") or 0.0)
    for row in filtered_transactions:
        ym_key = str(row.get("ym") or "")
        if ym_key in chart_map:
            if str(row.get("payment_method") or "") == "carry_forward":
                continue
            chart_map[ym_key]["paid_amount"] += float(row.get("amount") or 0.0)

    chart_series = []
    for ym_key in sorted(chart_map.keys()):
        values = chart_map[ym_key]
        chart_series.append(
            {
                "label": ym_key,
                "month": ym_key,
                "paid_amount": round(values["paid_amount"], 2),
                "debt_amount": round(values["debt_amount"], 2),
                "expected_amount": round(values["expected_amount"], 2),
                "final_amount": round(values["final_amount"], 2),
            }
        )

    status_counts = {
        "paid": len(paid_students),
        "unpaid": len(unpaid_students),
        "partial": len(partial_students),
        "overdue": len(late_students),
        "overpayment": len(overpay_students),
    }
    paid_amount_by_method = round(
        sum(
            float(row.get("amount") or 0.0)
            for row in filtered_transactions
            if str(row.get("payment_method") or "").strip().lower() not in {"refund"}
        ),
        2,
    )
    summary = {
        "total_paid_amount": paid_amount_by_method if method_filter and method_filter != "all" else round(sum(float(row.get("paid_amount") or 0.0) for row in filtered), 2),
        "total_debt_amount": round(sum(float(row.get("debt_amount") or 0.0) for row in filtered), 2),
        "total_expected_amount": round(sum(0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0) for row in filtered), 2),
        "total_final_payable_amount": round(sum(float(row.get("final_amount") or 0.0) for row in filtered), 2),
        "total_discount_amount": round(sum(float(row.get("discount_amount") or 0.0) for row in filtered), 2),
        "total_refund_amount": round(sum(abs(float(row.get("amount") or 0.0)) for row in filtered_refunds), 2),
        "total_overpayment_amount": round(sum(float(row.get("overpayment_amount") or 0.0) for row in filtered), 2),
        "student_count": len(student_rows),
        "paid_student_count": status_counts["paid"],
        "unpaid_student_count": status_counts["unpaid"],
        "partial_student_count": status_counts["partial"],
        "overdue_student_count": status_counts["overdue"],
        "overpayment_student_count": status_counts["overpayment"],
        "dpoint_bonus_given": round(
            sum(float(row.get("amount") or 0.0) for row in filtered_bonuses if int(row.get("reversed") or 0) == 0),
            2,
        ),
        "dcoin_penalties_applied": round(sum(abs(float(row.get("amount") or 0.0)) for row in filtered_penalties), 2),
        "payment_transaction_count": len(filtered_transactions),
        "refund_transaction_count": len(filtered_refunds),
    }

    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 250:
        logger.info(
            "perf payments.stats group_id=%s ym=%s total_ms=%.2f obligations=%s tx=%s refunds=%s groups=%s teachers=%s",
            int(selected_group_id or 0),
            str(month_key),
            elapsed_ms,
            len(obligation_rows),
            len(transaction_rows),
            len(refund_rows),
            len(group_comparison),
            len(teacher_comparison),
        )

    return {
        "ym": month_key,
        "period": {
            "from_ym": from_ym,
            "to_ym": to_ym,
            "date_from": raw_date_from or None,
            "date_to": raw_date_to or None,
        },
        "filters": {
            "group_id": selected_group_id if selected_group_id > 0 else None,
            "teacher_name": teacher_name or None,
            "subject": subject or None,
            "payment_status": payment_status or None,
            "payment_method": payment_method or None,
        },
        "group_id": selected_group_id if selected_group_id > 0 else None,
        "group_name": (str((group or {}).get("name") or "").strip() if selected_group_id > 0 else None),
        "summary": summary,
        "status_counts": status_counts,
        "status_lists": {
            "paid": paid_students[:800],
            "unpaid": unpaid_students[:800],
            "partial": partial_students[:800],
            "overdue": late_students[:800],
            "overpayment": overpay_students[:800],
        },
        "group_comparison": group_comparison[:500],
        "teacher_comparison": teacher_comparison[:500],
        "chart_data": {
            "series": chart_series,
            "pie": {
                "paid_amount": round(sum(float(item.get("paid_amount") or 0.0) for item in chart_series), 2),
                "debt_amount": round(sum(float(item.get("debt_amount") or 0.0) for item in chart_series), 2),
            },
        },
        # legacy fields
        "paid_count": status_counts["paid"],
        "unpaid_count": status_counts["unpaid"],
        "partial_count": status_counts["partial"],
        "late_count": status_counts["overdue"],
        "overpayment_count": status_counts["overpayment"],
        "total_paid_amount": summary["total_paid_amount"],
        "total_debt_amount": summary["total_debt_amount"],
        "total_discount_amount": summary["total_discount_amount"],
        "total_overpayment_amount": summary["total_overpayment_amount"],
        "paid_students": paid_students[:500],
        "unpaid_students": unpaid_students[:500],
        "partial_students": partial_students[:500],
        "late_students": late_students[:500],
        "overpayment_students": overpay_students[:500],
        "permission_scope": "general" if _is_general_admin_scope(admin_ref) else "limited",
    }


@app.get("/admin/payments/calculate")
async def admin_payments_calculate(
    user_id: int = Query(...),
    group_id: int | None = Query(default=None),
    ym: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target_user = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not _can_manage_user_globally(admin_ref, target_user):
        raise HTTPException(status_code=403, detail="Permission denied")
    selected_group_id = int(group_id or 0)
    if selected_group_id > 0:
        group_row = _safe_call(lambda: get_group(selected_group_id), None)
        if not _can_manage_group(admin_ref, group_row):
            raise HTTPException(status_code=403, detail="Permission denied")
    tz = pytz.timezone("Asia/Tashkent")
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else datetime.now(tz).strftime("%Y-%m")
    result = _calculate_monthly_payment_summary_for_student(
        int(user_id),
        month_key,
        int(admin_ref),
        selected_group_id if selected_group_id > 0 else None,
    )
    return result


