@app.patch("/admin/dpoint-settings")
@app.patch("/admin/economy/settings")
async def admin_update_economy_settings(
    payload: DpointSettingsUpdateRequest,
    request: Request,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _assert_general_admin_for_payment_globals(admin_ref, "economy_settings_update")
    before_values = _get_runtime_settings()
    values = _save_runtime_settings(payload.values or {})
    _append_economy_settings_audit_entries(
        actor_user_id=int(user.get("id") or 0),
        actor_name=_display_name(user),
        source_ip=str(getattr(request.client, "host", "") or ""),
        before=before_values,
        after=values,
    )
    _run_payment_recalculation_for_month(_payment_ym_now(), trigger_source="economy_settings_update")
    return {
        "message": "Settings updated",
        "values": values,
        "updated_at": _runtime_settings_updated_at(),
        "audit": _list_economy_settings_audit(80),
    }


