@app.get("/admin/payments/dashboard")
async def admin_payments_dashboard(
    ym: str | None = Query(default=None),
    group_id: int | None = Query(default=None),
    status: str | None = Query(default=None),
    include_items: bool = Query(default=True),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    # Keep dashboard opens fast: use already materialized obligations here.
    # Detailed stats/detail/payment actions still recalculate where needed.
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT o.*, g.name AS group_name, g.teacher_id,
               TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_monthly_obligations o
        LEFT JOIN groups g ON g.id = o.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE o.ym=?
        ORDER BY o.updated_at DESC, o.id DESC
        """,
        (month_key,),
    )
    rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        """
        SELECT *
        FROM payment_job_runs
        ORDER BY started_at DESC, id DESC
        LIMIT 30
        """
    )
    job_rows = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        """
        SELECT r.*, g.name AS group_name, g.teacher_id,
               TRIM(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) AS teacher_name
        FROM payment_refunds r
        LEFT JOIN groups g ON g.id = r.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE r.ym=?
        ORDER BY r.created_at DESC, r.id DESC
        """,
        (month_key,),
    )
    refund_rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()
    scoped_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}
    selected_gid = int(group_id or 0)
    status_filter = str(status or "").strip().lower()
    filtered = []
    for row in rows:
        gid = int(row.get("group_id") or 0)
        if gid > 0 and gid not in scoped_group_ids:
            continue
        if selected_gid > 0 and gid != selected_gid:
            continue
        if status_filter and status_filter not in str(row.get("status") or "").lower():
            continue
        filtered.append(row)
    filtered_refunds: list[dict[str, Any]] = []
    for row in refund_rows:
        gid = int(row.get("group_id") or 0)
        if gid > 0 and gid not in scoped_group_ids:
            continue
        if selected_gid > 0 and gid != selected_gid:
            continue
        filtered_refunds.append(row)
    total_paid = sum(float(row.get("paid_amount") or 0.0) for row in filtered)
    total_debt = sum(float(row.get("debt_amount") or 0.0) for row in filtered)
    total_discount = sum(float(row.get("discount_amount") or 0.0) for row in filtered)
    total_over = sum(float(row.get("overpayment_amount") or 0.0) for row in filtered)
    total_expected = sum(0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0) for row in filtered)
    total_final = sum(float(row.get("final_amount") or 0.0) for row in filtered)
    total_refund = sum(abs(float(row.get("amount") or 0.0)) for row in filtered_refunds)
    paid_rows = [row for row in filtered if str(row.get("status") or "") == PAYMENT_STATUS_PAID]
    unpaid_rows = [row for row in filtered if str(row.get("status") or "") == PAYMENT_STATUS_UNPAID]
    partial_rows = [row for row in filtered if str(row.get("status") or "") == PAYMENT_STATUS_PARTIAL]
    overdue_rows = [row for row in filtered if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE]
    overpay_rows = [row for row in filtered if str(row.get("status") or "") == PAYMENT_STATUS_OVERPAY]
    group_map: dict[int, dict[str, Any]] = {}
    teacher_map: dict[int, dict[str, Any]] = {}
    for row in filtered:
        gid = int(row.get("group_id") or 0)
        uid = int(row.get("user_id") or 0)
        if gid <= 0:
            continue
        teacher_id = int(row.get("teacher_id") or 0)
        group_item = group_map.get(gid)
        if not group_item:
            group_item = {
                "group_id": gid,
                "group_name": str(row.get("group_name") or "").strip() or f"Group #{gid}",
                "teacher_name": str(row.get("teacher_name") or "").strip() or ("No teacher" if teacher_id <= 0 else f"Teacher #{teacher_id}"),
                "student_ids": set(),
                "expected_amount": 0.0,
                "final_amount": 0.0,
                "paid_amount": 0.0,
                "debt_amount": 0.0,
                "discount_amount": 0.0,
                "refund_amount": 0.0,
                "overdue_user_ids": set(),
            }
            group_map[gid] = group_item
        if uid > 0:
            group_item["student_ids"].add(uid)
        group_item["expected_amount"] += (0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0))
        group_item["final_amount"] += float(row.get("final_amount") or 0.0)
        group_item["paid_amount"] += float(row.get("paid_amount") or 0.0)
        group_item["debt_amount"] += float(row.get("debt_amount") or 0.0)
        group_item["discount_amount"] += float(row.get("discount_amount") or 0.0)
        if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE and uid > 0:
            group_item["overdue_user_ids"].add(uid)

        teacher_item = teacher_map.get(teacher_id)
        if not teacher_item:
            teacher_item = {
                "teacher_id": teacher_id,
                "teacher_name": str(row.get("teacher_name") or "").strip() or ("No teacher" if teacher_id <= 0 else f"Teacher #{teacher_id}"),
                "group_ids": set(),
                "student_ids": set(),
                "expected_amount": 0.0,
                "final_amount": 0.0,
                "paid_amount": 0.0,
                "debt_amount": 0.0,
                "discount_amount": 0.0,
                "refund_amount": 0.0,
                "overdue_user_ids": set(),
            }
            teacher_map[teacher_id] = teacher_item
        teacher_item["group_ids"].add(gid)
        if uid > 0:
            teacher_item["student_ids"].add(uid)
        teacher_item["expected_amount"] += (0.0 if str(row.get("discount_type") or "") == "free_access" else float(row.get("original_amount") or 0.0))
        teacher_item["final_amount"] += float(row.get("final_amount") or 0.0)
        teacher_item["paid_amount"] += float(row.get("paid_amount") or 0.0)
        teacher_item["debt_amount"] += float(row.get("debt_amount") or 0.0)
        teacher_item["discount_amount"] += float(row.get("discount_amount") or 0.0)
        if str(row.get("status") or "") == PAYMENT_STATUS_OVERDUE and uid > 0:
            teacher_item["overdue_user_ids"].add(uid)
    for row in filtered_refunds:
        gid = int(row.get("group_id") or 0)
        teacher_id = int(row.get("teacher_id") or 0)
        amount = abs(float(row.get("amount") or 0.0))
        if gid in group_map:
            group_map[gid]["refund_amount"] += amount
        if teacher_id in teacher_map:
            teacher_map[teacher_id]["refund_amount"] += amount

    def _comparison_payload(item: dict[str, Any], *, teacher: bool = False) -> dict[str, Any]:
        final_amount = float(item.get("final_amount") or 0.0)
        paid_amount = float(item.get("paid_amount") or 0.0)
        payload: dict[str, Any] = {
            "student_count": len(item.get("student_ids") or set()),
            "expected_amount": round(float(item.get("expected_amount") or 0.0), 2),
            "paid_amount": round(paid_amount, 2),
            "debt_amount": round(float(item.get("debt_amount") or 0.0), 2),
            "discount_amount": round(float(item.get("discount_amount") or 0.0), 2),
            "refund_amount": round(float(item.get("refund_amount") or 0.0), 2),
            "overdue_count": len(item.get("overdue_user_ids") or set()),
            "completion_percent": round((paid_amount / final_amount) * 100.0, 2) if final_amount > 1e-9 else 0.0,
        }
        if teacher:
            payload.update({
                "teacher_id": int(item.get("teacher_id") or 0),
                "teacher_name": item.get("teacher_name"),
                "group_count": len(item.get("group_ids") or set()),
            })
        else:
            payload.update({
                "group_id": int(item.get("group_id") or 0),
                "group_name": item.get("group_name"),
                "teacher_name": item.get("teacher_name"),
            })
        return payload

    group_comparison = [_comparison_payload(item) for item in group_map.values()]
    group_comparison.sort(key=lambda r: (float(r.get("debt_amount") or 0.0), -float(r.get("paid_amount") or 0.0)), reverse=True)
    teacher_comparison = [_comparison_payload(item, teacher=True) for item in teacher_map.values()]
    teacher_comparison.sort(key=lambda r: (float(r.get("debt_amount") or 0.0), -float(r.get("paid_amount") or 0.0)), reverse=True)
    if include_items:
        referral_map = _payment_referral_statuses_for_users(
            int(row.get("user_id") or 0)
            for row in filtered
            if int(row.get("user_id") or 0) > 0
        )
        for row in filtered:
            uid = int(row.get("user_id") or 0)
            if uid > 0:
                row["referral_status"] = referral_map.get(uid)
    return {
        "ym": month_key,
        "stats": {
            "student_count": len({int(row.get("user_id") or 0) for row in filtered if int(row.get("user_id") or 0) > 0}),
            "paid_students": len({int(row.get("user_id") or 0) for row in paid_rows}),
            "unpaid_students": len({int(row.get("user_id") or 0) for row in unpaid_rows}),
            "partial_students": len({int(row.get("user_id") or 0) for row in partial_rows}),
            "late_students": len({int(row.get("user_id") or 0) for row in overdue_rows}),
            "overpayment_students": len({int(row.get("user_id") or 0) for row in overpay_rows}),
            "total_paid_amount": round(total_paid, 2),
            "total_debt_amount": round(total_debt, 2),
            "total_expected_amount": round(total_expected, 2),
            "total_final_payable_amount": round(total_final, 2),
            "discount_total": round(total_discount, 2),
            "refund_total": round(total_refund, 2),
            "overpayment_total": round(total_over, 2),
        },
        "group_comparison": group_comparison[:500],
        "teacher_comparison": teacher_comparison[:500],
        "items": filtered[:800] if include_items else [],
        "jobs": job_rows,
        "last_calc_run": next((job for job in job_rows if str(job.get("job_name") or "") == "payment_recalculation"), None),
        "last_reminder_run": next((job for job in job_rows if str(job.get("job_name") or "") == "payment_reminders_schedule"), None),
        "permission_scope": "general" if _is_general_admin_scope(admin_ref) else "limited",
    }


@app.get("/admin/payments/students")
async def admin_payments_students(
    ym: str | None = Query(default=None),
    q: str | None = Query(default=None),
    status: str | None = Query(default=None),
    subject: str | None = Query(default=None),
    teacher_name: str | None = Query(default=None),
    limit: int = Query(default=100, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    month_key = _payment_validate_ym(ym) if ym and str(ym).strip() else _payment_ym_now()
    
    # Run Recalc check
    _payment_recalc_for_view_if_stale({month_key}, trigger_source="students_list", freshness_seconds=900)
    
    # Restrict to scoped groups
    scoped_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}
    if not scoped_group_ids:
        return {"items": [], "total": 0, "page": offset // limit + 1, "pages": 0}
        
    conn = get_conn()
    cur = conn.cursor()
    
    placeholders = ", ".join(["?"] * len(scoped_group_ids))
    
    # Base query
    sql = f"""
    WITH student_aggregates AS (
        SELECT 
            o.user_id,
            SUM(o.final_amount) AS final_payable_amount,
            SUM(o.paid_amount) AS paid_amount,
            SUM(o.debt_amount) AS debt_amount,
            SUM(o.overpayment_amount) AS overpayment_amount,
            string_agg(g.name, ', ' ORDER BY g.name) AS group_names,
            CASE 
                WHEN 'kechikkan' = ANY(array_agg(LOWER(o.status))) THEN 'Kechikkan'
                WHEN 'qisman to''langan' = ANY(array_agg(LOWER(o.status))) THEN 'Qisman to''langan'
                WHEN 'to''lanmagan' = ANY(array_agg(LOWER(o.status))) THEN 'To''lanmagan'
                WHEN 'ortiqcha to''lov' = ANY(array_agg(LOWER(o.status))) THEN 'Ortiqcha to''lov'
                ELSE 'To''langan'
            END AS status
        FROM payment_monthly_obligations o
        LEFT JOIN groups g ON g.id = o.group_id
        LEFT JOIN users t ON t.id = g.teacher_id
        WHERE o.ym = ? AND o.group_id IN ({placeholders})
    """
    
    cte_where = []
    cte_params = [month_key, *sorted(list(scoped_group_ids))]
    
    if subject and str(subject).strip() and subject != "all":
        cte_where.append("LOWER(g.subject) = ?")
        cte_params.append(str(subject).strip().lower())
        
    if teacher_name and str(teacher_name).strip():
        cte_where.append("LOWER(COALESCE(t.first_name,'') || ' ' || COALESCE(t.last_name,'')) LIKE ?")
        cte_params.append(f"%{str(teacher_name).strip().lower()}%")
        
    if cte_where:
        sql += " AND " + " AND ".join(cte_where)
        
    sql += """
        GROUP BY o.user_id
    )
    SELECT 
        sa.*,
        TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')) AS full_name,
        u.phone,
        COUNT(*) OVER() AS total_count
    FROM student_aggregates sa
    LEFT JOIN users u ON u.id = sa.user_id
    """
    
    where_clauses = ["1=1"]
    params = cte_params
    
    if q and str(q).strip():
        q_norm = f"%{str(q).strip().lower()}%"
        where_clauses.append("LOWER(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'') || ' ' || COALESCE(u.phone,'')) LIKE ?")
        params.append(q_norm)
        
    if status and str(status).strip() and status != "all":
        status_val = str(status).strip().lower()
        if status_val == "to'langan":
            where_clauses.append("sa.status = 'To''langan'")
        elif status_val == "qisman to'langan":
            where_clauses.append("sa.status = 'Qisman to''langan'")
        elif status_val == "to'lanmagan":
            where_clauses.append("sa.status = 'To''lanmagan'")
        elif status_val == "kechikkan":
            where_clauses.append("sa.status = 'Kechikkan'")
        elif status_val == "ortiqcha to'lov":
            where_clauses.append("sa.status = 'Ortiqcha to''lov'")
        else:
            where_clauses.append("LOWER(sa.status) = ?")
            params.append(status_val)
            
    sql += " WHERE " + " AND ".join(where_clauses)
    sql += " ORDER BY sa.debt_amount DESC, full_name ASC LIMIT ? OFFSET ?"
    params.extend([limit, offset])
    
    cur.execute(sql, tuple(params))
    rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()
    
    total = rows[0]["total_count"] if rows else 0
    pages = (total + limit - 1) // limit
    
    for r in rows:
        r.pop("total_count", None)
        groups_str = r.get("group_names") or ""
        r["group_names"] = [g.strip() for g in groups_str.split(",") if g.strip()]
        
    return {
        "items": rows,
        "total": total,
        "page": offset // limit + 1,
        "pages": pages
    }


@app.get("/admin/payments/groups/{group_id}/students")
async def admin_payments_group_students(
    group_id: int,
    ym: str | None = Query(default=None),
    q: str | None = Query(default=None),
    status: str | None = Query(default=None),
    sort: str | None = Query(default=None),
    limit: int = Query(default=250, ge=1, le=1000),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_admin_perf_indexes()
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    # Keep this endpoint lightweight for split-view UX: avoid full month-wide recalculation here.
    # Obligations are refreshed lazily per user/group below when available.
    members = _safe_call(lambda: get_group_users(int(group_id)), []) or []
    members = [m for m in members if int(m.get("login_type") or 0) in (1, 2, 6)]
    active_member_ids = {int(m.get("id") or 0) for m in members if int(m.get("id") or 0) > 0}

    # --- Include removed students who studied during this month ---
    # Source 1: existing payment_monthly_obligations (most reliable)
    # Source 2: user_group_membership_log (catches students not yet obligated)
    month_start_dt, month_end_dt = _payment_month_date_bounds(month_key)
    month_start_iso = month_start_dt.strftime("%Y-%m-%d %H:%M:%S")
    month_end_iso = month_end_dt.strftime("%Y-%m-%d %H:%M:%S")
    removed_ids: set[int] = set()
    try:
        _conn_hist = get_conn()
        _cur_hist = _conn_hist.cursor()
        # Source 1: obligation-based
        _cur_hist.execute(
            "SELECT DISTINCT user_id FROM payment_monthly_obligations WHERE group_id=? AND ym=?",
            (int(group_id), str(month_key)),
        )
        for _row in (_cur_hist.fetchall() or []):
            _uid = int((dict(_row) if isinstance(_row, dict) else {"user_id": _row[0]}).get("user_id") or 0)
            if _uid > 0 and _uid not in active_member_ids:
                removed_ids.add(_uid)
        # Source 2: membership_log-based (joined before month_end, left during or after month_start)
        try:
            _cur_hist.execute(
                """
                SELECT DISTINCT user_id
                FROM user_group_membership_log
                WHERE group_id=?
                  AND joined_at <= ?
                  AND left_at IS NOT NULL
                  AND left_at >= ?
                  AND COALESCE(active, 0) = 0
                """,
                (int(group_id), month_end_iso, month_start_iso),
            )
            for _row in (_cur_hist.fetchall() or []):
                _uid = int((dict(_row) if isinstance(_row, dict) else {"user_id": _row[0]}).get("user_id") or 0)
                if _uid > 0 and _uid not in active_member_ids:
                    removed_ids.add(_uid)
        except Exception:
            pass
        _conn_hist.close()
    except Exception:
        removed_ids = set()

    # Load full user rows for removed students and append to members
    if removed_ids:
        try:
            _conn_r = get_conn()
            _cur_r = _conn_r.cursor()
            _ph_r = ", ".join(["?"] * len(removed_ids))
            _cur_r.execute(f"SELECT * FROM users WHERE id IN ({_ph_r})", tuple(removed_ids))
            for _rr in (_cur_r.fetchall() or []):
                _rr_dict = dict(_rr)
                if int(_rr_dict.get("login_type") or 0) in (1, 2, 6):
                    members.append(_rr_dict)
            _conn_r.close()
        except Exception:
            pass
    # --- end removed student inclusion ---
    members = _enrich_user_rows_with_face_profiles(members)

    user_ids = [int(m.get("id") or 0) for m in members if int(m.get("id") or 0) > 0]
    obligation_map: dict[int, dict[str, Any]] = {}
    if user_ids:
        conn = get_conn()
        cur = conn.cursor()
        placeholders = ", ".join(["?"] * len(user_ids))
        cur.execute(
            f"""
            SELECT *
            FROM payment_monthly_obligations
            WHERE group_id=?
              AND ym=?
              AND user_id IN ({placeholders})
            """,
            tuple([int(group_id), str(month_key), *user_ids]),
        )
        for row in (cur.fetchall() or []):
            item = dict(row)
            obligation_map[int(item.get("user_id") or 0)] = item
        cur.execute(
            f"""
            SELECT user_id, MAX(created_at) AS last_payment_at
            FROM payment_transactions
            WHERE group_id=?
              AND user_id IN ({placeholders})
            GROUP BY user_id
            """,
            tuple([int(group_id), *user_ids]),
        )
        last_paid_map = {int((row or {}).get("user_id") or 0): (row or {}).get("last_payment_at") for row in (cur.fetchall() or [])}
        conn.close()
    else:
        last_paid_map = {}

    # Preload shared data once to keep selected-group loading fast.
    group_row = group
    teacher_row = _safe_call(lambda: get_user_by_id(int(group_row.get("teacher_id") or 0)), None) if group_row else None
    lesson_dates = _payment_lesson_dates_for_group_month(group_row, month_key) if group_row else []
    discount_cache: dict[int, dict[str, Any]] = {}

    rows: list[dict[str, Any]] = []
    for member in members:
        uid = int(member.get("id") or 0)
        if uid <= 0:
            continue
        obligation = obligation_map.get(uid)
        if not obligation:
            # Fast fallback without DB upsert to avoid slow first-open timeouts.
            if uid not in discount_cache:
                discount_cache[uid] = _payment_discount_info_for_student(member, ym=month_key)
            calc = _calculate_monthly_payment_for_student_group(
                uid,
                int(group_id),
                month_key,
                student_row=member,
                group_row=group_row,
                lesson_dates=lesson_dates,
                teacher_row=teacher_row,
                discount_info=discount_cache.get(uid),
            ) or {}
            calc_final = float(calc.get("final_payable_amount") or calc.get("calculated_amount") or 0.0)
            calc_paid = 0.0
            calc_debt = max(0.0, calc_final - calc_paid)
            calc_over = max(0.0, calc_paid - calc_final)
            obligation = {
                "final_amount": float(calc_final),
                "paid_amount": float(calc_paid),
                "debt_amount": float(calc_debt),
                "overpayment_amount": float(calc_over),
                "status": _payment_status_label(calc_final, calc_paid, month_key),
            }
        row_status = str(obligation.get("status") or PAYMENT_STATUS_UNPAID)
        row = {
            "id": uid,
            "full_name": _display_name(member),
            "avatar_url": (
                str(member.get("profile_image_url") or "").strip()
                or str(member.get("effective_profile_image_url") or "").strip()
                or str(member.get("face_reference_image_url") or "").strip()
                or None
            ),
            "profile_image_url": (
                str(member.get("profile_image_url") or "").strip()
                or str(member.get("effective_profile_image_url") or "").strip()
                or str(member.get("face_reference_image_url") or "").strip()
                or None
            ),
            "phone": str(member.get("phone") or "").strip(),
            "login_type": int(member.get("login_type") or 0),
            "account_type": "accountless" if int(member.get("login_type") or 0) == 6 else "student",
            "is_accountless": bool(int(member.get("login_type") or 0) == 6),
            "is_removed": uid in removed_ids,
            "group_id": int(group_id),
            "ym": str(month_key),
            "status": row_status,
            "payment_status": row_status,
            "final_payable_amount": round(float(obligation.get("final_amount") or 0.0), 2),
            "paid_amount": round(float(obligation.get("paid_amount") or 0.0), 2),
            "debt_amount": round(float(obligation.get("debt_amount") or 0.0), 2),
            "overpayment_amount": round(float(obligation.get("overpayment_amount") or 0.0), 2),
            "last_payment_at": last_paid_map.get(uid),
        }
        rows.append(row)

    q_norm = str(q or "").strip().lower()
    if q_norm:
        rows = [
            row
            for row in rows
            if q_norm in f"{str(row.get('full_name') or '').lower()} {str(row.get('phone') or '').lower()}"
        ]
    status_norm = str(status or "").strip().lower()
    if status_norm and status_norm != "all":
        rows = [row for row in rows if status_norm in str(row.get("status") or "").strip().lower()]

    status_rank = {
        "kechikkan": 1,
        "to'lanmagan": 2,
        "qisman to'langan": 3,
        "to'langan": 4,
        "ortiqcha to'lov": 5,
    }
    sort_key = str(sort or "debt_desc").strip().lower()
    if sort_key == "name":
        rows.sort(key=lambda row: str(row.get("full_name") or "").lower())
    elif sort_key == "status":
        rows.sort(
            key=lambda row: (
                status_rank.get(str(row.get("status") or "").strip().lower(), 99),
                str(row.get("full_name") or "").lower(),
            )
        )
    elif sort_key == "last_payment":
        rows.sort(key=lambda row: str(row.get("last_payment_at") or ""), reverse=True)
    else:
        rows.sort(
            key=lambda row: (
                float(row.get("debt_amount") or 0.0),
                str(row.get("full_name") or "").lower(),
            ),
            reverse=True,
        )

    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 150:
        logger.info(
            "perf payments.group_students group_id=%s ym=%s total_ms=%.2f rows=%s removed=%s",
            int(group_id),
            str(month_key),
            elapsed_ms,
            len(rows),
            len(removed_ids),
        )
    return {
        "group_id": int(group_id),
        "ym": str(month_key),
        "items": rows[: int(limit)],
    }


@app.post("/admin/payments/export")
async def admin_payments_export_post(payload: PaymentExportRequest | None = None, authorization: str | None = Header(default=None)):
    _require_payment_extra_feature("payments export")
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    safe_payload = payload or PaymentExportRequest()
    from_day = _payment_validate_optional_iso_date(safe_payload.date_from, field_name="date_from")
    to_day = _payment_validate_optional_iso_date(safe_payload.date_to, field_name="date_to")
    if from_day and to_day and from_day > to_day:
        raise HTTPException(status_code=400, detail="date_from must be before date_to")
    if int(safe_payload.group_id or 0) > 0:
        target_group = _safe_call(lambda gid=int(safe_payload.group_id): get_group(gid), None)
        if not _can_manage_group(admin_ref, target_group):
            raise HTTPException(status_code=403, detail="Permission denied")
    scoped_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}
    filters = _payment_export_scope_filters(payload=safe_payload)
    bio, filename = export_payment_history_to_xlsx(
        owner_admin_id=(None if _is_general_admin_scope(admin_ref) else int(admin_ref)),
        filters=filters,
        scoped_group_ids=scoped_group_ids,
    )
    logger.info(
        "payment_export_downloaded admin_ref_id=%s scope=%s months=%s group_id=%s",
        int(admin_ref),
        "general" if _is_general_admin_scope(admin_ref) else "limited",
        int(filters.get("months") or 0),
        int(filters.get("group_id") or 0) if filters.get("group_id") else 0,
    )
    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return StreamingResponse(bio, media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers=headers)


@app.get("/admin/payments/jobs")
async def admin_payments_jobs(
    limit: int = Query(default=50, ge=1, le=250),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_payment_automation_schema()
    today_iso = _now_tashkent_date()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT *
        FROM payment_job_runs
        ORDER BY started_at DESC, id DESC
        LIMIT ?
        """,
        (int(limit),),
    )
    items = [dict(row) for row in (cur.fetchall() or [])]
    cur.execute(
        """
        SELECT
            channel,
            status,
            COUNT(*) AS c
        FROM payment_reminder_dispatch_log
        WHERE dispatch_day=?
        GROUP BY channel, status
        """,
        (today_iso,),
    )
    reminder_rows = [dict(row) for row in (cur.fetchall() or [])]
    conn.close()
    failed_recent = [row for row in items if str(row.get("status") or "").lower() == "failed"]
    reminder_summary: dict[str, dict[str, int]] = {
        "website": {"sent": 0, "failed": 0, "skipped": 0},
        "telegram": {"sent": 0, "failed": 0, "skipped": 0},
    }
    for row in reminder_rows:
        ch = str(row.get("channel") or "").strip().lower()
        st = str(row.get("status") or "").strip().lower()
        cnt = int(row.get("c") or 0)
        if ch in reminder_summary and st in reminder_summary[ch]:
            reminder_summary[ch][st] = cnt
    summary = {
        "total": len(items),
        "failed_count": len(failed_recent),
        "last_failed": failed_recent[0] if failed_recent else None,
        "last_calc": next((row for row in items if str(row.get("job_name") or "") == "payment_recalculation"), None),
        "last_reminder": next((row for row in items if str(row.get("job_name") or "") == "payment_reminders_schedule"), None),
        "warning": "Recent payment jobs contain failures" if failed_recent else None,
        "dispatch_day": today_iso,
        "reminder_dispatch": reminder_summary,
    }
    return {"items": items, "summary": summary}


@app.get("/admin/payments/students/{user_id}/detail")
async def admin_payments_student_detail(
    user_id: int,
    ym: str | None = Query(default=None),
    include_history: bool = Query(default=True),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    limited_scope = _is_limited_admin(admin_ref) and not _is_main_admin(admin_ref)
    scope_started_at = time.perf_counter()
    allowed_group_ids: set[int] = set()
    if limited_scope:
        allowed_group_ids = {int(g.get("id") or 0) for g in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or [])}
    has_any_group = True
    if bool(include_history):
        target_groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
        has_any_group = bool(target_groups)
    scope_elapsed_ms = (time.perf_counter() - scope_started_at) * 1000.0
    current_ym = _payment_ym_now()
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else current_ym
    overview_started_at = time.perf_counter()
    # Keep detail responsive:
    # - lightweight mode returns only current month overview for dashboards/modals;
    # - full mode keeps detailed history for dedicated payment detail page.
    overview = _payment_student_overview(
        target,
        ym=month_key,
        months_back=1 if not include_history else 6,
        include_history=bool(include_history),
    )
    overview_elapsed_ms = (time.perf_counter() - overview_started_at) * 1000.0
    if not bool(include_history):
        has_any_group = bool((overview.get("current_month") or {}).get("items"))
    if limited_scope:
        overview = _payment_filter_overview_by_group_scope(overview, allowed_group_ids)
    _ensure_payment_automation_schema()
    unpaid_scan_started_at = time.perf_counter()
    oldest_unpaid_rows: list[dict[str, Any]] = []
    if bool(include_history):
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            """
            SELECT ym, group_id
            FROM payment_monthly_obligations
            WHERE user_id=?
              AND COALESCE(debt_amount, 0) > 0
            ORDER BY ym ASC
            """,
            (int(user_id),),
        )
        oldest_unpaid_rows = [dict(row) for row in (cur.fetchall() or [])]
        conn.close()
    unpaid_scan_elapsed_ms = (time.perf_counter() - unpaid_scan_started_at) * 1000.0
    default_ym = month_key if not bool(include_history) else current_ym
    if bool(include_history):
        for row in oldest_unpaid_rows:
            gid = int(row.get("group_id") or 0)
            if limited_scope and gid > 0 and gid not in allowed_group_ids:
                continue
            default_ym = str(row.get("ym") or current_ym)
            break
        if limited_scope:
            for month in (overview.get("months") or []):
                if float(month.get("total_debt_amount") or 0.0) > 1e-9:
                    default_ym = str(month.get("ym") or default_ym)
                    break
    total_elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    log_fn = logger.info if total_elapsed_ms > 500 else logger.debug
    log_fn(
        "payment_detail_timing user_id=%s admin_ref_id=%s include_history=%s month=%s scope_ms=%.2f overview_ms=%.2f unpaid_scan_ms=%.2f total_ms=%.2f",
        int(user_id),
        int(admin_ref),
        bool(include_history),
        month_key,
        float(scope_elapsed_ms),
        float(overview_elapsed_ms),
        float(unpaid_scan_elapsed_ms),
        float(total_elapsed_ms),
    )
    return {
        "user": _serialize_user_row(target),
        "default_ym": default_ym,
        "referral_status": overview.get("referral_status"),
        "overview": overview,
        "has_group": bool(has_any_group),
        "no_group_message": "Student hech qaysi guruhga biriktirilmagan" if not has_any_group else None,
        "permission_scope": "general" if _is_general_admin_scope(admin_ref) else "limited",
    }


@app.get("/admin/payments/students/{user_id}/penalty-preview")
async def admin_payments_penalty_preview(
    user_id: int,
    group_id: int = Query(..., ge=1),
    ym: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
    group = next((g for g in groups if int(g.get("id") or 0) == int(group_id)), None)
    if not group:
        # Student may have been removed — allow if obligation exists for this group
        _grp_d = _safe_call(lambda: get_group(int(group_id)), None)
        if _grp_d:
            _conn_obl = get_conn()
            _cur_obl = _conn_obl.cursor()
            _cur_obl.execute(
                "SELECT id FROM payment_monthly_obligations WHERE user_id=? AND group_id=? LIMIT 1",
                (int(user_id), int(group_id)),
            )
            if _cur_obl.fetchone():
                group = _grp_d
            _conn_obl.close()
    if not group:
        raise HTTPException(status_code=404, detail="Group not found for this user")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    _payment_upsert_obligation(target, group, month_key)
    preview = _payment_penalty_preview(user_row=target, group_id=int(group_id), ym=month_key)
    preview.update(
        {
            "user_id": int(user_id),
            "group_id": int(group_id),
            "ym": month_key,
        }
    )
    return preview


@app.post("/admin/payments/students/{user_id}/confirm")
async def admin_payments_student_confirm(
    user_id: int,
    payload: PaymentConfirmRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    month_key = _payment_validate_ym(payload.ym)
    amount = _payment_require_positive_amount(payload.amount, field_name="amount")
    payment_method = str(payload.payment_method or "cash").strip().lower()
    if payment_method not in {"cash", "card"}:
        raise HTTPException(status_code=400, detail="Invalid payment method")
    clean_note = str(payload.note or "").strip()
    if len(clean_note) > 1000:
        raise HTTPException(status_code=400, detail="note is too long")
    groups = _safe_call(lambda: get_user_groups(int(user_id)), []) or []
    group = next((g for g in groups if int(g.get("id") or 0) == int(payload.group_id)), None)
    if not group:
        # Removed student: allow payment confirmation if obligation exists
        _grp_d = _safe_call(lambda: get_group(int(payload.group_id)), None)
        if _grp_d:
            _conn_obl = get_conn()
            _cur_obl = _conn_obl.cursor()
            _cur_obl.execute(
                "SELECT id FROM payment_monthly_obligations WHERE user_id=? AND group_id=? LIMIT 1",
                (int(user_id), int(payload.group_id)),
            )
            if _cur_obl.fetchone():
                group = _grp_d
            _conn_obl.close()
    if not group:
        raise HTTPException(status_code=404, detail="Group not found for this user")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    selected_card_id = int(payload.card_id or 0)
    selected_card_row: dict[str, Any] | None = None
    if payment_method == "card":
        cards = _payment_card_rows(active_only=True)
        if not cards:
            raise HTTPException(status_code=400, detail="No active payment cards available")
        if selected_card_id > 0:
            selected_card_row = next((row for row in cards if int(row.get("id") or 0) == selected_card_id), None)
            if not selected_card_row:
                raise HTTPException(status_code=400, detail="Selected payment card is invalid")
        else:
            selected_card_row = next((row for row in cards if bool(int(row.get("is_default") or 0) == 1)), cards[0] if cards else None)
            selected_card_id = int((selected_card_row or {}).get("id") or 0)
    else:
        selected_card_id = 0
    obligation = _payment_upsert_obligation(target, group, month_key)
    obligation_id = int(obligation.get("id") or 0)
    if obligation_id <= 0:
        raise HTTPException(status_code=500, detail="Could not resolve payment obligation")
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("BEGIN")
    status = PAYMENT_STATUS_UNPAID
    final_amount = 0.0
    paid_total_amount = 0.0
    remaining = 0.0
    overpayment = 0.0
    discount_type = "none"
    discount_percent = 0.0
    discount_amount = 0.0
    penalty_applied = False
    penalty_percent = 0.0
    penalty_amount = 0.0
    dcoin_before_penalty = 0.0
    dcoin_after_penalty = 0.0
    bonus_events: list[dict[str, Any]] = []
    referral_event: dict[str, Any] = {"applied": False}
    group_name = str(group.get("name") or "").strip() or f"Group #{int(payload.group_id)}"
    course_title = str(obligation.get("course_title") or group.get("course_title") or "").strip() or None
    try:
        # Guard against accidental duplicate submissions within a short window.
        cur.execute(
            """
            SELECT id, created_at
            FROM payment_transactions
            WHERE obligation_id=?
              AND user_id=?
              AND group_id=?
              AND ym=?
              AND amount=?
              AND payment_method=?
              AND COALESCE(note, '')=?
              AND confirmed_by_admin_id=?
            ORDER BY id DESC
            LIMIT 1
            """,
            (
                int(obligation_id),
                int(user_id),
                int(payload.group_id),
                month_key,
                float(amount),
                payment_method,
                clean_note,
                int(user.get("id") or 0),
            ),
        )
        last_same = dict(cur.fetchone() or {})
        if last_same:
            created_at = _parse_utc_timestamp(str(last_same.get("created_at") or ""))
            if created_at and (_now_utc() - created_at).total_seconds() <= 20:
                raise HTTPException(status_code=409, detail="Duplicate payment submission detected")

        cur.execute(
            """
            INSERT INTO payment_transactions
            (
                obligation_id, user_id, group_id, ym, amount, payment_method, card_id, note, is_advance,
                confirmed_by_admin_id, confirmed_by_admin_name, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            (
                obligation_id,
                int(user_id),
                int(payload.group_id),
                month_key,
                float(amount),
                payment_method,
                int(selected_card_id) if int(selected_card_id) > 0 else None,
                (clean_note or None),
                1 if bool(payload.is_advance) else 0,
                int(user.get("id") or 0),
                _display_name(user),
            ),
        )
        tx_id = int(getattr(cur, "lastrowid", 0) or 0)
        if tx_id <= 0:
            cur.execute("SELECT id FROM payment_transactions ORDER BY id DESC LIMIT 1")
            tx_id = int((cur.fetchone() or {}).get("id") or 0)
        cur.execute(
            """
            UPDATE payment_monthly_obligations
            SET paid_amount=COALESCE(paid_amount,0)+?,
                last_paid_at=CURRENT_TIMESTAMP,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (float(amount), obligation_id),
        )
        updated_obligation = _payment_update_obligation_after_amount_change(conn, cur, obligation_id)
        final_amount = float(updated_obligation.get("final_amount") or 0.0)
        paid_amount = float(updated_obligation.get("paid_amount") or 0.0)
        paid_total_amount = float(paid_amount)
        status = str(updated_obligation.get("status") or PAYMENT_STATUS_UNPAID)
        remaining = max(0.0, final_amount - paid_amount)
        overpayment = max(0.0, paid_amount - final_amount)
        discount_type = str(updated_obligation.get("discount_type") or "none")
        discount_percent = float(updated_obligation.get("discount_percent") or 0.0)
        discount_amount = float(updated_obligation.get("discount_amount") or 0.0)
        course_title = str(updated_obligation.get("course_title") or course_title or "").strip() or None
        cur.execute(
            """
            UPDATE payment_transactions
            SET status_after=?,
                remaining_after=?,
                overpayment_after=?
            WHERE id=?
            """,
            (status, float(remaining), float(overpayment), tx_id),
        )
        is_accountless = int(target.get("login_type") or 0) == 6
        # Overdue penalty (once per month/group, only when confirming a payment for overdue obligation).
        if not is_accountless and status in {PAYMENT_STATUS_PARTIAL, PAYMENT_STATUS_PAID, PAYMENT_STATUS_OVERPAY} and int(updated_obligation.get("overdue") or 0) == 1:
            cur.execute(
                """
                SELECT 1
                FROM payment_penalty_log
                WHERE user_id=? AND group_id=? AND ym=? AND penalty_type='overdue_confirm'
                LIMIT 1
                """,
                (int(user_id), int(payload.group_id), month_key),
            )
            has_penalty = cur.fetchone() is not None
            if not has_penalty:
                settings = _get_runtime_settings()
                penalty_percent = max(0.0, float(settings.get("payment_overdue_penalty_dcoin_percent") or 5.0))
                dcoin_before_penalty = _payment_total_dcoin_balance(int(user_id))
                penalty_amount = round(max(0.0, dcoin_before_penalty * (penalty_percent / 100.0)), 2)
                penalty_applied = False
                dcoin_after_penalty = dcoin_before_penalty
                if penalty_amount > 0:
                    subject = (_user_subjects_from_row(target) or ["English"])[0]
                    penalty_applied = add_dcoins_tx(
                        cur,
                        int(user_id),
                        -float(penalty_amount),
                        subject=subject,
                        change_type="payment_overdue_confirm_penalty",
                    )
                    if not penalty_applied:
                        raise RuntimeError(f"payment_overdue_penalty_wallet_update_failed user_id={int(user_id)}")
                    dcoin_after_penalty = round(dcoin_before_penalty - penalty_amount, 2) if penalty_applied else dcoin_before_penalty
                cur.execute(
                    """
                    INSERT INTO payment_penalty_log(user_id, group_id, ym, penalty_type, amount, source_transaction_id, created_at)
                    VALUES (?, ?, ?, 'overdue_confirm', ?, ?, CURRENT_TIMESTAMP)
                    """,
                    (int(user_id), int(payload.group_id), month_key, -float(penalty_amount if penalty_applied else 0.0), int(tx_id)),
                )
                cur.execute(
                    """
                    UPDATE payment_penalty_log
                    SET meta_json=?
                    WHERE user_id=? AND group_id=? AND ym=? AND penalty_type='overdue_confirm'
                    """,
                    (
                        json.dumps(
                            {
                                "penalty_percent": float(penalty_percent),
                                "dcoin_before": float(dcoin_before_penalty),
                                "dcoin_after": float(dcoin_after_penalty),
                                "admin_id": int(user.get("id") or 0),
                                "admin_name": _display_name(user),
                                "reason": "overdue payment confirmed",
                            },
                            ensure_ascii=False,
                        ),
                        int(user_id),
                        int(payload.group_id),
                        month_key,
                    ),
                )

        # D'point rewards (full close + next-month advance full close), duplicate-safe.
        if not is_accountless and remaining <= 1e-9 and final_amount > 0:
            monthly_amount = float(_payment_day_bonus_amount(month_key))
            monthly_event = _payment_apply_dpoint_bonus_for_transaction(
                conn,
                cur,
                user_row=target,
                user_id=int(user_id),
                group_id=int(payload.group_id),
                ym=month_key,
                bonus_type="full_month_payment",
                amount=monthly_amount,
                source_transaction_id=int(tx_id),
                source_label="full_month_payment",
            )
            bonus_events.append(monthly_event)
            tz = pytz.timezone("Asia/Tashkent")
            now_date = datetime.now(tz).date()
            current_ym = _payment_ym_now()
            target_month_start, _ = _payment_month_date_bounds(month_key)
            is_next_month_advance = month_key == _payment_next_ym(current_ym) and now_date < target_month_start.date()
            if is_next_month_advance:
                advance_amount = float(_get_runtime_settings().get("payment_advance_full_bonus_dpoints") or 200.0)
                advance_event = _payment_apply_dpoint_bonus_for_transaction(
                    conn,
                    cur,
                    user_row=target,
                    user_id=int(user_id),
                    group_id=int(payload.group_id),
                    ym=month_key,
                    bonus_type="next_month_advance_payment",
                    amount=advance_amount,
                    source_transaction_id=int(tx_id),
                    source_label="next_month_advance_payment",
                )
                bonus_events.append(advance_event)

        # Referral bonus on first payment (once per referred student), also handles accountless referrer pending.
        referral_event = _payment_apply_referral_bonus_if_needed(conn, cur, target, source_transaction_id=tx_id)

        if not is_accountless:
            _payment_store_confirmation_notification(
                cur,
                user_id=int(user_id),
                payment_transaction_id=int(tx_id),
                ym=month_key,
                amount=float(amount),
                status=str(status),
                remaining=float(remaining),
                overpayment=float(overpayment),
                payment_method=payment_method,
                note=(clean_note or None),
                group_name=group_name,
                course_title=course_title,
                bonus_events=bonus_events,
            )

        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    for ym_key in {month_key, _prev_month_ym(month_key), _payment_next_ym(month_key)}:
        _STUDENT_PAYMENT_ME_CACHE.pop((int(user_id), ym_key), None)
        _payment_recalculate_user_month(target, ym_key)
    if float(overpayment) > 1e-9:
        next_ym = _payment_next_ym(month_key)
        next_obligation = _payment_upsert_obligation(target, group, next_ym)
        if next_obligation:
            _payment_apply_carry_forward_for_obligation(next_obligation)
    if int(target.get("login_type") or 0) in (1, 2):
        try:
            await _payment_send_confirmation_telegram(
                target,
                ym=month_key,
                amount=float(amount),
                status=str(status),
                remaining=float(remaining),
                overpayment=float(overpayment),
                payment_method=payment_method,
                note=(clean_note or None),
                group_name=group_name,
                course_title=course_title,
                bonus_events=bonus_events,
            )
        except Exception:
            logger.exception("payment confirmation telegram notification failed user_id=%s tx_id=%s", int(user_id), int(tx_id))
        try:
            userbot_manager.handle_userbot_payment_received_event(
                student_id=int(user_id),
                amount=float(amount),
                ym=str(month_key),
                payment_method=str(payment_method)
            )
        except Exception:
            logger.exception("userbot payment received trigger failed")
    return {
        "message": "Payment confirmed",
        "transaction_id": int(tx_id),
        "status": str(status),
        "final_amount": float(final_amount),
        "paid_amount": float(paid_total_amount),
        "debt_amount": float(remaining),
        "overpayment_amount": float(overpayment),
        "discount_type": discount_type,
        "discount_percent": float(discount_percent),
        "discount_amount": float(discount_amount),
        "penalty_applied": bool(penalty_applied),
        "penalty_percent": float(penalty_percent),
        "penalty_amount": float(penalty_amount if penalty_applied else 0.0),
        "dcoin_before_penalty": float(dcoin_before_penalty if penalty_applied else 0.0),
        "dcoin_after_penalty": float(dcoin_after_penalty if penalty_applied else 0.0),
        "card_id": int(selected_card_id) if int(selected_card_id) > 0 else None,
        "card_owner_name": (
            f"{str((selected_card_row or {}).get('owner_first_name') or '').strip()} {str((selected_card_row or {}).get('owner_last_name') or '').strip()}".strip()
            if selected_card_row
            else None
        ),
        "card_number_masked": (
            next(
                (
                    card.get("card_number_masked")
                    for card in _payment_cards_public_payload()
                    if int(card.get("id") or 0) == int(selected_card_id)
                ),
                None,
            )
            if int(selected_card_id) > 0
            else None
        ),
        "bonus_events": bonus_events,
        "referral_event": referral_event,
        "detail": _payment_student_overview(target, ym=month_key, months_back=1, include_history=False),
    }


@app.post("/admin/payments/transactions/{transaction_id}/refund")
async def admin_payments_refund_transaction(
    transaction_id: int,
    payload: PaymentRefundRequest,
    authorization: str | None = Header(default=None),
):
    _require_payment_part4_feature("payment refund")
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    amount = _payment_require_positive_amount(payload.amount, field_name="amount")
    note = str(payload.note or "").strip()
    if not note:
        raise HTTPException(status_code=400, detail="Refund note is required")
    if len(note) > 1000:
        raise HTTPException(status_code=400, detail="Refund note is too long")
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM payment_transactions WHERE id=? LIMIT 1", (int(transaction_id),))
    tx = dict(cur.fetchone() or {})
    if not tx:
        conn.close()
        raise HTTPException(status_code=404, detail="Transaction not found")
    user_id = int(tx.get("user_id") or 0)
    target = _safe_call(lambda: get_user_by_id(user_id), None)
    admin_ref = _admin_ref_id(user)
    if not _can_manage_user_globally(admin_ref, target):
        conn.close()
        raise HTTPException(status_code=403, detail="Permission denied")
    group_row = _safe_call(lambda: get_group(int(tx.get("group_id") or 0)), None)
    if not _can_manage_group(admin_ref, group_row):
        conn.close()
        raise HTTPException(status_code=403, detail="Permission denied")
    refundable = float(tx.get("amount") or 0.0) - float(tx.get("refunded_amount") or 0.0)
    if amount - refundable > 1e-9:
        conn.close()
        raise HTTPException(status_code=400, detail="Refund amount exceeds refundable balance")
    obligation_id = int(tx.get("obligation_id") or 0)
    if obligation_id <= 0:
        conn.close()
        raise HTTPException(status_code=400, detail="Transaction has no obligation link")
    cur.execute("SELECT * FROM payment_monthly_obligations WHERE id=? LIMIT 1", (obligation_id,))
    obligation_before = dict(cur.fetchone() or {})
    status_before = str(obligation_before.get("status") or PAYMENT_STATUS_UNPAID)
    previous_overpayment_amount = float(obligation_before.get("overpayment_amount") or 0.0)
    cur.execute(
        """
        SELECT id, created_at
        FROM payment_refunds
        WHERE transaction_id=?
          AND amount=?
          AND note=?
          AND refunded_by_admin_id=?
        ORDER BY id DESC
        LIMIT 1
        """,
        (int(transaction_id), float(amount), note[:1000], int(user.get("id") or 0)),
    )
    last_same = dict(cur.fetchone() or {})
    if last_same:
        created_at = _parse_utc_timestamp(str(last_same.get("created_at") or ""))
        if created_at and (_now_utc() - created_at).total_seconds() <= 20:
            conn.close()
            raise HTTPException(status_code=409, detail="Duplicate refund submission detected")
    refund_type = "full" if abs(amount - refundable) <= 1e-9 else "partial"
    cur.execute("BEGIN")
    status_after_refund = PAYMENT_STATUS_UNPAID
    final_after_refund = 0.0
    paid_after_refund = 0.0
    debt_after_refund = 0.0
    overpayment_after_refund = 0.0
    discount_type_after_refund = "none"
    discount_percent_after_refund = 0.0
    discount_amount_after_refund = 0.0
    refund_id = 0
    bonus_reversals: list[dict[str, Any]] = []
    reversed_full_bonus = 0.0
    reversed_advance_bonus = 0.0
    try:
        cur.execute(
            """
            INSERT INTO payment_refunds
            (
                transaction_id, obligation_id, user_id, group_id, ym, amount, note,
                refund_type, status_before, previous_overpayment_amount,
                refunded_by_admin_id, refunded_by_admin_name, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            (
                int(transaction_id),
                obligation_id,
                int(tx.get("user_id") or 0),
                int(tx.get("group_id") or 0),
                str(tx.get("ym") or ""),
                float(amount),
                note[:1000],
                refund_type,
                status_before,
                float(previous_overpayment_amount),
                int(user.get("id") or 0),
                _display_name(user),
            ),
        )
        refund_id = int(getattr(cur, "lastrowid", 0) or 0)
        cur.execute(
            """
            UPDATE payment_transactions
            SET refunded_amount=COALESCE(refunded_amount,0)+?
            WHERE id=?
            """,
            (float(amount), int(transaction_id)),
        )
        cur.execute(
            """
            UPDATE payment_monthly_obligations
            SET paid_amount=GREATEST(0, COALESCE(paid_amount,0)-?),
                last_refund_at=CURRENT_TIMESTAMP,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=?
            """,
            (float(amount), obligation_id),
        )
        updated_obligation = _payment_update_obligation_after_amount_change(conn, cur, obligation_id)
        status_after_refund = str(updated_obligation.get("status") or PAYMENT_STATUS_UNPAID)
        final_after_refund = float(updated_obligation.get("final_amount") or 0.0)
        paid_after_refund = float(updated_obligation.get("paid_amount") or 0.0)
        debt_after_refund = float(updated_obligation.get("debt_amount") or 0.0)
        overpayment_after_refund = float(updated_obligation.get("overpayment_amount") or 0.0)
        discount_type_after_refund = str(updated_obligation.get("discount_type") or "none")
        discount_percent_after_refund = float(updated_obligation.get("discount_percent") or 0.0)
        discount_amount_after_refund = float(updated_obligation.get("discount_amount") or 0.0)
        ym = str(updated_obligation.get("ym") or tx.get("ym") or "")
        gid = int(updated_obligation.get("group_id") or tx.get("group_id") or 0)
        _payment_reconcile_carry_forward_after_source_change(
            conn,
            cur,
            user_id=int(user_id),
            group_id=int(gid),
            source_ym=str(ym),
        )
        # Reverse full/advance D'point bonuses only when month is no longer fully paid.
        if float(debt_after_refund) > 1e-9:
            bonus_reversals = _payment_reverse_dpoint_bonus_for_refund(
                conn,
                cur,
                user_row=target or {},
                user_id=int(user_id),
                group_id=int(gid),
                ym=str(ym),
                source_refund_id=int(refund_id or 0),
            )
        reversed_full_bonus = round(
            sum(
                float(item.get("amount") or 0.0)
                for item in bonus_reversals
                if str(item.get("bonus_type") or "") == "full_month_payment"
            ),
            2,
        )
        reversed_advance_bonus = round(
            sum(
                float(item.get("amount") or 0.0)
                for item in bonus_reversals
                if str(item.get("bonus_type") or "") == "next_month_advance_payment"
            ),
            2,
        )
        if int((target or {}).get("login_type") or 0) in (1, 2):
            _payment_store_refund_notification(
                cur,
                user_id=int(user_id),
                payment_refund_id=int(refund_id or 0),
                transaction_id=int(transaction_id),
                ym=str(ym),
                amount=float(amount),
                status=str(status_after_refund),
                debt=float(debt_after_refund),
                overpayment=float(overpayment_after_refund),
                note=note,
                reversed_full_bonus=float(reversed_full_bonus),
                reversed_advance_bonus=float(reversed_advance_bonus),
            )
        cur.execute(
            """
            UPDATE payment_refunds
            SET status_after=?,
                debt_after=?,
                overpayment_after=?
            WHERE id=?
            """,
            (
                status_after_refund,
                float(debt_after_refund),
                float(overpayment_after_refund),
                int(refund_id),
            ),
        )
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    refreshed_target = _safe_call(lambda: get_user_by_id(int(user_id)), None) or target
    recalc_ym = str(tx.get("ym") or _payment_ym_now())
    for ym_key in {recalc_ym, _prev_month_ym(recalc_ym), _payment_next_ym(recalc_ym)}:
        _STUDENT_PAYMENT_ME_CACHE.pop((int(user_id), ym_key), None)
        _payment_recalculate_user_month(refreshed_target, ym_key)
    if int((refreshed_target or {}).get("login_type") or 0) in (1, 2):
        try:
            await _payment_send_refund_telegram(
                refreshed_target,
                ym=recalc_ym,
                amount=float(amount),
                status=str(status_after_refund),
                debt=float(debt_after_refund),
                overpayment=float(overpayment_after_refund),
                note=note,
                reversed_full_bonus=float(reversed_full_bonus),
                reversed_advance_bonus=float(reversed_advance_bonus),
            )
        except Exception:
            logger.exception("payment refund telegram notification failed user_id=%s refund_id=%s", int(user_id), int(refund_id or 0))
    return {
        "message": "Refund completed",
        "transaction_id": int(transaction_id),
        "refund_id": int(refund_id),
        "refund_type": refund_type,
        "user_id": int(user_id),
        "status_before": status_before,
        "status": status_after_refund,
        "final_amount": final_after_refund,
        "paid_amount": paid_after_refund,
        "debt_amount": debt_after_refund,
        "overpayment_amount": overpayment_after_refund,
        "discount_type": discount_type_after_refund,
        "discount_percent": discount_percent_after_refund,
        "discount_amount": discount_amount_after_refund,
        "bonus_reversals": bonus_reversals,
        "detail": _payment_student_overview(refreshed_target, ym=str(tx.get("ym") or _payment_ym_now()), months_back=1, include_history=False),
    }


@app.get("/admin/payments/methods")
async def admin_payment_methods_get(authorization: str | None = Header(default=None)):
    _require_payment_part4_feature("payment methods")
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    rows = _payment_card_rows(active_only=False)
