        public_rows = _payment_cards_public_payload()
        public_by_id = {int(row.get("id") or 0): row for row in public_rows}
        limited_rows: list[dict[str, Any]] = []
        for row in rows:
            rid = int(row.get("id") or 0)
            public = public_by_id.get(rid) or {}
