def _family_group_member_rows(cur, family_group_id: int) -> list[dict[str, Any]]:
    cur.execute(
        """
        SELECT fgm.*, u.first_name, u.last_name, u.login_type
        FROM family_group_members fgm
        LEFT JOIN users u ON u.id = fgm.user_id
        WHERE fgm.family_group_id=? AND COALESCE(fgm.active, 1)=1
        ORDER BY fgm.id ASC
        """,
        (int(family_group_id),),
    )
    return [dict(row) for row in (cur.fetchall() or [])]


def _family_group_access_allowed(admin_ref: int, acting_user: dict, group_row: dict, members: list[dict[str, Any]]) -> tuple[bool, list[dict[str, Any]]]:
    if _is_general_admin_scope(admin_ref):
        return True, members
    created_by_current_admin = int(group_row.get("created_by_admin_id") or 0) == int(acting_user.get("id") or 0)
    if not members:
        return (True, []) if created_by_current_admin else (False, [])
    if any(not _can_manage_user(admin_ref, row) for row in members):
        return False, []
    return True, members


@app.get("/admin/family-groups")
async def admin_family_groups_get(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM family_groups ORDER BY id DESC")
    raw_groups = [dict(row) for row in (cur.fetchall() or [])]
    groups: list[dict[str, Any]] = []
    for group in raw_groups:
        gid = int(group.get("id") or 0)
        members = _family_group_member_rows(cur, gid)
        allowed, scoped_members = _family_group_access_allowed(admin_ref, user, group, members)
        if not allowed:
            continue
        member_payload: list[dict[str, Any]] = []
        active_member_count = 0
        for member in scoped_members:
            member_id = int(member.get("user_id") or member.get("id") or 0)
            is_active_student = bool(member_id > 0 and _payment_is_active_student(member_id))
            if is_active_student:
                active_member_count += 1
            member_payload.append(
                {
                    **member,
                    "full_name": _display_name(member),
                    "is_active_student": is_active_student,
                }
            )
        total_member_count = len(member_payload)
        family_enabled = bool(int(group.get("active") or 0) == 1)
        eligible_for_discount = bool(family_enabled and active_member_count >= 2)
        group["members"] = member_payload
        group["total_member_count"] = int(total_member_count)
        group["active_member_count"] = int(active_member_count)
        group["eligible_for_discount"] = bool(eligible_for_discount)
        groups.append(group)
    conn.close()
    return {"items": groups}


@app.post("/admin/family-groups")
async def admin_family_groups_create(payload: FamilyGroupCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_payment_automation_schema()
    selected_member_ids = sorted({int(uid) for uid in (payload.member_user_ids or []) if int(uid) > 0})
    selected_members: list[dict[str, Any]] = []
    for uid in selected_member_ids:
        member = _safe_call(lambda target_uid=uid: get_user_by_id(int(target_uid)), None)
        if not member or int(member.get("login_type") or 0) not in (1, 2, 6):
            raise HTTPException(status_code=404, detail="Family member not found")
        if not _can_manage_user(admin_ref, member):
            raise HTTPException(status_code=403, detail="Permission denied")
        member_groups = _safe_call(lambda target_uid=uid: get_user_groups(int(target_uid)), []) or []
        if any(not _can_manage_group(admin_ref, group) for group in member_groups):
            raise HTTPException(status_code=403, detail="Permission denied")
        selected_members.append(member)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("BEGIN")
    cur.execute(
        """
        INSERT INTO family_groups(name, active, created_by_admin_id, updated_by_admin_id, created_at, updated_at)
        VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
        RETURNING id
        """,
        (str(payload.name or "").strip(), 1 if bool(payload.active) else 0, int(user.get("id") or 0), int(user.get("id") or 0)),
    )
    row = dict(cur.fetchone() or {})
    family_group_id = int(row.get("id") or 0)
    if family_group_id <= 0:
        conn.rollback()
        conn.close()
        raise HTTPException(status_code=500, detail="Could not create family group")
    for member in selected_members:
        cur.execute(
            """
            INSERT INTO family_group_members(family_group_id, user_id, active, added_by_admin_id, added_at)
            VALUES (?, ?, 1, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(family_group_id, user_id) DO NOTHING
            """,
            (int(family_group_id), int(member.get("id") or 0), int(user.get("id") or 0)),
        )
    conn.commit()
    conn.close()
    if selected_member_ids:
        _payment_prewarm_users_month_async(
            user_ids=set(selected_member_ids),
            reason="family_group_create",
        )
    return {"message": "Family group created"}


@app.patch("/admin/family-groups/{family_group_id}")
async def admin_family_groups_patch(
    family_group_id: int,
    payload: FamilyGroupUpdateRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    updates: list[str] = []
    params: list[Any] = []
    if payload.name is not None:
        updates.append("name=?")
        params.append(str(payload.name or "").strip())
    if payload.active is not None:
        updates.append("active=?")
        params.append(1 if bool(payload.active) else 0)
    updates.append("updated_by_admin_id=?")
    params.append(int(user.get("id") or 0))
    updates.append("updated_at=CURRENT_TIMESTAMP")
    if not updates:
        return {"message": "No updates"}
    params.append(int(family_group_id))
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM family_groups WHERE id=? LIMIT 1", (int(family_group_id),))
    group_row = dict(cur.fetchone() or {})
    if not group_row:
        conn.close()
        raise HTTPException(status_code=404, detail="Family group not found")
    members = _family_group_member_rows(cur, int(family_group_id))
    member_ids_before = {int(row.get("user_id") or 0) for row in members if int(row.get("user_id") or 0) > 0}
    allowed, _ = _family_group_access_allowed(admin_ref, user, group_row, members)
    if not allowed:
        conn.close()
        raise HTTPException(status_code=403, detail="Permission denied")
    cur.execute(f"UPDATE family_groups SET {', '.join(updates)} WHERE id=?", tuple(params))
    conn.commit()
    conn.close()
    if member_ids_before:
        _payment_prewarm_users_month_async(
            user_ids=member_ids_before,
            reason="family_group_patch",
        )
    return {"message": "Family group updated"}


@app.post("/admin/family-groups/{family_group_id}/members")
async def admin_family_groups_add_member(
    family_group_id: int,
    payload: FamilyGroupMemberRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_payment_automation_schema()
    target = _safe_call(lambda: get_user_by_id(int(payload.user_id)), None)
    if not target or int(target.get("login_type") or 0) not in (1, 2, 6):
        raise HTTPException(status_code=400, detail="Only student/accountless users can be family members")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    target_groups = _safe_call(lambda: get_user_groups(int(payload.user_id)), []) or []
    if any(not _can_manage_group(admin_ref, group) for group in target_groups):
        raise HTTPException(status_code=403, detail="Permission denied for target student's groups")
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM family_groups WHERE id=? LIMIT 1", (int(family_group_id),))
    group_row = dict(cur.fetchone() or {})
    if not group_row:
        conn.close()
        raise HTTPException(status_code=404, detail="Family group not found")
    members = _family_group_member_rows(cur, int(family_group_id))
    allowed, _ = _family_group_access_allowed(admin_ref, user, group_row, members)
    if not allowed:
        conn.close()
        raise HTTPException(status_code=403, detail="Permission denied")
    cur.execute(
        """
        INSERT INTO family_group_members(family_group_id, user_id, active, added_by_admin_id, added_at)
        VALUES (?, ?, 1, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(family_group_id, user_id)
        DO UPDATE SET active=1, removed_by_admin_id=NULL, removed_at=NULL, added_by_admin_id=excluded.added_by_admin_id
        """,
        (int(family_group_id), int(payload.user_id), int(user.get("id") or 0)),
    )
    conn.commit()
    conn.close()
    
    # Prewarm all members so their discounts recalculate correctly
    all_member_ids = {int(m.get("user_id") or 0) for m in members if int(m.get("user_id") or 0) > 0}
    all_member_ids.add(int(payload.user_id))
    _payment_prewarm_users_month_async(
        user_ids=all_member_ids,
        reason="family_group_add_member",
    )
    return {"message": "Family member added"}


@app.delete("/admin/family-groups/{family_group_id}/members/{member_user_id}")
async def admin_family_groups_remove_member(
    family_group_id: int,
    member_user_id: int,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_payment_automation_schema()
    target = _safe_call(lambda: get_user_by_id(int(member_user_id)), None)
    if target and not _can_manage_user(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    if target:
        target_groups = _safe_call(lambda: get_user_groups(int(member_user_id)), []) or []
        if any(not _can_manage_group(admin_ref, group) for group in target_groups):
            raise HTTPException(status_code=403, detail="Permission denied for target student's groups")
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM family_groups WHERE id=? LIMIT 1", (int(family_group_id),))
    group_row = dict(cur.fetchone() or {})
    if not group_row:
        conn.close()
        raise HTTPException(status_code=404, detail="Family group not found")
    members = _family_group_member_rows(cur, int(family_group_id))
    allowed, _ = _family_group_access_allowed(admin_ref, user, group_row, members)
    if not allowed:
        conn.close()
        raise HTTPException(status_code=403, detail="Permission denied")
    cur.execute(
        """
        UPDATE family_group_members
        SET active=0, removed_by_admin_id=?, removed_at=CURRENT_TIMESTAMP
        WHERE family_group_id=? AND user_id=?
        """,
        (int(user.get("id") or 0), int(family_group_id), int(member_user_id)),
    )
    conn.commit()
    conn.close()
    
    # Prewarm all members so their discounts recalculate correctly
    all_member_ids = {int(m.get("user_id") or 0) for m in members if int(m.get("user_id") or 0) > 0}
    all_member_ids.add(int(member_user_id))
    _payment_prewarm_users_month_async(
        user_ids=all_member_ids,
        reason="family_group_remove_member",
    )
    return {"message": "Family member removed"}


@app.post("/admin/students/accountless")
async def admin_create_accountless_student(
    payload: AccountlessStudentCreateRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    first_name = str(payload.first_name or "").strip()
    last_name = str(payload.last_name or "").strip()
    phone = str(payload.phone or "").strip()
    if not first_name:
        raise HTTPException(status_code=400, detail="first_name is required")
    if not last_name:
        raise HTTPException(status_code=400, detail="last_name is required")
    if not phone:
        raise HTTPException(status_code=400, detail="phone is required")
    if payload.referral_student_id and int(payload.referral_student_id) > 0:
        referral_source = _safe_call(lambda: get_user_by_id(int(payload.referral_student_id or 0)), None)
        if not referral_source:
            raise HTTPException(status_code=404, detail="Referral source student not found")
        if int(referral_source.get("login_type") or 0) not in (1, 2, 6):
            raise HTTPException(status_code=400, detail="Referral source must be a student or accountless student")
    group_ids = [int(gid) for gid in (payload.group_ids or []) if int(gid) > 0]
    groups = []
    for gid in group_ids:
        group = _safe_call(lambda group_id=gid: get_group(int(group_id)), None)
        if not group:
            raise HTTPException(status_code=404, detail=f"Group not found: {gid}")
        if not _can_manage_group(admin_ref, group):
            raise HTTPException(status_code=403, detail="Permission denied for one or more groups")
        groups.append(group)
    subject = (
        _normalize_subject_label(payload.subject)
        or (groups and _normalize_subject_label(str(groups[0].get("subject") or "").strip()))
        or "English"
    )
    parent_phone = str(payload.parent_phone or "").strip() or None
    _ensure_user_web_columns()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO users
        (
            login_id, password, password_used, first_name, last_name, phone, parent_phone, subject, login_type,
            blocked, access_enabled, owner_admin_id, placement_required, placement_subject, free_access
        )
        VALUES (NULL, NULL, 1, ?, ?, ?, ?, ?, 6, 1, 0, ?, 0, ?, ?)
        RETURNING id
        """,
        (
            first_name,
            last_name,
            phone,
            parent_phone,
            subject,
            int(admin_ref),
            subject,
            1 if payload.free_access else 0,
        ),
    )
    row = cur.fetchone() or {}
    new_user_id = int(row.get("id") or 0)
    conn.commit()
    conn.close()
    if new_user_id <= 0:
        raise HTTPException(status_code=500, detail="Could not create accountless student")
    joined_at = payload.joined_at if payload else None
    for gid in group_ids:
        add_user_to_group(int(new_user_id), int(gid), joined_at=joined_at)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        "UPDATE users SET login_id=NULL, password=NULL, password_used=1, blocked=1, access_enabled=0, login_type=6 WHERE id=?",
        (int(new_user_id),),
    )
    conn.commit()
    conn.close()
    if payload.family_group_id and int(payload.family_group_id) > 0:
        _ensure_payment_automation_schema()
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO family_group_members(family_group_id, user_id, active, added_by_admin_id, added_at)
            VALUES (?, ?, 1, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(family_group_id, user_id)
            DO UPDATE SET active=1, removed_by_admin_id=NULL, removed_at=NULL
            """,
            (int(payload.family_group_id), int(new_user_id), int(user.get("id") or 0)),
        )
        conn.commit()
        conn.close()
    if payload.referral_student_id and int(payload.referral_student_id) > 0:
        _ensure_payment_automation_schema()
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO payment_referral_bonus_log(referred_user_id, referral_user_id, bonus_amount, status, created_by_admin_id, created_at, updated_at)
            VALUES (?, ?, ?, 'pending_first_payment', ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            ON CONFLICT(referred_user_id) DO UPDATE SET
                referral_user_id=excluded.referral_user_id,
                bonus_amount=excluded.bonus_amount,
                status='pending_first_payment',
                updated_at=CURRENT_TIMESTAMP
            """,
            (
                int(new_user_id),
                int(payload.referral_student_id),
                float(_get_runtime_settings().get("referral_bonus_dpoints") or 100.0),
                int(user.get("id") or 0),
            ),
        )
        conn.commit()
        conn.close()
    created_user = _safe_call(lambda: get_user_by_id(int(new_user_id)), None) or {"id": new_user_id}
    _payment_prewarm_users_month_async(
        user_ids={int(new_user_id)},
        reason="accountless_create",
    )
    return {"message": "Accountless student created", "user": _serialize_user_row(created_user)}


@app.post("/admin/students/accountless/{user_id}/convert")
async def admin_convert_accountless_student(
    user_id: int,
    payload: AccountlessStudentConvertRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if int(target.get("login_type") or 0) != 6:
        raise HTTPException(status_code=400, detail="User is not an accountless student")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    subjects = _normalize_subjects(payload.subjects, fallback=["English"])
    level_to_store = str(payload.level or target.get("level") or "PRE-INTERMEDIATE").strip() or "PRE-INTERMEDIATE"
    placement_subject = _normalize_subject_label(payload.placement_subject) or subjects[0]
    login_id, password = _generate_unique_student_credentials()
    converted_login_type = 2
    _ensure_user_web_columns()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        UPDATE users
        SET login_id=?,
            password=?,
            password_used=0,
            login_type=?,
            blocked=0,
            access_enabled=1,
            placement_required=0,
            placement_subject=?,
            level=?,
            subject=?,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (
            login_id,
            hash_password(password),
            converted_login_type,
            placement_subject,
            level_to_store,
            ",".join(subjects),
            int(user_id),
        ),
    )
    conn.commit()
    conn.close()
    update_user_subjects(int(user_id), subjects)
    # Apply pending referral rewards where this user was accountless referrer.
    pending_referral_applied = 0
    _ensure_payment_automation_schema()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("BEGIN")
    try:
        cur.execute(
            """
            SELECT *
            FROM payment_referral_bonus_log
            WHERE referral_user_id=?
              AND status='pending_accountless'
            ORDER BY id ASC
            """,
            (int(user_id),),
        )
        pending_rows = [dict(row) for row in (cur.fetchall() or [])]
        for row in pending_rows:
            bonus_amount = float(row.get("bonus_amount") or _get_runtime_settings().get("referral_bonus_dpoints") or 100.0)
            if abs(bonus_amount) > 1e-9 and not add_dpoints_tx(
                cur,
                int(user_id),
                float(bonus_amount),
                subject="English",
                change_type="referral_bonus_after_accountless_conversion",
            ):
                raise RuntimeError(
                    f"accountless_conversion_referral_bonus_failed user_id={int(user_id)} "
                    f"referral_log_id={int(row.get('id') or 0)} amount={float(bonus_amount)}"
                )
            cur.execute(
                """
                UPDATE payment_referral_bonus_log
                SET status='given',
                    applied_at=CURRENT_TIMESTAMP,
                    updated_at=CURRENT_TIMESTAMP
                WHERE id=?
                """,
                (int(row.get("id") or 0),),
            )
            pending_referral_applied += 1
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    finally:
        conn.close()
    qr_generated = _generate_qr_login_token(int(user_id), WEB_QR_LOGIN_TTL_SECONDS)
    _payment_prewarm_users_month_async(
        user_ids={int(user_id)},
        reason="accountless_to_normal_convert",
    )
    return {
        "message": "Accountless student converted",
        "new_user_id": int(user_id),
        "login_type": converted_login_type,
        "login_id": login_id,
        "password": password,
        "pending_referral_applied_count": int(pending_referral_applied),
        "qr_token": str(qr_generated.get("qr_token") or ""),
        "qr_payload": str(qr_generated.get("qr_payload") or ""),
        "qr_expires_at": str(qr_generated.get("expires_at") or ""),
    }


@app.post("/admin/users/{user_id}/convert-to-accountless")
async def admin_convert_student_to_accountless(
    user_id: int,
    payload: NormalStudentToAccountlessRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="Permission denied")
    login_type = int(target.get("login_type") or 0)
    if login_type == 6:
        return {"message": "User already accountless", "user": _serialize_user_row(target)}
    if login_type not in (1, 2):
        raise HTTPException(status_code=400, detail="Only student accounts can be converted to accountless")

    normalized_subject = _normalize_subject_label(payload.subject) or (_user_subjects_from_row(target) or ["English"])[0]
    _ensure_user_web_columns()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        UPDATE users
        SET login_id=NULL,
            password=NULL,
            password_used=1,
            login_type=6,
            blocked=1,
            access_enabled=0,
            placement_required=0,
            pending_approval=0,
            subject=?,
            updated_at=CURRENT_TIMESTAMP
        WHERE id=?
        """,
        (normalized_subject, int(user_id)),
    )
    conn.commit()
    conn.close()
    refreshed = _safe_call(lambda: get_user_by_id(int(user_id)), None) or target
    _payment_prewarm_users_month_async(
        user_ids={int(user_id)},
        reason="normal_to_accountless_convert",
    )
    return {"message": "Student converted to accountless", "user": _serialize_user_row(refreshed)}


@app.post("/admin/payments/reminders/bulk")
async def admin_payments_reminders_bulk(
    payload: PaymentReminderBulkRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    ym = _payment_validate_ym(payload.ym) if str(payload.ym or "").strip() else _payment_ym_now()
    send_telegram = bool(payload.send_telegram)
    send_website = bool(payload.send_website)
    if not send_telegram and not send_website:
        raise HTTPException(status_code=400, detail="At least one channel must be enabled")
    normalized_student_ids = sorted({int(sid) for sid in (payload.student_ids or []) if int(sid or 0) > 0})
    if len(normalized_student_ids) > 500:
        raise HTTPException(status_code=400, detail="Too many selected students for one bulk request")
    recipients: list[dict] = []
    if normalized_student_ids:
        for sid in normalized_student_ids:
            row = _safe_call(lambda uid=int(sid): get_user_by_id(uid), None)
            if not row or int(row.get("login_type") or 0) not in (1, 2):
                continue
            if _student_in_manageable_payment_group(admin_ref, int(row.get("id") or 0)):
                recipients.append(row)
            else:
                logger.warning(
                    "payment_bulk_reminder_scope_denied admin_ref_id=%s target_user_id=%s",
                    int(admin_ref),
                    int(sid),
                )
                _payment_log_reminder_dispatch(
                    user_id=int(sid),
                    ym=ym,
                    trigger_source="bulk_admin",
                    reminder_type="bulk_reminder",
                    channel="website",
                    status="skipped",
                    reason="unauthorized_scope",
                    dispatch_day=_now_tashkent_date(),
                )
    elif payload.group_id and int(payload.group_id) > 0:
        group = _safe_call(lambda gid=int(payload.group_id): get_group(gid), None)
        if not _can_manage_group(admin_ref, group):
            raise HTTPException(status_code=403, detail="Permission denied")
        members = _safe_call(lambda gid=int(payload.group_id): get_group_users(gid), []) or []
        recipients = [row for row in members if int(row.get("login_type") or 0) in (1, 2)]
    else:
        seen_ids: set[int] = set()
        recipients = []
        for group in _scope_groups_for_admin(admin_ref, _safe_call(get_all_groups, []) or []):
            for row in _safe_call(lambda gid=int(group.get("id") or 0): get_group_users(gid), []) or []:
                uid = int(row.get("id") or 0)
                if uid and uid not in seen_ids and int(row.get("login_type") or 0) in (1, 2):
                    seen_ids.add(uid)
                    recipients.append(row)
    sent = 0
    failed = 0
    skipped = 0
    sent_telegram = 0
    sent_website = 0
    failed_telegram = 0
    failed_website = 0
    skipped_telegram = 0
    skipped_website = 0
    dispatch_day = _now_tashkent_date()
    trigger_source = "bulk_admin"
    reminder_type = "bulk_reminder"
    def _render_bulk_template(template: str, values: dict[str, str]) -> str:
        out = str(template or "")
        for key, value in values.items():
            out = out.replace(f"{{{{{key}}}}}", value)
            out = out.replace(f"{{{key}}}", value)
        return out
    cards = _payment_cards_public_payload()
    default_card = next((card for card in cards if bool(card.get("is_default"))), cards[0] if cards else None)
    card_line = ""
    if default_card:
        owner = f"{str(default_card.get('owner_first_name') or '').strip()} {str(default_card.get('owner_last_name') or '').strip()}".strip()
        number = str(default_card.get("card_number_masked") or "").strip()
        if owner and number:
            card_line = f"Karta: {owner} — {number}"
        elif number:
            card_line = f"Karta: {number}"
    for row in recipients:
        uid = int(row.get("id") or 0)
        if uid <= 0:
            continue
        active_groups = _safe_call(lambda user_id=uid: get_user_groups(int(user_id)), []) or []
        if not active_groups:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=ym,
                trigger_source=trigger_source,
                reminder_type=reminder_type,
                channel="website",
                status="skipped",
                reason="no_active_group",
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        student_overview = _payment_student_overview(row, ym=ym, months_back=1)
        current = student_overview.get("current_month") or {}
        debt = float(current.get("total_debt_amount") or 0.0)
        status = str(current.get("status") or PAYMENT_STATUS_UNPAID)
        overpayment_amount = float(current.get("total_overpayment_amount") or 0.0)
        overdue_items = [
            month
            for month in (student_overview.get("months") or [])
            if str(month.get("status") or "") == PAYMENT_STATUS_OVERDUE and float(month.get("total_debt_amount") or 0.0) > 0
        ]
        skip_reason = _payment_skip_reason_for_reminder(
            trigger_source=trigger_source,
            status=status,
            debt_amount=float(debt),
            overpayment_amount=float(overpayment_amount),
            overdue_items=overdue_items,
        )
        if skip_reason:
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=ym,
                trigger_source=trigger_source,
                reminder_type=reminder_type,
                channel="website",
                status="skipped",
                reason=str(skip_reason),
                dispatch_day=dispatch_day,
            )
            _payment_log_reminder_dispatch(
                user_id=int(uid),
                ym=ym,
                trigger_source=trigger_source,
                reminder_type=reminder_type,
                channel="telegram",
                status="skipped",
                reason=str(skip_reason),
                dispatch_day=dispatch_day,
            )
            skipped += 1
            continue
        groups_text = ", ".join(
            sorted(
                {
                    str(item.get("group_name") or "").strip()
                    for item in (current.get("items") or [])
                    if str(item.get("group_name") or "").strip()
                }
            )
        ) or "-"
        courses_text = ", ".join(
            sorted(
                {
                    str(item.get("course_title") or "").strip()
                    for item in (current.get("items") or [])
                    if str(item.get("course_title") or "").strip()
                }
            )
        ) or "-"
        text = str(payload.message or "").strip()
        if text:
            text = _render_bulk_template(
                text,
                {
                    "student_name": _display_name(row),
                    "month": ym,
                    "debt_amount": f"{debt:.2f}",
                    "status": status,
                    "group_name": groups_text,
                    "course_name": courses_text,
                    "payment_deadline": "25",
                    "card_info": card_line or "-",
                },
            ).strip()
        user_lang = str(row.get("language") or "uz")
        if not text:
            text = _format_payment_reminder_text(
                lang=user_lang,
                student_name=_display_name(row),
                ym=ym,
                status=status,
                debt_amount=float(debt),
                groups_text=groups_text,
                courses_text=courses_text,
                card_line=card_line,
                overdue_items=overdue_items,
            )
        student_payments_url = f"{WEBAPP_URL}/?role=student&section=payments" if WEBAPP_URL else None
        if send_website:
            if _payment_reminder_dispatch_sent(
                user_id=int(uid),
                trigger_source=trigger_source,
                channel="website",
                dispatch_day=dispatch_day,
                reminder_type=reminder_type,
            ):
                skipped += 1
                skipped_website += 1
            else:
                conn_w = get_conn()
                cur_w = conn_w.cursor()
                try:
                    notif_id = int(
                        _payment_upsert_web_notification(
                            cur_w,
                            user_id=int(uid),
                            notification_type="payment_bulk_reminder",
                            title=_payment_reminder_web_title(user_lang),
                            message=text,
                            button_text=_payment_reminder_web_button(user_lang),
                            button_url="/?role=student&section=payments",
                            target_screen="payments",
                            source_key=f"payment_bulk_reminder:{dispatch_day}:{int(uid)}:{ym}",
                            meta={"ym": ym, "status": status, "debt_amount": float(debt)},
                        )
                        or 0
                    )
                    conn_w.commit()
                    _payment_log_reminder_dispatch(
                        user_id=int(uid),
                        ym=ym,
                        trigger_source=trigger_source,
                        reminder_type=reminder_type,
                        channel="website",
                        status="sent",
                        reason="ok",
                        message_text=text,
                        notification_id=(notif_id if notif_id > 0 else None),
                        dispatch_day=dispatch_day,
                    )
                    sent += 1
                    sent_website += 1
                except Exception as exc:
                    try:
                        conn_w.rollback()
                    except Exception:
                        pass
                    _payment_log_reminder_dispatch(
                        user_id=int(uid),
                        ym=ym,
                        trigger_source=trigger_source,
                        reminder_type=reminder_type,
                        channel="website",
                        status="failed",
                        reason=str(exc)[:240],
                        message_text=text,
                        dispatch_day=dispatch_day,
                    )
                    failed += 1
                    failed_website += 1
                finally:
                    conn_w.close()

        if send_telegram:
            tg = str(row.get("telegram_id") or "").strip()
            if not tg:
                _payment_log_reminder_dispatch(
                    user_id=int(uid),
                    ym=ym,
                    trigger_source=trigger_source,
                    reminder_type=reminder_type,
                    channel="telegram",
                    status="skipped",
                    reason="telegram_id_missing",
                    message_text=text,
                    dispatch_day=dispatch_day,
                )
                skipped += 1
                skipped_telegram += 1
            elif _payment_reminder_dispatch_sent(
                user_id=int(uid),
                trigger_source=trigger_source,
                channel="telegram",
                dispatch_day=dispatch_day,
                reminder_type=reminder_type,
            ):
                skipped += 1
                skipped_telegram += 1
            else:
                token = _tg_token_for_login_type(int(row.get("login_type") or 0))
                ok = await _send_telegram_text(
                    token,
                    tg,
                    text,
                )
                if ok:
                    _payment_log_reminder_dispatch(
                        user_id=int(uid),
                        ym=ym,
                        trigger_source=trigger_source,
                        reminder_type=reminder_type,
                        channel="telegram",
                        status="sent",
                        reason="ok",
                        message_text=text,
                        telegram_chat_id=tg,
                        dispatch_day=dispatch_day,
                    )
                    sent += 1
                    sent_telegram += 1
                else:
                    _payment_log_reminder_dispatch(
                        user_id=int(uid),
                        ym=ym,
                        trigger_source=trigger_source,
                        reminder_type=reminder_type,
                        channel="telegram",
                        status="failed",
                        reason="telegram_send_failed",
                        message_text=text,
                        telegram_chat_id=tg,
                        dispatch_day=dispatch_day,
                    )
                    failed += 1
                    failed_telegram += 1
    return {
        "message": "Reminder job finished",
        "ym": ym,
        "sent": int(sent),
        "failed": int(failed),
        "skipped": int(skipped),
        "channels": {
            "website": {"sent": int(sent_website), "failed": int(failed_website), "skipped": int(skipped_website)},
            "telegram": {"sent": int(sent_telegram), "failed": int(failed_telegram), "skipped": int(skipped_telegram)},
        },
    }


@app.get("/student/payments/me")
async def student_payments_me(
    ym: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    _require_payment_part4_feature("student payments page")
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"student"})
    if role != "student":
        raise HTTPException(status_code=403, detail="Only student can access")
    if int(user.get("login_type") or 0) == 6:
        raise HTTPException(status_code=403, detail="Accountless student has no web access")
    month_key = _payment_validate_ym(ym) if str(ym or "").strip() else _payment_ym_now()
    uid = int(user.get("id") or 0)
    cache_key = (uid, month_key)
    cached = _STUDENT_PAYMENT_ME_CACHE.get(cache_key)
    if cached and cached[0] > time.time():
        return dict(cached[1])
    lock = _hot_cache_key_lock("student_payments_me", cache_key)
    with lock:
        cached = _STUDENT_PAYMENT_ME_CACHE.get(cache_key)
        if cached and cached[0] > time.time():
            return dict(cached[1])

        overview = _payment_student_overview(user, ym=month_key, months_back=1, include_history=False)
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT
                    tx.id,
                    tx.user_id,
                    tx.group_id,
                    tx.ym,
                    tx.amount,
                    tx.payment_method,
                    tx.note,
                    tx.status_after,
                    tx.remaining_after,
                    tx.overpayment_after,
                    tx.created_at,
                    pc.card_number,
                    pc.owner_first_name AS card_owner_first_name,
                    pc.owner_last_name AS card_owner_last_name
                FROM payment_transactions tx
                LEFT JOIN payment_cards pc ON pc.id = tx.card_id
                WHERE tx.user_id=? AND tx.ym=?
                ORDER BY tx.created_at DESC, tx.id DESC
                LIMIT 8
                """,
                (uid, month_key),
            )
            tx_rows = [dict(row) for row in (cur.fetchall() or [])]
            for row in tx_rows:
                card_number = str(row.get("card_number") or "").strip()
                digits = re.sub(r"\D", "", card_number)
                row["card_number_masked"] = f"{digits[:4]} **** **** {digits[-4:]}" if len(digits) >= 8 else (card_number or None)
                row["card_owner_name"] = (
                    f"{str(row.get('card_owner_first_name') or '').strip()} {str(row.get('card_owner_last_name') or '').strip()}".strip()
                    or None
                )
            cur.execute(
                """
                SELECT id, user_id, group_id, ym, bonus_type, amount, reversed, created_at
                FROM payment_bonus_log
                WHERE user_id=? AND ym=?
                ORDER BY created_at DESC, id DESC
                LIMIT 6
                """,
                (uid, month_key),
            )
            overview["transactions"] = tx_rows
            overview["bonus_history"] = [dict(row) for row in (cur.fetchall() or [])]
        finally:
            conn.close()
        response_payload = {
            "user": _serialize_user_row(user),
            "overview": overview,
        }
        _STUDENT_PAYMENT_ME_CACHE[cache_key] = (time.time() + 5.0, dict(response_payload))
        return response_payload


@app.patch("/admin/users/{user_id}")
async def admin_update_user(user_id: int, payload: AdminUserUpdateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="You cannot manage this user")
    _assert_not_protected_admin_target(target)
    current_login_type = int(target.get("login_type") or 0)
    target_login_type = int(payload.login_type) if payload.login_type is not None else current_login_type
    if target_login_type in (1, 2, 6) and payload.subjects is not None:
        raise HTTPException(status_code=400, detail="Student subjects are derived from active groups")
    if target_login_type == 2:
        result_level = str(payload.level if payload.level is not None else target.get("level") or "").strip() or "PRE-INTERMEDIATE"
    if target_login_type in (3, 5):
        if (payload.level or "").strip():
            raise HTTPException(status_code=400, detail="teacher/support_teacher must not include level")
        if payload.placement_required is not None or (payload.placement_subject or "").strip():
            raise HTTPException(status_code=400, detail="teacher/support_teacher must not include placement fields")
        if payload.subjects is not None:
            teacher_subjects = _normalize_subjects(payload.subjects, fallback=[])
            if not teacher_subjects:
                raise HTTPException(status_code=400, detail="teacher/support_teacher must have at least one subject")
    if target_login_type == 1 and (payload.level or "").strip():
        raise HTTPException(status_code=400, detail="new_student_with_test must not include level")

    _ensure_user_web_columns()
    updates_sql: list[str] = []
    params: list[Any] = []
    if payload.first_name is not None:
        updates_sql.append("first_name=?")
        params.append(payload.first_name.strip())
    if payload.last_name is not None:
        updates_sql.append("last_name=?")
        params.append(payload.last_name.strip())
    if payload.phone is not None:
        updates_sql.append("phone=?")
        params.append(payload.phone.strip())
    if payload.parent_phone is not None:
        updates_sql.append("parent_phone=?")
        params.append(payload.parent_phone.strip() or None)
    if payload.telegram_id is not None:
        updates_sql.append("telegram_id=?")
        val = str(payload.telegram_id).strip()
        params.append(val if val else None)
    if payload.instagram_url is not None:
        updates_sql.append("instagram_url=?")
        val = str(payload.instagram_url).strip()
        params.append(val if val else None)
    if payload.telegram_url is not None:
        updates_sql.append("telegram_url=?")
        val = str(payload.telegram_url).strip()
        params.append(val if val else None)
    if payload.blocked is not None:
        updates_sql.append("blocked=?")
        params.append(1 if payload.blocked else 0)
    if payload.placement_required is not None:
        updates_sql.append("placement_required=?")
        params.append(1 if payload.placement_required else 0)
    if payload.placement_subject is not None:
        candidate_subjects = _normalize_subjects(
            payload.subjects if payload.subjects is not None else _user_subjects_from_row(target),
            fallback=["English"],
        )
        normalized_placement_subject = _normalize_subject_label(payload.placement_subject) or candidate_subjects[0]
        if normalized_placement_subject not in candidate_subjects:
            raise HTTPException(status_code=400, detail=f"placement_subject must be one of: {', '.join(candidate_subjects)}")
        updates_sql.append("placement_subject=?")
        params.append(normalized_placement_subject)
    if payload.family_discount_enabled is not None:
        updates_sql.append("family_discount_enabled=?")
        params.append(1 if payload.family_discount_enabled else 0)
    if payload.multi_group_discount_opt_in is not None:
        updates_sql.append("multi_group_discount_opt_in=?")
        params.append(1 if payload.multi_group_discount_opt_in else 0)
    if payload.referral_student_id is not None:
        referral_id = int(payload.referral_student_id) if int(payload.referral_student_id) > 0 else None
        if referral_id is not None:
            if int(referral_id) == int(user_id):
                raise HTTPException(status_code=400, detail="Referral source cannot be the same user")
            referral_source = _safe_call(lambda: get_user_by_id(int(referral_id)), None)
            if not referral_source:
                raise HTTPException(status_code=404, detail="Referral source student not found")
            if int(referral_source.get("login_type") or 0) not in (1, 2, 6):
                raise HTTPException(status_code=400, detail="Referral source must be a student or accountless student")
        updates_sql.append("referral_student_id=?")
        params.append(referral_id)
    if payload.free_access is not None:
        updates_sql.append("free_access=?")
        params.append(1 if payload.free_access else 0)

    if updates_sql:
        conn = get_conn()
        cur = conn.cursor()
        cur.execute(
            f"UPDATE users SET {', '.join(updates_sql)} WHERE id=?",
            (*params, int(user_id)),
        )
        conn.commit()
        conn.close()

    if payload.level is not None:
        update_user_level(int(user_id), payload.level.strip())
    if payload.language is not None:
        update_user_language(int(user_id), payload.language.strip().lower())
    if payload.login_type is not None:
        set_user_login_type(int(user_id), int(payload.login_type))
    if payload.pending_approval is not None:
        set_pending_approval(int(user_id), bool(payload.pending_approval))
    if payload.access_enabled is not None:
        if payload.access_enabled:
            enable_access(int(user_id))
        else:
            disable_access(int(user_id))
    if payload.subjects is not None:
        old_subjects = _user_subjects_from_row(target)
        if target_login_type in (3, 5):
            new_subjects = _normalize_subjects(payload.subjects, fallback=[])
            if not new_subjects:
                raise HTTPException(status_code=400, detail="teacher/support_teacher must have at least one subject")
        else:
            new_subjects = _normalize_subjects(payload.subjects, fallback=old_subjects or ["English"])
        update_user_subjects(int(user_id), new_subjects)
        if payload.placement_subject is None:
            conn = get_conn()
            cur = conn.cursor()
            cur.execute("UPDATE users SET placement_subject=? WHERE id=?", (new_subjects[0], int(user_id)))
            conn.commit()
            conn.close()
        for removed in old_subjects:
            if removed not in new_subjects:
                _safe_call(lambda s=removed: cleanup_student_subject_side_effects(int(user_id), s), None)
    if payload.placement_required is True:
        set_user_login_type(int(user_id), 1)
        disable_access(int(user_id))
    elif payload.placement_required is False:
        current = _safe_call(lambda: get_user_by_id(int(user_id)), None) or {}
        if int(current.get("login_type") or 0) == 1:
            set_user_login_type(int(user_id), 2)
        enable_access(int(user_id))

    refreshed = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not refreshed:
        raise HTTPException(status_code=404, detail="User not found after update")
    return {"message": "User updated", "user": _serialize_user_row(refreshed)}


@app.post("/admin/users/{user_id}/reset-password", response_model=AdminPasswordResetResponse)
async def admin_reset_password(user_id: int, payload: AdminPasswordResetRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if not _can_manage_user_globally(admin_ref, target):
        raise HTTPException(status_code=403, detail="You cannot manage this user")
    _assert_not_protected_admin_target(target)

    password = (payload.password or "").strip().upper()
    if not password:
        password = generate_password(6)
    if len(password) < 6:
        raise HTTPException(status_code=400, detail="Password must be at least 6 characters")
    reset_user_password(int(user_id), password)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        UPDATE users
        SET session_version=COALESCE(session_version, 1) + 1
        WHERE id=?
        """,
        (int(user_id),),
    )
    conn.commit()
    conn.close()
    _revoke_web_sessions(int(user_id), keep_session_id=None, reason="admin_reset_password")
    refreshed = _safe_call(lambda: get_user_by_id(int(user_id)), None) or target
    qr_generated = _safe_call(lambda: _generate_qr_login_token(int(user_id), WEB_QR_LOGIN_TTL_SECONDS), {}) or {}
    return {
        "message": "Password reset",
        "user_id": int(user_id),
        "password": password,
        "session_version": int(refreshed.get("session_version") or 1),
        "qr_token": str(qr_generated.get("qr_token") or "") or None,
        "qr_payload": str(qr_generated.get("qr_payload") or "") or None,
        "qr_expires_at": str(qr_generated.get("expires_at") or "") or None,
    }


