def _find_inactive_students(admin_ref: int, months: int = 2) -> list[dict]:
    """2 oydan ortiq hech qanday aktiv guruhda bo'lmagan o'quvchilarni qaytaradi."""
    from datetime import datetime, timezone, timedelta
    cutoff = (datetime.now(tz=timezone.utc) - timedelta(days=30 * months)).strftime("%Y-%m-%d")
    conn = get_conn()
    cur = conn.cursor()
    # O'quvchilar ro'yxati shu adminga tegishli
    cur.execute(
        """
        SELECT u.id, u.first_name, u.last_name, u.phone, u.login_type, u.owner_admin_id,
               u.created_at
        FROM users u
        WHERE u.owner_admin_id = ?
          AND u.login_type IN (1, 6)
          AND (u.blocked IS NULL OR u.blocked != 0)
        """,
        (admin_ref,),
    )
    all_students = [dict(r) for r in (cur.fetchall() or [])]
    # Guruh memberligi
    cur.execute(
        """
        SELECT gm.user_id, g.active, COALESCE(gm.joined_at, g.created_at, ?) as last_active
        FROM group_members gm
        JOIN groups g ON g.id = gm.group_id
        WHERE g.owner_admin_id = ?
        """,
        (cutoff, admin_ref),
    )
    member_rows = cur.fetchall() or []
    conn.close()
    # user_id → max(last_active_date) from active groups
    last_active_map: dict[int, str] = {}
    for row in member_rows:
        if int(row.get("active") or 0) == 0:
            # Faol emas guruh — ignore
            continue
        uid = int(row.get("user_id") or 0)
        la = str(row.get("last_active") or "")[:10]
        if uid not in last_active_map or la > last_active_map[uid]:
            last_active_map[uid] = la
    inactive = []
    for s in all_students:
        uid = int(s.get("id") or 0)
        last_active = last_active_map.get(uid, "")
        if last_active == "" or last_active < cutoff:
            inactive.append({
                "id": uid,
                "first_name": str(s.get("first_name") or ""),
                "last_name": str(s.get("last_name") or ""),
                "phone": str(s.get("phone") or ""),
                "login_type": int(s.get("login_type") or 0),
                "last_active_group": last_active or None,
                "created_at": str(s.get("created_at") or ""),
            })
    return inactive


@app.get("/admin/students/inactive-preview")
async def admin_inactive_students_preview(
    months: int = 2,
    authorization: str | None = Header(default=None),
):
    """2 oydan ortiq (default) hech qanday aktiv guruhda bo'lmagan o'quvchilar ro'yxati."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    if months < 1 or months > 24:
        raise HTTPException(status_code=400, detail="months must be between 1 and 24")
    students = _find_inactive_students(admin_ref, months=months)
    return {"inactive_count": len(students), "months": months, "students": students}


@app.delete("/admin/students/inactive-purge")
async def admin_inactive_students_purge(
    months: int = 2,
    dry_run: bool = False,
    authorization: str | None = Header(default=None),
):
    """2 oydan ortiq hech qanday aktiv guruhda bo'lmagan o'quvchilarni o'chiradi.
    dry_run=true bo'lsa faqat preview, o'chirish amalga oshirilmaydi."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    if months < 1 or months > 24:
        raise HTTPException(status_code=400, detail="months must be between 1 and 24")
    students = _find_inactive_students(admin_ref, months=months)
    if dry_run:
        return {
            "dry_run": True,
            "would_delete_count": len(students),
            "months": months,
            "students": students,
        }
    deleted_ids = []
    failed_ids = []
    for s in students:
        uid = int(s.get("id") or 0)
        try:
            ok = hard_delete_user_profile(uid)
            if ok:
                deleted_ids.append(uid)
                logger.info("inactive.purge deleted user_id=%s admin=%s months=%s", uid, admin_ref, months)
            else:
                failed_ids.append(uid)
        except Exception:
            failed_ids.append(uid)
            logger.exception("inactive.purge error user_id=%s", uid)
    return {
        "deleted_count": len(deleted_ids),
        "failed_count": len(failed_ids),
        "deleted_ids": deleted_ids,
        "failed_ids": failed_ids,
        "months": months,
    }


@app.patch("/admin/groups/{group_id}")
async def admin_update_group(group_id: int, payload: GroupUpdateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="You cannot manage this group")
    affected_user_ids = _payment_group_member_user_ids(int(group_id))

    if payload.name is not None:
        update_group_name(int(group_id), payload.name.strip())
        
    if payload.telegram_group_url is not None:
        update_group_telegram_url(int(group_id), payload.telegram_group_url.strip() or None)
    
    # Resolve subject first to check for level bypass
    effective_subject = _resolve_group_subject_input(
        payload.subject if payload.subject is not None else str(group.get("subject") or ""),
        payload.subject_id,
    )
    if payload.level is not None:
        group_level = "" if effective_subject in ("Matematika", "Ona tili", "Tarix", "Arab tili") else payload.level.strip()
        update_group_level(int(group_id), group_level, sync_students=True)
        
    if payload.subject is not None or payload.subject_id is not None or payload.teacher_id is not None:
        if payload.subject is not None and not str(payload.subject).strip():
            raise HTTPException(status_code=400, detail="subject cannot be empty")
        effective_teacher_id = int(payload.teacher_id) if payload.teacher_id is not None else int(group.get("teacher_id") or 0)
        if effective_teacher_id <= 0:
            raise HTTPException(status_code=400, detail="Group must have a valid teacher_id")
        _, validated_subject = _validate_group_teacher_and_subject(
            effective_teacher_id,
            effective_subject,
        )
        if payload.teacher_id is not None:
            update_group_teacher(int(group_id), effective_teacher_id)
        update_group_subject(int(group_id), validated_subject)
        if validated_subject in ("Matematika", "Ona tili", "Tarix", "Arab tili"):
            update_group_level(int(group_id), "", sync_students=True)
    elif not str(group.get("subject") or "").strip():
        # Legacy safeguard: do not allow saving groups without a subject.
        raise HTTPException(status_code=400, detail="subject is required for every group")
    effective_course_id = int(payload.course_id) if payload.course_id is not None else int(group.get("course_id") or 0)
    if effective_course_id <= 0:
        raise HTTPException(status_code=400, detail="course_id is required for every group")
    linked_course = _get_course_by_id(int(effective_course_id))
    if not linked_course:
        raise HTTPException(status_code=404, detail="Course not found")
    effective_pricing_type = payload.pricing_type if payload.pricing_type is not None else group.get("pricing_type")
    update_group_course_details(
        int(group_id),
        course_id=int(linked_course["id"]),
        course_title=str(linked_course.get("title") or "").strip(),
        monthly_fee_text=str(linked_course.get("individual_price_text") or "").strip() if effective_pricing_type == "individual" else str(linked_course.get("price_text") or "").strip(),
        telegram_group_url=payload.telegram_group_url,
        pricing_type=effective_pricing_type,
    )
    update_group_extra_subjects(int(group_id), [])
    if payload.lesson_date is not None or payload.lesson_start is not None or payload.lesson_end is not None or payload.tz is not None:
        lesson_days = group.get("lesson_date")
        if payload.lesson_date is not None:
            lesson_days = _normalize_lesson_days(payload.lesson_date)
            if not lesson_days:
                raise HTTPException(status_code=400, detail="lesson_date must be MWF or TTS")
        update_group_schedule(
            int(group_id),
            lesson_days,
            payload.lesson_start if payload.lesson_start is not None else group.get("lesson_start"),
            payload.lesson_end if payload.lesson_end is not None else group.get("lesson_end"),
            payload.tz if payload.tz is not None else group.get("tz") or "Asia/Tashkent",
        )
    refreshed = _safe_call(lambda: get_group(int(group_id)), None)
    if affected_user_ids:
        _payment_prewarm_users_month_async(
            user_ids=affected_user_ids,
            limit_group_ids={int(group_id)},
            reason="admin_update_group",
        )
    return {"message": "Group updated", "group": _serialize_group_row(refreshed or group)}


