@app.get("/admin/groups/{group_id}/available-students")
async def admin_group_available_students(
    group_id: int,
    q: str = Query(default=""),
    limit: int = Query(default=1000, ge=1, le=1000),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    try:
        _ensure_admin_perf_indexes()
    except Exception:
        logger.exception("admin_group_available_students index-ensure failed group_id=%s", group_id)
    query = (q or "").strip().lower()
    enforce_scope = False
    has_owner_admin_id = _db_has_column("users", "owner_admin_id")
    has_left_date = _db_has_column("user_groups", "left_date")
    has_groups_active = _db_has_column("groups", "active")
    active_join_clause = (
        "AND (ug.left_date IS NULL OR TRIM(CAST(ug.left_date AS TEXT))='')"
        if has_left_date
        else ""
    )
    active_sub_clause = (
        "WHERE (ug2.left_date IS NULL OR TRIM(CAST(ug2.left_date AS TEXT))='')"
        if has_left_date
        else "WHERE 1=1"
    )
    groups_active_clause = (
        "AND (g2.id IS NULL OR COALESCE(g2.active,1)=1)"
        if has_groups_active
        else ""
    )
    where_sql: list[str] = [
        "u.login_type IN (1,2,6)",
        "ug.user_id IS NULL",
    ]
    params: list[Any] = [int(group_id)]
    if query:
        where_sql.append(
            "LOWER(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'') || ' ' || COALESCE(u.phone,'') || ' ' || COALESCE(u.login_id,'') || ' ' || COALESCE(CAST(u.telegram_id AS TEXT),'')) LIKE ?"
        )
        params.append(f"%{query}%")

    if enforce_scope:
        if has_owner_admin_id:
            owner_scope, owner_params = _limited_admin_owner_scope_sql("u.owner_admin_id", int(admin_ref))
            where_sql.append(owner_scope)
            params.extend(owner_params)
        else:
            # Legacy schema with limited-admin mode and no ownership column: return empty set safely.
            where_sql.append("1=0")

    conn = get_conn()
    cur = conn.cursor()
    query_sql = f"""
        SELECT
            u.*,
            COALESCE(gc.group_count, 0) AS group_count
        FROM users u
        LEFT JOIN user_groups ug
          ON ug.user_id = u.id
         AND ug.group_id = ?
         {active_join_clause}
        LEFT JOIN (
            SELECT ug2.user_id, COUNT(DISTINCT ug2.group_id) AS group_count
            FROM user_groups ug2
            LEFT JOIN groups g2 ON g2.id = ug2.group_id
            {active_sub_clause}
            {groups_active_clause}
            GROUP BY ug2.user_id
        ) gc ON gc.user_id = u.id
        WHERE {" AND ".join(where_sql)}
        ORDER BY COALESCE(u.created_at, CURRENT_TIMESTAMP) DESC, u.id DESC
        LIMIT ?
    """
    try:
        cur.execute(query_sql, tuple([*params, int(limit)]))
        rows = [dict(row) for row in (cur.fetchall() or [])]
    except Exception as primary_exc:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.exception("admin_group_available_students primary query failed group_id=%s q=%s", group_id, query)
        # Fallback query for legacy schema inconsistencies.
        fallback_where = [
            "u.login_type IN (1,2,6)",
            "NOT EXISTS (SELECT 1 FROM user_groups ug WHERE ug.user_id = u.id AND ug.group_id = ?)",
        ]
        fallback_params: list[Any] = [int(group_id)]
        if query:
            fallback_where.append(
                "LOWER(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'') || ' ' || COALESCE(u.phone,'') || ' ' || COALESCE(u.login_id,'') || ' ' || COALESCE(CAST(u.telegram_id AS TEXT),'')) LIKE ?"
            )
            fallback_params.append(f"%{query}%")
        if enforce_scope:
            if has_owner_admin_id:
                owner_scope, owner_params = _limited_admin_owner_scope_sql("u.owner_admin_id", int(admin_ref))
                fallback_where.append(owner_scope)
                fallback_params.extend(owner_params)
            else:
                fallback_where.append("1=0")
        fallback_sql = f"""
            SELECT u.*
            FROM users u
            WHERE {" AND ".join(fallback_where)}
            ORDER BY COALESCE(u.created_at, CURRENT_TIMESTAMP) DESC, u.id DESC
            LIMIT ?
        """
        try:
            cur.execute(fallback_sql, tuple([*fallback_params, int(limit)]))
            rows = [dict(row) for row in (cur.fetchall() or [])]
        except Exception:
            conn.close()
            logger.exception(
                "admin_group_available_students fallback failed group_id=%s q=%s primary=%s",
                group_id,
                query,
                str(primary_exc),
            )
            raise HTTPException(status_code=500, detail="Talabalar ro'yxatini yuklab bo'lmadi")
    conn.close()
    return {"items": [_serialize_user_row_light(r) for r in rows]}


