@app.post("/admin/groups/{group_id}/temporary-assignments")
async def admin_create_temporary_assignment(
    group_id: int,
    payload: TemporaryAssignmentRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    owner_teacher_id = int(group.get("teacher_id") or 0)
    if owner_teacher_id <= 0:
        raise HTTPException(status_code=400, detail="Group has no assigned teacher")
    temp_teacher, temp_role, group_subject = _validate_temporary_assignee_for_group(group, int(payload.temp_teacher_id))
    slots = _resolve_temporary_assignment_slots(group, payload)
    assignment_ids, skipped_existing = _create_temporary_assignments_for_slots(
        int(group_id),
        owner_teacher_id=owner_teacher_id,
        temp_teacher_id=int(payload.temp_teacher_id),
        slots=slots,
    )
    if not assignment_ids:
        raise HTTPException(status_code=409, detail="Active temporary assignment already exists for selected lessons")
    support_side_effects = {"blocked_slots": 0, "cancelled_bookings": 0}
    if temp_role == "support":
        support_side_effects = await _apply_support_temp_assignment_side_effects(
            group=group,
            support_teacher_id=int(payload.temp_teacher_id),
            subject=group_subject,
            owner_teacher_id=owner_teacher_id,
            slots=slots,
            assignment_ids=assignment_ids,
        )
    return {
        "message": "Temporary assignment created",
        "assignment_id": int(assignment_ids[0]),
        "assignment_ids": assignment_ids,
        "created_count": len(assignment_ids),
        "skipped_existing": int(skipped_existing),
        **support_side_effects,
    }


@app.delete("/admin/groups/{group_id}/temporary-assignments/{temp_teacher_id}")
async def admin_cancel_temporary_assignments(
    group_id: int,
    temp_teacher_id: int,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if not _can_manage_group(admin_ref, group):
        raise HTTPException(status_code=403, detail="Permission denied")
    owner_teacher_id = int(group.get("teacher_id") or 0)
    temp_teacher, temp_role, group_subject = _validate_temporary_assignee_for_group(group, int(temp_teacher_id))
    active_rows = _safe_call(lambda: get_active_temporary_assignments_for_pair(owner_teacher_id, int(group_id), int(temp_teacher_id)), []) or []
    slots = [
        {"lesson_date": str(row.get("lesson_date") or ""), "lesson_start": row.get("lesson_start"), "lesson_end": row.get("lesson_end")}
        for row in active_rows
        if int(row.get("group_id") or 0) == int(group_id)
    ]
    cancelled = cancel_temporary_assignments_for_pair(owner_teacher_id, int(group_id), int(temp_teacher_id))
    released = _release_support_temp_blocks(int(temp_teacher_id), group_subject, int(group_id), slots) if temp_role == "support" else 0
    return {"message": "Temporary assignments cancelled", "cancelled": int(cancelled), "released_slots": int(released)}


@app.get("/admin/attendance")
async def admin_attendance(
    group_id: int = Query(...),
    date: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin", "teacher", "support"})
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    group = _safe_call(lambda: get_group(int(group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if role == "admin":
        admin_ref = _admin_ref_id(user)
        if not _can_manage_group(admin_ref, group):
            raise HTTPException(status_code=403, detail="Permission denied")
    else:
        if not _teacher_can_manage_group(user, group):
            raise HTTPException(status_code=403, detail="Teacher can only view own or temporary groups")

    day = str(date or _now_tashkent_date())
    _raise_if_holiday_otmen_day(day)
    _ensure_attendance_window_open(group, day)
    records = _safe_call(lambda: get_attendance_by_group(int(group_id), day), []) or []
    by_user = {int(r.get("user_id") or 0): str(r.get("status") or "-") for r in records}
    members = _enrich_user_rows_with_face_profiles(_safe_call(lambda: get_group_users(int(group_id)), []) or [])
    rows = []
    for member in members:
        uid = int(member.get("id") or 0)
        if int(member.get("login_type") or 0) not in (1, 2):
            continue
        avatar_url = (
            str(member.get("profile_image_url") or "").strip()
            or str(member.get("effective_profile_image_url") or "").strip()
            or str(member.get("face_reference_image_url") or "").strip()
            or None
        )
        rows.append(
            {
                "user_id": uid,
                "full_name": _display_name(member),
                "avatar_url": avatar_url,
                "profile_image_url": avatar_url,
                "status": by_user.get(uid, "-"),
            }
        )
    return {"group_id": int(group_id), "date": day, "items": rows}


