@app.post("/admin/attendance/mark")
async def admin_mark_attendance(payload: AttendanceMarkRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin", "teacher", "support"})
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    group = _safe_call(lambda: get_group(int(payload.group_id)), None)
    if not group:
        raise HTTPException(status_code=404, detail="Group not found")
    if role == "admin":
        admin_ref = _admin_ref_id(user)
        student = _safe_call(lambda: get_user_by_id(int(payload.user_id)), None)
        if not _can_manage_group(admin_ref, group) or not _can_manage_user_globally(admin_ref, student):
            raise HTTPException(status_code=403, detail="Permission denied")
    else:
        if not _teacher_can_manage_group(user, group):
            raise HTTPException(status_code=403, detail="Teacher can only manage own or temporary groups")

    _raise_if_holiday_otmen_day(str(payload.date))
    _ensure_attendance_mark_allowed(group, int(payload.group_id), int(payload.user_id), str(payload.date))
    status = _normalize_attendance_status(str(payload.status))
    subject_hint = _normalize_subject_label(str((group or {}).get("subject") or "")) or None
    effect = _sync_attendance_effect(int(payload.user_id), int(payload.group_id), str(payload.date), status, subject_hint)
    add_attendance(int(payload.user_id), int(payload.group_id), str(payload.date), status=status)
    _payment_invalidate_attendance_scope(
        user_ids=[int(payload.user_id)],
        group_id=int(payload.group_id),
        lesson_date=str(payload.date),
        reason="admin_attendance_mark",
    )
    return {
        "message": "Attendance marked",
        "status": status,
        "dpoints_delta": float(effect.get("applied_delta_dpoints") or 0.0),
        "effect": effect,
    }


