@app.post("/admin/student-shares")
async def admin_share_student(payload: StudentShareRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    actor = _admin_ref_id(user)
    student = _safe_call(lambda: get_user_by_id(int(payload.student_id)), None)
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")
    if not _can_manage_user(actor, student):
        raise HTTPException(status_code=403, detail="Permission denied")
    ok, error_key = share_student_between_admins(int(payload.student_id), int(payload.peer_admin_id), int(actor))
    if not ok:
        raise HTTPException(status_code=400, detail=f"Share failed: {error_key}")
    return {"message": "Student shared", "student_id": int(payload.student_id), "peer_admin_id": int(payload.peer_admin_id)}


