@app.get("/admin/article-permissions")
async def admin_article_permissions(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    users = _safe_call(get_all_users, []) or []
    target_users = [u for u in users if int(u.get("login_type") or 0) in (3, 5)]
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT user_id, can_create FROM web_article_permissions")
    perm_rows = {int(r.get("user_id") or 0): int(r.get("can_create") or 0) for r in (cur.fetchall() or [])}
    conn.close()
    out = []
    for tu in target_users:
        uid = int(tu.get("id") or 0)
        out.append(
            {
                "user_id": uid,
                "full_name": _display_name(tu),
                "role": _role_from_login_type(int(tu.get("login_type") or 0), str(tu.get("login_id") or "")),
                "can_create": bool(perm_rows.get(uid, 1)),
            }
        )
    return {"items": out}


@app.post("/admin/article-permissions/{user_id}")
async def admin_set_article_permission(user_id: int, payload: ArticlePermissionRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    target = _safe_call(lambda: get_user_by_id(int(user_id)), None)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if int(target.get("login_type") or 0) not in (3, 5):
        raise HTTPException(status_code=400, detail="Only teacher/support users can receive article permissions")
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO web_article_permissions (user_id, can_create, updated_by, updated_at)
        VALUES (?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(user_id) DO UPDATE SET
            can_create=excluded.can_create,
            updated_by=excluded.updated_by,
            updated_at=CURRENT_TIMESTAMP
        """,
        (int(user_id), 1 if payload.can_create else 0, int(user.get("id") or 0)),
    )
    conn.commit()
    conn.close()
    return {"message": "Article permission updated", "user_id": int(user_id), "can_create": bool(payload.can_create)}
@app.post("/admin/sms/send")
async def admin_sms_send(req: SmsSendRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    
    token = os.environ.get("ESKIZ_TOKEN")
    if not token:
        raise HTTPException(status_code=500, detail="ESKIZ_TOKEN is not configured in .env")
    
    url = "https://notify.eskiz.uz/api/message/sms/send"
    headers = {
        "Authorization": f"Bearer {token}"
    }
    
    data = aiohttp.FormData()
    clean_phone = req.phone_number.replace("+", "").replace(" ", "").strip()
    data.add_field("mobile_phone", clean_phone)
    data.add_field("message", req.message)
    data.add_field("from", "4546")
    
    async with aiohttp.ClientSession() as session:
        async with session.post(url, headers=headers, data=data) as response:
            if response.status != 200:
                text = await response.text()
                raise HTTPException(status_code=400, detail=f"Eskiz API Error: {text}")
            return {"success": True, "message": "SMS sent successfully"}



