@app.post("/admin/broadcasts")
async def admin_create_broadcast(payload: BroadcastCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    _ensure_web_tables()

    text = (payload.message_text or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Broadcast message cannot be empty")
    button_text = (payload.button_text or "").strip() or None
    button_url = (payload.button_url or "").strip() or None
    if (button_text and not button_url) or (button_url and not button_text):
        raise HTTPException(status_code=400, detail="Both button text and button URL are required together")
    if button_url and not re.match(r"^https?://", button_url, flags=re.IGNORECASE):
        raise HTTPException(status_code=400, detail="Button URL must start with http:// or https://")

    recipients: list[dict] = []
    all_users = _safe_call(get_all_users, []) or []
    scoped_users = all_users
    if payload.target_type == "all_students":
        recipients = [u for u in scoped_users if int(u.get("login_type") or 0) in (1, 2) and str(u.get("telegram_id") or "").strip()]
        from db import get_active_telegram_group_chats
        recipients.extend(_safe_call(get_active_telegram_group_chats, []) or [])
    elif payload.target_type == "all_teachers":
        recipients = [u for u in scoped_users if int(u.get("login_type") or 0) in (3, 5) and str(u.get("telegram_id") or "").strip()]
    elif payload.target_type == "all_users":
        recipients = [u for u in scoped_users if str(u.get("telegram_id") or "").strip()]
        from db import get_active_telegram_group_chats
        recipients.extend(_safe_call(get_active_telegram_group_chats, []) or [])

    elif payload.target_type == "by_group":
        if not payload.group_ids:
            raise HTTPException(status_code=400, detail="group_ids are required for by_group target")
        seen_ids: set[int] = set()
        for gid in payload.group_ids:
            group_row = _safe_call(lambda group_id=int(gid): get_group(group_id), None)
            if not _can_manage_group(admin_ref, group_row):
                continue
            for member in _safe_call(lambda group_id=int(gid): get_group_users(group_id), []) or []:
                uid = int(member.get("id") or 0)
                if uid and uid not in seen_ids and str(member.get("telegram_id") or "").strip():
                    seen_ids.add(uid)
                    recipients.append(member)
    else:
        if not payload.user_ids:
            raise HTTPException(status_code=400, detail="user_ids are required for custom_users target")
        for uid in payload.user_ids:
            row = _safe_call(lambda user_id=int(uid): get_user_by_id(user_id), None)
            if row and str(row.get("telegram_id") or "").strip():
                recipients.append(row)

    deduped: list[dict] = []
    seen_tg: set[str] = set()
    for recipient in recipients:
        tg = str(recipient.get("telegram_id") or "").strip()
        if not tg or tg in seen_tg:
            continue
        seen_tg.add(tg)
        deduped.append(recipient)

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO web_broadcasts
        (creator_user_id, target_type, target_ids_json, message_text, button_text, button_url, status, total_recipients)
        VALUES (?, ?, ?, ?, ?, ?, 'queued', ?)
        RETURNING id
        """,
        (
            int(user.get("id") or 0),
            payload.target_type,
            json.dumps({"group_ids": payload.group_ids, "user_ids": payload.user_ids}),
            text,
            button_text,
            button_url,
            int(len(deduped)),
        ),
    )
    row = cur.fetchone()
    conn.commit()
    conn.close()
    broadcast_id = int(row.get("id") or 0) if row else 0

    task = asyncio.create_task(
        _run_broadcast_job(
            broadcast_id=broadcast_id,
            message_text=text,
            recipients=deduped,
            button_text=button_text,
            button_url=button_url,
            button_type=payload.button_type,
        )
    )
    BROADCAST_TASKS[broadcast_id] = task
    return {"message": "Broadcast queued", "broadcast_id": broadcast_id, "recipient_count": len(deduped)}


