@app.post("/support/broadcasts")
async def support_create_broadcast(payload: BroadcastCreateRequest, authorization: str | None = Header(default=None)):
    """Support teacher o'z fanlari bo'yicha student'larga broadcast yuboradi."""
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"support", "admin"})
    _ensure_web_tables()

    text = (payload.message_text or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Broadcast message cannot be empty")
    button_text = (payload.button_text or "").strip() or None
    button_url = (payload.button_url or "").strip() or None
    if (button_text and not button_url) or (button_url and not button_text):
        raise HTTPException(status_code=400, detail="Both button text and button URL are required together")
    if button_url and not re.match(r"^https?://", button_url, flags=re.IGNORECASE):
        raise HTTPException(status_code=400, detail="Button URL must start with http:// or https://")

    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    all_users = _safe_call(get_all_users, []) or []

    # Support teacher can only broadcast to students of their subjects
    support_subjects = _support_actor_subjects(user) if role == "support" else []

    recipients: list[dict] = []
    if payload.target_type == "all_students":
        if role == "support" and support_subjects:
            # Filter students who have active/past bookings for support teacher's subjects
            from db import list_lesson_bookings
            bookings, _ = _safe_call(lambda: list_lesson_bookings(status=None, page=1, per_page=500), ([], 1))
            student_ids_with_booking: set[int] = set()
            for bk in (bookings or []):
                subj = _normalize_subject_label(str(bk.get("support_subject") or ""))
                if subj in support_subjects:
                    sid = int(bk.get("student_user_id") or 0)
                    if sid:
                        student_ids_with_booking.add(sid)
            if student_ids_with_booking:
                recipients = [
                    u for u in all_users
                    if int(u.get("id") or 0) in student_ids_with_booking
                    and str(u.get("telegram_id") or "").strip()
                ]
            else:
                # Fallback: all students if no bookings found
                recipients = [u for u in all_users if int(u.get("login_type") or 0) in (1, 2) and str(u.get("telegram_id") or "").strip()]
        else:
            recipients = [u for u in all_users if int(u.get("login_type") or 0) in (1, 2) and str(u.get("telegram_id") or "").strip()]
    elif payload.target_type == "all_users":
        recipients = [u for u in all_users if str(u.get("telegram_id") or "").strip()]
    elif payload.target_type == "custom_users":
        if not payload.user_ids:
            raise HTTPException(status_code=400, detail="user_ids are required for custom_users target")
        for uid in payload.user_ids:
            row = _safe_call(lambda user_id=int(uid): get_user_by_id(user_id), None)
            if row and str(row.get("telegram_id") or "").strip():
                recipients.append(row)
    else:
        recipients = [u for u in all_users if int(u.get("login_type") or 0) in (1, 2) and str(u.get("telegram_id") or "").strip()]

    deduped: list[dict] = []
    seen_tg: set[str] = set()
    for recipient in recipients:
        tg = str(recipient.get("telegram_id") or "").strip()
        if not tg or tg in seen_tg:
            continue
        seen_tg.add(tg)
        deduped.append(recipient)

    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO web_broadcasts
        (creator_user_id, target_type, target_ids_json, message_text, button_text, button_url, status, total_recipients)
        VALUES (?, ?, ?, ?, ?, ?, 'queued', ?)
        RETURNING id
        """,
        (
            int(user.get("id") or 0),
            payload.target_type,
            json.dumps({"user_ids": payload.user_ids}),
            text,
            button_text,
            button_url,
            int(len(deduped)),
        ),
    )
    row = cur.fetchone()
    conn.commit()
    conn.close()
    broadcast_id = int(row.get("id") or 0) if row else 0

    task = asyncio.create_task(
        _run_broadcast_job(
            broadcast_id=broadcast_id,
            message_text=text,
            recipients=deduped,
            button_text=button_text,
            button_url=button_url,
            button_type=payload.button_type,
        )
    )
    BROADCAST_TASKS[broadcast_id] = task
    return {"message": "Broadcast queued", "broadcast_id": broadcast_id, "recipient_count": len(deduped)}


