@app.put("/admin/surveys/{survey_id}")
async def admin_update_survey(survey_id: int, payload: SurveyCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    
    questions_json = json.dumps([q.dict() for q in payload.questions])
    conn = get_conn()
    cur = conn.cursor()
    
    cur.execute("SELECT id FROM web_surveys WHERE id=?", (int(survey_id),))
