@app.post("/survey/{survey_id}/submit")
async def submit_survey(survey_id: int, payload: SurveySubmitRequest, req: Request, authorization: str | None = Header(default=None)):
    user = None
    if authorization and authorization != "Bearer null":
        try:
            user = _user_row_from_bearer(authorization)
        except Exception:
            pass

    tg_user = payload.telegram_user or {}
    tg_id_str = str(tg_user.get("id") or "").strip()

    if not user and tg_id_str:
        user = _safe_call(lambda: get_user_by_telegram(tg_id_str), None)

    if tg_id_str:
        tg_first = (tg_user.get("first_name") or "").strip()
        tg_last = (tg_user.get("last_name") or "").strip()
        tg_full = f"{tg_first} {tg_last}".strip()
        tg_uname = (tg_user.get("username") or "").strip()
        _safe_call(lambda: upsert_lesson_user(tg_id_str, first_name=tg_first, username=tg_uname, full_name=tg_full), None)

    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    
    # Generate negative random user_id for anonymous to bypass UNIQUE(survey_id, user_id)
    user_id = int(user.get("id") or 0) if user else -random.randint(1, 2**31 - 1)
    tg_user_json = json.dumps(tg_user) if tg_user else None

    # Check if this user or telegram_id already submitted
    if user_id > 0:
        cur.execute("SELECT id FROM web_survey_responses WHERE survey_id=? AND user_id=?", (int(survey_id), user_id))
        if cur.fetchone():
            conn.close()
            raise HTTPException(status_code=400, detail="Siz ushbu so'rovnomaga allaqachon javob bergansiz")

    if tg_id_str:
        try:
            cur.execute("SELECT id FROM web_survey_responses WHERE survey_id=? AND telegram_id=?", (int(survey_id), tg_id_str))
            if cur.fetchone():
                conn.close()
                raise HTTPException(status_code=400, detail="Siz ushbu so'rovnomaga allaqachon javob bergansiz")
        except Exception:
            try: conn.rollback()
            except Exception: pass

    user_agent = req.headers.get("user-agent")
    if user_agent:
        payload.answers["__device_info__"] = user_agent

    try:
        cur.execute(
            """
            INSERT INTO web_survey_responses (survey_id, user_id, answers_json, telegram_id, tg_user_json)
            VALUES (?, ?, ?, ?, ?)
            """,
            (int(survey_id), user_id, json.dumps(payload.answers), tg_id_str or None, tg_user_json)
        )
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        try:
            cur.execute(
                """
                INSERT INTO web_survey_responses (survey_id, user_id, answers_json)
                VALUES (?, ?, ?)
                """,
                (int(survey_id), user_id, json.dumps(payload.answers))
            )
            conn.commit()
        except Exception as inner_e:
            try: conn.rollback()
            except Exception: pass
            conn.close()
            err_str = str(e) + " " + str(inner_e)
            if "UNIQUE" in err_str or "unique" in err_str.lower():
                raise HTTPException(status_code=400, detail="Siz ushbu so'rovnomaga allaqachon javob bergansiz")
            raise HTTPException(status_code=500, detail=str(inner_e))

    conn.close()
    return {"message": "Survey submitted successfully"}






def _dns_short(record_type: str, name: str) -> list[str]:
    dig = shutil.which("dig")
    if not dig:
        return []
    try:
        result = subprocess.run(
            [dig, "+short", name, record_type],
            check=False,
            capture_output=True,
            text=True,
            timeout=4,
        )
    except Exception:
        return []
    if result.returncode != 0:
        return []
    return [line.strip() for line in result.stdout.splitlines() if line.strip()]


def _service_active(service_name: str) -> bool:
    systemctl = shutil.which("systemctl")
    if not systemctl:
        return False
    try:
        result = subprocess.run(
            [systemctl, "is-active", "--quiet", service_name],
            check=False,
            capture_output=True,
            timeout=3,
        )
        return result.returncode == 0
    except Exception:
        return False


def _listening_tcp_ports() -> set[int]:
    ss = shutil.which("ss")
    if not ss:
        return set()
    try:
        result = subprocess.run(
            [ss, "-ltn"],
            check=False,
            capture_output=True,
            text=True,
            timeout=3,
        )
    except Exception:
        return set()
    ports: set[int] = set()
    for line in result.stdout.splitlines():
        parts = line.split()
        if len(parts) < 4:
            continue
        local = parts[3]
        match = re.search(r":(\d+)$", local)
        if match:
            try:
                ports.add(int(match.group(1)))
            except Exception:
                continue
    return ports


def _postfix_catch_all_target(domain: str) -> str | None:
    candidates = [
        Path("/etc/postfix/virtual"),
        Path("/etc/postfix/virtual-regexp"),
        Path("/etc/postfix/virtual_regex"),
    ]
    wanted = f"@{domain}".lower()
    for path in candidates:
        try:
            if not path.exists() or not path.is_file():
                continue
            for raw_line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#"):
                    continue
                lowered = line.lower()
                if wanted in lowered or domain.lower().replace(".", r"\.") in lowered:
                    parts = re.split(r"\s+", line, maxsplit=1)
                    if len(parts) == 2:
                        return parts[1].strip()
        except Exception:
            continue
    return None


def _postfix_transport_target(domain: str) -> str | None:
    for path in (Path("/etc/postfix/transport"),):
        try:
            if not path.exists() or not path.is_file():
                continue
            for raw_line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = re.split(r"\s+", line, maxsplit=1)
                if len(parts) == 2 and parts[0].strip().lower() == domain.lower():
                    return parts[1].strip()
        except Exception:
            continue
    return None


def _inbound_email_status_counts() -> dict:
    _ensure_web_tables()
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status='unread' THEN 1 ELSE 0 END) AS unread,
                MAX(received_at) AS last_received_at
            FROM inbound_emails
            """
        )
        row = _row_to_dict(cur.fetchone()) or {}
        return {
            "total": int(row.get("total") or 0),
            "unread": int(row.get("unread") or 0),
            "last_received_at": _as_iso_timestamp(row.get("last_received_at")),
        }
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return {"total": 0, "unread": 0, "last_received_at": None}
    finally:
        conn.close()


def _serialize_inbound_email(row: dict, include_body: bool = False) -> dict:
    payload = {
        "id": int(row.get("id") or 0),
        "recipient": str(row.get("recipient") or "").strip(),
        "sender": str(row.get("sender") or "").strip(),
        "subject": str(row.get("subject") or "").strip(),
        "message_id": str(row.get("message_id") or "").strip() or None,
        "has_attachments": int(row.get("has_attachments") or 0) == 1,
        "attachment_count": int(row.get("attachment_count") or 0),
        "status": str(row.get("status") or "unread").strip() or "unread",
        "received_at": _as_iso_timestamp(row.get("received_at")),
        "created_at": _as_iso_timestamp(row.get("created_at")),
        "replied_at": _as_iso_timestamp(row.get("replied_at")) if row.get("replied_at") else None,
        "reply_content": str(row.get("reply_content") or "").strip() if row.get("reply_content") else None,
    }
    if include_body:
        payload["text_body"] = str(row.get("text_body") or "")
        payload["html_body_sanitized"] = str(row.get("html_body_sanitized") or "")
    return payload


@app.get("/admin/domain-email/status")
async def admin_domain_email_status(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    domain = "diamond-education.uz"
    mail_domain = f"mail.{domain}"
    mx_records = _dns_short("MX", domain)
    spf_records = [row for row in _dns_short("TXT", domain) if "v=spf1" in row.lower()]
    dmarc_records = _dns_short("TXT", f"_dmarc.{domain}")
    mail_a_records = _dns_short("A", mail_domain)
    postfix_active = _service_active("postfix")
    dovecot_active = _service_active("dovecot")
    ports = _listening_tcp_ports()
    smtp_ports = {str(port): port in ports for port in (25, 465, 587, 143, 993)}
    catch_all_target = _postfix_catch_all_target(domain) or _postfix_transport_target(domain)
    inbox_counts = _inbound_email_status_counts()
    mail_stack_active = postfix_active
    catch_all_status = "configured" if mail_stack_active and mx_records and smtp_ports.get("25") and catch_all_target else "not_configured"
    notes = []
    if catch_all_status == "configured":
        notes.append("Catch-all xabarlar serverda qabul qilinib, sayt ichidagi Admin inboxga saqlanadi.")
    else:
        if not postfix_active:
            notes.append("Postfix faol emas.")
        if not smtp_ports.get("25"):
            notes.append("SMTP 25-port tinglanmayapti yoki provider tomonidan bloklangan.")
        if not catch_all_target:
            notes.append("Postfix catch-all pipe/alias target topilmadi.")
        if not mx_records:
            notes.append("MX yozuvi topilmadi.")
    return {
        "domain": domain,
        "catch_all_status": catch_all_status,
        "mode": "local_inbox",
        "mail_stack": {
            "postfix_active": postfix_active,
            "dovecot_active": dovecot_active,
            "smtp_ports": smtp_ports,
        },
        "inbox": inbox_counts,
        "current": {
            "mx": mx_records,
            "spf": spf_records,
            "dmarc": dmarc_records,
            "mail_a": mail_a_records,
        },
        "required": {
            "mx": f"{domain}. MX 10 {mail_domain}.",
            "mail_a": f"{mail_domain}. A 31.220.87.193",
            "spf": f'{domain}. TXT "v=spf1 mx -all"',
            "dmarc": f'_dmarc.{domain}. TXT "v=DMARC1; p=quarantine; rua=mailto:postmaster@{domain}"',
        },
        "destination_inbox": "Admin Email Inbox",
        "postfix_target": catch_all_target,
        "notes": notes,
    }


import smtplib
from email.message import EmailMessage

@app.post("/admin/domain-email/send")
async def admin_domain_email_send(
    payload: DomainEmailSendRequest,
    authorization: str | None = Header(default=None)
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    
    sender_email = f"{payload.alias}@diamond-education.uz"
    sender_name = "Diamond Info" if payload.alias == "info" else "Diamond Admin"
    from_address = f'"{sender_name}" <{sender_email}>'

    msg = EmailMessage()
    msg['Subject'] = payload.subject
    msg['From'] = from_address
    msg['To'] = payload.to_email

    if payload.text_body and payload.html_body:
        msg.set_content(payload.text_body)
        msg.add_alternative(payload.html_body, subtype='html')
    elif payload.html_body:
        msg.set_content(payload.html_body, subtype='html')
    else:
        msg.set_content(payload.text_body or " ")

    try:
        # First try local postfix
        with smtplib.SMTP("127.0.0.1", 25, timeout=10) as server:
            server.send_message(msg)
    except Exception as e:
        # Fallback to configured SMTP if local fails
        smtp_host = os.getenv("SMTP_HOST")
        smtp_port = int(os.getenv("SMTP_PORT") or 587)
        smtp_user = os.getenv("SMTP_USER")
        smtp_pass = os.getenv("SMTP_PASSWORD")
        if smtp_host and smtp_user:
            try:
                with smtplib.SMTP(smtp_host, smtp_port, timeout=15) as server:
                    server.starttls()
                    server.login(smtp_user, smtp_pass)
                    server.send_message(msg)
            except Exception as inner_e:
                raise HTTPException(status_code=500, detail=f"Email jo'natib bo'lmadi (local/external): {inner_e}")
        else:
            raise HTTPException(status_code=500, detail=f"Email jo'natib bo'lmadi: local smtp ishlamayapti va external smtp sozlanmagan. Xato: {e}")

    return {"message": "Email muvaffaqiyatli jo'natildi"}


@app.post("/admin/domain-email/inbox/{email_id}/reply")
async def admin_domain_email_reply(
    email_id: int,
    payload: DomainEmailReplyRequest,
    authorization: str | None = Header(default=None)
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})

    with sqlite3.connect("db.sqlite3") as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("SELECT * FROM inbound_emails WHERE id=? LIMIT 1", (email_id,))
        email = cur.fetchone()
        if not email:
            raise HTTPException(status_code=404, detail="Email topilmadi")
        
        reply_to_email = str(email["sender"]) if email["sender"] else None
        if not reply_to_email:
             raise HTTPException(status_code=400, detail="Jo'natuvchi manzili mavjud emas")

    sender_email = f"{payload.alias}@diamond-education.uz"
    sender_name = "Diamond Info" if payload.alias == "info" else "Diamond Admin"
    from_address = f'"{sender_name}" <{sender_email}>'

    msg = EmailMessage()
    msg['Subject'] = f"Re: {email['subject']}" if email["subject"] else "Re: Xabar"
    msg['From'] = from_address
    msg['To'] = reply_to_email

    msg.set_content(payload.reply_body)

    try:
        with smtplib.SMTP("127.0.0.1", 25, timeout=10) as server:
            server.send_message(msg)
    except Exception as e:
        smtp_host = os.getenv("SMTP_HOST")
        smtp_port = int(os.getenv("SMTP_PORT") or 587)
        smtp_user = os.getenv("SMTP_USER")
        smtp_pass = os.getenv("SMTP_PASSWORD")
        if smtp_host and smtp_user:
            try:
                with smtplib.SMTP(smtp_host, smtp_port, timeout=15) as server:
                    server.starttls()
                    server.login(smtp_user, smtp_pass)
                    server.send_message(msg)
            except Exception as inner_e:
                raise HTTPException(status_code=500, detail=f"Javob jo'natib bo'lmadi (local/external): {inner_e}")
        else:
            raise HTTPException(status_code=500, detail=f"Javob jo'natib bo'lmadi: {e}")

    with sqlite3.connect("db.sqlite3") as conn:
        cur = conn.cursor()
        cur.execute("UPDATE inbound_emails SET reply_content=?, replied_at=CURRENT_TIMESTAMP WHERE id=?", (payload.reply_body, email_id))
        conn.commit()

    return {"message": "Javob xati muvaffaqiyatli jo'natildi"}

@app.get("/admin/domain-email/inbox")
async def admin_domain_email_inbox(
    page: int = Query(default=1, ge=1),
    limit: int = Query(default=20, ge=1, le=100),
    status: str | None = Query(default=None),
    search: str | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    _ensure_web_tables()
    safe_status = str(status or "all").strip().lower()
    if safe_status not in {"all", "unread", "read", "archived"}:
        safe_status = "all"
    offset = (int(page) - 1) * int(limit)
    where = ["1=1"]
    params: list[Any] = []
    if safe_status != "all":
        where.append("status=?")
        params.append(safe_status)
    q = str(search or "").strip()
    if q:
        like = f"%{q.lower()}%"
        where.append("(LOWER(COALESCE(recipient,'')) LIKE ? OR LOWER(COALESCE(sender,'')) LIKE ? OR LOWER(COALESCE(subject,'')) LIKE ? OR LOWER(COALESCE(text_body,'')) LIKE ?)")
        params.extend([like, like, like, like])
    where_sql = " AND ".join(where)
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(f"SELECT COUNT(*) AS total FROM inbound_emails WHERE {where_sql}", tuple(params))
        total_row = _row_to_dict(cur.fetchone()) or {}
        cur.execute(
            f"""
            SELECT id, recipient, sender, subject, message_id, has_attachments, attachment_count, status, received_at, created_at
            FROM inbound_emails
            WHERE {where_sql}
            ORDER BY received_at DESC, id DESC
            LIMIT ? OFFSET ?
            """,
            tuple([*params, int(limit), int(offset)]),
        )
        rows = [_serialize_inbound_email(_row_to_dict(row) or {}) for row in (cur.fetchall() or [])]
        return {
            "items": rows,
            "page": int(page),
            "limit": int(limit),
            "total": int(total_row.get("total") or 0),
            "has_more": offset + len(rows) < int(total_row.get("total") or 0),
        }
    finally:
        conn.close()


