@app.post("/admin/system/wipe-database")
async def admin_wipe_database(payload: WipeDatabaseRequest, authorization: str | None = Header(default=None)):
    raise HTTPException(status_code=403, detail="Database wipe is disabled by policy")
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    if not _is_main_admin(admin_ref):
        raise HTTPException(status_code=403, detail="Only main admins can wipe database")
    if (payload.confirm_phrase or "").strip().upper() != "I UNDERSTAND":
        raise HTTPException(status_code=400, detail="confirm_phrase must be exactly 'I UNDERSTAND'")
    secret = (payload.secret or "").strip()
    expected = (DIAMONDVOY_DB_RESET_SECRET or "").strip()
    if not expected or secret != expected:
        raise HTTPException(status_code=403, detail="Invalid reset secret")
    _safe_call(wipe_postgresql_database_and_reinit, None)
    _safe_call(init_db, None)
    _safe_call(_ensure_web_tables, None)
    return {"message": "Database wiped and reinitialized"}


