@app.patch("/support/manage/schedule")
async def support_manage_schedule_update(payload: SupportSubjectScheduleRequest, authorization: str | None = Header(default=None)):
    user = _require_support_management_user(authorization)
    selected_subject = _require_support_subject_access(user, payload.subject)
    teacher_id = _support_teacher_id_for_management(user, selected_subject)
    if teacher_id <= 0:
        raise HTTPException(status_code=409, detail="No support teacher found for selected subject")
    weekdays = sorted({int(day) for day in (payload.weekdays or []) if 0 <= int(day) <= 5})
    if not weekdays:
        raise HTTPException(status_code=400, detail="At least one weekday is required")
    current = {int(row["weekday"]): row for row in _support_weekday_settings_for_teacher(teacher_id, selected_subject)}
    for weekday in range(0, 6):
        branch_key = str((current.get(weekday) or {}).get("branch") or _default_support_branch_for_weekday(weekday))
        _upsert_support_weekday_setting(
            teacher_id,
            selected_subject,
            weekday,
            active=weekday in weekdays,
            branch=branch_key,
            updated_by=int(user.get("id") or 0),
        )
    rows = _support_weekday_settings_for_teacher(teacher_id, selected_subject)
    return {"subject": selected_subject, "support_teacher_id": teacher_id, "items": rows, "weekdays": weekdays}


@app.get("/support/manage/calendar")
async def support_manage_calendar(
    subject: str,
    days_ahead: int = Query(default=21, ge=1, le=60),
    authorization: str | None = Header(default=None),
):
    user = _require_support_management_user(authorization)
    selected_subject = _require_support_subject_access(user, subject)
    teacher_id = _support_teacher_id_for_management(user, selected_subject)
    today = datetime.now(TASHKENT_TZ).date()
    calendar_days = [today + timedelta(days=i) for i in range(0, int(days_ahead))]
    date_keys = [day.isoformat() for day in calendar_days if day.weekday() != 6]
    override_map = _support_teacher_date_overrides_map([teacher_id], selected_subject, date_keys) if teacher_id else {}
    rows: list[dict] = []
    for day in calendar_days:
        if day.weekday() == 6:
            continue
        iso = day.isoformat()
        override = override_map.get((teacher_id, iso)) if teacher_id else None
        rows.append(
            {
                "date": iso,
                "weekday": _weekday_short_name(iso),
                "closed": bool(override and int(override.get("is_closed") or 0) == 1),
                "closed_reason": str((override or {}).get("reason") or "").strip() or None,
                "locked": bool(override and int(override.get("is_closed") or 0) == 1),
                "is_open_override": bool(override and int(override.get("is_closed") or 0) == 0),
            }
        )
    return {"subject": selected_subject, "support_teacher_id": teacher_id, "items": rows}


