@app.get("/support/manage/hours")
async def support_manage_hours(
    subject: str,
    weekday: int | None = Query(default=None),
    authorization: str | None = Header(default=None),
):
    user = _require_support_management_user(authorization)
    selected_subject = _require_support_subject_access(user, subject)
    teacher_id = _support_teacher_id_for_management(user, selected_subject)
    if teacher_id <= 0:
        return {"subject": selected_subject, "support_teacher_id": None, "items": []}
    weekdays = [int(weekday)] if weekday is not None else list(range(0, 6))
    items: list[dict] = []
    for wd in weekdays:
        if wd < 0 or wd > 5:
            continue
        active_times = set(_support_teacher_active_times(teacher_id, selected_subject, wd))
        explicit = {normalize_time_hhmm(str(row.get("time") or "")): row for row in _support_teacher_time_rows(teacher_id, selected_subject, wd)}
        for tm in sorted(set(SUPPORT_MANAGE_TIME_OPTIONS) | set(SUPPORT_DEFAULT_TIMES) | set(explicit.keys()) | active_times):
            if not tm:
                continue
            row = explicit.get(tm) or {}
            is_default = tm in set(SUPPORT_DEFAULT_TIMES)
            is_explicit = bool(row)
            items.append(
                {
                    "weekday": wd,
                    "time": tm,
                    "active": tm in active_times,
                    "addable": not is_default and not is_explicit and tm not in active_times,
                    "source": "custom" if is_explicit else ("default" if is_default else "candidate"),
                    "updated_at": row.get("updated_at"),
                }
            )
    return {"subject": selected_subject, "support_teacher_id": teacher_id, "items": items}


