def _support_booking_rows_for_actor(user: dict, mode: str, subject: str | None = None, limit: int = 80) -> list[dict]:
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role not in {"support", "admin"}:
        raise HTTPException(status_code=403, detail="Permission denied")
    subjects = _support_actor_subjects(user)
    selected_subject = _normalize_subject_label(subject)
    if selected_subject:
        _require_support_subject_access(user, selected_subject)
        subjects = [selected_subject]
    now_iso = _now_utc().isoformat()
    where: list[str] = []
    vals: list[Any] = []
    if role == "support":
        if not subjects:
            return []
        placeholders = ",".join("?" for _ in subjects)
        where.append(f"(support_teacher_id=? OR (support_teacher_id IS NULL AND support_subject IN ({placeholders})))")
        vals.extend([int(user.get("id") or 0), *subjects])
    elif subjects:
        placeholders = ",".join("?" for _ in subjects)
        where.append(f"support_subject IN ({placeholders})")
        vals.extend(subjects)
    if mode == "upcoming":
        where.append("status IN ('pending','approved')")
        where.append("(start_ts IS NULL OR start_ts >= ?)")
        vals.append(now_iso)
        order_by = "start_ts ASC, created_at DESC"
    elif mode == "bonus":
        window_start = (_now_utc() - timedelta(hours=3)).isoformat()
        where.append("status IN ('approved','passed')")
        where.append("end_ts IS NOT NULL AND end_ts <= ? AND end_ts >= ?")
        vals.extend([now_iso, window_start])
        order_by = "end_ts DESC, created_at DESC"
    else:
        window_start = (_now_utc() - timedelta(days=14)).isoformat()
        where.append("status IN ('pending','approved')")
        where.append("(end_ts IS NULL OR end_ts >= ?)")
        vals.append(window_start)
        order_by = "start_ts ASC, created_at DESC"
    q = "SELECT * FROM lesson_bookings"
    if where:
        q += " WHERE " + " AND ".join(where)
    q += f" ORDER BY {order_by} LIMIT ?"
    vals.append(max(1, min(200, int(limit or 80))))
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(q, tuple(vals))
        return [dict(row) for row in (cur.fetchall() or [])]
    except Exception:
        logger.exception("support booking list failed mode=%s subject=%s", mode, subject)
        return []
    finally:
        conn.close()


