@app.post("/admin/holiday-otmen/cancel")
async def admin_holiday_otmen_cancel(payload: HolidayOtmenCancelRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    date_iso = _validate_iso_date(payload.date)
    reason = (payload.reason or "").strip() or None
    cancel_mode = (payload.mode or "").strip().lower()
    if cancel_mode not in {"auto", "manual"}:
        cancel_mode = "auto" if is_official_holiday_date(date_iso) else "manual"
    result = execute_otmen_for_date(
        date_iso,
        admin_user_id=int(user.get("id") or 0),
        reason_override=reason,
        cancel_mode=cancel_mode,
    )
    if not bool(result.get("ok")):
        _raise_holiday_otmen_result_error(result)
    await _notify_holiday_otmen_result(result)
    stats = result.get("stats") or {}
    return {
        "message": "Holiday cancellation executed",
        "date": date_iso,
        "reason": result.get("reason"),
        "mode": cancel_mode,
        "request_id": result.get("request_id"),
        "stats": stats,
    }


