def _validate_support_booking_reschedule_target(
    booking: dict,
    *,
    date_iso: str,
    time_hhmm: str,
    branch_key: str,
) -> tuple[str, str]:
    target_date = _validate_iso_date(date_iso)
    tm = normalize_time_hhmm(time_hhmm)
    if not tm:
        raise HTTPException(status_code=400, detail="Invalid time format")
    subject = _normalize_subject_label(str(booking.get("support_subject") or "")) or "English"
    teacher_id = int(booking.get("support_teacher_id") or 0)
    if teacher_id <= 0:
        teacher_id = _select_support_teacher_for_slot(subject, branch_key, target_date, tm) or 0
    if teacher_id <= 0:
        raise HTTPException(status_code=409, detail="No support teacher available for selected slot")
    try:
        weekday = datetime.strptime(target_date, "%Y-%m-%d").date().weekday()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid booking date")
    if weekday == 6:
        raise HTTPException(status_code=409, detail="Sunday bookings are not available")
    setting = _support_weekday_setting_for_teacher(teacher_id, subject, weekday)
    if not bool(setting.get("active")) or str(setting.get("branch") or "") != str(branch_key):
        raise HTTPException(status_code=409, detail="Selected date is not available for this support teacher")
    override = _support_teacher_date_override(teacher_id, subject, target_date)
    if override and int(override.get("is_closed") or 0) == 1:
        raise HTTPException(status_code=409, detail=str(override.get("reason") or "Selected date is closed"))
    if tm not in _support_teacher_active_times(teacher_id, subject, weekday, branch_key, target_date):
        raise HTTPException(status_code=409, detail="Selected time is closed for this support teacher")
    if _support_teacher_temp_slot_blocked(teacher_id, subject, target_date, tm):
        raise HTTPException(status_code=409, detail="Selected time is temporarily blocked")
    if is_lesson_holiday(target_date) or is_lesson_otmen_date_cancelled(target_date):
        raise HTTPException(status_code=409, detail="Selected date is closed due to holiday")
    if is_branch_date_closed_for_booking(branch_key, target_date):
        reason = get_branch_date_closed_reason(branch_key, target_date)
        raise HTTPException(status_code=409, detail=reason or "Selected date is closed")
    if is_slot_closed_effective(branch_key, target_date, tm):
        reason = get_slot_block_reason(branch_key, target_date, tm)
        raise HTTPException(status_code=409, detail=reason or "Selected time is closed")
    now_tz = datetime.now(TASHKENT_TZ)
    try:
        hh, mm = [int(x) for x in tm.split(":", 1)]
        date_obj = datetime.strptime(target_date, "%Y-%m-%d").date()
        local_dt = TASHKENT_TZ.localize(datetime.combine(date_obj, datetime.min.time().replace(hour=hh, minute=mm)))
        if local_dt <= now_tz:
            raise HTTPException(status_code=409, detail="Selected time already passed")
    except HTTPException:
        raise
    except Exception:
        pass
    start_ts = support_make_start_ts(target_date, tm)
    if not start_ts:
        raise HTTPException(status_code=400, detail="Invalid booking date/time")
    current_start = str(booking.get("start_ts") or "")
    if start_ts != current_start and not lesson_is_slot_free(start_ts):
        raise HTTPException(status_code=409, detail="Selected slot is already taken")
    return target_date, tm


def _suggest_support_slots(branch_key: str, date_iso: str, limit: int = 4) -> list[str]:
    recurring = _safe_call(lambda: list_recurring_open_times_for_date(branch_key, date_iso), []) or []
    extras = _safe_call(lambda: list_lesson_extra_slots_for_date(date_iso, branch_key), []) or []
    slots = sorted({normalize_time_hhmm(str(item or "")) for item in [*recurring, *extras] if normalize_time_hhmm(str(item or ""))})
    now_tz = datetime.now(TASHKENT_TZ)
    try:
        date_obj = datetime.strptime(date_iso, "%Y-%m-%d").date()
    except Exception:
        date_obj = None
    suggested: list[str] = []
    for slot in slots:
        tm = normalize_time_hhmm(str(slot or ""))
        if not tm:
            continue
        if is_slot_closed_effective(branch_key, date_iso, tm):
            continue
        start_ts = support_make_start_ts(date_iso, tm)
        if not start_ts or not lesson_is_slot_free(start_ts):
            continue
        if date_obj is not None:
            try:
                hh, mm = [int(x) for x in tm.split(":", 1)]
                local_dt = TASHKENT_TZ.localize(datetime.combine(date_obj, datetime.min.time().replace(hour=hh, minute=mm)))
                if date_obj == now_tz.date() and local_dt <= now_tz:
                    continue
            except Exception:
                pass
        suggested.append(tm)
        if len(suggested) >= limit:
            break
    return suggested


@app.post("/student/bookings")
async def create_student_booking(payload: BookingCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    support_subjects = _support_enabled_subjects_for_user(user)
    selected_subject = _normalize_subject_label(payload.subject) or (support_subjects[0] if support_subjects else None)
    if not selected_subject or selected_subject not in support_subjects:
        raise HTTPException(status_code=403, detail="Support lessons are available only for English subject")
    if not _has_active_support_teacher_for_subject(selected_subject):
        raise HTTPException(status_code=409, detail="No support teacher available for selected subject")

    guard = _student_support_booking_guard_payload(user_id, selected_subject)
    if guard.get("blocked"):
        if str(guard.get("block_type") or "") == "active_booking":
            raise HTTPException(status_code=409, detail="active_booking")
        unlock_at = str(guard.get("unlock_at") or "").strip()
        if unlock_at:
            raise HTTPException(status_code=409, detail=f"cooldown:{unlock_at}")
        raise HTTPException(status_code=409, detail="cooldown")

    branch_key = _validate_branch_key(payload.branch or "branch_1")
    date_iso = _validate_iso_date(payload.date)
    tm = normalize_time_hhmm(payload.time)
    if not tm:
        raise HTTPException(status_code=400, detail="Invalid time format")

    try:
        d = datetime.strptime(date_iso, "%Y-%m-%d").date()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid booking date")
    if d.weekday() == 6:
        raise HTTPException(status_code=409, detail="Sunday bookings are not available")
    
    candidates = _support_teacher_candidates_for_slot(selected_subject, branch_key, date_iso, tm)
    if not candidates:
        raise HTTPException(status_code=409, detail="Selected date is not available for this branch")
        
    support_teacher_id = None
    if payload.teacher_id and int(payload.teacher_id) > 0:
        valid_ids = {int(c.get("id") or 0) for c in candidates}
        if int(payload.teacher_id) in valid_ids:
            support_teacher_id = int(payload.teacher_id)
        else:
            raise HTTPException(status_code=409, detail="Selected teacher is not available for this slot")
    
    if not support_teacher_id:
        support_teacher_id = int(candidates[0].get("id") or 0) or None
        
    if not support_teacher_id:
        raise HTTPException(status_code=409, detail="Selected date is not available for this branch")
    if is_lesson_holiday(date_iso):
        raise HTTPException(status_code=409, detail="Selected date is closed due to holiday")
    if is_branch_date_closed_for_booking(branch_key, date_iso):
        reason = get_branch_date_closed_reason(branch_key, date_iso)
        if reason:
            raise HTTPException(status_code=409, detail=f"Selected date is closed: {reason}")
        raise HTTPException(status_code=409, detail="Selected date is closed")
    if is_slot_closed_effective(branch_key, date_iso, tm):
        reason = get_slot_block_reason(branch_key, date_iso, tm)
        alternatives = _suggest_support_slots(branch_key, date_iso)
        alternatives_text = f" Available slots: {', '.join(alternatives)}." if alternatives else ""
        if reason:
            raise HTTPException(status_code=409, detail=f"slot_closed: {reason}.{alternatives_text}".strip())
        raise HTTPException(status_code=409, detail=f"slot_closed: selected slot is closed.{alternatives_text}".strip())

    start_ts = support_make_start_ts(date_iso, tm)
    end_ts = support_make_end_ts(start_ts)
    if not start_ts:
        raise HTTPException(status_code=400, detail="Invalid booking date/time")
        
    slot_is_free = False
    if selected_subject:
        slot_is_free = lesson_is_slot_free_for_subject(selected_subject, date_iso, tm)
    else:
        slot_is_free = lesson_is_slot_free(start_ts)
        
    if not slot_is_free:
        alternatives = _suggest_support_slots(branch_key, date_iso)
        alternatives_text = f" Available slots: {', '.join(alternatives)}." if alternatives else ""
        raise HTTPException(status_code=409, detail=f"slot_taken: selected slot is already taken.{alternatives_text}".strip())

    now_tz = datetime.now(TASHKENT_TZ)
    try:
        hh, mm = [int(x) for x in tm.split(":", 1)]
        local_dt = TASHKENT_TZ.localize(datetime.combine(d, datetime.min.time().replace(hour=hh, minute=mm)))
        if d == now_tz.date() and local_dt <= now_tz:
            alternatives = _suggest_support_slots(branch_key, date_iso)
            alternatives_text = f" Available slots: {', '.join(alternatives)}." if alternatives else ""
            raise HTTPException(status_code=409, detail=f"time_passed: selected slot time already passed.{alternatives_text}".strip())
    except HTTPException:
        raise
    except Exception:
        pass

    booking_id = generate_lesson_booking_id()
    ok = create_lesson_booking_request(
        booking_id=booking_id,
        student_user_id=user_id,
        student_telegram_id=str(user.get("telegram_id") or "") or None,
        branch=branch_key,
        date_iso=date_iso,
        time_hhmm=tm,
        start_ts=start_ts,
        end_ts=end_ts,
        purpose=(payload.purpose or "General").strip(),
        subject=selected_subject,
        support_teacher_id=support_teacher_id,
    )
    if not ok:
        post_guard = _student_support_booking_guard_payload(user_id, selected_subject)
        if post_guard.get("blocked"):
            if str(post_guard.get("block_type") or "") == "active_booking":
                raise HTTPException(status_code=409, detail="active_booking")
            unlock_at = str(post_guard.get("unlock_at") or "").strip()
            if unlock_at:
                raise HTTPException(status_code=409, detail=f"cooldown:{unlock_at}")
            raise HTTPException(status_code=409, detail="cooldown")
        raise HTTPException(status_code=409, detail="slot_taken: booking could not be created")

    created = _safe_call(lambda: get_lesson_booking(booking_id), None)
    if created:
        _safe_call(lambda: refresh_lesson_reminders_for_booking(booking_id), None)
        await _notify_support_booking_created(created)
    return {"message": "Booking created", "booking": _serialize_booking_row(created or {"id": booking_id}, user)}


@app.post("/student/bookings/{booking_id}/cancel")
async def student_cancel_booking(booking_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM lesson_bookings
        WHERE id=? AND student_user_id=?
        LIMIT 1
        """,
        (str(booking_id), int(user_id)),
    )
    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Booking not found")
    payload = dict(row)
    status = str(payload.get("status") or "").lower()
    if status not in {"pending", "approved"}:
        conn.close()
        raise HTTPException(status_code=409, detail="Only pending/approved bookings can be cancelled")
    end_ts = _parse_utc_timestamp(str(payload.get("end_ts") or ""))
    if end_ts is not None and end_ts <= _now_utc():
        conn.close()
        raise HTTPException(status_code=409, detail="Passed bookings cannot be cancelled")
    cur.execute(
        """
        UPDATE lesson_bookings
        SET status='cancelled', updated_at=CURRENT_TIMESTAMP
        WHERE id=? AND student_user_id=?
        """,
        (str(booking_id), int(user_id)),
    )
    conn.commit()
    conn.close()
    await _notify_support_booking_cancelled_by_student(payload)
    return {"message": "Booking cancelled", "booking_id": str(booking_id), "status": "cancelled"}


@app.post("/support/bookings/{booking_id}/status")
async def change_booking_status(booking_id: str, payload: BookingStatusRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"support", "admin"})
    current_booking = _safe_call(lambda: get_lesson_booking(str(booking_id)), None)
    if not current_booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if role == "support" and not _booking_visible_to_support_user(user, current_booking):
        raise HTTPException(status_code=403, detail="Permission denied")

    status_value = payload.status
    if status_value == "reschedule":
        if not payload.date or not payload.time:
            raise HTTPException(status_code=400, detail="Reschedule requires date and time")
        target_branch = _validate_branch_key(payload.branch) if payload.branch else str(current_booking.get("branch") or "")
        target_date, target_time = _validate_support_booking_reschedule_target(
            current_booking,
            date_iso=str(payload.date),
            time_hhmm=str(payload.time),
            branch_key=target_branch,
        )
        ok = reschedule_lesson_booking(
            booking_id=booking_id,
            date_iso=target_date,
            time_hhmm=target_time,
            start_ts=None,
            admin_id=int(user.get("id") or 0),
        )
        if ok and target_branch != str(current_booking.get("branch") or ""):
            _safe_call(lambda: update_lesson_booking_branch(booking_id, target_branch, int(user.get("id") or 0)), False)
    else:
        if status_value in {"pending", "approved"} and current_booking:
            _raise_if_lesson_date_closed(str(current_booking.get("date") or ""), str(current_booking.get("branch") or ""))
        ok = set_lesson_booking_status(
            booking_id=booking_id,
            status=status_value,
            admin_id=int(user.get("id") or 0),
            admin_note=payload.admin_note,
        )
    if not ok:
        raise HTTPException(status_code=404, detail="Booking not found or not updated")
    updated_booking = _safe_call(lambda: get_lesson_booking(str(booking_id)), None)
    if status_value == "reschedule" and updated_booking:
        await _notify_support_booking_rescheduled(updated_booking, current_booking)
    return {
        "message": "Booking updated",
        "booking_id": booking_id,
        "status": status_value,
        "booking": _serialize_booking_row(updated_booking or current_booking),
    }


@app.post("/support/bookings/{booking_id}/attendance")
async def mark_booking_attendance(booking_id: str, payload: BookingAttendanceRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"support", "admin"})
    current_booking = _safe_call(lambda: get_lesson_booking(str(booking_id)), None)
    if not current_booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    if role == "support" and not _booking_visible_to_support_user(user, current_booking):
        raise HTTPException(status_code=403, detail="Permission denied")
    ok = set_support_booking_attendance(booking_id, payload.status)
    if not ok:
        raise HTTPException(status_code=404, detail="Booking not found")

    bonus_result = {"applied": False, "history_id": None}
    penalty_result = {"applied": False, "history_id": None}
    points_delta = 0.0
    st = payload.status.lower()
    subject = _normalize_subject_label(str(current_booking.get("support_subject") or "")) or "English"
    if st in {"present", "late"} and payload.bonus_amount > 0:
        applied, student_user_id = apply_support_bonus_if_needed(booking_id, float(payload.bonus_amount))
        bonus_result = {"applied": bool(applied), "history_id": student_user_id}
        if applied and student_user_id:
            add_dpoints(int(student_user_id), float(payload.bonus_amount), subject, change_type="support_bonus")
            points_delta += float(payload.bonus_amount)
    if st == "late":
        applied, student_user_id = apply_support_attendance_penalty_if_needed(booking_id, 5.0)
        penalty_result = {"applied": bool(applied), "history_id": student_user_id}
        if applied and student_user_id:
            add_dpoints(int(student_user_id), -5.0, subject, change_type="support_attendance_late")
            points_delta -= 5.0
    elif st == "absent":
        applied, student_user_id = apply_support_attendance_penalty_if_needed(booking_id, 10.0)
        penalty_result = {"applied": bool(applied), "history_id": student_user_id}
        if applied and student_user_id:
            add_dpoints(int(student_user_id), -10.0, subject, change_type="support_attendance_absent")
            points_delta -= 10.0

    return {
        "message": "Attendance updated",
        "booking_id": booking_id,
        "status": st,
        "bonus": bonus_result,
        "penalty": penalty_result,
        "points_delta": float(points_delta),
    }


