@app.post("/groups")
async def create_group(payload: GroupCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    admin_ref = _admin_ref_id(user)
    normalized_subject_input = _resolve_group_subject_input(payload.subject, payload.subject_id)
    _, normalized_subject = _validate_group_teacher_and_subject(int(payload.teacher_id), normalized_subject_input)
    if payload.course_id is None or int(payload.course_id) <= 0:
        raise HTTPException(status_code=400, detail="course_id is required for group creation")
    linked_course = _get_course_by_id(int(payload.course_id))
    if not linked_course:
        raise HTTPException(status_code=404, detail="Course not found")
    lesson_days = _normalize_lesson_days(payload.lesson_date) or "MWF"
    if payload.lesson_date is not None and not _normalize_lesson_days(payload.lesson_date):
        raise HTTPException(status_code=400, detail="lesson_date must be MWF or TTS")
    try:
        group_id = db_create_group(
            payload.name.strip(),
            int(payload.teacher_id),
            level=payload.level.strip() or "PRE-INTERMEDIATE",
            subject=normalized_subject,
            extra_subjects=[],
            lesson_date=lesson_days,
            lesson_start=payload.lesson_start,
            lesson_end=payload.lesson_end,
            owner_admin_id=int(admin_ref),
            course_id=int(linked_course["id"]) if linked_course else None,
            course_title=str(linked_course.get("title") or "").strip() if linked_course else None,
            monthly_fee_text=(
                str(linked_course.get("individual_price_text") or "").strip() if payload.pricing_type == "individual" else str(linked_course.get("price_text") or "").strip()
            ) if linked_course else None,
            telegram_group_url=payload.telegram_group_url,
            pricing_type=payload.pricing_type,
            lang=payload.lang,
        )
    except Exception as exc:
        logger.exception("groups.create failed admin_ref=%s teacher_id=%s name=%s", admin_ref, payload.teacher_id, payload.name)
        raise HTTPException(status_code=500, detail=f"Group create failed: {str(exc)[:220]}") from exc
    if int(group_id or 0) <= 0:
        raise HTTPException(status_code=422, detail="Group create failed: invalid group id")
    extras_ok = bool(update_group_extra_subjects(int(group_id), []))
    if not extras_ok:
        logger.warning("groups.create extra subjects sync failed group_id=%s", int(group_id))
    return {"message": "Group created", "group_id": int(group_id)}


@app.post("/groups/{group_id}/members/{student_id}")
async def add_group_member(
    group_id: int,
    student_id: int,
    payload: GroupMemberAddRequest | None = None,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"admin", "teacher", "support"})
    group_row = _safe_call(lambda: get_group(int(group_id)), None)
    student_row = _safe_call(lambda: get_user_by_id(int(student_id)), None)
    if not group_row or not student_row:
        raise HTTPException(status_code=404, detail="Group or student not found")
    if int(student_row.get("login_type") or 0) not in (1, 2, 6):
        raise HTTPException(status_code=400, detail="Only students can be added to groups")
    if role in {"teacher", "support"}:
        if not _teacher_can_manage_group(user, group_row):
            raise HTTPException(status_code=403, detail="Teacher can only manage own or temporary groups")
    else:
        admin_ref = _admin_ref_id(user)
        if not _can_manage_group(admin_ref, group_row):
            raise HTTPException(status_code=403, detail="You cannot manage this group")
        if not _can_manage_user_globally(admin_ref, student_row):
            raise HTTPException(status_code=403, detail="You cannot manage this student")
    _require_student_group_subject_match(student_row, group_row)
    joined_at = payload.joined_at if payload else None
    if not joined_at:
        raise HTTPException(status_code=400, detail="Qo'shilgan sana kiritilishi majburiy")
    add_user_to_group(int(student_id), int(group_id), joined_at=joined_at)
    _clear_user_media_caches(int(student_id))
    _payment_prewarm_users_month_async(
        user_ids={int(student_id)},
        reason="admin_add_group_member_new",
    )
    return _group_membership_change_payload(
        int(group_id),
        int(student_id),
        "Student added to group",
        membership_mode="new",
        billing_joined_at=joined_at,
    )


