@app.post("/arena/battles/{battle_id}/join")
async def join_battle(battle_id: str, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user_id = int(user.get("id") or 0)
    subject = _user_subjects_from_row(user)[0] if _user_subjects_from_row(user) else "English"
    level = str(user.get("level") or "PRE-INTERMEDIATE").strip().upper()
    if level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}:
        level = "PRE-INTERMEDIATE"

    if battle_id.startswith("group-"):
        try:
            sid = int(battle_id.split("-", 1)[1])
        except Exception:
            raise HTTPException(status_code=400, detail="Invalid group arena session id")
        session = _safe_call(lambda: get_arena_group_session(sid), None)
        if not session:
            raise HTTPException(status_code=404, detail="Group arena session not found")
        return {
            "message": "Joined group arena",
            "battle_id": battle_id,
            "session_id": sid,
            "user_id": user_id,
            "session": session,
        }

    if battle_id in {"duel-1v1", "duel-3v3", "duel-5v5"}:
        mode_map = {
            "duel-1v1": ("1v1", 2),
            "duel-3v3": ("3v3", 6),
            "duel-5v5": ("5v5", 10),
        }
        duel_mode, required_players = mode_map[battle_id]
        expiry = (_now_utc() + timedelta(minutes=10)).isoformat()
        sess = get_open_duel_session(duel_mode, subject, level)
        if not sess:
            for row in list_open_duel_sessions_for_mode(duel_mode):
                if str(row.get("subject") or "").strip().title() == subject:
                    sess = dict(row)
                    break
        session_id = int(sess.get("id") or 0) if sess else 0
        if session_id <= 0:
            session_id = create_duel_session(
                mode=duel_mode,
                subject=subject,
                level=level,
                created_by_user_id=user_id,
                required_players=int(required_players),
                expires_at=expiry,
            )
        current = count_duel_participants(session_id)
        team_no = 1
        if duel_mode == "3v3":
            team_no = 1 if current < 3 else 2
        elif duel_mode == "5v5":
            team_no = 1 if current < 5 else 2
        joined = join_duel_session(session_id, user_id, int(user.get("telegram_id") or 0) or user_id, team_no=team_no)
        participants = count_duel_participants(session_id)
        if participants >= int(required_players):
            mark_duel_session_started(session_id)
        return {
            "message": "Duel joined" if joined else "Already in duel queue",
            "battle_id": battle_id,
            "session_id": session_id,
            "participants": participants,
            "required_players": int(required_players),
            "status": "running" if participants >= int(required_players) else "waiting",
            "user_id": user_id,
        }

    return {
        "message": "Joined battle",
        "match_id": f"ARENA-{random.randint(1000, 9999)}",
        "battle_id": battle_id,
        "user_id": user_id,
    }


