@app.post("/vocabulary/quiz/start")
async def vocabulary_quiz_start(payload: VocabularyQuizStartRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)
    user_id = int(user.get("id") or 0)
    subjects = _user_subjects_from_row(user)
    requested_subject = _normalize_subject_label(payload.subject)
    if requested_subject and subjects and requested_subject not in subjects:
        raise HTTPException(status_code=403, detail="Selected subject is not available for this student")
    selected_subject = requested_subject or (subjects[0] if subjects else "English")
    selected_level = str(payload.level or "").strip().upper()
    if selected_level in {"", "ALL"}:
        selected_level = ""
    elif selected_level not in {"BEGINNER", "ELEMENTARY", "PRE-INTERMEDIATE", "INTERMEDIATE", "UPPER-INTERMEDIATE", "ADVANCED", "A1", "A2", "B1", "B2", "C1"}:
        selected_level = ""
    allowed_levels = [selected_level] if selected_level else get_vocab_allowed_levels_for_user(str(user.get("level") or "BEGINNER"))
    preferred_translation = str(get_student_preference(user_id) or "uz").strip().lower()
    if preferred_translation not in {"uz", "ru"}:
        preferred_translation = "uz"
    count = VOCAB_WEB_QUIZ_FIXED_COUNT
    quiz_type = "mixed"
    now_ts = _now_utc().replace(tzinfo=None)
    cooldowns = {
        qtype: get_vocab_cooldown_word_ids(user_id, qtype, now_ts=now_ts)
        for qtype in VOCAB_WEB_QUIZ_TYPES
    }
    questions = generate_balanced_mixed_quiz(
        user_id=user_id,
        subject=selected_subject,
        levels=allowed_levels,
        count=count,
        preferred_translation=preferred_translation,
        cooldown_word_ids_by_type=cooldowns,
    )
    if len(questions) < count and selected_level == "":
        questions = generate_balanced_mixed_quiz(
            user_id=user_id,
            subject=selected_subject,
            levels=[],
            count=count,
            preferred_translation=preferred_translation,
            cooldown_word_ids_by_type=cooldowns,
        )
    if not questions:
        raise HTTPException(status_code=409, detail="No vocabulary questions available for selected filters")

    session_id = f"vq_{uuid4().hex}"
    VOCAB_QUIZ_SESSIONS[session_id] = {
        "user_id": user_id,
        "subject": selected_subject,
        "level": selected_level or "ALL",
        "quiz_type": quiz_type,
        "questions": [
            {
                "prompt": str(q.get("prompt") or ""),
                "subject": selected_subject,
                "language": vocab_language_for_subject(selected_subject),
                "tts_language": _test_tts_language_for_subject(selected_subject),
                "options": [str(opt) for opt in (q.get("options") or [])],
                "correct": str(q.get("correct") or ""),
                "word_id": int(q.get("word_id") or 0),
                "question_type": str(q.get("question_type") or q.get("type") or "multiple_choice"),
                "instruction": str(q.get("instruction") or ""),
            }
            for q in questions
            if q.get("options")
        ],
        "index": 0,
        "correct": 0,
        "wrong": 0,
        "skipped": 0,
        "started_at": _now_utc().isoformat(),
    }
    session = VOCAB_QUIZ_SESSIONS[session_id]
    _persist_student_quiz_session(session_id, user_id, "vocabulary", session, status="active")
    runtime_questions = session.get("questions") or []
    if not runtime_questions:
        VOCAB_QUIZ_SESSIONS.pop(session_id, None)
        raise HTTPException(status_code=409, detail="Could not initialize vocabulary quiz session")
    q0 = runtime_questions[0]
    return _attach_proctoring_payload(user, {
        "session_id": session_id,
        "subject": selected_subject,
        "level": selected_level or "ALL",
        "quiz_type": quiz_type,
        "question_index": 1,
        "total_questions": len(runtime_questions),
        "progress_percent": 0,
        "question": {
            # `question_index` here (nested, 1-based) lets the client key its
            # per-question timer reset on the actual question rather than on
            # the whole session — without it, every question shares the same
            # key and the timer never restarts after question 1.
            **_public_question_payload(q0, question_index=1),
        },
    }, test_type="vocabulary", test_attempt_ref=session_id, test_route="/student/vocabulary")


@app.post("/vocabulary/quiz/answer")
async def vocabulary_quiz_answer(payload: VocabularyQuizAnswerRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    session_id = str(payload.session_id or "").strip()
    user_id = int(user.get("id") or 0)
    conn = cur = None
    row = state = result = None
    try:
        pre_row, pre_state, pre_result = _load_student_quiz_session_snapshot(session_id, user_id, "vocabulary")
        if pre_row and str((pre_row or {}).get("status") or "").lower() == "completed":
            if pre_result:
                return pre_result
            raise HTTPException(status_code=400, detail="Vocabulary quiz already completed")
        pre_session = pre_state if isinstance(pre_state, dict) and pre_state else VOCAB_QUIZ_SESSIONS.get(session_id)
        if not pre_session:
            raise HTTPException(status_code=404, detail="Vocabulary quiz session not found")
        if int(pre_session.get("user_id") or 0) != user_id:
            raise HTTPException(status_code=403, detail="Session does not belong to current user")
        _ensure_proctoring_session_access(
            user,
            payload.proctoring_session_id,
            expected_test_type="vocabulary",
            expected_attempt_ref=session_id,
        )
        conn, cur, row, state, result = _load_student_quiz_session_locked(session_id, user_id, "vocabulary")
        if row and str((row or {}).get("status") or "").lower() == "completed":
            if result:
                return result
            raise HTTPException(status_code=400, detail="Vocabulary quiz already completed")
        session = state if isinstance(state, dict) and state else VOCAB_QUIZ_SESSIONS.get(session_id)
        if not session:
            raise HTTPException(status_code=404, detail="Vocabulary quiz session not found")
        if int(session.get("user_id") or 0) != user_id:
            raise HTTPException(status_code=403, detail="Session does not belong to current user")
        questions = session.get("questions") or []
        idx = int(session.get("index") or 0)
        if idx >= len(questions):
            completed_result = result or {}
            if completed_result:
                return completed_result
            raise HTTPException(status_code=400, detail="Vocabulary quiz already completed")
        q = questions[idx]
        selected = payload.selected_option_index
        options = q.get("options") or []
        selected_correct = False
        if selected is None:
            session["skipped"] = int(session.get("skipped") or 0) + 1
        else:
            selected_idx = int(selected)
            if selected_idx < 0 or selected_idx >= len(options):
                raise HTTPException(status_code=400, detail="Invalid option index")
            selected_value = str(options[selected_idx] or "")
            if _selected_option_is_correct(q, selected_idx) or selected_value == str(q.get("correct") or ""):
                session["correct"] = int(session.get("correct") or 0) + 1
                selected_correct = True
            else:
                session["wrong"] = int(session.get("wrong") or 0) + 1
        word_id = int(q.get("word_id") or 0)
        if word_id > 0:
            record_vocab_word_result(
                user_id=user_id,
                word_id=word_id,
                question_type=str(q.get("question_type") or "multiple_choice"),
                is_correct=selected_correct,
                answered_at=_now_utc().replace(tzinfo=None),
            )
            _invalidate_student_overview_cache(user_id)
        session["index"] = idx + 1

        if session["index"] < len(questions):
            qn = questions[int(session["index"])]
            next_index = int(session["index"]) + 1
            response = {
                "completed": False,
                "session_id": session_id,
                "quiz_type": session.get("quiz_type"),
                "subject": session.get("subject"),
                "question_index": next_index,
                "total_questions": len(questions),
                "progress_percent": int(round(((next_index - 1) * 100) / max(1, len(questions)))),
                "question": {
                    **_public_question_payload(qn, question_index=next_index),
                },
            }
            if cur is not None:
                _update_student_quiz_session_tx(cur, session_id, session, status="active")
                conn.commit()
            else:
                VOCAB_QUIZ_SESSIONS[session_id] = session
            return response

        correct = int(session.get("correct") or 0)
        wrong = int(session.get("wrong") or 0)
        skipped = int(session.get("skipped") or 0)
        total = max(1, len(questions))
        percent = round((correct * 100.0) / total, 1)
        breakdown = award_quiz_dpoints(
            user_id=user_id,
            subject=str(session.get("subject") or "English"),
            correct_count=correct,
            wrong_count=wrong,
            skipped_count=skipped,
            mode="vocabulary",
            change_type="vocabulary_web_quiz",
        )
        add_test_history(
            user_id,
            "vocabulary",
            str(session.get("quiz_type") or "multiple_choice"),
            correct,
            wrong,
            skipped,
        )
        _invalidate_student_overview_cache(user_id)
        response = {
            "completed": True,
            "quiz_type": session.get("quiz_type"),
            "subject": session.get("subject"),
            "correct": correct,
            "wrong": wrong,
            "skipped": skipped,
            "total_questions": total,
            "percentage": percent,
            "dpoints": float(breakdown.get("total_points") or 0),
            "dcoin": float(breakdown.get("final_dcoins") or 0),
            "dcoin_breakdown": breakdown,
            "dpoint_breakdown": breakdown,
        }
        if cur is not None:
            _update_student_quiz_session_tx(cur, session_id, session, status="completed", result=response)
            conn.commit()
        VOCAB_QUIZ_SESSIONS.pop(session_id, None)
        return response
    except HTTPException:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        raise
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        logger.exception("vocabulary_quiz_answer failed session_id=%s user_id=%s", session_id, user_id)
        raise
    finally:
        if conn is not None:
            conn.close()


