@app.post("/economy/transfer")
async def transfer_dcoins(
    payload: TransferRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    sender_id = int(user.get("id") or 0)
    recipient_id = int(payload.recipient_id)
    amount = float(payload.amount)

    if recipient_id == sender_id:
        raise HTTPException(status_code=400, detail="Cannot transfer to self")
    if amount <= 0:
        raise HTTPException(status_code=400, detail="Amount must be positive")

    # Security: verify recipient exists and is a student (cannot send coins to admins/teachers)
    recipient = _safe_call(lambda: get_user_by_id(recipient_id), None)
    if not recipient:
        raise HTTPException(status_code=404, detail="Recipient not found")
    recipient_role = _role_from_login_type(int(recipient.get("login_type") or 0), str(recipient.get("login_id") or ""))
    if recipient_role != "student":
        raise HTTPException(status_code=403, detail="Can only transfer D'coin to other students")
    if int(recipient.get("blocked") or 0) == 1:
        raise HTTPException(status_code=403, detail="Recipient account is blocked")

    # Security: per-user daily transfer cap
    import datetime as _dt
    today_str = _dt.datetime.utcnow().strftime("%Y-%m-%d")
    _day, _total = _TRANSFER_DAILY_TOTALS.get(sender_id, (today_str, 0.0))
    if _day != today_str:
        _day, _total = today_str, 0.0
    if _total + amount > _TRANSFER_DAILY_MAX:
        remaining = max(0.0, _TRANSFER_DAILY_MAX - _total)
        raise HTTPException(
            status_code=429,
            detail=f"Daily transfer limit reached. You can still send {remaining:.1f} D'coin today.",
        )

    chosen_subject = _normalize_subject_label(payload.subject) or (_user_subjects_from_row(user)[0] if _user_subjects_from_row(user) else "English")
    result = transfer_dcoins_atomic(
        sender_id=sender_id,
        recipient_id=recipient_id,
        amount=amount,
        subject=chosen_subject,
    )
    if not result.get("ok"):
        reason = str(result.get("reason") or "transaction_failed")
        if reason == "insufficient_balance":
            raise HTTPException(status_code=400, detail="Insufficient Dcoin balance")
        if reason == "user_not_found":
            raise HTTPException(status_code=404, detail="Recipient not found")
        raise HTTPException(status_code=400, detail="Transfer could not be completed")

    # Record daily total
    _TRANSFER_DAILY_TOTALS[sender_id] = (today_str, _total + amount)

    return {
        "message": "Transfer successful",
        "subject": chosen_subject,
        "amount": amount,
        "sender_balance": float(result.get("sender_balance_after") or 0.0),
        "recipient_balance": float(result.get("recipient_balance_after") or 0.0),
    }


