@app.post("/admin/videos")
@app.post("/teacher/videos")
async def admin_create_video(payload: VideoCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    role = _require_role(user, {"admin", "teacher", "support"})
    if role == "teacher" or (role != "admin" and not _safe_call(lambda: get_video_upload_permission(int(user.get("id") or 0)), False)):
        raise HTTPException(status_code=403, detail="Video yuklash uchun ruxsat yo'q")
    title = str(payload.title or "").strip()
    if len(title) < 2:
        raise HTTPException(status_code=400, detail="Video title is required")
    thumbnail_url = str(payload.thumbnail_url or "").strip()
    if not _has_valid_thumbnail_like_url(thumbnail_url):
        raise HTTPException(status_code=400, detail="Video thumbnail is required")
    asset_id = int(payload.video_asset_id or 0) or None
    
    teacher_id = payload.teacher_id
    if role in ("teacher", "support"):
        teacher_id = int(user.get("id") or 0)
        
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO videos (title, subject, description, author, category, level, thumbnail_url, video_url, video_asset_id, duration, is_published, teacher_id, support_teacher_ids)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            title,
            str(payload.subject or "").strip(),
            str(payload.description or "").strip(),
            str(payload.author or "").strip(),
            str(payload.category or "").strip(),
            str(payload.level or "").strip(),
            thumbnail_url,
            str(payload.video_url or "").strip(),
            asset_id,
            int(payload.duration or 0),
            1,
            teacher_id,
            payload.support_teacher_ids,
        )
    )
    conn.commit()
    cur.execute("SELECT * FROM videos ORDER BY id DESC LIMIT 1")
    row = cur.fetchone()
    conn.close()
    _clear_video_list_caches()
    return {
        "message": "Video created",
        "item": _serialize_video_row(dict(row), viewer_user_id=int(user.get("id") or 0)) if row else None,
    }


@app.put("/admin/videos/{video_id}")
async def admin_update_video(
    video_id: int,
    payload: VideoUpdateRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    updates = payload.model_dump(exclude_unset=True)
    if not updates:
        raise HTTPException(status_code=400, detail="No fields provided for update")
    if "title" in updates:
        updates["title"] = str(updates.get("title") or "").strip()
        if len(str(updates["title"])) < 2:
            raise HTTPException(status_code=400, detail="Video title is required")
    if "subject" in updates:
        updates["subject"] = str(updates.get("subject") or "").strip()
        if len(str(updates["subject"])) < 2:
            raise HTTPException(status_code=400, detail="Video subject is required")
    for key in ("description", "author", "category", "level", "thumbnail_url", "video_url", "support_teacher_ids"):
        if key in updates:
            updates[key] = str(updates.get(key) or "").strip()
    if "video_asset_id" in updates:
        updates["video_asset_id"] = int(updates.get("video_asset_id") or 0) or None
    if "teacher_id" in updates:
        updates["teacher_id"] = int(updates.get("teacher_id") or 0) or None
    if "duration" in updates:
        updates["duration"] = max(0, int(updates.get("duration") or 0))
    if "is_published" in updates:
        updates["is_published"] = 1 if bool(updates.get("is_published")) else 0

    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM videos WHERE id = ? LIMIT 1", (int(video_id),))
    existing = cur.fetchone()
    if not existing:
        conn.close()
        raise HTTPException(status_code=404, detail="Video not found")
    if "thumbnail_url" in updates:
        thumb = str(updates.get("thumbnail_url") or "").strip()
        if not _has_valid_thumbnail_like_url(thumb):
            conn.close()
            raise HTTPException(status_code=400, detail="Video thumbnail is required")
        updates["thumbnail_url"] = thumb

    assignments = ", ".join([f"{key}=?" for key in updates.keys()])
    params = [*updates.values(), int(video_id)]
    cur.execute(
        f"UPDATE videos SET {assignments}, updated_at=CURRENT_TIMESTAMP WHERE id=?",
        tuple(params),
    )
    conn.commit()
    cur.execute("SELECT * FROM videos WHERE id = ? LIMIT 1", (int(video_id),))
    row = cur.fetchone()
    conn.close()
    _clear_video_list_caches()
    return {"message": "Video updated", "item": _serialize_video_row(dict(row), viewer_user_id=int(user.get("id") or 0)) if row else None}


