@app.get("/student/videos")
@app.get("/teacher/videos")
@app.get("/support/videos")
async def user_get_videos(
    subject: str | None = Query(default=None),
    level: str | None = Query(default=None),
    limit: int = Query(default=120, ge=1, le=300),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "support"})
    user_id = int(user.get("id") or 0)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    subjects = _user_subjects_from_row(user)
    selected_subject = _normalize_subject_label(subject)
    selected_level = (level or "").strip() or None
    subjects_sig = ",".join(sorted(subjects or []))
    cache_key = ("videos", user_id, role, selected_subject or "", selected_level or "", subjects_sig, int(limit), int(offset))
    cached = _short_cache_get(_MEDIA_LIST_CACHE, cache_key)
    if isinstance(cached, dict):
        return cached
    conn = get_conn()
    cur = conn.cursor()
    params: list[Any] = []
    columns = """
        id, title, description, author, category, level, subject,
        thumbnail_url, video_url, video_asset_id, duration, is_published, created_at, updated_at,
        COALESCE(view_count, 0) AS view_count,
        COALESCE(like_count, 0) AS like_count
    """
    if role in {"teacher", "support"}:
        where = "is_published = 1"
        if selected_subject:
            where += " AND subject=?"
            params.append(selected_subject)
        if selected_level:
            where += " AND level=?"
            params.append(selected_level)
        cur.execute(
            f"""
            SELECT {columns}
            FROM videos
            WHERE {where}
            ORDER BY COALESCE(view_count, 0) DESC, COALESCE(like_count, 0) DESC, created_at DESC, id DESC
            LIMIT ? OFFSET ?
            """,
            tuple([*params, int(limit), int(offset)]),
        )
    elif subjects:
        allowed_subjects = [selected_subject] if selected_subject and selected_subject in subjects else subjects
        qmarks = ",".join(["?"] * len(allowed_subjects))
        query = f"""
            SELECT {columns}
            FROM videos
            WHERE is_published = 1
              AND (subject IS NULL OR subject = '' OR subject IN ({qmarks}))
        """
        queryParams = [*allowed_subjects]
        if selected_level:
            query += " AND level=?"
            queryParams.append(selected_level)
        query += """
            ORDER BY COALESCE(view_count, 0) DESC, COALESCE(like_count, 0) DESC, created_at DESC, id DESC
            LIMIT ? OFFSET ?
        """
        cur.execute(query, tuple([*queryParams, int(limit), int(offset)]))
    else:
        query = f"""
            SELECT {columns}
            FROM videos
            WHERE is_published = 1 AND (subject IS NULL OR subject = '')
        """
        queryParams = []
        if selected_level:
            query += " AND level=?"
            queryParams.append(selected_level)
        query += """
            ORDER BY COALESCE(view_count, 0) DESC, COALESCE(like_count, 0) DESC, created_at DESC, id DESC
            LIMIT ? OFFSET ?
        """
        cur.execute(query, tuple([*queryParams, int(limit), int(offset)]))
    
    videos = [dict(r) for r in (cur.fetchall() or [])]
    progress_rows: list[dict[str, Any]] = []
    video_ids = [int(v.get("id") or 0) for v in videos if int(v.get("id") or 0) > 0]
    if video_ids:
        qmarks = ",".join(["?"] * len(video_ids))
        cur.execute(
            f"SELECT * FROM video_progress WHERE user_id = ? AND video_id IN ({qmarks})",
            tuple([user_id, *video_ids]),
        )
        progress_rows = [dict(p) for p in (cur.fetchall() or [])]
    progress_map = {int(p["video_id"]): p for p in progress_rows}
    _mark_liked_videos_for_user(cur, videos, user_id)
    conn.close()
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 750:
        logger.info("perf media.videos.list role=%s total_ms=%.2f rows=%s", role, elapsed_ms, len(videos))
    payload = {
        "items": [_serialize_video_list_row(v, progress_map.get(int(v.get("id") or 0))) for v in videos],
        "limit": int(limit),
        "offset": int(offset),
        "has_more": len(videos) >= int(limit),
    }
    return _short_cache_set(_MEDIA_LIST_CACHE, cache_key, payload, ttl_seconds=6.0, max_items=4096)


