    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Video not found")
    video_dict = dict(row)
    if not _media_subject_allowed_for_user(user, video_dict):
        conn.close()
        raise HTTPException(status_code=403, detail="Sizda bu videoni ko'rish huquqi yo'q")
        
    cur.execute("UPDATE videos SET view_count = COALESCE(view_count, 0) + 1 WHERE id = ?", (int(video_id),))

        
    conn.commit()

        
    video_dict["view_count"] = int(video_dict.get("view_count") or 0) + 1


        
    cur.execute("SELECT * FROM video_progress WHERE user_id = ? AND video_id = ? LIMIT 1", (user_id, int(video_id)))
    progress_row = cur.fetchone()
    video_rows = [video_dict]
    _mark_liked_videos_for_user(cur, video_rows, user_id)
    video_dict = video_rows[0]

    cur.execute("SELECT * FROM videos WHERE is_published = 1 AND id != ? ORDER BY created_at DESC LIMIT 100", (int(video_id),))
    related_rows = []
    for r in cur.fetchall() or []:
        rd = dict(r)
        if _media_subject_allowed_for_user(user, rd):
            related_rows.append(rd)
            if len(related_rows) >= 12:
                break
    _mark_liked_videos_for_user(cur, related_rows, user_id)

    cur.execute(


        "SELECT id, parent_id, like_count, dislike_count, author_name, comment_text, created_at "


        "FROM web_video_comments WHERE video_id = ? ORDER BY created_at DESC",


        (int(video_id),)


    )


    comments = []


    for cr in cur.fetchall() or []:


        comments.append({


            "id": int(cr["id"]),


            "user_name": str(cr["author_name"]),


            "content": str(cr["comment_text"]),


            "created_at": _as_iso_timestamp(cr["created_at"])


        })


    item_serialized = _serialize_video_row(video_dict, dict(progress_row) if progress_row else None, viewer_user_id=user_id)


    item_serialized["comments"] = comments



    conn.close()


    return {


        "item": item_serialized,


        "related": [_serialize_video_row(r, None, viewer_user_id=user_id) for r in related_rows]


    }

