@app.get("/admin/books")
async def admin_get_books(
    limit: int = Query(default=120, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    viewer_user_id = int(user.get("id") or 0)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT
            b.*,
            COALESCE(bp.purchase_count, 0) AS purchase_count,
            GREATEST(
                COALESCE(bq.question_count, 0),
                COALESCE(wct.question_count, 0)
            ) AS question_count
        FROM books b
        LEFT JOIN (
            SELECT book_id, COUNT(*) AS purchase_count
            FROM student_book_purchases
            GROUP BY book_id
        ) bp ON bp.book_id = b.id
        LEFT JOIN (
            SELECT book_id, COUNT(*) AS question_count
            FROM book_questions
            GROUP BY book_id
        ) bq ON bq.book_id = b.id
        LEFT JOIN (
            SELECT content_id, COUNT(*) AS question_count
            FROM web_content_test_questions wctq
            JOIN web_content_tests wct2 ON wct2.id = wctq.test_id
            WHERE wct2.content_type = 'book' AND COALESCE(wct2.is_active, 1) = 1
            GROUP BY content_id
        ) wct ON wct.content_id = b.id
        ORDER BY b.created_at DESC, b.id DESC
        LIMIT ? OFFSET ?
        """
        ,
        (int(limit), int(offset)),
    )
    rows = [dict(r) for r in (cur.fetchall() or [])]
    conn.close()
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 750:
        logger.info("perf admin.books.list total_ms=%.2f rows=%s", elapsed_ms, len(rows))
    return {
        "items": [_serialize_book_row(r, include_purchase=False, viewer_user_id=viewer_user_id) for r in rows],
        "limit": int(limit),
        "offset": int(offset),
        "has_more": len(rows) >= int(limit),
    }


