@app.post("/admin/books")
@app.post("/teacher/books")
@app.post("/support/books")
async def admin_create_book(payload: BookCreateRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_book_upload_access(user)
    title = str(payload.title or "").strip()
    if len(title) < 2:
        raise HTTPException(status_code=400, detail="Book title is required")
    cover_url = str(payload.cover_url or "").strip()
    if not _has_valid_thumbnail_like_url(cover_url):
        raise HTTPException(status_code=400, detail="Book thumbnail is required")
    asset_id = int(payload.pdf_asset_id or 0) or None
    price_value = max(0.0, float(payload.price or 0.0))
    # Deadline olib tashlangan: deadline_days kelmasa yoki 0 bo'lsa — NULL
    raw_deadline_days = int(payload.deadline_days or 0)
    deadline_days = max(1, raw_deadline_days) if raw_deadline_days > 0 else None
    conn = get_conn()
    cur = conn.cursor()
    params = (
        title,
        str(payload.subject or "").strip(),
        str(payload.description or "").strip(),
        str(payload.author or "").strip(),
        str(payload.category or "").strip(),
        str(payload.level or "").strip(),
        cover_url,
        str(payload.pdf_url or "").strip(),
        asset_id,
        price_value,
        deadline_days,
        1,
    )
    cur.execute(
        """
        INSERT INTO books (title, subject, description, author, category, level, cover_url, pdf_url, pdf_asset_id, price, deadline_days, is_published)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, params
    )
    conn.commit()
    cur.execute("SELECT * FROM books ORDER BY id DESC LIMIT 1")
    row = cur.fetchone()
    conn.close()
    _clear_book_list_caches()
    return {
        "message": "Book created",
        "item": _serialize_book_row(
            dict(row),
            include_purchase=False,
            viewer_user_id=int(user.get("id") or 0),
        )
        if row
        else None,
    }


@app.put("/admin/books/{book_id}")
async def admin_update_book(
    book_id: int,
    payload: BookUpdateRequest,
    authorization: str | None = Header(default=None),
):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin"})
    updates = payload.model_dump(exclude_unset=True)
    if not updates:
        raise HTTPException(status_code=400, detail="No fields provided for update")
    if "title" in updates:
        updates["title"] = str(updates.get("title") or "").strip()
        if len(str(updates["title"])) < 2:
            raise HTTPException(status_code=400, detail="Book title is required")
    if "subject" in updates:
        updates["subject"] = str(updates.get("subject") or "").strip()
        if len(str(updates["subject"])) < 2:
            raise HTTPException(status_code=400, detail="Book subject is required")
    for key in ("description", "author", "category", "level", "cover_url", "pdf_url"):
        if key in updates:
            updates[key] = str(updates.get(key) or "").strip()
    if "pdf_asset_id" in updates:
        updates["pdf_asset_id"] = int(updates.get("pdf_asset_id") or 0) or None
    if "price" in updates:
        updates["price"] = max(0.0, float(updates.get("price") or 0.0))
    if "deadline_days" in updates:
        # Deadline ixtiyoriy: 0/bo'sh -> NULL
        raw_dd = int(updates.get("deadline_days") or 0)
        updates["deadline_days"] = max(1, raw_dd) if raw_dd > 0 else None
    if "is_published" in updates:
        updates["is_published"] = 1 if bool(updates.get("is_published")) else 0

    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM books WHERE id = ? LIMIT 1", (int(book_id),))
    existing = cur.fetchone()
    if not existing:
        conn.close()
        raise HTTPException(status_code=404, detail="Book not found")
    if "cover_url" in updates:
        cover = str(updates.get("cover_url") or "").strip()
        if not _has_valid_thumbnail_like_url(cover):
            conn.close()
            raise HTTPException(status_code=400, detail="Book thumbnail is required")
        updates["cover_url"] = cover

    assignments = ", ".join([f"{key}=?" for key in updates.keys()])
    cur.execute(
        f"UPDATE books SET {assignments}, updated_at=CURRENT_TIMESTAMP WHERE id = ?",
        (*updates.values(), int(book_id)),
    )
    conn.commit()
    cur.execute("SELECT * FROM books WHERE id = ? LIMIT 1", (int(book_id),))
    row = cur.fetchone()
    conn.close()
    _clear_book_list_caches()
    return {
        "message": "Book updated",
        "item": _serialize_book_row(
            dict(row),
            include_purchase=False,
            viewer_user_id=int(user.get("id") or 0),
        )
        if row
        else None,
    }


