@app.get("/student/books")
@app.get("/teacher/books")
@app.get("/support/books")
async def user_get_books(
    subject: str | None = Query(default=None),
    level: str | None = Query(default=None),
    limit: int = Query(default=120, ge=1, le=300),
    offset: int = Query(default=0, ge=0),
    authorization: str | None = Header(default=None),
):
    started_at = time.perf_counter()
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "support"})
    user_id = int(user.get("id") or 0)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    subjects = _user_subjects_from_row(user)
    selected_subject = _normalize_subject_label(subject)
    selected_level = str(level or "").strip()
    subjects_sig = ",".join(sorted(subjects or []))
    cache_key = ("books", user_id, role, selected_subject or "", selected_level, subjects_sig, int(limit), int(offset))
    cached = _short_cache_get(_MEDIA_LIST_CACHE, cache_key)
    if isinstance(cached, dict):
        return cached
    conn = get_conn()
    cur = conn.cursor()
    
    query = """
        SELECT
            b.id, b.title, b.description, b.author, b.category, b.level, b.subject,
            b.cover_url, b.pdf_url, b.pdf_asset_id, b.price, b.deadline_days, b.is_published, b.created_at, b.updated_at,
            COALESCE(b.purchase_count, 0) AS purchase_count,
            GREATEST(
                COALESCE(bq.question_count, 0),
                COALESCE(wct.question_count, 0)
            ) AS question_count
        FROM books b
        LEFT JOIN (
            SELECT book_id, COUNT(*) AS question_count
            FROM book_questions
            GROUP BY book_id
        ) bq ON bq.book_id = b.id
        LEFT JOIN (
            SELECT content_id, COUNT(*) AS question_count
            FROM web_content_test_questions wctq
            JOIN web_content_tests wct2 ON wct2.id = wctq.test_id
            WHERE wct2.content_type = 'book' AND COALESCE(wct2.is_active, 1) = 1
            GROUP BY content_id
        ) wct ON wct.content_id = b.id
        WHERE b.is_published = 1
    """
    params = []
    if role in {"teacher", "support"}:
        if selected_subject:
            query += " AND b.subject=?"
            params.append(selected_subject)
    elif subjects:
        allowed_subjects = [selected_subject] if selected_subject and selected_subject in subjects else subjects
        qmarks = ",".join(["?"] * len(allowed_subjects))
        query += f" AND (b.subject IS NULL OR b.subject = '' OR b.subject IN ({qmarks}))"
        params.extend(allowed_subjects)
    else:
        query += " AND (b.subject IS NULL OR b.subject = '')"
    if selected_level:
        query += " AND b.level=?"
        params.append(selected_level)
    
    query += " ORDER BY COALESCE(b.purchase_count, 0) DESC, b.created_at DESC, b.id DESC LIMIT ? OFFSET ?"
    cur.execute(query, tuple([*params, int(limit), int(offset)]))
    books = [dict(r) for r in (cur.fetchall() or [])]
    
    purchases = {}
    book_ids = [int(b.get("id") or 0) for b in books if int(b.get("id") or 0) > 0]
    if role == "student":
        if book_ids:
            qmarks = ",".join(["?"] * len(book_ids))
            cur.execute(
                f"SELECT * FROM student_book_purchases WHERE user_id = ? AND book_id IN ({qmarks})",
                tuple([user_id, *book_ids]),
            )
            purchases = {int(p["book_id"]): dict(p) for p in (cur.fetchall() or [])}
    else:
        for b in books:
            b_id = int(b.get("id") or 0)
            purchases[b_id] = {
                "id": 999999,
                "user_id": user_id,
                "book_id": b_id,
                "purchased_at": _now_utc().isoformat(),
                "deadline_at": (_now_utc() + timedelta(days=3650)).isoformat(),
                "status": "active"
            }
            
    wallet = float(user.get("dcoin_balance") if user.get("dcoin_balance") is not None else get_dcoins(user_id)) if role == "student" else 0.0
    conn.close()
    
    items = []
    for row in books:
        book_id = int(row.get("id") or 0)
        items.append(_serialize_book_list_row(row, purchases.get(book_id), include_purchase=True))
    elapsed_ms = (time.perf_counter() - started_at) * 1000.0
    if elapsed_ms > 750:
        logger.info("perf media.books.list role=%s total_ms=%.2f rows=%s", role, elapsed_ms, len(books))
    payload = {
        "items": items,
        "dcoin_balance": wallet,
        "limit": int(limit),
        "offset": int(offset),
        "has_more": len(books) >= int(limit),
    }
    return _short_cache_set(_MEDIA_LIST_CACHE, cache_key, payload, ttl_seconds=6.0, max_items=4096)


@app.get("/student/books/{book_id}")
@app.get("/teacher/books/{book_id}")
@app.get("/support/books/{book_id}")
async def user_get_book_detail(book_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student", "teacher", "support"})
    user_id = int(user.get("id") or 0)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        SELECT
            b.*,
            GREATEST(
                COALESCE(bq.question_count, 0),
                COALESCE(wct.question_count, 0)
            ) AS question_count
        FROM books b
        LEFT JOIN (
            SELECT book_id, COUNT(*) AS question_count
            FROM book_questions
            GROUP BY book_id
        ) bq ON bq.book_id = b.id
        LEFT JOIN (
            SELECT content_id, COUNT(*) AS question_count
            FROM web_content_test_questions wctq
            JOIN web_content_tests wct2 ON wct2.id = wctq.test_id
            WHERE wct2.content_type = 'book' AND COALESCE(wct2.is_active, 1) = 1
            GROUP BY content_id
        ) wct ON wct.content_id = b.id
        WHERE b.id=? AND b.is_published=1
        LIMIT 1
        """,
        (int(book_id),),
    )
    row = cur.fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="Book not found")
    book_dict = dict(row)
    if not _media_subject_allowed_for_user(user, book_dict):
        conn.close()
        raise HTTPException(status_code=403, detail="Sizda bu kitobni ko'rish huquqi yo'q")
        
    if role == "student":
        cur.execute("SELECT * FROM student_book_purchases WHERE user_id=? AND book_id=? LIMIT 1", (user_id, int(book_id)))
        purchase_row = cur.fetchone()
    else:
        purchase_row = {
            "id": 999999,
            "user_id": user_id,
            "book_id": int(book_id),
            "purchased_at": _now_utc().isoformat(),
            "deadline_at": (_now_utc() + timedelta(days=3650)).isoformat(),
            "status": "active"
        }
    conn.close()
    return {
        "item": _serialize_book_row(
            book_dict,
            dict(purchase_row) if purchase_row else None,
            include_purchase=True,
            viewer_user_id=user_id,
        )
    }

@app.post("/student/books/{book_id}/buy")
async def student_buy_book(book_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT * FROM books WHERE id = ? LIMIT 1", (int(book_id),))
    book = cur.fetchone()
    if not book:
        conn.close()
        raise HTTPException(status_code=404, detail="Book not found")
    if int(book.get("is_published") or 0) != 1:
        conn.close()
        raise HTTPException(status_code=403, detail="Book is not available for students")
    if not _media_subject_allowed_for_user(user, dict(book)):
        conn.close()
        raise HTTPException(status_code=403, detail="Sizda bu kitobni sotib olish huquqi yo'q")

    cur.execute(
        "SELECT * FROM student_book_purchases WHERE user_id = ? AND book_id = ? LIMIT 1",
        (user_id, int(book_id)),
    )
    existing = cur.fetchone()
    if existing:
        conn.close()
        _clear_user_media_caches(user_id)
        return {
            "message": "Book already purchased",
            "item": _serialize_book_purchase_row(dict(existing)),
            "dcoin_balance": float(get_dcoins(user_id)),
        }

    price = max(0.0, float(book.get("price") or 0.0))
    # Deadline tizimi to'liq olib tashlandi: yangi xaridlar doim cheksiz muddatli
    deadline = None
    deadline_days = None
    conn.close()

    purchase_result = purchase_book_with_dcoins(
        user_id=user_id,
        book_id=int(book_id),
        price_dcoin=price,
        deadline_at=deadline,
        book_title=str(book.get("title") or "").strip() or "Book",
        deadline_days=deadline_days,
    )
    if not purchase_result.get("ok"):
        reason = str(purchase_result.get("reason") or "transaction_failed")
        if reason == "insufficient_balance":
            raise HTTPException(status_code=400, detail="Insufficient Dcoin balance")
        raise HTTPException(status_code=400, detail="Could not create purchase")

    purchase = purchase_result.get("purchase") if isinstance(purchase_result.get("purchase"), dict) else None
    if purchase_result.get("already_purchased"):
        _clear_user_media_caches(user_id)
        return {
            "message": "Book already purchased",
            "item": _serialize_book_purchase_row(purchase),
            "dcoin_balance": float(purchase_result.get("balance_after") or get_dcoins(user_id)),
        }
    _clear_user_media_caches(user_id)
    await _notify_admins_purchase_created(
        buyer=user,
        item_type="book",
        item_title=str(book.get("title") or "").strip() or "Book",
        amount_spent=price,
        balance_after=float(purchase_result.get("balance_after") or get_dcoins(user_id)),
        purchase_history_id=int(purchase_result.get("purchase_history_id") or 0),
        item_id=int(book_id),
        source_page="student_books",
    )
    return {
        "message": "Book purchased successfully",
        "item": _serialize_book_purchase_row(purchase) if purchase else None,
        "dcoin_balance": float(purchase_result.get("balance_after") or get_dcoins(user_id)),
    }


