# --- CONTENT TESTS (VIDEO/BOOK) ---

class ContentTestSaveRequest(BaseModel):
    questions: list[dict]
    title: str | None = None
    is_active: bool | None = True

class ContentTestSubmitRequest(BaseModel):
    answers: dict[str, Any]
    proctoring_session_id: int | None = None

def _normalize_content_route_type(content_type: str) -> str:
    raw = str(content_type or "").strip().lower()
    aliases = {"videos": "video", "video": "video", "books": "book", "book": "book", "homeworks": "homework", "homework": "homework"}
    normalized = aliases.get(raw, raw)
    if normalized not in {"video", "book", "homework"}:
        raise HTTPException(status_code=400, detail="Unsupported content test type")
    return normalized


def _sanitize_content_test_for_student(test: dict | None) -> dict | None:
    if not test:
        return None
    out = {k: v for k, v in dict(test).items() if k != "questions_json"}
    questions = []
    for raw in (test.get("questions") or []):
        q = dict(raw)
        q.pop("correct", None)
        q.pop("correct_option_index", None)
        q.pop("explanation", None)
        # AI/yangi test turlarining javoblari studentga yuborilmasin.
        q.pop("answer", None)
        q.pop("accepted_answers", None)
        q.pop("correct_index", None)
        q.pop("reference_answer", None)
        q.pop("target_level", None)
        if q.get("pairs"):
            q.pop("pairs", None)
        questions.append(q)
    # Har safar savollar tartibi random — yodlab olish ishlamaydi.
    random.shuffle(questions)
    out["questions"] = questions
    out["question_count"] = len(questions)
    return out


def _content_test_subject(content_type: str, content_id: int, user: dict | None = None) -> str:
    normalized = _normalize_content_route_type(content_type)
    if normalized == "video":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT subject FROM videos WHERE id=? LIMIT 1", (int(content_id),))
            row = cur.fetchone()
            return _normalize_subject_label(str((row or {}).get("subject") or "")) or "GLOBAL"
        finally:
            conn.close()
    if normalized == "book":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT subject FROM books WHERE id=? LIMIT 1", (int(content_id),))
            row = cur.fetchone()
            return _normalize_subject_label(str((row or {}).get("subject") or "")) or "GLOBAL"
        finally:
            conn.close()
    if normalized == "homework":
        homework = _safe_call(lambda: get_homework(int(content_id)), None) or {}
        group_id = int(homework.get("group_id") or 0)
        if group_id > 0:
            group = _safe_call(lambda: get_group(group_id), None) or {}
            return _normalize_subject_label(str(group.get("subject") or "")) or "GLOBAL"
    if user:
        return (_user_subjects_from_row(user) or ["GLOBAL"])[0]
    return "GLOBAL"


def _require_content_test_manage_access(user: dict, content_type: str, content_id: int) -> dict | None:
    normalized = _normalize_content_route_type(content_type)
    role = _role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or ""))
    if role == "admin":
        return None
    if role not in {"teacher", "support"}:
        raise HTTPException(status_code=403, detail="Permission denied")
    user_id = int(user.get("id") or 0)
    # Teachers/support can manage tests for any video/book they have access to, bypassing the check for can_manage_video_tests column.
    if normalized == "video":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT * FROM videos WHERE id=? LIMIT 1", (int(content_id),))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Video not found")
            item = dict(row)
            if not _media_subject_allowed_for_user(user, item):
                raise HTTPException(status_code=403, detail="Sizda bu videoni boshqarish huquqi yo'q")
            return item
        finally:
            conn.close()
    if normalized == "book":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT * FROM books WHERE id=? LIMIT 1", (int(content_id),))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Book not found")
            item = dict(row)
            if not _media_subject_allowed_for_user(user, item):
                raise HTTPException(status_code=403, detail="Sizda bu kitobni boshqarish huquqi yo'q")
            return item
        finally:
            conn.close()
    homework = _safe_call(lambda: get_homework(int(content_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    if int(homework.get("teacher_id") or 0) == user_id:
        return homework
    group_id = int(homework.get("group_id") or 0)
    if group_id > 0 and _teacher_can_manage_group(user, _safe_call(lambda: get_group(group_id), None)):
        return homework
    raise HTTPException(status_code=403, detail="Only homework owner or active temporary teacher can manage this test")


def _require_student_content_test_access(user: dict, content_type: str, content_id: int, *, for_submit: bool = False) -> dict:
    normalized = _normalize_content_route_type(content_type)
    _require_role(user, {"student"})
    user_id = int(user.get("id") or 0)
    if normalized == "video":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT * FROM videos WHERE id=? AND COALESCE(is_published,1)=1 LIMIT 1", (int(content_id),))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Video not found")
            video = dict(row)
            if not _media_subject_allowed_for_user(user, video):
                raise HTTPException(status_code=403, detail="Sizda bu videoni ko'rish huquqi yo'q")
        finally:
            conn.close()
        prog = _safe_call(lambda: get_video_progress(user_id, int(content_id)), None)
        # Relax video completion check: allow test access once they've started watching (watched_seconds > 0 or max_watched_seconds > 0) or completed.
        if not prog or (int(prog.get("watched_seconds") or 0) <= 0 and int(prog.get("max_watched_seconds") or 0) <= 0 and not bool(prog.get("completed"))):
            raise HTTPException(status_code=403, detail="Videoni tomosha qilgandan keyin test ochiladi.")
        return video
    if normalized == "book":
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute("SELECT * FROM books WHERE id=? AND COALESCE(is_published,1)=1 LIMIT 1", (int(content_id),))
            book_row = cur.fetchone()
            if not book_row:
                raise HTTPException(status_code=404, detail="Book not found")
            book = dict(book_row)
            if not _media_subject_allowed_for_user(user, book):
                raise HTTPException(status_code=403, detail="Sizda bu kitobni ko'rish huquqi yo'q")
            cur.execute("SELECT * FROM student_book_purchases WHERE user_id=? AND book_id=? LIMIT 1", (user_id, int(content_id)))
            purchase = _row_to_dict(cur.fetchone())
        finally:
            conn.close()
        price = max(0.0, float(book.get("price") or 0.0))
        if not purchase and price > 0:
            raise HTTPException(status_code=403, detail="Kitobni avval xarid qiling")
        # Kitob sotib olingandan keyin test istalgan vaqtda bir marta ishlaydi.
        # Deadline tekshiruvi olib tashlandi (deadline_days=0 => cheksiz muddat).
        # Bir martalik cheklash submit paytida 409 orqali ta'minlanadi.
        return book
    homework = _safe_call(lambda: get_homework(int(content_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    group_id = int(homework.get("group_id") or 0)
    owns = int(homework.get("student_id") or 0) == user_id
    group_ids = {int(row.get("id") or 0) for row in (_safe_call(lambda: get_user_groups(user_id), []) or [])}
    if not owns and not (group_id > 0 and group_id in group_ids):
        raise HTTPException(status_code=404, detail="Homework not found")
    return homework


async def _manage_get_content_test(content_type: str, content_id: int, authorization: str | None):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin", "teacher", "support"})
    normalized = _normalize_content_route_type(content_type)
    _require_content_test_manage_access(user, normalized, int(content_id))
    test = _safe_call(lambda: get_content_test(normalized, int(content_id), include_inactive=True, include_answers=True), None)
    return {"test": test}


async def _manage_save_content_test(content_type: str, content_id: int, payload: ContentTestSaveRequest, authorization: str | None):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"admin", "teacher", "support"})
    normalized = _normalize_content_route_type(content_type)
    _require_content_test_manage_access(user, normalized, int(content_id))
    saved = _safe_call(
        lambda: save_content_test(
            normalized,
            int(content_id),
            json.dumps(payload.questions or [], ensure_ascii=False),
            int(user.get("id") or 0),
            title=payload.title,
            created_by_role=_role_from_login_type(int(user.get("login_type") or 1), str(user.get("login_id") or "")),
            is_active=bool(payload.is_active if payload.is_active is not None else True),
        ),
        None,
    )
    if not saved:
        raise HTTPException(status_code=500, detail="Could not save test")
    return {"message": "Test saved", "test": saved}


async def _student_get_content_test_endpoint(content_type: str, content_id: int, authorization: str | None):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)
    normalized = _normalize_content_route_type(content_type)
    _require_student_content_test_access(user, normalized, int(content_id))
    test = _safe_call(lambda: get_content_test(normalized, int(content_id), include_inactive=False, include_answers=False), None)
    if not test:
        raise HTTPException(status_code=404, detail="Test hali qo'shilmagan.")
    result = _safe_call(lambda: get_content_test_result(int(user.get("id") or 0), normalized, int(content_id)), None)
    return {
        "test": _sanitize_content_test_for_student(test),
        "result": result,
        # Mobil ilova `can_take_test`/`test_submitted` flaglariga tayanadi;
        # bu yerga yetib kelgan foydalanuvchi access tekshiruvdan o'tgan.
        "can_take_test": result is None,
        "test_submitted": result is not None,
    }


async def _student_submit_content_test_endpoint(content_type: str, content_id: int, payload: ContentTestSubmitRequest, authorization: str | None):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"student"})
    _require_student_learning_access(user)
    user = _require_student_face_setup_complete(user)
    normalized = _normalize_content_route_type(content_type)
    _require_student_content_test_access(user, normalized, int(content_id), for_submit=True)
    user_id = int(user.get("id") or 0)
    _ensure_proctoring_session_access(
        user,
        payload.proctoring_session_id,
        expected_test_type=f"content_{normalized}",
        expected_attempt_ref=f"{normalized}:{int(content_id)}",
    )
    existing = _safe_call(lambda: get_content_test_result(user_id, normalized, int(content_id)), None)
    if existing:
        raise HTTPException(status_code=409, detail="Test already submitted")
    result = _safe_call(
        lambda: submit_content_test_attempt(
            user_id,
            normalized,
            int(content_id),
            payload.answers or {},
            subject=_content_test_subject(normalized, int(content_id), user),
        ),
        None,
    )
    if not result:
        raise HTTPException(status_code=404, detail="Test not found")
    if normalized == "book":
        try:
            conn = get_conn()
            cur = conn.cursor()
            next_status = "test_passed" if bool(result.get("passed")) else "test_failed"
            cur.execute(
                "UPDATE student_book_purchases SET status=? WHERE user_id=? AND book_id=?",
                (next_status, user_id, int(content_id)),
            )
            conn.commit()
            conn.close()
            _clear_user_media_caches(user_id)
        except Exception:
            logger.exception("book content test status update failed user_id=%s book_id=%s", user_id, content_id)
    elif normalized == "homework":
        try:
            homework = _safe_call(lambda: get_homework(int(content_id)), None)
            if homework:
                _attach_homework_runtime_fields(homework)
                if _normalize_homework_kind(homework.get("homework_kind")) == "test":
                    existing_submission = _safe_call(lambda: get_homework_submission(int(content_id), user_id), None)
                    if not existing_submission:
                        submission = upsert_homework_submission(
                            homework_id=int(content_id),
                            student_id=user_id,
                            status="pending_review",
                            note="Test auto-submit",
                            proof_image_url=None,
                            proof_images_json=None,
                        )
                        if submission:
                            _attach_homework_runtime_fields(submission)
                            await _notify_homework_submitted(homework, user, submission)
        except Exception:
            logger.exception("homework test auto-submit failed user_id=%s homework_id=%s", user_id, content_id)
    return {"message": "Test submitted", "result": result}


