@app.get("/teacher/homework/{homework_id}/report")
async def teacher_homework_report(homework_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, TEACHER_STAFF_ROLES)
    teacher_id = int(user.get("id") or 0)
    homework = _safe_call(lambda: get_homework(int(homework_id)), None)
    if not homework:
        raise HTTPException(status_code=404, detail="Homework not found")
    group_id = int(homework.get("group_id") or 0)
    if int(homework.get("teacher_id") or 0) != teacher_id:
        if group_id <= 0 or not _teacher_can_manage_group(user, _safe_call(lambda: get_group(group_id), None)):
            raise HTTPException(status_code=403, detail="Only homework owner or active temporary teacher can view report")
    rows = [row for row in (_safe_call(lambda: list_homeworks_for_teacher(teacher_id), []) or []) if int(row.get("id") or 0) == int(homework_id)]
    if int(homework.get("teacher_id") or 0) != teacher_id and not rows:
        members = _safe_call(lambda: get_group_users(group_id), []) or []
        rows = [
            {
                **homework,
                "student_id": int(m.get("id") or 0),
                "student_first_name": m.get("first_name"),
                "student_last_name": m.get("last_name"),
                "student_profile_image_url": m.get("profile_image_url"),
            }
            for m in members
            if int(m.get("login_type") or 0) in (1, 2, 6)
        ]
    test = _safe_call(lambda: get_content_test("homework", int(homework_id), include_inactive=False, include_answers=False), None)
    items: list[dict[str, Any]] = []
    for row in rows:
        _attach_homework_runtime_fields(row)
        sid = int(row.get("submission_student_id") or row.get("student_id") or 0)
        result = _safe_call(lambda student_id=sid: get_content_test_result(student_id, "homework", int(homework_id)), None) if sid > 0 else None
        items.append(
            {
                **row,
                "student_id": sid,
                "uploaded": bool(row.get("proof_images") or row.get("proof_image_url")),
                "uploaded_at": row.get("submission_created_at") or row.get("submission_updated_at"),
                "test_available": bool(test),
                "test_completed": bool(result),
                "test_result": result,
                "test_correct_count": int((result or {}).get("correct_count") or (result or {}).get("correct") or 0),
                "test_wrong_count": int((result or {}).get("wrong_count") or (result or {}).get("wrong") or 0),
                "test_skipped_count": int((result or {}).get("skipped_count") or (result or {}).get("skipped") or 0),
                "test_total_questions": int((result or {}).get("total_questions") or (result or {}).get("total") or 0),
                "test_dpoints_delta": float((result or {}).get("dpoints_delta") or 0.0),
                "test_submitted_at": (result or {}).get("submitted_at"),
            }
        )
    return {"homework": homework, "test": _sanitize_content_test_for_student(test), "items": items, "total": len(items)}

