    cur.execute("SELECT * FROM web_voicerooms WHERE owner_id=%s ORDER BY created_at DESC", (user_id,))
    rooms = cur.fetchall()
    
    parsed_rooms = []
    for r in rooms:
        r_dict = dict(r)
        tags = []
        if r_dict.get("tags"):
            try: tags = json.loads(r_dict["tags"])
            except: pass
        r_dict["tags"] = tags
        parsed_rooms.append(r_dict)
        
    conn.close()
    return {"rooms": parsed_rooms}

