@app.get("/voice-rooms/active")
async def get_active_voice_rooms(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    
    # 1. Get all rooms from DB
    conn = get_conn()
    cur = conn.cursor()
    cur.execute("SELECT v.*, COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '') as host_name FROM web_voicerooms v LEFT JOIN users u ON u.id = v.owner_id")
    db_rooms = {str(r["id"]): dict(r) for r in cur.fetchall()}
    conn.close()
    
    # 2. Get active rooms from Redis
    rooms = []
    keys = _REDIS_CLIENT.keys("voice_room_info_*")
    for k in keys:
        room_id = k.replace("voice_room_info_", "")
        if room_id not in db_rooms:
            continue
            
        info_raw = _REDIS_CLIENT.hgetall(k)
        if not info_raw: continue
        
        try:
            listeners = _REDIS_CLIENT.scard(f"voice_room_peers_{room_id}") or 0
            db_room = db_rooms[room_id]
            
            tags = []
            if db_room.get("tags"):
                try: tags = json.loads(db_room["tags"])
                except: pass
                
            rooms.append({
                "room_id": room_id,
                "name": db_room["name"],
                "subject": db_room["subject"],
                "tags": tags,
                "host_id": db_room["owner_id"],
                "host_name": db_room["host_name"],
                "listeners": listeners
            })
        except Exception:
            pass
            
    return {"rooms": rooms}

