@app.websocket("/voice-room-ws")
async def websocket_voice_room(websocket: WebSocket, token: str | None = Query(default=None)):
    await websocket.accept()
    my_ws_id = str(uuid.uuid4())
    current_room_id = None
    my_user_id = None
    my_name = "Mehmon"
    my_role = "student"
    my_subject = "english"
    my_avatar_url = ""

    # Auth: Authorization header preferred (native apps set it on the
    # handshake; keeps the JWT out of proxy/access logs). The query-param
    # form is kept only so already-shipped browser mini-app builds keep
    # working.
    if not token:
        auth_header = (websocket.headers.get("authorization") or "").strip()
        if auth_header.lower().startswith("bearer "):
            token = auth_header.split(" ", 1)[1].strip()
    elif str(token or "").strip():
        logger.warning("voice-room-ws: token received via query param (deprecated); use Authorization header")

    # Try to auth
    if token:
        try:
            user = _user_row_from_bearer(f"Bearer {token}")
            if user:
                my_user_id = int(user.get("id") or 0)
                my_name = f"{user.get('first_name') or ''} {user.get('last_name') or ''}".strip() or "O'quvchi"
                my_avatar_url = _first_existing_avatar_url(user.get("profile_image_url"), user.get("effective_profile_image_url")) or ""
                r = int(user.get("login_type") or 0)
                if r in (3, 4, 5):
                    my_role = "admin"
                elif r == 2:
                    my_role = "teacher"
                else:
                    my_role = "student"
        except Exception:
            pass

    async def _send(msg: dict):
        try:
            await websocket.send_json(msg)
        except Exception:
            pass

    async def _broadcast_room(room_id: str, msg: dict, exclude=None):
        peers = _REDIS_CLIENT.smembers(f"voice_room_peers_{room_id}") or set()
        for p in peers:
            if p != exclude:
                _REDIS_CLIENT.rpush(f"webrtc_signal_{p}", json.dumps(msg))
                _REDIS_CLIENT.expire(f"webrtc_signal_{p}", 3600)

    async def _send_room_state(room_id: str):
        info_raw = _REDIS_CLIENT.hgetall(f"voice_room_info_{room_id}")
        if not info_raw:
            return
        stage_peers = list(_REDIS_CLIENT.smembers(f"voice_room_stage_{room_id}") or set())
        admin_peers = list(_REDIS_CLIENT.smembers(f"voice_room_admins_{room_id}") or set())
        total_peers = _REDIS_CLIENT.scard(f"voice_room_peers_{room_id}") or 0
        admin_count = _REDIS_CLIENT.scard(f"voice_room_admins_{room_id}") or 0
        listeners_count = max(0, total_peers - admin_count)
        co_hosts = list(_REDIS_CLIENT.smembers(f"voice_room_cohosts_{room_id}") or set())
        hidden_speakers = list(_REDIS_CLIENT.smembers(f"voice_room_hidden_{room_id}") or set())
        
        peer_info = {}
        for p in set(stage_peers + admin_peers):
            p_data = _REDIS_CLIENT.hgetall(f"voice_room_peer_info_{p}")
            if p_data:
                peer_info[p] = p_data
                
        state = {
            "type": "room_state",
            "room_id": room_id,
            "host_id": info_raw.get("host_id"),
            "host_name": info_raw.get("host_name"),
            "subject": info_raw.get("subject"),
            "stage_peers": stage_peers,
            "admin_peers": admin_peers,
            "co_hosts": co_hosts,
            "hidden_speakers": hidden_speakers,
            "listeners_count": listeners_count,
            "peer_info": peer_info,
            "total_visits": info_raw.get("total_visits", 0),
            "total_gifts_amount": info_raw.get("total_gifts_amount", 0)
        }
        await _broadcast_room(room_id, state)

    try:
        while True:
            try:
                data = await asyncio.wait_for(websocket.receive_text(), timeout=0.2)
                try:
                    msg = json.loads(data)
                except Exception:
                    continue

                action = msg.get("action")
                
                if action == "join_room":
                    room_id = str(msg.get("room_id"))
                    
                    if _REDIS_CLIENT.sismember("voice_room_banned_users", str(my_user_id)) and my_role != "admin":
                        await _send({"type": "error", "message": "Siz ovozli xonalardan chetlashtirilgansiz."})
                        continue
                        
                    # Verify DB
                    conn = get_conn()
                    cur = conn.cursor()
                    cur.execute("SELECT * FROM web_voicerooms WHERE id=%s", (room_id,))
                    db_room = cur.fetchone()
                    
                    is_homework_room = False
                    if not db_room:
                        cur.execute("SELECT * FROM web_homework_voiceroom_groups WHERE room_id=%s", (room_id,))
                        hw_group = cur.fetchone()
                        if hw_group:
                            if my_user_id not in (int(hw_group["student1_id"]), int(hw_group.get("student2_id") or 0), int(hw_group.get("student3_id") or 0)):
                                conn.close()
                                await _send({"type": "error", "message": "Siz ushbu guruhga kiritilmagansiz."})
                                continue
                            is_homework_room = True
                            db_room = {
                                "id": room_id,
                                "owner_id": 0,
                                "subject": "homework",
                                "name": "Homework Voiceroom"
                            }
                    conn.close()
                    
                    if not db_room:
                        await _send({"type": "error", "message": "Xona topilmadi."})
                        continue
                        
                    is_host = (int(db_room["owner_id"]) == my_user_id) if not is_homework_room else False
                    
                    info = _REDIS_CLIENT.hgetall(f"voice_room_info_{room_id}")
                    if not info:
                        if is_homework_room:
                            _REDIS_CLIENT.hset(f"voice_room_info_{room_id}", mapping={
                                "host_id": "",
                                "host_user_id": "",
                                "host_name": "",
                                "subject": db_room["subject"],
                                "created_at": str(time.time()),
                                "session_id": "0",
                                "is_homework": "1"
                            })
                            _REDIS_CLIENT.expire(f"voice_room_info_{room_id}", 14400)
                        elif not is_host:
                            await _send({"type": "error", "message": "Xona hozircha faol emas. Host kirishi kutilmoqda."})
                            continue
                        else:
                            # Start room
                            conn2 = get_conn()
                            cur2 = conn2.cursor()
                            cur2.execute("INSERT INTO web_voiceroom_sessions (room_id, host_id) VALUES (%s, %s) RETURNING id", (room_id, my_user_id))
                            session_id = cur2.fetchone()["id"]
                            conn2.commit()
                            conn2.close()
                            
                            _REDIS_CLIENT.hset(f"voice_room_info_{room_id}", mapping={
                                "host_id": my_ws_id,
                                "host_user_id": str(my_user_id),
                                "host_name": my_name,
                                "subject": db_room["subject"],
                                "created_at": str(time.time()),
                                "session_id": str(session_id)
                            })
                            _REDIS_CLIENT.expire(f"voice_room_info_{room_id}", 14400) # 4 hours

                            # Send Telegram notification
                            try:
                                from db import list_student_telegram_ids_by_subject
                                students_to_notify = list_student_telegram_ids_by_subject(db_room["subject"])
                                if students_to_notify:
                                    bot_token = os.getenv("TELEGRAM_STUDENT_BOT_TOKEN")
                                    if bot_token:
                                        creator_tg = ""
                                        owner_name = "User"
                                        try:
                                            # user variable from upper scope is a dict if auth succeeded
                                            creator_tg = str(user.get("telegram_id") or "").strip()
                                            owner_name = str(user.get("first_name") or "User")
                                        except Exception:
                                            pass
                                        for st in students_to_notify:
                                            st_tg = str(st.get("telegram_id") or "").strip()
                                            if st_tg and st_tg != creator_tg:
                                                st_lang = str(st.get("language") or "uz")
                                                msg = _voice_room_notify_text(st_lang, db_room["subject"], db_room["name"], owner_name)
                                                asyncio.create_task(_send_telegram_text(bot_token, st_tg, msg))
                            except Exception as e:
                                logger.error(f"Failed to send voice room telegram notification: {e}")
                            
                    current_room_id = room_id
                    _REDIS_CLIENT.sadd(f"voice_room_peers_{room_id}", my_ws_id)
                    _REDIS_CLIENT.expire(f"voice_room_peers_{room_id}", 14400)
                    
                    if my_role == "admin":
                        _REDIS_CLIENT.sadd(f"voice_room_admins_{room_id}", my_ws_id)
                        _REDIS_CLIENT.expire(f"voice_room_admins_{room_id}", 14400)
                    
                    # Store peer info for avatar and name
                    _REDIS_CLIENT.hset(f"voice_room_peer_info_{my_ws_id}", mapping={
                        "user_id": str(my_user_id) if my_user_id else "",
                        "name": my_name,
                        "avatar_url": my_avatar_url or ""
                    })
                    _REDIS_CLIENT.expire(f"voice_room_peer_info_{my_ws_id}", 14400)
                    
                    if is_host or is_homework_room:
                        _REDIS_CLIENT.sadd(f"voice_room_stage_{room_id}", my_ws_id)
                        _REDIS_CLIENT.expire(f"voice_room_stage_{room_id}", 14400)
                        
                    if my_role == "admin":
                        _REDIS_CLIENT.sadd(f"voice_room_hidden_{room_id}", my_ws_id)
                        _REDIS_CLIENT.expire(f"voice_room_hidden_{room_id}", 14400)
                    
                    await _send({"type": "room_joined", "room_id": room_id, "my_id": my_ws_id, "is_admin": my_role == "admin"})
                    if my_role != "admin":
                        await _broadcast_room(room_id, {"type": "chat_message", "author": "Tizim", "text": f"{my_name} xonaga qo'shildi."})
                    await _send_room_state(room_id)
                    
                elif action == "request_stage":
                    if current_room_id:
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        host_id = info.get("host_id")
                        if host_id:
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{host_id}", json.dumps({
                                "type": "webrtc_signal",
                                "from_id": my_ws_id,
                                "data": {
                                    "type": "stage_request",
                                    "peer_name": my_name
                                }
                            }))
                            await _send({"type": "chat_message", "author": "Tizim", "text": "Sahnaga chiqish so'rovi yuborildi."})
                
                elif action == "force_join_stage":
                    if current_room_id and my_role == "admin":
                        _REDIS_CLIENT.sadd(f"voice_room_stage_{current_room_id}", my_ws_id)
                        await _broadcast_room(current_room_id, {"type": "stage_approved", "peer_id": my_ws_id})
                        await _send({"type": "stage_approved", "peer_id": my_ws_id})
                        await _send_room_state(current_room_id)
                elif action == "approve_stage":
                    peer_id = msg.get("peer_id")
                    if current_room_id:
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id:
                            stage_count = _REDIS_CLIENT.scard(f"voice_room_stage_{current_room_id}") or 0
                            if stage_count < 4:
                                _REDIS_CLIENT.sadd(f"voice_room_stage_{current_room_id}", peer_id)
                                await _broadcast_room(current_room_id, {"type": "stage_approved", "peer_id": peer_id})
                                await _send_room_state(current_room_id)
                            else:
                                await _send({"type": "error", "message": "Sahna to'ldi (Maks 4 kishi)."})

                elif action == "leave_stage":
                    if current_room_id:
                        _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", my_ws_id)
                        await _broadcast_room(current_room_id, {"type": "stage_left", "peer_id": my_ws_id})
                        await _send_room_state(current_room_id)

                elif action == "toggle_hidden_speaker":
                    if current_room_id and my_role == "admin":
                        if _REDIS_CLIENT.sismember(f"voice_room_hidden_{current_room_id}", my_ws_id):
                            _REDIS_CLIENT.srem(f"voice_room_hidden_{current_room_id}", my_ws_id)
                        else:
                            _REDIS_CLIENT.sadd(f"voice_room_hidden_{current_room_id}", my_ws_id)
                        await _send_room_state(current_room_id)

                elif action == "chat_message":
                    if current_room_id:
                        text = msg.get("text", "").strip()
                        replyToId = msg.get("replyToId")
                        replyToAuthor = msg.get("replyToAuthor")
                        replyToText = msg.get("replyToText")
                        if text:
                            # Check if game is active and text matches
                            game_raw = _REDIS_CLIENT.hgetall(f"voice_room_game_{current_room_id}")
                            if game_raw and game_raw.get("active") == "1":
                                original = game_raw.get("original_word", "")
                                if text.strip().lower() == original.lower():
                                    _REDIS_CLIENT.hset(f"voice_room_game_{current_room_id}", "active", "0")
                                    await _broadcast_room(current_room_id, {
                                        "type": "chat_message",
                                        "author": "Tizim",
                                        "text": f"🎉 {my_name} so'zni to'g'ri topdi: {original}!"
                                    })
                                    await _broadcast_room(current_room_id, {
                                        "type": "game_ended"
                                    })
                                    # Don't send the user's message, or send it then send the system message
                                    # We will send the user's message first
                            
                            await _broadcast_room(current_room_id, {
                                "type": "chat_message",
                                "author": my_name,
                                "text": text,
                                "is_admin": my_role == "admin",
                                "replyToId": replyToId,
                                "replyToAuthor": replyToAuthor,
                                "replyToText": replyToText
                            })
                            
                elif action == "start_game":
                    if current_room_id:
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id:
                            # For simplicity, we just hardcode some words or random pick
                            words = ["ENGLISH", "APPLE", "SCHOOL", "STUDENT", "TEACHER", "LANGUAGE", "DICTIONARY"]
                            import random
                            word = random.choice(words)
                            scrambled = list(word)
                            random.shuffle(scrambled)
                            scrambled = "".join(scrambled)
                            
                            _REDIS_CLIENT.hset(f"voice_room_game_{current_room_id}", mapping={
                                "active": "1",
                                "original_word": word,
                                "word": scrambled,
                                "time_left": 60
                            })
                            
                            await _broadcast_room(current_room_id, {
                                "type": "game_state",
                                "game": {
                                    "active": True,
                                    "word": scrambled,
                                    "time_left": 60
                                }
                            })
                            await _broadcast_room(current_room_id, {
                                "type": "chat_message",
                                "author": "Tizim",
                                "text": f"🎮 O'yin boshlandi! Harflardan so'z tuzing: {scrambled}"
                            })

                elif action == "webrtc_signal":
                    target_id = msg.get("target_id")
                    if target_id:
                        payload = json.dumps({"type": "webrtc_signal", "from_id": my_ws_id, "data": msg.get("data")})
                        _REDIS_CLIENT.rpush(f"webrtc_signal_{target_id}", payload)
                        _REDIS_CLIENT.expire(f"webrtc_signal_{target_id}", 3600)

                elif action == "reaction":
                    if current_room_id:
                        emoji = msg.get("emoji")
                        if emoji:
                            await _broadcast_room(current_room_id, {
                                "type": "reaction",
                                "peer_id": my_ws_id,
                                "emoji": emoji
                            })
                            
                elif action == "force_mute":
                    target_id = msg.get("target_id")
                    if current_room_id and target_id:
                        if _REDIS_CLIENT.sismember(f"voice_room_admins_{current_room_id}", target_id):
                            await _send({"type": "error", "message": "Adminlarni Mute qilish mumkin emas!"})
                            continue
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id or my_role == "admin":
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{target_id}", json.dumps({"type": "force_mute"}))

                elif action == "demote_peer":
                    peer_id = msg.get("peer_id")
                    if current_room_id and peer_id:
                        if _REDIS_CLIENT.sismember(f"voice_room_admins_{current_room_id}", peer_id):
                            await _send({"type": "error", "message": "Adminlarni sahnadan olish mumkin emas!"})
                            continue
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id or my_role == "admin":
                            _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", peer_id)
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{peer_id}", json.dumps({"type": "demoted"}))
                            await _broadcast_room(current_room_id, {"type": "stage_left", "peer_id": peer_id})
                            await _send_room_state(current_room_id)

                elif action == "kick_peer":
                    peer_id = msg.get("peer_id")
                    if current_room_id and peer_id:
                        if _REDIS_CLIENT.sismember(f"voice_room_admins_{current_room_id}", peer_id):
                            await _send({"type": "error", "message": "Adminlarni xonadan chiqarish mumkin emas!"})
                            continue
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id or my_role == "admin":
                            _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", peer_id)
                            _REDIS_CLIENT.srem(f"voice_room_peers_{current_room_id}", peer_id)
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{peer_id}", json.dumps({"type": "kicked"}))
                            await _broadcast_room(current_room_id, {"type": "peer_left", "peer_id": peer_id})
                            await _send_room_state(current_room_id)
                elif action == "force_close_room":
                    if my_role == "admin" and current_room_id:
                        await _broadcast_room(current_room_id, {"type": "room_closed"})
                        _REDIS_CLIENT.delete(f"voice_room_info_{current_room_id}")
                        _REDIS_CLIENT.delete(f"voice_room_stage_{current_room_id}")
                        _REDIS_CLIENT.delete(f"voice_room_peers_{current_room_id}")
                        _REDIS_CLIENT.delete(f"voice_room_admins_{current_room_id}")
                        _REDIS_CLIENT.delete(f"voice_room_cohosts_{current_room_id}")
                        _REDIS_CLIENT.delete(f"voice_room_hidden_{current_room_id}")
                        
                elif action == "transfer_host":
                    target_id = msg.get("target_id")
                    if current_room_id and target_id and my_role == "admin":
                        target_info = _REDIS_CLIENT.hgetall(f"voice_room_peer_info_{target_id}")
                        if target_info:
                            _REDIS_CLIENT.hset(f"voice_room_info_{current_room_id}", mapping={
                                "host_id": target_id,
                                "host_user_id": target_info.get("user_id"),
                                "host_name": target_info.get("name")
                            })
                            await _send_room_state(current_room_id)

                elif action == "global_ban":
                    target_user_id = msg.get("target_user_id")
                    if my_role == "admin" and target_user_id:
                        _REDIS_CLIENT.sadd("voice_room_banned_users", str(target_user_id))
                        target_peer_id = msg.get("target_id")
                        if target_peer_id and current_room_id:
                            _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", target_peer_id)
                            _REDIS_CLIENT.srem(f"voice_room_peers_{current_room_id}", target_peer_id)
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{target_peer_id}", json.dumps({"type": "kicked", "reason": "global_ban"}))
                            await _broadcast_room(current_room_id, {"type": "peer_left", "peer_id": target_peer_id})
                            await _send_room_state(current_room_id)

                elif action == "global_unban":
                    target_user_id = msg.get("target_user_id")
                    if my_role == "admin" and target_user_id:
                        _REDIS_CLIENT.srem("voice_room_banned_users", str(target_user_id))

                elif action == "global_broadcast":
                    text = msg.get("text", "").strip()
                    if my_role == "admin" and text:
                        keys = _REDIS_CLIENT.keys("voice_room_peers_*")
                        all_peers = set()
                        for k in keys:
                            for p in _REDIS_CLIENT.smembers(k):
                                all_peers.add(p)
                        for p in all_peers:
                            _REDIS_CLIENT.rpush(f"webrtc_signal_{p}", json.dumps({
                                "type": "global_alert",
                                "text": text
                            }))
                            _REDIS_CLIENT.expire(f"webrtc_signal_{p}", 3600)

                elif action == "play_system_sound":
                    sound_name = msg.get("sound_name")
                    if my_role == "admin" and sound_name and current_room_id:
                        await _broadcast_room(current_room_id, {
                            "type": "system_sound",
                            "sound_name": sound_name
                        })

                elif action == "make_cohost":
                    target_id = msg.get("target_id")
                    if current_room_id and target_id:
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id:
                            _REDIS_CLIENT.sadd(f"voice_room_cohosts_{current_room_id}", target_id)
                            await _send_room_state(current_room_id)
                            
                elif action == "gift_broadcast":
                    if current_room_id:
                        target_id = msg.get("target_id")
                        gift_name = msg.get("giftName")
                        amount = float(msg.get("amount", 0))
                        
                        target_info = _REDIS_CLIENT.hgetall(f"voice_room_peer_info_{target_id}")
                        target_user_id = int(target_info.get("user_id") or 0)
                        
                        if my_user_id and my_user_id > 0 and target_user_id > 0 and amount > 0:
                            from db import transfer_dcoins_atomic
                            # Transfer dcoin
                            res = _safe_call(lambda: transfer_dcoins_atomic(sender_id=my_user_id, recipient_id=target_user_id, amount=amount, subject="Ovozli xonada sovg'a"), {})
                            if not res or not res.get("ok"):
                                await _send({"type": "error", "message": "Hisobingizda mablag' yetarli emas yoki xatolik."})
                                continue
                                
                            # Increment leaderboard in Redis
                            _REDIS_CLIENT.zincrby(f"voice_room_gifters_{current_room_id}", amount, my_name)
                            
                            # Broadcast gift to all peers
                            await _broadcast_room(current_room_id, {
                                "type": "webrtc_signal", 
                                "from_id": "system",
                                "data": {
                                    "type": "gift",
                                    "target_id": target_id,
                                    "giftName": gift_name,
                                    "amount": amount,
                                    "senderName": my_name
                                }
                            })
                        
                elif action == "get_top_gifters":
                    if current_room_id:
                        top = _REDIS_CLIENT.zrevrange(f"voice_room_gifters_{current_room_id}", 0, 9, withscores=True)
                        gifters = [{"name": name, "amount": int(score)} for name, score in top]
                        await _send({
                            "type": "top_gifters_list",
                            "gifters": gifters
                        })

                elif action == "end_room":
                    if current_room_id:
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id or my_role == "admin":
                            await _broadcast_room(current_room_id, {"type": "room_closed"})
                            session_id = info.get("session_id")
                            if session_id:
                                conn3 = get_conn()
                                cur3 = conn3.cursor()
                                cur3.execute("UPDATE web_voiceroom_sessions SET end_time = CURRENT_TIMESTAMP WHERE id = %s", (session_id,))
                                conn3.commit()
                                conn3.close()
                                
                            _REDIS_CLIENT.delete(f"voice_room_info_{current_room_id}")
                            _REDIS_CLIENT.delete(f"voice_room_stage_{current_room_id}")
                            _REDIS_CLIENT.delete(f"voice_room_peers_{current_room_id}")
                            _REDIS_CLIENT.srem("active_voice_rooms", current_room_id)
                            
                        current_room_id = None
                        await _send({"type": "left_room"})

                elif action == "leave_room":
                    if current_room_id:
                        _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", my_ws_id)
                        _REDIS_CLIENT.srem(f"voice_room_peers_{current_room_id}", my_ws_id)
                        _REDIS_CLIENT.srem(f"voice_room_admins_{current_room_id}", my_ws_id)
                        await _broadcast_room(current_room_id, {"type": "peer_left", "peer_id": my_ws_id})
                        
                        info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
                        if info.get("host_id") == my_ws_id:
                            # Host left, close room
                            await _broadcast_room(current_room_id, {"type": "room_closed"})
                            
                            # End session in DB
                            session_id = info.get("session_id")
                            if session_id:
                                conn3 = get_conn()
                                cur3 = conn3.cursor()
                                cur3.execute("UPDATE web_voiceroom_sessions SET end_time = CURRENT_TIMESTAMP WHERE id = %s", (session_id,))
                                conn3.commit()
                                conn3.close()
                                
                            _REDIS_CLIENT.delete(f"voice_room_info_{current_room_id}")
                            _REDIS_CLIENT.delete(f"voice_room_stage_{current_room_id}")
                            _REDIS_CLIENT.delete(f"voice_room_peers_{current_room_id}")
                            _REDIS_CLIENT.srem("active_voice_rooms", current_room_id)
                        else:
                            await _send_room_state(current_room_id)
                            
                    current_room_id = None
                    await _send({"type": "left_room"})
                        
            except asyncio.TimeoutError:
                while True:
                    msg_str = _REDIS_CLIENT.lpop(f"webrtc_signal_{my_ws_id}")
                    if not msg_str:
                        break
                    signal_msg = json.loads(msg_str)
                    await _send(signal_msg)
                    
    except WebSocketDisconnect:
        pass
    except Exception as e:
        logger.error(f"WS error: {e}")
    finally:
        if current_room_id:
            _REDIS_CLIENT.srem(f"voice_room_stage_{current_room_id}", my_ws_id)
            _REDIS_CLIENT.srem(f"voice_room_peers_{current_room_id}", my_ws_id)
            _REDIS_CLIENT.srem(f"voice_room_admins_{current_room_id}", my_ws_id)
            
            # Send sync message before dying
            peers = _REDIS_CLIENT.smembers(f"voice_room_peers_{current_room_id}") or set()
            for p in peers:
                _REDIS_CLIENT.rpush(f"webrtc_signal_{p}", json.dumps({"type": "peer_left", "peer_id": my_ws_id}))
                
            info = _REDIS_CLIENT.hgetall(f"voice_room_info_{current_room_id}")
            if info and info.get("host_id") == my_ws_id:
                for p in peers:
                    _REDIS_CLIENT.rpush(f"webrtc_signal_{p}", json.dumps({"type": "room_closed"}))
                    
                # End session in DB
                session_id = info.get("session_id")
                if session_id:
                    conn3 = get_conn()
                    cur3 = conn3.cursor()
                    cur3.execute("UPDATE web_voiceroom_sessions SET end_time = CURRENT_TIMESTAMP WHERE id = %s", (session_id,))
                    conn3.commit()
                    conn3.close()
                    
                _REDIS_CLIENT.delete(f"voice_room_info_{current_room_id}")
                _REDIS_CLIENT.delete(f"voice_room_stage_{current_room_id}")
                _REDIS_CLIENT.delete(f"voice_room_peers_{current_room_id}")
                _REDIS_CLIENT.srem("active_voice_rooms", current_room_id)
            else:
                # Update room state for others
                asyncio.create_task(_send_room_state(current_room_id))

class VoiceRoomNameUpdate(BaseModel):
    name: str

@app.put("/voice-rooms/{room_id}/name")
async def update_voice_room_name(room_id: str, payload: VoiceRoomNameUpdate, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    user_id = int(user.get("id") or 0)
    
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute("SELECT owner_id FROM web_voicerooms WHERE id=%s", (room_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Room not found")
            
        if int(row["owner_id"]) != user_id:
            user_role = _role_from_login_type(int(user.get("login_type") or 0), str(user.get("login_id") or ""))
            if user_role != "admin":
                raise HTTPException(status_code=403, detail="Siz ushbu xonaning egasi emassiz")
            
        cur.execute("UPDATE web_voicerooms SET name=%s WHERE id=%s", (payload.name, room_id))
        conn.commit()
        
        # Broadcast via Redis (so all active participants see the new name immediately)
        try:
            from ws_logic import publish_to_voice_room
            asyncio.create_task(publish_to_voice_room(room_id, {
                "type": "room_name_changed",
                "name": payload.name
            }))
        except Exception:
            pass
            
        return {"success": True}
    finally:
        conn.close()


