@app.get("/teacher/my-students")
async def teacher_my_students(authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher"})
    groups = _teacher_manageable_groups(int(user["id"]))
    students = {}
    for g in groups:
        members = _safe_call(lambda gid=g["id"]: get_group_users(int(gid)), []) or []
        for m in members:
            uid = int(m.get("id") or 0)
            if uid > 0 and int(m.get("login_type") or 0) in (1, 2, 6) and uid not in students:
                students[uid] = m
    res = []
    for uid, m in students.items():
        res.append({
            "id": uid,
            "first_name": m.get("first_name"),
            "last_name": m.get("last_name"),
            "phone": m.get("phone"),
            "parent_phone": m.get("parent_phone"),
            "login_id": m.get("login_id"),
            "subject": m.get("subject"),
            "level": m.get("level"),
            "login_type": m.get("login_type"),
            # `get_group_users()` already selects `u.*`, so the avatar is
            # available on `m` — it just wasn't being forwarded here,
            # leaving every "Mening o'quvchilarim" client with no way to
            # show a student's profile picture.
            "profile_image_url": m.get("profile_image_url"),
            "avatar_url": _first_existing_avatar_url(m.get("profile_image_url"), m.get("effective_profile_image_url")),
        })
    return sorted(res, key=lambda x: (x["first_name"] or "", x["last_name"] or ""))

@app.put("/teacher/my-students/{student_id}")
async def teacher_update_student(student_id: int, payload: TeacherUpdateStudentRequest, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher"})
    groups = _teacher_manageable_groups(int(user["id"]))
    is_my_student = False
    for g in groups:
        members = _safe_call(lambda gid=g["id"]: get_group_users(int(gid)), []) or []
        if any(int(m.get("id") or 0) == student_id for m in members):
            is_my_student = True
            break
    if not is_my_student:
        raise HTTPException(status_code=403, detail="Student not found in your groups")
    student = get_user_by_id(student_id)
    if not student:
        raise HTTPException(status_code=404, detail="Student not found")
        
    fn = payload.first_name if payload.first_name is not None else student.get("first_name")
    ln = payload.last_name if payload.last_name is not None else student.get("last_name")
    ph = payload.phone if payload.phone is not None else student.get("phone")
    pp = payload.parent_phone if payload.parent_phone is not None else student.get("parent_phone")
    sub = payload.subject if payload.subject is not None else student.get("subject")
    lvl = payload.level if payload.level is not None else student.get("level")
    
    conn = get_conn()
    cur = conn.cursor()
    try:
        cur.execute(
            "UPDATE users SET first_name=?, last_name=?, phone=?, parent_phone=?, subject=?, level=? WHERE id=?",
            (fn, ln, ph, pp, sub, lvl, student_id)
        )
        conn.commit()
    finally:
        conn.close()
    return {"message": "Student updated"}

@app.post("/teacher/my-students/{student_id}/reset-password")
async def teacher_reset_student_password(student_id: int, authorization: str | None = Header(default=None)):
    user = _user_row_from_bearer(authorization)
    _require_role(user, {"teacher"})
    groups = _teacher_manageable_groups(int(user["id"]))
    is_my_student = False
    for g in groups:
        members = _safe_call(lambda gid=g["id"]: get_group_users(int(gid)), []) or []
        if any(int(m.get("id") or 0) == student_id for m in members):
            is_my_student = True
            break
    if not is_my_student:
        raise HTTPException(status_code=403, detail="Student not found in your groups")

    target = get_user_by_id(student_id)
    if not target:
        raise HTTPException(status_code=404, detail="Student not found")

    password = generate_password(6)
    reset_user_password(int(student_id), password)
    
    conn = get_conn()
    cur = conn.cursor()
    cur.execute(
        """
        UPDATE users
        SET session_version=COALESCE(session_version, 1) + 1
        WHERE id=?
        """,
        (int(student_id),),
    )
    conn.commit()
    conn.close()

    _revoke_web_sessions(int(student_id), keep_session_id=None, reason="teacher_reset_password")
    refreshed = _safe_call(lambda: get_user_by_id(int(student_id)), None) or target
    qr_generated = _safe_call(lambda: _generate_qr_login_token(int(student_id), WEB_QR_LOGIN_TTL_SECONDS), {}) or {}

    return {
        "message": "Password reset successfully",
        "user_id": int(student_id),
        "password": password,
        "session_version": int(refreshed.get("session_version") or 1),
        "qr_token": str(qr_generated.get("qr_token") or "") or None,
        "qr_payload": str(qr_generated.get("qr_payload") or "") or None,
        "qr_expires_at": str(qr_generated.get("expires_at") or "") or None,
    }


